window.KURAN_MEALS=window.KURAN_MEALS||{};window.KURAN_MEALS["ioglu"]=[[{"n":1,"t":"Rahman rahim Allah`ın adıyla"},{"n":2,"t":"Hamd, bütün alemlerin Rabbi Allah`a mahsustur."},{"n":3,"t":"O özünde rahmet sahibi, işinde rahmet sahibidir."},{"n":4,"t":"O, Hesap Günü`nün hakimidir."},{"n":5,"t":"(Rabbimiz!) Yalnız sana kulluk eder ve yalnız senden yardım isteriz."},{"n":6,"t":"Bizi yönelt Dosdoğru Yol`a;"},{"n":7,"t":"Nimet verdiklerinin yoluna; gazaba uğrayanların ve sapıtanların yoluna değil!"}],[{"n":1,"t":"Elif-Lam-Mim!"},{"n":2,"t":"İşte kendisi hakkında hiçbir kuşkuya yer olmayan bu ilahi kelam, takva sahipleri için bir hidayet rehberidir;"},{"n":3,"t":"O hidayete erenler ki, idraki aşan hakikatlere bütünüyle iman ederler, namazı istikamet üzre kılarlar, kendilerine sürekli lutfettiğimiz şeylerden (ihtiyaç sahiplerine) harcarlar;"},{"n":4,"t":"Ve onlar sana indirilene de; ahiretin varlığına dair ilahi habere mutmain bir kalple inanmıştırlar."},{"n":5,"t":"İşte onlar, Rablerinden gelen kusursuz bir rehberliğe tabidirler; ve işte onlar, evet onlardır sonsuz mutluluğa erenler."},{"n":6,"t":"Şu bir gerçek ki, küfre şartlanmış o kimseleri ha uyarmışsın ha uyarmamışsın, onlar için (ikisi de) bir: iman etmezler."},{"n":7,"t":"Allah onların kalpleri ve kulakları üzerine mühür vurmuştur, gözleri üzerinde de bir tür perde vardır; işte onlardır korkunç bir azabı hak edenler."},{"n":8,"t":"İnsanlardan öyleleri de var ki, \"Allah`a ve ahiret gününe inandık\" der(ler); ama onlar mü`min değiller."},{"n":9,"t":"Allah`ı ve iman etmiş kimseleri aldatmak isterler; halbuki onlar yalnızca kendilerini aldatırlar; ama bunu (Allah`ın ifşa edeceğinin) farkında bile değiller."},{"n":10,"t":"Kalplerinde hastalık vardır; Allah da onların hastalığını arttırmıştır; ve ısrarlı yalanları yüzünden can yakıcı azabı hak ederler."},{"n":11,"t":"Kendilerine \"Yeryüzünde fesat çıkarmayın!\" denildiğinde, \"Biz sadece ıslahatçılarız\" derler."},{"n":12,"t":"Aman dikkat, kesinlikle onlar fesatçıların ta kendileridirler, ama bunun farkında dahi değiller."},{"n":13,"t":"Kendilerine \"Siz de insanların inandıkları gibi inanın!\" denildiğinde, \"Ya biz, ahmakların inandıkları gibi mi inanıyoruz?\" dediler. Bakın! Onlar var ya onlar, gerçekten de ahmaktırlar; lakin bunun bile farkında değiller."},{"n":14,"t":"Ama inanan kimselerle karşılaştıklarında \"Biz iman ettik\" derler. Şeytanlarıyla baş başa kaldıklarında ise, \"Biz sizinle beraberiz, biz (onlarla) sadece alay ediyorduk\" derler."},{"n":15,"t":"Allah da onların alaylarına karşılık verir ve onları kendi tuğyanlarına gömülmüş olarak bırakır, şaşkın şaşkın debelenirler."},{"n":16,"t":"Onlar hidayet karşılığında sapıklığı satın aldılar, bu yüzden ticaretleri onlara kâr sağlamadı; zira onlar doğru yolda giden kimseler değiller."},{"n":17,"t":"Onların durumu şu kişinin durumuna benzer: O kişi bir meş`ale tutuşturdu; Alevler etrafını aydınlatır aydınlatmaz Allah (gözlerinin) nurunu alıverdi ve kendilerini karanlıklar içinde bıraktı; artık göremezler:"},{"n":18,"t":"Sağırdırlar, dilsizdirler, kördürler: artık onlar (hakikate) dönemezler."},{"n":19,"t":"Ya da (durumları şu örneğe) benzer: Gökten inen bir sağanak (düşünün), onunla birlikte karanlıklar, gök gürlemesi, şimşek... Yıldırımlardan dolayı, ölüm korkusuyla parmaklarını kulaklarına tıkıyorlar. Zira Allah kafirleri çepeçevre kuşatandır."},{"n":20,"t":"Şimşek neredeyse gözlerini kör eder; onları ne zaman aydınlatsa, o aydınlıkta yol alırlar; ne zaman da karanlık üzerlerine çökse, ayakta kalakalırlar. Ve eğer Allah dileseydi, işitme ve görme duyularını giderirdi; çünkü Allah`ın her şeye gücü yeter."},{"n":21,"t":"Ey insanlar, sizi ve sizden öncekileri yaratan Rabbinize kulluk edin ki takvâya erişesiniz."},{"n":22,"t":"O`dur size yeryüzünü döşek kılan, gökyüzünü bina eden, gökten suyu indirerek ikram eden ve onunla sizin için türlü meyveler çıkaran. O halde (bütün bunları yapanın tek O olduğunu) bile bile Allah`a eşdeğer rakip güçler tasarlamayınız!"},{"n":23,"t":"Eğer siz kulumuza indirdiklerimize dair bir kuşku taşıyorsanız, haydi, hemen onun benzeri bir sure getiriniz; ve eğer sözünüze sadıksanız, Allah dışındaki tanıklarınızı da yardıma çağırınız!"},{"n":24,"t":"Ama eğer şimdiye kadar (bunu) yapamadınızsa, bundan böyle de asla yapamayacaksınız demektir; o halde yakıtı insanlar ve taşlar olan, inkar edenler için hazırlanmış ateşten sakınınız!"},{"n":25,"t":"İman eden ve bu imanla uyumlu iyilikler işleyen kimseleri zemininden ırmaklar çağlayan cennetlerle müjdele! Her zaman oranın nimetlerinden ikram olarak onlara sunulsa \"Bunlar bize daha önce bahşedilenlerin aynısıymış\" diyecekler. Oysa ki bu, o nimetlerin çağrıştırdığı belli belirsiz bir benzerlik. Ve onlar için cennette tertemiz eşler olacak ve onlar orada kalıcıdırlar."},{"n":26,"t":"Allah bir sivrisineği ya da ondan da küçüğünü misal vermekten haya etmez. İman edenlere gelince: onlar iyi bilirler ki, o, Rableri katından gelen hakikattir. Küfre saplananlara gelince: \"Allah bu örnek ile ne demek istedi?\" derler. Bununla Allah bir çoğunu saptırırken bir çoğunu da doğru yola yöneltir. Ve fakat yoldan çıkmışlardan başkasını kesinlikle saptırmaz."},{"n":27,"t":"Onlar ki (fıtrat) sözleşmesinden sonra Allah`ın (aldığı) sözü bozarlar, Allah`ın kurulmasını emrettiği bağları kesip koparırlar ve yeryüzünde ahlaki çürümeye neden olurlar işte bunlardır hüsrana uğrayanlar!"},{"n":28,"t":"Cansızken size hayat bahşeden, ardından sizi öldürecek ve ondan sonra da diriltecek olan, en sonunda sizi kendisine döndürecek olan Allah`a karşı nasıl olur da nankörlük yaparsınız?"},{"n":29,"t":"Yeryüzündekilerin tümünü sizin için yaratan, sonra göğe yönelerek onu yedi gök olarak düzenleyen O`dur: Nihayet her şeyin bilgisine sahip olan da O`dur."},{"n":30,"t":"Hani, senin Rabbin melaikeye \"Ben yeryüzünde bir halife tayin edeceğim\" dediği zaman da şöyle sormuşlardı: Yeryüzüne fesat çıkaran ve kan dökmekte olan birini mi atayacaksın; üstelik biz seni hamd ile tesbih ve takdis edip dururken?\" (Allah) cevap verdi: \"Şu kesin ki, ben sizin bilmediğiniz şeyleri de bilirim.\""},{"n":31,"t":"Ve Adem`e tüm isimleri öğretti, bunun ardından onları meleklere takdim etti ve dedi ki: \"Hadi, eğer sözünüzün arkasında duruyorsanız şunların isimlerini bana bir bir haber verin!\""},{"n":32,"t":"(Melekler) cevapladılar: \"Sen tek otoritesin, bizim Senin bize öğrettiğinden başka bir ilmimiz olamaz; yalnızca Sensin her şeyi tam bilen, her hükmünde tam isabet kaydeden.\""},{"n":33,"t":"(Allah) buyurdu: \"Ey Adem! Şunların isimlerini onlara bildir.\" Onların isimlerini (meleklere) bildirince de; \"Size dememiş miydim \"Ben bilirim göklerin ve yerin sırrını, gizlediklerinizin ve açıkladıklarınızın tümünü de ben bilirim\" diye?\""},{"n":34,"t":"İşte o zaman meleklere demiştik ki: \"Adem (oğlu) için emre amade olun! İblis hariç, hepsi emre amade olmuştular. O (ise) emre karşı geldi, büyüklük tasladı ve nankörlerden oldu."},{"n":35,"t":"Ve dedik ki: \"Adem! Sen ve eşin şu bahçeye yerleşin, orada canınızın çektiği her şeyden serbestçe yiyin, şu ağaca da yaklaşayım demeyin, sonra zalimlerden olursunuz.\""},{"n":36,"t":"Fakat Şeytan onların ayaklarını kaydırdı, böylece sahip oldukları müstesna konumdan uzaklaştırdı. Ve Biz dedik ki: \"Birbirinize düşman olarak çıkıp gidin! Zira yeryüzünde, geçici bir hayat alanı ve tadımlık bir haz sizi bekliyor!\""},{"n":37,"t":"Fakat Adem Rabbinden aldığı birtakım kelimelere sarıldı, (Allah) da onun tevbesini kabul etti: çünkü O, evet O`ydu tevbeleri kabul etme makamında olan, her işinde merhamet sahibi olan."},{"n":38,"t":"Emrettik: Oradan hep birlikte çıkıp inin! Ne var ki, Benden bir rehberliğin size ulaşması şarttır. Her kim (kendisine ulaşan) rehberliğime uyarsa, artık onlar geleceğe dair kaygı geçmişe dair hüzün duymayacaklar."},{"n":39,"t":"O inkâr edip âyetlerimizi yalanlayanlara gelince, işte onlar ateş ehlidirler! Onlar orada ebedî olarak kalıcıdırlar."},{"n":40,"t":"Ey İsrailoğulları! Bir dönem size verdiğim nimetleri hatırlayın! Siz Bana verdiğiniz sözde durun ki Ben de size olan vaadimi tamamlayayım; ve kaygınızın merkezinde sadece Ben olayım!"},{"n":41,"t":"Ve yanınızda olanı doğrulayıcı olarak indirdiğim vahye inanın; ve onu inkar edenlerin öncüsü siz olmayın, ayetlerimi de basit çıkarlar karşılığında pazarlamayın; ve sorumluluğunuzun merkezinde sadece Ben olayım!"},{"n":42,"t":"Hakkı batılla karıştırmayın ve bildiğiniz halde hakkı gizlemeyin!"},{"n":43,"t":"Namazı istikametle kılın, zekatı gönlünüzden kopararak verin, Allah`a rüku edenlerle birlikte siz de rüku edin!"},{"n":44,"t":"Diğer insanlara sahici erdemlerle donanmayı öğütlerken sıra size gelince terk mi ediyorsunuz; ve üstelik Kıtabı da tilavet edip dururken? Siz hiç kafanızı çalıştırmayacak mısınız?"},{"n":45,"t":"Sabır ve salat ile yardım isteyin! Ancak bu huşu duyanlardan başkasına ağır gelir."},{"n":46,"t":"(Huşu duyanlar), Rablerine kavuşacaklarına ve sonunda O`na döneceklerine kesin gözüyle bakarlar."},{"n":47,"t":"Ey İsrailoğulları! Size lutfettiğim nimetlerimi hatırlayın; hani Ben sizi çağınızın milletlerine üstün kılmıştım."},{"n":48,"t":"Hiç kimsenin hiç kimse adına hiçbir şey ödemeyeceği, kimseden şefaatin kabul edilmeyeceği, kurtuluş akçesi alınmayacağı ve hiç kimsenin yardım görmeyeceği günün (dehşetinden) korunun!"},{"n":49,"t":"Yine bir zaman da sizi Firavun hanedanının elinden kurtarmıştık. Size işkencenin en alçağını reva görüyorlar, erkek çocuklarınızı öldürüp kadınlarınızı da bırakıyorlardı. Bu yaşananlarda, Rabbinizin sizi tabi tuttuğu dehşet bir imtihan vardı."},{"n":50,"t":"Bir zaman da suyu sizin için açmış ve sizi kurtarmış, gözlerinizin önünde Firavun`un kadrosunu boğmuştuk."},{"n":51,"t":"Bir zaman Musa`ya kırk gece süren bir randevu vermiştik. (Bunu fırsat bilen siz), onun ardından bir inek yavrusu heykelini peydahlayıverdiniz ve böylece zalimlerden oldunuz."},{"n":52,"t":"Ve sizi bunun ardından bir kez daha affettik, belki şükredersiniz diye..."},{"n":53,"t":"Yine doğru yolu bulmakta kılavuz edinmeniz için Musa`ya hakkı batıldan ayıran Kitabı vermiştik."},{"n":54,"t":"Hani Musa kavmine demişti ki: Ey kavmim! İyi bilin ki siz buzağıyı peydahlamakla kendi kendinize kötülük ettiniz. Sizi yoktan eşsiz-örneksiz vareden Yaratıcınıza yönelerek af dileyin ve böylece içinizdeki kötülükleri öldürün! Böyle yapmanız, eşsiz yaratıcınız katında sizin için daha hayırlıdır.\" İşte sizin tevbenizi (bir kez daha) böyle kabul etmişti: çünkü yalnız O`dur tevbeleri kabul eden, merhamet eden."},{"n":55,"t":"Bir zaman da demiştiniz ki: Ey Musa! Allah`ı açıkça görünceye dek sana kesinlikle inanmayacağız. Ve ardından siz bön bön bakarken yıldırım çarpmışa dönmüştünüz."},{"n":56,"t":"Daha sonra, belki teşekkür edersiniz diye ölümünüzün ardından sizi bir daha diriltmiştik."},{"n":57,"t":"Üzerinizdeki bulutla sizi gölgeledik, size menn ve selva ikram ettik: Size verdiğimiz rızıkların temiz olanlarından yiyin (diyerek)... Bize kötülük etmediler, fakat kötülük ettikleri yalnızca kendileriydi."},{"n":58,"t":"Bir zaman da demiştik ki: Girin şu şehre, canınızın çektiklerinden bol bol yiyin! Ama (şehre ait) kapıdan tevazu içerisinde iki büklüm girin ve \"Bizi affet!\" diyin! Böylece biz de sizin hatalarınızı affedelim. Sonuçta, Allah`ı görür gibi kulluk edenlere ikramımızı arttıracağız."},{"n":59,"t":"Zulme gömülenler, kendilerine tembih edilen sözü bir başka sözle değiştirdiler. Biz de yoldan saptıkları için zulmedenlerin üzerine yukarıdan bela yağdırdık."},{"n":60,"t":"Musa kavmi için su istediği zaman da dedik ki: \"Değneğini kayaya vur!\" Bunun ardından ondan on iki kaynak fışkırmıştı. Bu sayede herkes içeceği yeri bilmişti. Haydi, Allah`ın rızkından yiyin, için; fakat yeryüzünün fesadıyla sonuçlanacak düzenbazlıklara tevessül etmeyin."},{"n":61,"t":"Yine bir zaman da demiştiniz ki: \"Ey Musa! Biz tek çeşit yiyecekten bıktık: Rabbine yalvar da, bize yeryüzünün değişik ürünlerinden; sebzesinden, acurundan, sarımsağından, mercimeğinden, soğanından versin! (Musa) şöyle cevaplamıştı: Hayırlı olanı, daha değersiz ve aşağı olanla mı değişmek istiyorsunuz? Öyleyse dönün Mısır`a, istediklerinizin tümü orada sizi bekliyor! İşte böylece onlara alçaklık ve yoksulluk mührü vuruldu ve Allah`ın gazabına uğradılar. İşte bu, onların Allah`ın mesajını inkar etmeleri ve Peygamberlerini haksız yere öldürmeleri yüzünden oldu. Bütün bunların asıl nedeni ise, isyankarlıkları ve taşkınlık yapmalarıydı."},{"n":62,"t":"Hiç şüphesiz bu kitaba inanan kimselerden, Yahudileşen kimselerden, Hıristiyanlardan ve Sabiilerden her kim Allah`a ve ahiret gününe inanır, ıslah edici iyilik işlerse, işte onlar için Rableri katında yaptıklarının karşılığı vardır. Onlar gelecekten endişe etmeyecek, geçmişten dolayı da üzüntü duymayacaklar."},{"n":63,"t":"Bir zaman da (Sina) Dağı`nı başınıza dikip sizden (şöyle) söz almıştık: Size verdiğimiz mesaja sımsıkı sarılın, onun muhtevasını hatırdan çıkarmayın ki sorumluluğunuzun bilincine varasınız."},{"n":64,"t":"Bunun ardından bir kez daha sözünüzden döndünüz. Eğer Allah size lutfedip acımasaydı, kesinlikle kaybetmiştiniz."},{"n":65,"t":"Nitekim, içinizden Yasak Günü`nde haddi aşan kimseleri siz de biliyorsunuz. Onlara, \"Maymunlardan beter olun!\" demiştik."},{"n":66,"t":"Ve onları, hem ilk kuşaklar hem de sonraki nesiller için bir ibret vesikası, (taklitten) sakınanlar içinde uyarıcı bir örnek kıldık."},{"n":67,"t":"Hani (fail-i meçhul bir cinayet işlendiği) bir zaman da Musa, kavmine \"Allah size bir inek kurban etmenizi emrediyor!\" demişti de şöyle çıkışmışlardı: \"Sen bizimle dalga mı geçiyorsun?\" (Musa), \"Cahillerden olmaktan Allah`a sığınırım\" demişti."},{"n":68,"t":"Onlar: \"Bizim için Rabbine yalvar da, bize onun niteliğini açıklasın!\" dediler. \"O diyor ki, kesinlikle o ne çok yaşlı ne çok toy, bu ikisi arasında bir inek olmalı. Hadi artık size verilen emri yerine getirin!\" dedi."},{"n":69,"t":"Onlar: \"Bizim için Rabbine yalvar da bize onun rengini bildirsin\" dediler. O, \"Kesinlikle o, rengi bakanın gözünü kamaştıracak parlaklıkta sarı bir inek olmalı\" dedi."},{"n":70,"t":"Onlar: \" Bizim için Rabbine yalvar da bize onun tam olarak ne olduğunu açıklasın; çünkü bize göre bütün inekler birbirine benzer: (eğer açıklanırsa) inşaallah biz de doğrusunu buluruz\" dediler."},{"n":71,"t":"\"O diyor ki: o, toprağı sürmek ve ekin sulamak için çifte koşulmamış, kusursuz, alacasız bir inek olmalı\" dedi. Onlar: \"İşte şimdi gerçeği bildirdin\" dediler ve hemen onu (bulup) kurban ettiler: fakat neredeyse yapamayacaklardı."},{"n":72,"t":"Hani bir kişiyi öldürmüştünüz de, hemen ardından bu konuda birbirinizi suçlamıştınız. Oysa ki Allah örtbas ettiğiniz gerçeği ortaya çıkarırdı."},{"n":73,"t":"Bu maksatla dedik ki: \"Bu (prensib)i bu türden (çözünlenmemiş cinayet olaylarından) bazılarına da uygulayın!\" Allah aklınızı kullanabilesiniz diye ölüyü işte böyle diriltir ve ayetlerini size bu şekilde gösterir."},{"n":74,"t":"Bütün bunların ardından yürekleriniz katılaştı; taş gibi, hatta daha da katı hale geldi. Çünkü, nice kayalar var ki bağrından ırmaklar fışkırır, öyleleri de var ki yarıldığı zaman su çıkar, ve kimileri de var ki Allah`ın haşmetinden harekete geçip yuvarlanır. Allah yaptıklarınıza karşı duyarsız değildir."},{"n":75,"t":"Bütün bu olanlardan sonra siz, onların size inanmalarını mı bekliyorsunuz? Oysa onlardan bir çoğu Allah`ın kelamını işitip ne demek istediğini kavradıkları halde, bile bile tahrif ediyorlar."},{"n":76,"t":"Onlar, iman edenlerle buluştuklarında \"iman ettik\" derler, birbirleriyle baş başa kaldıklarındaysa (akıl hocaları, \"iman ettik\" diyenlere) \"Rabbinizin katında size karşı bir koz olarak kullansınlar diye mi Allah`ın size açtığı şeyi onlara haber veriyorsunuz? Bu kadarını düşünemiyor musunuz?\" derler."},{"n":77,"t":"Asıl onlar düşünmez mi ki, Allah onların gizlediklerini de çok iyi biliyor, açıkladıklarını da?"},{"n":78,"t":"Onların içerisinde ümmiler de var. Onlar kitabı bilmezler, sadece birtakım kuruntulara sahipler; ve onlar (gerçekleri bilmiyor) yalnızca zannediyorlar."},{"n":79,"t":"Yazıklar olsun onlara ki, kitabı kendi elleriyle yazıp da az bir getiri sağlamak için \"Bu Allah katındandır\" derler. Elleriyle yazdıklarından dolayı yazıklar olsun onlara, kazandıklarından dolayı da yazıklar olsun!"},{"n":80,"t":"Onlar, \"Sayılı bir kaç gün dışında kesinlikle bizi ateş yakmayacak\" derler. Sor onlara: \"Allah`tan kesin bir söz mü aldınız -ki eğer öyleyse, Allah sözünden kesinlikle caymaz-; yoksa bilmediğiniz bir konuda Allah`a iftira mı atıyorsunuz?\""},{"n":81,"t":"Aksine, kim kötülük yapar ve suçu onu vebaliyle çepeçevre kuşatırsa, işte onlar ateş halkıdır ve orada kalıcıdırlar."},{"n":82,"t":"İman eden ve ıslah edici iyilikler işleyen kimseler: İşte onlar cennet halkıdır ve onlar da orada kalıcıdırlar."},{"n":83,"t":"Hani bir zaman İsrailoğullarından yalnızca Allah`a kulluk edeceksiniz, ana-babaya, yakınlara, kimsesizlere, yoksullara iyilik yapacaksınız, insanlara güzel söz söyleyeceksiniz, namazı istikametle kılacaksınız, zekatı vereceksiniz diye söz almıştık. Sizden birkaç istisna dışında hepiniz sözünüzden dönmüştünüz; ve siz pek dönek bir toplumsunuz."},{"n":84,"t":"Yine sizden \"Birbirinizin kanını dökmeyeceksiniz, birbirinizi yurdunuzdan çıkarmayacaksınız\" diye de söz almıştık; üstelik siz de bunu ikrar etmiştiniz; hala da buna şahitsiniz."},{"n":85,"t":"Bütün bunlara rağmen birbirinizi katleden, günah ve düşmanlıkta dayanışma sergileyerek kendi içinizden bir kısımını yurtlarından çıkaran -ki onların çıkarılması size kesinlikle yasaklanmıştı- ve elinize esir düşdüklerinde onları ancak fidye karşılığı serbest bırakan yine sizlerdiniz. Şimdi siz vahyin bir kısmına inanıp bir kısmını inkar mı ediyorsunuz? İyi bilin ki, sizden kim böyle yaparsa, kesinlikle onun cezası dünya hayatında zilletten başka bir şey olmayacaktır. Ahirette ise azabın en acıklısına mahkum olacaklar. Zira Allah yaptıklarınıza karşı duyarsız değildir."},{"n":86,"t":"İşte bunlardır ahireti feda edip karşılığında dünya hayatını satın alanlar. Böyle kimselerin azabı hafifletilmeyecek ve onlara yardım da edilmeyecektir."},{"n":87,"t":"Musa`ya ilahi kelamı vermiş ve birbiri ardınca onu izleyen peygamberler göndermiştik. Meryem oğlu İsa`ya da gerçeğin açık belgelerini vermiş ve onu kutsal ruh ile güçlendirmiştik. Fakat her ne zaman bir elçi hoşunuza gitmeyen bir mesaj getirmişse, küstahça ona başkaldırdınız: kimini yalanladınız, kimini öldürüyorsunuz."},{"n":88,"t":"\"Kalplerimiz (bilgi ile) kaplıdır\" dediler. Aksine Allah, hakikati inkar ettikleri için onları rahmetinden dışlamıştır; baksanıza, ne kadar da azı inanıyor."},{"n":89,"t":"Allah katından o (Yahudilere) halen sahip oldukları bilgiyi doğrulayan bir kitap geldiğinde; -ki önceleri inkar edenlere (o kitap ve peygamberle) istikbalde galip gelecekleri (tehdidinde) bulunuyorlardı- işte böylesine tanıdıkları o kitap kendilerine geldiğinde onu inkar ettiler: Allah`ın laneti inkarcıların üzerine olsun!"},{"n":90,"t":"Allah`ın indirdiği vahyi kulları arasından istediğine bahşetmesini kıskanmaları ve indirdiği vahyi inkar ederek kişiliklerini satmaları ne fena şey! İşte bunun üzerine (dünyada) katmerli bir gazaba uğradılar: İnkar edenler için (ahirette de) alçaltıcı bir azap vardır."},{"n":91,"t":"Kendilerine \"Allah`ın indirdiğine inanın\" denildiğinde, \"Biz sadece kendimize indirilene inanırız\" derler. Kendilerinde mevcut bir hakikati doğruladığı halde, daha sonra gelen her hakikati inkar ederler. Onlara; \"Peki, eğer gerçekten inanmış idiyseniz daha önce Allah`ın (sizden olan) elçilerini neden öldürdünüz?\" diye sor."},{"n":92,"t":"Doğrusu Musa da size hakikatin apaçık belgeleriyle gelmişti. Ardından yine buzağıyı peydahlamıştınız ve siz yine kendisine kötülük edenlerden olmuştunuz."},{"n":93,"t":"Hani, bir zaman (Sina) Dağı`nı üzerinize yükselterek sizden kesin söz almıştık: \"Size gönderdiğimiz mesajı hayata uygulayın ve artık hakikatı duyun!\" Buna karşın \"İşittik ve itaat ettik/isyan ettik\" dediler. Küfürleri sebebiyle buzağı (heykeli) gönüllerinde taht kurdu. De ki onlara: Bozuk inancınız size ne fena şeyler yaptırıyor? Eğer gerçekten inandıysanız (böyle yapmazdınız)."},{"n":94,"t":"(Yine) onlara de ki: Allah katında, Ahiret yurdunun insanlar arasında yalnızca size ait olduğu inancında eğer samimiyseniz, hadi ölümü isteyin!"},{"n":95,"t":"Fakat işledikleri kötülükler yüzünden onlar hiçbir zaman ölümü istemeyecekler; Allah, kendi kendisine kötülük yapanları çok iyi bilir."},{"n":96,"t":"İnsanlar arasında, hayatın sadece bir türüne karşı en çok ihtiras taşıyanlar olarak, onları bulursun; hatta, Allah`tan başkasına ilahlık yakıştıranlardan da daha fazla. Onlardan her biri ister ki bin yıl yaşasın. Tut ki bunca ömre sahip olsun; bu dahi onu azaptan uzak tutamaz: Zira Allah tüm yapıp ettiklerini görmektedir."},{"n":97,"t":"(Ey Nebi!) De ki: \"Kim Cibril`e düşmansa, iyi bilsin ki o, hakikatten ellerinde kalanı doğrulayan, bir rehber ve inananlar için de bir müjde olan vahyi, senin kalbine Allah`tan aldığı izin sayesinde indirmiştir."},{"n":98,"t":"Allah`a, meleklerine, Cebrail ve Mikail de dahil elçilerine düşman olan herkes unutmasın ki, elbet Allah da böylesi kafirlerin düşmanıdır."},{"n":99,"t":"Doğrusu biz sana hakikatin apaçık belgelerini indirdik: yoldan sapmış olanlardan başkası bunları inkar edemez."},{"n":100,"t":"Ne yani, her söz verişlerinde onlardan bir kısmı bu sözden dönmedi mi? Maalesef onların çoğu güven duygusundan yoksun kalmışlardır."},{"n":101,"t":"Onlara Allah katından ellerindeki hakikati doğrulayan bir elçi gelince, kendilerine kitap verilenlerden bir kısmı, sanki gerçeği bilmiyorlarmış gibi Allah`ın kitabına sırt döndüler;"},{"n":102,"t":"ve onlar tutup Süleyman`ın yöntemi sırasında (o dönemin) şeytanlarının uydurduğu yalan ve desiselerin peşine takıldılar. Oysa ki Süleyman küfre sapıp nankörlük yapmadı, aksine o(na düzen kuran) şeytanlar küfre sapıp nankörlük yaptılar: insanlara sihri öğrettiler. Yine (Medine Yahudileri) Babilli iki güç sahibine; Harut ve Marut`a verileni izlediklerini (iddia ettiler). Oysa o ikisi \"Baksanıza biz (Babil esaretiyle) sınanmaktayız, sakın küfre sapma(yın)!\" demedikçe hiç kimseye bir şey öğretmiyorlardı. Fakat (Babil`deki düzenbazlar) bu ikiliden kişi ile eşinin arasını açacak şeyler öğreniyorlardı. Ne var ki o (Babilli düzenbazlar), Allah`ın izni olmadan hiç kimseye zarar veremezlerdi; ama yine de zarar verip yarar sağlamayan şeyler öğreniyorlardı. Doğrusu onlar, bu türden bir alışverişe giren kimsenin ahirette eli boş kalacağını çok iyi biliyorlardı. Kişiliklerini sattıkları şey ne fenadır; keşke bunu olsun bilebilselerdi."},{"n":103,"t":"Ve eğer onlar hakikate inansalar ve sorumluluklarının bilincine varsalardı, Allah katından kendileri için hayırlı bir ödül alırlardı. Keşke bunu olsun bilselerdi."},{"n":104,"t":"Siz ey iman edenler! \"Sen bize uy\" demeyin, \"Bizi görüp gözet\" deyin ve dinleyin; zira inkar edenleri acıklı bir azap beklemektedir."},{"n":105,"t":"Ne önceki vahyin muhataplarından küfre sapanlar, ne de Allah`tan başkasına ilahlık yakıştıranlar Rabbinizden size bir hayrın indirilmesini isterler. Oysa ki Allah, rahmetini dilediğine verir: zira Allah sınırsız lütuf sahibidir."},{"n":106,"t":"Biz yerine yenisini ya da daha hayırlısını getirmeden bir mesajı unutturmayız ya da yürürlükten kaldırmayız: Bilmez misin ki Allah her şeye kadirdir."},{"n":107,"t":"Yine bilmez misin ki göklerin ve yerin hakimiyeti Allah`a aittir. Sizin için, Allah`tan başka ne bir yar, ne de bir yardımcı var."},{"n":108,"t":"Yoksa daha önce Musa`dan istenilen şeylerin benzerini, siz de peygamberinizden mi istiyorsunuz? Kim imanı inkarla değiştirirse, iyi bilsin ki doğru yoldan sapmıştır."},{"n":109,"t":"Kitap ehlinden bir çoğu, hakikat kendileri için de apaçık ortaya çıktığı halde, sırf hasetlerinden dolayı siz inandıktan sonra, sizi geriye döndürüp inkar etmenizi isterler. Allah`ın onlar hakkındaki hükmü gelinceye kadar onları hoşgörün, kusurlarına bakmayın: Unutmayın ki Allah her şeye kadirdir."},{"n":110,"t":"Namazı istikametle kılın, zekatı gönülden gelerek verin. Unutmayın: Kendiniz için ne hayır yaparsanız Allah`ın katında onu mutlaka bulursunuz. Çünkü Allah bütün yaptıklarınızı görmektedir."},{"n":111,"t":"Bir de kalkıp dediler ki: Yahudi veya Hıristiyan olmayanlar cennete giremeyecek. Bu onların hüsnü kuruntusudur. De ki: Eğer iddianızın arkasında duruyorsanız, hadi ispatlayın."},{"n":112,"t":"Hayır aksine, her kim bütün varlığıyla görürcesine inandığı Allah`a teslim olursa, ancak o kişi Rabbi katında onun karşılığını bulacak; gelecek için kaygı, geçmiş için üzüntü duymayacaktır."},{"n":113,"t":"Hepsi de (aynı) kitabı okudukları halde, Yahudiler \"Hıristiyanlar bir inanç temelinden yoksundur\" dediler; Hıristiyanlar da \"Yahudiler bir inanç temelinden yoksundur\" dediler. (Vahye dair) bilgisi olmayanlar da tuttu, aynen onların söylediği gibi söyledi. Fakat Allah, anlaşamadıkları şeyler konusunda kıyamet günü son sözü söyleyecektir."},{"n":114,"t":"Allah`ın ibadethanelerinde O`na ibadet edilmesini engelleyen ve onu tahrip etmeye çalışandan daha zalim biri olabilir mi? Bu tür kimselerin oraya sadece Allah korkusuyla girmeleri gerekirdi: Onlara dünyada zillet, ahirette ise korkunç bir mahrumiyet vardır."},{"n":115,"t":"Doğu da Allah`ındır batı da. Şu halde nereye dönerseniz dönün, orası da Allah`ın yönüdür. Çünkü Allah sınırsızdır, ilmi her şeyi kuşatandır."},{"n":116,"t":"Bir de \"Allah bir oğul edindi\" iddiasında bulundular. Haşa! O aşkın bir hakikattir. Aksine göklerde ve yerde bulunan her şey O`na aittir: hepsi de O`nun iradesine boyun eğerler."},{"n":117,"t":"Gökleri ve yeri yoktan, eşsiz ve benzersiz yaratan O`dur. Bir işin olmasını murad ettiğinde, ona sadece \"ol\" der ve o da hemen oluş sürecine girer."},{"n":118,"t":"İlimden yoksun olanlar \"Allah bizimle niçin konuşmuyor, ya da niçin bize mucizevi bir belge ulaştırmıyor\" derler. Onlardan öncekiler de aynen onların söylediğini söylemişlerdi. Akılları da birbirine benzedi. Elbet biz gönülden inanacak herkes için ayetlerimizi açık ve anlaşılır kılmışızdır."},{"n":119,"t":"Gerçekten biz seni, hakikat ile müjdeleyici ve uyarıcı olarak gönderdik; ateşe yoldaş olanlardan sen sorumlu değilsin."},{"n":120,"t":"Sen onların inanç sistemini benimsemedikçe, ne Yahudiler ne de Hıristayanlar seni asla kabullenmeyecekler. Onlara şöyle de: Allah`ın rehberliği var ya, işte gerçek rehberlik odur. Eğer sana gelen (mutlak hakikatin) bilgisinden sonra onların keyifli sistemine uyarsan, Allah`ın elinden seni kurtaracak ne bir yar, ne de bir yardımcı bulabilirsin."},{"n":121,"t":"Kendilerine ilahi mesaj (verilip) de onu tilavet etmenin hakkını verenler var ya: işte onlardır ona hakkıyla inananlar, kim de bu mesajı inkar ederse, işte kaybedenler de onlardır."},{"n":122,"t":"Ey İsrailoğulları! Size lutfettiğim nimetlerimi hatırlayın; hani Ben sizi çağınızın milletlerine üstün kılmıştım?"},{"n":123,"t":"Kimsenin kimseye hiç bir fayda sağlamayacağı, kimseden kurtuluş bedeli kabul edilmeyeceği, şefaatin hiç bir yarar vermeyeceği ve hiç kimsenin yardım görmeyeceği günün bilincinde olun!"},{"n":124,"t":"Hani Rabbi İbrahim`i insanı şiddetle sarsan ağır imtihanlara tabi tutmuş ve o da bu (imtihanı) hakkıyla verdiği zaman demişti ki: \"Ben seni insanlığa önder yapacağım\". İbrahim: \"Neslimden de!?\" demişti. Allah buyurmuştu: \"Sözüm (senin neslinden de olsa) zalimler için asla geçerli değildir.\""},{"n":125,"t":"Hani bir zaman da Kabe`yi insanlık için daimi bir merkez ve kutsal bir güvenlik bölgesi kılmıştık: öyleyse İbrahim`in makamını dua ve ibadet yeri edinin! Nitekim biz İbrahim ve İsmail`e, \"Tavaf edecekler, (iç dünyasını iman için) içe kapanacaklar ve uzun uzun rüku ve secde ile namaz kılacaklar için mabedimi temiz tutun!\" diye emretmiştik."},{"n":126,"t":"Hani İbrahim de şöyle dua etmişti: \"Rabbim! Burasını emin bir bölge kıl! Onun sakinlerinden Allah`a ve ahiret gününe inananları türlü ürünlerle rızıklandır!\" Allah karşılık verdi: \"Onlardan küfredenleri de, geçici zevkleri tattırdıktan sonra yakıcı bir azaba mahkum ederim ki, orası pek fena bir duraktır.\""},{"n":127,"t":"İbrahim, İsmail`le birlikte Kabe`nin temelleri yükseltirken şöyle yalvardılar: \"Rabbimiz! Kabul buyur bizden! Yalnız sensin tüm duaları işiten; ve gönüllerdekini bilen de yalnız sen!"},{"n":128,"t":"\"Rabbimiz\" Bizi kayıtsız şartsız sana teslim olan kimselerden eyle! Soyumuzdan da sürekli sana teslim olacak önder topluluklar var et! Bize nasıl kulluk yapacağımızı göster ve bizi affet! Hiç şüphe yok ki sen tevbeleri çokça kabul edensin, rahmetle muamele edensin!"},{"n":129,"t":"\"Rabbimiz! Onlar arasından kendilerine senin mesajını okuyacak, ilahi kelamı ve hakikate mutabık hüküm vermeyi öğrenecek ve onları arındıracak bir elçi gönder. Çünkü yalnızca Sensin her işinde mükemmel olan, her hükmünde tam isabet kaydeden de Sen."},{"n":130,"t":"Kişiliksiz tipler hariç, kim İbrahim`in inanç sisteminden yüz çevirebilir ki? Biz onu dünyada seçkin kılmıştık, ahirette ise o kesinlikle erdemliler arasında yer alacak."},{"n":131,"t":"\"Rabbi ona `teslim ol` dediğinde, karşılığı şu oldu: Alemlerin Rabbine teslim oldum.\""},{"n":132,"t":"İşte İbrahim, kendi oğullarına bu dini vasiyet etmişti; nitekim Yakub da öyle yaptı: \"Yavrucuklarım! Allah size en saf, en temiz inancı seçti! Şu halde (Allah`a) tam teslim olmadan can verecekseniz sakın ölmeyin!\""},{"n":133,"t":"Ve siz (Ey İsrailoğulları), Yakub`un ölüm döşeğinde oğullarına \"Benden sonra neye kulluk edeceksiniz?\" diye sorduğunda, onların da \"Senin ve ataların İbrahim, İsmail ve İshak`ın da ilahı olan tek ilaha kulluk edeceğiz ve yalnızca O`na teslim olacağız\" dediklerine şahit olmadınız mı?\""},{"n":134,"t":"\"Şimdi o toplumlar geçmişte kaldı: onların kazandıkları kendilerine, sizin kazandıklarınız da size aittir; ve siz onların yaptıklarından asla sorumlu tutulmayacaksınız.\""},{"n":135,"t":"Onlar dediler ki: \"Yahudileşin ya da Hıristiyanlaşın ki doğru yolu bulasınız!\" De ki: \"Hayır, biz dosdoğru yol üzere bulunan İbrahim`in inanç sistemine mensubuz; üstelik o Allah`tan başkasına ilahlık da yakıştırmazdı.\""},{"n":136,"t":"Deyiniz ki: \"Biz Allah`a inanırız; bize indirilene, İbrahim`e, İsmail`e, İshak`a Yakub`a ve onların (iman) soyundan gelen (peygamberlere) indirilenlere; Musa`ya ve İsa`ya indirilene; yani tüm nebilere Rablerinden indirilenlere inanırız; onların arasından hiçbirini ayırt etmeyiz: zira biz sadece O`na teslim olanlarız."},{"n":137,"t":"Eğer onlar sizin inandığınız gibi inanırlarsa, işte asıl o zaman doğru yola girmiş olurlar. Yok eğer bundan kaçınırlarsa, o zaman ayrımcılık çıkarıp sapan onlar olmuş olur. Onlara karşı, (tam zamanında) Allah sana yetecektir: zira O`dur içinizden geçen dilekleri işiten, niyetlerinizi ayrıntısıyla bilen."},{"n":138,"t":"Allah`ın vurduğu boya... Kim Allah`tan daha güzel boya vurabilir ki? İşte biz, (bunun için) yalnızca O`na kulluk ederiz."},{"n":139,"t":"(Kitap Ehli`ne) de ki: Allah hakkında bizimle tartışacak mısınz? Halbuki O bizim de Rabbimiz, sizin de Rabbinizdir; bizim yaptıklarımızın sorumluluğu bize, sizin yaptıklarınızın sorumluluğu size aittir: biz varlığımızı sadece O`na adadık."},{"n":140,"t":"Yoksa siz \"İbrahim, İsmail, İshak, Yakub ve onların neslinden gelenler Yahudi ya da Hıristiyan`dılar mı demek istiyorsunuz? Söyle onlara: Siz Allah`tan daha mı iyi biliyorsunuz? Kendisine Allah`tan gelen bir şahitliği gizleyenden daha zalim kim olabilir? Ama Allah yaptıklarınızdan gafil değildir.\""},{"n":141,"t":"\"O toplumlar şimdi geçip gittiler: Onların kazandıkları kendilerine sizin kazandırdıklarınız da size aittir; ve siz onların yaptıklarından kesinlikle sorumlu tutulmayacaksınız.\""},{"n":142,"t":"İnsanlar arasından beyinsizler çıkıp diyecekler ki: \"Daha önce yöneldikleri kıbleden onları çeviren sebep nedir?\" De ki: \"Doğu da batı da Allah`ındır: O dileyen kimseyi doğru yola yöneltmeyi diler."},{"n":143,"t":"İşte böylece sizin dengeli bir ümmet olmanızı istedik ki, insanlığa örnek ve model olasınız ve Rasul de size örnek ve model olsun. Elçi`ye uyanların arasından topukları üzerinde geri dönenleri seçip ayırmak için, senin daha önce yöneldiğin yönü kıble olarak tayin ettik. Hiç şüphesiz bu olay Allah`ın yol gösterdikleri hariç, herkes için çok zor bir sınavdı; Allah sizin imanda ısrarınızı kesinlikle zayi etmeyecektir: Elbette Allah insanlara karşı sınırsız bir şefkat, sonsuz bir merhamet sahibidir."},{"n":144,"t":"Biz senin yüzünü gökyüzüne çevirip durduğunu görüyorduk. İşte şimdi seni kesinlikle razı olacağın bir kıbleye döndürüyoruz: Artık yüzünü Mescid-i Haram`dan yana çevir! Siz de nerede olursanız olunuz yönünüzü o yana çeviriniz! Kendilerine daha önce vahiy emanet edilmiş olanlar, bu emrin Rablerinden gelen bir gerçek olduğunu iyi bilirler: Allah onların yaptıklarından habersiz değildir."},{"n":145,"t":"Sen daha önceden kitap gönderilenlere tüm delilleri getirsen dahi onlar senin kıblene yönelmezler; ve sen de artık onların kıblesine yönelmezsin. Ve ne de onlar birbirlerinin kıblelerine yönelirler. Sana ilim geldikten sonra eğer onların keyiflerine uysaydın, bu durumda sen kesinlikle kendine zulmedenlerden olurdun."},{"n":146,"t":"Kendilerine vahiy tevdi edilenler, onu öz oğullarını tanıdıkları gibi tanırlar. Buna rağmen onların çoğu, bildikleri halde ısrarla gerçeği gizlerler."},{"n":147,"t":"Hakikat Rabbinden gelendir; sakın kuşkuya kapılanlardan olma."},{"n":148,"t":"Her bir ümmetin O`nun yönlendirdiği bir kıblesi vardır: O halde, iyilikte birbirinizle yarışın! Her nerede olursanız olun Allah sizin tümünüzü bir araya toplayacaktır. Zira Allah her bir şeye kadirdir."},{"n":149,"t":"Nereden yola çıkarsan çık, yüzünü mutlaka Mescid-i Haram`a çevir. Bil ki bu emir Rabbinden gelen bir hakikattir. Allah sizin de yaptıklarınızdan habersiz değildir."},{"n":150,"t":"Ve her nereden gelirsen gel, kesinlikle yüzünü Mescid-i Haram`dan yana çevir. Siz de nerede olursanız olunuz, yüzlerinizi Mescid-i Haram`dan yana çeviriniz ki, onlar içerisinden zulümde direnenler hariç, insanların size karşı kullanacakları bir delilleri olmasın. Onlara tazim göstermeyin, asıl Bana tazim gösterin! Böylece size olan nimetimi tamamlayayım ve siz de bu sayede doğru yolu bulabilesiniz."},{"n":151,"t":"İşte böylece, içinizden size ayetlerimizi okuyacak, sizi arındıracak, size ilahi mesajı ve hikmeti öğretecek ve ayrıca bilmediklerinizi size bildirecek bir elçi gönderdik."},{"n":152,"t":"Şu halde, beni anın ki ben de sizi anayım! Ve bana şükredin, sakın nankörlük etmeyin!"},{"n":153,"t":"Ey iman edenler! (Allah`tan) sabır ve salat ile yardım isteyin. Zira Allah sabredenlerle beraberdir."},{"n":154,"t":"Allah yolunda öldürülenler için \"ölü\" demeyin! Aksine onlar diridirler, fakat siz farkında değilsiniz."},{"n":155,"t":"Kesinlikle sizi korkuyla, açlıkla, mal, can ve verim kaybıyla sınarız. Ama sabredenleri müjdele!"},{"n":156,"t":"Onlar bir musibete uğradıklarında: \"Doğrusu biz Allah`a aidiz ve sonunda yine O`na döneceğiz\" derler."},{"n":157,"t":"İşte bunlar, Rablerinin sürekli destek ve bağışına mazhar olanlardır. Doğru yolda olanlar da bunlardır."},{"n":158,"t":"\"Hiç kuşkusuz Safa ile Merve Allah`ın sembollerindendir. Kim hac ya da umre amacıyla Kabe`yi ziyaret ederse, o ikisi arasında sa`y etmesinde herhangi bir mahzur yoktur. Eğer biri kalkar da emredilenin ötesinde hayır işlerse, iyi bilsin ki Allah yaptığının karşılığını bol bol verendir, (insan için iyi olanı) tarifsiz bir biçimde bilendir."},{"n":159,"t":"Şimdi, katımızdan indirdiğimiz apaçık belgeleri ve rehberlik delillerini Kitab aracılığıyla insanların önüne koyduktan sonra onu gizleyenler var ya: işte Allah`ın ve lanet etme yeteneğine sahip tüm varlıkların lanet ettiği kimseler onlardır."},{"n":160,"t":"Fakat tevbe edenler, kendini onaranlar ve gizlediği gerçeği açıklayanlar hariç. İşte onların tevbelerini kabul edeceğim: Zira, sadece Benim tevbeleri çokça kabul eden, merhameti sonsuz olan."},{"n":161,"t":"Küfreden ve küfründe sonuna kadar direnip o hal üzre ölen kimselere gelince: Allah`ın, meleklerin ve tüm insanlığın lanetine uğrayacak olanlar onlardır."},{"n":162,"t":"Onlar o lanetin içinde kalıcıdırlar: Onların ne azabı hafifletilecek, ne de kendilerine göz açtırılacaktır."},{"n":163,"t":"Ve sizin ilahınız bir tek İlah`dır; O`ndan başka tapılmaya layık hiçbir varlık yoktur; Özünde rahmet sahibi olan O`dur, işinde merhametli olan O`dur."},{"n":164,"t":"Şüphe yok ki göklerin ve yerin yaratılışında, gece ve gündüzün birbirini takip edişinde, insanlara yararlı yüklerle yüklenip denize açılan gemilerde, Allah`ın gökten indirerek kendisiyle yeryüzünü ölümünden sonra tekrar dirilttiği ve her tür canlının çoğalmasını sağladığı yağmurlarda, rüzgarları dağıtmasında, gökle yer arasında kendileri için belirlenen istikamette hareket eden bulutlarda, düşünen bir toplum için mesajlar vardır."},{"n":165,"t":"Fakat insanlar içerisinde Allah`tan başka birtakım varlıkları Allah`a eşdeğer rakip güçler olarak görüp, onları Allah`ı sever gibi sevenler de var. Oysa ki iman edenler en çok Allah`ı severler. Kendi kendine kötülük edenler, azaba uğratıldıkları zaman görecekleri gibi, keşke tüm kudretin sadece Allah`a ait olduğunu ve azabı en çetin olanın yalnızca Allah olduğunu görseler!"},{"n":166,"t":"Kendisine ilahlık yakıştırılanların, ilahlık yakıştıranlara sırt döndüğü o zaman gelip de azabı görünce, birbirleri arasındaki bütün ilişkiler kökten kesiliverecek."},{"n":167,"t":"İlahlık yakıştıranlar da diyecek ki: Keşke elimize ikinci kez dünyaya dönme fırsatı geçse de, onların bize sırt döndüğü gibi biz de onlara sırt dönsek. Böylece Allah onlara, yaptıkları tüm işleri derin bir pişmanlık (kaynağı) olarak gösterecek ve onlar ateşten de çıkamayacaktır."},{"n":168,"t":"Ey insanlık! Yeryüzündeki helal ve temiz olan her şeyden yararlanın! Şeytanın izinden gitmeyin! Çünkü o sizin apaçık düşmanınızdır:"},{"n":169,"t":"size yalnızca kötüyü, gayr-ı meşru olanı ve bilmediğiniz şeyleri Allah`a yakıştırmanızı telkin eder."},{"n":170,"t":"Onlara \"Allah`ın indirdiklerine uyun! \" denildiği zaman, \"Hayır, biz atalarımızın üzerinde bulunduğu geleneğe uyarız!\" derler. Ya ataları hiç akıllarını kullanmamış ve doğru yolu bulamışsalar?"},{"n":171,"t":"İşte inkarda direnen bu kimselerin durumu, şu (sürüye) benzer: Bir sürü (düşünün ki), çobanın canhıraş haykırışını yalnızca çığlık-bağlık olarak algılıyor. Onlar sağırdırlar, dilsizdirler, kördürler; çünkü onlar akıllarını kullanmazlar."},{"n":172,"t":"Siz ey iman edenler! Size rızık olarak bahşettiğimiz şeylerin temiz olanlarından yiyin ve Allah`a şükredin; gerçekten O`na kulluk ediyorsanız eğer."},{"n":173,"t":"O, size yalnızca leşi, kanı, domuz etini ve üzerine Allah`tan başkasının adı anılarak kesilen hayvanı haram kıldı. Kim bunlara mecbur kalırsa -iştahı kabarmadan ve haddi aşmadan- ona bir günah yoktur: Allah tarifsiz bağışlayıcıdır, eşsiz merhamet kaynağıdır."},{"n":174,"t":"Şüphesiz Allah`ın indirdiği ilahi mesajdan bir kısmını gizleyenler ve bunu az bir gelir karşılığında pazarlayanlar da var. Onlar karınlarına ateşten başka bir şey doldurmuyorlar. Kıyamet günü Allah onlarla konuşmayacak, onları temizlemeyecek, can yakıcı azab da onların olacak."},{"n":175,"t":"İşte onlar hidayet karşılığında sapıklığı, mağfiret karşılığında azabı satın aldılar. Meğerse ateşe ne kadar da dayanıklıymışlar!?"},{"n":176,"t":"İşte bu sebeple Allah, ilahi kelamı hakikati ortaya çıkarmak için indirdi. Onlar Kitab üzerinde anlaşmazlığa düşerek, haktan bir hayli uzaklaştılar."},{"n":177,"t":"Gerçek erdem yüzlerinizi doğuya veya batıya döndürmeniz değildir. Fakat gerçek erdem kişinin Allah`a, ahiret gününe, meleklere, İlahi kelama, peygamberlere inanması, malı -ona sevgi duymasına rağmen- yakınlara, yetimlere, yoksullara, yolda kalmışlara, isteyenlere ve özgürlüğü elinden alınanlara vermesi, namazı istikametle kılması, zekatı gönlünden gelerek vermesidir. Onlar söz verdikleri zaman sözlerinde dururlar, şiddetli zorluk ve darlıklara karşı göğüs gererler. İşte bunlardır sözlerine sadık kalanlar... Takvaya ermiş olanlar da bunlardır."},{"n":178,"t":"Siz ey iman edenler! Cinayete kurban gidenler hakkında size adil karşılık farz kılındı: Hüre karşılık hür, köleye karşılık köle, kadına karşılık kadın. Bunun üzerine her kim kardeşi tarafından bir şekilde bağışlanırsa, bu bağış makul bir biçimde uygulanmalı, tazminatı da ona güzellikle ödenmeli: İşte bu, Rabbiniz katından bir kolaylaştırma ve rahmettir. Kim ki bundan sonra haddi aşarsa, onun için şiddetli bir azap vardır."},{"n":179,"t":"Bakın ey akıl sahipleri! Kısasta sizin için hayat vardır: sizden (artık) sorumlu davranmanız beklenir."},{"n":180,"t":"Herhangi birinize ölüm yaklaştığında eğer geriye bir değer bırakıyorsa, münasip bir biçimde anne-babaya ve yakın akrabaya vasiyet etmek size farz kılındı. Bu, Allah`a karşı sorumluluk duyanların uymaları gereken bir hakikattir."},{"n":181,"t":"Kim de (vasiyeti) işittikten sonra tahrif edip değiştirirse, bunun günahı yalnızca onu değiştirenedir. Doğrusu Allah her şeyi işitendir, her şeyi bilendir."},{"n":182,"t":"Fakat kim vasiyet edenin yanlı ya da kasıtlı davrandığından endişe eder ve (mirasçıların) arasını uzlaştırırsa, bu durumda kendisine herhangi bir vebal yoktur. Elbette Allah tarifsiz bağışlayıcıdır, eşsiz merhamet kaynağıdır."},{"n":183,"t":"Siz ey iman edenler! Oruç tıpkı sizden öncekilere olduğu gibi size de yazıldı; belki bu sayede takvaya erersiniz:"},{"n":184,"t":"Sayılı günlerde... Sizden kim hasta ya da yolcu olursa, tutmadığının sayısı kadar diğer günlerde (oruç tutar) ve (bunlar arasından) ona gücü yetenler üzerine, bir yoksulu doyuracak fidye gerekir; Kim daha fazla hayır işlerse kendisi için daha yararlı olur, ama -eğer bilirseniz-oruç tutmanız sizin için daha hayırlıdır."},{"n":185,"t":"(O sayılı günler) Ramazan ayıdır ki, insanlığa rehber olan, bu rehberliğin apaçık belgelerini taşıyan ve hakkı batıldan ayıran Kur`an işte bu ayda indirilmiştir. Sizden biri bu aya ulaştığında oruç tutsun; hasta ya da yolcu olan kimse de başka günlerde kaza etsin! Allah sizin için kolaylık ister, sizi zora koşmak istemez; oruç günlerinin sayısını tamamlamanızı, sizi doğru yola ulaştırdığı için O`nu yüceltmenizi ve şükretmenizi ister."},{"n":186,"t":"Eğer kullarım sana Benden soracak olurlarsa, iyi bilsinler ki Ben çok yakınım: Bana dua edenin çağrısına hemen karşılık veririm. Öyleyse onlar da Bana karşılık versinler ve Bana tam güvensinler ki, hak yoluna yöneltilsinler."},{"n":187,"t":"Oruç günlerinizin gecesinde kadınlarınıza yaklaşmak size helaldir: Onlar sizin elbiseleriniz, siz de onların elbiselerisiniz. Sizin kendinizi zor duruma düşüreceğinizi Allah gördü; işte bu yüzden size affıyla muamele etti ve zorluğu üzerinizden kaldırdı: Şimdi artık onlara yaklaşın ve Allah`ın size meşru kıldığından yararlanın! Fecir vakti, gecenin karanlığından tan yerinin aydınlığı sizin için belirgin hale gelinceye kadar yiyin için! Sonra orucu geceye kadar tamamlayın! Mescidlerde itikafa girdiğinizde de hanımlarınıza yaklaşmayın! İşte bunlar Allah`ın çizdiği sınırlardır, sakın bunlara yaklaşmayın! Allah ayetlerini insanlığa böylece açıklıyor ki, sorumluluk bilincini kuşanabilsinler."},{"n":188,"t":"Birbirinizin mallarını gayr-ı meşru bir biçimde yemeyin ve günaha girerek bile bile insanların hakkını yemek için o malları kullanarak yetkililere ulaşmayın!"},{"n":189,"t":"Sana ayın evreleri hakkında soru soruyorlar. Cevap ver: O insanlık için zamanın ölçü birimidir, haccın da. Bu arada, evlere arkasından girmeniz de erdemlilik değildir, gerçek erdem sahibi, sorumluluk bilinciyle hareket eden kimsedir. O halde evlere kapılarından girin ve Allah`a karşı sorumluluğunuzun bilincinde olun ki, ebedi kurtuluşa erebilesiniz!"},{"n":190,"t":"Size karşı savaş açanlarla siz de Allah yolunda savaşın, fakat saldırganlık yapmayın! Allah saldırganlık yapanları sevmez."},{"n":191,"t":"Onları, (savaşta) gözünüze kestirdiğiniz her yerde öldürün. Sizi sürgün ettikleri yerden siz de onları sürgün edin. İnanca yönelik zulüm ve baskı ölümden beterdir. Mescid-i Haram civarında onlar size savaş açmadıkça siz de onlara savaş açmayın. Eğer onlar size savaş açarsa, onları öldürün! İşte kafirler böyle cezalandırılır."},{"n":192,"t":"Eğer yaptıklarına bir son verirlerse, şüphe yok ki Allah tarifsiz bağışlayıcıdır, eşsiz merhamet kaynağıdır."},{"n":193,"t":"Onlarla inanca yönelik zulüm ve baskı kalmayıncaya ve din yalnız Allah`a ait oluncaya kadar savaşın! Eğer yaptıklarına bir son verirlerse, zulmedenlerin haricindekilere düşmanlık da sona erecektir."},{"n":194,"t":"Dokunulmazlık ayında saldırana cevap, yine dokunulmazlık ayında verilir. Zira dokunulmazlıkta denklik esastır. Her kim de size saldırırsa, onun yaptığının aynısıyla siz de karşılık verin ve fakat Allah`a karşı sorumluluğunuzun bilincinde olun; Allah`ın, sorumluluk bilincini kuşananların yanında olduğunu aklınızdan çıkarmayın!"},{"n":195,"t":"Bir de Allah yolunda harcayın ve kendinizi kendi ellerinizle tehlikeye atmayın! Hep iyilik edin: Allah iyilik edenleri sever."},{"n":196,"t":"Haccı da umreyi de Allah rızası için eksiksiz ve tam yapın. Eğer yerine getirmekten alıkonursanız gücünüzün yeteceği bir kurban verin ve kurban yerine ulaşıncaya kadar başlarınızı tıraş etmeyin! İçinizden hasta ya da başından bir rahatsızlığı olan kimse fidye olarak oruç tutmalı veya sadaka vermeli ya da kurban kesmelidir. Bir engel olmadığı zaman, hacdan önce umre yapacak kimse gücünün yettiği cinsten bir kurban kessin! Fakat kurbana gücü yetmeyen üç günü hacda yedi günü döndükten sonra olmak üzere toplum on gün oruç tutsun! Bunlar ailece Mescid-i Haram civarında oturmayanlar içindir. Allah`a karşı sorumluluğunuzun bilincinde olun ve Allah`ın cezalandırmada çok şiddetli olduğunu aklınızdan çıkarmayın!"},{"n":197,"t":"Hac (her yılın) malum aylarındadır. Kim söz konusu aylarda haccı eda ederse artık o hac boyunca çirkin konuşmalardan, tüm yakışıksız davranışlardan ve kavgadan kaçınılmalıdır. Zira ne tür iyilik yaparsanız Allah bunu bilir: Öyleyse (ebedi yolculuk için) azık hazırlayın! Hiç kuşkusuz yol azığının en hayırlısı sorumluluk bilincini kuşanmaktır: Bana karşı sorumluluğunuzun bilincinde olun ey derin kavrayış sahipleri!"},{"n":198,"t":"Rabbinizin lutfundan pay almak istemenizde size bir vebal yoktur. Arafat`tan çağlayıp akarken Meş`ari`l-Haram`da Allah`ı anın! Artık O`nu, size gösterdiği gibi anın! Doğrusu siz, bundan önce yolunu şaşıranlar arasındaydınız."},{"n":199,"t":"Ardından insanların çağlayıp geldikleri yerden siz de çağlayıp gelin ve Allah`tan günahlarınıza mağfiret dileyin! Doğrusu Allah tarifsiz bağışlayıcıdır, eşsiz merhamet kaynağıdır."},{"n":200,"t":"(Hacca has) ibadetlerinizi tamamladıktan sonra (bir zamanlar) atarınızı andığınız gibi, hatta daha güçlü bir biçimde Allah`ı anın! İnsanlardan bazısı \"Ey Rabbimiz! Bize vereceğini bu dünyada ver!\" derler. Böylelerinin ahiret nimetlerinden nasibi yoktur."},{"n":201,"t":"Fakat öyleleri de var ki, onlar \"Ey Rabbimiz! Bize bu dünyada da iyilik güzellik ver, ahirette de iyilik güzellik ver ve bizi ateşin azabından koru!\" diye yakarırlar."},{"n":202,"t":"İşte bunlar, kazandıklarına karşılık (ahiret nimetlerinden) nasip alacak olanlardır: zira Allah hesabı seri bir biçimde görendir."},{"n":203,"t":"Sayılı günlerde Allah`ı anın! Her kim acele edip iki günde dönerse ona günah yoktur. Kim de dönüşü erteleyip daha uzun kalırsa sorumlu davrandığı sürece ona da günah yoktur. Allah`a karşı sorumluluğunuzun bilincinde olun ve sonunda O`nun huzurunda toplanacağınızı aklınızdan çıkarmayın!"},{"n":204,"t":"İnsanlardan kimi var ki, batılda ölesiye direnen bir hasım olduğu halde, bu dünya hayatı hakkında söylediği söz senin hoşuna gider ve kendi kalbindekine de Allah`ı şahit tutar."},{"n":205,"t":"Eline yetki geçtiği zaman da yeryüzünde fesat çıkarmaya, insanın ürününü ve neslini yok etmeye çalışır: Ama Allah fesadı sevmez."},{"n":206,"t":"Kendisine ne zaman \"Allah`a karşı sorumluluğunun bilincinde ol!\" dense, kibir ve gururu onu günaha sürükler. İşte böylesine cehennem yeter, ne kötü konaktır orası!"},{"n":207,"t":"İnsanlardan kimi de var ki Allah rızasını kazanmak için kendisini (vakfeder). Allah ise kullarına karşı hep şefkatlidir."},{"n":208,"t":"Ey iman edenler! Hep birlikte teslimiyet yoluna girin ve şeytanın adımlarını izlemeyin! Çünkü o sizin apaçık düşmanınızdır."},{"n":209,"t":"Eğer hakikatin apaçık belgeleri size geldikten sonra ayaklarınız kayarsa, Allah`ın her işinde mükemmel olduğunu, her hükmünde tam isabet kaydettiğini unutmayın!"},{"n":210,"t":"Onlar, Allah`ın meleklerle birlikte bulutların gölgeleri arasından çıkagelmesini mi gözlüyorlar? Bu durumda iş bitirilmiş olurdu: Nihayet bütün işler Allah`a döndürülür."},{"n":211,"t":"Sor İsrailoğullarına: Biz onlara nice açık mesajlar verdik de (ne oldu)? Her kim Allah`ın nimeti olan mesajlarını kendilerine ulaştıktan sonra değiştirirse, bilsin ki Allah karşılık vermede şiddetlidir."},{"n":212,"t":"Kafirlere dünya hayatı güzel görünür; bu yüzden mü`minlerle alay ederler. Sorumluluk şuuru taşıyanlarsa kıyamet günü onlardan üstün bir konumda olacaklar. Allah dilediğine hesapsız rızık verir."},{"n":213,"t":"BÜTÜN insanlık (başlangıçta) tek bir topluluk idi, (sonradan yoldan çıkıp parçalandı). Allah nebilerini müjdeleyici ve uyarıcı olarak gönderdi. Onlarla birlikte gerçek bir amaca mebni olarak vahiy(ler) gönderdi ki, o vahiyler, insanlar arasında ihtilafa düştükleri konularda hakem olsun. Buna rağmen, kendilerine hakikatin apaçık belgeleri geldikten sonra, aralarındaki kıskançlık yüzünden O’nun mesajı hakkında ihtilafa düşenler bizzat bu vahyin gönderildiği insanlardan başkası değildi. Sonuçta Allah iman edenlere, kendi iradesiyle, hakkında ihtilafa düştükleri hususlarda doğru yolu gösterdi. Allah, isteyeni/istediğini doğru yola işte böyle yöneltir."},{"n":214,"t":"Yoksa siz, sizden öncekilerin başına gelenler sizin de başınıza gelmeden cennete gireceğinizi mi sanıyorsunuz? Onların başına öyle şiddetli zorluklar, öyle boğucu darlıklar geldi ve öylesine sarsıldılar ki, mü`minlerle birlikte Elçi de \"Allah`ın yardımı ne zaman gelecek!\" diye feryat ediyordu. Bakın, Allah`ın yardımı yakındır."},{"n":215,"t":"Sana, (kime) neyi infak edeceklerini soruyorlar. Cevap ver: \"Hayır olarak yapacağınız harcama öncelikle ebeveyninize, akrabanıza, yetimlere, yoksullara, yoldakileredir. Her ne iyilik yaparsanız yapın, Allah onu mutlaka bilir."},{"n":216,"t":"Hoşunuza gitmese de savaş size farz kılındı. Hem sizin hoşlanmadığınız bir şey sizin için hayırlı, sizin hoşlandığınız bir şey de sizin için şerli olabilir: Allah, sizin bilmediklerinizi de bilir."},{"n":217,"t":"Sana saldırmazlık ayında savaşmanın hükmünü soruyorlar. De ki: \"O ayda savaşmak büyük bir hatadır. Fakat Allah`ın yolundan insanları çevirmek, O`nu ve Mescid-i Haram`ın hürmetini inkar etmek, oranın sakinlerini oradan sürüp çıkarmak Allah katında daha büyük bir cürümdür. Fakat inanca yönelik baskı ve zulüm, adam öldürmekten daha beterdir.\" Eğer düşmanlarınızın gücü yeterse, sizi dininizden döndürünceye kadar sizinle savaşmayı sürdürürler. Sizden her kim dininden döner ve kafir olduğu halde ölürse, onun bütün yapıp-ettiği ameller dünyada da ahirette de boşa gitmiştir. Onlar ateşe mahkumdurlar, onlar orada kalıcıdırlar."},{"n":218,"t":"Şüphe yok ki iman edenler, hicret edenler ve Allah yolunda cihad edenler var ya; işte ancak onlar Allah`ın rahmetini umabilirler: Allah tarifsiz bağış sahibidir, eşsiz merhamet kaynağıdır."},{"n":219,"t":"Sana sarhoşluk veren şeyler ve şans oyunları hakkında soruyorlar. De ki: \"Onların her ikisinde de insanlar için büyük bir kötülük ve birtakım menfaatler vardır. Her ikisinin yol açtıkları kötülük sağladıkları menfaatten çok daha büyüktür.\" Yine onlar \"Neden infak edelim?\" diye soruyorlar. De ki: \"Bağışlanabilen her şeyden\". Böylece Allah size mesajlarını açıklıyor ki, tefekkür edebilesiniz."},{"n":220,"t":"Bu dünya ve ahiret hakkında... Bir de sana yetimler hakkında soruyorlar. De ki: \"Onların lehine olan her tür iyileştirme (yüzüstü bırakmakdan) daha hayırlıdır. Onlarla (hayatı) paylaşırsanız, unutmayın ki onlar sizin kardeşinizdir. Kaldı ki Allah fesatçılık yapanı ıslah edenden ayırmasını bilir. Ve eğer Allah dileseydi sizi zora koşardı; ne var ki Allah her işinde mükemmeldir, her hükmünde tam isabet sahibidir."},{"n":221,"t":"Müşrik kadınlarla onlar imana ulaşıncaya kadar evlenmeyiniz! Çünkü (Allah`a) bağlanmış hür olmayan mü`min bir kadın, müşrik hür bir kadından -ondan hoşlanıyor da olsanız- daha hayırlıdır. Yine müşrik erkeklerle, onlar iman edinceye kadar kadınlarınızı nikahlamayınız! Zira (Allah`a) kulluk yapan mü`min bir erkek, müşrik bir erkekten -bu sizi hoşnut etse bile- daha hayırlıdır. Onlar sizi ateşe çağırıyor, oysa ki Allah sizi kendi rızasıyla cennet ve mağfirete çağırıyor; dahası, mesajlarını insanlığa açıklıyor ki ibret alsınlar."},{"n":222,"t":"Sana kadınların ay hali hakkında soruyorlar. De ki: \"O sıkıntı verici bir rahatsızlıktır: Ay hali sırasında kadınları (rahat) bırakın ve onlar temizleninceye kadar (cinsel) ilişkiye girmeyin! Temizlendikleri zaman, Allah`ın size emrettiği gibi yaklaşın!\" Hiç kuşkusuz Allah özden tevbe edenleri sever, özden temizlenenleri de sever."},{"n":223,"t":"Kadınlarınız, sizin için bir tür tarladır; tarlanıza nereden, nasıl ve ne zaman isterseniz öyle varın! Fakat önce kendi canlarınız için bir hazırlık yapın! Allah`a karşı sorumluluğunuzun bilincinde olun ve unutmayın ki, mutlaka O`na kavuşacaksınız! Artık sen de mü`minleri müjdele!"},{"n":224,"t":"Allah adına ettiğiniz yeminler, erdemliliğe, sorumluluğun gereğini yerine getirmeye ve insanlar arası barışın sağlanmasına engel teşkil etmesin! Allah her şeyi işitir, tarifsiz bilir."},{"n":225,"t":"Allah, düşünmeden yaptığınız yeminlerden dolayı sizi sorumlu tutmaz; fakat kalplerinizin aldığı tavırdan sorumlu tutacaktır; ama Allah tarifsiz bağışlayandır, cezalandırmadan önce fırsat tanıyandır."},{"n":226,"t":"Hanımlarına yaklaşmamaya yemin edenlere dört ay bekleme süresi vardır. Şayet dönerlerse, iyi bilsinler ki Allah tarifsiz bağış, eşsiz merhamet sahibidir."},{"n":227,"t":"Ama eğer ayrılmaya karar verirlerse, bilsinler ki Allah her şeyi işitendir, her şeyi bilendir."},{"n":228,"t":"Boşanmış hanımlar, üç temizlenme süresince kendilerini gözetlerler. Zira eğer Allah`a ve ahiret gününe inanıyorlarsa Allah`ın rahimlerinde yarattığını gizlemeleri onlara helal değildir. Bu süre zarfında barışmak isterlerse, bu durumda kocaları onları almak hakkında önceliğe sahiptirler. Meşru olmak kaydıyla erkeklerin kadınlar üzerinde nasıl hakları varsa, kadınların da erkek üzerinde benzer hakları vardır, ne ki erkeklerin o kadınlar üzerinde öncelik hakkı vardır. Allah her işinde mükemmeldir, her hükmünde tam isabet edendir."},{"n":229,"t":"(Dönüşü mümkün olan) boşama iki defadır. Bundan sonrası ya iyilikle geçinmek ya da güzellikle (son defa boşayıp) ayrılmaktır. Bu durumda kadınlarınıza verdiğiniz şeyleri geri almanız, her iki tarafın da Allah`ın koyduğu sınırları koruyamama endişeleri dışında, sizin için helal değildir. Eğer Allah`ın her iki taraf için koyduğu sınırları koruyamamalarından endişe ederseniz, bu durumda kadının fidye verip ayrılmasında her ikisi için de bir vebal yoktur. Bunlar Allah`ın koyduğu sınırlardır, sakın ha aşmayın! Kim Allah`ın koyduğu sınırları aşarsa, işte onlar zulmetmiş olurlar."},{"n":230,"t":"Ve erkek (sonunda) kadını boşarsa, bu kadın bir başka erkekle evlenmedikçe kendisine helal olmaz. Eğer sonraki erkek de onu boşarsa, her iki taraf da Allah`ın koyduğu sınırları gözetecekleri kanaatindeyse, tekrar birbirlerine dönmelerinde bir günah yoktur. İşte bunlar, Allah`ın akledenlere açıkladığı sınırlardır."},{"n":231,"t":"Bu şekilde kadınları boşadığınızda ve onlar da bekleme sürelerinin sonuna geldiklerinde, ya güzellikle tutun ya da güzellikle bırakın! Onlara zarar vermek için alıkoymayın! Bu durumda haddi aşmış olursunuz. Kim de böyle yaparsa, elbette kendisine kötülük etmiş olur. Allah`ın ayetlerini hafife almayın! Allah`ın size olan nimetlerini, size öğüt vermek için size indirdiği vahyi ve hikmeti hatırlayın ve Allah`a karşı sorumluluğunuzun bilincinde olun! İyi bilin ki Allah her şeyin aslını bilir."},{"n":232,"t":"Kadınları boşadıktan sonra, bekleme sürelerini tamamlamışlarsa, aralarında münasip bir biçimde anlaştıkları takdirde, eş(namzet)leriyle evlenmelerine engel çıkarmayın! Bu, içinizden Allah`a ve ahiret gününe inanan herkese bir uyarıdır; işte bu sizin için en yararlı ve en temiz olandır. Allah her şeyi bilir ve fakat siz bilemezsiniz."},{"n":233,"t":"Ve (boşanmış) annelerden emzirme süresini tamamlatmak isteyenler çocuklarını tam iki yıl emzirirler; onların yeme-içme ve giyim-kuşaklarını temin etmek münasip bir biçimde babaya düşer. Hiç kimseye taşıyamayacağı bir sorumluluk yükletilemez. Ne bir anne çocuğu yüzünden zarara uğratılsın, ne de çocuğu yüzünden bir baba. Ve (babanın) varisine de aynı görev düşer. Eğer (çocuğun boşanmış ebeveyni, çocukla annenin) ayrılmasına karşılıklı istişare sonucu razı olurlarsa, her ikisine de bir vebal yoktur. Eğer çocuklarınızı süt annelere baktırmaya karar verirseniz, teslim edeceğiniz çocuğun emniyetini uygun şekilde sağlamanız şartıyla size bir vebal yoktur. Allah`a karşı sorumluluğunuzun bilincinde olun: iyi bilin ki Allah tüm yapıp - ettiklerinizi görmektedir."},{"n":234,"t":"İçinizden ölen kimselerin geriye bıraktığı eşler dört ay on gün kendilerini gözetlesinler. Bu süreyi tamamladıklarında kendileri için gerekli olan şeyleri meşru olmak kaydıyla yapmalarında size herhangi bir vebal yoktur. Ve Allah yaptığınız her şeyden haberdardır."},{"n":235,"t":"Ve bu gibi kadınlara evlenme arzusunu ima etmekte, ya da böyle bir arzuyu içinizde taşımanızda da bir vebal yoktur. Nasılsa Allah sizin onlara karşı hissetiğiniz duyguları açacağınızı bilir. Lakin onlarla meşru bir biçimde konuşmak yerine, duygularınızı gizlice açma yoluna gitmeyin; dahası, belirlenmiş süre tamamlanmadan evlilik bağını, kurmaya kalkmayın! Zira iyi bilin ki Allah içinizde sakladıklarınızı bilir: öyleyse O`ndan sakının! Ve yine iyi bilin ki Allah tarifsiz bağışlayandır, acele cezalandırmayandır."},{"n":236,"t":"Kendilerine henüz dokunmadığınız ya da bir mehir tesbit etmediğiniz kadınları boşamanızda size bir vebal yoktur. Ne ki (bu durumda dahi) onlara destek olun! Eli geniş olan kendi takdirince, eli dar olan da gücü yettiği miktar makul bir biçimde geçimlik tedarik etsin! Bu, Allah`ı görür gibi inanan herkesin üzerine bir yükümlülüktür."},{"n":237,"t":"Eğer kendilerine dokunmadan fakat mehirlerini tesbit ettikten sonra boşarsanız, bu durumda tesbit ettiğiniz miktarın yarısı onlarındır; ancak onların bundan vazgeçmeleri ya da nikah bağını elinde tutan kimsenin vazgeçmesi müstesna. Vazgeçmeniz takvaya daha uygundur, zira birbirine karşı fedakarca davranmanız gerektiğini aklınızdan çıkarmayın: çünkü Allah yaptığınız her şeyi görmektedir."},{"n":238,"t":"Namazlarınızı, özellikle en ideal namazı kılmaya gayret edin ve Allah`ın huzurunda gönülden bir bağlılıkla durun!"},{"n":239,"t":"Fakat tehlikedeyseniz, yaya ya da binek üzerinde eda edin! Tekrar güvenliğe kavuştuğunuzda Allah`ı, bilmezken size bildirdiği gibi anın!"},{"n":240,"t":"İçinizden biri ölür de geride eşler bırakırsa, dul eşlerine, kendi evlerinden çıkarılmaksızın bir yıllık geçimlik vasiyet etsinler! Eğer onlar kendiliklerinden çıkarlarsa, size onların kendileri hakkında aldıkları makul kararları uygulamalarından dolayı bir vebal yoktur. Ve Allah her işinde mükemmeldir, her hükmünde tam isabet edendir."},{"n":241,"t":"Ve (böylece) boşanmış dul kadınlar da meşru bir biçimde geçimlerini sağlamış olacaklardır: Bu, sorumlu davranan herkesin üzerine düşen bir görevdir."},{"n":242,"t":"İşte Allah aklınızı kullanabilesiniz diye, size mesajlarını böyle açıklıyor."},{"n":243,"t":"Sayıları binlerce olduğu halde, ölüm korkusuyla yurtlarını terk edenleri gözünde canlandırabilir misin!? Allah onlara önce \"Ölün!\" demiş, peşinden onları hayata döndürmüştü. Hiç şüphesiz Allah insanlara karşı sınırsız lütuf sahibidir, fakat insanların çoğu şükretmezler."},{"n":244,"t":"O halde Allah yolunda savaşın! Ama unutmayın ki, Allah her şeyi tarifsiz işitendir, her şeyi sınırsız bilendir."},{"n":245,"t":"Allah`ın kat kat fazlasıyla geri ödeyeceği bir güzel borcu O`na verecek olan kimdir? Allah hem daraltır hem genişletir; ve hepiniz sonunda O`na döndürüleceksiniz."},{"n":246,"t":"Musa`dan sonra İsrailoğullarının ileri gelenlerinin, peygamberlerinden birine \"Bize bir kral tayin et ki Allah yolunda savaşalım\" dediklerini görmedin mi? O da dedi ki: \"Ya size savaş emredildikten sonra savaşmaktan geri durarak isyan ederseniz?\" Cevap verdiler: \"Biz, yurdumuzdan ve çoluk-çocuğumuzdan ayrı düşürülmüşken neden savaşmayalım?\" Oysa ki savaşmak onlara emredilince, pek azı dışında hepsi yüz çevirdiler. Allah, gerçek zalimlerin kim olduğunu çok iyi bilmektedir."},{"n":247,"t":"Peygamberleri onlara, \"İşte, Allah size Talut`u hükümdar tayin etti\" deyince şöyle karşı çıktılar: \"Biz yönetime ondan daha layıkken ve ona büyük bir servet de verilmemişken, nasıl olur da o bizim üzerimize otorite sahibi olabilir ki?\" Cevap verdi: Çünkü Allah onu seçti, ilimde kuşatıcı bir derinlik ve fiziki üstünlük sahibi kıldı. Ve Allah otoriteyi dilediğine bahşeder: zira Allah sınırsız güç sahibidir, her şeyi bilendir."},{"n":248,"t":"Ve Peygamberleri onlara dedi ki: \"Bakın, onun otoritesini meşru kılan belge olarak size içinde Rabbiniz tarafından bahşedilmiş bir gönül huzuru ile Musa`nın ailesi ve Harun`un ailesinden geriye kalan, meleklerin yüklediği bir gönül bağışlanacaktır. Eğer gerçekten inanıyorsanız, bunda sizin için bir işaret vardır.\""},{"n":249,"t":"Ve Talut ordusuyla harekete geçtiği zaman dedi ki: \"Bakın, Allah sizi bir ırmakla sınayacak; kim ondan içerse benden değildir, kim de ondan tatmazsa bendendir; ancak bir avuç içen bundan müstesnadır. Onlardan pek azı dışında, hepsi ondan (kana kana) içtiler. O ve ona inananlar ırmağı geçtikleri sırada, (ırmağın beri tarafında kalanlar) dediler ki: \"Bugün Calut ve ordusuna karşı koyacak gücümüz yok\". (Fakat) Allah`a kavuşacaklarına kesin gözüyle bakanlar da dediler ki: \"Nice sayıca az (örgütlü ve disiplinli) topluluk, Allah`ın izniyle nice sayıca çok (örgütsüz ve başı bozuk) topluluklara galip gelmiştir: Zira Allah direnenlerle beraberdir.\""},{"n":250,"t":"Onlar Calut ve ordusuyla karşı karşıya geldiklerinde \"Ey Rabbimiz! Üzerimize sabır boca et ve ayaklarımızı (hak üzre) sabit tut; ve kafirler güruhuna karşı bize yardım et!\" diye dua ettiler."},{"n":251,"t":"Bunun üzerine, Allah`ın izniyle onları bozguna uğrattılar. Ve Davut Calut`u öldürdü, bunun ardından Allah da ona hükümranlık ve adil hüküm liyakati verdi ve dilediklerine öğretti. Eğer Allah insanların bazısını diğer bazısıyla savunmamış olsaydı, yeryüzü fesada giderdi. Ve fakat Allah bütün varlıklara karşı sınırsız lütuf sahibidir."},{"n":252,"t":"İşte bunlar Allah`ın mesajlarıdır; biz bunları sana gerçek bir amaca mebni olarak iletiyoruz, çünkü sen kendisine mesaj gönderilenlerdensin."},{"n":253,"t":"Söz konusu elçilerden her birine diğerinden farklı meziyetler bahşettik. Onlardan kimisiyle Allah konuşmuş, kimisini de yüce mertebelere çıkarmıştır. Meryem oğlu İsa`ya da hakikatin apaçık belgelerini verdik ve onu mukaddes ruh ile destekledik. Eğer Allah dileseydi, onların ardından gelenler, kendilerine hakikatin apaçık belgeleri geldikten sonra birbirlerinin kanına girmezlerdi. Ne ki onlar ihtilafa düştüler; onlardan kimi inandı, kimi de inkar etti. Eğer Allah dileseydi birbirlerinin kanına girmezlerdi, fakat Allah dilediğini yapar."},{"n":254,"t":"Siz ey iman edenler! Kendisinde pazarlığın, dostluğun ve şefaatin olmayacağı gün gelmezden önce size rızık olarak bahşettiklerimizden harcayın! Zira nankörler zalimlerin ta kendileridir."},{"n":255,"t":"Allah, kendisinden başka ilah olmayan, mutlak diri, hayatın ve varlığın kaynağı ve dayanağıdır; ne gaflet basar O`nu, ne de uyku. Göklerde ve yerde olan her bir şey O`nundur: O`nun izni olmaksızın katında şefaat edecek olan kimmiş bakayım? O, kullarının önünde-açıkta olan şeyleri de, ardında-gizli olan şeyleri de bilir; oysa onlar, O dilemedikçe O`nun ilminden hiç bir şey kavrayamazlar. O`nun sonsuz kudret ve otoritesi gökleri ve yeri kaplamıştır; üstelik onları görüp gözetmek O`na güç gelmez: zira yüce ve azametli olan yalnızca O`dur."},{"n":256,"t":"Zorlama dinde yoktur. Artık doğru ile yanlış birbirinden seçilip ayrılmıştır. Şu halde kim şeytani güç odaklarını reddeder de Allah`a inanırsa, kesinlikle kopmaz bir kulpa yapışmış olur: zira Allah her şeyi sınırsız işitendir, her şeyi limitsiz bilendir."},{"n":257,"t":"Allah`tır iman edenlerin velisi: onları (kalp gözünü kör eden) karanlıklardan (iç) aydınlığa çıkarır. Küfreden kimselerin velileri ise şeytani güç odaklarıdır: onları aydınlıktan çıkarıp karanlıklara iterler. İşte onlar ateşin sakinleridirler, onlar orada kalıcıdırlar."},{"n":258,"t":"Sırf Allah kendisine hükümranlık verdi diye Rabbi hakkında İbrahim`le tartışan kimseye baksana! O zaman İbrahim demişti ki: \"Benim Rabbim hayat veren ve öldürendir\". O cevap verdi: \"Ben de hayat verir ve öldürürüm.\" İbrahim: \"Allah güneşi doğudan getirir, hadi sen de onu batıdan getir!\" demişti de küfre gömülen herif donakalmıştı: Evet, Allah zulme gömülmüş bir topluma asla rehberliğini bahşetmez."},{"n":259,"t":"Yoksa (sen ey insan); alt üst olmuş, her tarafı yıkılıp harabe haline gelmiş bir şehre uğrayıp, \"Allah bütün bunları öldükten sonra nasıl diriltecek?\" diyen biri gibi misin? Allah onu yüz yıl ölü olarak bıraktı, ardından dirilterek sordu: \"Ne kadar kaldın?\" O da cevap verdi: \"Bir gün ya da daha az kaldım.\" Buyurdu: \"Hayır, aksine yüz yıl kaldın, istersen yiyeceğine ve içeceğine bak, daha kokuşmamış bile; ve bir de eşeğine bak. Biz, seni insanlara bir işaret kıldık. Ve bak (canlılara ait) kemiklere, onları nasıl yerli yerince dizip, ardından üzerlerini etle kapladığımızı düşün!\" Bütün bunlar kendisine açıklanınca şu itirafta bulundu: \"Artık bildim ki Allah her şeye kadirdir.\""},{"n":260,"t":"Hani İbrahim demişti ki: \"Rabbim, ölüyü nasıl dirilttiğini bana göster!\" O da, \"Yoksa inanmadın mı?\" diye sordu. Cevap verdi: \"Hayır, fakat kalbim mutmain olsun diye.\" O da, \"O halde dört kuş al ve onları kendine (itaate) alıştır; bunun ardından onları ayrı ayrı bir tepeye sal ve onları çağır; uçarak sana gelecekler: İyi bil ki Allah her işinde mükemmeldir, her hükmünde tam isabet edendir.\""},{"n":261,"t":"Mallarını Allah yolunda harcayanların durumu, yedi başak veren ve her başakta yüz dane bulunan tohuma benzer. Allah dilediğine kat kat verir: zira Allah, (rahmetiyle) sınırsızdır, her şeyi tarifsiz bilendir."},{"n":262,"t":"Mallarını Allah yolunda sarf etmekte olanlar, sonra sarf ettikleri şey(in arkasın)a başa kakma ve (gönül) incitme katmayanlar var ya, onların, Rableri katında mükâfâtları vardır. Hem onlara hiçbir korku yoktur ve onlar mahzun olmazlar."},{"n":263,"t":"Gönül yapan hoş bir söz ve rahmet dileme, arkasından incitmenin geldiği bir yardımdan daha hayırlıdır. Ve Allah kendi kendine yetendir, cezalandırmadan önce fırsat tanıyandır."},{"n":264,"t":"Siz ey iman edenler! İnsanlara gösteriş için malını harcayan, Allah`a ve ahiret gününe de inanmayan kimse gibi, başa kakarak ve gönül inciterek yardımlarınızın sonucunu iptal etmeyiniz. O kişinin hali, üzerinde biraz toprak bulunan bir kayaya benzer: bir sağanak yağar, onu cascavlak bırakıverir. İşte bu gibilerin, yaptıklarından hiçbir kazançları olamaz. Zira Allah kafir bir topluma asla rehberliğini bahşetmez."},{"n":265,"t":"Geçici servetlerini Allah rızasını elde etmek ve kişiliklerini güçlendirmek için harcayanların durumu da verimli bir bahçe gibidir: bir sağanak yağar, bu sayede ürünü iki kat biter. Tut ki sağanak yağmadı, çiselese dahi yeter. Neticede Allah yaptığınız her şeyi görür."},{"n":266,"t":"Sizden biri, zemininden ırmaklar çağlayan, içerisinde her tür meyve yetişen asma ve hurma bahçesine sahip olsun, bu halde bakıma muhtaç çocuklarıyla yaşlılık yakasına yapışsın ve ardından samyeli vurup da onu yakıp kavursun ister mi? İşte Allah, belki düşünürsünüz diye mesajları size böyle açıklıyor."},{"n":267,"t":"Siz ey iman edenler! Kazancınızın temiz ve helal olanından ve sizin için topraktan bitirdiğimiz ürünlerden karşılıksız harcayın; fakat, size verildiğinde gözü kapalı olmadıkça el uzatmayacağınız, bayağı ve haram olanı vermeye kalkmayın! Zira iyi bilin ki, Allah (kendi kendine ve tüm varlığa) yetendir, hamdin her türüne layıktır."},{"n":268,"t":"Şeytan sizi fakirlikle korkutur ve size cimriliği telkin eder. Allah ise size katından bir bağış ve daha fazlasını vaad eder. Allah (rahmet ve bağışıyla) sınırsızdır, her şeyi bilendir."},{"n":269,"t":"İsabetli hüküm verme yeteneğini (hak edene) vermeyi diler; ama kime isabetli hüküm verme yeteneği bahşedilmişse, doğrusu ona tarifsiz büyüklükte bir servet bahşedilmiştir; fakat, derin kavrayış sahiplerinden başkası bunu düşünüp kavrayamaz."},{"n":270,"t":"Başkaları için her ne harcama yaparsanız yapın, ya da (bu niyetle) her ne adarsanız adayın Allah onu mutlaka bilir; ama (hayrı engelleyen) zalimler, yardım edecek kimse bulamayacaklar."},{"n":271,"t":"Eğer yardımları açıktan yaparsanız, o da hoş. Yok eğer onu ihtiyaç sahiplerine gizlice verirseniz, işte bu sizin için daha hayırlıdır ve günahlarınızdan bir kısmına keffaret olur. Zira Allah yaptıklarınızın tümünden haberdardır."},{"n":272,"t":"(Ey Peygamber!) İnsanların hidayeti senin elinde değildir; lakin Allah isteyenin hidayetini bilir. Hayır için harcadığınız herhangi bir şey kendi yararınızadır; yeter ki yalnızca Allah`ı kazanmak için harcayın; ve hayır için yapacağınız bir harcama, size tastamam geri dönecek ve siz kesinlikle haksızlığa uğramayacaksınız."},{"n":273,"t":"Kendilerini Allah yolunda vakfettikleri için (ticaret amacıyla) yeryüzünde dolaşamayanlara yardım yapın! İstemekten çekindikleri için, durumlarını bilmeyenler onları zengin zanneder. Onları kimi özelliklerinden tanırsın: (Mesela) insanlardan arsızca istemezler: Her ne iyilik yaparsanız yapın, doğrusu Allah onu kesinlikle bilir."},{"n":274,"t":"Gece ve gündüz, gizli ve açık, servetlerini infak edenler var ya: işte onların karşılığı Rableri katındadır. Onlar geleceğe dair kaygı geçmişe dair hüzün duymayacaklar."},{"n":275,"t":"Faiz yiyen kimseler, başka değil sadece şeytanın dokunarak aklını çeldiği kimse gibi hareket ederler: Çünkü onlar \"Alışveriş de faiz gibidir\" derler. Oysa ki Allah alışverişi helal, faizi haram kılmıştır. Her kim Rabbinden kendisine nasihat gelir gelmez bu işe son verirse, evvelki kazançları ona, onun hakkında karar vermek de Allah`a kalır. Her kim de dönerse, içerisinde kalıcı oldukları ateşe mahkum olanlar işte bunlardır."},{"n":276,"t":"Allah faizin bereketini alır ve (emanete sadakat için) yapılan hayrı (kattığı bereketle) artırır: Allah günahda ısrar eden hiç bir inatçı nankörü sevmez."},{"n":277,"t":"Buna mukabil, bir de iman edip güvenen, ıslah edici iyi işler yapan, namazı istikametle kılan, zekatı gönlünden gelerek veren kimseler var; işte onlar, ödüllerini Rablerinden alacaklar: ve onlar geleceğe dair kaygı, geçmişe dair hüzün duymayacaklar."},{"n":278,"t":"Ey iman edenler! Allah`a karşı sorumluluğunuzun bilincinde olun; ve eğer Allah`a yürekten güveniyorsanız, faizden kaynaklanan kazançların tümünden vazgeçin!"},{"n":279,"t":"Fakat bunu hala yapmıyorsanız, bu durumda Allah ve Rasulü`ne (güvensizlik ilan ederek) azılı bir savaş açmışsınız demektir. Eğer tevbe ederseniz, sermayeniz size aittir: Böylece ne haksızlık yapmış, ne de haksızlığa uğramış olursunuz."},{"n":280,"t":"Şayet (borçlu) güç durumdaysa, rahatlayıncaya kadar ona vade tanıyın! Eğer bilirseniz, (borcu) bağışlamak sizin için çok daha hayırlıdır."},{"n":281,"t":"Öyle bir günün bilincinde olun ki, o günde Allah`a döndürüleceksiniz. Ardından herkese kazandığının karşılığı tastamam ödenecek ve kesinlikle haksızlık edilmeyecek."},{"n":282,"t":"Siz ey iman edenler! Birbirinizle vadeli borçlanmaya girdiğiniz zaman, bunu belgeleyin. Onu, aranızdan adil bir yazıcı kaydetsin! Ve hiçbir yazıcı Allah`ın öğrettiği gibi yazmaktan çekinmesin, yazsın! Borçlu olan taraf borcunu kaydettirsin, Rabbi olan Allah`a karşı sorumluluğunun bilincinde olsun ve borcundan hiçbir şey eksiltmesin! Ve eğer borçlu akli ve bedeni bakımdan yetersizse ya da kendisi kaydettirecek durumda değilse, o zaman onun velisi borcunu adil bir şekilde kaydettirsin! Ve erkeklerinizden iki kişinin şahitliğine başvurun! Eğer iki erkek bulunmazsa, bu durumda doğruluğundan emin olduğunuz kimselerden bir erkekle iki kadını şahit tutun ki ikisinden biri şaşırır, unutur, yanılırsa diğeri ona hatırlatabilsin! Ve şahitler de çağrıldıklarında kaçınmasınlar! Küçük büyük olduğuna bakmaksızın, vadesiyle birlikte yazmaya üşenmeyin: Bu Allah katında daha adil, ispatlama açısından daha güvenilir kuşkuya kapılmamanız açısından daha uygun olandır. Fakat eğer ticari işleminiz aranızda karşılıklı peşin muameleye dayanıyorsa, onu belgelememenizde size herhangi bir vebal yoktur. Birbirinizle alışveriş yapacağınız zaman şahit bulundurun; ancak yazan da şahit de bir zarara uğramasın! Zira eğer zarar verirseniz, işte bu aleyhinize bir çıkış olacaktır. Allah`a karşı sorumluluğunuzun bilincinde olun; zira Allah sizi eğitiyor: zaten her şeyi en iyi bilen de Allah`tır."},{"n":283,"t":"Eğer seyahatteyseniz ve yazan birini de bulamamışsanız, bu durumda alınan bir rehin de yeterlidir. Birbirinize güveniyorsanız, kendisine güvenilen kimse, bu güvenin gereğini yerine getirsin ve Rabbi olan Allah`tan korksun: Artık şahit olduğunuz şeyi gizlemeyin; her kim onu gizlerse, işte onun kalbi günahkar olur: zira Allah yaptıklarınızı çok iyi bilir."},{"n":284,"t":"Göklerde ve yerde olanların tümü Allah`a aittir. Siz içinizdekini açıklasanız da gizleseniz de, Allah sizi ondan dolayı hesaba çekecektir; ve ardından O müstehak olanın bağışlanmasını diler, (cezayı) dileyeni de cezalandırmayı diler. Ve Allah her şeye kadirdir."},{"n":285,"t":"Rasul Rabbinden kendine indirilene önce kendisi iman etti, sonra da mü`minler. Hepsi Allah`a, meleklerine, mesajlarına ve elçilerine inandılar: \"O`nun elçilerinden hiçbiri arasında ayrım yapmayız. İşittik ve itaat ettik; bağışlamanı dileriz ey Rabbimiz: zira varış sanadır!\" dediler."},{"n":286,"t":"Allah hiç kimseye taşıyacağından fazlasını yüklemez. Herkesin kazandığı iyilik kendi lehine, işlediği kötülük de kendi aleyhinedir. Rabbimiz! Unutur ya da yanılırsak, bundan dolayı bizi sorguya çekme! Rabbimiz! Bizden öncekilere yüklediğin gibi bize de ağır yük yükleme! Rabbimiz! Güç yetiremeyeceğimiz yükü bize taşıtma! Günahlarımızı affet, bizi bağışla, bize merhamet et! Sen bizim Mevla`mızsın; Kafirler güruhuna karşı Sen bize yardım et!"}],[{"n":1,"t":"Elif-Lam-Mim!"},{"n":2,"t":"Allah, kendisinden başka tanrı olmayan, mutlak diri, hayatın ve varlığın kaynağı ve dayanağıdır."},{"n":3,"t":"Önceki (vahiy)lerden bugüne ulaşan hakiketleri doğrulayan bu ilahi kelamı sana sapasağlam indiren O`dur; üstelik, Tevrat`ı ve İncil`i de O indirmiştir"},{"n":4,"t":"geçmişte insanlığa yol gösterici olarak, yine hakkı batıldan kesin hatlarla ayıran mesajı da O indirmiştir. Allah`ın mesajlarını inkar eden kemselere gelince: Onlar için şiddetli bir azap vardır; zira Allah üstün ve yüce olandır, insana yaptıklarının acısını tattırandır."},{"n":5,"t":"Kuşku yok, yerde ve göklerde olan hiçbir şey Allah`tan gizli-saklı değildir."},{"n":6,"t":"Rahimlerde size dilediği şekli veren O`dur. O`ndan başka ilah yoktur; O her işinde mükemmel olandır, her hükmünde tam isabet edendir."},{"n":7,"t":"Yine O`dur sana İlahi Kelam`ı indiren. O`nun ayetlerinden bir kısmının hükmü kesin ve nettir; bunlar İlahi Kelam`ın anasıdır. Gerisi de müteşabihlerden oluşmuştur. Kalplerinde yamukluk bulunan kimseler, fitne çıkarmak ve tevil etmek amacıyla, onun müteşabih olan kısmının peşine düşerler. Oysa onun gerçek te`vilini kimse bilmez, yalnızca Allah (bilir); ve ilimde derinleşenler derler ki: \"Biz ona inanırız, tümü Rabbimizin katındandır. Derin kavrayış sahiplerinden başkası bu gerçeği fark edemese de.\""},{"n":8,"t":"\"Rabbimiz! Bizi doğru yola ilettikten sonra kalplerimizi saptırma ve bize katından bir rahmet bahşet: çünkü yalnızca Sensin hiç karşılıksız sınırsızca lutfeden.\""},{"n":9,"t":"\"Rabbimiz! Geleceğinden kuşku duyulmayan o günde Sen insanlığı bir araya toplayacaksın! Çünkü Allah vaadinden asla dönmez.\""},{"n":10,"t":"Küfre saplananlara gelince: ne malları ne de çocukları, onlara Allah`tan gelecek bir azap karşısında hiçbir yarar sağlamaz: işte ateşin yakıtı olanlar da onlardır."},{"n":11,"t":"(Onların gidişatı da) tıpkı Firavun toplumu ve onlardan öncekilerin gidişatı gibi: mesajlarımızı yalanladılar ve Allah da onları günahları nedeniyle (suçüstü) yakalayıverdi: Allah pek şiddetli cezalandırandır."},{"n":12,"t":"İnkarda direnenlere de ki: Yenileceksiniz ve cehenneme sürüleceksiniz: Orası ne fena bir döşektir!"},{"n":13,"t":"Karşı karşıya gelen iki orduda sizin için bir mesaj vardı: Bir ordu Allah yolunda savaşıyor, diğeri ise inkarında direniyordu. Onlar ötekilerin iki misli olduğunu kendi gözleriyle görüyorlardı: Ama Allah dilediğini yardımıyla güçlendirir. İşte bu olayda basiret sahipleri için elbette ibretler vardır."},{"n":14,"t":"Kadınlara, oğullara, altın ve gümüş cinsinden yığılmış servetlere, gözde nişan vurulmuş atlara, sürülere ve ekinlere tutkulu bir sevgi duymak insanoğluna cazip kılındı. Bütün bunlar dünya hayatının geçici zevkleridir, fakat en güzel gelecek Allah katındadır."},{"n":15,"t":"De ki: \"Size, bütün bunlardan daha hayırlısını haber vereyim mi? Sorumluluk bilincine sahip olanlar için, Rableri katında zemininden ırmaklar çağlayan yerleşip kalacakları cennetler, tertemiz eşler ve Allah rızası vardır.\" Allah kulları her haliyle görür;"},{"n":16,"t":"\"Rabbimiz! Kuşkusuz biz iman ettik: Bizi bağışla, günahlarımızı da... Ve bizi ateşin azabından koru!\" diyenleri;"},{"n":17,"t":"(zorluklara) sabredenleri, (imana) sadakat gösterenleri, (Allah`a) boyun eğenleri, (O`nun için) harcayanları, (günahlarından dolayı) seherlerde canı gönülden yalvaranları (da görür)."},{"n":18,"t":"Allah şahittir ki O`ndan başka ilah yoktur; melekler de, adaleti şiar edinen ilim adamları da (şahittirler ki) O`ndan başka ilah yoktur; O her işinde mükemmel olandır, her hükmünde tam isabet edendir."},{"n":19,"t":"Allah katında tek din İslam`dır. Daha önce kendilerine mesaj gönderilenler, başka değil, yalnızca kıskançlıktan dolayı, kendilerine gerçeğin işareti geldiği halde farklı görüşlere saptılar. Kim Allah`ın mesajlarını inkar ederse, iyi bilsin ki Allah hesabı en seri biçimde görendir."},{"n":20,"t":"Şu halde, eğer seninle tartışırlarsa de ki: Ben tüm varlığımla Allah`a teslim oldum, bana uyanlar da... Daha önce kendilerine vahiy emanet edilmiş olanlara ve vahiyden bihaber olanlara \"Siz de tüm varlığınızla teslim oldunuz mu?\" diye sor! Eğer teslim olurlarsa, işte o zaman doğru yolu bulmuş olurlar; yok eğer yüz çevirirlerse, sana düşen yalnızca tebliğ etmektir: Zira Allah kulları her haliyle görür."},{"n":21,"t":"Allah`ın mesajlarını tanımayan, peygamberleri haksız yere öldüren ve insanlara fedakar olmayı öğütleyenlerin kanına girenleri, yürek yakan bir mahrumiyetle müjdele!"},{"n":22,"t":"İşte dünyada ve ahirette yaptıkları iyiliklerin hayrını görmeyecek olan onlardır; onlara yardım eden de olmayacaktır."},{"n":23,"t":"Baksana şu kendilerine daha önce vahiyden bir pay verilenlere? Aralarını bulmak için Allah`ın kitabına çağrıldılar; fakat onlardan bir kısmı döneklik yaparak yüz çevirdiler."},{"n":24,"t":"İşte bu, onların \"Ateş bize bir kaç günden fazla dokunmayacak\" demeleri yüzündendir. Zira uydurmayı gelenek edindikleri şeyler onları inançlarından saptırmıştır."},{"n":25,"t":"Geleceğinde kuşku olmayan bir gün onları bir araya topladığımızda, herkesin yaptığının karşılığı hiç kimseye haksızlık yapılmaksızın eksiksiz olarak ödendiğinde, bakalım (onların hali) nasıl olacak?"},{"n":26,"t":"De ki: \"Ey mutlak iktidar sahibi olan Allah`ım! Sen dilediğine iktidar verir dilediğinden de iktidarı çeker alırsın, dilediğini aziz eder dilediğini de zelil edersin; Senin elindeki mahza hayırdır: Elbette Sen her bir şeye kadirsin."},{"n":27,"t":"Geceyi uzatıp gündüzü kısaltırsın, gündüzü uzatıp geceyi kısaltırsın! Ölüden diriyi çıkarır, diriden de ölüyü çıkarırsın. Ve dilediğin kimseye hesapsız rızık verirsin.\""},{"n":28,"t":"Mü`minler mü`minleri bırakıp da kafirleri (askeri) müttefik edinmesinler. Kim böyle yaparsa Allah`tan bütünüyle kopmuş olur; ancak kendinizi onlara karşı korumak için (bilinçli bir tercihse), o başka: Ne ki Allah, kendisine karşı dikkatli olmanızı ihtar eder; çünkü bütün yollar Allah`a çıkar."},{"n":29,"t":"De ki: \"İçinizdekileri saklasanız da açıklasanız da Allah onu bilir; zira göklerde ve yerde olanların hepsi O`na ayandır: ve Allah her bir şeye kadirdir."},{"n":30,"t":"Her insan, yaptığı bütün iyilikleri de kötülükleri de karşısında bulacağı o günün kendisinden fersah fersah uzak olmasını ister. Ne ki Allah, kendisine karşı dikkatli olmanızı ihtar eder: Zira Allah`ın kullarına şefkati tariflere sığmaz."},{"n":31,"t":"De ki: \"Eğer siz Allah`ı seviyorsanız beni izleyin ki Allah sizi sevsin; ve günahlarınızı bağışlasın! Zira Allah çok bağışlayandır, eşsiz merhamet kaynağıdır."},{"n":32,"t":"De ki: \"Allah`a ve elçisine itaat edin! Yok eğer itaatten yüz çevirirseniz, iyi bilin ki Allah nankörleri sevmez.\""},{"n":33,"t":"Şüphe yok ki Allah Adem`i, Nuh`u, İbrahim ailesini, İmran ailesini kendi çağının insanları içinden seçerek üstün kıldı:"},{"n":34,"t":"Birbirlerinden gelen (aynı inanç üzerinde) tek bir nesil olarak. (Bu bakımdan, peygamberlere inanmada onları birbirinden ayırmayın ve haklarında, ayrıca Allah’ın tercihi konusunda yanlış söz söylemeyin ve yanlış düşüncelere girmeyin). Allah, (her söyleneni) hakkıyla işitendir; her şeyi hakkıyla bilendir."},{"n":35,"t":"Hani İmran`ın kadını demişti ki: \"Rabbim! Karnımdaki çocuğu, (her tür iç ve dış ayartmalardan) özgür olarak sana adadım: Benden kabul buyur! Çünkü sen her şeyi işitensin, her şeyi bilensin."},{"n":36,"t":"Fakat çocuğu doğurunca dedi ki: \"Rabbim! Onu kız doğurdum -Allah onun ne doğurduğunu ve erkeğin kız gibi olamayacağını pekala biliyordu-; ve adını Meryem koydum: İmdi ben onu ve soyunu taşlanmış şeytanın şerrinden sana ısmarlıyorum!\""},{"n":37,"t":"Bunun üzerine Rabbi onu memnuniyetle kabul etti; dahası onu bir çiçek gibi yetiştirdi ve Zekeriyya`nın himayesine verdi. Zekeriyya ne zaman onun bulunduğu bölmeye girse, onun yanında yiyecekler görürdü. (Ve bir gün) sordu. \"Ey Meryem! Bunlar sana nereden geliyor?\" O da cevapladı: \"Bunlar Allah katındandır; Allah dilediği kimseye hesapsız rızık bağışlar.\""},{"n":38,"t":"İşte o anda-orada Zekeriyya Rabbine şöyle dua etti: \"Rabbum! Bana katından güzel bir nesil bağışla; çünkü sen tüm duaları işitensin!\""},{"n":39,"t":"Zekeriyya mihrapta ibadet ederken melekler ona seslendiler: \"Allah sana, Allah`tan gelen kelamı doğrulayıcı bir kelime olan, saygın bir konuma sahip, nefsine hakim, salihlerden bir peygamber olacak Yahya`yı müjdeliyor."},{"n":40,"t":"Cevap verdi: \"Rabbim! Ben bunca yaşlanmış, karım da kısır kalmışken benim nasıl bir oğlum olabilir?\" (Melek) cevap verdi: \"İşte böyledir Allah; dilediğini yapar.\""},{"n":41,"t":"(Zekeriyya) yalvardı: \"Rabbim! Bana bir işaret göster!\" (Allah) buyurdu ki: \"Senin işaretin, insanlarla üç gün boyunca işaret dışında konuşamamandır. (Konuşma yerine) Rabbini çok zikret ve sabah-akşam, gündüz-gece O`nu tesbih et!"},{"n":42,"t":"(Benzer bir olayda farklı bir tavrın mümkün olduğunu da) hatırla! Hani melekler Meryem`e demişlerdi ki: \"Ey Meryem! Allah seni seçti ve tertemiz kıldı; seni bütün dünya kadınlarına tercih etti."},{"n":43,"t":"Ey Meryem! Rabbine huşu ile bağlan, secdeye kapan ve (O`nun huzurunda) eğilenlerle birlikte eğil!\""},{"n":44,"t":"(Ey Nebi!) Sana aktardığımız bu bilgi senin gıyabında olup biten olayların haberlerindendir. İçlerinden hangisi Meryem`i himaye edecek diye kur`a çektiklerinde sen yanlarında değildin; onlar (bu konuda) birbirleriyle tartışırken de yanlarında değildin."},{"n":45,"t":"O zaman melekler demişler di ki: \"Ey Meryem! Allah sana adı Meryem oğlu İsa Mesih olan, dünyada da ahirette de gözde ve (Allah`a) yakınlardan biri olacak kendi katından bir kelimeyi müjdeliyor!"},{"n":46,"t":"O beşikte ve erişkin iken insanlara konuşacak; ve salihlerden biri olacak."},{"n":47,"t":"(Meryem) \"Rabbim!\" dedi, \"bana hiç bir insan dokunmadığı halde benim nasıl çocuğum olabilir?\" (Melek) dedi ki: \"İşte böyledir Allah; dilediğini yapar! Bir işi dilediği zaman ona sadece \"Ol!\" der, o da hemen oluş sürecine girer."},{"n":48,"t":"O, (İsa)ya vahyi ve o vahyi ile doğru hükme varmada kullanılacak yöntemi, Tevrat ve İncil`i öğretecek;"},{"n":49,"t":"üstelik onu İsrailoğullarına elçi yapacaktır; şöyle (diyen bir elçi): \"Ben size Rabbimden bir mesaj getirdim. Size çamurdan kuşa benzer bir maket yapar, ardından ona üflerim, Allah`ın izniyle kuş oluverir. Körleri ve cüzzamlıları iyileştirir, yine Allah`ın izniyle ölüleri hayata döndürürüm. Dahası yiyebileceğiniz ve evlerinizde saklayabileceğiniz şeyleri size haber veririm. Hiç kuşkusuz, eğer gerçekten inanıyorsanız, bütün bunlarda sizin için mucizevi bir mesaj vardır."},{"n":50,"t":"Tevrat`tan bana kadar ulaşanın doğruluğunu tasdik etmek ve size (gelenek yoluyla) yasak edilmiş olan şeyler içerisinden bazılarını helal kılmak için geldim ve size Rabbinizden bir mesaj getirdim: Allah`a karşı sorumluluğunuzu bilin ve bana uyun!"},{"n":51,"t":"Hiç kuşkusuz Allah benim de Rabbim, sizin de Rabbinizdir: artık yalnız O`na kulluk edin, bu dosdoğru yoldur."},{"n":52,"t":"İsa, onlardaki küfrü fark edince sordu: \"Kim Allah`a ulaşan yolda bana yardım eder?\" Havariler dediler ki: \"Allah`ın yardımcıları biziz: Biz Allah`a inandık, Sen de şahit ol ki biz Allah`a teslim olan müslümanlarız!\""},{"n":53,"t":"\"Rabbimiz! İndirdiklerine iman ettik, elçiye de tabi olduk: Bu nedenle bizi (hakikate) şahit olanlarla birlikte yaz!"},{"n":54,"t":"(İnkarcılar İsa`ya) tuzak kurdular; Allah da onların tuzağını başlarına geçirdi: Allah tuzakları bozanların en hayırlısıdır."},{"n":55,"t":"O zaman Allah \"Ey İsa!\" demişti, \"Seni Ben ölüme yollayacağım ve katıma yücelteceğim ve seni küfreden kimselerden arındıracağım; sana uyanları, Kıyamet Gününe kadar (ve o günde) inkar edenlere üstün kılacağım: Sonra hepinizin dönüşü Bana olacak. İşte o zaman anlaşmazlığa düştüğünüz konularda aranızda Ben hüküm vereceğim."},{"n":56,"t":"İnkarında direnenlere gelince: onlara bu dünyada ve ahirette şiddetli azap çektireceğim: kendilerine yardım eden birini de bulamayacaklar.\""},{"n":57,"t":"İnanan ve ıslah edici iyi işler işleyenlere gelince: (Allah) onlara ödüllerini tam olarak verecektir; zira Allah zalimleri asla sevmez."},{"n":58,"t":"Bütün bunlar, sana bildirdiğimiz mesajlardan ve hikmetli haberlerdendir."},{"n":59,"t":"Allah katında İsa`nın durumu Adem`in durumu gibidir. Allah onu toprak türünden yarattı, ardından ona \"Ol!\" dedi; o da oluş sürecine girdi."},{"n":60,"t":"İşte (bu) gerçek sana Rabbin tarafından bildirildi; öyleyse tereddüt edenlerden olma."},{"n":61,"t":"Sana gelen (bu) bilgiden sonra, bu konuda seninle tartışanlara de ki: Gelin, oğullarımızı ve oğullarınızı, kadınlarımızı ve kadınlarınızı, bizimkileri ve sizinkileri çağıralım; sonra canı gönülden yalvaralım ve Allah`ın lanetinin yalan söyleyenler üzerine olmasını dileyelim."},{"n":62,"t":"İşte budur işin hakikati; Allah`tan başka ilah asla yoktur: Hiç kuşku yok ki Allah, evet, yalnızca O`dur her işinde mükemmel, her hükmünde tam isabet sahibi olan."},{"n":63,"t":"Eğer yüz çevirirlerse, unutmasınlar ki, Allah (akideyi) ifsat edenleri çok iyi bilir."},{"n":64,"t":"De ki: \"Ey kitap ehli! Sizinle aramızdaki şu ortak ilkeye gelin: Allah`tan başkasına kulluk etmeyeceğiz, O`ndan başka hiçbir şeye ilahlık yakıştırmayacağız, Allah`ın yanı sıra başka birilerini rabler olarak kabul etmeyeceğiz! Ve eğer yüz çevirirlerse o zaman deyiniz ki: Şahid olun ki biz, kesinlikle O`na teslim olduk."},{"n":65,"t":"Ey kitap ehli! Neden İbrahim hakkında tartışıp duruyorsunuz? Oysa ki Tevrat da, İncil de ondan sonra indirildi. Akletmiyor musunuz?"},{"n":66,"t":"Hadi şu bildiğiniz şeylerde tartıştınız, fakat bilmediğiniz şey hakkında niçin tartışırsınız? Halbuki Allah bilir, fakat siz bilemez siniz:"},{"n":67,"t":"İbrahim ne Yahudi ne de Hıristiyandı, fakat tam anlamıyla Hakka yönelmiş bir müslümandı; Allah`a şirk koşanlardan da değildi."},{"n":68,"t":"Gerçekte İbrahim`e en yakın olanlar ona uyanlardır; yani, işte bu peygamber ve iman edenlerdir: şu da var ki Allah inananların tümüne yakındır."},{"n":69,"t":"Önceki vahiylerin takipçilerinden kimileri sizi aldatmak isterler; fakat onlar kendilerinden başkasını aldatmış olmazlar, üstelik bunun farkına da varmazlar."},{"n":70,"t":"Ey önceki vahyin mensupları! Bizzat kendiniz şahit olup dururken Allah`ın mesajlarını neden inkar ediyorsunuz?"},{"n":71,"t":"Ey önceki vahyin mensupları! Niçin hakka batıl elbisesi giydirip de bildiğiniz halde hakikati gizliyorsunuz?"},{"n":72,"t":"Önceki vahyin mensuplarından bir gurup dedi ki: \"İman edenlere indirilen vahye günün başında inandığınızı söyleyin, o günün sonunda inkar edin; bu sayede belki (imanlarından) dönerler;"},{"n":73,"t":"fakat sizin dininize uymayan kimseye asla (yürekten) inanmayın!\" (Şu hakikati) ilan et: \"Doğru rehberlik sadece Allah`ın rehberliğidir; size verilenin bir benzerinin başka birine de verilmesi (zorunuza mı gitti), yoksa Rabbinizin huzurunda aleyhinize delil getirirler diye mi (korkuyorsunuz)? (Şunu da) ekle: \"Lütuf ve ihsan Allah`ın elindedir, onu dilediğine bahşeder; zira Allah (lutfunda) sınırsız olandır, her şeyi bilendir:"},{"n":74,"t":"Dilediğine rahmetini bağışlar: zaten Allah muazzam lütuf sahibidir."},{"n":75,"t":"Önceki vahyin mensuplarından öyleleri var ki, kendisine bir hazine emanet etsen (kuruşuna dokunmadan) iade eder; öyleleri de var ki, tek bir dinar emanet etsen tepesine dikilmedikçe sana geri vermez. Bu, onların, \"Bizden olmayanlara yaptıklarımızdan dolayı bir şey lazım gelmez\" şeklindeki iddiaları yüzündendir. Fakat onlar bile bile Allah hakkında yalan söylüyorlar."},{"n":76,"t":"Bilakis, kim taahhütlerine sadık kalır ve sorumluluk bilinci taşırsa, iyi bilsin ki Allah sorumluluk bilinciyle hareket edenleri sever."},{"n":77,"t":"Allah`a karşı taahhütlerini ve yeminlerini az bir pahaya satanlar var ya: onların ahirette payı olmayacak, Allah onlarla konuşmayacak, kıyamet günü Allah onların yüzüne bakmayacak ve arındırmayacak onları: nihayet onları acıklı bir azap bekleyecek."},{"n":78,"t":"Yine onlardan öylesi de var ki, Kitap`tan olmadığı halde ona ait olduğunu sanasınız diye dillerini eğip bükerek Kitabı çarpıtırlar ve o Allah katından olmadığı halde \"Bu Allah katındandır\" derler: sonuçta onlar bile bile Allah`a iftira etmiş olurlar."},{"n":79,"t":"Allah`ın kendisine vahiy, hüküm ve peygamberlik verdiği hiç kimsenin, bunun ardı sıra topluma \"Allah`ın peşi sıra bana da kulluk edin!\" demesi düşünülemez. Aksine \"İlahi kelamı derinliğine öğrenip onu başkalarına da öğreterek Rabbin şahsiyetler olun!\" der."},{"n":80,"t":"Yine O, melekleri ve peygamberleri rabler edinmenizi emretmez; siz Allah`a kayıtsız şartsız teslim olduktan sonra, o size inkarı emreder mi hiç?"},{"n":81,"t":"Allah peygamber (aracılığıyla kitap ehlin)den; \"Eğer vahiyden ve hikmetten size bir pay verdikten sonra size hakikatten yanınızda kalanı tasdik eden bir elçi gelirse, kesinlikle ona inanmalı ve yardım etmelisiniz\" taahhüdünü aldığı zaman sordu: \"İşte bu şarta dayalı ahdimi alıp kabul ettiniz mi?\" \"Kabul ve tasdik ettik!\" diye cevap verdiler. Allah buyurdu: \"O halde şahid olun! Ben de sizinle birlikte şahitler arasında olacağım!\""},{"n":82,"t":"O halde her kim bundan sonra yüz çevirirse, işte onlar yoldan çıkmış olanların ta kendileridir."},{"n":83,"t":"Yoksa onlar, Allah`ın dininden gayrı (bir inanç sistemi) mi arıyorlar? Oysa ki bütün göktekiler ve yerdekiler ister istemez O`na teslim oldular: Çünkü hepsi (sonunda) O`na varacaklar."},{"n":84,"t":"De ki: \"Allah`a, bizi indirilene, İbrahim`e, İsmail`e, İshak`a, Yakub`a ve onun neslinden gelenlere indirilene; Rablerinden Musa`ya, İsa`ya ve (diğer) tüm peygamberlere bahşedilene inanırız; onlar arasından hiç birini ayırt etmeyiz; ve biz yalnız O`na teslim oluruz."},{"n":85,"t":"Her kim kendisine Allah`a kayıtsız şartsız teslimiyet yolundan başka bir din ararsa, bu kendisinden asla kabul edilmeyecektir; üstelik o ahirette de kaybedenlerden olacaktır."},{"n":86,"t":"İman ettikten, Elçi`nin hak olduğuna şahit olduktan, kendilerine hakikatin apaçık belgeleri geldikten sonra inkara sapan bir toplumu Allah nasıl muvaffak eder? Çünkü Allah, zulme gömülen bir topluma asla rehberliğini bahşetmez."},{"n":87,"t":"Onların karşılığı, Allah`ın, meleklerin ve tüm insanların lanetine uğramak olacaktır:"},{"n":88,"t":"Onlar bu halde kalacaklar; ne azapları hafifletilecek ne de onlara süre tanınacaktır."},{"n":89,"t":"Ama tevbe edenler ve durumlarını düzeltenler hariç; çünkü Allah`ın bağışı da, merhameti de tariflere sığmaz."},{"n":90,"t":"İman etmelerinin ardından inkara sapıp, sonra da inkarda ileri gidenlere gelince: Onların tevbesi kabul olunmayacaktır; işte asıl sapıklar onlardır."},{"n":91,"t":"İnkarda direnenler ve inkara saplanmış halde ölen kimselere gelince: Yeryüzünün bütün hazinelerini verseler bile, onlardan kurtuluş akçesi kabul edilmeyecektir: işte onlar içindir acıklı azap ve onlara yardım eden de çıkmayacaktır."},{"n":92,"t":"Sevdiğiniz şeylerden infak etmedikçe fazilete ulaşamazsınız; zaten ne infak ederseniz edin, kesinlikle Allah onu ayrıntısıyla bilir."},{"n":93,"t":"Tevrat indirilmeden önce İsrail(oğullarının) kendisine haram kıldığı şeyler dışında bütün yiyecekler İsrailoğullarına helal idi. De ki: \"Hadi, eğer sözünüzün eriyseniz, getirin Tevrat`ı da onu gösterin!\""},{"n":94,"t":"Ve her kim bundan böyle Allah`a iftira atarsa, işte kendilerine zulmedenler onlardır."},{"n":95,"t":"De ki: \"Allah haklıdır: Şu halde, yalnız Hakka yönelen ve müşriklerden de olmayan İbrahim`in inanç sistemine uyun!"},{"n":96,"t":"Zira insanlık için inşa edilen ilk mabet, Bekke`deki bereketli ve bütün toplumlar için hidayet merkezi olan mabet idi."},{"n":97,"t":"Buna delalet eden işaretler hala orada duruyor; orası İbrahim`in makamıdır: oraya giren herkes emin olur. Ve ona ulaşmaya gücü yeten herkesin mabedi haccetmesi, Allah`ın insanlık üzerindeki hakkıdır. Kim de nankörlük ederse, iyi bilsin ki Allah hiç bir varlığa muhtaç değildir."},{"n":98,"t":"De ki: \"Ey önceki vahyin takipçileri! Allah yaptıklarınıza şahid olup dururken, niçin Allah`ın ayetlerini reddediyorsunuz?"},{"n":99,"t":"De ki: \"Ey önceki vahyin takipçileri! Doğru olduğuna bizzat şahit olduğunuz halde, onu eğri göstermeye çalışarak, iman edenleri niçin Allah yolundan döndürmeye çabalıyorsunuz? Ama Allah yaptıklarınızdan asla gafil değildir."},{"n":100,"t":"Siz ey (bu vahye) iman edenler! Kendilerine kitap verilenlerden bir fırkaya uyarsanız, sizi imanınızdan sonra yeniden inkara döndürürler."},{"n":101,"t":"(Onlar böyle yapabilirler), ama siz nasıl olur da Allah`ın ayetleri size okunup dururken ve O`nun elçisi aranızdayken inkara yeltenebilirsiniz? Ne var ki Allah`a sımsıkı yapışan, dosdoğru bir yola yöneltilmiş demektir."},{"n":102,"t":"Ey (bu vahye) iman edenler! Allah`a karşı sorumluluğunuzun gereğini hakkıyla yerine getirin! Ve (Allah`a) tam teslim olmadan can verecekseniz, sakın ölmeyin!"},{"n":103,"t":"Hep birlikte Allah`ın ipine sımsıkı yapışın ve birbirinizden ayrılmayın! Ve Allah`ın üzerinizdeki nimetini hatırlayın: Hani siz birbirinize düşman iken kalplerinizin arasını uzlaştırdı da, O`nun lutfu sayesinde kardeşler oldunuz; ve siz ateşten bir çukurun kenarındaydınız da, sizi oradan kurtardı! İşte bu şekilde Allah size mesajlarını açıklar ki doğruyu bulasınız."},{"n":104,"t":"Öyleyse sizler hayra çağıran, meşru ve iyi olanı öneren, kötü ve yanlış olandan da sakındıran, (ümmet olmanın gereğini yapan) bir ümmet olun! İşte onlardır ebedi saadete erecek olanlar."},{"n":105,"t":"Kendilerine hakikatin apaçık belgeleri geldikten sonra parçalanıp birbirine düşen kimseler gibi olmayın; işte bunlar için korkunç bir azap vardır;"},{"n":106,"t":"bazı yüzlerin ağarıp bazı yüzlerin karardığı o günde, yüzü kara çıkanlara (denilecek ki): \"İmana erdikten sonra inkara saptınız ha? O halde, inkarınızdan dolayı tadın azabı!\""},{"n":107,"t":"Fakat yüzü ağaranlar Allah`ın rahmetine dalacaklar; onlar o rahmette ebediyyen kalacaklar."},{"n":108,"t":"Bütün bunlar Allah`ın mesajlarıdır. Bunları belli bir amaç uğruna sana bildiriyoruz; zira Allah hiçbir varlığın haksızlığa uğramasını dilemez."},{"n":109,"t":"Göklerdeki ve yerdeki her şey Allah`a aittir; ve tüm iş ve oluş sonunda Allah`a döner."},{"n":110,"t":"Siz, insanlık adına çıkarılmış en hayırlı ümmetsiniz; iyi ve doğru olanı teklif eder, kötü ve yanlış olandan sakındırırsınız; zira Allah`a güvenip inanırsınız. Eğer kitap ehli de güvenip inansaydı, haklarında hayırlı olurdu. Onlardan (Allah`a) güvenip inananlar varsa da, çoğunluğu yoldan çıkmıştır:"},{"n":111,"t":"onlar size, geçici eziyet vermenin dışında, kalıcı hiç bir zarar veremezler; sizinle savaşacak olsalar arkalarını dönüp kaçarlar: Sonra onlara yardım da ulaşmaz."},{"n":112,"t":"Onlar Allah`a ve insanlığa karşı taahhütlerine yapışmadıkları sürece, nerede olurlarsa olsunlar zillete mahkumdurlar. Zira Allah`ın gazabına uğramış, üzerlerine zillet ve miskinlik damgası vurulmuştur. Bütün bunların nedeni, Allah`ın ayetlerini inkar etmeleri ve peygamberleri haksız yere öldürmeleridir. Bunlarsa, isyankar olmaları ve ısrarla taşkınlıkta bulunmaları yüzündendir."},{"n":113,"t":"Onların hepsi bir değildir; önceki vahyin takipçilerinden, gece boyunca Allah`ın ayetlerini okuyup secdeye kapanan onurlu bir topluluk da vardır."},{"n":114,"t":"Onlar Allah`a ve ahiret gününe inanırlar, iyi ve doğru olanı teklif eder kötü ve yanlış olandan sakındırırlar; ve hayırlı işlerde birbirleriyle yarışırlar: işte bunlar aktif iyi olanlardır."},{"n":115,"t":"Onların yaptığı hiç bir iyilik zayi olmayacaktır: çünkü Allah sorumlu davrananları çok iyi bilir."},{"n":116,"t":"Küfre saplananlara gelince: Onları ne malları ne de çocukları Allah`a karşı koruyabilir. İşte onlar ateş yaranıdır; onlar orada ebedi kalıcıdır."},{"n":117,"t":"Onların bu dünya hayatı için harcadıkları, kendi kendilerine zulmeden bir toplumun ekinlerine musallat olan ve onu mahveden dondurucu bir kasırgaya benzer: Onlara zulmeden Allah değildir, asıl onlar kendi kendilerine zulmetmektedir."},{"n":118,"t":"Siz ey iman edenler! Sizden olmayanları sırdaş edinip içinize almayınız. Onlar size zarar vermek için hiç bir çabadan geri durmazlar; dahası sizi zora sokan her şey hoşlarına gider. Kinleri ağızlarından taşmaktadır; kalplerinde sakladıkları ise daha beter. Biz (buna ilişkin) işaretleri sizin için (işte böyle) açık ve anlaşılır kıldık; tabi ki eğer aklınızı kullanırsanız."},{"n":119,"t":"Hadi siz onları sevip bağrınıza bastınız; ama onlar, (kendilerine indirilen de dahil) vahyin tümüne inandığınız halde sizi sevmezler. Ve sizinle karşılaştıklarında \"Biz de inandık\" derler, fakat yalnız kalınca size olan kinlerinden dolayı parmaklarına diş geçirirler. De ki: Kininizle geberin! Allah, göğüslerin en mahrem sırlarını bilendir."},{"n":120,"t":"Eğer siz bir iyiliğe ulaşırsanız buna üzüleverirler; yok eğer başınıza bir kötülük gelirse buna da sevinirler. Ama eğer zorluklara direnir ve sorumluluk bilincini kuşanırsanız, onların tuzakları size hiç bir zarar veremez: Zira Allah, yaptıkları her şeyi çepeçevre kuşatandır."},{"n":121,"t":"Hani, sabahleyin mü`minleri savaş düzenine sokmak için evinden çıkmıştın. Allah da tarifsiz bir biçimde her şeyi duyuyordu, her şeyi biliyordu."},{"n":122,"t":"İçinizdeki iki grubun -Allah onların velisi olduğu halde- paniğe kapıldığını da (biliyordu). Artık mü`minler yalnız Allah`a güvenmeliler."},{"n":123,"t":"Nitekim siz oldukça zayıf bir haldeyken, Allah size Bedir`de de yardım etmişti. O halde, Allah`a karşı sorumluluğunuzun bilincinde olun ki, şükredenlerden olasınız!"},{"n":124,"t":"Hani sen inananlara demiştin ki: \"Gönderilmiş üç bin melekle Rabbinizin imdadınıza yetişecek olması sizin için yeterli değil mi?\""},{"n":125,"t":"Kesinlikle evet! Ama siz zorluklara direnir ve sorumluluk bilincini kuşanırsanız, düşman ansızın size saldırdığında Rabbiniz size anlı-şanlı beş bin melekle yardım edecektir."},{"n":126,"t":"Allah bunu, sadece size bir müjde olsun ve gönlünüz onunla ferahlasın diye (vaad) etti; zira (zafer garantili) yardım, yalnızca her işinde mükemmel olan, her hükmünde tam isabet kaydeden Allah katından gelir"},{"n":127,"t":"ki, küfre saplanan kimselerden bir kısmını tamamen mahvetsin ya da alçaltsın; sonunda umutsuzluğa kapılarak geri çekilsinler."},{"n":128,"t":"İlahi emrin gerçekleşmesine dair senin elinde hiçbir yetki yoktur; dolayısıyla onların tevbelerini kabule ya da onları cezalandırmaya karar vermek de (sana düşmez); çünkü onlar zalimlerin ta kendileridir."},{"n":129,"t":"Oysa, göklerdeki ve yeryüzündeki her şey Allah`a aittir; dilediğini bağışlar, dilediğini cezalandırır; fakat Allah`ın affı da, rahmeti de tarifsizdir."},{"n":130,"t":"Siz ey iman edenler! Faizi kat kat artırarak boğazınıza geçirmeyin; sorumluluk bilincini kuşanın ki mutluluğa erebilesiniz!"},{"n":131,"t":"Bir de inkar edenler için hazırlanmış olan ateşten sakının!"},{"n":132,"t":"Allah`a ve elçisine de tabi olun ki, rahmete mazhar olasınız!"},{"n":133,"t":"Rabbinizin mağfiretine ermek ve muttakiler için hazırlanmış gökler ve yeryüzü genişliğinde olan cenneti kazanmak için birbirinizle yarışın!"},{"n":134,"t":"Onlar ki bollukta da darlıkta da infak ederler; öfkelerini kontrol altında tutarlar ve insanların hatalarını bağışlarlar; zira Allah iyilik edenleri sever."},{"n":135,"t":"Yine onlar, utanç verici bir iş yaptıkları ya da kendi kendilerine bir kötülük ettikleri zaman, Allah`ı hatırlayıp hemen günahları için istiğfar ederler; zira Allah`tan başka günahları kim bağışlayabilir ki? Üstelik onlar, yaptıkları kötülük üzerinde bile bile ısrar da etmezler."},{"n":136,"t":"İşte bunların ödülü, Rablerinden bir mağfiret ve orada yerleşip kalacakları zemininden ırmaklar çağlayan cennet olacaktır: çalışıp çabalayanlar için ne muhteşem bir ödüldür bu."},{"n":137,"t":"Sizden önce de nice hayat tarzları gelip geçti. Öyleyse gezin yeryüzünü ve hakikati yalanlayanların sonunun nasıl olduğunu görün!"},{"n":138,"t":"Bu, bütün insanlığa iletilmiş tarifsiz bir bildiridir ve sorumluluk bilincini kuşananlar için de bir rehber ve öğüttür."},{"n":139,"t":"Öyleyse ne yılgınlığa kapılın ne de üzülün: eğer gerçekten inanıyorsanız, insanların en üstünü mutlaka siz olursunuz."},{"n":140,"t":"Eğer size bir zarar dokunduysa, elbet benzer bir zarar (başka) insanlara da dokundu. Zira o (iyi ve kötü) dönemleri biz insanlar arasında döndürür dururuz ki, Allah iman eden kimseleri seçip ayırsın ve sizden hakikate şahit olanları tesbit etsin; çünkü Allah zalimleri sevmez;"},{"n":141,"t":"yine Allah, iman edenleri arındırıp üste çıkarsın ve inkarcıları da mahvetsin."},{"n":142,"t":"Ya yoksa siz, Allah içinizden cihad edenleri ve (yolunda) direnenleri seçip ayırmadan cennete girebileceğinizi mi sanıyorsunuz?"},{"n":143,"t":"Nitekim siz, ölümle yüz yüze gelmeden önce (Allah yolunda) can vermeyi arzuluyordunuz; işte şimdi onu gösterdiğimiz halde seyirci kalan da (yine) siz oluyorsunuz."},{"n":144,"t":"Muhammed yalnızca bir elçidir; ondan önce de elçiler gelip geçmiştir. O halde o ölür ya da öldürülürse, topuklarınız üzerinde geriye mi döneceksiniz? Fakat kim topukları üzerinde geriye dönerse, iyi bilsin ki Allah`a hiç bir zarar veremez; halbuki Allah şükredenlerin karşılığını verecektir."},{"n":145,"t":"Hiç kimse, Allah`ın izniyle ilahi yasa ile kararlaştırılmış vade dışında ölmez. Ve kim bu dünyanın nimetlerini isterse kendisine ondan veririz, kim de ahiretin nimetlerini isterse ona da ondan veririz; ve Biz, şükredenleri ödüllendiririz."},{"n":146,"t":"Ve nice peygamber, yanındaki Rabbe adanmış bir çok insanla birlikte savaşma durumunda kaldı. Onlar Allah yolunda başlarına gelenlerden dolayı ne yılgınlığa kapıldılar, ne acziyet gösterdiler, ne de baş eğdiler: zira Allah direnenleri sever."},{"n":147,"t":"Onların söylediği yalnızca şuydu: \"Rabbimiz! Günahlarımızı ve haddi aşan tavırlarımızı bağışla! Bizi sabit kadem kıl ve kafir topluma karşı bize yardım et!\""},{"n":148,"t":"Bunun ardından Allah onlara, hem bu dünya nimetlerini hem de ahiret nimetlerinin en güzelini bahşetti: Allah kendisini görüyormuş gibi kulluk edenleri sever."},{"n":149,"t":"Siz ey iman edenler! Eğer küfre saplananlara uyarsanız, sizi ökçelerinizin üzerine gerisin geri döndürürler; asıl işte o zaman kaybedenlerden olursunuz."},{"n":150,"t":"Hayır! Sizin Mevlanız yalnızca Allah`tır; O`dur yardıma koşanların en hayırlısı."},{"n":151,"t":"Hiçbir delile dayanmadan Allah`a şirk koşmalarından dolayı kafirlerin yüreklerine korku salacağız. Nitekim onların son durağı ateştir: ne berbattır zalimlerin meskeni!"},{"n":152,"t":"Ve doğrusu Allah size verdiği sözü tuttu; hatırlayın ki O`nun izni sayesinde köklerini kazıyordunuz; ne ki arzuladığınız zaferi Allah size gösterdikten sonra gevşeyip (Peygamber`in) emri konusunda tartıştınız ve itaatsizlik ettiniz. İçinde dünyaya özlem duyanlar olduğu gibi, ahirete özlem duyanlar da vardı. Bunun üzerine Allah, sizi sınamak için düşmanlarınızı yenmenize mani oldu. Fakat O (şimdi) sizi bağışladı; zaten Allah inananlara karşı çok lütufkardır."},{"n":153,"t":"O zaman siz, kimseye bakmadan tepelere doğru kaçışıyor, Peygamber de arkanızdan sizi çağırıyordu. İşte bu yüzden, (Peygamber`in) elemine karşılık (Allah) size öyle bir elem verdi ki, ne kaçırdığınız fırsata ne de başınıza gelene üzülmeye fırsatınız olmadı: zira Allah yaptıklarınızdan tümüyle haberdardı."},{"n":154,"t":"Sonra (Allah), bu elemin ardından size bir güven hissi, bir kısmınızı çepeçevre kuşatan bir dinginlik bahşetti. Diğer bir kısmınız ise canlarının derdine düşmüşlerdi; Allah hakkında, haddini bilmezlik çağına özgü, yanlış tasavvurlara kapıldılar. Diyorlardı ki: \"Bizim, mutlak hükümranlıkta bir karar yetkimiz var da (kullanmadık) mı sankı?\" De ki: \"Bütün yetki, yalnızca Allah`a aittir.\" Onlar ise içlerinde gizleyip sana göstermedikleri gerçek duygularını (şöyle) dile getiriyorlardı: \"Eğer karar yetkisi bizde olsaydı, burada bu kadar ölü vermezdik.\" de ki: \"Evlerinizde kalmış olsaydınız dahi, ölümü mukadder olanlarınızı, o ölüm, elbet yataklarına kadar kovalardı.\" Bu da, Allah`ın göğüslerinizde olan her bir şeyi sınaması ve kalplerinizde olanları arıtıp damıtması içindir: zira Allah kalplerin içini bilir."},{"n":155,"t":"İki ordunun karşılaştığı gün, içinizden kaçanlara gelince: birtakım eylemleri sebebiyle şeytan onların ayağını kaydırdı. Fakat (şimdi) Allah onların günahlarını sildi: çünkü Allah tarifsiz bir bağışlayandır, acele cezalandırmayandır."},{"n":156,"t":"Siz ey iman edenler! İnkara saplanıp da, yeryüzünde sefere çıkan ya da gazaya katılan kardeşleri için \"Bizimle kalmış olsalardı ölmeyecekler ya da öldürülmeyeceklerdi\" diyenler gibi olmayın! Zira Allah bunu, onların içine bir yürek yarası yapacaktır. Çünkü hayatı ve ölümü yaratan Allah`tır: ve Allah yaptığınız her şeyi görmektedir."},{"n":157,"t":"Ve eğer Allah yolunda öldürülür ya da ölürseniz, Allah`tan gelecek rahmet ve mağfiret, onların yığabilecekleri tüm dünyalıklardan daha hayırlıdır."},{"n":158,"t":"Zira ölseniz de öldürülseniz de, sonunda Allah katında toplanacaksınız."},{"n":159,"t":"Allah`ın rahmeti sayesinde sen onlara yumuşak davrandın. Ama eğer onlara karşı katı yürekli davransaydın, kesinlikle senden uzaklaşırlardı: Şu halde onları affet, affedilmeleri için de dua et ve yönetim işinde onlarla istişare(ye devam) et! Artık kararını verdiğin zaman da, Allah`a güven! Çünkü Allah kendisine güvenenleri sever."},{"n":160,"t":"Allah yardım ederse size, artık yenemez sizi hiç kimse; ama eğer sizi terk ederse, ondan sonra kim yardım eder size? Şu halde mü`minler, yalnızca Allah`a güvensinler."},{"n":161,"t":"Bir peygamberin hile yapması düşünülemez. Zira kim hile yaparsa, kıyamet günü hilesi açığa çıkarılacaktır. Sonunda herkes, yaptıklarının karşılığını eksiksiz alacak ve hiç kimseye haksızlık edilmeyecektir."},{"n":162,"t":"Öyleyse, Allah`ın rızasını gözeten kişiyle Allah`ın hışmına uğrayan ve varacağı yer cehennem olan kişi bir olur mu? Orası ne kötü son duraktır!"},{"n":163,"t":"Onlar Allah katında farklı konumlara sahiptir: zira Allah yaptıkları her şeyi görmektedir."},{"n":164,"t":"Doğrusu Allah, ayetlerini onlara okumak, onları arındırmak, ilahi kelamı ve hikmeti onlara öğretmek için içlerinden bir elçi çıkararak mü`minlere ihsanda bulunmuştur; oysa ki daha önce apaçık bir sapıklık içerisinde bulunuyorlardı."},{"n":165,"t":"Onları iki kat musibete uğrattıktan hemen sonra, o musibet sizin başınıza da geldi diye \"Bu başımıza nereden geldi?\" diye soruyorsunuz, öyle mi? De ki: \"Sizin kendi yüzünüzden!\" Hiç kuşku yok ki Allah, dilediği her şeyi yapmaya kadirdir."},{"n":166,"t":"İki ordunun karşılaştığı gün başınıza gelenler Allah`ın izni sonucunda gerçekleşmişti. Bu da (Allah`ın) mü`minleri belirlemesi içindi."},{"n":167,"t":"Yine, ikiyüzlülük yapıp da kendilerine \"Gelin, Allah yolunda savaşın!\", dahası \"Kendinizi savunun!\" denildiğinde, \"Eğer savaş (çıkacağın)ı bilseydik kesinlikle arkanızdan gelirdik\" diye cevap verenleri belirlemek içindi. Onlar o gün, kalplerinde olmayanı ağızlarıyla söyleyerek inkara imandan daha fazla yaklaştılar. Oysa ki Allah onların gizledikleri şeyi çok iyi biliyordu;"},{"n":168,"t":"kendileri evlerinde oturdukları halde, kardeşleri hakkında şöyle dediklerini: \"Eğer bize uysalardı, öldürülmüş olmayacaklardı\". De ki: \"Hadi eğer sözünüzün arkasında duruyorsanız, başınızdan savın bakalım ölümü?\""},{"n":169,"t":"Ve Allah yolunda öldürülenleri ölü saymayın! Aksine onlar diridirler; rızıkları Allah katındadır."},{"n":170,"t":"Onlar Allah`ın lutfundan kendilerine bağışladığıyla kıvanç duyarlar. Arkadan gelip de henüz kendilerine kavuşmamış olanlara, geleceğe ilişkin kaygı ve geçmişe ilişkin üzüntü duymayacakları müjdesini vermekten haz alırlar."},{"n":171,"t":"Onlar, Allah`ın nimeti ve keremiyle, Allah`ın mü`minlere ait ecri zayi etmeyeceğini müjdelemeye can atarlar."},{"n":172,"t":"Onlar ki, kendilerine dokunan zarardan sonra Allah`ın ve Elçisi`nin çağrısına uydular; bunlardan iyilikte sebat gösterenleri ve sorumluluk bilincini kuşananları muazzam bir karşılık beklemektedir."},{"n":173,"t":"Onlar ki, malum insanlar kendilerine \"Bakın, düşmanlarınız size saldırı için toplandı, onlardan korkun!\" demişlerdi de, işte bu onların imanını artırmış ve şöyle cevap vermişlerdi: \"Allah bize yeter, O ne güzel vekildir!\""},{"n":174,"t":"Onlar, Allah`ın nimeti ve lütfu sayesinde kendilerine hiç bir zarar dokunmadan geri döndüler. Zira onlar Allah`ın rızasına taliptiler: zira Allah sınırsız lütuf sahibidir."},{"n":175,"t":"Başkası değil, işte o şeytandır kendi dostlarıyla (sizi) korkutan. O halde onlardan korkmayın, sadece benden korkun, gerçekten inanıyorsanız eğer."},{"n":176,"t":"İnkarda birbirleriyle yarış halinde olanlardan dolayı üzülme! Unutma ki onlar Allah`a hiç bir zarar veremezler; Allah onların ahiretten hiç bir pay almamalarını murad eder. Ve onları konkunç bir azap bekler."},{"n":177,"t":"İman karşılığında inkarı satın alanlar, Allah`a hiç bir zarar veremezler; onları da acıklı bir azap bekler."},{"n":178,"t":"Ve inkarda direnenler sanmasınlar ki, onlara mühlet vermemiz kendi hayırlarınadır. Onlara yalnızca günahlarını artırsınlar diye mühlet verdik; sonunda alçaltıcı bir azap onları bekler."},{"n":179,"t":"(Ey Kafirler!) Allah, mü`minleri, sizin yaşadığınız hayat tarzı üzere bırakacak değildir; nihayet Allah iyiyi kötüden ayıracaktır. Allah gaybı size bildirecek de değildir; fakat Allah (bu amaçla) elçilerinden dilediğini seçer. Şu halde Allah`a ve elçilerine inanın; zira eğer iman eder ve sorumluluk bilincini kuşanırsanız, işte o zaman sizi muazzam bir karşılık bekler."},{"n":180,"t":"Allah`ın lutfundan kendilerine verdiklerinde cimrilik yapanlar, bunun kendileri için hayırlı olduğunu sanmasınlar! Aksine bu onlar için pek fenadır. Cimrilik yaptıkları şeyler kıyamet gününde boyunlarına dolanacaktır. Zira göklerin ve yeryüzünün mirası tamamıyla Allah`a aittir. Ve Allah yaptığınız her şeyden haberdardır."},{"n":181,"t":"\"Allah fakirdir fakat biz zenginiz!\" diyenlerin laflarını Allah duymuştur. Onların hem söylediklerini, hem de peygamberleri haksız yere öldürmelerini kaydedeceğiz ve diyeceğiz ki: \"Tadın yakıp kavuran azabı!"},{"n":182,"t":"Bu, kendi ellerinizle yaptıklarınızın karşılığıdır. Unutmayın ki Allah`ın kullarına zulmetme ihtimali bulunmamaktadır!\""},{"n":183,"t":"\"Allah, yakılarak sunulan bir kurban getirmedikçe hiçbir elçiye inanmamamızı emretmişti\" diyenlere gelince: De ki: \"Benden önce de size peygamberler gelmiş, hem hakikatin apaçık belgelerini hem de sözünü ettiğiniz şeyi getirmişlerdi. Peki, madem doğru söylüyordunuz da niçin onları öldürdünüz?\""},{"n":184,"t":"Ve seni yalancılıkla suçladılarsa; unutma ki senden önce hakikatin apaçık delilleriyle, ilahi hikmet yüklü kitaplarla ve aydınlık saçan vahiyle gelen peygamberler de yalancılıkla suçlanmıştı."},{"n":185,"t":"Her can ölümü tadar. Ve kıyamet gününde, karşılıklarınız size tam olarak ödenir. Ve kim ateşten uzaklaştırılır da cennete alınırsa, işte o murada ermiş olur. Bu dünya hayatıysa, aldatıcı bir tatmin aracından başka bir şey değildir."},{"n":186,"t":"Elbette mallarınızla ve canlarınızla sınanacaksınız; ve hem sizden önce vahye muhatap olanlardan, hem de Allah`tan başkasına ilahlık yakıştıranlardan birçok incitici söz işiteceksiniz. Ama, eğer direnir ve sorumluluk bilincini kuşanırsanız (iyi olur); fakat unutmayın ki bu bir azim işidir."},{"n":187,"t":"Allah, (daha önceden) vahye muhatap olanlardan \"Onu insanlara açıklayacaksınız ve kesinlikle gizlemeyeceksiniz\" diye söz almıştı. Fakat onlar bunu kulak ardı ettiler ve değersiz bir menfaat karşılığı pazarladılar: ne kötü bir alışverişti bu!"},{"n":188,"t":"Sanma ki yaptıkları (bu tür) işlerle sevinen ve yapmadıklarıyla övülmekten hoşlananlar, evet onlar, sanma ki azaptan kurtulabilecekler: Onları şiddetli bir azap beklemektedir."},{"n":189,"t":"Göklerde de yeryüzünde de hükümranlık Allah`a aittir: zira Allah her şeyi yapmaya kadirdir."},{"n":190,"t":"Kuşkusuz göklerin ve yeryüzünün yaratılışında, gece ile gündüzün birbirini izlemesinde derin bir kavrayış sahipleri için alınacak dersler vardır."},{"n":191,"t":"Onlar ki; ayaktayken, otururken ve uyumak için uzandıklarında Allah`ı anar, göklerin ve yerin yaratılışı üzerine tefekkür ederler: \"Rabbimiz! Bütün bunları anlamsız ve amaçsız yaratmadın! Yücelikte eşsizsin! Bizi ateşin azabından koru!\""},{"n":192,"t":"\"Rabbimiz! Sen kimi ateşe mahkum edersen, kesinlikle onu rezil etmiş olursun; ve o zalimler yardımcı da bulamazlar!\""},{"n":193,"t":"\"Rabbimiz! Bizi, \"Rabbinize iman edin!\" diye imana çağıran bir davetçiyi duyduk ve hemen iman ettik!\" \"Rabbimiz! Bizim günahlarımızı bağışla, kötülüklerimizi de ört ve canımızı erdemlilerle birlikteyken al!\""},{"n":194,"t":"\"Rabbimiz! Elçilerin aracılığıyla yaptığın vaadi bize bahşet ve Kıyamet Günü bizi mahcup etme! Çünkü Sen, vaaadinden asla caymazsın!\""},{"n":195,"t":"Rableri de onların dualarına şöyle icabet etti: \"Erkek olsun kadın olsun, çaba gösteren hiç kimsenin çabasını boşa çıkarmayacağım; sizler karşılıklı birbirinizi tamamlayan parçalarsınız. Kötülükten ve kötülük diyarından hicret edenlere, yurtlarından sürülenlere, yolunda eziyet çekenlere, savaşanlara ve öldürülenlere gelince: Onların kötülüklerini mutlaka örteceğim ve elbet onları Allah`tan bir ödül olarak zemininden ırmaklar çağlayan cennetlere sokacağım; zira ödüllerin en güzeli Allah katındadır.\""},{"n":196,"t":"İnkara saplananların, yeryüzünde keyiflerinin peşi sıra gezip tozmaları seni yanıltmasın!"},{"n":197,"t":"O geçici ve uçucu bir hazdır; sonunda varacakları yer cehennemdir, o ne kötü bir meskendir!"},{"n":198,"t":"Fakat Rablerine karşı sorumluluk duyanlar var ya: işte onlarındır zemininden ırmaklar çağlayan cennetler; Allah katından bir ikram olarak, orada yerleşip kalırlar. Zira Allah katında olan, erdemliler için en hayırlı olandır."},{"n":199,"t":"Doğrusu kitap ehli arasında, mutlaka Allah`a (gereği gibi) iman eden de, hem size hem kendilerine indirilene iman eden de vardı; onlar Allah`tan saygıyla korkarlar ve Allah`ın ayetlerini değersiz bir menfaat karşılığı pazarlamazlar: Onların ödülü Rableri katındadır; çünkü Allah hesabı seri tutandır."},{"n":200,"t":"Siz ey iman edenler! Zorluklara karşı direnin, direnişte birbirinizle dayanışma içinde olun, mevzilerinizi koruyun ve Allah`a karşı sorumluluk bilincini kuşanın ki ebedi saadete erebilesiniz."}],[{"n":1,"t":"Ey insanlık! Sizi bir tek canlı varlıktan yaratan, ondan da eşini yaratan ve her ikisinden de birçok erkek ve kadın var eden Rabbinize karşı sorumluluğunuzun bilincinde olun! Kendisi adına birbirinizden (hak) talebinde bulunduğunuz Zat`a ve bu insanlık bağına karşı sorumluluk duyun. Kuşkusuz Allah, üzerinizde daimi bir gözetleyicidir."},{"n":2,"t":"O halde yetimlere mallarını verin; değersizi değerliyle değiştirmeyin. Onların mallarını kendi mallarınıza katıp da boğazınıza geçirmeyin. Çünkü bu büyük bir vebaldir."},{"n":3,"t":"Ve eğer yetimlere, adil davranamamaktan korkuyorsanız, o zaman size helal olan diğer kadınlardan biriyle evlenin; (hatta) ikisi, üçü ve dördüyle; ama onlara da adil davranamayacağınızdan korkarsanız, o zaman bir taneyle ya da meşru olarak sahip olduklarınızla (yetinin)! Bu, altına girdiğiniz sorumluluğu ihlal etmemeniz açısından daha uygundur."},{"n":4,"t":"Kadınlarınıza mehirlerini, gönül rızasıyla karşılık beklemeksizin verin! Ve fakat, kendi rızalarıyla bir kısmını size bırakırlarsa, onu da afiyetle yiyin!"},{"n":5,"t":"Allah`ın koruyasınız diye sizin sorumluluğunuza bıraktığı malları, muhakeme yeteneği zayıf olan (mal sahiplerinin) eline terk etmeyin! Fakat bu mallarla onları yedirin, giydirin ve onlara (duruma) münasip bir dille izah edin!"},{"n":6,"t":"Yetimleri, evlenme çağına gelinceye kadar gözetleyin; ama eğer aklen olgunlaştıklarını tesbit ederseniz, mallarını kendilerine geri verin! Büyüyüverecekler diye mallarını alelacele ve saçıp-savurarak yemeye kalkmayın: İhtiyacı olmayan kimse tenezzül etmesin, muhtaç olan da münasip bir biçimde yararlansın! Mallarını kendilerine iade ettiğinizde, onlar adına şahitler bulundurun! Hesap sorucu olarak Allah yeter."},{"n":7,"t":"Ana-baba ve akrabanın bıraktıklarında erkeklerin bir payı (zaten) vardır. Ana-baba ve akrabanın bıraktıklarında, az ya da çok, kadınların da bir payı olmalıdır; (Allah tarafından) farz kılınan bir paydır bu."},{"n":8,"t":"(Miras) taksimi sırasında, (diğer) akraba, yetimler ve yoksullar da hazır bulunurlarsa, onlara da bir şey verin; ve kendilerine gönül alıcı sözler söyleyin!"},{"n":9,"t":"Artık korksun onlar ki; eğer kendileri, arkalarında korunmaya muhtaç cocuklar bıraksalardı, onlar için endişelenirlerdi. Allah`a karşı sorumluluk bilincini kuşansınlar da doğru dürüst konuşsunlar."},{"n":10,"t":"Doğrusu, yetimlerin mallarını haksız yere boğazlarına geçirenler, karınlarını yalnızca ateşle doldurmuş olurlar. Zira, gelecekte çılgın bir ateşe mahkum olacaklar."},{"n":11,"t":"Allah size çocuklarınız hakkında, bir erkeğe iki kızın payını vermenizi tavsiye etmektedir. [2] Eğer ikiden fazla kız iseler ölenin geriye bıraktığı malın üçte ikisi onlarındır. [3] Eğer sadece bir kızsa mirasın yarısı onundur. Eğer ölenin geride çocuğu varsa bıraktığı mirastan anne ve babanın her birine altıda bir pay verilir. Çocuğu yoksa ve anne babası ona mirasçı oluyorsa o zaman annenin payı üçte birdir. Eğer kardeşleri varsa anneye verilecek pay altıda birdir. Bu (paylaştırma) ölenin yaptığı vasiyetin yerine getirilmesinden yahut borcunun ödenmesinden sonradır. Babalarınız ve oğullarınızdan, hangilerinin yarar bakımından size daha yakın olduklarını bilemezsiniz. Bunlar Allah tarafından farz olarak konulan hükümlerdir. Allah ilim sahibidir, hakimdir."},{"n":12,"t":"Eğer çocukları bulunmuyorsa, eşlerinizin miraslarının yarısı size aittir. Fakat eğer onların çocukları varsa, ettikleri vasiyet ve borçlarından sonra terekelerinin dörtte birini alacaksınız. Eğer çocuğunuz yoksa, terekenizin dörtte biri eşlerine aittir. Fakat eğer çocuğunuz varsa, ettiğiniz vasiyet ve borçlardan sonra terekenizin sekizde birini alacaklar. Eğer erkek ya da kadın birinci dereceden bir mirasçıya sahip değilse; kız ya da erkek kardeşi de varsa, her birine altıda bir düşer. Fakat erkek ve kız kardeş birden fazlaysalar, edilen vasiyet ve borçtan sonra üçte birini alırlar. Bu her iki durumda da, (mirasçılara) zarar verilmemelidir. Bunlar Allah`ın size tavsiyesidir; zira Allah her şeyi bilendir, (bu kurallar hususunda) hilim ve hoşgörü sahibidir."},{"n":13,"t":"Bütün bunlar Allah tarafından çizilen sınırlardır. Kim Allah`a ve Rasulü`ne uyarsa, Allah onları içerisinde yerleşip kalacakları zemininden ırmaklar çağlayan cennetlere koyar; işte muhteşem kazanç da budur."},{"n":14,"t":"Kim de Allah’a ve Rasulüne, Kur’ân’a ve sünnete bağlılığı ve saygıyı terkeder, emirlerine itaat etmez, savsaklar ve rızalarını gözetmez, Allah’ın koyduğu kuralları ve sınırlarını çiğnerse, onu da Allah, içinde ebedî kalacağı ateşe, cehenneme sokar. Onun için alçaltıcı, zillete düşürücü bir azap vardır."},{"n":15,"t":"Hayasızlık sergileyen kadınlarınıza gelince: aranızdan onlar için dört şahit gösterin! Ve eğer bunlar onun için şahitlik yaparlarsa, ölüm gelinceye ya da Allah onların lehine bir yol gösterinceye kadar evlerde hapsedin!"},{"n":16,"t":"Ve aranızdan bu işi yapan her iki erkeği de cezalandırın! Eğer o ikisi tevbe eder ve durumlarını düzeltirse, onları cezalandırmaktan vazgeçin! Çünkü Allah tevbeleri kabul edendir, sınırsız merhamet sahibidir."},{"n":17,"t":"Doğrusu, Allah katında kabul gören tevbe, yalnızca bir cahillik ederek kötülük işleyen ve sonra vakit geçirmeden Allah`a yönelenlere mahsustur. İşte Allah da onları affa yöneltecektir; zira Allah her şeyi bilendir, her hükmünde tam isabet edendir."},{"n":18,"t":"Oysa ne ölüm gelip çatıncaya kadar (ısrarla) günah işlemeyi sürdürerek son anda \"İşte şimdi tevbe ediyorum!\" diyen birinin tevbesi kabul görecektir, ne de inkarında direnerek ölenlerin tevbeleri... İşte onlar kendilerine acıklı bir azap hazırladığımız kimselerdir."},{"n":19,"t":"Ey iman edenler! Kadınlara zorla mirasçı olmanız size helal değildir. Ve açık bir biçimde fuhuş işlemedikçe, verdiğiniz bir şeyi onlardan geri almak için onlara baskı yapmayın! Ve onlarla güzel bir şekilde geçinin; zira onlar size itici gelse bile, hoşlanmadığınız bir şeyde Allah bir çok hayır dilemiş olabilir."},{"n":20,"t":"Fakat eğer bir kadını bırakıp yerine başka bir kadın almak isterseniz, birincisine külçe külçe altın vermiş olsanız dahi hiçbir şeyi geri almayın. Ona iftira ederek ve bu nedenle açıkça günaha girerek verdiğinizi geri almak olur mu hiç?"},{"n":21,"t":"Birbirinizin mahremi olduktan ve eşiniz sizden sağlam bir taahhüt aldıktan sonra, onu nasıl geri alabilirsiniz ki?"},{"n":22,"t":"Babalarınızın daha önce evlilik yaptığı kadınlarla evlilik yapmayın, fakat geçmişte yapılanlar geçmişte kalmıştır. Bu davranış kesinlikle yüz kızartıcı bir hayasızlık, çirkin bir günah, kötü bir gelenek idi."},{"n":23,"t":"Anneleriniz, kızlarınız, kız kardeşleriniz, halalarınız, teyzeleriniz; erkek ve kız kardeşlerinizin kızları; süt anneleriniz ve süt kardeşleriniz; eşlerinizin anneleri; kendileriyle gerdeğe girdiğiniz eşlerinizden doğmuş olup sizin kendi hanenizde bakım ve velayetini üstlendiğiniz (sulbünüzden olmayan) kızlarınız, size haram kılınmıştır; fakat gerdeğe girmemişseniz bir mahzur yoktur; ve öz oğullarınızın eşleri de size haramdır; aynı anda iki kız kardeşi almanız da öyle. Fakat geçmişte olanlar geçmişte kalmıştır; çünkü Allah tarifsiz bir bağışlayıcıdır, eşsiz bir merhamet kaynağıdır."},{"n":24,"t":"Meşru şekilde hakkını vererek sahip olduklarınızın dışında, bütün evli kadınlar (da haramdır). Bu Allah`ın size talimatıdır. Bunların dışındakilerin tümü, mal varlığınızdan bir kısmını vererek istemeniz, gayr-ı meşru bir ilişkiyle değil de evlilik bağı yoluyla almak şartıyla size helaldir. Kendilerinden yararlandığınız kadınlara mehirlerini bir yükümlülük olarak tastamam verin! Bu yükümlülüğün tesbitinden sonra, başka bir şey üzerinde uzlaşmanızda sizin için bir sorumluluk yoktur. Kuşku yok ki Allah her şeyi bilendir, her hükmünde tam isabet edendir."},{"n":25,"t":"Aranızdan her kimin durumu, hür bir mü`min kadın almaya elvermezse, o meşru şekilde sahip olduğunuz mü`min kızlardan birini alsın; çünkü Allah, imanınızı(n değerini) çok iyi bilir; (zaten eşler olarak) siz, birbirini bütünleyen parçalarsınız. O halde iffetini koruyan, fuhşa bulaşmayan ve dost da tutmayan kadınlarla sahiplerinin izniyle evlenin ve mehirlerini makul bir şekilde verin! Onlar evlendirildikten sonra iffetsiz bir davranışta bulunurlarsa, onları hür evli kadınlara verilenin yarısıyla cezalandırın! Bu, içinizden zorlanınca günaha girme korkusu duyanlar içindir. Fakat sabretmeniz sizin için daha hayırlıdır: Allah tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":26,"t":"Allah (bütün bunları) size açıklamak, öncekilerin (doğru) hayat tarzlarına sizi yönlendirmek ve size bağışıyla yönelmek ister; çünkü Allah her şeyi bilendir, her hükmünde tam isabet edendir."},{"n":27,"t":"Allah size olanca bağışlayıcılığıyla yönelmek isterken, ayartıcı içgüdülerine esir olanlar sizi yoldan tamamen çıkarmak isterler."},{"n":28,"t":"Allah yükünüzü hafifletmek ister; zira insan zayıf yaratılmıştır."},{"n":29,"t":"Ey iman edenler! Karşılıklı rızaya da dayansa, birbirinizin mallarını haksız yere yemeyin; -tabi ki (meşru) ticaret hariç- ve kendinize kıymayın; çünkü Allah sizin için bir rahmet kaynağıdır."},{"n":30,"t":"Kim bunu düşmanca ve zulmetme kastıyla yaparsa, onu zamanı geldiğinde ateşe mahkum edeceğiz; zira bu Allah için çok kolaydır."},{"n":31,"t":"Kaçınmanız emredilen büyük günahlardan uzak durursanız, kusurlarınızı örteriz ve sizi onurlu bir makama yerleştiririz."},{"n":32,"t":"O halde Allah`ın size bahşettiği sizi birbirinize üstün kılan farklı değerleri temenni etmeyin. Erkeklerin kendi kazançlarından bir payı vardır; kadınların da kendi kazançlarından bir payı vardır. İhsanından bahşetmesi için Allah`tan isteyin; kuşkusuz Allah her bir şeyi hakkıyla bilmektedir."},{"n":33,"t":"Herkes için, geriye bıraktığı mirastan pay alacak mirasçılar tayin ettik: Ebeveynler, akrabalar ve kendileriyle sözleştikleriniz... İşte bunlara nasiplerine düşeni verin; iyi bilin ki Allah her bir şeye hakkıyla şahittir."},{"n":34,"t":"Allah`ın onlara fazladan vermiş olduğu nimetler ve mallarından yaptıkları harcamalar sebebiyle, erkekler kadınlar üzerinde yönetici ve koruyup gözeticidirler. Saliha kadınlar ise itaatkârdırlar; Allah kendilerini nasıl korudu ise, onlar da kocalarının yokluğunda onların hukukunu korurlar. Geçimsizliğinden korktuğunuz kadınlara öğüt verin; sonra onları yataklarında yalnız bırakın; sonra da hafifçe dövebilirsiniz. Eğer size itaat ederlerse, artık onlara karşı bahane aramayın. Çünkü Allah herşeyden yüce, herşeyden büyüktür."},{"n":35,"t":"Şayet evli bir çiftin aralarının açılmasından endişe ederseniz, erkeğin ve kadının ailelerinden birer hakem tayin edin! Eğer iki taraf da anlaşmazlığı gidermek isterse, Allah onları uzlaştırır. Unutmayın ki Allah her şeyi bilendir, her şeyden haberdar olandır."},{"n":36,"t":"Allah`a kulluk edin ve O`ndan başka hiçbir şeye ilahlık yakıştırmayın; ana-babaya ve akrabaya, yetimlere ve yoksullara, kendi çevrenizden olan komşulara ve yabancı komşulara, yanınızdaki dosta, yolcuya ve meşru şekilde bihakkın sahip olduklarınıza iyilik yapın! Unutmayın ki Allah kendini beğenmiş küstahları sevmez;"},{"n":37,"t":"kendisi cimrilik yapan ve başkalarına cimriliği öneren, Allah`ın kendilerine bağışladığı nimetleri saklayanları da... Ve kafirler için utanç veren bir azap hazırladık."},{"n":38,"t":"Yine Allah`a ve ahiret gününe inanmadıkları halde mallarını sırf gösteriş olsun için harcayanları da (sevmez). Can yoldaşı şeytan olan kimse ne kötü dosta sahiptir!"},{"n":39,"t":"Bunlar da Allah`a ve ahiret gününe iman etselerdi ve Allah`ın kendilerine bağışladığı rızıktan infak etselerdi ne kaybederlerdi sanki? Ama Allah onlar hakkında her şeyi bilir."},{"n":40,"t":"Kuşkusuz Allah kimseye zerre miktarı haksızlık yapmaz; eğer hayırlı bir iş varsa onu kat kat artırır; katından da büyük bir ödül bahşeder."},{"n":41,"t":"Asıl her toplumdan bir şahit getirdiğimiz ve seni de onlar aleyhine şahit gösterdiğimiz zaman ne olacak (onların hali)?"},{"n":42,"t":"O gün hakikati inkar edenler ve Peygamber`e karşı çıkanlar, yerin dibine geçmeyi temenni ederler; fakat onlar hiçbir şeyi Allah`tan gizleyemezler."},{"n":43,"t":"Siz ey iman edenler! Sarhoşken ne dediğinizi bilinceye kadar, cünüpken de -seyahat (gibi yıkanmayı güçleştiren haller) hariç- yıkanıncaya kadar namaza yaklaşmayın! Fakat eğer hastaysanız ya da yolculuk yapıyorsanız veya ihtiyaç giderdikten sonra yahut kadınlarla birlikte olmuşsanız ve üstelik su da bulamıyorsanız, o zaman temiz bir toprak alıp yüzlerinizi ve ellerinizi onunla meshedin! Unutmayın ki Allah tarifsiz bir affedicidir, eşsiz bir bağışlayıcıdır."},{"n":44,"t":"Kendilerine vahiyden bir pay verilmiş olanların onu sapıklıkla değiştirdiklerini ve sizin de yoldan çıkmanızı istediklerini görmüyor musun?"},{"n":45,"t":"Fakat Allah düşmanlarınızı daha iyi bilir. Ama (eğer size dost lazımsa) dost olarak Allah yeter; (yardım lazımsa) yardımcı olarak da Allah yeter."},{"n":46,"t":"Yahudileşenlerden kimileri sözleri bağlamlarından kopararak çırpıtırlar; \"İşittik ve sarıldık/reddettik\", \"dinle dinlenilmeyesi\" ve \"ra`ina\" derler, dillerini eğip bükerek ve dine hakaret kastıyla. Eğer onlar \"işittik ve itaat ettik\", \"dinle\" ve \"unzurna\" deselerdi, bu kendileri için daha yararlı ve daha dürüstçe bir davranış olurdu. Ne ki, hakikati inkar ettikleri için Allah onları rahmetinden dışladı; gerçekten de onlar, çok azı müstesna, inanmıyorlar."},{"n":47,"t":"Siz ey önceki vahiylerin müntesipleri! Sizdekini tasdik edici olarak indirdiğimiz vahye inanın ki, (geleceğe yönelik) umutlarınızı söndürüp yüzlerinizi geçmişe döndürmeyelim; ya da Cumartesi yasağını çiğneyen topluluğu lanetlediğimiz gibi lanetlemeyelim; zira Allah`ın iradesi mutlaka gerçekleşir."},{"n":48,"t":"Kuşkusuz Allah kendisine ortak koşulmasını bağışlamaz; fakat dileyen kimselerin bunun dışındaki günahlarını bağışlamayı diler. Zira Allah`a ortak koşan kimseler, (O`na) iftira ederek korkunç bir günah işlemiş olmaktadırlar."},{"n":49,"t":"Baksana kendilerini temize çıkaranlara! Ama yoo! Allah dilediğini temize çıkarır ve kimseye zerre kadar haksızlık yapılmaz."},{"n":50,"t":"Bak, kendi uydurduklarını nasıl da Allah`a atıyorlar? (Onların pek de temiz olmadıklarına) bu aşikar günah yeter."},{"n":51,"t":"Kendilerine vahiyden bir pay verilenleri görmüyor musun? Eşya ve olaylarda uğur ve uğursuzluk olduğuna ve tağuta inanıyorlar ve kafirlerin mü`minlerden daha doğru yolda olduğunu iddia ediyorlar."},{"n":52,"t":"Allah`ın lanetledikleri işte bunlardır; Allah`ın lanetine uğrayan biri de asla kendisine yardımcı bulamazsın."},{"n":53,"t":"Yoksa onlar Allah`ın mülküne ortak olduklarını mı sanıyorlar? Eğer öyle olsaydı, insanlara zırnık bile vermezlerdi."},{"n":54,"t":"Yoksa onlar, Allah`ın lutfundan bahşettiği şeylerden dolayı insanlara haset mi besliyorlar? Oysa Biz, İbrahim ailesine vahiy ve onu doğru hükme ulaşmada kullanacakları selim bir muhakeme yeteneği vermiş ve onlara güçlü bir hükümranlık bahşetmiştik."},{"n":55,"t":"Aralarında ona inananlar da vardı, ondan yüz çevirenler de; (işte bunlara) kavurucu bir ateş olarak cehennem yeter."},{"n":56,"t":"Ayetlerimizi inkarda ısrar edenleri, zamanı gelince ateşe mahkum edeceğiz; (ve) derilerinin her yanıp soyulmasında, derilerini değiştireceğiz ki azabı (ta can evinde) hissedebilsinler: Şüphesiz Allah her işinde tek mükemmal olan, her hükmünde tam isabet kaydedendir."},{"n":57,"t":"Fakat iman edip salih amel işleyenleri, zemininden ırmaklar çağlayan cennetlere koyacağız, orada ebediyyen kalacaklar; orada onlar tertemiz eşlere sahip olacaklar; ve onları muhteşem bir gölgede gölgelendireceğiz."},{"n":58,"t":"Allah, size emanet edilen şeyleri mutlaka ehline vermenizi ve insanlar arasında hüküm verecek olursanız adaletle hüküm vermenizi emrediyor. Allah size ne de güzel öğüt veriyor; zira Allah akıl sır ermez bir biçimde her şeyi işiten, her şeyi görendir."},{"n":59,"t":"Siz ey iman edenler! Allah`a, Peygamber`e ve aranızdan alanlarında yetkin ve otorite sahibi olanlara itaat edin; bir hususta anlaşmazlığa düşerseniz, onu Allah`a ve Peygamber`e götürün; tabi eğer Allah`a ve ahiret gününe inanıyorsanız. Bu, en iyi seçimdir ve sonuç açısından da en verimli olandır."},{"n":60,"t":"Sana ve senden önce indirilenlere iman ettiğini sananlara bir baksana! Birbirlerini (İlahlık rolüne soyunan) şeytani güç odaklarının hakimiyetine çağırmakta bir sakınca görmüyorlar; oysa onu inkar etmekle emrolunmuşlardı. Nitekim şeytanın tek arzusu, onları derin bir sapıklığa itmektir."},{"n":61,"t":"Onlara, \"Allah`ın indirdiğine ve Peygamber`e gelin\" denildiğinde, bu münafıkların nefretle senden yüz çevirdiklerini görürsün."},{"n":62,"t":"Fakat, önceden yaptıkları yüzünden başlarına öngöremedikleri bir musibet gelirse ne olacak halleri? Sonra sana gelecekler, Allah adına yeminle \"bizim amacımız sadece iyilik yapmak ve uyumu sağlamaktı\" (diyecekler)."},{"n":63,"t":"Ama Allah, onların kalplerindeki her şeyi bilir. Şu halde onları kendi hallerine bırak; onlara öğüt ver ve içine düştükleri durumu net bir biçimde açıkla."},{"n":64,"t":"Zira Biz, her peygamberi, Allah`ın izni dahilinde sadece kendilerine itaat olunsunlar diye gönderdik. Eğer onlar, kendilerine kötülük ettikten sonra sana gelip de Allah`tan af dileselerdi ve -Peygamber de onların bağışlanması için dua etseydi- kesinlikle Allah`ı tevbeleri kabul etmeye hazır ve merhametli bulacaklardı."},{"n":65,"t":"Ama hayır, Rabbine andolsun ki, aralarında tartıştıkları her konuda seni hakem yapmadıkça, sonra da senin hükmüne içlerinde hiçbir tereddüt taşımaksızın tam bir teslimiyetle uymadıkça iman etmiş sayılmazlar."},{"n":66,"t":"Fakat Biz, onlara \"Canlarınızı feda edin!\" ya da \"Yurtlarınızı terk edin!\" diye emretmiş olsaydık, çok azı dışında bu emri tutmazlardı. Ama öğütleneni yapsalardı, kendileri için daha iyi olurdu ve (bu) onları daha dirençli kılardı."},{"n":67,"t":"O zaman Biz de onlara, katımızdan muhteşem bir ödül verirdik."},{"n":68,"t":"ve onları dosdoğru bir yola yöneltirdik."},{"n":69,"t":"Allah`a ve Peygamber`e itaat eden kimseler, Allah`ın kendilerine nimet verdiği peygamberler, Hakk`a sadık kalanlar, hayatını imanına şahit kılanlar ve iyiliği yayanların safında olurlar. Bunlar ne güzel dostturlar."},{"n":70,"t":"Bu Allah`ın bir lutfudur; ve (bunu birinin bilmesi gerekiyorsa) her şeyi bilen Allah yeter."},{"n":71,"t":"Siz ey iman edenler! Küçük müfrezeler halinde ya da topyekün orduyla ilerlerken ihtiyatlı hareket edin!"},{"n":72,"t":"Aranızda elbette işi ağırdan alan kimseler olacak ve bir yenilgiyle karşılaştığınızda \"Onlarla birlikte bulunmamam Allah`ın bana bir lutfudur\" diyecek."},{"n":73,"t":"Fakat Allah`tan size bir zafer ihsan edildiğinde, bu kez de o kimseler sanki sizinle kendi aralarında hiçbir sevgi problemi yokmuş gibi \"Keşke onlarla birlikte olsaydım da o muhteşem başarıya konsaydım!\" diyecek."},{"n":74,"t":"O halde, dünya hayatını ahiret hayatıyla takas etmek isteyenler Allah yolunda savaşsınlar. Allah yolunda savaşan herkese, ister öldürülsün ister galip gelsin gelecekte muazzam bir ödül bahşedeceğiz."},{"n":75,"t":"Size ne oluyor da, Allah yolunda \"Ey Rabbimiz! Bizi halkı zalim olan şu beldeden kurtar ve rahmetinle bize sahip çıkacak bir koruyucu ve destek olacak bir yardımcı gönder!\" diye yalvaran güçsüz erkekler, kadınlar ve çocuklar için savaşmıyormusunuz?"},{"n":76,"t":"İman edenler Allah yolunda, inkar edenler de şeytani güçlerin yolunda mücadele ederler. O halde, Şeytan`ın dostlarına karşı mücadele edin! Unutmayın ki Şeytan`ın hilesi kesinlikle zayıftır."},{"n":77,"t":"Kendilerine \"(Artık savaştan) çekin ellerinizi! Namazı istikametle kılın, zekatı içten gelerek verin\" denilenlerin haline baksana bir! Ama onlara savaşmaları emredildiği zaman, içlerinden bir gurup Allah`tan korkarcasına, hatta daha da büyük bir korkuyla insanlardan korkmaya başladılar ve şöyle dediler: \"Rabbimiz! Niçin bize savaşı emrettin? Bize biraz daha süre tanıyamaz mıydın!\" De ki: \"Dünyevi tatmin geçici bir hazdır, ahiret ise sorumluluk sahibi biri için en hayırlı olandır; sonuçta zerre kadar haksızlığa uğramayacaksınız."},{"n":78,"t":"Nerede olursanız olun, ölüm gelip sizi bulur; yıldızlara yükselmiş bile olsanız.\" Güzel şeylerle karşılaştıklarında \"Bu Allah katındandır!\" derler, fakat bir kötülüğe uğradıklarında ise \"Bu senin yüzündendir!\" diye sitem ederler. De ki: \"Hepsi Allah`tandır!\" Fakat, bu adamlara ne oluyor ki sözü anlamamakta ısrar ediyorlar?"},{"n":79,"t":"Uğradığınız her iyilik Allah`tandır; başınıza gelen her kötülük de kendinizdendir. Biz seni bütün insanlığa elçi olarak gönderdik; ve buna (birinin şahid olması gerekirse), en büyük şahit olan Allah yeter."},{"n":80,"t":"Kim Elçi`ye itaat ederse Allah`a itaat etmiş olur. Kim de yüz çevirirse, iyi bilsin ki biz seni onlara korumalık yapasın diye göndermedik."},{"n":81,"t":"Onlar \"Baş üstüne!\" derler, ama yanından uzaklaştıklarında, içlerinden bir güruh gece boyunca senin dile getirdiğinden farklı işler çevirirler. Ama Allah onların gece karanlığında çevirdikleri işleri kaydetmektedir. Şu halde işine bak ve Allah`a dayan; zira dayanak olarak Allah yeter."},{"n":82,"t":"Onlar Kur`an`ın manası üzerinde kafa patlatırcasına derinliğine durmuyorlar mı? Eğer o Allah dışındaki bir kaynaktan gelmiş olsaydı, elbette onda bir yığın çelişki ve tutarsızlık bulurlardı."},{"n":83,"t":"Onlar, kendilerine barış ya da savaşla ilgili herhangi bir bilgi ulaştığında onu dışarı yayarlar. Oysa ki onu Peygambere ya da mü`minler arasından kendilerine yetki verilmiş olanlara iletselerdi, onlar arasından işin (uzmanı olup) ölçme-değerlendirme yapabilenler onu da (değerlendire)bilirlerdi. Size Allah`ın lütuf ve rahmeti olmasaydı, çok azınız hariç kesinlikle şeytanın ardınca giderdiniz."},{"n":84,"t":"Artık Allah yolunda savaş! Sen kendinden sorumlusun. Yine de mü`minleri uyuşukluktan kurtulmaları için teşvik et! Belki Allah inkarcıların direncini kırar; zira Allah`ın gücü daha çetin ve cezalandırması daha şiddetlidir."},{"n":85,"t":"Kim haklı bir davaya katkıda bulunursa, onun tüm getirisinden bir pay alacaktır; kim de haksız bir davaya katkıda bulunursa, onun tüm vebalinden bir pay alacaktır: Zira Allah her şeye bir ölçü koyan, koyduğu ölçüye sahip çıkandır."},{"n":86,"t":"Bir selam aldığınızda daha güzel bir selamla karşılık verin, ya da aynısıyla iade edin; zira Allah, her şeyin hesabını tutmaktadır."},{"n":87,"t":"Allah -ki O`ndan başka ilah yoktur- geleceğinde asla kuşku olmayan Kıyamet Günü`nde elbette sizi bir araya toplayacaktır. Kim Allah`tan daha doğru sözlü olabilir?"},{"n":88,"t":"İşlediklerinden dolayı Allah onları terslediği halde, size ne oluyar da münafıklar hakkında iki gruba ayrılıyorsunuz? Allah`ın sapıklık içinde bıraktığı kimseyi doğru yola getirmek mi istiyorsunuz? Allah kimi sapıklık içinde bırakırsa, artık ona bir çıkış yolu bulamazsın."},{"n":89,"t":"Onlar, kendilerinin inkar ettikleri gibi sizin de inkar edip kendileriyle aynı seviyeye düşmenizi istiyorlar. O halde, Allah yolunda hicret edinceye kadar onları kendinize sır ortağı edinmeyin! Eğer düşmanlığa yönelirlerse, onları nerede bulursanız yakalayın, öldürün ve onlardan kimseyi ne dost, ne de yardımcı tutun!"},{"n":90,"t":"Ne var ki, sizinle arasında anlaşma bulunan bir topluma sığınanlar, ya da sizinle veya kendi toplumlarıyla savaşma (fikrinden) içleri daralarak size başvuranlar hariç. Eğer Allah isteseydi, onları sizin başınıza musallat eder ve onlar da sizinle savaşırlardı. Ama onlar sizi bırakır, size karşı savaşmaz ve size barış teklif ederlerse, o zaman onlara zarar vermenize Allah razı olmaz."},{"n":91,"t":"Siz, hem sizden hem de kendi toplumlarından emin olmak isteyen, fakat ne zaman (mü`minler aleyhine bir) entrikaya davet edilseler, içine balıklama dalanlara da rastlayacaksınız. İşte o zaman, eğer onlar sizi bırakmaz, sizinle barışa yanaşmaz ve ellerini yakanızdan çekmezlerse; onları da savaş içinde gözünüze kestirdiğiniz her yerde yakalayın ve öldürün: İşte size, kendileri aleyhine açıkça (savaşmak için) izin verdiklerimiz bunlardır."},{"n":92,"t":"Ve bir mü`min başka bir mü`mini asla öldüremez; hataen olursa o başka. Bir mü`mini hata ile öldüren kişi ise, mü`min birini özgürlüğe kavuşturur ve müktulün yakınlarına diyet öder; eğer onlar diyeti bağışlarlarsa, o başka. Maktul mü`min olduğu halde size düşman olan bir topluma mensupsa, o zaman mü`min birini özgürlüğe kavuşturmak (yeterlidir). Ama o sizinle arasında anlaşma olan bir topluma mensupsa, bu durumda mü`min birini özgürlüğüne kavuşturmak ve yakınlarına diyet ödemek gerekir. Buna imkan bulamayanlar peş peşe iki ay oruç tutmalıdırlar; Allah tarafından tevbenin kabulüne bir karşılık olarak: Zira Allah her şeyi bilendir, her hükmünde tam isabet edendir."},{"n":93,"t":"Kim de bir mü`mini kasten öldürürse, onun cezası cehennemde süresiz kalış olacaktır. O, Allah`ın gazabına ve lanetine uğrayacak, (Allah) onun için korkunç bir azap hazırlayacaktır."},{"n":94,"t":"Siz ey iman edenler! Allah yolunda sefere çıktığınız zaman son derece sorumlu davranın; ve size barış teklif edene bu dünya hayatının geçici zevkine göz dikerek \"Sen mü`min değilsin!\" demeyin! Çünkü asıl ganimet Allah katındadır. Siz de daha önce onların durumundaydınız, fakat Allah`ın lutfuna nail oldunuz. Artık çok dikkatli davranın: zira Allah tüm yaptıklarınızdan haberdardır."},{"n":95,"t":"Mü`minlerden bir mazereti olmaksızın mücadeleden kaçınanlarla Allah yolunda mallarıyla ve canlarıyla çaba gösterenler bir olamaz: Allah mallarıyla ve canlarıyla elinden gelen çabayı sarf edenleri mücadeleden kaçınanlardan daha yüce bir mertebeye çıkarmıştır. Allah bütün mü`minlere nihai güzellikler vaad etmesine rağmen, yolunda üstün gayret harcayanları yerinde sayanlara muhteşem bir ödül vaadiyle üstün tutmuştur:"},{"n":96,"t":"Katından yüce mertebelerle, mağfiret ve rahmetle... Zaten Allah tarifsiz bir bağışlayıcıdır, eşsiz bir merhamet kaynağıdır."},{"n":97,"t":"Melekler, kendi kendilerine zulmedenlere canlarını alırken \"Sizin neyiniz vardı?\" diye soracak. Onlar, \"Biz yeryüzünde güçsüzdük!\" diye cevap verecekler. (Melekler) \"Allah`ın arzı yeterince geniş değil miydi, hicret etseydiniz ya?\" diyecekler. İşte bu tiplerin varacağı yer cehennemdir; orası ne kötü varış yeridir."},{"n":98,"t":"Ne ki ezilen kesimlere mensup erkek, kadın ve çocuklardan hiçbir gücü olmayan ve yol göstericisi de bulunmayan kimseler bundan müstesnadır."},{"n":99,"t":"İşte bunları da Allah`ın affetmesi umulur; zira Allah tarifsiz bir affedicidir, eşsiz bir bağışlayıcıdır."},{"n":100,"t":"Kim de Allah yolunda hicret ederse, kendisine bir çok alternatif mekanlar ve imkanlar bulur. Ve her kim Allah`a ve Peygamberine hicret etmek üzere evinden çıkar da, ardından ölüm gelip onu bulursa, artık onun ödülü Allah`a aittir; zaten Allah tarifsiz bir bağışlayıcıdır, eşsiz bir merhamet kaynağıdır."},{"n":101,"t":"Yeryüzünde sefere çıktığınızda, inkarda ısrar eden kimselerin aniden size zarar vermelerinden korkarsanız, namazları kısaltmanızda bir beis yoktur. Zira inkar edenler size açıktan düşmanlık yapmaktadırlar."},{"n":102,"t":"Sen de onların arasındayken kendilerine imamlık yapacağın zaman, sadece bir kısmı silahlarını kuşanmış olarak seninle namaza dursunlar. Onlar secdeye vardıklarında (diğerleri) sizin ardınızda dursunlar. Bu kez namazlarını eda etmemiş olan diğer grup gelsin, her türlü tehlikeye karşı müteyakkız ve silahlarını kuşanmış bir halde seninle birlikte namaza dursunlar. İnkarda direnenler sizi silahsız ve teçhizatsız yakalamak isterler ki, ani bir baskınla sizi gafil avlayabilsinler. Fakat yağmur dolayısıyla zorda kalır ya da hastalıktan muzdarip olursanız, (namaz sırasında) silahlarınızı bırakmanızda bir beis yoktur; yine de siz tehlikeye karşı tetikte olun! Kuşku yok ki Allah, inkarcılar için alçaltıcı bir azap hazırlamıştır."},{"n":103,"t":"Namazınızı eda ettiğinizde, ayaktayken, otururken ve uzanmış bir haldeyken Allah`ı anın ve güvenlik içindeyken namazlarınızı (eksiksiz) kılın; çünkü namaz bütün mü`minler için belirli zamanlarda kayıtlı bir vecibedir."},{"n":104,"t":"(Düşman) tarafını takip etmekte ürkek davranmayın. Eğer siz sıkıntı çekiyorsanız, onlar da sizin çektiğiniz sıkıntıyı çekiyorlar; fazladan siz onların Allah`tan umut edemedikleri şeyleri umut ediyorsunuz: ve Allah her şeyi bilendir, her hükmünde tam isabet edendir."},{"n":105,"t":"Biz sana, insanlar arasında Allah`ın sana gösterdiği gibi hüküm verebilesin diye hakikatin ifadesi olan bu vahyi indirdik; sakın hainlere taraftar olma!"},{"n":106,"t":"Ve Allah`tan af dile! Çünkü Allah tarifsiz bir bağışlayıcıdır, eşsiz bir merhamet kaynağıdır."},{"n":107,"t":"Öz benliklerine ihanet edenleri de savunma! Hiç şüphesiz Allah, kendisine ihaneti meslek edinip boğazına kadar günaha batanları sevmez."},{"n":108,"t":"Onlar yaptıklarını insanlardan gizleyebildiler (belki), fakat Allah`tan gizleyemezler. Çünkü zifiri gecede Allah`ın razı olmadığı bir söylemi tasarladıkları her an bile Allah onların yanı başındadır. Zira Allah onların yaptığı her şeyi çepeçevre kuşatandır."},{"n":109,"t":"Hadi siz bu dünya hayatında onları savundunuz diyelim; ya Kıyamet Günü, Allah`a karşı onların savunmasını kim üstlenecek; ya da onları kim koruyacak?"},{"n":110,"t":"Fakat kim kötülük yapar ya da kendine zulmeder ama Allah`tan af dilerse, Allah`ı hem tarifsiz bir bağışlayıcı, hem de eşsiz merhamet sahibi bulacaktır."},{"n":111,"t":"Zira kötülük işleyen kimse ancak kendi aleyhine işlemiş olur; Allah ise her şeyi bilendir, her hükmünde tam isabet edendir."},{"n":112,"t":"Kim de bir hata yapar ya da günah işler ardından da onu suçsuz bir kimsenin üzerine atarsa, işte o zaman korkunç bir iftiranın ve aşikar bir günahın vebalini yüklenmiş olur."},{"n":113,"t":"Allah`ın sana lutfu ve rahmeti olmasaydı, o(kendilerine zulüm yapa)nlardan bazısı seni saptırmaya çalışırdı; fakat onlar kendilerinden başka kimseyi saptıramazlar ve sana hiçbir zarar veremezler. Zira Allah sana bu kitabı indirmiş, sana doğru hüküm vermeyi ve bilmediklerini öğretmiştir. Çünkü Allah`ın sana olan lutfu gerçekten büyüktür."},{"n":114,"t":"Gizli toplantıların çoğunda hayır yoktur; ancak yardımlaşmayı, iyilik yapmayı ve insanların arasını düzeltmeyi amaçlayan kimselerin yaptığı toplantılar müstesna; bütün bu güzellikleri Allah rızasını kazanmak için yapan kimseye, zamanı geldiğinde muhteşem bir ödül vereceğiz."},{"n":115,"t":"Fakat kendisine doğru yol ayan açık belli olduktan sonra Peygamber ile yollarını ayıran ve mü`minlerin yolundan başka yollara sapan kimseyi kendi tercihiyle baş başa bırakacak ve onu cehenneme sokacağız: O ne berbat bir ikametgahtır!"},{"n":116,"t":"Kuşkusuz Allah kendisine ortak koşulmasını bağışlamaz; fakat dileyen kimselerin bunun dışındaki günahlarını bağışlamayı diler; ve her kim Allah`a ortak koşmakta (ısrar ederse), işte o apaçık bir sapkınlığa gömülüp gitmiştir."},{"n":117,"t":"Onlar Allah`ı bırakıp yalnızca cansız dişil nesnelere sığınıyorlar; bu şekilde onlar, inatçı şeytana sığınmış oluyorlar;"},{"n":118,"t":"ki Allah onu lanetlemiş, o da şöyle demişti: \"Senin kullarından payıma düşeni mutlaka alacağım!"},{"n":119,"t":"Onları saptıracağım ve kuruntularla oyalayacağım: zira ben onlara emredeceğim, onlar da develerin kulaklarını kesecekler; yine onlara emredeceğim, onlar Allah`ın yaratışını değiştirecekler!\" Fakat Allah`ı bırakıp Şeytan`ı kendilerine rehber edinenler, apaçık bir ziyana uğramış olurlar."},{"n":120,"t":"Şeytan onlara boş vaadlerde bulunur ve kuruntularla oyalar; ama Şeytan`ın onlara vaad ettiği her şey, aldanışa sürüklemekten başka bir işe yaramaz."},{"n":121,"t":"Böylelerinin varacağı yer cehennemdir, oradan kaçış yolu da bulamayacaklar."},{"n":122,"t":"İman eden ve o imanla uyumlu ıslah edici iyi işler yapanlara gelince: onları zemininden ırmaklar çağlayan cennetlere koyacağız, orada ebediyyen kalacaklar. Bu Allah`ın gerçekleşecek bir vaadidir; hem, kim Allah`tan daha doğru sözlü olabilir ki?"},{"n":123,"t":"Değil, sizin kuruntularınız da, geçmiş vahiy mensuplarının kuruntuları da belirleyici değil: Kötülük işleyen herkes cezalandırılacaktır. Allah`tan başka dost ve yardımcı da bulamayacaktır."},{"n":124,"t":"Ama erkek olsun kadın olsun, imanlı olarak salih amel işleyen herkes cennete girecek, zırnık kadar da haksızlığa uğratılmayacaktır."},{"n":125,"t":"Bütün varlığıyla Allah`a adanan, sürekli iyilik yapan ve bir muvahhid olarak İbrahim`in iman ailesine -ki Allah İbrahim`ten hoşnut ve razı olmuştu- tabi olan kimseden daha güzel dinli biri olabilir mi?"},{"n":126,"t":"Neticede, göklerde ve yeryüzünde olan her şey Allah`a aittir ve Allah her şeyi çepeçevre kuşatandır."},{"n":127,"t":"Onlar, kadın(ın hakları) konusunda senden açıklama istiyorlar. De ki: \"(Bizzat) Allah onlar hakkındaki hükümleri size açıklamaktadır\". Kaldı ki, yazılı haklarını dahi kendilerine vermeye yanaşmayıp üstelik (bir de) nikahlamak istediğiniz (velayetiniz altındaki) yetim kızlar, kimsesiz çocuklar ve sözkonusu yetimleri adaletle koruyup kollama yükümlülüğünüz hakkında Kitap`ta size tebliğ edilen hükümler zaten mevcuttur. Ve her ne iyilik yaparsanız yapın, unutmayın ki Allah onu bilir."},{"n":128,"t":"Eğer bir kadın kocasının sadakatsizlik ve geçimsizliğinden ya da kendisini terk etmesinden korkarsa, karşılıklı anlaşma yoluyla aralarındaki sorunu çözmelerinde her iki taraf için de bir beis yoktur; anlaşma en iyi yoldur, bencilce kıskançlık ise insan fıtratında hazır ve nazırdır: Eğer iyilik yapar ve sorumlu davranırsanız, iyi bilin ki Allah yaptığınız her şeyden haberdardır."},{"n":129,"t":"Ne kadar arzu etseniz de, eşleriniz arasında adaleti tam gerçekleştiremeyeceksiniz. Hiç değilse, sadece birine yönelerek diğerini boşluktaymış gibi bırakıp dışlamayın. Eğer arayı bulur ve sorumlu davranırsanız, iyi bilin ki Allah tarifsiz bir bağışlayıcı, eşsiz bir rahmet kaynağıdır."},{"n":130,"t":"Ve eğer (her şeye rağmen) eşler ayrılırlarsa, Allah lutfuyla her birinin geçimini sağlar: Zira Allah (lütfunda) sınırsızdır, her hükmünde tam isabet sahibidir."},{"n":131,"t":"Sözün özü: göklerde ve yerde olan her şey Allah`a aittir. Biz, hem sizden önce kendilerine vahiy emanet edilenlere hem de size \"Allah`a karşı sorumluluğunuzun bilincinde olun!\" tavsiyesinde bulunmuştuk. Ama eğer O`nu inkar ederseniz, unutmayın ki göklerde ve yerde olan her şey Allah`a aittir: Ve Allah kendi kendine yetendir ve bütün hamdlerin tek adresidir."},{"n":132,"t":"Evet, göklerde ve yeryüzünde olan her şey Allah`a aittir ve güven kapısı olarak Allah yeter."},{"n":133,"t":"Ey insanlar! Eğer O dilerse sizi topyekün ortadan kaldırır, yerinize daha başkalarını getirir; zira Allah`ın bunu yapmaya gücü yeter."},{"n":134,"t":"Kim bu dünyanın nimetlerini isterse, iyi bilsin ki, bu dünyanın da ahiretin de nimetleri Allah`a aittir ve Allah her şeyi işitendir, her şeyi tarifsiz görendir."},{"n":135,"t":"Siz ey iman edenler! Kendinizin, ebeveyninizin ve akrabanızın aleyhine de olsa, Allah için hakka şahitlik yaparak daima adaleti tesis etmeye çalışın. O kimse zengin olsun fakir olsun, Allah`ın hakkı onların her birinin önüne geçer. O halde kendi arzularınıza uymayın ki adaletten uzaklaşmayasınız. Ama eğer hakikati çarpıtırsanız ve(ya) şahitlikten kaçınırsanız bilin ki Allah yaptıklarınızdan haberdardır."},{"n":136,"t":"Siz ey iman edenler! İman edin Allah`a, O`nun Elçisi`ne, O`nun Peygamberi`ne peyderpey indirdiği ilahi kelama ve daha önce indirdiği mesaja! Zira kim Allah`ı, meleklerini, vahiylerini, peygamberlerini ve Ahiret Günü`nü inkar ederse, işte o derin bir sapıklığı boylamış olur."},{"n":137,"t":"İman edip sonra inkâr edenleri, sonra yine iman edip tekrar inkâr edenleri, sonra da inkârlarını arttıranları Allah ne bağışlayacak, ne de onları doğru yola iletecektir."},{"n":138,"t":"Münafıklara kendileri için acı bir azap olduğunu müjdele!"},{"n":139,"t":"Mü`minleri bırakıp da kafirlerin dostluğuyla (onur) duyanlar, şeref ve itibarı onların yanında mı arıyorlar? İyi bilin ki şeref ve itibar bütünüyle Allah`a aittir."},{"n":140,"t":"Allah vahyinde size şu talimatı indirdi: Ne zaman Allah`ın mesajlarının inkar edildiğini ve onların hafife alındığını duyarsanız, mevzu değişinciye kadar onlarla birlikte oturmamalısınız; değilse siz de onlar gibi olursunuz. Nitekim Allah ikiyüzlüleri ve inkarcıları, hep beraber cehennemde toplayacaktır."},{"n":141,"t":"Onlar sizin başınıza gelecekleri gözetlerler: Eğer Allah`tan size bir zafer erişirse \"Sizin yanınızda değil miydik?\" derler; yok eğer kafirlerin şansı yaver giderse bu sefer de (onlara) derler ki: \"Üzerinizde baskı kurup sizi teşvik ederek şu mü`minlerden kurtarmış olmadık mı?\" Fakat Allah Kıyamet Günü aranızda hükmünü verecek ve inkarcıların mü`minlere zarar vermelerine asla izin vermeyecektir."},{"n":142,"t":"İkiyüzlüler Allah`ı aldatmaya çalışıyorlar, oysa ki O onların aldanmalarını sağlıyor. Üstelik onlar namaza kalktıklarında, gönülsüzce, yalnızca insanlar görsün diye kalkarlar; Allah`ı ise pek az hatıra getirirler."},{"n":143,"t":"İki arada bir derede kalmışlardır; ne o tarafa ne de bu tarafa aittirler. Nitekim Allah`ın sapıklığını tescil ettiği kimseler için asla bir çıkış yolu bulamazsın."},{"n":144,"t":"Siz ey iman edenler! Mü`minleri bırakıp da kafirleri müttefik edinmeyin! Siz kendi aleyhinize, Allah`ın önüne açık bir delil mi koymak istiyorsunuz?"},{"n":145,"t":"Kuşku yok ki ikiyüzlüler ateşin en dibini boylayacaklar ve sen onlara yardım eden birini bulamayacaksın."},{"n":146,"t":"Ne ki tevbe edenler, gidişatını düzeltenler, Allah`a sımsıkı sarılanlar ve Allah`a itaatte samimi olanlar hariç; işte bunlar mü`minlerle birlikte olacaklar ve zamanı geldiğinde Allah mü`minlere muhteşem bir ödül verecek."},{"n":147,"t":"Eğer siz Allah`a şükreder ve iman ederseniz, Allah size azap edip de ne yapsın? Zira Allah şükredenlerin karşılığını her zaman veren ve her şeyi bilendir."},{"n":148,"t":"Allah, bir kötülüğün -ondan zarar gören hariç- açıkça söylenmesini sevmez; zira Allah her şeyi duyar, her şeyi bilir."},{"n":149,"t":"İyiliği -açık ya da gizli- yapar, kötülüğü de affederseniz (onu da bilir); unutmayın ki Allah çok bağışlayıcıdır, sınırsız kudret sahibidir."},{"n":150,"t":"Allah ile elçilerinin arasında ayrım yaparak Allah`ı ve elçilerini inkar edenlerle, \"bazılarına inanır bazılarını inkar ederiz\" diyerek iman ile inkar arasında bir yol tutturmak isteyenler var ya:"},{"n":151,"t":"işte gerçekten kafir olanlar bunlardır ve Biz kafirler için alçaltıcı bir azap hazırlamışızdır."},{"n":152,"t":"Fakat Allah`a ve elçilerine inanan ve elçiler arasında hiçbir ayrım yapmayanlara gelince: Zamanı geldiğinde Allah onlara ödüllerini tam olarak verecektir; çünkü Allah tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":153,"t":"Önceki vahyin takipçisi olan (Yahudiler), senden, gökten kendilerine özel bir kitap indirmeni istiyorlar. Onlar Musa`dan bundan daha büyüğünü istemişler ve \"Bize Allah`ı doğrudan göster!\" demişlerdi. Bu densizlikleri yüzünden yıldırım çarpmışa döndüler. Daha sonra kendilerine (tevhidin) apaçık belgeleri geldiği halde buzağı (heykeli)ne tapınmaya başladılar. Yine de onları bu günahlarından arındırmış, Musa`ya ise güçlü bir (nübüvvet) delili bahşetmiş"},{"n":154,"t":"ve Yüce Dağı (Sina) söz vermeleri için üzerlerine yükseltmiştik. Kendilerine \"Kapıdan (şükür) secdeleriyle girin!\" demiş ve \"Sebt`i ihlal etmeyin!\" uyarısında bulunmuştuk; üstelik kendilerinden sağlam bir taahhüt de almıştık."},{"n":155,"t":"İşte böylece, taahhütlerini çiğnedikleri Allah`ın mesajlarını reddettikleri, peygamberleri haksız yere öldürdükleri ve \"Kalplerimiz (bilgi ile) kaplıdır!\" dedikleri için (onları cezalandırdık). Bilakis Allah inkarlarından dolayı onların kalplerini mühürlemiştir ve işte onlar (bu nedenle) inanmazlar; çok azı müstesna."},{"n":156,"t":"Ve inkârları ve Meryem`e pek büyük bir iftira atmaları yüzündendir."},{"n":157,"t":"ve \"Allah`ın elçisi (olduğunu söyleyen) Meryem`in oğlu İsa Mesih`i işte biz öldürdük!\" demeleri nedeniyle... Aslında onu ne öldürdüler ne de çarmıha gerdiler, fakat (kafa karışıklığıyla) onlara öyle olmuş gibi geldi. Bu konuda farklı görüşler ileri sürenler ise, ondan dolayı gerçekten şaşkınlık içerisindedirler; onunla ilgili bir bilgileri yoktu ve yalnızca zanna dayanıyorlardı. Sonuç olarak kesinlikle onu öldürmediler:"},{"n":158,"t":"Bilakis, Allah onu kendi katına yüceltti. Zira Allah mutlak üstün ve yüce olandır, her hükmünde tam isabet sahibidir."},{"n":159,"t":"Nitekim (İsa`yı biz öldürdük diyen) kitap ehli Yahudilerden hiç kimse yoktur ki, onun ölümü arefesinde bu gerçeği tasdik etmiş olmasın. Zira Kıyamet Günü de o onlar aleyhine şahitlik yapacaktır."},{"n":160,"t":"Yahudileşenlerin işledikleri zulümlerden dolayı, önceden helal kılınan bir çok iyi ve temiz şeyden onları mahrum bıraktık. Nedeni ise, Allah yolundan sıkça sapıyor/saptırıyor olmalarıydı:"},{"n":161,"t":"mesela yasaklandığı halde faiz alıyorlar ve başkalarının malını haksız yere yiyorlardı. Neticede onlardan inkara gömülenler için şiddetli bir azap hazırladık."},{"n":162,"t":"Lakin içlerinde ilimde derinleşmiş olanlara, sana ve senden önce indirilene iman edenlere, özellikle de namazı istikamet üzre diriltenlere, zekatı gönülden gelerek verenlere, Allah`a ve Ahiret Günü`ne inananlara; işte bunlara, zamanı gelince muazzam bir ödül bahşedeceğiz."},{"n":163,"t":"Biz Nuh`a ve ondan sonraki tüm peygamberlere vahyettiğimiz gibi sana da vahyettik; yine İbrahim`e, İsmail`e, İshak`a, Yakub`a, (ondan türeyen israiloğlu) boylarına, İsa`ya, Eyyub`a, Yunus`a, Harun`a, Süleyman`a da vahyettik; üstelik Davud`a da Zebur`u verdik;"},{"n":164,"t":"tıpkı hem daha önce sana bildirdiğimiz elçiler, hem de bildirmediğimiz elçiler(e vahyettiğimiz) gibi; Allah`ın Musa`ya kelamını söylediği gibi..."},{"n":165,"t":"Onlar, müjdeli ve uyarıcı haber taşıyan elçiler; ki (o) elçilerden sonra insanın Allah karşısında bir mazereti bulunmasın: Allah zatında sonsuz izzet ve her hükmünde tam isabet sahibidir."},{"n":166,"t":"Lakin Allah, sana kendi ilminden indirdiğine bizzat şahitlik yapar ve melekler de şahitlik yaparlar: zaten şahid olarak Allah yeter."},{"n":167,"t":"İnkara sapan ve başkalarını Allah yolundan saptıranlara gelince: onlar derin bir sapıklığa gömülüp gitmişlerdir."},{"n":168,"t":"Küfre gömülen ve zulümde direnenleri Allah asla affetmeyecek ve onlara bir yol göstermeyecektir;"},{"n":169,"t":"sadece cehennemin yolunu (gösterecektir), orada ebediyyen kalıcıdırlar: ve bütün bunlar Allah için pek kolaydır."},{"n":170,"t":"Ey insanlık! İşte Peygamber size Rabbinizden hakikati getirdi: artık iman ederseniz sizin için hayırlı olur. Yok eğer hakikati inkar ederseniz, iyi bilin ki göklerde ve yeryüzünde olan her şey Allah`a aittir: zira Allah her şeyi bilendir, her hükmünde tam isabet kaydedendir."},{"n":171,"t":"Ey kitap ehli (olan Hıristiyanlar)! Dininizde haddi aşmayın ve Allah hakkında yalnızca hakkı söyleyin! Meryem oğlu İsa Mesih sadece Allah`ın elçisi, O`nun Meryem`e ilka ettiği kelimesi ve O`ndan bir ruhtur. Artık Allah`a ve peygamberlerine inanın ve \"Tanrı üçtür\" demeyin. Buna bir son verirseniz hakkınızda hayırlı olur. Allah tek ilahtır; çocuk sahibi olmaktan münezzehtir, göklerde ve yeryüzünde olan her bir şey O`na aittir; koruyucu otorite olarak Allah yeter."},{"n":172,"t":"Ne İsa Allah`a kul olmaktan kaçınacak kadar gurura kapılır, ne de kendisine yakın melekler. Ve Allah, kendisine kul olmaktan kaçınacak kadar küstahça bir gurura kapılan herkesi, Hesap Günü kendi katında toplayacaktır."},{"n":173,"t":"İman edip ıslah edici eylem ortaya koyanlara gelince: karşılıklarını tastamam kendilerine verecek, kendilerine lutfu kereminden artırdıkça artıracaktır. (O`na kulluktan) kaçınan ve küstahça bir gurura kapılanları, elim bir azaba mahkum edecek; onlar ne kendilerini Allah`a karşı koruyacak ve ne de yardımcı bulabileceklerdir."},{"n":174,"t":"Ey insanlık! Artık Rabbinizden size hakikatin belgesi geldi! Biz de size aydınlatıcı bir ışık gönderdik."},{"n":175,"t":"Allah`a iman eden ve O`nun (vahyine) sımsıkı sarılanlara gelince: Allah onları rahmet ve ihsanına gark edecek ve dosdoğru bir yolla Kendisine yöneltecektir."},{"n":176,"t":"Onlar senden açıklama istiyorlar. De ki: \"Allah, birinci dereceden mirasçısı olmayanlar hakkında size (şöyle) açıklama yapar: Eğer bir erkek, çocuk bırakmadan ölürse ve bir kız kardeşi varsa, onun terekesinin yarısına kız kardeşi sahip olacaktır; kız kardeşin çocuk bırakmadan ölmesi durumundaysa erkek onun mirasını alacaktır. Ama iki kız kardeş varsa, ikisi birden onun terekesinin üçte ikisine sahip olacaktır. Ve eğer erkek kardeşler ve kız kardeşler varsa erkek iki kadının payı kadar alacaktır. Allah bunları, (aksi halde) sapıtırsınız diye size açıklar. Sözün özü: Allah her şeyi sonsuz ilmiyle kuşatandır."}],[{"n":1,"t":"Siz ey iman edenler! Sözleşmelere sadakat gösterin! Size belirtilenler dışında, sığır cinsi hayvanlar size helal kılındı; ne ki ihramlıyken avlamanız helal değildir. Şüphesiz Allah razı olduğu şeyleri emreder."},{"n":2,"t":"Siz ey iman edenler! Allah`ın sembollerine, kutsal aya, gerdanları süslenmiş kurbanlıklara ve Rablerinin ihsan ve rızasını isteyerek Beytu`l-Haram`a koşanlara karşı saygısızlık etmeyin! Ancak, hac ile ilgili sorumlulukları yerine getirdiğiniz zaman avlanın! Sizi Mescid-i Haram`dan alıkoyanlara olan hıncınız, onlara saldırganlık yapmanıza yol açmasın; erdem ve takvada birbirinizle dayanışma içinde olun, günahkarca kötülük ve düşmanlıkta değil; artık Allah`a karşı sorumluluğunuzun bilincinde olun: Çünkü Allah`ın cezası pek çetindir."},{"n":3,"t":"Ölü hayvan, kan, domuz eti, Allah`tan başkası adına kesilenler; bir de boğulan, dövülerek öldürülen, düşerek ölen, boynuzlanarak öldürülen ya da vahşi bir hayvan tarafından parçalanan hayvanlar -henüz canlıyken kestikleriniz müstesnadır- ve putperestçe semboller üzerine kesilenler, ayrıca attığınız zarla geleceğe ilişkin kehanette bulunmak size haram kılınmıştır. Bütün bunlar birer sapmadır. Bugün, inkara saplananlar, dininiz(i terk edeceğiniz)den umutlarını tamamen kesmişlerdir: O halde, onları gözünüzde büyütüp de saygınlaştırmayın! Yalnız Beni tazim edip, Bana saygı duyun! Bugün dininizi sizin için kemale erdirdim ve size olan nimetimi tamamladım; ve (Allah`a) teslimiyeti sizin için hayat tarzı olarak benimsedim. Günaha gönüllü koşmaksızın kim hayati bir zaruretten dolayı zorda kalırsa, iyi bilsin ki Allah tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":4,"t":"Kendileri için neyin helal kılındığını sana soruyorlar. De ki: \"Temiz ve güzel olan her şey size helal kılındı.\" Allah`ın size öğrettiği bilgi sayesinde eğittiğiniz avcı hayvanlara gelince: onların sizin için avladığı her şeyi yiyin, ama üzerlerine Allah`ın adını da anın ve Allah`a karşı sorumluluğunuzun bilincinde olun; hiç şüphe yok ki Allah`ın hesap görüşü çok dakiktir."},{"n":5,"t":"Bugün, temiz ve güzel olan her şey size helal kılınmıştır. Üstelik, kendilerine daha önce vahiy gönderilmiş olanların yiyecekleri de size helaldir ve sizin yiyecekleriniz de onlara helaldir. Ve (son vahye) inanan iffetli kadınlar ile sizden önce kendilerine vahiy verilenlerin iffetli kadınları -kendilerine mali güvence vermeniz, onları meşru olmayan yolla ya da gizli dost tutma yöntemiyle değil de meşru bir akitle- nikahlamanız da (size helaldir). Kim imanı inkar ederse işte onun ameli boşa gitmiştir; üstelik o ahirette zarara uğrayanlar arasında yer alacaktır."},{"n":6,"t":"Siz ey iman edenler! Namaza kalkacağınız zaman yüzünüzü, ellerinizi ve dirseklere kadar kollarınızı meshedin ve bileklere kadar ayaklarınızı da (yıkayın ve/veya meshedin). Eğer cünüp olmuşsanız baştan ayağa temizlenin! Fakat eğer hastaysanız, ya da yolcuysanız, yahut doğal ihtiyacanızı gidermişseniz veya kadınlarla birlikte olmuşsanız ve su da bulamıyorsanız, o zaman temiz bir toprağa yönelerek onunla yüzlerinizi ve kollarınızı meshedin. Allah sizi zora sokmak istemez; fakat sizi pırıl pırıl yapmak ve nimetlerinin tamamını size bahşetmek ister ki şükredenlerden olasınız."},{"n":7,"t":"Ve hatırlayın Allah`ın size olan nimetini ve \"İşittik ve itaat ettik\" dediğiniz zaman Allah`a karşı kendinizi bağladığınız taahhüdü; Allah`a karşı da sorumluluğunuzun bilincinde olun: Kuşku yok ki Allah kalplerin içini bilir."},{"n":8,"t":"Siz ey iman edenler! Allah için, hakkı ayağa kaldırarak adaletin timsali olun ve birilerine olan nefretiniz sizi adaletten sapmaya sevk etmesin! Adil olun, bu Allah`ın koruması altına girmenin en kestirme yoludur: Artık Allah`a karşı sorumluluğunuzun bilincinde olun! Şüphe yok ki Allah bütün yaptıklarınızdan haberdardır."},{"n":9,"t":"Allah, inanan ve ıslah edici iyi işler yapanlara günahlarının affedileceğini ve muhteşem bir ödüle kavuşacaklarını vaad etmiştir."},{"n":10,"t":"İnkara saplanan ve mesajlarımızı yalanlayanlara gelince: işte onlardır cehennemlik olanlar."},{"n":11,"t":"Siz ey iman edenler! Hatırlayın Allah`ın üzerinizdeki nimetini! Hani size bir toplum el uzatmaya kalkışmıştı da, onların elinden sizi kurtarmıştı! Şu halde Allah`a karşı sorumluluğunuzun bilincinde olun! Ve mü`minler artık yalnızca Allah`a güvensinler."},{"n":12,"t":"İşte onlar arasından her deliğe girecek on iki kişiyi gönderdiğimiz zaman, Allah İsrailoğulları`ndan da kesin taahhüd almış ve buyurmuştu ki: Kuşkusuz Ben sizinleyin: Eğer salat`ı doğru-dürüst eda eder, arınmak için karşılıksız yardımda bulunur, düşmanlarını engelleyerek elçilerimi desteklerseniz; Allah`a da (güveninizi ispat etmek için) gönüllü olarak borç verirseniz, kesinlikle kötülüklerinizi örterim ve sizi zemininden ırmaklar çağlayan cennetlere koyarım. İçinizden her kim de bundan sonra inkar ederse, kesinlikle o doğru yoldan sapmış olur."},{"n":13,"t":"Daha sonra, bu kesin taahhütlerimi bozdukları için onları rahmetimizden dışladık ve kalplerini katılaştırdık; (şimdi onlar) kelimeleri bağlamlarından kopararak çarpıtıyorlar; üstelik kendilerine hatırlatılan hakikatlerden bir kısmını da unutmuş durumdalar. Çok azı dışında hep onların ihanetine uğrayacaksın. Onları bağışla ve hoş gör! İyi bil ki Allah güzel davrananları sever."},{"n":14,"t":"\"Biz Nesara`yız (Hristiyan)\" diyenlerden de kesin bir taahhüt almıştık; onların (takipçileri) de uyarıldıkları şeyden hisse kapmayı unuttular. Bu yüzden onları, aralarında Kıyamet Günü`ne kadar sürecek düşmanlık ve nefrete mahkum ettik. Zamanı gelince, Allah kendilerine yaptıkları her şeyi bir bir haber verecektir."},{"n":15,"t":"Ey önceki vahyin mensupları (olan Yahudiler)! Kitaptan gizlediğiniz bir çok hakikati size açıklamak ve (zaten bilinen) bir kısmından da geçmek üzere elçimiz gelmiştir. Artık size Allah`tan bir ışık ve net bir mesaj ulaşmıştır."},{"n":16,"t":"Onunla Allah, kendi rızasını gözetenleri ebedi kurtuluş yollarına ulaştırır; rahmetiyle onları karanlıklardan aydınlığa çıkarır ve dosdoğru bir yola yönlendirir."},{"n":17,"t":"\"Allah Meryem oğlu Mesih`tir\" diyenler, kesinlikle küfre saplanmışlardır. De ki: \"Eğer Meryem oğlu Mesih`i ve onun annesini ve yeryüzünde yaşayan herkesi helak etmek isteseydi kim Allah`a engel olabilirdi? Zira göklerin, yerin ve onlar arasındakilerin otoritesi dilediğini yaratan Allah`a aittir: ve Allah`ın gücü her şeye yeter!"},{"n":18,"t":"Yahudiler ve Hıristiyanlar \"Bizler Allah`ın çocukları ve can dostlarıyız!\" dediler. De ki: \"Öyleyse neden günahlarınız yüzünden sizi cezalandırıyor? Aksine siz O`nun yarattığı insanlardan sadece bir kısmısınız. O müstehak olanın bağışlanmasını diler, (cezayı) dileyeni de cezalandırmayı diler; zira göklerde, yerde ve her ikisi arasındaki şeylerin tümü üzerinde hükümranlık Allah`a aittir ve dönüş O`nadır."},{"n":19,"t":"Ey önceki vahyin takipçileri! Peygambersiz geçen uzun bir fetretin ardından \"Bize asla ne müjdecilerden biri geldi, ne de uyarıcılardan biri\" dersiniz diye, uyaran ve müjdeleyen Elçimiz, (hakikati) açıklamak üzere işte size de geldi; zira Allah`ın gücü her şeye yeter."},{"n":20,"t":"Bir zamanlar Musa halkına, \"Ey halkım! Allah`ın size lutfettiği nimeti hatırlayın ki, O aranızdan peygamberler çıkarmış, sizi kendi kendinizin efendisi kılmış ve başka hiçbir topluma vermediğini size vermişti."},{"n":21,"t":"Ey Halkım! Allah`ın size vaad ettiği kutsal topraklara girin, fakat sakın geri adım atmayın, yoksa kaybedenlerden olursunuz!\""},{"n":22,"t":"Onlar, \"Ey Musa!\" dediler; \"Unutma ki orada zorba bir halk var. Onlar oradan uzaklaşmadıkça biz kesinlikle oraya girmeyeceğiz; ama eğer uzaklaşırlarsa işte o zaman gireriz.\""},{"n":23,"t":"Allah`ın lutfuna mazhar olan ve O`ndan korkanlar arasından iki kişi, \"Onların üzerine (mertçe) kapıdan gidin!\" dediler; \"zira unutmayın, siz oraya girerseniz galip geleceksiniz. Eğer gerçek mü`minlerseniz, artık yalnızca Allah`a dayanmak zorundasınız.\""},{"n":24,"t":"Berikiler (ise) \"Ey Musa!\" dediler, \"onlar orada bulundukça, biz asla oraya girmeyeceğiz. O halde sen ve Rabbin gidip savaşın, biz işte şuracıkta oturuyoruz!\""},{"n":25,"t":"(Musa) \"Rabbim! Sözüm kendimden ve kardeşimden başkasına geçmiyor. O halde, bizimle şu sapkın halk arasındaki farkı gözet!\" diye yalvardı."},{"n":26,"t":"Allah şöyle icabet etti: \"O halde, onlar o topraklardan kırk yıl mahrum yaşayacak ve şaşkın şaşkın malum arazide dolaşmaya mahkum olacaklar: Artık bu sapkın halk için kendini üzme!\""},{"n":27,"t":"Ve onlara Adem`in iki oğlunun kıssasını gerçek bir amaca matuf olarak anlat: Hani, ikisi de birer kurban sunmuşlardı ve birinden kabul edildiği halde diğerinden kabul edilmemişti! (Bunun üzerine) O (diğerine) demişti ki: \"Çaresi yok, seni öldüreceğim!\" (Öteki) cevap vermişti: \"Allah, yalnızca sorumlu davrananların kurbanını kabul eder!"},{"n":28,"t":"Beni öldürmek için el kaldırsan bile, ben seni öldürmek için elimi oynatmayacağım; çünkü ben alemlerin Rabbi Allah`tan korkarım."},{"n":29,"t":"Dilerim, hem benim günahımı hem de (benden dolayı) kazandığın günahı yüklenir ve böylece cehennemin yolunu tutarsın: Zaten zalimlerin cezası da budur.\""},{"n":30,"t":"Fakat diğerinin benlik davası, onu kardeşini öldürmeye sevk etti; sonunda onu öldürdü, böylece kaybedenlerden oldu."},{"n":31,"t":"Bunun üzerine Allah, kardeşinin cesedini nasıl örteceğini göstersin diye toprağı eşeleyen bir karga gönderdi. \"Eyvah, yazıklar olsun bana!\" dedi, \"ben bu karganın yaptığını yapamayacak, kardeşimin cesedini örtemeyecek kadar aciz biri miyim?\" En sonunda pişman olmuştu."},{"n":32,"t":"Bundan dolayı Biz İsrailoğullarına şöyle vahyetmiştik: Kim cinayet suçu işlememiş veya yeryüzünde fesat çıkarmamış bir kişiyi öldürürse bütün insanlığı öldürmüş gibi olur. Dahası kim de bir hayat kurtarırsa, bütün insanlığı kurtarmış gibi olur. Elçilerimiz onlara hakikatin tüm delilleriyle gelmiştiler; fakat daha sonra onların çoğu yeryüzünde her tür taşkınlığı irtikap ettiler."},{"n":33,"t":"Allah`a ve Rasulü`ne karşı savaş açanların ve yeryüzünde bozgunculuğu yaymaya çalışanların öldürülmeleri ya da asılmaları veya muhalefetlerinden dolayı ellerinin ve ayaklarının kesilmesi, yahut bulundukları yerden sürülmeleri, sadece (adil) bir karşılıktan ibarettir. Bu, onların dünyada uğradıkları zillettir; ahirette ise korkunç bir azap beklemektedir;"},{"n":34,"t":"ancak siz onlara hakim olmadan önce tevbe edenler hariç: Zira iyi bilin ki Allah tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":35,"t":"Siz ey iman edenler! Allah`a karşı saygılı olun ve O`na yaklaşma çabası içinde bulunun ve O`nun yolunda tüm gayretinizi harcayın ki kurtuluşa erebilesiniz."},{"n":36,"t":"Kuşkusuz inkarda direnenler, eğer yeryüzündeki her şeyi, hatta onun iki katını Kıyamet Günü`nün azabından kurtulmak için fidye olarak verseler asla kabul ettiremezler. Can yakıcı bir azap onları bekler."},{"n":37,"t":"Ateşten çıkmak isterler; fakat asla oradan çıkacak değiller; ve sürekli bir azaba mahkum edilirler."},{"n":38,"t":"İmdi, işledikleri suça karşılık Allah`tan ibret-i alem bir müeyyide olarak hırsızlık yapan erkek ve hırsızlık yapan kadının ellerini kesin. Zira Allah her işinde mükemmeldir, her hükmünde tam isabet sahibidir."},{"n":39,"t":"Bu zulmü işledikten sonra kim tevbe eder ve kendini düzeltirse, elbet Allah da onun tevbesini kabul eder; zira Allah tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":40,"t":"Bilmez misin ki göklerin ve yerin otoritesi Allah`a aittir; O dileyeni cezalandırmayı, dileyeni de bağışlamayı diler: tabii ki Allah`ın gücü her şeye yeter."},{"n":41,"t":"Ey Peygamber! Yürekten iman etmedikleri halde ağızlarıyla \"iman ettik\" diyen kimseler arasından inkarda birbirleriyle yarışanlar seni üzmesin; Yahudileşenler arasından yalanı can kulağıyla dinleyen ve sana başvurmak yerine başka insanların laflarına kulak kesilenler de.. Onlar, sözleri asıl bağlamlarından kopararak manalarını çarpıtırlar, \"Eğer size şu tür bir öğreti verilirse hemen alın; yok verilmezse sakın yaklaşmayın!\" derler. Allah birini fitneye sokmayı dilemişse, Allah`ın onun hakkındaki iradesine hiçbir şekilde engel olamazsın. İşte onlar, Allah`ın kalplerini temizlemek istemediği kimselerdir; onları dünyada zillet, ahirette korkunç bir azap bekler."},{"n":42,"t":"Onlar yalana kulak kesilir, haram adına ne varsa ona yumulurlar. İmdi eğer sana başvururlarsa; ister aralarında hüküm ver, ister onları kendi hallerine bırak. Zira eğer onları kendi hallerine bırakacak olursan, sana hiçbir zarar veremezler. Ama eğer hüküm verecek olursan aralarında adaletle hükmet: çünkü Allah adil olanları sever."},{"n":43,"t":"Yanlarında Tevrat ve onda da Allah`ın hükmü bulunduğu halde seni nasıl hakem tutuyorlar ve daha sonra da o hükümden yüz çeviriyorlar? İşte böyleleri, gerçek mü`min de değildirler."},{"n":44,"t":"Şüphe yok ki, kendisinde rehberlik ve ışık bulunan Tevrat`ı Biz indirdik. Hepsi de Allah`a teslim olmuş bulunan peygamberler, Yahudi olanlara onunla hükmetmişlerdi; Allah kelamından bir kısmı kendi korumalarına bırakıldığı için, Allah`a adanmış adamlar ve hahamlar da öyle yapmışlardı; hepsi de ona şahit idiler. O halde (Ey Yahudileşen İsrailoğulları), gözünüzde büyüttüğünüz insanlardan korkmayın, Benden korkun! Ayetlerimi az bir menfaat karşılığı pazarlamayın! Zira Allah`ın indirdiğiyle hükmetmeyenler kafirlerin ta kendileridirler."},{"n":45,"t":"Onlara orada şöyle yazdık: Cana can, göze göz, buruna burun, kulağa kulak, dişe diş ve yaralamalarda eş değer bir karşılık; fakat kim de onu bağışlarsa, o kendi günahlarına keffarettir. Ama Allah`ın indirdiğiyle hükmetmeyenler zalimlerin ta kendileridirler."},{"n":46,"t":"Ve ardından onları izdüşümü olarak Meryem oğlu İsa`yı, Tevrat`tan geriye kalanların doğruluğunu tasdik edici olarak gönderdik. Yine Biz kendisinde rehberlik ve ışık olan, muttakilere bir rehber ve bir öğüt olarak Tevrat`tan geriye kalan hakikatleri onaylayan İncil`i verdik."},{"n":47,"t":"İncil`e inananlar da, Allah`ın onda indirdikleriyle hükmetsinler. Zira her kim Allah`ın indirdiğiyle hükmetmezse işte onlar fasıkların ta kendileridir."},{"n":48,"t":"Sana da, hakikatin ifadesi olan bu Kitabı, geçmiş vahiyden geriye kalan hakikatleri doğrulayıcı ve onların doğrusunu yanlışından ayırt edici olarak gönderdik. O halde artık onların aralarında Allah`ın indirdiklerine uygun olarak hüküm ver; sana gelen hakikati bırakarak onların keyfi yargılarına uyma! Sizden her biriniz için bir şeriat ve (onu) uygulama yöntemleri belirledik. Eğer Allah dileseydi, hepinizi tek bir topluluk yapardı; fakat size emanet ettikleriyle sizi sınamak için (öyle yapmadı): O halde hayırlarda birbirinizle yarışın! Topyekün dönüşünüz Allah`adır: işte o zaman Allah ihtilaf ettiğiniz şeyleri size bir bir haber verecektir."},{"n":49,"t":"Ve Sen aralarında Allah`ın indirdiğine uygun olarak hükmet! Onların keyfi yargılarına da uyma! Allah`ın sana gönderdiklerinden bir kısmında seni yanıltmalarından sakın! Eğer yüz çevirmekte ısrar ederlerse, iyi bil ki Allah onları birtakım günahlarından dolayı cezalandırmak istiyor. Unutmayın ki insanların çoğu yoldan çıkmıştır."},{"n":50,"t":"Yoksa onlar cahiliye yasasını mı istiyorlar? Aklı başında bir toplum için, Allah`tan daha iyi yasa yapıcı olabilir mi?"},{"n":51,"t":"Siz ey iman edenler! Yahudileri ve Hıristiyanları müttefik edinmeyin! Onlar birbirlerinin müttefikidir. Sizden her kim onları müttefik edinirse, o onlardan olur. Şüphesiz Allah zulme gömülmüş bir topluma rehberliğini bahşetmez."},{"n":52,"t":"Kalplerinde hastalık bulunanların, \"İşlerin ters gidip başımıza bir şey gelmesinden korkarız\" diyerek, ötekilerin işine yarayacak bir tavır sergilemekte yarıştıklarını görürsün. Belki Allah bir zafer verir ya da O`nun katından bir talimat gelir de, içlerinde sakladıkları düşüncelerden dolayı vicdan azabı çekmeye başlarlar."},{"n":53,"t":"İman edenler de (birbirlerine) derler ki: \"Var güçleriyle, sizinle beraber olacaklarına dair yemin edenler bunlar mı? Onların bütün çabaları boşa gitmiştir; sonuçta kaybeden onlar olmuştur.\""},{"n":54,"t":"Siz ey iman edenler! İçinizden her kim dininden dönerse, iyi bilsin ki Allah zaman içerisinde onun yerine başka bir topluluk getirir; O onları sever, onlar da O`nu; mü`minlere karşı alçakgönüllü, kafirlere karşı onurlu davranırlar; Allah yolunda tüm çabalarını sergiler, kınayacak olanın da kınamasından korkmazlar: İşte bütün bu özellikler Allah`ın isteyene bahşetmeyi dilediği lutfudur. Zira Allah engin (lütuf) sahibidir, her şeyi ayrıntısıyla bilendir."},{"n":55,"t":"Yalnızca Allah, O`nun Elçi`si ve inananlardır sizin müttefikiniz. O inananlar ki, namazı hakkını vererek kılarlar, zekatı gönülden gelerek verirler; çünkü onlar Allah`a boyun eğerler."},{"n":56,"t":"Allah`a, Rasulü`ne ve inananlara müttefik olanlar var ya: işte onlardır Allah taraftarı olanlar: galip gelecek olan da onlardır."},{"n":57,"t":"Siz ey iman edenler! Gerek önceki vahyin mensuplarından, gerekse (vahyi) inkar edenlerden dininizi hafife alan ve inancınızla oynayanları müttefik edinmeyin. Eğer gerçekten inanıyorsanız Allah`a karşı saygılı olun."},{"n":58,"t":"Onları salat`a çağırdığınız zaman, onu hafife alırlar ve oyun ederler. Bu, onların kafalarını kullanmayan bir topluluk olduğunu göstermektedir."},{"n":59,"t":"De ki: Ey önceki vahyin mensupları! Şimdi biz yalnızca Allah`a, bize ve bizden önce indirilen vahiylere iman ettik diye kusur mu işledik? Çoğunuzun yoldan çıktığı kesin bir gerçektir."},{"n":60,"t":"De ki: Allah katında, bunlardan daha beter bir cezayı hak edenleri size söyleyeyim mi? Onlar Allah`ın lanet ve gazabına uğrayanlardır; şeytani güçlere kul oldukları için maymuna ve hınzıra benzettikleridir. En şerli konumda bulunanlar ve doğru yoldan en çok sapanlar işte bunlardır."},{"n":61,"t":"Onlar sana geldiklerinde \"inandık\" derler; oysa ki onlar gerçekte inkarla gelirler ve yine onunla ayrılırlar. Fakat Allah onların gizlediklerini çok iyi bilmektedir."},{"n":62,"t":"Onların çoğunun günahta, saldırganlıkta ve haramilikte yarıştıklarını görürsün; yaptıkları şey pek fenadır."},{"n":63,"t":"Onların din adamları ve hahamları, onları günahkarca düşüncelerden ve haram yemekten alıkoysalardı ya? İşledikleri şey ne kötüdür."},{"n":64,"t":"Yahudiler, \"Allah`ın eli sıkıdır!\" dediler; sıkılaştı elleri ve bu düşüncelerinden dolayı rahmetten dışlandılar. Aksine O`nun iki eli de sonsuzca açıktır, (lutfunu) dilediği gibi dağıtır. Fakat Rabbinden sana indirilen, onların küstahça azgınlığını ve inatçı inkarlarını daha da artıracaktır. Ve Biz onların arasına Kıyamet Günü`ne kadar sürecek olan kin ve nefret tohumları saçmışızdır. Ne zaman savaş ateşi yaksalar Allah onu söndürür; zira onlar yeryüzünde çürüme ve yozlaşmayı yaymak için çırpınırlar, Allah ise çürüme ve yozlaşmaya neden olanları sevmez."},{"n":65,"t":"Eğer önceki vahyin mensupları iman etmiş ve sorumluluk bilinciyle hareket etmiş olsalardı, kesinlikle onların kötülüklerini örter ve kendilerini sonsuz nimetler diyarı cennetlere koyardık."},{"n":66,"t":"Eğer onlar Tevrat`ı, İncil`i ve kendilerine Rableri tarafından indirilenleri uygulamış olsalardı, gökten ve yerden gelen tüm nimetlerden yararlanırlardı. Onlardan doğru, adil bir yol tutturanlar var. Çoğuna gelince: ne berbat şeyler yapıyorlar!"},{"n":67,"t":"Ey Peygamber! Rabbinden sana indirilen hakikati tebliğ et! Eğer bunu (tam) yapmazsan, O`nun mesajını (hiç) tebliğ etmemiş olursun. Allah seni insanlar(ın saldırısın)dan koruyacaktır. Kuşku yok ki Allah nankörlüğe (ittifak etmiş) bir topluma rehberliğini bahşetmez."},{"n":68,"t":"De ki: \"Ey önceki vahyin mensupları! Tevrat`ı, İncil`i ve Rabbinizden size indirilenleri tam uygulamadıkça siz hiçbir şey değilsiniz! Öte yandan, elbette Rabbinden sana indirilenler onlardan bir çoğunun küstahça taşkınlığını ve inkarını artıracaktır: Artık kafir bir toplum için üzülme!"},{"n":69,"t":"Çünkü (bu mesaja) inanan kimseler, Yahudiler, Sabiiler ve Hıristiyanlardan, Allah`a ve Ahiret Günü`ne inanan, ıslah edici iyi işler işleyen hiç kimse, gelecekten endişe ve geçmişten dolayı üzüntü duymayacaktır."},{"n":70,"t":"Doğrusu, Biz İsrailoğulları`ndan söz almış ve kendilerine elçiler göndermiştik. Elçi(ler) onların hoşlanmadığı bir mesajla geldiği zaman bir kısmını yalanladılar bir kısmını ise öldürdüler."},{"n":71,"t":"Zira kendilerine bir bela gelmeyeceğini sanarak kör ve sağır davrandılar. Sonra Allah onların tevbelerini kabul etti. Bunun ardından onların çoğu yine körleşti ve sağırlaştı: ama Allah yaptıkları her şeyi görmektedir."},{"n":72,"t":"Doğrusu, \"Allah Meryem oğlu Mesih`in ta kendisidir!\" diyenler küfre girmiştir. Üstelik Mesih \"Ey İsrailoğulları, hem benim hem de sizin Rabbiniz olan Allah`a kulluk edin!\" dediği halde. Bakın, kim Allah`a şirk koşarsa kesinlikle Allah ona cenneti haram kılar. Onun varacağı yer ateştir: zalimler bir yardımcı da bulamayacaklar."},{"n":73,"t":"Doğrusu, \"Allah üçün üçüncüsüdür\" diyenler küfre girmiştir. Oysa bir tek Allah`tan başka ilah yoktur. Bu iddialarına son vermedikçe, hakikati inkar eden bu gibilerin başına şiddetli bir azap gelecektir."},{"n":74,"t":"Hala Allah`a yönelip O`ndan af dilemeyecekler mi? Zira Allah tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":75,"t":"Meryem oğlu Mesih, yalnızca bir elçidir; ondan önce de elçiler gelip geçmiştir. Onun annesi iffetliydi; her ikisi de bildik yiyeceklerle beslenen (ölümlü insanlardı). Bak, Biz mesajları onlara nasıl açıklıyoruz; ve yine bak, onlar hakikati nasıl tersyüz ediyorlar!"},{"n":76,"t":"De ki: \"Allah dışında, size hiçbir zarar veremeyen ve yarar sağlamayan kimselere de mi tapıyorsunuz? Oysa yalnız Allah`tır her şeyi bütünüyle işiten, her şeyi tamamıyla bilen.\""},{"n":77,"t":"Ey Kitap Ehli! Akidenizde hakikatin sınırlarını çiğnemeyin. Daha önce kendileri sapmış, bir çoklarını da saptırmış olan ve yoldan çıkmakta hala direnen bir topluluğun keyfi yargılarına uymayın!"},{"n":78,"t":"İsrailoğullarından nankörlükte ısrar edenler, Davud`un ve Meryem oğlu İsa`nın diliyle lanetlenmişlerdir. Bu, onların isyankarlıkları ve sürekli taşkınlık yapmaları yüzündendir."},{"n":79,"t":"Onlar birbirlerini, yapageldikleri kötülüklerden caydırmaya çalışmıyorlardı; gerçekten bu yaptıkları ne fena şeydi."},{"n":80,"t":"Onlardan bir çoğunu küfre saplananlarla sarmaş-dolaş görürsün. Ayartıcı benliklerin kendilerine telkin ettiği şey öylesine kötüdür ki, Allah`ın hışmına uğramışlardır; ve onlar azaba mahkum olacaklardır."},{"n":81,"t":"Eğer bu (Yahudiler) Allah`a, Peygamber`e ve ona indirilene inanmış olsalardı, o (Müşrikleri) müttefik edinmezlerdi. Ne ki, bunlardan çoğu yoldan sapmıştır."},{"n":82,"t":"Kesinlikle bütün insanlar içerisinde, (bu mesaja) iman edenlere karşı en çok düşmanlık yapanların Yahudiler ve Allah`a şirk koşanlar olduğunu görürsün. Yine onlar içerisinden (bu mesaja) iman edenlere en yakın olanların da, \"Biz Nasara`yız\" diyenler olduğunu görürsün. Bunun nedeni, onların arasında böbürlenmeyen keşişlerin ve rahiplerin bulunuyor olmasıdır."},{"n":83,"t":"Onlar Peygamber`e indirileni işittiklerinde, ondaki hakikatleri kavradıkları için gözyaşlarının çağladığını görürsün. Derler ki: \"Rabbimiz! İnandık biz: o halde bizi de hakka şahit olanlarla birlikte yaz!"},{"n":84,"t":"Neden Allah`a ve bize gönderilen hakikate inanmayalım ki? Zira biz, Rabbimizin bizi erdemliler arasına katmasını dileriz!\""},{"n":85,"t":"Ve Allah da onları, bu inançlarından dolayı zemininden ırmaklar çağlayan cennetlerle ödüllendirdi, orada karar kılacaklar: işte budur iyilerin ödülü."},{"n":86,"t":"Küfre saplananlara ve mesajlarımızı yalanlayanlara gelince: onlar, yakıcı ateşe mahkumdurlar."},{"n":87,"t":"Siz ey iman edenler! Allah`ın size helal kıldığı temiz ve güzel şeylerden kendinizi mahrum etmeyin, fakat sınırları da aşmayın; unutmayın ki Allah haddi aşanları sevmez."},{"n":88,"t":"O halde, Allah`ın size sunduğu rızıkların helal ve temiz olanlarından yararlanın ve kendisine iman ettiğiniz Allah`a saygılı olun!"},{"n":89,"t":"Allah, düşüncesizce ağzınızdan kaçırdığınız yeminler hususunda sizi sorumlu tutmaz. Fakat bilinçli olarak yaptığınız yeminlerden sorumlu tutacaktır. Bu tür yeminleri bozmanın karşılığı, kendi ailenize ikram ettiğinizin ortalamasıyla on yoksulu doyurmak ya da giydirmek veya bir insanı özgürlüğe kavuşturmaktır; bunu bulamayan kimse ise üç gün oruç tutar. Bozduğunuz yeminlerin keffareti budur: öyleyse yeminlerinize sadık olun! Allah size ayetlerini böyle açıklar ki, şükredebilesiniz."},{"n":90,"t":"Siz ey iman edenler! Sarhoşluk veren her şey, tüm şans oyunları, Allah`tan başkasına kurban sunmak ve gelecek hakkında kehanette bulunmak şeytan işi pisliklerden başka bir şey değildir. O halde bunlardan kaçının ki ebedi mutluluğa erişebilesiniz."},{"n":91,"t":"Şeytan sarhoşluk veren şeyler ve şans oyunlarıyla sizin aranıza düşmanlık ve kin tohumları saçmaktan, Allah`ı anmak ve namazdan alıkoymaktan başka bir şey istemez: öyleyse siz, hala vazgeçmeyecek misiniz?"},{"n":92,"t":"Şu halde Allah`a itaat edin, Peygamber`e itaat edin ve (kötülükten) sakının! Eğer yüz çevirirseniz, iyi bilin ki Elçi`mizin görevi mesajı apaçık tebliğ etmekten ibarettir."},{"n":93,"t":"İman edip salih amel işleyenler, takva ehli oldukları, iman edip salih amel işlemeye devam ettikleri sürece, önceden tattıklarından dolayı sorumlu tutulmayacaklardır; yeter ki takvada ve imanda, dahası, takvada ve iyilikte kararlı olsunlar: Zira Allah iyileri sever."},{"n":94,"t":"Siz ey iman edenler! Elbette Allah, ellerinizin ve silahlarınızın menziline giren avı yasaklayarak, aşkın olan zatından yalnızken dahi korkanları seçip ayırmak için sizi sınayacak. Kim bundan sonra haddi aşarsa, işte onu acıklı bir azap bekler."},{"n":95,"t":"Siz ey iman edenler! Hac için ihrama girdiğinizde av hayvanı öldürmeyin! Sizden kim kasıtlı olarak onu öldürürse, adil iki kişinin takdiriyle öldürdüğünün eş değerdeki hayvanı kurban edilmek üzere Kabe`ye getirerek öldürdüğüne denk bir bedel öder. Ya da yoksulları doyurmak veya ona denk olacak kadar oruç tutmak suretiyle günahının keffaretini öder. Ve (böylece) yaptığı işin vebalini hisseder. Allah geçmişi silmiştir; fakat kim yeniden işlerse, Allah ona yaptığının acısını tattırır. Zira Allah şerefin kaynağıdır, kimsenin yaptığını yanına kar bırakmayandır."},{"n":96,"t":"Sularda yapılan her tür avlanma ve onunla beslenme sizin için helaldir. Bu, sizin de yolcuların da yararınadır. Fakat, ihramlı olduğunuz sürece kara avı size yasaklanmıştır. Şu halde, topyekün huzuruna varacağınız Allah`a karşı sorumluluğunuzun bilincine varın!"},{"n":97,"t":"Allah, Beytu`l-Haram olan Kabe`yi bütün insanlık için bir kıyam (sembolü) kıldı; Ve Haram ay ile boyunları bağlı ve bağsız kurbanlıkları da (sembol kıldı). Bu, Allah`ın göklerde ve yerde olan her şeyden haberdar olduğunu ve Allah`ın her şeyin bilgisine vakıf olduğunu bilesiniz diyedir."},{"n":98,"t":"İyi bilin ki Allah cezalandırmada pek şedittir; yine unutmayın ki, Allah tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":99,"t":"Elçinin görevi, mesajı apaçık tebliğ etmekten başka bir şey değildir. Zira Allah açığa vurduklarınızı da gizlediklerinizi de bilmektedir."},{"n":100,"t":"De ki: Kötü ve çirkin olan şeylerle iyi ve güzel olan şeyler eşdeğerde olamaz; kötünün çokluğu hoşuna gitse bile. O halde ey derin kavrayış sahipleri: Allah`a karşı sorumluluğunuzun bilincinde olun ki kalıcı mutluluğa erebilesiniz!"},{"n":101,"t":"Siz ey iman edenler! Açıklanması halinde sizi zora sokabilecek şeyler hakkında soru sormayın! Nitekim Kur`an iniyorken onlar hakkında soru sorarsanız size açıklarız. (Açıklanmadığına göre), Allah onlarla sizi mükellef tutmamıştır. Allah tarifsiz bir bağışlayandır, acele cezalandırmayandır."},{"n":102,"t":"Sizden önceki insanlar da bu türden sorular sormuşlar, en sonunda hakkı inkara kadar varmışlardı."},{"n":103,"t":"Ne bahira ve saibe, ne de vasile ve ham (adı altında, hayvanların batıl inançlarla yaratılış amacı dışına çıkarılmaları) Allah`ın emri değildir. Fakat hakikati inkarda ısrar edenler, kendi uydurdukları yalanları Allah`a yakıştırıyorlar. Zira onların çoğu kafalarını kullanmıyorlar."},{"n":104,"t":"Ve onlara \"Allah`ın indirdiğine ve Peygamber`e gelin!\" denildiğinde, \"Atalarımızı üzerinde bulduğumuz inanç bize yeter!\" diyorlar. Ya ataları hiçbir şey bilmeyen ve doğru yolda olmayan kimseler idiyse de mi?"},{"n":105,"t":"Ey iman edenler! Siz kendinizden sorumlusunuz. Eğer doğru yoldaysanız, sapıtanlar size zarar veremez. Hepinizin dönüşü Allah`adır: işte o zaman yaptıklarınızı size bir bir haber verecektir."},{"n":106,"t":"Siz ey iman edenler! Ölüm size yaklaştığında yapacağınız vasiyet sırasında şahitler bulundurun: Kendi aranızdan dürüst iki kişi, ya da seyahatteyken ölüm emareleri gelip sizi bulursa, (adil şahitliğe) davetten sonra, sizden olmayan öteki iki kişiyi alıkoyun; eğer içinize bir kuşku düşerse onlara Allah adına şöyle yemin ettirin: \"Akraba hatırına da olsa, hiçbir bedel karşılığında sözümüzü satmayacağız ve Allah`ın bildiğini gizlemeyeceğiz; eğer böyle yaparsak günahkar biz olmuş oluruz."},{"n":107,"t":"Ama bu iki şahidin sonradan bu tür bir günah işledikleri ortaya çıkarsa, bu iki kişinin hakkını çiğnediği taraftan başka iki kişi onların yerini alır ve Allah adına şöyle yemin eder: \"Bizim şahitliğimiz ötekilerin şahitliğinden daha doğrudur, zira biz hakka tecavüz etmedik; eğer böyle yaparsak bu kez de zalim biz olmuş oluruz.\""},{"n":108,"t":"Bu (hüküm), şâhidliği lâyıkıyla yapmalarına veya yeminlerinden sonra (vârisler tarafından) yeminler(in)in reddedilmesinden korkmalarına en yakın bir çâredir. Artık Allah’dan sakının ve (emirlerini) dinleyin! Çünki Allah, (isyanlarındaki ısrarları yüzünden) fâsıklar topluluğunu hidâyete erdirmez."},{"n":109,"t":"Allah bütün peygamberleri topladığı gün, onlara \"Size ne cevap verildi?\" deye soracak. Onlar, \"Bizim bir bilgimiz yok, yaratılmışların idrakini aşan her şeyi tümüyle bilen yalnız Sensin!\" diyecekler."},{"n":110,"t":"İşte o zaman Allah diyecek ki: \"Ey Meryem oğlu İsa: sana ve annene bahşettiğim nimetimi hatırla! Hani, seni Kutsal Ruh ile desteklemiştim; insanlarla beşikte iken de erişkin iken de konuşuyordun! Hani, Ben sana vahyi ve hikmeti; yani Tevrat ve İncil`i talim ettirmiştim! Hani sen Benim iznimle çamurdan kuş maketi yapıyor, ona üflüyor ve o da Benim iznimle kuş oluveriyordu. Ve nasıl iznimle körleri ve cüzzamlıları iyileştiriyor ve yine iznimle ölüleri ayağa kaldırıyordun! Hani sen İsrailoğullarına hakikatin bütün delilleriyle; yani onlardan nankörlükte ısrar edenler \"Bu sihirden başka bir şey değildir\" dedikleri zaman, sana zarar vermelerine mani olmuştum!"},{"n":111,"t":"Ve hani, havarilere (senin aracılığınla) \"Bana ve Benim elçime inanın!\" diye vahyetmiştim; onlar da \"Biz inanıyoruz, Sana kayıtsız şartsız teslim olduğumuza şahit ol!\" demişlerdi."},{"n":112,"t":"Yine o zaman havariler \"Ey Meryem oğlu İsa!\" demişlerdi; \"Rabbin bize gökten bir sofra indirebilir mi?\" (İsa) cevap vermişti: Eğer gerçekten inanıp güveniyorsanız Allah`a karşı saygılı olmalısınız!\" demişti."},{"n":113,"t":"Onlar, \"Biz ondan yemek, kalplerimizi tatmin etmek, bize hakikati söylediğini bilmek ve o hakikete biz de şahitlik yapmak isteriz\" dediler."},{"n":114,"t":"Meryem oğlu İsa dedi ki: \"Ey Allah`ım Rabbimiz! Gökten bize bir sofra gönder: o, bizim için ilkimizden sonuncumuza kadar sürekli bir sevinç ve Senden bir işaret olacaktır. Ve bize rızkımızı ver, zira rızık verenlerin en hayırlısı sensin."},{"n":115,"t":"Allah buyurdu ki: \"Ben onu size gönderebilirim; ancak ondan sonra içinizden kim nankörlük ederse, iyi bilin ki onu akıllı varlıklar âleminde kimseyi çarptırmadığım bir azaba çarptıracağım!\""},{"n":116,"t":"Ve işte o zaman Allah \"Ey Meryem oğlu İsa!\" dedi, \"Sen insanlara `Allah`ın dışında, O`nun astı olarak beni ve annemi ilah edinin` mi dedin? Cevap verdi: \"Zatını tenzih ederim! Kendim için hakkım olmayan bir şeyi söylemek bana yakışmaz. Bunu söylemiş olsaydım elbette Sen bilirdin. Sen benim sırrıma erersin, fakat ben Senin sırrına eremem. Şüphesiz yaratılmışların idrakini aşan her şeyi bilen yalnızca Sensin."},{"n":117,"t":"Ben onlara bana emrettiğin, \"Benim Rabbim ve sizin Rabbiniz olan Allah`a kulluk edin!\" demekten başka bir şey söylemedim. Ve onların arasında yaşadığım sürece yaptıklarına şahitlik ettim. Fakat ne zaman ki Sen benim canımı aldın, artık onların gözetleyicisi yalnızca Sen oldun. Zaten Sen, her bir şeye ta özünden şahitsin."},{"n":118,"t":"Eğer onlara azab edersen, şüphe yok ki onlar Senin kullarındır; yok eğer onları bağışlarsan, hiç şüphesiz her işinde mükemmel olan tek Sensin, her hükmünde tam isabet eden de yalnız Sen!\""},{"n":119,"t":"(O gün) Allah şöyle diyecek: \"Bugün, sözlerine sadık olanların sadaketlerinin hayrını görecekleri gündür. Zemininden ırmaklar çağlayan, içinde ebedi kalacakları cennetler onlarındır. Allah onlardan razı, onlar da Allah`tan razıdırlar: İşte bu muhteşem bir başarıdır."},{"n":120,"t":"Göklerin, yerin ve içindekilerin hükümranlığı Allah`a aittir! Zira O her şeyi yapmaya kadirdir."}],[{"n":1,"t":"Bütün hamd gökleri ve yeri yaratan, karanlıkları ve aydınlığı var eden Allah`a mahsustur. Buna rağmen tevhid hakikatini inkar edenler, başkalarını Rablerine denk tutarlar."},{"n":2,"t":"O`dur sizi balçıktan yaratan, sonra bir ömür tayin eden; yalnızca O`nun bildiği bir ömür. Fakat hala tereddüt içinde bocalıyorsunuz."},{"n":3,"t":"Oysa O, göklerde de yerde de Allah`tır; gizlediğinizi de açığa vurduğunuzu da bilir; dahası bütün işlediklerinizle neyi kazandığınızın da farkındadır."},{"n":4,"t":"Ne zaman Rablerinden ayetlerinden bir ayet gelmişse, ondan yüz çevirmişlerdir."},{"n":5,"t":"Ve kendilerine gelen hakikati yalanlamışlardır. Yakında onlar, alay ettikleri şeyin ne olduğunu öğrenecekler."},{"n":6,"t":"Görmezler mi kendilerinden önceki nice nesilleri helak ettiğimizi? Onları, sizi yerleştirmediğimiz verimli yurtlara yerleştirmiştik, üzerlerine semadan mütemadiyen rahmet göndermiştik, ayaklarının altından çağlayan ırmaklar var etmiştik. Ama sonunda onları günahlarından dolayı helak ettik ve onların yerine başka nesiller var ettik."},{"n":7,"t":"Eğer sana yazılı bir metin indirseydik ve ona elleriyle dokunmuş olsalardı dahi, inkarda direnenler ısrarla derlerdi ki: \"Bu apaçık bir sihirden başka şey değildir!\""},{"n":8,"t":"Bir de, \"Ona bir melek indirilseydi ya!\" derler. Ama eğer melek indirmiş olsaydık, iş bitirilmiş olurdu ve bir daha da fırsat tanınmazdı."},{"n":9,"t":"Ama Biz bir melek göndermiş olsaydık, yine de onu insan kılığında gönderirdik; böylece şimdi içine düştükleri şaşkınlığa onları yine düşürürdük."},{"n":10,"t":"Doğrusu senden önceki elçilerle de alay edildi. Ama onlarla alay edenler, alay ettikleri gerçek tarafından kuşatılıp yok edildiler."},{"n":11,"t":"De ki: \"Dolaş yeryüzünü, sonra görün gerçeği yalanlayanların sonunun ne olduğunu!\""},{"n":12,"t":"\"Kime aittir göklerde ve yerdeki her şey?\" diye sor! \"Kendisine rahmeti prensip edinen Allah`a\" diye cevap ver! Geleceğine dair hiçbir kuşku bulunmayan Kıyamet Günü`nde, elbet hepinizi bir araya toplayacaktır. Kendisini kaybeden kimselere gelince: onlar artık iman etmezler."},{"n":13,"t":"Oysa ki, gecenin ve gündüzün koynunda yatan her şey O`na aittir; ve yalnızca O`dur duyulmayanı duyan, varlığın sırrını bilen."},{"n":14,"t":"(Ey muhatab)! De ki: \"Ben gökleri ve yeri bir çekirdeği yarar gibi yarıp çıkaran Allah`tan başkasını mı veli edineceğim? Ki O herkesi doyurur, fakat doyurulmaya muhtaç değildir.\" \"Ben Allah`a teslim olanların öncüsü olmakla emrolundum\" de ve sakın şirk koşanlardan olma!"},{"n":15,"t":"De ki: \"Eğer Rabbime karşı gelirsem, elbet korkunç bir günün azabından korkarım.\""},{"n":16,"t":"O gün kim azaptan esirgenirse, kesinlikle Allah ona rahmet etmiştir. Bu ise apaçık bir kurtuluş demektir."},{"n":17,"t":"Ve eğer Allah senin zarara uğramanı isterse, Zatından başka kimse ona engel olamaz; yok eğer senin için bir hayır dilerse, unutma ki O her şeyi yapmaya kadirdir."},{"n":18,"t":"Zira yalnızca O`dur kulları üzerinde mutlak otorite sahibi olan; yine O`dur her hükmünde tam isabet kaydeden, her şeyden henüz kaynağındayken haberdar olan."},{"n":19,"t":"Sor onlara \"En büyük şahit kimdir?\" Cevap ver: \"Benimle sizin aranızda Allah şahittir; ve bu Kur`an bana kendisiyle sizi ve onun ulaştığı kimseleri uyarayım diye vahyedildi. Size de (ulaştığına göre şimdi söyleyin bakalım): Allah`la birlikte başka ilahların olduğuna gerçekten şahitlik eder misiniz? De ki: \"Ben buna şahitlik etmem.\" Ve ekle: \"Tek ilah ancak O`dur; ve benim Allah dışında ilahlık yakıştırdıklarınızla hiçbir bağım yoktur.\""},{"n":20,"t":"Daha önce vahye muhatap kıldıklarımıza gelince: onlar onu kendi çocuklarını tanıdıkları gibi tanırlar. Kendilerini kaybeden kimseler var ya: işte onlardır inanmaya yanaşmayanlar."},{"n":21,"t":"Uydurdukları yalanları Allah’a isnat ederek O’na iftirada bulunan veya (kâinatta ve öz nefislerinde bütün iman hakikatlerini apaçık gösteren) O’na ait işaretleri ve O’ nun indirmiş olduğu âyetleri yalanlayandan daha zalim kim olabilir? Şurası bir gerçek ki, zalimler asla felâh bulmaz, muratlarına ermezler."},{"n":22,"t":"Zira o gün tümünü bir araya toplayacağız, ardından ortak koşmakta ısrar edenlere soracağız: \"Hani sizin (yardım edeceğini) düşündüğünüz ortaklarınız?\""},{"n":23,"t":"Bunun ardından, \"Rabbimiz Allah`a yemin olsun ki, bizim amacımız O`na ortak koşmak değildi\" demekten başka bir fitnelik düşünemeyecekler."},{"n":24,"t":"Bak, kendi kendilerine karşı nasıl yalan söylemişler; ve yamuk tasavvurları kendilerini nasıl aldatmış!"},{"n":25,"t":"Onlar arasında öyleleri var ki, sana kulak verir(miş gibi yapar). Fakat kalplerinin üzerine, onları hakikati kavramaktan aciz bırakan örtüler yerleştirdik, kulaklarına da kurşun. Ve hakikatin bütün belgelerini görseler dahi artık iman etmezler. Öyle ki, tartışmak için sana geldiklerinde inkara saplanmış olanlar derler ki: \"Bu eskilerin masallarından başka bir şey değildir.\""},{"n":26,"t":"Onlar hem diğerlerini ondan mahrum eder, hem de kendileri ondan yan çizerler. Başka değil, yalnızca kendi benliklerini helake sürüklerler de bunun farkına dahi varmazlar."},{"n":27,"t":"Ateşin başında dikilecekleri zaman onları bir görmelisin. Derler ki: \"Ah, keşke hayata bir daha döndürülsek! (O zaman) Rabbimizin mesajlarını yalanlamaz, mü`minlerden olurduk.\""},{"n":28,"t":"Ama hayır, daha önce gizlemiş oldukları şey onlara apaçık göründü de ondan; ve eğer geri döndürülselerdi, kendilerine yasaklanan şeylere yine dönerlerdi: Şu kesin ki onlar, yalanı tabiat haline getiren kimselerdir."},{"n":29,"t":"Zira, \"Bu dünyadakinden başka hayatımız yoktur, öldükten sonra da dirilecek değiliz\" demişlerdir."},{"n":30,"t":"Yine sen onları, Rablerinin katına çıkarılıp O`nun \"Bu gerçek değil miymiş?\" diye sorduğu zaman görmeliydin. Onlar, \"Kesinlikle... Rabbimiz hakkı için öyle!\" diye cevap verecekler. O da diyecek ki: \"Tadın azabı, ısrarlı inkarınıza karşılık!\""},{"n":31,"t":"Doğrusu, Allah`a kavuşacaklarını yalanlayanlar hüsrana uğrayacaklar. Kıyamet Saati ansızın geliverdiğinde, günahlarının yükünü sırtlarında taşır bir halde diyecekler ki: \"Ondan mahrum kaldığımız için yazıklar olsun bize!\" Ah, o yüklendikleri şey ne fenadır!"},{"n":32,"t":"(Tek başına) bu dünya hayatı geçici bir oyun ve eğlenceden ibarettir. Ahiret yurdu ise, sorumluluk bilincini kuşananlar için daha hayırlıdır: Hala aklınızı kullanmayacak mısınız?"},{"n":33,"t":"Onların söylediklerinin seni üzdüğünü biliyoruz elbet. Şu bir gerçek ki, onların yalanladığı sen değilsin; bu zalimlerin asıl inkar ettiği Allah`ın mesajlarıdır."},{"n":34,"t":"Doğrusu senden önce de elçiler yalanlanmıştı. Ama yalanladıkları hakikat üzerinde direndiler ve bu yüzden eziyete uğradılar; en sonunda kendilerine yardımımız yetişti: Zira hiçbir güç Allah`ın kesin ve keskin vaadini değiştiremez. Doğrusu peygamberlere dair bir kısım bilgiler daha önce sana ulaşmıştı."},{"n":35,"t":"Eğer onların yüz çevirmeleri ağırına gidiyorsa ve senin de yeri oymaya ya da göğe merdiven dayamaya gücün varsa, haydi bunu yap da bir mucize getir bakalım! Oysa ki eğer Allah dileseydi, onların tümünü hidayet üzre buluştururdu, (ama dilemedi). Öyleyse, sakın (Allah`ın yasasını) bilmezden gelme!"},{"n":36,"t":"Şüphe yok ki, sadece yürekten dinleyenler bir davete icabet edebilir. Ölülere gelince: Onları yalnızca Allah diriltebilir; en sonunda hepsi O`na dönecektir."},{"n":37,"t":"Onlar \"Ona Rabbinden mucizevi bir belge indirilmesi gerekmez miydi?\" derler. De ki: \"Allah her tür mucizevi belgeyi indirmeye kadirdir.\" Fakat onların çoğu bunun bilincinde değildir."},{"n":38,"t":"Oysa yeryüzünde yürüyen hiçbir hayvan ve iki kanadıyla uçan hiçbir varlık türü yoktur ki, sizin gibi bir alem olmasın. Biz ilahi yasalarda hiçbir boşluk bırakmadık. Yine en sonunda onlar, Rablerinin huzurunda toplanacaklar."},{"n":39,"t":"Mesajlarımızı yalanlayanlar, karanlığa mahkum olmuş sağırlar ve dilsizlerdir. Allah kimi dilerse onu saptırır; ve kimi de dilerse onu dosdoğru bir yola yönlendirir."},{"n":40,"t":"De ki: \"Düşünsenize bir, eğer Allah`ın azabına uğrasanız ya da Kıyamet Günü gelip çatsa, Allah`tan başkasına yalvarabilir misiniz? Hadi (cevap verin), eğer dürüstseniz?"},{"n":41,"t":"Aksine, yalnızca O`na yalvarırsınız; O da eğer dilerse sizi yalvartan sıkıntıyı giderir; öyle ki, koştuğunuz ortakları bile unutuverirsiniz."},{"n":42,"t":"Doğrusu Biz, senden önceki topluluklara da mesajlarımızı göndermiştik. Onları da şiddetli zorluğa ve darlığa düşürdük ki, acziyetlerini itiraf etsinler."},{"n":43,"t":"Onlara takdir ettiğimiz sıkıntı kendilerine eriştiği zaman acziyetlerini itiraf etmeliydiler, fakat yürekleri katılaştı. Çünkü Şeytan yaptıkları her şeyi onlara güzel gösterdi."},{"n":44,"t":"Öyle ki, onlar kendilerine yapılan bütün uyarıları kulak ardı ettiler. Biz de nimet kapılarını ardına kadar açtık. Onlar kendilerine verilen nimetlerin hazzıyla sermest bir haldeyken, kendilerini apansız yakalayıverdik: İşte o vakit, tüm umutlarını yitirdiler."},{"n":45,"t":"En sonunda zulümde ısrar eden toplum(ların) kökü kesilip atıldı. Neticede tüm övgüler, yalnızca alemlerin Rabbi Allah`a mahsustur."},{"n":46,"t":"De ki: \"Tutun ki Allah işitme yeteneğinizi ve görme duyularınızı elinizden aldı ve kalplerinizi de mühürledi; peki, onları size Allah`tan başka hangi ilah geri verebilir? Bak, mesajlarımızı nasıl da her boyutuyla açıklıyoruz? Fakat hala onlar katı bir önyargıyla diretiyorlar."},{"n":47,"t":"De ki: \"Tutun ki Allah`ın azabı aniden ya da ayan açık geldi; (o zaman) hiç zalim halktan başkası helak edilir mi dersiniz?"},{"n":48,"t":"Biz elçilerimizi, yalnızca müjdeci ve uyarıcı olsunlar diye göndeririz. Bundan sonra da kim iman eder ve kendini düzeltirse, işte onların gelecekten endişe geçmişten hüzün duymalarına gerek yoktur."},{"n":49,"t":"Mesajlarımızı yalanlayan kimselere gelince: onlar yoldan çıkmaları sebebiyle azaba mahkum olacaklar."},{"n":50,"t":"De ki: \"Size ben ne `Allah`ın hazineleri bana aittir`, ne de `Gaybı ben bilirim` diyorum; yine size, `Ben bir meleğim` de demiyorum: Benim görevim, sadece bana bildirilene uymaktır!\" De ki: \"Hiç görmeyenle gören bir olur mu? Siz hala düşünmeyecek misiniz?"},{"n":51,"t":"Kendilerini O`na karşı savunacak bir dost ya da O`nun katında şefaat edecek birileri olmadan Allah`ın huzuruna çıkmaktan korkanları vahiyle uyar ki, O`na karşı sorumluluk bilinciyle hareket etsinler."},{"n":52,"t":"Ve Rablerinin rızası uğruna sabah akşam O`na kulluk eden (hiç) kimseyi huzurundan kovma! Ne onların yaptıkları şeyden dolayı sen hesaba çekilirsin, ne de senin yaptıklarından dolayı onlar hesaba çekilirler. Sözün özü: onları kovarsan zalimlerden olursun."},{"n":53,"t":"İşte bu şekilde insanları birbiriyle sınarız ki, \"Acaba Allah bizi bırakıp da onlara mı ikramda bulundu?\" diye sorsunlar. Kimin şükrettiğini en iyi bilen Allah değil midir?"},{"n":54,"t":"Mesajlarımıza yürekten inanan kimseler sana geldiğinde de ki: \"Selam olsun size! Rabbiniz, rahmeti kendi zatı için prensip edinmiştir. Haberiniz olsun ki, sizden biri bilmeden bir kötülük işler ve ardından tevbe edip kendini düzeltirse, kesinlikle O`nu tarifsiz bir bağışlayıcılığı olan eşsiz bir merhamet kaynağı olarak (bulacaktır)."},{"n":55,"t":"Böylece Biz mesajlarımızı ayrıntılı aktarıyoruz ki, günahı hayat tarzı haline getirenlerin yolu açık seçik ayırt edilebilsin."},{"n":56,"t":"De ki: \"Ben, Allah`ı bırakıp yalvardığınız şeylere kulluk etmekten men olundum.\" De ki: \"Sizin keyfinize uymam! (Eğer uysaydım), asıl o zaman sapıtmış olurdum ve doğru yolda yürüyenlerden olmazdım!\""},{"n":57,"t":"De ki: \"Çünkü ben Rabbimden gelen açık bir delile dayanmaktayım; ve siz bu tavrınızla onu da yalanlamış bulunuyorsunuz; sizin acele gerçekleşmesini istediğiniz şey (de) benim elimde değil. Hüküm yalnızca Allah`a aittir. O, hakikati haber verecektir; zira (hak ile batıl arasında) en iyi hükmü O verir.\""},{"n":58,"t":"De ki: \"Eğer acele gerçekleşmesini ısrarla istediğiniz şey benim elimde olsaydı, benimle sizin aranızda hüküm gerçekleşmiş olurdu. Ama Allah kimin zalim olduğunu daha iyi bilir."},{"n":59,"t":"Zira gaybın anahtarları yalnızca O`nun katındadır; onu başkası değil, yalnızca O bilir. O, karada ve denizde olan-biten her şeyi bilir; hiç bir yaprak düşmez ki O bunu bilmesin; yerin derinliklerinde bir tek tohum, yaş-kuru hiçbir şey yoktur ki O`nun apaçık yasasına dahil olmasın."},{"n":60,"t":"Nitekim, geceleyin sizi ölü (gibi) yapan ve gündüzün neler işlediğinizi bilen O`dur. Sonra tayin edilen ömrü yaşamak üzere, sizi her gün hayata O geri döndürür. En sonunda dönüşünüz O`nadır ve nihayet yaptığınız her bir şeyi size bildirecektir."},{"n":61,"t":"Çünkü kulları üzerinde mutlak otorite sahibi olan yalnızca O`dur. İçinizden birine ölüm gelip de elçilerimiz onun canını alıncaya dek size kol kanat geren koruyucular gönderir ve bunlar hiç bir şeyi gözden kaçırmazlar."},{"n":62,"t":"Sonunda onlar gerçek sahipleri olan Allah`a teslim edilirler: İşte mutlak hüküm yalnızca O`nundur; ve O hesabı en seri görendir."},{"n":63,"t":"De ki: \"Siz, ta yüreğinizden `eğer O bizi bu (musibet)ten kurtarırsa kesinlikle şükredenlerden olacağız` diye dua ettiğinizde, karanın ve denizin görünmez tehlikelerinden sizi kurtaracak olan biri var mı?\""},{"n":64,"t":"De ki: \"Sizi ondan ve diğer tüm sıkıntılardan kurtaracak olan yalnızca Allah`tır; ama hala Allah`tan başkasına ilahlık yakıştırmayı sürdürüyorsunuz."},{"n":65,"t":"De ki: \"Size üstünüzden ya da ayaklarınızın altından azap gönderme ya da sizi birbirinize düşürüp paramparça bir toplum haline getirme gücü yalnızca O`nundur. Bak, iyice kavrasınlar diye mesajlarımızı nasıl çok boyutlu dile getiriyoruz?"},{"n":66,"t":"O hakikatin ta kendisi olduğu halde, senin hitap ettiğin toplum bunu yalanlıyor. De ki: \"Ben size korumalık yapmakla yükümlü değilim.\""},{"n":67,"t":"Her haberin bir gerçekleşme süreci vardır; zaman gelecek (bunu) siz de öğreneceksiniz."},{"n":68,"t":"Ayetlerimiz hakkında ileri-geri konuşanları gördüğün zaman, onlar başka konulara geçinceye kadar sen onlardan uzak dur! Ama eğer Şeytan sana bunu unutturursa, hiç değilse hatırladıktan sonra, zulme gömülmüş böylesi bir toplulukla birlikte bulunma!"},{"n":69,"t":"Gerçi, sorumluluk bilincini kuşananlar onlardan hiçbir şekilde sorumlu değildirler; fakat bir hatırlatmadır, umulur ki sorumluluk bilincini kuşanırlar."},{"n":70,"t":"Dünya hayatına dalarak eğlenceyi ve geçici zevklerini din haline getiren kimseleri kendi haline bırak. Fakat şunu da onlara hatırlat ki, her insan işlediklerine karşılık ipotek altına alınacak, ve ne kendisini Allah`a karşı koruyacak, ne de kayıracak kimsesi olacaktır. Ve kendisi için en yüksek fidyeyi verse bile, bu ondan asla kabul edilmeyecektir. İşte bunlardır işlediklerine karşılık ipotek edilecekler; ısrarlı inkarları sebebiyle onlar (gelecek için) yakıp kavurucu bir (umutsuzluk) zehiri içecekler, (geçmiş için) şiddetli bir azap çekecekler."},{"n":71,"t":"De ki: \"Biz, Allah`ı bırakıp da bize ne faydası dokunan ne de zarar veren şeylere mi yalvaralım? Ve tıpkı \"bizimle gel!\" diye kendisini doğru yola çağıran arkadaşları dururken şeytanların ayartmalarına kapılıp dünyevi zevklerin peşine tutkulu bir biçimde takılan kimse gibi, Allah bizi doğru yola ilettikten sonra topuklarımız üzerinde gerisin geri mi dönelim? De ki: \"Hiç şüphe yok ki yegane rehberlik Allah`ın rehberliğidir ve biz Alemlerin Rabbine kayıtsız-şartsız teslim olmakla emrolunduk;"},{"n":72,"t":"Bir de: `Namazı hakkıyla edâ edin ve O’ndan (Allah’dan) sakının!` diye (emredildi). Zîrâ (kıyâmet günü) huzûruna toplanacağınız ancak O’dur."},{"n":73,"t":"Zira gökleri ve yeri gerçek bir amaca mebni olarak yaratan O`dur. O ne vakit \"Var ol!\" derse, (varlık) hemen varoluş sürecine girer: O`nun sözü (sanal değil) tahakkuk eden bir gerçekliktir. Ve Sur çalındığında, otorite yalnızca O`na ait olacaktır. O gerçekliğin algılanamayan kısmını da, algı kapsamana giren kısmını da bilendir: O her hükmünde tam isabet edendir, her şeyden haberdar olandır."},{"n":74,"t":"Hani bir zamanlar İbrahim babası Azer`e demişti ki: \"Sen putları mı ilah ediniyorsun? Görüyorum ki, sen ve toplumun apaçık bir sapıklık içindesiniz!\""},{"n":75,"t":"İşte böylece Biz, İbrahim`e göklerin ve yerin hükümranlığı hakkında bir bakış açısı kazandırdık ki, kalben mutmain kimselerden olsun."},{"n":76,"t":"Ve gece karardığında bir yıldız gördü ve haykırdı: \"Benim Rabbim bu!\" Fakat yıldız batınca dedi ki: \"Ben batanları sevmem\"."},{"n":77,"t":"Sonra aynı doğuşunu görünce \"İşte Rabbim bu!\" dedi. Fakat o da batınca dedi ki: \"Doğrusu eğer Rabbim beni doğru yola iletmeseydi, ben de kesinlikle sapıtan kimselerden olurdum!\""},{"n":78,"t":"Nihayet güneşin doğuşunu gördü ve \"Benim Rabbim bu; (zira) bu en büyüğü!\" dedi. Fakat o da kaybolunca \"Ey kavmim!\" diye seslendi, \"Ben sizin şirk koştuğunuz şeylerde yokum!\""},{"n":79,"t":"Artık ben, her türlü batıldan yüz çevirerek bütün varlığımla gökleri ve yeri yaratana yöneldim; ve ben O`ndan başkasına ilahlık yakıştıranlardan değilim!"},{"n":80,"t":"Ve toplumu onunla tartışmaya girdi. Dedi ki: \"Beni doğru yola ileten O olduğu halde, siz Allah hakkında hala benimle tartışıyor musunuz? Ben sizin şirk aracı kıldığınız şeylerden korkmuyorum; Rabbimin dilemediği hiçbir şey gerçekleşmez, Rabbim ilmiyle her şeyi kuşatır: siz hala bunu düşünemiyor musunuz?"},{"n":81,"t":"Hem ben Allah`a ortak koştuğunuz şeylerden neden korkacakmışım? Üstelik siz, Allah katından geçerli bir deliliniz olmadığı halde Allah`a şirk koşmaktan korkmazken? Şu halde eğer biliyorsanız, iki taraftan hangisi kendini güvende hissetmeye daha layıktır, (söylesenize)?"},{"n":82,"t":"İmana ulaşan ve imanlarına zulüm bulaştırmayanlar var ya: işte onlardır güvene layık olanlar; zira onlar doğru yoldadırlar.\""},{"n":83,"t":"İşte bu, toplumuna karşı kullanması için İbrahim`e verdiğimiz ispat yöntemimizdi. Biz, dilediğimiz kimseyi derece derece (hakikate) yüceltiriz. Hiç şüphesiz senin Rabbin her hükmünde tam isabet edendir, her şeyi tarifsiz bilendir."},{"n":84,"t":"Ona İshak`ı ve Yakub`u bağışladık; ve daha önce Nuh`u ilettiğimiz gibi hepsini de doğru yola ilettik. Onun neslinden Davud`u, Süleyman`ı, Eyyub`u, Yusuf`u, Musa`yı ve Harun`u (seçtik). İşte Biz, iyilik yapanları böyle ödüllendiririz;"},{"n":85,"t":"ve Zekeriyya`yı, Yahya`yı, İsa`yı ve İlyas`ı da (seçtik): hepsi de dürüst ve erdemli kimselerdendi."},{"n":86,"t":"İsmail`i, Elyasa`yı, Yunus`u ve Lut`u da (seçtik). Ve Biz onlardan her birini çağının diğer insanlarına üstün kıldık."},{"n":87,"t":"Onların atalarından, çocuklarından ve kardeşlerinden kimilerini de... İşte onların hepsini Biz seçtik ve dosdoğru bir yola yönelttik."},{"n":88,"t":"Bu Allah`ın rehberliğidir: O bununla kullarından dilediğini doğru yola ulaştırır. Eğer onlar şirk koşmuş olsalardı, yapmış oldukları her şey kesinlikle boşa gitmiş olurdu."},{"n":89,"t":"(Ne ki) Biz onlara vahiy, (onunla) hükmederek yetenek ve peygamberlik verdik. Eğer onlar bu hakikatleri inkar ediyorlarsa, iyi bilsinler ki Biz (çoktan) onların yerine başka bir topluluğu vekil kıldık: onlar asla bu hakikatlerin inkarcısı olmazlar;"},{"n":90,"t":"işte şu Allah`ın doğru yolu gösterdiği insanları... O halde sen de onların rehberliğine uy! (Ve) de ki: \"Sizden bunun için bir karşılık beklemiyorum. Unutmayın ki o, bütün insanlığa bir öğütten ibarettir!"},{"n":91,"t":"Onlar \"Allah hiç bir insana hiç bir şey indirmemiştir\" derken Allah`ı hakkıyla takdir edemediler. De ki: \"Kim indirdi Musa`nın insanlara bir ışık ve rehber olarak getirdiği ve sizin papirüs parçalarına dönüştürdüğünüz, çok gizlediğiniz halde sadece gösteriye açtığınız, sizin ve atalarınızın bilmediği birçok şeyi kendisi sayesinde öğrendiğiniz kitabı?\" \"Allah`tır!\" diye cevap ver! Sonra da bırak, daldıkları boş laflarla oyalanıp dursunlar."},{"n":92,"t":"Bu da, şehirlerin anasında ve onun çevresinde bulunanları uyarman için indirdiğimiz, bereket kaynağı, kendisine kadar gelen hakikatleri doğrulayan ilahi bir kelamdır. Ahirete inanan kimseler buna da inanırlar. (Allah`a karşı esas duruş olan) namazlarını muhafaza edenler de işte onlardır."},{"n":93,"t":"Allah hakında yalan uyduran ya da kendisine hiçbir şey indirilmediği halde \"Bana da indirildi\" diyen ve \"Allah`ın indirdiğine benzer şeyleri ben de indirebilirim\" iddiasında bulunan kimseden daha tahripkar biri olabilir mi? Ölüm sancısıyla kıvranırken melekler ellerini uzatarak \"Ruhlarınızı teslim edin! Allah`a doğru olmayan şeyler atfettiğiniz ve O`nun mesajlarına karşı kibrinizden dolayı bugün onur kırıcı bir cezaya çarptırılacaksınız!\" dediklerinde, bir görmeliydin o zalimleri!"},{"n":94,"t":"Ve (Allah diyecek ki): \"İşte şimdi bize yapayalnız geldiniz, tıpkı sizi ilk yarattığımız gibi; dahası, size verdiğimiz her şeyi arkanızda bıraktınız. Sizin lehinize Allah`a ortak olduğunu sandığınız o şefaatçilerinizi neden şimdi yanınızda göremiyorsunuz? Artık aranızdaki bütün bağlar kopmuştur ve bütün dost sandıklarınız sizi yapayalnız bırakmıştır.\""},{"n":95,"t":"Kuşkusuz Allah`tır tohumu ve çekirdeği yaran, bir süreçte ölüden diriyi var eden ve diriden ölüyü çıkaran. İşte budur Allah! Peki, nasıl oluyor da böylesine savruluyorsunuz!"},{"n":96,"t":"O`dur tan yerini ağartan ve geceyi dinlenme vakti, güneşi ve ayı zamanı tayin ölçüsü kılan. Bunlar, her şeyi bilen sonsuz kudret sahibinin iradesiyle tayin ve tesbit edilmiştir."},{"n":97,"t":"Dahası, karanın ve denizin zifiri karanlığında onlara bakıp yolunuzu bulabilesiniz diye sizin için yıldızları var eden O`dur. Doğrusu Biz bu mesajları öğrenmeye gönüllü olanlar için açıklıyoruz."},{"n":98,"t":"Yine O`dur sizi bir tek canlıdan ortaya çıkaran; ve (her biriniz için) geçici ve kalıcı bir yer (tayin eden). Doğrusu Biz bu mesajları kavrama yeteneği olan insanlara açık ve anlaşılır kılıyoruz."},{"n":99,"t":"O`dur gökten yağmuru indiren. İşte Biz bu yolla her türlü bitkiyi tomurcuklandırdık, ondan da yemyeşil bir çim meydana getirdik, ondan ise birbiri üzerine binmiş tahıl taneleri çıkarıyoruz. Yine hurma ağacının tomurcuğundan sık salkımlı hurmalar, üzüm bağları, zeytin ve nar ağaçları; biri diğerine çok benzeyen ve biri diğerinden çok farklı. Ürün verdiği ve olgunlaştığı zaman meyvesine bakın! Hiç kuşkusuz bütün bunlarda inanacak insanlar için derin mesajlar vardır."},{"n":100,"t":"Fakat görünmez varlık türlerine Allah`a denk bir makam yakıp yakıştırdılar, oysa ki onları da O yaratmıştı. Bir de cehaletleri yüzünden O`na oğullar ve kızlar peydahladılar. O`nun aşkın ve yüce olan zatı, insanların her tür tasavvur ve tahayyüllerinin üzerindedir."},{"n":101,"t":"Gökleri ve yeri, örneksiz yaratandır. O`nun hiçbir zaman bir eşi olmadığı halde nasıl çocuk sahibi olabilir? Kaldı ki, her şeyi yaratan O`dur ve O her şeyi bilmektedir."},{"n":102,"t":"İşte Rabbiniz Allah budur: O`ndan başka ilah yoktur, her şeyin yaratıcısıdır. O halde yalnızca O`na kulluk edin! Çünkü O`dur her şeyi koruyup gözeten."},{"n":103,"t":"Hiçbir beşeri görüş ve tasavvur O`nu kuşatamaz, fakat O her türlü beşeri görüş ve tasavvuru çepeçevre kuşatır: Yalnızca O`dur her şeye nüfuz eden, her şeyden haberdar olan."},{"n":104,"t":"Doğrusu, Rabbinizden size (vahiy gibi) bir bilinç kaynağı gelmiştir. Artık kim (vahyin gösterdiği hakikati) görmek isterse kendi lehine, kim de körlüğü tercih ederse kendi aleyhinedir. Ben sizi engelleyecek değilim."},{"n":105,"t":"İşte böylece Biz, mesajlarımızı çok boyutlu olarak dile getiriyoruz ki \"Sen dersini almışsın!\" desinler; dahası öğrenmeye gönüllü bir topluluğa onu açıklayabilelim."},{"n":106,"t":"Sen Rabbinden sana vahyedilene uy -O`ndan başka ilah yoktur- ve başkalarına ilahlık yakıştıranlardan yüz çevir!"},{"n":107,"t":"Eğer Allah (aksini) dileseydi, onlar (Allah`a rağmen) şirk koşamazlardı. Ne Biz seni onlara muhafız yaptık, ne de sen onları korumakla yükümlüsün."},{"n":108,"t":"Allah`tan başkalarına yalvarıp yakaranlara sövmeyin ki, onlar cehaletin verdiği nefretle Allah`a sövmesinler: Zira Biz her topluma kendi yaptıklarını güzel gösterdik. Sonuçta onlar Rablerine dönecekler: İşte o zaman yaptıkları kendilerine bir bir haber verilecektir."},{"n":109,"t":"Şimdi kendilerine bir mucize gösterilmesi halinde bu vahye iman edeceklerine dair var güçleriyle yeminler ediyorlar. De ki: \"Tüm mucizeler Allah katındadır!\" Ve farkında değil misiniz ki, onlara bir mucize gelmiş olsaydı dahi yine de inanmazlardı."},{"n":110,"t":"Biz de onların gönülleri ve gözlerini çeviriverirdik, tıpkı ilk başta ona inanmadıkları konumda olduğu gibi; ve Biz onları küstahça taşkınlıkları içinde kör ve şaşkın debelenmeye terkederiz."},{"n":111,"t":"Eğer Biz onlara melekleri indirmiş olsaydık, ölüler de onlarla konuşmuş olsalardı, (gerçeği ispat edecek) her şeyi de onların önüne sermiş olsaydık, Allah dilemedikçe yine de iman etmezlerdi. Fakat onların çoğu (bunu) bilmezden gelirler."},{"n":112,"t":"Ve böylece Biz, görünür-görünmez şeytanları her peygambere düşman kıldık. Onlar aldatmak amacıyla birbirlerine yaldızlı yalanları telkin ediyorlar. Ama eğer Rabbin dileseydi, onlar bunu yapamazlardı: o halde onlardan da, uyduruk teorilerinden de uzak dur!"},{"n":113,"t":"Zaten onların bundan amacı, ahirete inanmayanların gönüllerini o (yaldızla yalanlarla) çelmektir ki, berikiler ondan hoşlansınlar ve ulaşmak için çabaladıkları kötü sonuca ulaşabilsinler."},{"n":114,"t":"(De ki): \"Hakikati açık ve net bir biçimde ortaya koyan bu ilahi kelamı size gönderen O iken, (iyi ve kötüyü belirlemede) O`ndan başka bir hakem mi arayayım?\" Dahası kendilerine önceden vahiy emanet ettiklerimiz bilirler ki, bu (Kur`an) Rabbin tarafından indirilmiş olan bir hakikattir: öyleyse (ey muhatab), sakın kuşku duyanlardan olma!"},{"n":115,"t":"Zira Rabbinin sözü aslına sadık olarak (yerine ulaşmış) ve adaletle uygulanmıştır: O`nun sözlerini alıp da yerine başka söz koyacak hiçbir güç yoktur: Zira her şeyi işiten, her şeyi bilen sadece O`dur."},{"n":116,"t":"Eğer yeryüzünde yaşayan kitlelerin ardına düşersen seni Allah yolundan saptırırlar: Onlar yalnızca batıl inancın peşinden giderler ve onlar sadece kitle psikolojisiyle hareket ederler."},{"n":117,"t":"Hiç kuşkusuz senin Rabbin, kimin kendi yolundan saptığını kimin de doğru yolda olduğunu en iyi bilendir."},{"n":118,"t":"O halde, üzerine Allah`ın adının anıldığı şeylerden yiyin; tabi ki O`nun ayetlerine içten inanıyorsanız!"},{"n":119,"t":"Kaldı ki Allah, -mecbur kaldığınız haller dışında- yasakladığı şeyleri size ayrıntılı olarak açıkladığı halde, O`nun adının üzerlerine anıldığı şeyleri niçin yemiyorsunuz? Fakat (bu tür konularda) birçokları, sahih bir bilgiye dayanmaksızın sırf kendi kişisel görüşleriyle (yasak alanını genişleterek) başkalarını saptırmaktadır: Kuşkusuz Rabbin haddini aşanları çok iyi bilmektedir."},{"n":120,"t":"Ve günahın açığını da gizlisini de bırakın! Unutmayın ki, günahkar kimseler işledikleri yüzünden cezalandırılacaktır."},{"n":121,"t":"Üzerine Allah`ın adı anılmayıp (başkasının adı anıldığı için) fısk olduğu muhakkak olan şeylerden yemeyin! Ve şeytanlar kendi dostlarına, sizi (iyi ve kötüyü belirleme konusunda) tartışmaya çekmeye telkin ederler; ve eğer onlara uyarsanız, hiç kuşkusuz siz Allah`tan başkasına ilahlık yakıştırmış olursunuz."},{"n":122,"t":"Hiç (manen) ölüyken hayat verdiğimiz ve insanlar arasında yolunu bulması için kendisine ışık tuttuğumuz kimse, içinden çıkma imkanı bulamayacağı zifiri karanlıklara gömülüp giden kimse gibi olur mu? İşte inkarcılara yaptıkları böyle güzel görünür."},{"n":123,"t":"Ve böylece her ülkede, entrika ve hile düzenini kuran düzenbaz suçluları oranın el üstünde tutulan kimseleri yaparız: Fakat çevirdikleri entrikalar yalnız kendi aleyhlerine olur da, onu dahi anlamazlar."},{"n":124,"t":"Ne zaman onlara bir ayet gelse, \"Allah`ın peygamberine verdiklerinin benzeri bize de verilmedikçe inanmayız\" derler. (Oysa ki) risaletini kime vereceğini en iyi bilen Allah`tır. Suç işlemekte ısrar edenler, Allah katında aşağılanacak ve entrikalarından dolayı şiddetli bir azaba çarptırılıcaklardır."},{"n":125,"t":"Allah kimi doğru yola ulaştırmak isterse, onun kalbini teslimiyet için genişletir; kimin de sapmasına izin verirse, onun kalbini de adeta göğe tırmanıyormuş gibi daraltıp sıkıştırır: İşte böylece Allah, inanmamakta direnen kimseleri dehşet bir ıstıraba sürükler."},{"n":126,"t":"Ve bu Rabbinin dosdoğru yoludur. Doğrusu Biz mesajlarımızı, ders alacak insanlara açık ve net olarak anlatıyoruz."},{"n":127,"t":"Rableri katında barış ve saadet yurdu onların olacak; ve O, yapıp ettiklerinden dolayı onların velayetini üstlenecek."},{"n":128,"t":"Yine O, onların tümünü bir araya topladığı o gün, \"Ey görünmez (şerli) varlıklarla aynı safta duranlar! Siz insanlardan birçoğuna epey çektirdiniz!\" (diyecek). Onlara yakın olan insanlarsa; \"Rabbimiz! Biz birbirimizden epey yararlandık, nihayet senin bizim için tayin ettiğin sürenin sonuna geldik!\" diyecekler. (Ve) O, \"Ateş sizin içinde yerleşip kalacağınız ikametgahınız olacaktır; tabii ki Allah aksini dilemedikçe\" diyecektir. Kuşkusuz Rabbin her hükmünde tam isabet eder, her şeyin hakikatini bilir."},{"n":129,"t":"Ve işte Biz, işledikleri yüzünden zalimleri birbirine böyle musallat ederiz."},{"n":130,"t":"(Allah diyecek ki): \"Ey görünmeyen ve görüneniyle tüm iradeli varlık türleri! Kendi içinizden, mesajlarımı size anlatan ve bu gününüzle karşılaşacağınız konusunda sizi uyaran peygamberler gelmedi mi? Onlar: \"Biz kendi aleyhimize şahitlik yaparız!\" diyecekler; zira bu dünya hayatı onları aldatmıştır; ve böylece onlar kendilerinin inkarcı olduklarına yine kendileri şahitlik yapmış olacaklar."},{"n":131,"t":"Bunun nedeni şudur: bir toplumun bireyleri (ilahi sınırlardan) habersiz oldukları sürece, senin Rabbin o (tür) toplumları işledikleri yanlışlar sebebiyle asla helak etmez."},{"n":132,"t":"Zira herkes, ancak yaptıklarına bakılarak sınıflandırılır. Rabbin ise, onların yapıp ettiklerinden habersiz değildir."},{"n":133,"t":"Ve yalnızca Rabbindir kendi kendine yeten, rahmet sahibi olan. O dilerse tıpkı sizi başka insanların soyundan var ettiği gibi, sizi ortadan kaldırıp sonra da dilediğini sizin yerinize geçirir."},{"n":134,"t":"Kaçış yok: tehdit edildiğiniz şey mutlaka gerçekleşecektir: ve siz ona asla engel olamayacaksınız."},{"n":135,"t":"De ki: \"Ey halkım! Siz kendinize yakışanı yapın! Ben de görevimi yapıyorum ve nasıl olsa zamanla anlayacaksınız kimin mutlu sona ulaşacağını!\" Kesin olan şu ki; zalimler asla mutluluğa ulaşamayacaklar."},{"n":136,"t":"Allah`ın yarattığı ekinlerden ve hayvanlardan bir pay ayırıp, batıl inançlarına göre dediler ki: \"Bu Allah`a aittir, bu da (Allah`a) koştuğumuz ortaklarımıza.\" Oysa ki ortakları için olan Allah`a ulaşmıyor, fakat Allah için olan ortaklarına ulaşıyordu: ne berbat muhakeme tarzları var!"},{"n":137,"t":"Dahası, (Allah`a) koştukları ortaklara (olan inançları), şirk koşanların çoğuna çocuklarını öldürmeyi bile güzel gösterir; işte böylece onları yok oluşa sürükler ve değer sistemlerini yozlaştırır. Ne ki, eğer Allah dileseydi yine de bunları yapamazlardı: Şu halde onlardan da, uyduruk teorilerinden de uzak dur."},{"n":138,"t":"Onlar batıl inançlarına göre dediler ki: \"Şu hayvanlar ve ekinler kutsaldır, bizim izin verdiklerimiz dışında hiç kimse onlardan yiyemez! Yine falanca türden hayvanlara yük vurulması haram kılınmıştır!\" Ve birtakım hayvanlar da vardır ki onlar üzerine Allah`ın adını anmazlar, (batıl inançlarını) asılsız yere O`na isnat ederler. Zamanı gelince iftiralarından dolayı cezalandırılacaklar."},{"n":139,"t":"Yine onlar şu (çarpık) iddiada bulundular: \"Şu hayvanların karnında olan yavrular canlı doğarsa yalnızca erkeklerimize ait olup kadınlarımıza yasaklanmıştır; ama ölü doğarsa, hepsi de ona ortak olacaklardır.\" Allah onları bu tür isnatlarından dolayı cezalandıracaktır: Çünkü O her hükmünde tam isabet kaydeder, tarifsiz bir bilgiyle bilir."},{"n":140,"t":"Gerçekte hüsrana uğrayan kimseler, cehaletleri yüzünden beyinsizce çocuklarını öldürenler ve Allah`ın kendilerine rızık olarak bağışladıklarını Allah`a iftara olan (hurafelerle) haram kılanlardır: Onlar sapmışlardır ve doğru yolu da bulamamışlardır."},{"n":141,"t":"Ve O`dur insan eliyle yetiştirilen ve kendi başına yetişen bahçeleri bağları, hurmagilleri, çeşit çeşit ürün veren tarlaları, biri diğerine çok benzeyen ve biri diğerinden çok farklı zeytingilleri ve narı var eden. Her biri ürün verdiğinde ürünlerinden yiyin ve hasat günü (yoksullara) haklarını verin; fakat israf etmeyin: Unutmayın ki O israfçıları sevmez."},{"n":142,"t":"Ve yük taşımaya elverişli olan ve olmayanıyla hayvanlardan, Allah`ın size rızık olarak verdiklerini yiyin ve Şeytan`ın izinden gitmeyin: Unutmayın ki o sizin apaçık düşmanınızdır."},{"n":143,"t":"(Sayısı) sekiz(e ulaşan dört) çift (hayvanın da insana yasak olduğunu iddia ettiler): Koyun ve keçinin iki cinsinden her biri. Sor (onlara): \"O`nun haram kıldığı, çiftlerin erkekleri mi, yoksa dişileri mi? Bir de şu: (yasak), dişilerin rahimlerinde bulunan yavruları da kapsıyor mu? Hadi, bilgiye dayalı bir haber verin bana; tabi ki iddianızın arkasında duruyorsanız?"},{"n":144,"t":"Deve ve sığırın iki cinsinden her biri (ni de haram sayarlar). Sor (onlara): \"O`nun haram kıldığı çiftlerin erkekleri mi, yoksa dişileri mi; ya da (yasak) dişilerin rahimlerinde bulunan yavruları da kapsıyor mu? Ya yoksa, Allah bütün bunları yasaklarken siz şahit miydiniz? Hiçbir gerçek bilgiye dayanmaksızın, insanları saptırmak amacıyla, kendi uydurdukları yalanı Allah`a isnat edenden daha zalim biri olabilir mi? Bakın, Allah zalim bir topluma rehberliğini bahşetmez."},{"n":145,"t":"De ki: \"Bana vahyedilenler içerisinde leş ya da akan kan veya domuz eti -ki o katıksız pistir-, yahut amacından saptırılarak Allah`tan başkası adına kesilen kurban dışında, yemek isteyen için yasak olan hiçbir şey göremiyorum. Fakat çaresiz kalan kimse, hakka tecavüz etmeden ve zaruret sınırını aşmadan (yemişse), unutma ki Rabbin tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":146,"t":"Yahudileşenlere tırnaklı her tür hayvanı haram kıldık; ve onlara ineğin ve koyunun sırt, bağırsak ve kemik yağları dışında kalan içyağlarını da haram kıldık: Onları, değer yıkıcılıkları yüzünden işte bu şekilde cezalandırdık: çünkü Biz, kesinlikle sözümüze sahibiz."},{"n":147,"t":"Ve onlar seni yalancılıkla itham ederlerse de ki: Rabbiniz sınırsız merhamet sahibidir; ama günaha gömülüp gitmiş insanları cezalandırması da kaçınılmazdır."},{"n":148,"t":"Allah`a ortak koşanlar derler ki: \"Eğer Allah dileseydi, ne biz ne de atalarımız şirk koşmazdık; dahası (O`nun helallerinden) hiçbir şeyi haram kılmazdık.\" Onlardan öncekiler de hakikati işte bu mantıkla yalanladılar; ta ki azabımızı tadıncaya kadar... De ki: \"Elinizde bize sunabileceğiniz güvenilir bilgiye dayalı herhangi bir belge var mı?\" Siz yalnızca hurafenin peşinden gidiyorsunuz ve sadece kitle psikolojisiyle hareket ediyorsunuz."},{"n":149,"t":"De ki: \"İyi bilin ki, yalnız Allah katındadır hakikaten en kesin delili; ve O dileseydi, hepinizi doğru yola yöneltirdi."},{"n":150,"t":"De ki: \"Haydi, Allah`ın bütün bunları haram kıldığına tanıklık eden şahitlerinizi getirin bakalım!\" Eğer onlar yalan yere tanıklık ederlerse sakın onların bu tanıklığını onaylama ve mesajlarımızı yalanlayanların ve ahirete inanmayacakların keyfi düşüncelerine uyma! Zira onlar, mevhum güçleri Rablerine denk tutuyorlar."},{"n":151,"t":"De ki: \"Gelin, Allah`ın size neyi haram ve dokunulmaz kıldığını aktarayam: O`ndan başka şeylere kesinlikle ilahlık yakıştırmayın; anne-babaya iyi davranın; rızkınıza ortak çıkar endişesiyle çocuklarınızı öldürmeyin, zira sizin de onların da rızkını Biz veriyoruz; açık ya da gizli, sizi mahcup edecek bir günaha yanaşmayın; haklı bir gerekçeye dayanmaksızın Allah`ın kutsal saydığı insan hayatına kıymayın: Allah size işte bunları emretti ki aklınızı kullanabilesiniz."},{"n":152,"t":"Rüştüne erinceye kadar, lehine olmadıkça yetimin malına dokunmayın; (maddi manevi her alanda) ölçüp tartarken hikmet ve hakkinayeti gözetin; (bilin ki) Biz insana gücünün yettiğinden fazlasını yüklemeyiz; ve biri hakkında konuşacaksanız yakınınız da olsa adil olun; Allah`la olan sözleşmenize sadakat gösterin! Bütün bunları Allah size emretti ki, sorumluluğunuzu aklınızdan çıkarmayasınız."},{"n":153,"t":"Zira işte Benim dosdoğru yolum budur: Öyleyse bu yolu izleyin ve farklı yollara sapmayın ki; sizi O`nun yolundan uzaklaştırmasınlar! Bütün bunları Allah size emretti ki, O`na karşı saygıda kusur etmeyesiniz."},{"n":154,"t":"(Bilinen sürecin) ardından, iyilikte sebat edenlere nimetimizi tamamlamak, (gereken) her şeyi iyice açıklamak ve bir yol haritası ve bir rahmet olmak üzere Musa`ya ilahi kelamı bağışladık ki, (en sonunda) Rableriyle buluşacaklarına inansınlar!"},{"n":155,"t":"İşte bu da Bizim indirdiğimiz mübarek bir kelamdır: Şu halde ona uyun ve sorumluluk bilincini kuşanın ki rahmete nail olasınız."},{"n":156,"t":"(Bir de) \"Sadece bizden önce yaşamış iki topluluğa ilahi mesaj indirilmişti ve biz onların öğretilerinden haberdar değildik\" demeyesiniz;"},{"n":157,"t":"ya da, \"Eğer bize de ilahi bir kelam indirilmiş olsaydı onlardan daha sıkı uyardık\" (demeyesiniz). İşte size de Rabbinizden hakikatin açık belgesi, yol haritası ve rahmet gelmiştir. Bu durumda, Allah`ın ayetlerini yalanlayandan ve ona karşı katı davranandan daha zalim biri olabilir mi? Ayetlerimize karşı katı davrananları, bu kaskatı davranışları yüzünden şiddetli bir azapla cezalandıracağız!"},{"n":158,"t":"Onların, meleklerin kendilerine (ölüm) getirmesinden ya da Rabbinin (azabının) gelmesinden, veya Rabbinin (haber verdiği) kimi (helak) işaretlerinin geldiğini haber vereceği o gün, daha önce inanmamış, yahut inandığı halde imanının hayrını görmemiş olan kimseye imanı hiçbir yarar sağlamaz. De ki: \"Bekleyin (o kaçınılmaz günü)! Ama asla unutmayın: Biz de bekliyoruz!"},{"n":159,"t":"Dinlerini paramparça edip fırkalara taraftar olanlara gelince: Senin onlar için yapabileceğin bir şey yok. Zira onların işi yalnız Allah`a kalmıştır: Sonunda Allah onlara yaptıklarının hesabını soracaktır."},{"n":160,"t":"Kim (İlahi mahkemeye) bir iyilikle gelirse yaptığının on katını kazanacaktır; ama kim de bir kötülükle gelirse onun aynısıyla cezalandırılacaktır: fakat hiç kimseye haksızlık yapılmayacaktır."},{"n":161,"t":"De ki: \"Kuşku yok ki, Rabbim beni dosdoğru bir yola yöneltti; her türlü sapmadan uzaklaşan ve Allah`tan başkasına ilahlık yakıştırmayan İbrahim`in değişmez değerleri (temsil eden) yoluna.\""},{"n":162,"t":"De ki: \"Benim tüm istek ve arzum, bütün ibadetlerim, hayatım ve ölümüm alemlerin Rabbi olan Allah`a armağan olsun!"},{"n":163,"t":"Uluhiyyetinde O`nun ortağı yoktur: Ben işte bu tevhid ile emrolundum; ve ben varlığını kayıtsız şartsız Allah`a teslim edenlerin öncüsü olacağım!"},{"n":164,"t":"De ki: \"O her şeyin Rabbi iken, şimdi ben Allah`tan başka bir Rab mi arayacağım? İnsanların işledikleri kötülükler yalnızca kendilerini bağlar; zira hiç kimse bir başkasının sorumluluğunu taşımaz. Sonunda hepiniz Rabbinize döneceksiniz; işte o zaman O, ihtilafa düştüğünüz hakikatlerin içyüzünü size bildirecektir."},{"n":165,"t":"Çünkü O, sizi yeryüzüne mirasçı kılmış ve bahşettiği nimetlerle sizi sınamak için bir kısmınızı diğerlerinizden derecelerle üstün kılmıştır. Kuşkusuz Rabbin karşılık vermede çok seridir: Fakat, bununla birlikte O gerçekten tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."}],[{"n":1,"t":"Elif-Lam-Mim-Sad!"},{"n":2,"t":"Bir sure indirildi sana, artık bundan dolayı için daralmasın ki, onunla (insanları) uyarabilesin ve mü`minlere de (şu) öğüdü verebilesin:"},{"n":3,"t":"\"Uyun Rabbinizin katından size indirilene! O`nun dışında birtakım otoritelere de asla uymayın!\" Ne kadar da kıt hafızalısınız!"},{"n":4,"t":"Biz nice (asi) toplulukları helak etmişizdir; kahredici gazabımız bir gece vakti ya da gün ortasında dinlenirken gelip çatıvermiştir."},{"n":5,"t":"Kahredici gazabımız kendilerine gelip çatınca, \"Kesinlikle bizdik haksız olan, evet biz!\" itirafından başka bir savunmaları olmayacaktır."},{"n":6,"t":"Hem kendilerine ilahi mesaj gönderilenleri, hem de (onlara) ilahi mesajı iletmekle görevli olanları elbet hesaba çekeceğiz."},{"n":7,"t":"Ardından onlara (haklarındaki) bilgi arşivimizi mutlaka açacağız; hoş, onlardan hiç uzak olmadık ki..."},{"n":8,"t":"Ölçme ve değerlendirme o gün hakkıyla gerçekleşir; sonuçta kimin sevabı tartıda ağır gelirse, işte o kesintisiz mutluluğa erişir."},{"n":9,"t":"Fakat sevabı tartıda hafif gelen kimseler var ya: işte onlar, mesajlarımıza ettikleri haksızlık yüzünden kendilerini harcayan kimselerdir."},{"n":10,"t":"(Ey insanlar!) Doğrusu sizi yeryüzüne yerleştirdik ve orada geçiminizi sağlayacak bir ortam hazırladık: (Bu gerçeğe rağmen) şükredenleriniz ne kadar azdır?"},{"n":11,"t":"Doğrusu sizi yarattık, sonra sizi biçimlendirdik, ardından meleklere dedik ki: \"Adem (oğlu) lehine emre amade olun!\" Hemen emre amade oldular, İblis hariç: o emre amade olanlar arasında yer almadı."},{"n":12,"t":"(Allah) sordu: \"Sana emrettiğim zaman seni emre amade olmaktan alıkoyan neydi?\" (İblis) cevap verdi: \"Ben ondan üstünüm; (çünkü) beni ateşten yarattın, oysa onu balçıktan yarattın!\""},{"n":13,"t":"(Allah): \"Öyleyse in o bulunduğun yerden!\" dedi, \"Çünkü o (makamda) büyüklük taslamak senin haddine düşmez! Hadi, çık git artık! Çünkü sen aşağılık birisin!\""},{"n":14,"t":"(İblis) dedi ki: \"Yeniden diriliş gününe kadar bana süre tanı!\""},{"n":15,"t":"(Allah) \"Sen zaten süre tanınmışlardan biriydin!\" buyurdu."},{"n":16,"t":"(Ve İblis) şöyle dedi: \"Madem ki sen beni saptırdın, yemin olsun ki ben de senin dosdoğru yolunun üzerine onlar için pusu kuracağım;"},{"n":17,"t":"sonra da hem doğrudan ve açıktan, hem de dolaylı ve sinsice, hem suret-i haktan görünerek hem de zaafları ve güdüleri kullanarak sokulacağım onlara: Ve Sen onların çoğunu nankörlük eden kimseler olarak bulacaksın.\""},{"n":18,"t":"(Allah): \"Aşağılanmış ve dışlanmış bir halde defol oradan!\" dedi; \"onlardan kim sana uyarsa, unutmayın ki cehennemi tıka basa sizlerle dolduracağım!\""},{"n":19,"t":"Ve (sana gelince) Ey Adem! Sen ve eşin has bahçede yerleşin, canınızın çektiği her şeyden yiyin, ama sakın şu ağaca yaklaşayım demeyin: sonra zalimlerden olursunuz!"},{"n":20,"t":"Bunun üzerine, Şeytan onlara (o zamana değin) cinsellikleri hakkında henüz farkına varmadıkları şeyi ifşa etmek için fısıldadı ve \"Rabbinizin sizi bu ağaçtan uzak tutması, başka değil, sadece siz (ondan yiyince) iki melek (gibi) olursunuz ya da ölümsüzleşirsiniz de ondandır\" dedi."},{"n":21,"t":"Ve her ikisine yeminler etti: \"İnanın ki ben ikinizin de iyiliğini istiyorum.\""},{"n":22,"t":"İşte böylece onları aldanışa sürükleyecek telkinlerde bulundu. Bunun üzerine onlar o bitkiden tadar tatmaz cinselliklerinin farkına vardılar ve başladılar has bahçenin yapraklarından topladıklarıyla üzerlerini örtmeye. Rableri de ikisine birden şöyle seslendi: \"Ben ikinizi de o ağaçtan men etmemiş miydim? Ve ben ikinize `Kesinlikle Şeytan sizin için ayan açık bir düşmandır!` dememiş miydim?\""},{"n":23,"t":"Her ikisi de dediler ki: \"Rabbimiz! Biz kendi kendimize zulmetmişiz; eğer bizi bağışlamaz ve bize acımazsan, kesinlikle kaybedenler arasına gireriz!\""},{"n":24,"t":"(Allah) buyurdu: \"Birbirinize düşman olarak çıkıp gidin! Zira yeryüzünde, geçici bir hayat alanı ve tadımlık bir haz sizi bekliyor.\""},{"n":25,"t":"(Ve) dedi ki: \"Orada yaşayacak ve orada öleceksiniz; nihayet oradan (ahiret yolculuğuna) çıkarılacaksınız.\""},{"n":26,"t":"Ey Ademoğulları! Size katımızdan, hem çıplaklığınızı örtmek hem de zarafet ve güzellik aracı olmak üzere giysi (yapma yeteneği) bahşettik; fakat takva elbisesi var ya: işte o en hayırlı olandır. Bunlar da Allah`ın ayetlerindendir; belki insanlar ders alırlar."},{"n":27,"t":"Ey Ademoğulları! Tıpkı atalarınızın hasbahçeden çıkışına sebep olduğu gibi, Şeytan`ın sizi şaşırtmasına fırsat vermeyin: Cinselliklerini keşfetmeleri için, her ikisinin örtüden yoksun bırak(ılmasını sağla)mıştı. Hiç kuşkunuz olmasın ki, o ve avanesi sizin kendilerini hiç göremeyeceğiniz bir boyuttan sizi görüyorlar! Çünkü Biz şeytanları, (hakkıyla) iman etmeyenlere otorite kılarız."},{"n":28,"t":"O iman etmeyenler, (Kâbe’yi çıplak tavaf etme gibi) çirkin bir iş işlediklerinde “Biz, atalarımızı da aynı işi yaparken gördük (ve onların izinden gidiyoruz); kaldı ki, Allah da bize böyle emretti.” derler. (Ey Rasûlüm,) de ki: “Allah, asla çirkin bir işi emretmez. Yoksa siz, Allah hakkında bilmediğiniz şeyleri konuşuyor olmayasınız?”"},{"n":29,"t":"De ki: \"Benim Rabbim, sadece doğru olanın yapılmasını emretmiştir: O halde siz, Allah`a sadakatinizi ispat için giriştiğiniz her eylemde bütün varlığınızla O`na yönelin ve dini yalnızca O`na has kılarak ta yürekten yalvarın. Başlangıçta sizi yarattığı gibi, sonunda yine O`na döneceksiniz."},{"n":30,"t":"O, bazılarını doğru yola sevk edecek; fakat bazıları için de doğru yoldan sapmak kaçınılmaz hale gelecek: Çünkü onlar Allah`ı bırakıp şeytan(i duyguların)ın hakimiyetine girecek; üstelik doğru yolu bulduklarını sanarak..."},{"n":31,"t":"Ey Ademoğulları! Allah`a sadakatinizi ispat için giriştiğiniz her eylemde ziynet ve zarafetinizi takının. Yiyin için ama israf etmeyin; çünkü O israf edenleri sevmez."},{"n":32,"t":"Sor bakayım: \"Allah`ın kulları için yarattığı güzellikleri, temiz ve helal rızıkları yasaklayan kimmiş?\" Cevap Ver: \"Bunlar dünya hayatında (herkesle birlikte) imana erenler için, Kıyamet Günü ise yalnızca onlara has olacaktır.\" Kavrama yeteneği olan bir toplum için ayetlerimizi işte böyle açık ve net bir biçimde dile getiriyoruz."},{"n":33,"t":"De ki: \"Benim Rabbim, yalnızca açık ya da gizli yüz kızartıcı davranışları, günahın her türünü, haksız yere başkasının malına göz dikmeyi, herhangi bir delil indirmediği halde Allah`tan başkasına ilahlık yakıştırmanızı, hakkında bilginizin olmadığı şeyi Allah`a atfetmenizi yasaklamıştır.\""},{"n":34,"t":"Her toplumun bir vadesi vardır: Vadeleri dolduğu vakit, onu bir an ne erteleyebilirler ve ne öne alabilirler."},{"n":35,"t":"Ey Ademoğulları! Size aranızdan benim mesajlarımı ileten elçiler geldiğinde, her kim sorumluluk bilinciyle hareket eder ve kendini düzeltirse, onlar gelecek kaygısı taşımayacak ve geçmişte yaptıkları için üzüntü duymayacaklar."},{"n":36,"t":"Mesajlarımızı yalanlayan ve onları küçümseyenlere gelince: onlar, içinde temelli kalmak üzere ateşe girecek."},{"n":37,"t":"Kendi uydurduklarını Allah`a isnat eden ya da O`nun ayetlerini yalanlayandan daha zalim biri olabilir mi? Bu tipler için yazılan (ceza)lardan onların payına düşen gelip onları bulacak: En sonunda canlarını almak için elçilerimiz geldiğinde, onlara \"Nerede Allah`ı bırakıp da kendilerine yalvarıp yakardıklarınız?\" diye soracak. Onlar (ise) \"Bizi yüzüstü bıraktılar!\" cevabını vererek, hakikati ısrarla inkar etmeleri konusunda yine kendi aleyhlerine tanıklık edecek."},{"n":38,"t":"(Ve Allah): \"Sizden önce gelip geçmiş olan görünür görünmüz iradeli varlık gurupları arasına siz de katılarak ateşe girin!\" diyecek. (Ateşe) giren guruplar her seferinde diğer guruba lanet edecek; öyle ki, onların tümü birbiri ardınca oraya doluşunca, sonrakiler önden gidenler için \"Rabbimiz! İşte bizi yoldan çıkaran bunlar; bu yüzden onlara iki kat ateş azabı çektir!\" diyecek. (Allah): \"Hepiniz iki kat azabı hak ettiniz, fakat bunun dahi farkında değilsiniz!\" diye cevap verecek."},{"n":39,"t":"Bu kez öncekiler sonrakilere: \"İşte gördünüz, sizin bizden bir farkınız yok. Öyleyse, kendi işledikleriniz yüzünden tadın azabı!\" diyecekler."},{"n":40,"t":"Hiç şüphesiz mesajlarımızı yalanlamaya kalkan ve onları küçümseyenlere yüce alemlerin kapıları açılmayacak; ve onlar, halat iğne deliğinden geçmedikçe cennete giremeyecekler. Biz, günahta ısrar edenleri işte böyle cezalandırırız."},{"n":41,"t":"Onların (altlarında) cehennemden bir döşek, üstlerinde ateşten bir örtü olacak: İşte Biz, zulme gömülüp gidenleri böyle cezalandırırız."},{"n":42,"t":"Fakat kim imana erer ve imanıyla uyumlu işler yaparsa -(ki) Biz hiç kimseye taşıyacağından fazlasını yüklemeyiz- işte, içinde ebedi kalmak üzere cennete girecek olan da bunlardır."},{"n":43,"t":"Onları içlerine işlemiş olan her tür olumsuz duygu ve düşünceden tamamen arındıracağız, ayaklarının altından nehirler çağlayacak ve şu itirafta bulunacaklar: \"Hamdin tamamı bizi bu (mutlu sona) ulaştıran Allah`a mahsustur; eğer Allah bize doğru yolu göstermemiş olsaydı, biz asla doğru yolu bulamazdık. Doğrusu, Rabbimizin elçileri bize gerçeği söylemişler.\" Ve yankılanan bir nida: \"İşte, yaptığınız (iyiliklere) karşılık mirasçısı olduğunuz cennet bu!\""},{"n":44,"t":"Ve cennetlikler cehennemliklere: \"Rabbimiz bize ne vaad ettiyse hepsini gerçekleşmiş bulduk; siz de Rabbinizin size vaad ettiklerinin hepsini gerçekleşmiş buldunuz mu?\" diye seslenecekler. \"Evet!..\" diye cevap verecekler. Bunun üzerine içlerinden bir münâdî haykıracak: \"Allah lanet etsin tüm zalimlere!.."},{"n":45,"t":"Onlar ki, insanları Allah`ın yolundan çevirirler ve onu karmaşık, dolambaçlı göstermeye çabalarlar; üstelik onlar ahireti (de) inkar ederler!\""},{"n":46,"t":"O ikisi arasında bir engel bulunacaktır. Orada (iyilerle kötüleri) ayırdetme yetisiyle donatılmış kimseler olacak; onlar her iki kesimi de belirtilerinden tanıyacaklar ve henüz cennete girmeyen lakin girmek için sabırsızlanan cennetliklere \"Selamün aleyküm!\" diye seslenecekler."},{"n":47,"t":"Onların gözleri ateş kafilesine doğru çevrilince: \"Rabbimiz! Bizi zalimlerin arasına katma!\" diye yalvaracaklar."},{"n":48,"t":"Ve (sözkonusu) ayırdetme yeteneğine sahip olanlar, belirtilerinden kim olduklarını çıkardıkları kimselere seslenecekler: \"Sahi, ne sağladı size taraftarlarınız / mal-mülkünüz ve böbürlendiğiniz o nesneler?\""},{"n":49,"t":"(Cennet yolcularını işaret ederek) \"İşte şunlar, bir zamanlar \"Allah rahmetini onlara asla ulaştırmaz!\" diye yeminler ettiğiniz, (şimdi ise) kendilerine \"Girin cennete! Sizin için gelecek endişesi yok, geçmişten dolayı hüzün duymak da yok!\" denilen kimseler değiller mi?\""},{"n":50,"t":"Ve ateş yolcuları cennet yolcularına seslenecekler: \"(Ne olur), üzerimize bir parça su dökün!..\" ya da \"Allah`ın size bahşettiği rızıklardan (bize de verin)!..\" (Diğerleri):\" Unutmayın ki Allah, inkar edenleri her ikisinden de mahrum bırakmıştır!"},{"n":51,"t":"Onlar ki, dinlerini oyun ve eğlenceye çevirip dünya hayatının albenisine kanmıştılar!\" cevabını verecekler. Dahası, onlar nasıl bu Hesap Günü`nün gelip çatacağını unuttular ve mesajlarımızı inkar ettilerse, Biz de bugün onları unutulmaya terk edeceğiz."},{"n":52,"t":"Zira Biz onlara, inanmaya gönüllü bir toplum için bir yol haritası ve rahmet pınarı olan, tarifsiz bir bilgiye dayalı izahlarımız bulunan bir kitap iletmiştik."},{"n":53,"t":"(Şimdi) onları, O (Gün`ün) ne demeye geldiğinden başka bir şeyi bekleme hakları mı var? Onu vaktiyle göz ardı eden kimseler, onun ne demeye geldiğinin açıklandığı gün diyecekler ki: \"Doğrusu Rabbimizin elçileri bize hakikati söylemiş. Acaba şimdi bizden yana aracılık yapıp da bizi kayıracak birileri var mı? Veya geri dönmemize izin verilse de, şimdiye kadar yaptıklarımızdan başka türlü davransak olmaz mı?\" Doğrusu onlar kendilerini (işte böyle) aldatacaklar ve uydurdukları kuruntu ürünü (şefaatçi)ler, kendilerini yüzüstü bırakacak."},{"n":54,"t":"Kuşkusuz sizin Rabbiniz, gökleri ve yeri altı aşamada yaratan; ve sınırsız güç ve kudret makamına kurulan Allah`tır. O`dur gündüzü aralıksız kovalayan geceyle örten; güneşi, ayı ve yıldızları emrine amade kılan O... Bakın, yalnız O`na aittir bütün yaratılış ve mutlak emir: Alemlerin Rabbi Allah en yüce, en ulvi bereket kaynağıdır."},{"n":55,"t":"Rabbinize alçak gönüllü olarak ve derin bir aciziyet duygusu içinde yalvarın! Şüphesiz O haddi aşanları sevmez."},{"n":56,"t":"Bu nedenle, iyi bir düzene sokulmuşken yeryüzünde bozgunculuk çıkarmayın; derin bir ürperti ve büyük bir iştiyakla yalvarın O`na; çünkü Allah`ın rahmeti erdemli davrananlara pek yakındır."},{"n":57,"t":"O`dur rüzgarları rahmetinin önüne katıp müjdeci olarak gönderen; nihayet bunlar yağmur yüklü bulutları taşıyınca, onu ölü toprağa doğru sevkedip bu yolla su indiririz ve böylece her türlü ürünün yeşerip boy vermesini sağlarız. Ölüleri de işte böyle dirilteceğiz: belki düşünür de ibret alırsınız."},{"n":58,"t":"Ya bereketli toprak! Onun bitkisi, -Rabbinin izniyle- gür ve gümrah olur. Ama kötüyse bir şey yetişmez, yetişse de işe yaramaz. Elindeki nimetin değerini bilen bir topluluk için ayetlerimizi işte böyle çok boyutlu olarak dile getiriyoruz."},{"n":59,"t":"Doğrusu Biz Nuh`u kendi toplumuna göndermiştik. Dedi ki: \"Ey kavmim! Yalnızca Allah`a kulluk edin, sizin O`ndan başka ilahınız yok. Kuşkusuz ben, korkunç bir günün azabına uğramanızdan korkuyorum.\""},{"n":60,"t":"Toplumun seçkinleri: \"Şu kesin ki, biz seni apaçık bir sapıklık içinde görüyoruz\" diye cevap verdiler."},{"n":61,"t":"\"Ey kavmim!\" dedi, \"Ben sapıtmış değilim, aksine ben alemlerin Rabbi tarafından seçilen bir elçiyim."},{"n":62,"t":"Size Rabbimin mesajlarını tebliğ ediyor ve öğüt veriyorum; çünkü ben Allah`tan gelen (vahiy) sayesinde sizin bilmediklerinizi biliyorum."},{"n":63,"t":"Ne yani, sizi uyarsın, sorumluluğunuzu hatırlatsın ve bu sayede rahmete nail olasınız diye içinizden bir adam eliyle Rabbinizden size bir bildiri gelmesinde şaşılacak ne var?\""},{"n":64,"t":"En sonunda onu yalanladılar. Bunun üzerine Biz de onu ve onunla birlikte gemide bulunanları kurtardık; ayetlerimizi yalanlayanları ise boğulmaya terk ettik: Onlar gerçekten de kör bir topluluk idiler."},{"n":65,"t":"Ad`a da soydaşları Hud`u (gönderdik). \"Ey kavmim!\" dedi, \"yalnızca Allah`a kulluk edin! Sizin O`ndan başka ilahınız yok. Şu halde hala (O`na ortak koşmaktan) sakınmayacak mısınız?\""},{"n":66,"t":"Toplumunun inkarda direnen seçkinleri, \"Gerçekte biz seni akıl zafiyetine uğramış biri olarak görüyoruz; üstelik biz senin yalan söylediğini düşünüyoruz\" diye cevap verdiler."},{"n":67,"t":"Dedi ki: \"Ey kavmim! Ben aklı kıt biri değilim; bilakis ben alemlerin Rabbinden bir elçiyim."},{"n":68,"t":"Size Rabbimin mesajlarını tebliğ ediyoruz; zira ben sizin için güvenilir bir nasihatçiyim."},{"n":69,"t":"Ne yani, sizi uyarsın diye içinizden bir adam eliyle Rabbinizden size bir bildiri gelmesine niçin şaşıyorsunuz? Bari Nuh kavminin ardından sizi nasıl (uygarlığa) mirasçı kıldığını, yaratılış bakımından sizi nasıl üstünlükleriyle takviye ettiğini hatırlayın! Artık Allah`ın nimetlerini unutmayın ki ebedi kurtuluşa erebilesiniz!\""},{"n":70,"t":"Onlar dediler ki: \"Sen bize bir tek Allah`a kulluk etmemiz ve atalarımızın tapa geldiği şeyleri bırakmamız için mi geldin? Tamam, eğer sözünün arkasındaysan haydi getir bizi tehdit edip durduğun azabı!\""},{"n":71,"t":"(Hud) dedi ki: \"Rabbinizden (bir ceza olarak) üstünüze çökmüş bir (ahlaki) kokuşmuşluğun ve tarifsiz bir gazabın içindesiniz zaten. Şimdi, Allah`ın haklarında hiçbir delil indirmediği, yalnızca sizin ve atalarınızın yücelttiği isimler hakkında mı benimle tartışıyorsunuz? O halde bekleyin, gerçek şu ki ben de sizinle birlikte bekleyeceğim!\""},{"n":72,"t":"Nihayet, katımızdan bir rahmet eseri olarak onu ve onunla birlikte olanları kurtardık; ve ayetlerimizi yalanlayanların kökünü kazıdık: nitekim onlar da (tehdidimizin gerçekliğine) inanmamıştılar."},{"n":73,"t":"Semud`a da soydaşları Salih`i (gönderdik). \"Ey kavmim!\" dedi, \"Yalnızca Allah`a kulluk edin! Sizin O`ndan başka ilahınız yok. Doğrusu Rabbinizden size açık ve net bir delil gelmiştir: İşte Allah`ın devesi; sizin için bir semboldür: O halde bırakın onu, (Allah`ın devesi) Allah`ın arzında otlasın ve sakın ona bir kötülük yapayım demeyin! Yoksa size elem veren bir azap dokunur."},{"n":74,"t":"Hem hatırlayın Ad`ın ardından O`nun sizi nasıl (uygarlığa) varis kıldığını ve şu malum yerde sizi yerleştirdiğini! (Siz ki) buranın düzlüklerinde köşkler inşa edip, dağlarındaki (kayalardan) evler yontarsınız. Artık hatırlayın Allah`ın nimetlerini de, kötülüğü yaygınlaştırarak ahlaki çürümeye meydan vermeyin!\""},{"n":75,"t":"Toplumun güçsüzlere karşı büyüklük taslayan seçkinleri, ezilenler arasındaki inanan kimselere dediler ki: \"Siz Salih`in Rabbi tarafından gönderildiğine inanıyor musunuz?\" Onlar \"Elbette\" dediler, \"biz onunla gönderilene de iman etmiş kişileriz!\""},{"n":76,"t":"Büyüklük taslayanlarsa: \"Biz\" dediler, \"Sizin iman etmeye değer bulduğunuz şeyin inkarcısıyız!\""},{"n":77,"t":"En sonunda dişi deveyi işkenceyle, vahşice katlettiler ve Rablerinin buyruğuna karşı geldiler; üstelik dediler ki: \"Ey Salih! Eğer peygamberlerden biri olduğun gerçekse, haydi getir şu bizi tehdit ettiğin azabı!\""},{"n":78,"t":"Derken şiddetli bir sarsıntı onları ansızın yakalayıverdi ve kendi obalarında cansız donakaldılar."},{"n":79,"t":"Ve (Salih) onları ardında bırakırken \"Ey kavmim!\" diye mırıldanmıştı, \"Doğrusu ben size Rabbimin mesajını tebliğ etmiştim ve size öğüt vermiştim; ne ki siz öğüt verenleri hiç sevmediniz!\""},{"n":80,"t":"Lut`u da (gönderdik). Hani o toplumuna şöyle çıkışmıştı: \"Sizden önceki toplumlardan hiç birinin yapmadığı (düzeyde) bir irtikap etmekte ısrarcı mısınız?"},{"n":81,"t":"Siz ki, kadınları bırakıp şehvetle erkeklere yaklaşıyorsunuz: Yoo, siz gerçekten de haddi aşan bir topluluksunuz."},{"n":82,"t":"Ama kavminin cevabı şundan ibaret oldu: \"Sürüp çıkarın yurdunuzdan onları! Besbelli bunlar pek temiz insanlarmış!\""},{"n":83,"t":"Bunun ardından onu ve yakınlarını kurtardık; ne ki eşi (yolda) dökülenlerden biri oldu."},{"n":84,"t":"Sonunda sağanak (gibi bela) yağdırdık üzerlerine: Gör ki günaha gömülüp gidenlerin sonu nice olurmuş!"},{"n":85,"t":"Medyen`e de soydaşları Şuayb`i gönderdik. \"Ey kavmim!\" dedi, \"Yalnızca Allah`a kulluk edin! Sizin O`ndan başka ilahınız yok: size Rabbinizden hakikatin apaçık belgeleri gelmiştir. Artık (her şeyde) ölçüyü ve tartıyı tam gözetin, insanları hakları olan şeylerden mahrum bırakmayın ve iyi bir düzene sokulmuşken yeryüzünde fesat çıkarmayın! Bütün bunlar sizin hayrınızadır: tabi ki gerçekten Allah`a güveniyorsanız!"},{"n":86,"t":"Bir de (Hakka varan) her yolun kenarına kurulup O`na iman eden kimseleri türlü tehditlerle Allah`ın yolundan döndürmeye ve onu eğri büğrü göstermeye çalışmayın! Ve hatırlayın ki, siz azınlık iken O sizi çoğalttı: işte, fesat çıkaranların akıbeti nasıl olurmuş görün!"},{"n":87,"t":"Madem ki aranızda, getirdiğim mesaja inanan bir topluluk yanında inanmayan bir topluluk da var; o halde Allah aramızda hüküm verinceye kadar sabredin: Zira O, hüküm verenlerin en hayırlısıdır."},{"n":88,"t":"Kavminin büyüklük taslayan seçkinleri \"Ey Şuayb!\" dediler, \"Ya seni ve beraberindeki mü`minleri yurdumuzdan sürüp çıkarırız, ya da bizim inanç sistemimize geri dönersin!\" (Şuayb) dedi ki: \"Peki, ya razı olmazsak?"},{"n":89,"t":"Hem Allah bizi ondan kurtardıktan sonra kalkıp sizin inanç sisteminize dönecek olursak, uydurduğumuz yalanı Allah`a isnat etmiş oluruz. Rabbimiz Allah istemediği sürece inancınıza dönmemiz asla mümkün değildir. Rabbimizin ilmi her şeyi kuşatmıştır (ve) biz Allah`a güvenmişizdir: Rabbimiz! Bizimle kavmimiz arasındaki engelleri kaldır! Çünkü Sen, engel kaldıranların en hayırlısısın!\""},{"n":90,"t":"Ve kavminden inkarda direnen seçkinler: \"Eğer Şuayb`e uyacak olursanız kesinlikle kaybeden siz olacaksınız!\" diye tehdit ettiler."},{"n":91,"t":"Derken şiddetli bir sarsıntı onları ansızın yakalayıverdi ve kendi yurtlarında cansız donakaldılar."},{"n":92,"t":"Onlar ki Şuayb`i yalanlıyorlardı; kendilerine yalan oldular... Onlar ki Şuayb`i yalancı çıkarıyorlardı; kaybeden yine onlar oldu..."},{"n":93,"t":"Ve (Şuayb) onları ardında bırakırken \"Ey kavmim!\" diye mırıldanmıştı, \"Doğrusu ben size Rabbimin mesajlarını tebliğ etmiştim ve size öğüt vermiştim. Şu halde ben (sizin gibi) nankör bir kavim için nasıl gam çekeyim!?\""},{"n":94,"t":"Biz hiçbir ülkeye bir peygamber göndermemişisizdir ki, (zamanında) oranın halkını belki (Allah`a) boyun eğerler diye şiddetli zorluk ve darlıkla sınamamış olalım."},{"n":95,"t":"Sonra (o) kötü durumu güzelliğe çevirmişizdir de, refaha kavuşup şımarmamışlar ve \"(Bir zamanlar) atalarımız da sıkıntılı ve sevinçli günler yaşamışmış\" demişlerdir. İşte bunun üzerine biz de onları, olup bitenin farkına dahi varmadan ansızın yakalayıvermişizdir."},{"n":96,"t":"Oysa ki, eğer bu ülkelerin insanları inansalar ve sorumlu hareket etselerdi, onlara göklerin ve yerin bereketini ardına kadar açardık, fakat yalanladılar. Bunun üzerine biz de yaptıklarından dolayı onları kıskıvrak yakaldık."},{"n":97,"t":"Şu halde bu ülkelerin insanları, azabımızın gece vakti onlar uykudayken ansızıp gelip çatmayacağından emin olabilirler miydi?"},{"n":98,"t":"Ya da, (sözkonusu) ülkelerin insanları azabımızın gündüz gözüyle onlar (hayat) oyununu oynarken ansızıp gelip çatmayacağından emin olabilirler miydi?"},{"n":99,"t":"Yani onlar, Allah`ın entrikayla alt edilemeyen düzenine karşı kendilerini güvencede sayabilirler miydi? Doğrusu, Allah`ın entrikayla alt edilemeyen düzenine karşı, sadece tükenmiş bir toplum kendisinin güvencede olduğunu sanır."},{"n":100,"t":"Artık önce gelip geçmiş (uygarlıkların) ardından yeryüzünün (medeniyet) mirasına konanlar için şu gerçek ortaya çıkmış olmuyor mu: Eğer istersek, günahları yüzünden onları da hedefe koyabiliriz; üstelik kalplerine mühür basarız da, onlar artık (gerçeği) işitmez olurlar."},{"n":101,"t":"Sana kıssalarını naklettiğimiz bu ülkeler... Doğrusu bütün bunlara kendi içlerinden elçiler hakikatin apaçık belgelerini getirdiler; fakat onlar, bir kez yalanlamış bulundukları için bir daha iman etmediler: İşte Allah inkarcıların kalplerini böyle mühürler."},{"n":102,"t":"Ve biz onların çoğunu (fıtrat) sözleşmesine sadık bulmadık; aksine onların çoğunu sapıtmış bulduk."},{"n":103,"t":"Sonra, bu kavimlerin peşinden Firavun`a ve onun önde gelen adamlarına ayetlerimizle Musa`yı gönderdik; ona getirdiği ayetler yüzünden haksızlık ettiler ve bak nasıl oldu fesatçıların sonu."},{"n":104,"t":"Ve Musa dedi ki: \"Ey Firavun! Ben alemlerin Rabbinden bir elçiyim!"},{"n":105,"t":"Bana yakışan Allah hakkında hakikatten başka bir şey söylememektir. Elbet size Rabbinizden apaçık mucizelerle geldim. Artık bırak da İsrailoğulları benimle gelsinler."},{"n":106,"t":"(Firavun) dedi ki: \"Madem ki bir mucizeyle geldin, o halde ortaya koy, tabi ki sözünün arkasında duruyorsan?\""},{"n":107,"t":"Bunun üzerine (Musa) asasını yere bıraktı: Fakat o da ne? Düpedüz bır yılandı o!"},{"n":108,"t":"Ve elini çıkardı: Bir de baktılar ki, göz kamaştırıcı bir parlaklık!"},{"n":109,"t":"Firavun toplumunun seçkinleri dediler ki: \"Anlaşıldı ki bu kişi, bu işleri iyi bilen bir sihirbazmış,"},{"n":110,"t":"tüm arzusu (ise) sizi yerinizden yurdunuzdan etmek!\" (Firavun): \"O halde ne öneriyorsunuz?\""},{"n":111,"t":"Şu cevabı verdiler: \"Onu ve kardeşini alıkoy ve şehirlere görevliler yolla,"},{"n":112,"t":"bütün bilgin sihirbazları toplayıp huzuruna getirsinler.\""},{"n":113,"t":"Ve sihirbizlar gelip Firavun`a dediler ki: \"Şayet biz kazanacak olursak her halde bize bir ödül verilir?\""},{"n":114,"t":"(Firavun): \"Kesinlikle!\" dedi, \"üstelik siz (protokolde) maiyetimiz arasındaki yerinizi de alacaksınız.\""},{"n":115,"t":"(Sihirbazlar dönüp) \"Ey Musa!\" dediler, \"Önce sen mi atacaksın (asanı), ya yoksa biz atalım mı?\""},{"n":116,"t":"(Musa): \"(Önce) siz atın!\" dedi. Ve onlar attıkları zaman büyüyle insanların gözlerini bağladılar ve onlara korku saldılar: Sonuçta müthiş bir sihirdi sergiledikleri."},{"n":117,"t":"Biz de Musa`ya \"Asanı bırak\" diye vahyettik. Fakat o da ne! O, onların gözbağcıklarını bir bir silip süpürmesin mi!"},{"n":118,"t":"Böylece hakikat ortaya çıktı ve (Allah) diğerlerinin yaptıkları sihri iptal etti."},{"n":119,"t":"Sonunda (Firavun ve avanesi) yenik düştüler. İşte orada ve o anda, onların küstahça gururunu yerle bir eden bir inkılab gerçekleşti;"},{"n":120,"t":"ve sihirbazlar hep birden yere kapanarak"},{"n":121,"t":"şöyle dediler: \"İman ettik alemlerin Rabbine!"},{"n":122,"t":"Rabbine Musa ve Harun`un!\""},{"n":123,"t":"Firavun: \"Demek siz ben izin vermeden ona inandınız ha?\" dedi; \"İyi dinleyin: Bu sizin kurduğunuz haince bir tuzaktır! (Üstelik bana ait) şehirde... Hem de şehrin ahalisini oradan çıkarmak için... Fakat yakında gününüzü göreceksiniz!"},{"n":124,"t":"Kesinlikle dönekliğinizden dolayı ellerinizi ve ayaklarınızı keseceğim, sonra topunuzu asacağım!"},{"n":125,"t":"Onlar şöyle cevap verdi: \"(İyi ya), biz de Rabbimize kavuşmuş oluruz."},{"n":126,"t":"Çünkü sen, sadece Rabbimizin ayetlerine bize ulaşır ulaşmaz inandık diye bizden intikam alıyorsun.\" \"Rabbimiz! Sabır yağdır üzerimize ve varlığımızı sana adamış olarak canımızı al!\""},{"n":127,"t":"Firavun toplumunun seçkinleri dedi ki: \"Şimdi sen Musa`yı ve halkını seni ve ilahlarını bırakıp ülkede kargaşa çıkarsınlar diye kendi başlarına mı bırakacaksın?\" (Firavun): \"Onların çocuklarını öldürtüp kadınlarını sağ bırakacağız: Ve böylece biz onların üzerindeki ezici baskımızı sürdürmüş olacağız\" dedi."},{"n":128,"t":"Musa toplumuna dedi ki: \"Allah`tan yardım isteyin ve dirençli olun! Bilin ki yeryüzü Allah`ındır, kullarından dilediğini oraya mirasçı kılar: mutlu son sorumlu davrananlarındır.\""},{"n":129,"t":"(Musa`nın toplumu): \"Sen bize gelmeden önce de eza cefa görüyorduk, mucizelerle geldikten sonra da\" diye çıkıştılar. (Musa): \"Rabbiniz düşmanınızı yok ettikten sonra sizi ülkeye kesinlikle varis kılacak, bunun için de sizin tavır ve davranışlarınıza bakacaktır\" dedi."},{"n":130,"t":"Doğrusu Biz Firavun`un halkını, akıllarını başlarına toplasınlar diye kuraklık ve ürün kıtlığına mahkum ettik."},{"n":131,"t":"Oysa ki onlar, kendilerine ne zaman bir iyilik ulaşsa \"Bu (zaten) bizim hakkımızdı\" derler; fakat ne zaman da bir kötülük dokunsa, Musa ve onunla birlikte olanların uğursuzluğuna yorarlardı. Yoo! Onların uğursuzluğa yordukları (şey) Allah katındandır; fakat onların çoğu bunun farkında değiller."},{"n":132,"t":"(Musa`ya) dediler ki: \"Bizi büyülemek için hangi delili getirirsen getir yine sana inanmayacağız.\""},{"n":133,"t":"Bunun üzerine Biz de onlara tufanı, çekirge ve kurbağa sürülerini, zararlı böcekleri ve kan (kırmızı suyu) musallat ettik; (bunlar) apaçık mesajlardı, fakat yine büyüklük tasladılar: Zira onlar günaha batmış bir topluluktular."},{"n":134,"t":"(Bu) musibet(ler)in başlarına geldiği her zaman şu vaadde bulunurlardı: \"Ey Musa, seninle yaptığı peygamberlik ahdi hürmetine bizim için Rabbine dua et! Bu musibeti bizden uzak tutmayı sağlarsan, söz, sana inanacak ve İsrailoğullarının seninle gitmesine izin vereceğiz.\""},{"n":135,"t":"Fakat ne zaman sözlerini gerçekleştirmeye yetecek bir süre musibeti kaldırsak, her seferinde gerisin geri sözlerinden dönerlerdi."},{"n":136,"t":"En sonunda Biz de bunun acısını onlardan çıkardık: Ayetlerimizi yalanladıkları ve onlara karşı kayıtsız kaldıkları için onları suda boğduk."},{"n":137,"t":"Vaktiyle hor görülüp ezilen insanları, toprağını bereketli kıldığımız ülkenin en doğusundan en batısına kadar tamamına hakim kıldık. Ve Rabbinin İsrailoğullarına verdiği güzel (bir gelecek) vaadi, onların sabırlarına karşılık (işte böyle) gerçekleşti. Firavun ve avanesinin yapıp yücelttikleri kibir uygarlığını tarihe gömdük."},{"n":138,"t":"Sonunda İsrailoğullarını denizden geçirdik; derken, birtakım putlara tapınan insanlarla karşılaştılar. \"Ey Musa!\" dediler, \"Onların ilahı gibi bize de bir ilah tedarik ediver!\" (Musa) cevaben dedi ki: \"Siz sahiden de kendini bilmez bir yığınsınız."},{"n":139,"t":"O (putperestlere) gelince: Yaşam tarzları onları yok oluşa sürükleyecektir: zira onlar bir saçmalığı sürdürüyorlar.\""},{"n":140,"t":"(Ve) ekledi: \"Size Allah`tan başka bir ilah arayayım, öyle mi; üstelik O, bütün insanlar arasından (vahyi taşıma) onurunu size bahşetmişken?\""},{"n":141,"t":"Ve hatırlayın ki size en berbat acıları yaşatan, çocuklarınızı öldürtüp kadınlarınızı sağ bırakan Firavun toplumunun elinden kurtarmıştık sizi! İşte bu, Rabbiniz tarafından tabi tutulduğunuz ağır bir sınavdı."},{"n":142,"t":"Ve Musa`ya otuz gecelik bir süre tayin ettik ve buna on gece daha ekledik. Böylece Rabbinin tayin ettiği süre kırk geceye tamamlanmış oldu. Ve Musa kardeşi Harun`a dedi ki: \"Halkımın arasındaki görevimi sen üstlen ve düzeni sağla: sakın bozguncuların yoluna sapma!\""},{"n":143,"t":"Ve Musa tayin ettiğimiz vakitte tesbit ettiğimiz yere gelince Rabbi de ona konuştu: (Musa): \"Rabbim! Göster bana zatını, göreyim seni!\" dedi. (Allah) \"Asla göremezsin beni!\" dedi. \"Fakat şu dağa bir bak; eğer o yerinde kalırsa, sen Beni ancak o zaman görebilirsin.\" Ve Rabbi dağa tecelli eder etmez, onu toza toprağa çevirdi; Musa ise baygın düştü. Kendine geldiği zaman dedi ki: \"Şanın ne yücedir senin! Pişmanlık duyarak sana yöneldim ve ben (bu gerçeğe, yaşayarak) inananların öncüsüyüm."},{"n":144,"t":"(Allah) buyurdu ki: \"Ey Musa, mesajlarım yoluyla ve hitabım sayesinde seni insanlar arasından seçip onurlandırdım; öyleyse sana bahşettiklerime sımsıkı sarıl ve şükredenlerden ol!\""},{"n":145,"t":"Ve levhalara onun için her şey hakkında öğüt ve her konuda net açıklamalar yazdık: Artık onlara kuvvetle sarıl; halkına da emret: iyi niyetle onlar da sıkıca sarılsınlar! Daha durun, size yoldan çıkmışların dünyasını da göstereceğim!"},{"n":146,"t":"Yeryüzünde haddini aşarak büyüklük taslayanları ayetlerimden uzak tutacağım; isterse onlar her türlü mucizeye şahit olsunlar, yine de ona inanmazlar; yine onlar hak yolu görüyor olsalar bile o yoldan gitmezler; fakat sapık yolu görünce hemen onu kendilerine yol olarak benimserler. İşte bu, onların ayetlerimizi yalanlamaları ve onlara karşı umursamazlıkları nedeniyledir."},{"n":147,"t":"Nitekim, ayetlerimizi ve ahiret buluşmasını yalanlayan kimselerin yapıp ettikleri boşa gidecek. Ne yani, onlar yaptıklarının karşılığından başka bir şeyle ödüllendirilmeyi mi bekliyorlar?"},{"n":148,"t":"Ve Musa`nın halkı onun peşi sıra, takılardan mamul ses çıkaran bir buzağı heykelini ilah edindiler. Onlar onun kendileriyle konuşmayacağını, yol da göstermeyeceğini görmüyorlar mıydı sanki! (Yine de onu) ilah edindiler; çünkü onlar bilinci altüst olmuş kimselerdi."},{"n":149,"t":"Pişmanlık içinde elleri kolları dökülüp de sapmış olduklarının farkına varınca \"Eğer Rabbimiz bize acıyıp da bizi bağışlamazsa, işte o zaman büsbütün kaybedenlerden olacağız!\" diye dövündüler."},{"n":150,"t":"Ve Musa halkının yanına döndüğünde, hüzünle karışık bir öfkeyle dedi ki: \"Benim yokluğumda ne berbat bir yol tutturmuşsunuz öyle! Rabbinizin emrini çiğnemede bu ne acele böyle?\" Hemen levhaları attı, kardeşinin başını kavrayıp kendine doğru çekti. (Harun): \"Anamın oğlu! diye yakındı, \"Bu topluluk beni etkisiz hale getirdi, hatta az kalsın canıma kastedeceklerdi! Sakin ol, beni düşmanıma karşı gülünç duruma düşürme ve bu zalimler güruhuyla beni bir tutma!\""},{"n":151,"t":"(Musa): \"Rabbim!\" dedi, \"Beni bağışla, kardeşimi de; ve bizi koruyucu şefkatinle kuşat! Çünkü sen merhametlilerin en merhametlisisin.\""},{"n":152,"t":"(Harun`a yönelerek): \"Şu buzağıyı ilah edinenlere gelince: Sonunda Rablerinin gazabı gelip onları bulacak, dünya hayatında ise onursuzluğa mahkum olacaklar!\" Biz, (Allah`a) iftira edenleri işte böyle cezalandırırız."},{"n":153,"t":"Ama önce kötülük işleyip de ardından pişmanlık duyarak Allah`a güvenle yönelenlere gelince: Kuşkusuz senin Rabbin -hele de böyle bir tevbeden sonra- tarifsiz bir bağışlayıcıdır, eşsiz merhamet sahibidir."},{"n":154,"t":"Ve öfkesi yatışınca, Musa, üzerinde Rablerinin (sevgisini yitirmekten) korkanlara rehberlik eden ve rahmet vaad eden öğretiler yazılı levhaları aldı."},{"n":155,"t":"Ve Musa, belirlediğimiz bir zaman ve mekanda hazır olmak üzere toplumu arasından yetmiş kişi seçti. O zaman onları derin bir sarsıntı tutunca, \"Rabbim!\" dedi, \"Dileseydin bunları ve beni daha evvel helak ederdin. Şimdi içimizdeki beyinsizlerin işledikleri yüzünden bizleri de helak eder misin? Bu Senin sınamandan başka bir şey değil; onunla dilediğini sapıklığa terk eden, dilediğini de doğru yola yöneltirsin! Sensin bizim velimiz: O halde bizi bağışla, bize merhamet et! Çünkü Sen bağışlayanların en hayırlısısın."},{"n":156,"t":"Bizim için bu dünyada da güzellikler yaz, ahirette de; ki biz pişmanlık içinde Sana sığındık!\" (Allah) buyurdu ki: \"Dilediğim kimseyi azabıma hedef kılabilirim, fakat rahmetim her şeyi kuşatmıştır. En sonunda sorumlu davranan ve arınıp yücelmek için ödenmesi gereken bedeli ödeyen kimseler, -ki onlar ayetlerimize inanan kişilerdir- onu paylaştıracağım;"},{"n":157,"t":"onlar ki, ellerinde Tevrat ve İncil`de tanıtılmış bulacakları Rasul`un, o Kitap Ehli`nden olmayan peygamberin izinden gidecekler; (o peygamber) onlara iyiliği emredip kötülükten sakındıracak, temiz ve yararlı şeyleri onlara helal kılıp pis ve zararlı şeyleri onlara yasaklayacak; sırtlarına vurulmuş olan yüklerini indirip öteden beri (özgürlüklerine) vurulan zincirleri çözecek. Sonuçta ona inanan, onu el üstünde tutup destekleyen ve ona yücelerden bahşedilen ışığın ardına onunla birlikte düşenler kurtuluşa erenler olacak."},{"n":158,"t":"(Ey Peygamber) de ki: \"Ey İnsanlar! İyi bilin ki ben Allah`ın hepinize gönderdiği elçisiyim. Öyle bir (Allah) ki; göklerin ve yerin egemenliği O`na aittir; O`ndan başka ilah yoktur; hayatı ve ölümü yaratan O`dur: o halde Allah`a ve O`nun elçisine inanın; Allah`a ve O`nun bütün mesajlarına inanan kitap ehlinden olmayan Haberci`ye... Ve ona uyun ki doğru yolu bulabilesiniz!"},{"n":159,"t":"Musa`nın toplumu içerisinde öyle bir kesim de vardır ki, onlar hakkıyla rehberlik ederler ve o hakikat sayesinde adaletli davranırlar."},{"n":160,"t":"Derken, Biz onları on iki boydan oluşan (on iki) guruba ayırdık. Toplumu Musa`dan su talep ettiğinde, ona \"Asanla taşa vur!\" diye vahyettik: Bunun üzerine taştan on iki su gözesi fışkırdı da, bu sayede herkes nereden içeceğini öğrendi. Yine onları bulutla gölgeledik, onlara menn ve selva ikram ettik (ve dedik ki): \"Size bahşettiğimiz rızıkların temiz ve güzel olanlarından yararlanın!\" Fakat (onlar nankörlük etmekle) bize zulmetmiş olmadılar; asıl zulmettikleri kendi benlikleriydi."},{"n":161,"t":"Hani, bir zaman da onlara denilmişti ki: \"Yerleşin şu ülkeye, oranın ürünlerinden dilediğiniz gibi yararlanın! Bir yandan da `Bağışla!` diye yalvarın ve mahviyet içerisinde (kentin) kapısından girin; Biz de sizin hatalarınızı bağışlayalım ve sonunda güzel davrananları ödüllendirelim!\""},{"n":162,"t":"Fakat onlardan kendilerine kötülük edenler, sözü kendilerine söylenenden başkasıyla değiştirdiler. Bunun üzerine Biz de, ettikleri kötülükler yüzünden onların üzerine gökten bela yağdırdık."},{"n":163,"t":"Mesela, sor onlara deniz kıyısındaki mamur kentin halini! Hani onlar, Sebt Günü dışında ortaya çıkmıyorlar diye, Sebt Günü`nde balıkların kendilerine akın akın gelişine tamah ederek Cumartesi geleneğini çiğniyorlardı! Biz, yoldan çıkmaları nedeniyle onları (dünyalığa) işte böyle mübtela ettik."},{"n":164,"t":"Ne zaman ki onlardan bir topluluk (söz konusu sapkınlara karşı çıkanlara), \"Niçin Allah`ın (bu dünyada) helak edeceği, veya (ahirette) şiddetli bir azaba uğratacağı birilerine öğüt verip duruyorsunuz ki?\" dediklerinde, onlar şu cevabı verdiler: \"Rabbinizin katında sorumlu olmayalım diye; bir de, belki sorumluluklarını hatırlarlar umuduyla!\""},{"n":165,"t":"Ve o (sapkınlar) kendilerine yapılan tüm uyarıları kulak ardı edince, Biz de kötülüğe engel olmaya çalışan (bu) kimseleri kurtardık; ve kendilerine kötülük eden kimseleri yoldan çıkmalarından dolayı kahredici bir azabın pençesine mahkum ettik."},{"n":166,"t":"Ve sonunda, kendilerine yasaklanan şeyleri işlemekteki inatçı tutumları yüzünden onlara dedik ki: \"Maymundan beter olun!\""},{"n":167,"t":"Nitekim Rabbin, Kıyamet Günü`ne kadar onların başına, kendilerini dehşet felaketlere uğratacak kimseleri bela edeceğini ilan etmişti. Unutma ki Rabbin cezalandırmada çok dakiktir; bununla beraber O, tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":168,"t":"Ve onları gurup gurup yeryüzünün her tarafına dağıttık; onların aralarında dürüst ve erdemli kimseler olduğu gibi, böyle olmayanlar da var. Bu sonuncuları belki kendilerine dönerler umuduyla, hem bağış ve bollukla hem sıkıntı ve darlıkla sınadık."},{"n":169,"t":"Onların ardından, kendilerinin yerini alan yeni kuşaklar Kitab`a varis oldular; (fakat) bu değersiz dünyanın geçici hazlarına kapıldılar. Ayaklarına gelen bu türden her (dünyevi) hazzı fırsat bilip üzerine atladıkları halde, \"Nasıl olsa sonunda bağışlanacağız!\" bile dediler. Oysa ki onlardan Allah hakkında, gerçekten başka hiçbir şey söylemeyeceklerine dair vahiy (ile belgelenen) söz alınmamış mıydı? Dahası, onun kitapta kayıtlı bulunan dersini almamışlar mıydı? Tabii ki, sorumluluğunun bilincinde olanlar için ahiret hayatı en hayırlısıdır: Hala akıllanmayacak mısınız?"},{"n":170,"t":"Ama kitaba sımsıkı sarılan ve Allah`a kulluğun hakkını verenler var ya: onlar iyi bilsinler ki Biz, kendilerini ve başkalarını düzeltmek için çaba gösterenlerin emeklerini zayi etmeyeceğiz."},{"n":171,"t":"Ve Biz (Sina) Dağı`nı bir gölgelik gibi tepelerine dikip, onların dağın üzerlerine yıkılacağını zannettikleri o zaman da (demiştik): \"Size bahşettiğimiz vahye sımsıkı sarılın ve onun ilkelerini aklınızdan çıkarmayın ki, sorumluluğunuzu yerine getirmiş olasınız!\""},{"n":172,"t":"Ve Rabbin, Ademoğlunun sulbünden onların nesillerini çıkardığı her zaman, onları kendileri hakkında tanık kıldı: \"Ben değil miyim sizin Rabbiniz?\" Onlar da \"Kesinlikle\" dediler, \"buna biz şahidiz!\" (Bunu hatırlattık) ki, Kıyamet Günü bizim bu gerçekten haberimiz yoktu demeyesiniz,"},{"n":173,"t":"ya da \"Doğrusu bizden önce babalarımız şirk koşmuştu, bizse sadece onların peşinden giden bir kuşağız; dolayısıyla, batılı icat edenlerin yaptıkları yüzünden bizi mi helak edeceksin?\" gerekçesine sığınmayasınız."},{"n":174,"t":"İşte Biz, ayetlerimizi bu şekilde çok boyutlu olarak açıklıyoruz ki, belki tekrar gerçeğe dönerler."},{"n":175,"t":"Bir de onlara, mesajlarımızı ulaştırdığımız halde, onları elinin tersiyle itip şeytana uyan ve sonunda sapık olup çıkan kimsenin durumunu haber ver."},{"n":176,"t":"Ki, eğer Biz isteseydik onu mesajlarımızla yüceltirdik, ne ki o dünyaya sarıldı ve ihtirasının peşine düştü. İşte bu yüzden böyle birinin durumu, üstüne varsan da kendi haline bıraksan da hırlayıp duran köpeğe benzer. Mesajlarımızı yalanlamaya kalkanların durumu işte böyledir. Şu halde bu kıssaları aktar, belki üzerinde düşünürler."},{"n":177,"t":"Ne berbattır ayetlerimizi yalanlayan bir toplumun hali; üstelik onlar (böyle yapmakla) kendilerine zulmetmiş oluyorlar."},{"n":178,"t":"Kimin rehberi Allah olursa, doğru yola ulaşan o olur; O kimi de sapıklığa terk ederse, işte gerçekten kaybeden de onlar olurlar."},{"n":179,"t":"Doğrusu Biz, görünen görünmeyen iradeli varlıklar içinden akleden kalpleri olup da kavramayan, gözleri olup da görmeyen, kulakları olup da işitmeyen birçoklarını cehennemlik yapmışızdır. Hayvan gibidir onlar, belki daha da aşağı! Onlar gaflete gömülmüş olan zavallılardır."},{"n":180,"t":"En güzel nitelikler ve tüm mükemmelikler Allah`a mahsustur. Artık O`na yalvarıp yakarın ve O`nun yüceltilmesinde haktan sapan kimselerden uzak durun! Onlar, zamanı gelince yaptıklarından dolayı cezalandırılacaktır."},{"n":181,"t":"Yarattıklarımız içersinde hakikate giden yolu gösteren ve onun sayesinde adaletle davranan kimseler de vardır."},{"n":182,"t":"Ayetlerimizi yalan sayan kimselere gelince: onları bir süreç içerisinde yavaş yavaş eriteceğiz de farkına dahi varmayacaklar."},{"n":183,"t":"Onları bir süre kendi hallerine bıraksam bile, unutmayın ki onların entrikalarını başlarına geçiren düzenim çok sağlamdır."},{"n":184,"t":"İmdi, onlar (yıllar yılı tanıdıkları) hemşehrilerinde delilikten eser olmadığını düşünmezler mi? O yalnızca açıktan açığa uyaran biridir."},{"n":185,"t":"Hem bakmazlar mı göklerin ve yerin mutlak otoritesine, Allah`ın yarattığı her bir şeyin niteliğine? (Düşünmezler mi) ecellerinin yaklaşmış olma ihtimalini? Bu (vahiy) de değilse, artık hangi habere inanacaklar?!"},{"n":186,"t":"Allah kimi sapmaya terk ederse, artık ona doğru yolu kimse gösteremez: zira onları ısrarlı tercihleri olan sapıklıkta debelenmeye terk edecektir."},{"n":187,"t":"Sana soruyorlar: \"Son Saat ne zaman gelip çatacak?\" diye. Cevap ver: \"Onun bilgisi yalnızca Rabbimin katındadır; onun vaktini O`ndan başka ortaya koyacak kimse yoktur: O bütün ağırlığıyla göklerde ve yerde kopacak, sizi haberiniz olmadan ansızın yakalayacaktır. Sanki senin ısrarla o bilginin peşine düşüp elde etmen mümkünmüş gibi, onu sana soruyorlar. De ki: \"Onun gerçek bilgisi yalnızca Allah katındadır, ne ki insanların çoğu bunu bilmezden geliyor.\""},{"n":188,"t":"De ki: \"Allah dilemedikçe, ben (dahi) kendime ne yarar sağlayabilirim, ne de zararı önleyebilirim. Zira eğer gaybı bilseydim, kendime tüm güzelliklerden daha çok pay ayrılmasını sağlardım, üstelik kötülük de semtime uğrayamazdı. Ne ki ben, inanan insanlar için yalnızca bir uyarıcı ve müjdeciyim.\""},{"n":189,"t":"O`dur sizi bir tek candan yaratan ve kendisine ilgi duysun diye ona kendi cinsinden eşini var eden. Gün gelip o eşine sarılınca, (önce) eş hafif bir yük yüklenir ve o yükü bir süre taşır. Ardından yük ağırlaşınca eşler Rableri olan Allah`a: \"Eğer bize eli ayağı düzgün, kusursuz bir çocuk bahşedersen; söz, Sana şükreden kimselerden olacağız!\" diye yakarırlar."},{"n":190,"t":"Fakat O kendilerine eli ayağı düzgün, kusursuz bir çocuk bahşedince de, onlara bahşettiği çocuk üzerinden O`na ortak koşmaya kalkarlar: oysa ki Allah, onların ortak koştukları şeylerden çok yücedir."},{"n":191,"t":"Şimdi siz O`na has birtakım nitelikleri, bir şey yaratmaktan aciz, aksine kendileri yaratılmış bulunan şeylere mi yakıştırıyorsunuz?"},{"n":192,"t":"Kaldı ki, ne onlara yardımları dokunabilir ne de bizzat kendilerine yardımcı olabilirler."},{"n":193,"t":"Ve eğer yol göstersinler diye yakarsanız, size cevap bile veremezler. Onlara ister yalvarın ister susun; size karşı konumlarında hiçbir şey değişmez."},{"n":194,"t":"İyi bilin ki, Allah`tan başka yalvarıp yakardığınız kimseler de sizin gibi yaratılmış varlıklardır. Nitekim eğer doğruluğunuzdan eminseniz, haydi yakarın da duanıza icabet etsinler!"},{"n":195,"t":"Hem onların yürüyecek ayakları mı var? Ya da tutacak elleri veya görecek gözleri, yahut işitecek kulakları mı var? De ki: \"Haydi çağırın Allah`a ortak koştuklarınızı, sonra önüme her türlü tuzağı kurun ve bana göz açtırmayın!"},{"n":196,"t":"(Ama) unutmayın ki, benim savunucum Kitab`ı indiren Allah`tır: zira, dürüst ve erdemli olanları O savunacaktır."},{"n":197,"t":"Oysa ki, O`nun dışında yalvarıp yakardıklarınız ne size yardımcı olabilir ne de kendilerine yardımları dokunur."},{"n":198,"t":"Ve eğer yol göstersinler diye yakarsanız, sizi duymazlar bile; ve sanırsın ki sana bakıyorlar, fakat onlar görmezler.\""},{"n":199,"t":"Sen insan fıtratına uyan yolu tut, iyi olanı emret ve haddini bilmezlere aldırma!"},{"n":200,"t":"Yine de Şeytan tarafından kurgulanan ayartıcı bir kışkırtmaya hedef olursan, hemen Allah`a sığın: unutma ki O her şeyi işitir, akıl sır ermez bir ilim sahibidir."},{"n":201,"t":"Şüphesiz, sorumluluk bilincini kuşanan kimselerin içine Şeytan tarafından kurgulanan mevhum bir görüntü yansıyacak olursa, (hemen fıtrat sözleşmesini) hatırlayıverirler ve işte o an gerçeği kavrarlar."},{"n":202,"t":"Kendi (fıtratlarına yabancılaşmış) kardeşleri onları azgın sulara sürüklemek isteseler dahi, sonuna (dek) mücadeleden el çekmezler."},{"n":203,"t":"Ve sen onlara istedikleri ayeti getirmediğin zaman hemen derler ki: \"Onu (Rabbinden) almak için çabalasaydın ya!\" De ki: \"Ben yalnızca Rabbimden bana vahyedilene uyarım: bu (vahiy) Rabbiniz katından gelen bir bilinç kaynağıdır; inanacak bir toplum için de kapsamlı bir doğru yol haritası ve bir rahmet pınarıdır.\""},{"n":204,"t":"Artık Kur`an okunurken onu can kulağıyla dinleyin ve sesinizi kesin ki rahmete nail olabilesiniz!"},{"n":205,"t":"Ve Rabbini, özbenliğinde, alçak gönüllülükle ve O`ndan sakınarak, sesini yükseltmeksizin gündüz gece an ve sakın kendine yabancılaşanlardan olma!"},{"n":206,"t":"Unutma ki, Rabbinin tarafında olanlar O`na kullukta kibre kapılmazlar; ve O`nun adına/aşkına hareket ederler ve yalnız O`nun önünde secdeye kapanırlar."}],[{"n":1,"t":"Sana cihadın bahşettiği gelirler hakkında soruyorlar. De ki: \"Cihadın bahşettiği bütün gelirler Allah`a ve Elçisi`ne aittir. Şu halde, Allah`a karşı sorumluluğunuzun bilincinde olun ve aranızdaki ilişkiyi düzgün tutun! Bir de Allah`a ve Elçisi`ne kulak verin: tabi ki, gerçekten inanıyorsanız eğer!\""},{"n":2,"t":"Gerçek mü`minler şu kimselerdir ki; Allah hatırlatıldığı zaman kalpleri ürperir; kendilerine O`nun ayetleri okunduğu zaman imanları güçlenir ve daima Rablerine güvenirler."},{"n":3,"t":"Onlar namazı hakkını vererek kılarlar ve kendilerine verdiğimiz rızıklardan cömertçe sarf ederler."},{"n":4,"t":"İşte onlardır hakkıyla iman edenler! Rableri katında saygınlığı olan rütbeler, sınırsız bir bağış ve görkemli bir rızık onları bekler."},{"n":5,"t":"Tıpkı, Rabbin seni hakikat yoluna (savaşmak için) evinden çıkardığında inananlardan kimileri bundan nasıl hoşlanmadılarsa;"},{"n":6,"t":"gerçek ortaya çıktıktan sonra da, sanki sen onları göz göre göre ölüme sürüyormuşsun gibi, seninle tartışmaktan geri durmadılar."},{"n":7,"t":"Hani Allah, iki topluluktan birinin sizin elinize geçeceğine ilişkin vaadde bulunmuştu; siz ise korumasız olanın elinize düşmesini istiyordunuz. Ne ki Allah`ın muradı, kelamı aracılığıyla hakkı gerçekleştirmek ve kafirlerin kökünü kurutmaktı;"},{"n":8,"t":"ki hakkın gerçek ve batılın sahte olduğu böylece ortaya çıksın: tabi ki, günahı tabiat haline getirenler istemese de!"},{"n":9,"t":"Hani Rabbinizden yardım dileniyordunuz; bunun üzerine size şöyle icabet etmişti: \"Size birbirini izleyen bin melekle yardım edeceğim!\""},{"n":10,"t":"Çünkü Allah bunu yalnızca bir müjde olsun, bu vesileyle içiniz ferahlayıp moraliniz yükselsin diye yaptı; kaldı ki zafer garantili yardım, başkasından değil yalnızca Allah katındadır: Elbette Allah her işinde mükemmel olan, her hükmünde tam isabet edendir."},{"n":11,"t":"Hani o zaman, O`nun inayetinden bir güvence olarak sizi bir iç sükunetinin çepeçevre kuşatmasını sağlamış ve üzerinize gökten tarifsiz bir yağmur indirmişti ki, onunla sizi temizlesin, (iç dünyanızı kirleten) Şeytan kirinden sizi arındırsın, yüreklerinizi güçlendirip ayaklarınızı onunla sabit kılsın."},{"n":12,"t":"Hani o zaman Rabbin meleklere, \"Elbet Ben de sizinle beraberim!\" mesajını (iletmelerini) bildirdi: Haydi, imanda sebat edenlere direnç ve moral verin; Ben, inkarda direnenlerin yüreklerine korku salacağım! Haydi, vurun boyunlarının üstüne!... Kopartın onların (silah tutan) tüm parmaklarını!..\""},{"n":13,"t":"Bu, onların Allah ve Elçisi`ne karşı konuşlanmaları yüzündendir; ve kim Allah ve Rasulü`ne karşı konuşlanırsa, iyi bilsin ki Allah`ın cezalandırması pek şiddetlidir."},{"n":14,"t":"Bu sizin için (ey inkarcılar)! Haydi, tadın onu! Bir de ayrıca, inkarda (sonuna kadar) direnenler için (ahirette) ateş azabı var!"},{"n":15,"t":"Siz ey iman edenler! Savaşta, inkarda direnenlerin kalabalık ordusuyla karşılatığınızda sakın ardınızı dönüp kaçmayın!"},{"n":16,"t":"Nitekim o gün -taktik gereği olmaksızın ya da diğer bir birliğe katılma amacı taşımaksızın- kim ardını dönüp kaçarsa, kesinlikle o Allah`ın gazabına muhatap olacak ve meskeni (de) cehennem olacaktır: o ne berbat bir ikametgahtır."},{"n":17,"t":"Hem onları siz öldürmediniz; amma velakin, onları asıl öldüren Allah`tı. Attığın zaman da atan sen değildin, ama asıl Allah attı. Zira O, inananları (sonucunu) inayetiyle takdir ettiği güzel bir sınava tabi tuttu: şüphesiz Allah her şeyi işitir, her şeyi bilir."},{"n":18,"t":"Bu (da) sizin için (ey inananlar): İşte Allah, inkar edenlerin tuzağını (böyle) boşa çıkarır!"},{"n":19,"t":"Siz ey fetih isteyenler! İşte fetih ayağınıza gelmiştir! Şimdi, eğer bir son verirseniz bu sizler için daha hayırlıdır. Yok eğer dönerseniz biz de döneriz; ve ne kadar kalabalık olursa olsun topluluğunuz size hiçbir yarar sağlamaz: (Herkes) iyi bilsin ki Allah mü`minlerle beraberdir."},{"n":20,"t":"Siz ey iman edenler! Allah`a ve O`nun Elçisi`ne bağlılığınızı gösterin; (O`nun mesajını) işittiğiniz halde O`ndan yüz çevirmeyin!"},{"n":21,"t":"Bir de kulak asmadıkları halde \"İşittik!\" diyenler gibi olmayın!"},{"n":22,"t":"İyi bilin ki, Allah katında canlıların en şerlisi aklını kullanmayan (gerçek) sağır ve dilsizdirler."},{"n":23,"t":"Hem eğer Allah onlarda iyi bir hal ve gidiş görseydi, onların işitmelerini sağlardı; ne ki eğer onların işitmelerini sağlasaydı bile, onlar inatçı inkarlarıyla yine yüz çevirirlerdi."},{"n":24,"t":"Siz ey iman edenler! O sizi hayat bahşeden bir (diril)işe davet ettiğinde, Allah`a ve Elçi`ye icabet edin! Zira iyi bilin ki Allah kişiyle kalbinin (eğilimleri) arasına sürekli müdahale eder; akıbet O`nun huzurunda toplanacaksınız."},{"n":25,"t":"Ve öylesine çetin bir yürek sınavına karşı tetikte ve tedbirli olun ki, o içinizden yalnızca bilinci altüst olmuş kimselere musallat olmakla kalmayacaktır. Ve iyi bilin ki Allah`ın azabı pek şiddetlidir."},{"n":26,"t":"Ve hatırlayın ki bir zamanlar siz yeryüzünde ezilen bir azınlıktınız; insanların sizi etnik temizliğe tabi tutmasından endişe ederdiniz! Böyleyken O size sığınak oldu, sizi yardımıyla güçlendirdi ve size güzel ve temiz rızıklar bahşetti: Belki şükredersiniz."},{"n":27,"t":"Siz ey iman edenler! Allah`a ve Elçi`ye ihanet etmeyin! Sonra, korumanız gereken değerlere bile bile ihanet etmiş olursunuz."},{"n":28,"t":"Zira aklınızdan çıkarmayın ki, mallarınız ve çocuklarınız birer sınav aracıdır; ve bilin ki katında en büyük ecir bulunan Allah`tır!"},{"n":29,"t":"Siz ey iman edenler! Eğer Allah`a karşı sorumluluk bilinciyle hareket ederseniz, size hakkı batıldan ayıracak bir ayrım gücü verir; dahası kötülüklerinizin üzerini örter ve sizi bağışlar; çünkü Allah`tır sınırsız lütuf, sonsuz kerem sahibi olan!"},{"n":30,"t":"Hani bir zaman da inkarda direnenler senin önünü kesmek, öldürmek ya da sürgün etmek için sana tuzaklar kuruyorlardı. Nitekim onlar hep tuzak kurmuşlar, Allah da onların tuzağını sürekli boşa çıkarmıştır; zira Allah tuzakları boşa çıkaranların en hayırlısıdır."},{"n":31,"t":"Her ne zaman ayetlerimiz kendilerine iletilse derler ki: \"Biz (bu tür sözleri) önceden de işitmiştik. İstesek buna benzer sözleri biz de düzüp koşabiliriz. Hem bu, eskilerin masallarından başka bir şey değildir!\""},{"n":32,"t":"Bir zaman da tuttular şöyle dediler: \"Allah`ım! Bu eğer senin katından gelen bir hakikatse, o zaman gökten üzerimize taş yağdır; ya da bize can yakıcı bir azap gönder!\""},{"n":33,"t":"Oysa ki Allah, sen onların arasındayken onları cezalandırmayı istemedi; üstelik Allah, af dileme sürecini yaşarken onları cezalandırmak ta istemezdi."},{"n":34,"t":"Ama şimdi onlar Mescid-i Haram`dan (inananları) alıkoyup dururken, Allah`ın onları cezalandırmaması için ne gibi bir gerekçeleri olabilir? Kaldı ki, onlar (Kabe`nin) can dostları olamazlar: çünkü oraya can dost olmaya ancak sorumluluk bilincini kuşananlar layıktır; ve fakat onların çoğu bunu bile fark etmezler."},{"n":35,"t":"Onların Beyt çevresindeki ibadeti (vahyi susturmak için) şamata çıkarmak ve (namazı) engellemekten ibarettir. Haydi öyleyse, ısrarlı inkarınızdan dolayı tadın azabı!"},{"n":36,"t":"(İnsanları) Allah yolundan çevirmek için servetlerini ortaya koyan şu kafirler var ya: işte onların, daha çok servet harcamaları gerekecek; sonra bu onların içinde gerçekleşmemiş bir özlem olarak kalacak ve en sonunda tükenip gidecekler. Nihayet, inkarda ısrar eden bu kimseler topluca cehenneme sürülecekler"},{"n":37,"t":"(ki), Allah pisliğe kesmiş batmış olanı tertemiz olandan seçip ayırsın; ve pisliğe batan herkesi birbiri üzerine istif ederek tümünü cehenneme doldursun: işte onlardır büsbütün kaybedenler."},{"n":38,"t":"İnkarda ısrar edenlere, eğer (inada) bir son verirlerse geçmişte yaptıklarının bağışlanacağını söyle; yok eğer bildiklerini okumaya devam ederlerse, geçmişteki benzerlerinin başına gelenleri sakın (unutmasınlar)!"},{"n":39,"t":"Artık onlarla zulüm ve baskı sona erinceye ve hayatın Allah`a adanmasına (yönelik tüm baskılar kaldırılıncaya) kadar savaşın! Ne ki baskıya bir son verirlerse, unutmayın ki Allah onların yaptığı her şeyi görmektedir."},{"n":40,"t":"Bütün bunlardan sonra yüzçevirecek olurlarsa, şunu iyi bilin ki Allah sizin Sahibinizdir: O ne muhteşem bir sahip, O ne mükemmel bir yardımcıdır!"},{"n":41,"t":"Şunu iyi bilin ki, ganimet olarak aldığınız her şeyin beşte biri Allah`a ve Elçi`ye; dolayısıyla yakınlara, yetimlere, muhtaçlara ve yolda kalmışlara aittir. Eğer siz, Allah`a ve hakkın batıldan ayrıldığı o gün, -yani iki ordunun karşı karşıya geldiği gün- kulumuza indirdiklerimize inanıyorsanız (bu paylaşıma uyarsınız): Zira Allah her şeyi yapmaya kadirdir."},{"n":42,"t":"O zaman siz vadinin yakın ucunda, onlar da uzak ucundaydı; kervansa sizden hayli aşağıdaydı. Eğer sözleşmiş olsaydınız dahi, sözleştiğiniz zamanı bu kadar isabetli tutturamazdınız. Fakat Allah olması mukadder bir işi gerçekleştirmek için (böyle) yaptı ki; helak olan hakkın açık bir müdahelesiyle helak olsun, hayatta kalan da (yine) hakkın açık bir müdahalesiyle hayatta kalsın: Zira Allah her şeyi işitendir, her şeyi bilendir."},{"n":43,"t":"O zaman Allah rüyanda, sana onları sayıca az gösterdi. Eğer onları sana kalabalık gösterseydi, kesinlikle yılgınlığa kapılacak ve yapılması gerek iş konusunda anlaşmazlığa düşecektiniz. Fakat Allah (sizi) bundan korudu: çünkü O gönüllerin özünü en ince ayrıntısına kadar bilir."},{"n":44,"t":"Hani o gün karşı karşıya geldiğiniz zaman onları gözünüzde büyütmemenizi sağlamıştı; sizse onların gözünde zaten az görünüyordunuz ki, Allah olması mukadder bir işi gerçekleştirsin: sonunda her iş döner dolaşır Allah`ın dilediğine varır."},{"n":45,"t":"(Öyleyse) siz ey iman edenler; bir toplulukla savaş için karşı karşıya geldiğinizde, yılmayın ve Allah`ı sürekli anın ki kurtuluşa eresiniz."},{"n":46,"t":"Ve Allah`a ve O`nun Elçisi`ne tabi olun ve birbirinizle didişmeyin! Sonra direncinizi yitirirsiniz, rüzgarınız da kesilir. Kesinlikle direnin, unutmayın ki Allah direnenlerle birliktedir."},{"n":47,"t":"Ve yurtlarından, gösteriş içinde kasılarak huruç eden kimseler gibi olmayın; çünkü onlar Allah`ın yolundan (insanları) alıkoyuyorlar. Allah ise onları yaptıkları şeylerle kuşatandır."},{"n":48,"t":"Ve o zaman Şeytan, yapıp ettiklerini kendilerine güzel göstererek diyordu ki: \"Bu gün hiç bir insan size galip gelemez; çünkü ben sizin yanınızdayım!\" Fakat iki taraf birbirinin görüş alanına girince ökçeleri üzerine geri döndü ve dedi ki: \"Benim sizinle hiçbir ilişkim olamaz! Çünkü ben sizin görmediğinizi görüyorum; üstelik ben Allah`tan korkarım: çünkü Allah`ın cezalandırması pek şedid olur!\""},{"n":49,"t":"O zaman ikiyüzlüler ve kalbinde hastalık olanlar diyorlardı ki: \"Bu adamlara dinleri yanlış yaptırıyor!\" Oysa, Allah`a güvenen herkes şunu bilmeli: her işinde mükemmel olan, her hükmünde tam isabet eden yalnız Allah`tır."},{"n":50,"t":"Ve O, küfre saplanıp kalanlara ölümü tattırdığında bir görmeliydin: Melekler onların suratlarına ve sırtlarına vurarak (diyecekler) ki: \"Tadın bakalım yakıcı azabı;"},{"n":51,"t":"bu, kendi ellerinizle işlediklerinizin karşılığıdır; değilse Allah`ın kullarına haksızlık yapma ihtimali bulunmamaktadır."},{"n":52,"t":"(Onların gidişatı da) tıpkı Firavun toplumu ve ondan öncekilerin gidişatı gibi: Allah`ın mesajlarını ısrarla yalanladılar; ardından, Allah da günahları nedeniyle onları (suçüstü) yakalayıverdi. Elbette Allah (işinde) kuvvetli, azabında şiddetlidir."},{"n":53,"t":"Bu, şu (yasa) gereğidir: Allah, bir topluma bahşettiği nimeti o toplum özbenliğine yabancılaşmadıkça asla değiştirmez: zira Allah her şeyi işitendir, tarifsiz bir ilimle bilendir."},{"n":54,"t":"(O halde onların akıbeti de) Firavun toplumu ve ondan öncekilerin akıbetine benzeyecek: Onlar Rablerinin mesajlarını yalanlamışlardı, biz de onları günahları yüzünden helak ettik; boğulmaya mahkum ettik Firavun soyunu: zira hepsi de zalim olmakta direniyorlardı."},{"n":55,"t":"Allah katında canlıların en şerlisi, (her nasılsa) geçmişte küfre sapmış olup da daha sonra iman etmemekte direnenlerdir."},{"n":56,"t":"Kendileriyle anlaşma yaptıktan sonra, her seferinde, sorumsuzca anlaşmalarını bozanlara gelince:"},{"n":57,"t":"savaşta onları gözüne kestirirsen, geriden gelenlere ibret olsun diye öyle bir darmadağın et ki, berikiler ders alabilsinler."},{"n":58,"t":"Ve eğer (aranızda anlaşma bulunan) bir toplumun ihanetinden haklı nedenlerle kaygıya kapılırsan, durumu dengelemek için onlarla yaptığın anlaşmayı geçersiz ilan et: unutma ki Allah hainleri sevmez!"},{"n":59,"t":"Nitekim, küfre saplanan kimseler (Bizi) aşabileceklerini sanmasınlar. Unutmasınlar ki onlar (Allah`ı) atlatamazlar."},{"n":60,"t":"Siz de onlara karşı gücünüz oranında kuvvet ve atlı birlik hazırlayıp, bu yolla hem Allah düşmanlarını, hem kendi düşmanlarınızı, hem de bunlar dışında sizin bilmeyip Allah`ın bildiği daha başkalarını yıldırıp caydırabilesiniz. Ve Allah yolunda her ne harcarsanız size tümüyle geri ödenecektir; ve siz asla zulme uğramayacaksınız."},{"n":61,"t":"Ama eğer onlar barışa yönelirlerse sen de bu yönelişe uy! Ne ki yalnızca Allah`a güven: unutma ki O duyulmayanı duyan, bilinmeyeni bilendir."},{"n":62,"t":"Tut ki onlar seni (barış tuzağıyla) aldatmayı planlamış olsunlar; o zaman de elbet Allah sana yeter: O`dur seni yardımıyla ve imanlı insanlarla güçlendiren:"},{"n":63,"t":"ki onların yüreklerini O kaynaştırdı; eğer sen yeryüzünün bütün servetini harcasaydın, onların yüreklerinin arasını kaynaştıramazdın, ama Allah onları birleştirdi: çünkü her işinde mükemmel olan, her hükmünde tam isabet kaydeden yalnızca O`dur."},{"n":64,"t":"Sen ey Peygamber! Allah sana da yeter, sana tabi olan gerçek mü`minlere de!"},{"n":65,"t":"Sen ey Peygamber! Savaşta ölüm korkusunu yenmeleri için inananları yüreklendir: Eğer sizden dirençli yirmi kişi olursa, bunlar iki yüz kişiyi alt eder; yok eğer sizden yüz kişi olursa, inkarda direnenlerden bin kişiyi alt eder: çünkü onlar derin kavrayıştan mahrum bir yığındırlar."},{"n":66,"t":"Mevcut şartlarda Allah yükünüzü hafifletmiştir; zira sizin güçsüz olduğunuzu iyi biliyor: O halde, sizden dirençli yüz kişi çıkacak olursa, bunlar iki yüz kişiyi alt eder; ama eğer sizden bin kişi çıkarsa, Allah`ın izni sayesinde iki bin kişiyi alt eder: zira Allah (hakta) direnenlerle beraberdir."},{"n":67,"t":"Kıran kırana gerçekleşmiş sıcak bir savaş sonucu olmadıkça bir peygambere esir almak yakışmaz. Sizler bu dünyanın geçici değerlerini istiyorsunuz; ama Allah (sizin için daha yüce bir değer olan) ahireti istiyor: zira Allah iradesinde pek yüce, işinde hikmetli olandır."},{"n":68,"t":"Eğer Allah tarafından, önceden bir yasal izin olmamış olsaydı, ele geçirdikleriniz yüzünden başınıza korkunç bir felaketin gelmesi kaçınılmaz olurdu."},{"n":69,"t":"Şu halde, ganimet olarak ele geçirdiklerinizin helal ve temiz olanlarını kullanın ve Allah`a karşı sorumlu davranın: unutmayın ki Allah tarifsiz bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":70,"t":"Sen ey Peygamber! Elinizde bulunan esirlere de ki: \"Eğer Allah yüreklerinizde iyi ve güzelin (yerleşik hali olan imana) yatkınlık bulursa, size sizden alınandan daha güzelini bahşedecek; tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağı olan Allah sizi de bağışlayacaktır."},{"n":71,"t":"Ama eğer sana ihanete kalkışırlarsa, unutma ki (senden) daha önce Allah`a ihanet etmişlerdi de, (Allah mü`minlere) onları (uslandırma) imkanı vermişti: zira (unutmasınlar ki) Allah her niyeti bilendir, her işinde tam isabet edendir."},{"n":72,"t":"İmanda sebat eden, zulüm diyarından göç eden, Allah yolunda mallarıyla ve canlarıyla çaba gösteren ve onlara kucak açıp yardım edenlere gelince: işte bunlar birbirlerinin (gerçek) dostudurlar. Ama iman etmiş fakat zulüm diyarından göç edinceye kadar korunup gözetilmeleri konusunda size hiçbir sorumluluk düşmez. Şu var ki, eğer dini baskıya karşı sizden yardım isterlerse, bu durumda size düşen yardım etmektir; yeter ki kendileriyle aranızda anlaşma bulunan bir topluluğa karşı olmasın: çünkü Allah yaptıklarınızın tümünü görmektedir."},{"n":73,"t":"Nitekim, küfre saplananlar (da) birbirleriyle dayanışma içindedirler. Ancak, siz de böyle yapmadıkça yeryüzünde zorbalık ve büyük bir baskı hakim olacaktır."},{"n":74,"t":"Hani o imanda sebat eden, zulüm diyarından göç eden, Allah yolunda var gücüyle çaba gösteren ve onlara kucak açıp yardım edenler var ya: onlar gerçek birer mü`mindirler: Onları, engin bir bağış ve görkemli bir rızık beklemektedir."},{"n":75,"t":"Ve daha sonra inanıp zulüm diyarından göç edecek ve sizinle birlikte Allah yolunda üstün gayret gösterecek kimselere gelince: İşte onlar da sizdendirler; bir de Allah`ın yasası uyarınca, akrabalık bağına sahip olanlar (bu şartlara da uyunca) birbirlerine daha bir yakın hale gelirler. Hiç kuşku yok ki, her şeyi bilen yegane varlık Allah`tır."}],[{"n":1,"t":"Bu, Allah ve O`nun elçisi tarafından, müşrikler içerisinden anlaşma yaptıklarınıza yönelik bir ilişik kesme ilanıdır:"},{"n":2,"t":"Bundan böyle, işte size dört ay daha serbest dolaşım izni! Ama bilin ki siz, Allah`ı asla atlatamayacaksınız; yine unutmayın ki, Allah inkar ve ihanette ısrar edenleri onursuzluğa mahkum edecektir."},{"n":3,"t":"Yine Allah ve O`nun Elçisi`nden, Büyük Hac gününde bütün insanlığa yapılmış bir duyurudur ki; Allah kendine mahsus özellikleri başkalarına yakıştıranlarla ilişiğini kesmiştir; O`nun elçisi de öyle. Bundan böyle tevbe ederseniz, işte bu sizin için daha hayırlıdır; fakat (bu davetten) yüz çevirirseniz, iyi bilin ki siz Allah`ı asla atlatamazsınız. Nitekim, inkar ve ihanette ısrar edenleri can yakıcı bir azap ile müjdele."},{"n":4,"t":"Ne var ki, şirk koşanlar arasından kendileriyle anlaşma yapmış olduğunuz ve daha sonra bu anlaşmayı herhangi bir biçimde ihlal etmeyen ve sizin hasımlarınızdan hiç biriyle dayanışma içine girmeyen kimseler bunun dışındadır. Artık onlarla olan anlaşmanıza süresi doluncaya kadar riayet edin! Unutmayın ki Allah sorumlu davrananları sever."},{"n":5,"t":"Ve (bu) yasak (kapsamındaki) aylar çıktığında, artık müşrikleri tuttuğunuz yerde öldürün; yakalayın, çepeçevre kuşatın, onları her gözetim noktasına kurulup gözetleyin! Fakat eğer onlar tevbe eder, namazı istikametle eda eder ve arınıp yücelmek için ödenmesi gereken bedeli ödemeyi kabul ederlerse, işte o zaman bırakın yakalarını! Unutmayın ki Allah tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":6,"t":"Ve eğer müşriklerden biri senden sığınma hakkı isterse ona sığınak ol; bakarsın Allah`ın kelamına kulak verir. Sonunda onu kendini güvende hissedebileceği bir yere bırak! Böyle davran, çünkü onlar hakikati bilmeyen bir topluluktur."},{"n":7,"t":"Şirk koşan kimselerin Allah`la ve O`nun Elçi`siyle anlaşma yapmaları nasıl mümkün olabilir ki! Ne var ki sizin Mescid-i Haram`ın yanında kendileriyle anlaşma yaptığınız kimseler hariç; onlar size verdikleri söze sadık kaldıkları sürece siz de onlara verdiğiniz söze sadık kalın: unutmayın ki Allah sorumlu davrananları sever."},{"n":8,"t":"(Düşmanlarınızın) size galip gelmeleri halinde, size karşı ne bağlayıcı bir yükümlülük ne de anlaşmadan doğan bir sorumluluk üstlenmemişken, (başka) nasıl olabilirdi ki? Sözleriyle sizi hoş tutmaya çalışırken, yürekleri onları yalanlamaktadır; zira onların çoğu (fıtratın gösterdiği) yoldan çıkmış kimselerdir."},{"n":9,"t":"Allah`ın ayetlerini az bir menfaate değiştiler ve O`nun yoluna engel oldular; onlar, ne berbat şeyler yapıp duruyorlar:"},{"n":10,"t":"Bir mü`min için ne bağlayıcı bir yükümlülük, ne de anlaşma ve yakınlıktan doğan bir sorumluluk gözetiyorlar. İşte böyleleri, haddi aşanların ta kendisidirler."},{"n":11,"t":"Ama eğer kendilerini düzeltir, namazı istikametle kılar ve zekatı gönülden gelerek verirlerse, o zaman sizin dinde kardeşiniz olmuş olurlar. Ve Biz ayetlerimizi, onların (değerini) bilen bir toplum için işte bu şekilde tüm boyutlarıyla açıklıyoruz."},{"n":12,"t":"Fakat, anlaşma yaptıktan sonra sözlerini bozar ve inanç sisteminize hakarete yeltenirlerse, işte o zaman küfrün öncülerine karşı savaş açın; çünkü sözü-sebatı olmayan bu tipler, hainliklerine belki (bu sayede) bir son verirler."},{"n":13,"t":"Hala sözlerini bozan, Elçi`yi kovuncaya kadar çabalayan ve önce kendileri saldırmış bulunan bir toplulukla savaşmayacak mısınız? Yoksa onları gözünüzde büyütüp saygınlık mı kazandırıyorsunuz? Ama, eğer gerçekten imanda ısrarlıysanız, unutmayın ki Allah kendisini tazim edip saygı duymanıza daha layıktır."},{"n":14,"t":"Onlarla savaşın, Allah onlara sizin ellerinizle azap edip onları rezil eder; ve onlara karşı size yardım edip inananların gönlüne ferahlık verir"},{"n":15,"t":"ve kalplerindeki öfkeyi dindirir. Sonuçta Allah dilediğine affını tahsis eder; zira Allah her şeyi bilendir, her hükmünde üstün hikmet sahibidir."},{"n":16,"t":"Yoksa siz, Allah`ın içinizden kendi yolunda tüm çabasını seferber edenleri; Allah`tan, O`nun Elçisi`nden ve inananlardan başkasını can yoldaşı edinmeyecek kimseleri seçip ayırmadan, karma karışık bir halde bırakılacağınızı mı sandınız? Oysa ki Allah yaptığınız her şeyden haberdardır."},{"n":17,"t":"İnkarlarına yine bizzat kendileri tanıklık edip dururken, Allah`ın mescidlerini ziyaret edip onarmak Allah`a ortak koşanlara düşmez. Onlar, yaptıkları boşa gidecek olan kimselerdir; zira onlar ateşte yerleşip kalacaklardır."},{"n":18,"t":"Allah`ın mescidlerini ancak Allah`a ve Ahiret Günü`ne iman eden, namazı istikametle kılan ve zekatı içinden gelerek veren; dahası Allah`tan başka hiç kimseden korkmayan kişiler ziyaret edip onarabilirler. Nitekim, yalnızca böyleleri doğru yolda olmayı umabilir."},{"n":19,"t":"Yoksa siz, (yalnızca) hacıları suvarmayı ve Mescid-i Haram`ı ziyaret edip tamir etmeyi, Allah`a ve Ahiret Günü`ne iman etmek ve Allah yolunda elden gelen gayreti göstermekle eşdeğerde mi tutuyorsunuz? Allah`a göre bunlar birbirine eşdeğer değildirler. Ve Allah, değerleri yerinden etmiş bir toplumu doğruya yöneltmez."},{"n":20,"t":"İman eden ve hicret edenler, Allah yolunda mallarıyla ve canlarıyla her türlü çabayı gösterenler, Allah nezdinde daha yüce bir makama sahiptirler: zira işte onlar başarının gerçek sahibidirler."},{"n":21,"t":"Rableri onları yüce katından bir rahmetle, rıza-yı bari ile ve kendilerini içerisinde kesintisiz her tür nimetin beklediği cennetlerle müjdeler."},{"n":22,"t":"Onlar orada ebedi kalacaklar; çünkü, katında yüce ödül(ler) bulunan yalnızca Allah`tır."},{"n":23,"t":"Siz ey iman edenler! Eğer iman yerine küfrü tercih ediyorlarsa, babalarınızı ve kardeşlerinizi sığınılacak bir can dost olarak görmeyin. İçinizden kim onları sığınılacak bir dost olarak görürse, işte onlar tam anlamıyla zalimce davranmış olurlar."},{"n":24,"t":"De ki: \"Eğer babalarınız, çocuklarınız, kardeşleriniz, eşleriniz, mensubu bulunduğunuz topluluk, kazandığınız mallar, kötüye gitmesinden kaygı duyduğunuz ticaret ve kendisiyle huzur bulduğunuz konaklar; Allah`tan, O`nun Elçisi`nden ve O`nun yolunda cihad etmekten daha sevimli geliyorsa, Allah`ın buyruğu gerçekleşinceye kadar bekleyin! Ne ki Allah, sorumsuzca davranan bir toplumu doğru yola yöneltmez."},{"n":25,"t":"Doğrusu Allah, size bir çok savaş alanında yardım etmişti; özellikle de Huneyn Günü: Hani o zaman çokluğunuz sizi gururlandırmıştı, fakat hiçbir işinize yaramadı; ve olanca genişliğine rağmen yeryüzü size dar gelmişti, sonra da geri kaçmıştınız."},{"n":26,"t":"Daha sonra Allah, Rasulü`ne ve inananlara katından bir sükunet indirmiş, görmediğiniz güçlerle sizi takviye etmiş ve inkarda direnenleri azaba uğratmıştı: Bu ise, inkar edenlerin cezasıydı."},{"n":27,"t":"Fakat bütün bunlara rağmen, Allah kendine yönelmeyi dileyenin yönelişine mukabele edecektir; zira Allah tarifsiz bir bağış, eşsiz bir merhamet kaynağıdır."},{"n":28,"t":"Siz ey iman edenler! Bilin ki şirki karakter haline getiren herkes baştan ayağa pistir. Bu nedenle, bu yıldan sonra Mescid-i Haram`a yaklaşmasınlar. Eğer ekonomik krizden endişe ediyorsanız, unutmayın ki gün gelir, Allah dilerse sizi lutfuyla bolluğa kavuşturur: Zira Allah her (çareyi) bilendir, onu hikmetle (icra) edendir."},{"n":29,"t":"Kendilerine (daha) önceden kitap verilen zümreden Allah`a da ahiret gününe de (gerçek anlamda) inanmayan, Allah ve O`nun Elçisi`nin yasakladığını yasak saymayan ve hak dini tek din olarak benimsemeyen kimselerle, teslim olmuş bir halde güvenlik vergisini kendi elleriyle verinceye kadar savaşın."},{"n":30,"t":"Yahudiler \"Uzeyr Allah`ın oğludur\" dediler; Hıristiyanlarsa \"Mesih Allah`ın oğludur\" dediler. Bunlar, geçmiş dönemlerin ısrarlı inkarcılarının uydurduğu asılsız iddialara özenerek ağızlarında geveledikleri söylentilerdir; Allah kahretsin onları: nasıl da savruluyorlar!"},{"n":31,"t":"Allah`ın peşi sıra, hahamlarını ve rahiplerini -tabi ki Meryem oğlu Mesih`i de- rabler edindiler. Oysa ki tek bir ilahtan başkasına asla kulluk etmemekle emr olunmuşlardı; (O ki), O`ndan başka ilah yok; ve O onların putlaştırdıkları her şeyden beri ve yücedir."},{"n":32,"t":"Onlar Allah`ın (hidayet) nurunu üfürükleriyle söndürmek istiyorlar; Allah ise, nurunu tamamlamak dışındaki bir seçeneğe asla izin vermeyecektir; tabi ki inkar edenler istemese de..."},{"n":33,"t":"O`dur dinin tümünü kendisine bildirmek için Elçisi`ni doğru yol bilgisiyle ve hak din ile gönderen; tabi ki şirke gömülüp gidenler hoşlanmasa da..."},{"n":34,"t":"Siz ey iman edenler! Bilin ki hahamlardan ve rahiplerden bir çoğu insanların mallarını, (ürettikleri) batıl inanç karşılığı boğazlarına geçiriyorlar; böylece (onları) Allah`ın yolundan çeviriyorlar. Hem altın ve gümüş toplayarak servet yapıp, hem de onu Allah yolunda sarf etmeye yanaşmayan kimseler var ya: işte onları can yakıcı bir azap ile müjdele."},{"n":35,"t":"O servetin cehennem ateşinde kızartılıp onların alınlarının, yanlarının ve sırtlarının dağlanacağı gün onlara: \"İşte sırf kendiniz için yığdığınız servetiniz! Haydi, şimdi görün bakalım yığdığınız servetin gününü!\" (denilecek)."},{"n":36,"t":"Bilin ki Allah`a göre ayların sayısı, gökleri ve yeri yarattığı gün Allah`ın koyduğu yasa gereğince on ikidir. Onlardan dördü haram aydır; Allah`ın koyduğu kozmik nizama uygun değerlendirme budur. O halde, bu konuda kendinize kötülük etmeyin! Tabii ki onların sizinle topyekün savaştığı gibi siz de onlarla topyekün savaşın: ama iyi bilin ki Allah sorumlu davrananlarla birliktedir."},{"n":37,"t":"Aylara yapılan ilave, olsa olsa küfre yapılmış bir ilavedir: İnkarda direnenlerin çarpıtma yöntemidir bu; Allah`ın haram kıldığı ay sayısına denk getirmek amacıyla bu uygulamayı bir yıl serbest bir yıl yasak sayıyorlar ve işte bu şekilde Allah`ın yasakladığını meşru görüyorlar. Kötü fiilleri onlara pek cazip göründü; kaldı ki Allah inkara gömülmüş bir toplumu doğru yola yöneltmez."},{"n":38,"t":"Siz ey iman edenler! Size ne oluyor da \"Allah yolunda savaşa çıkın!\" denildiğinde yere çakılıp kalıyorsunuz? Öte dünyadan vazgeçip bu dünya hayatıyla mı tatmin oldunuz? Ama unutmayın ki, bu dünya hayatının sefası öte dünyaya kıyasla pek değersizdir."},{"n":39,"t":"Eğer savaşa çıkmazsanız, size acı bir azap çektirir ve sizin yerinize başka bir toplum getirir de (yokluğunuzla) O`na hiçbir zarar açmış olmazsınız: Zira Allah her şeye kadirdir."},{"n":40,"t":"Eğer ona destek vermezseniz, unutmayın ki ona Allah yardım edecektir: inkarda direnenler onu sürüp çıkardıkları zaman (Muhammed sadece) iki kişiden biriydi. Hani o ikisi mağaradayken, o arkadaşına \"Tasalanma, Allah bizimle beraberdir!\" demişti de, bunun üzerine Allah ona katından bir sükunet indirmiş ve onu sizin göremediğiniz güçlerle takviye etmişti: böylece inkarda ısrar edenlerin davasını alçalttı, Allah`ın davasıysa en yüce olma konumunu korudu; çünkü Allah`tı her işinde mükemmel olan, her hükmünde üstün hikmetler bulunan."},{"n":41,"t":"Kolay da gelse zor da gelse savaşa çıkın ve Allah yolunda mallarınızla, canlarınızla olanca gücünüzü sarf edin: eğer fark ederseniz, bu sizin için daha yararlıdır."},{"n":42,"t":"Eğer yakın bir menfaat ve kolay bir sefer olsaydı, senin ardına tereddütsüz takılırlardı. Fakat bu zorlu yolculuk onlara pek uzun geldi. Üstelik, \"Eğer gücümüz olsaydı kesin sizinle çıkardık\" diye Allah adına yemin ederek kişiliklerini mahvedecekler: Oysa ki, Allah onların yalancı olduğunu çok iyi biliyor."},{"n":43,"t":"Allah seni affetsin; daha kimin doğru söylediği sana aydınlanmadan ve yalancıları iyice öğrenmeden niçin onlara (savaşa katılma) izni verdin?"},{"n":44,"t":"Allah`a ve Ahiret Günü`ne (yürekten) güvenip inanan kimseler mallarıyla ve canlarıyla zaten cihat etmeleri hasebiyle, senden cihada çıkmak için izin isteme gereği duymazlar. Allah sorumlu davranışta sebat edenleri çok iyi bilir."},{"n":45,"t":"Yalnızca Allah`a ve Ahiret Günü`ne (yürekten) güvenip inanmayan kimseler senden (cihada) katılma izni isterler; zira onların kalpleri kuşkuya teslim olmuştur, bu yüzden (katılsak mı, katılmasak mı diye) derin tereddütler içerisinde bocalayıp dururlar."},{"n":46,"t":"Hem, eğer (gerçekten) sefere çıkmak isteselerdi elbet bir hazırlığa girişirlerdi; fakat Allah onların kalkış biçimlerini beğenmedi, bu yüzden de onları alıkoydu. Adeta onlara, \"(Sefere ehil olmayıp) oturanlarla birlikte siz de oturun!\" denildi."},{"n":47,"t":"Eğer sizinle birlikte sefere çıkmış olsalardı, sorun çıkarmaktan başka size bir katkıları olmayacaktı. Zira içinizden kendilerini can kulağıyla dinleyecek olanları görüp aranıza daha fazla fitne sokmak amacıyla saflarınıza daha bir sokulacaklardı: ama Allah o zalimleri çok iyi bilmektedir."},{"n":48,"t":"Zaten onlar daha önce de fitne çıkarmaya çalışmışlar ve sana karşı epey işler çevirmişlerdi; ta ki hak tecelli edinceye ve Allah`ın yasası onların hoşuna gitmeyecek bir biçimde gerçekleşinceye dek."},{"n":49,"t":"Onlardan kimileri de \"İzin ver bana, beni günaha sokma!\" der. Şu işe bakın ki, baştan ayağa günaha gömüldüler: Üstelik, nankörlükte ısrar edenler bir de cehennem tarafından kuşatılacaktır."},{"n":50,"t":"Eğer sana bir iyilik dokunsa onların canı sıkılır. Ama başına bir kötülük gelse; \"İyi ki biz daha önceden önlemlerimizi almıştık\" derler ve şen şakrak dönüp giderler."},{"n":51,"t":"De ki: \"Başımıza, Allah`ın bizim için yazdığından başka bir şey gelmez; O`dur bizim tek sahibimiz; şu halde inananlar yalnızca O`na güvensinler!\""},{"n":52,"t":"De ki: \"Bizim için iki güzellikten biri değil de, ille de (kötülük) beklentisi içinde misiniz? Bizim size ilişkin beklentimizse -O`nun katından ya da bizim elimizle- Allah`ın gazabına uğramanızdır. Artık bekleyin; bilin ki biz de sizinle birlikte bekliyoruz!\""},{"n":53,"t":"De ki: \"İster gönüllü infak edin ister gönülsüz; sizden asla kabul edilmeyecektir: çünkü siz, hepten sapık bir güruh haline geldiniz.\""},{"n":54,"t":"Onların hayır için harcadıklarının kabülüne tek engel, Allah`a ve O`nun Elçisi`ne ısrarla nankörlük etmeleridir; onlar namaza hep üşene üşene katılırlar ve onlar her daim gönülsüzce hayır yaparlar."},{"n":55,"t":"Artık onları, (sınamak için verdiğimiz) mallarının ve çocuklarının (çokluğuna) şaşırma; Allah bütün bunlar nedeniyle onlara dünyada bela vermek ve canlarını kendileri inkara saplanmışken almak istiyor."},{"n":56,"t":"Ve onlar, kendilerinin sizden olduğuna dair Allah adına yemin ederler; oysa ki onlar sizden değildirler; ve fakat onlar, korkuya teslim olmuş bir güruhturlar."},{"n":57,"t":"Eğer bir sığınak, bir mağara ya da bir korunak bulabilselerdi, sürü içgüdüsüyle panik halinde oraya seğirtirlerdi."},{"n":58,"t":"Onlar arasında, sadaka ve zekatların (dağıtımı) konusunda sana dil uzatanlar var: eğer kendilerine ondan bir pay verirsen seslerini keserler, yok eğer kendilerine ondan bir pay vermezsen, o zaman da öfkelerini kusarlar."},{"n":59,"t":"Ah keşke onlar Allah`ın ve O`nun Elçisi`nin kendilerine verdikleriyle yetinselerdi; ve \"Allah bize yeter; gün gelir de Allah lutfundan bize (bir pay) verirse, O`nun Elçisi de (bize takdim eder); elbet biz ta gönülden Allah`a yönelmişiz\" deselerdi."},{"n":60,"t":"Zekatlar yalnızca yoksullara ve düşkünlere, bu işi yapan görevlilere ve kalpleri kazanılacak kimselere, özgürlükleri elinden alınanlar ve borç yükü altında ezilenler için, Allah yolunda gösterilen her türlü faaliyet ve yolda kalmışlar için verilir: bu Allah`ın koyduğu bir kuraldır. Ve Allah her şeyi bilir, her hükmünde tam isabet sahibidir."},{"n":61,"t":"Yine o (ikiyüzlüler) arasında, \"O (her sözü dinleyen) som bir `kulak`tır\" diyerek Peygamber`i rencide eden kimseler var. De ki: (Öyle ama), sizin için hayırlı bir `kulak`tır: Allah`a iman eder, mü`minlere ise güvenir; üstelik içinizden imanda sebat edenler için bir rahmettir. Allah`ın Elçisi`ni rencide edenlere gelince: onları pek acı bir azap beklemektedir."},{"n":62,"t":"Onlar, sizi hoşnut etmek için size Allah adına yeminler ederler. Oysa ki daha öncelikli bir görevleri var: Allah`ı hoşnut etmek, O`nun Elçisi`ni de... Tabi ki yürekten inanmışlarsa eğer!"},{"n":63,"t":"Yoksa onlar şunu bilmiyorlar mı: kim Allah`a ve O`nun Elçisi`ne meydan okursa, işte o içinde daimi kalmak üzere cehennem ateşine atılır; en dehşet onursuzluk da budur."},{"n":64,"t":"İkiyüzlüler kendileri hakkında, kalplerinde olanı sana haber veren bir sure inmesinden endişe ediyorlar. De ki: \"Alay edin bakalım! Nasıl olsa Allah korktuğunuzu başınıza getirecektir.\""},{"n":65,"t":"Dönüp kendilerine sorsan, elbet şöyle diyecekler: \"Kendimizi lafa kaptırmıştık, eğleniyorduk, hepsi bu!\" de ki: \"Allah`la, O`nun ayetleriyle ve O`nun Elçisi`yle mi eğlenip duruyordunuz?"},{"n":66,"t":"Bahane üretmeyin! Doğrusu siz, inandığınızı (açıkladıktan) sonra da küfre saptınız. Bir kısmınızı suçu savunmalarından dolayı cezalandıracağız."},{"n":67,"t":"İkiyüzlü erkekler ve ikiyüzlü kadınlar; hepsi birbirine benzerler: Kötü ve yanlış olanı teklif eder, iyi ve doğru olanı önlerler; ve (iyilik için) ellerini oynatmazlar. Onlar Allah`ı unuttular, bu yüzden Allah da onları hatırlanmaya değer bulmadı. Gerçekte sapık olan işte bunlar, bu münafıklardır."},{"n":68,"t":"Allah, ikiyüzlü erkeklerle ikiyüzlü kadınlara ve inkarını açıkça ortaya koyanlara, içinde daimi kalmak üzere cehennem ateşini vaad etmiştir: odur onların payına düşen; zira Allah onları rahmetinden dışlamıştır; dolayısıyla onlar sürekli bir azaba mahkum olacaklardır."},{"n":69,"t":"(De ki onlara): \"(Siz de) tıpkı sizden önceki (ikiyüzlüler) gibisiniz. Onlar kuvvet bakımından sizden daha güçlüydüler, servet ve sayıca daha fazlaydılar; fakat bu dünyadan paylarına düşenle safa sürmeyi seçtiler; siz de kendi payınıza düşenle safa sürmeyi seçtiniz; tıpkı sizden öncekilerin kendi paylarına düşenle safa sürmeyi seçtikleri gibi: sonunda siz de aynı onlar gibi batılın bataklığına saplandınız. Önünde de sonunda da, bu tür kimselerin çabaları boşa gidecektir; sonunda kaybedecek olan da bunlardır."},{"n":70,"t":"Yoksa kendilerinden önce geçip gidenlerin, Nuh kavminin, Ad ve Semud`un, İbrahim kavminin, Medyen ahalisinin ve bütün o altı üstüne gelmiş kentlerin (felaket) haberleri onlara ulaşmadı mı? Öncekilere (de) elçileri hakikatin apaçık delilleriyle gelmişlerdi (fakat inkar ettiler). Sonuçta, Allah onlara kıymış değildi; fakat onlar asıl kendi kendilerine kıydılar."},{"n":71,"t":"Ama inanan erkekler ve inanan kadınlar (da) birbirlerinin dostu, koruyucusudurlar: İyi ve doğru olanı teklif eder, kötü ve yanlış olanı önlerler; ve namazı içtenlikle kılarlar, zekatı da seve seve verirler; Allah`a ve O`nun Elçisi`ne uyarlar: işte onlardır Allah`ın rahmetini bahşedeceği kimseler; çünkü her işinde mükemmel olan, her hükmünde tam isabet kaydeden yalnızca Allah`tır."},{"n":72,"t":"Allah, inanan erkeklere ve inanan kadınlara zemininden ırmaklar çağlayan cennetler vaad etti; orada daimi kalıcıdırlar; hele bir de Allah`tan gelen tarifi imkansız hoşnutluk, bu (mutlulukların) en büyüğü olacaktır; bu, işte budur muhteşem zafer."},{"n":73,"t":"Sen ey peygamber! İnkarı ısrarla savunanlarla ve ikiyüzlülüğü tabiat haline getirenlerle mücadele et ve onlara karşı ödünsüz davran! Sonunda karar kılacakları yer cehennemdir ve o ne berbat bir son duraktır."},{"n":74,"t":"Onlar, (kötü) bir söz söylemediklerine ilişkin Allah adına yemin ediyorlar; oysa ki onlar kesinlikle küfre varan sözler söylemişler, böylece Allah`a teslim olmalarından sonra inkara sapmışlar ve başarmaları mümkün olmayan bir işe soyunmuşlardı. Onların kin duymaları için, Allah`ın ve O`nun lutfu sayesinde Elçisi`nin kendilerini zengin ve yetkin hale getirmesi dışında bir neden yok ki! Artık tevbe ederlerse, bu kendileri hakkında daha hayırlı olur; yok eğer yüz çevirirlerse, Allah onları bu dünyada da öte dünyada da pek acı bir azaba çarptıracak; ve onlar yeryüzünde kendileri için ne bir dost, ne de bir yardımcı bulabileceklerdir."},{"n":75,"t":"Hem, onlar arasında \"Eğer O`nun bağışladıklarından bize de bir şeyler düşerse, elbet biz de hayır hasenat için harcar, böylece biz de iyiler arasına karışmış oluruz!\" diye Allah`a yemin edenler var."},{"n":76,"t":"Ama onlar, Allah kendilerine lutfundan bağışlar bağışlamaz onda cimrilik ederler ve (yeminlerinden) geri dönerler: zira onlar dönektirler."},{"n":77,"t":"Bunun üzerine O da, Zatıyla karşılaşacakları güne kadar kalplerinde (taşıyacakları) bir nifakı başlarına sarar. Bu, onların Allah`a verdikleri sözden dönmeleri ve yalan söylemeyi alışkanlık haline getirmeleri yüzündendir."},{"n":78,"t":"Bilmiyorlar mı ki Allah, onların sırlarından ve gizli görüşmelerinden çok iyi haberdardır; zira, iyi bilsinler ki Allah her türlü gizliliği tüm ayrıntılarıyla bilir."},{"n":79,"t":"Onlar, (yürekten) inananlar arasından, hem vermesi gerekenden fazlasını gönlünden koparak verenlere, hem de gündelik emeğinden başka verecek bir şey bulamayanlara dil uzatmakta ve onlarla alay etmektedirler. Allah onların alaylarını başlarına geçirecektir ve acıklı bir azap onları beklemektedir."},{"n":80,"t":"Onların bağışlanmaları için Allah`tan ister af dile, ister dileme: Onlar için Allah`tan yetmiş kez af dilemiş olsan dahi, artık Allah onları asla affetmeyecektir. Bunun nedeni, onların Allah`a ve O`nun Elçisi`ne ısrarla nankörlük etmeleridir; zira Allah (fıtrat) yolundan sapmış kimseleri doğru yola yöneltmez."},{"n":81,"t":"Terk edilen (bu) kimseler, Rasululllah`a muhafelet ederek oturup kalmalarına sevindiler ve Allah yolunda mallarıyla ve canlarıyla cihad etmekten hoşlanmadılar; bir de kalkıp \"Şu sıcakta savaşa çıkmayın!\" diye propaganda yaptılar. Onlara \"Cehennem ateşi daha sıcaktır!\" de; tabii ki bunun bilincine varabilirlerse!"},{"n":82,"t":"Artık, bundan böyle (dünyada) az biraz gülsünler; fakat kazandıklarının bir karşılığı olarak (ukbada) çok ağlayacaklar!"},{"n":83,"t":"Bundan sonra, Allah sana (seferden) dönmeyi nasip eder de onlardan bir grupla karşılaştırırsa, dahası onlar senden savaşa çıkma izni isterlerse, de ki: \"Bundan böyle benimle kesinlikle sefere çıkmayacaksınız; ve benimle birlikte asla düşmana karşı savaşmayacaksınız! Madem siz bir kez oturup kalmaya razı oldunuz, bundan sonra da geri kalanlarla birlikte oturmayı sürdürün!\""},{"n":84,"t":"Ve onlardan ölen herhangi birinin namazını kılma ve kabrinin başında da asla bulunma! Çünkü onlar Allah`a ve Elçisi`ne nankörlük ettiler ve yoldan sapmış bir halde öldüler."},{"n":85,"t":"Ve onların malları da, çocukları da seni hayrete düşürmesin: şu kesin ki Allah, bu şeyleri dünyada onlar için bir azaba dönüştürmek ve canlarını inkara gömülüp gitmişken çekip almak istiyor."},{"n":86,"t":"Hem, ne zaman \"Allah`a güvenip iman edin ve Elçisi`yle birlikte cihad edin!\" diyen bir pasaj indirilse; içlerinden durumu gayet müsait olanlar (bile) senden izin isteyerek derler ki: \"Bırak bizi, oturanlarla birlikte oturalım!\""},{"n":87,"t":"Geri kalanlarla birlikte olmayı gönülden kabullendiler; sonunda kalplerine mühür basıldı: artık onlar gerçeği kavrayamazlar."},{"n":88,"t":"Fakat, Elçi ve onunla birlikte iman edip mallarıyla ve canlarıyla cihad eden kimseler var ya: işte onları hayırlı sonuçlar beklemektedir; üstelik kurtuluşa erecek olan da onlardır."},{"n":89,"t":"Allah onlar için, zemininden ırmaklar çağlayan, içerisinde ebedi kalacakları Cennetler hazırlamıştır: işte budur muhteşem zafer."},{"n":90,"t":"Bedevilerden beyan edecek özrü olanlar, hiç değilse gelip kendilerine (savaşa katılmama) izni verilmesini talep ettiler; Allah ve Rasulü`nü yalanlayanlar ise oturup kaldılar. Onlardan nankörlükte ısrar edenlere, er geç acıklı bir azap dokunacak."},{"n":91,"t":"Zayıflar, hastalar, infak edecek bir şey bulamayan yoksul kimseler için, Allah`a ve Rasulü`ne karşı samimi oldukları sürece bir sorumluluk yoktur; iyilik yapanları sorumlu tutacak bir gerekçe de yoktur. Zira Allah tarifsiz bağışlayan, eşsiz merhametiyle kuşatandır."},{"n":92,"t":"Bir de sana kendilerine binek sağlaman için geldiklerinde, \"Sizi bindirecek bir şey bulamıyorum\" dediğin zaman, bu yolda harcayacak bir şey bulamadıkları için üzüntüden iki gözü iki çeşme geri dönenlere de bir sorumluluk yoktur."},{"n":93,"t":"Sorumluluk ancak, yeterli varlık sahibi olduğu halde senden izin isteyen kimseler için geçerlidir. Onlar geri kalanlarla birlikte bulunmayı içlerine sindirdiler, Allah da onların yüreklerini mühürledi: öyle ki, artık onlar yaptıklarının farkına dahi varmıyorlar."},{"n":94,"t":"Seferden dönüp de karşılaştığınız zaman size bahaneler sıralayacaklar. De ki: \"Boşuna bahane üretmeyin, kesinlikle size inanmayacağız! Allah sizin (gerçek) durumunuzdan bizi haberdar etmiştir. Allah da, Rasulü de yaptıklarınızın (hesabını) görecektir. En sonunda görülemeyeni ve görüleni ayrıntılarıyla Bilen`in huzuruna çıkartılacaksınız; ve O size, yapıp ettiklerinizi bir bir haber verecektir."},{"n":95,"t":"Dönüp de üzerlerine vardığınızda, sizi baştan savmak için Allah adına size yemin edeceklerdir. Madem öyle, siz de bırakın yakalarını! Çünkü onlar iğrençleşmiş varlıklardır; sonunda yaptıklarına bir karşılık olarak varacakları yer Cehennemdir."},{"n":96,"t":"Kendilerinden razı olasınız diye size yemin ediyorlar. Bilmiyorlar ki, siz kendilerinden razı olsanız dahi Allah yoldan sapmış bir topluluktan asla razı olmayacaktır."},{"n":97,"t":"Bedevi Araplar, inkar ve ikiyüzlülük açısından (kentsoylulardan) daha katıdırlar; ve Allah`ın, Elçisine indirdiği hayat tarzının sınırlarını tanıyıp kavramamaya daha yatkındırlar: Allah bu (gerçeği) de çok iyi bilendir, (ama) hikmetle iş görendir."},{"n":98,"t":"Bedevi Araplardan gönlü (Allah yolunda) harcadığı şeyde kalanlar var ve zamanın aleyhinize dönmesini gözleyenler var; bekledikleri bela girdabını kendileri boylayacaktır: zira Allah her şeyi işitmekte, her hesabı tarifsiz bir bilgiyle bilmektedir."},{"n":99,"t":"Bedevi Araplar arasında Allah`a ve Ahiret Günü`ne iman eden, (Allah yoluna) harcadığı her şeyi Allah katında bir yakınlık ve Elçi`nin dua ve desteğini alma vesilesi bilenler de var: Bakın, işte bu onların yakınlığına gerçek bir vesile olacaktır (ve) Allah onları rahmetiyle kuşatacaktır: çünkü Allah tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":100,"t":"Muhacirler`in ve Ensar`ın önderlik yapan ilklerine ve iyilik yolunda onların izini takip edenlere gelince: Allah onlardan razı, onlar da Allah`tan razı olmuştur; ve onlar için zemininden ırmaklar çağlayan ebedi kalacakları Cennetler hazırlamıştır: işte budur büyük mutluluk."},{"n":101,"t":"Ne ki çevrenizdekilerden bedevi Araplar arasında ikiyüzlüler ve şehir ahalisi arasında da ikiyüzlülükte zirveleşenler var. Sen onları tanımıyorsun, (ama) Biz tanıyoruz. Onlara (bu dünyada) iki kat azap çektireceğiz, (bu hayatın) sonunda ise korkunç bir azaba sevk edileceklerdir."},{"n":102,"t":"Bir de ilkin iyi olan işini, kötü olan ötekisiyle karıştırıp (en sonunda) günahını itiraf eden berikiler var. Allah`ın onların af taleplerini kabul etmesi beklenir; çünkü Allah tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":103,"t":"Onların Allah`a sadakatlerini ifade için mallarından bir miktar sadaka al; bu sayede, onların temizlenmelerine ve inkişafına yol açmış olursun. Ve onları dua ile destekle; çünkü senin duan, onlar için bir gönül ferahlığıdır: Hem Allah tüm (duaları) işitir ve (kime neyi vereceğini) çok iyi bilir."},{"n":104,"t":"Bilmiyorlar mı ki Allah, evet yalnızca O`dur kullarının tevbelerini kabul eden; O`na sadakatlerini ifade için mallarından sunduklarını kabul buyuran da O: hem unutmasınlar ki Allah, tevbeleri hep kabul edendir, merhametiyle muamele edendir!"},{"n":105,"t":"Tekrar de ki: \"(Durmayın), değer üretin! Nasıl olsa ürettiğiniz değeri Allah görüyor, O`nun Elçisi de, mü`minler de... En sonunda görülemeyeni ve görüneni ayrıntılarıyla Bilen`in huzuruna çıkartılacaksınız: nihayet O size yapıp ettiklerinizi bir bir haber verecektir.\""},{"n":106,"t":"Bir de, durumları Allah`ın takdirine kalmış bir grup insan daha var. Allah isterse onları cezalandırır, isterse onların tevbelerini kabul eder: Zira Allah her şeyi bilir, her takdirinde tam isabet sahibidir."},{"n":107,"t":"Ayrıca, zarar vermek, inkarda direnmek, inananlar arasına ayrılık sokmak ve öteden beri Allah ve O`nun Elçisi`ne savaş açan kimseler adına gözetleme yapmak amacıyla ibadethane inşa edenler var. Üstelik onlar, \"Amacımız daha güzelini ortaya koymaktır\" diye ısrarla yemin ederler; ama Allah şahittir ki onlar, kesinlikle yalancıdırlar:"},{"n":108,"t":"Asla orada ibadete durayım deme! (Beri yanda) ilk günden beri Allah kaygısı üzerine inşa edilmiş olan bir ibadethane daha var; ibadete durmana en layık olan da burasıdır. Burası, arınıp tertemiz olmak için can atan adamların yeridir: zira Allah itina ile temizlenen kimseleri pek sever."},{"n":109,"t":"Şimdi, (hayat) binasını Allah kaygısı ve rızası temelleri üzere inşa eden kimse mi daha iyidir; ya yoksa binasını suyun altına oyduğu kırılgan bir yar üzerine yapıp, sonunda da onunla birlikte Cehennem ateşine yuvarlanan kimse mi? Allah, zulmü içselleştiren bir toplumu asla doğru yola yöneltmez."},{"n":110,"t":"Yüreklerindeki kuşku (uçurumu) üzerine inşa ettikleri (hayat) binası, ancak yüreklerini paramparça edinceye kadar dayanacaktır. Allah, hem (onların bu halini) bilen, hem de hikmeti gereği (buna izin veren)dir."},{"n":111,"t":"Kuşku yok ki Allah yolunda çarpışan, öldüren ve öldürülen mü`minlerden Allah, karşılığında Cennet vaad ederek mallarını ve canlarını satın almıştır. Bu Allah`ın Tevrat`ta, İncil`de ve Kur`an`da gerçekleştirmeyi üstlendiği bir vaaddir: hem, sözüne Allah`tan daha sadık kim olabilir ki? Öyleyse sevinin O`nunla böyle bir alışveriş yaptığınız için; bu, işte budur muhteşem mutluluk!"},{"n":112,"t":"(Bu), ne zaman bir günah işleseler hemen tüm varlığıyla O`na yönelenlerin, yalnız O`na kulluk edenlerin, övgülerin tamamını sadece O`na hasredenlerin, seyyah olup O`nun rızasının peşine düşenlerin, yalnızca O`nun önünde eğilip, sadece O`nun huzurunda yere kapananların, iyi ve doğru olanı önerip kötü ve yanlış olandan alıkoyanların ve Allah`ın koyduğu sınırları kesintisiz koruyanların (mutluluğudur). O halde, (bu evsaftaki) tüm mü`minleri müjdele."},{"n":113,"t":"(Küfre saplanarak ölenlerin) cehennemlik olduğu kendilerine açıklandıktan sonra, müşrikler için -isterse yakın akrabalık bağları bulunsun- Allah`tan af dilemek, ne Peygamber`e ne de iman eden kimselere hiç yakışık almaz."},{"n":114,"t":"İbrahim`in babası için Allah`tan af dilemesinin nedeni, yalnızca berikinin diğerine (hayattayken) verdiği bir söze dayanıyordu. Fakat, diğerinin Allah düşmanı olduğu onun için kesinlik kazanınca ondan hemen el çekti. Zaten İbrahim çok yufka yürekli, yumuşak huylu biriydi."},{"n":115,"t":"Hem Allah hiç bir topluluğu, -(akıl, fıtrat ve irade ile) doğru yolu gösterdikten sonra (bile)- korunup sakınacakları şeyleri kendilerine bütünüyle açıklamadıktan sonra sapıklıkla suçlamaz. Elbette her şeyi bilen sadece Allah`tır."},{"n":116,"t":"(Ve) elbette göklerin ve yerin hakimiyeti yalnızca Allah`a aittir: Hayatı da ölümü de O takdir eder. Sonuçta sizin için Allah dışında ne bir yar, ne de bir yardımcı var."},{"n":117,"t":"Doğrusu şu ki: Allah, Peygamber`e, (imkanların tükendiği yerden imkanların üretileceği yere göç eden) muhacirlere, (zorluk demlerinde kendi imkanlarını onlarla paylaşan) Ensar`a, üstelik içlerinden bir kısmının kalbinin kaymaya yüz tuttuğu bir durumun ardından, rahmet ve bağışıyla yöneldi. Evet, onların tevbelerini kabul etti; çünkü O`nun sınırsız şefkat ve merhameti, onları da kuşatır."},{"n":118,"t":"Yine geri kalan üç kişiye de (Allah, şefkat ve merhametiyle yöneldi). O kadar ki olanca genişliğine rağmen yeryüzü onlara dar gelmiş, dahası vicdanları da kendilerini sıkıştırmıştı; sonunda Allah`tan yine Allah`a kaçıp sığınmaktan başka çare olmadığını anladılar. Ardından O da onlara rahmetiyle yöneldi ki, onlar af dilemek için Kendisine dönsünler: İyi bilin ki Allah, evet yalnızca O`dur tevbeleri kabul eden, rahmetiyle muamele eden!"},{"n":119,"t":"Siz ey iman edenler! Allah`a karşı sorumluluğunuzun bilincine varın ve dürüst kimselerle birlikte olun!"},{"n":120,"t":"(Peygamber) şehrinin halkına ve çevresindeki bedevilere, ne Allah`ın Elçisi`nden geriye kalmak, ne de kendi canlarını onunkinden fazla sakınmak yaraşır. Şöyle ki; ne zaman onların başına Allah yolunda bir susuzluk, yorgunluk ve şiddetli açlık gelse; ne zaman inkara gömülenleri öfkelendiren bir hamle yapsalar ve ne zaman mukadder olan sonuca düşman eliyle ulaşsalar; mutlaka bu onların lehine üretilmiş bir değer olarak yazılmaktadır: Elbette Allah iyilerin hakkını zayi edecek değildir."},{"n":121,"t":"Yine onlar, az ya da çok Allah yolunda her ne harcamışlar ve hangi vadide ne yol almışlarsa, Allah`ın onları yaptıklarından dolayı en güzel bir biçimde ödüllendirmesi için, elbet o da onların lehine kayda geçirilmektedir."},{"n":122,"t":"Fakat, (yeni) mü`minlerin (dini öğrenmek için) hep birlikte yola koyulmaları doğru olmaz; onlar arasından her gruptan birileri (Medine`ye doğru) yola çıkmalı, dinde derin bir anlayış ve ilim elde etmek için (orada) çaba harcamalı ve kendi toplumları arasına geri döndükleri zaman da, onları uyarmalı değil mi; belki de böylece (ileride doğacak) birtakım mahzurlar (önceden) engellenmiş olur."},{"n":123,"t":"Siz ey iman edenler! İnkara gömülenler arasından size en yakın (tehdit) oluşturanlara karşı savaşın! Ve sizin şahsınızda sert bir direnişe şahit olsunlar. Hem şunu iyi bilin ki, Allah sorumlu davrananların yanındadır."},{"n":124,"t":"Ne zaman Kur`an`dan bir bölüm indirilse, hemen onlardan birileri: \"Bu hanginizin imanını artırdı?\" derler. Hani iman edenler var ya: bu onların imanlarını tabii ki artırmıştır; ve elbet onlar bunun sevincini ve müjdesini paylaşırlar."},{"n":125,"t":"Bir de kalpleri hastalıklı kimseler var; ve bu onların çirkefliklerinin katmerlenmesine yol açmıştır; en sonunda onlar, (boğazlarına kadar gömüldükleri inkarda) kafir olarak ölüp gidecekler."},{"n":126,"t":"Görmüyorlar mı ki her yıl bir ya da iki kez skandala konu oluyorlar, sonra da ne tevbe ediyorlar ne de ders alıyorlar!"},{"n":127,"t":"Bir de, ne zaman bir sure indirilse; \"Sizi görecek biri mi var ki?!\" (der gibi) birbirlerine bakıyorlar, peşinden de dönüp gidiyorlar. Allah onların kalplerini (haktan) döndürmüştür; çünkü onlar anlayışsız bir topluluktur."},{"n":128,"t":"Doğrusu (ey insanlık)! Size kendi türünüzden bir Elçi gelmiştir ki o pek azizdir: sizin zorlanmanız ona pek ağır geliyor, üzerinize hassasiyetle titriyor; çünkü o mü`minlere karşı şefkat pınarı bir rauf, merhamet abidesi bir rahimdir."},{"n":129,"t":"(Bu gerçek ortadayken) yine de onlar yüz çevirirlerse, de ki: \"Allah bana yeter, O`ndan başka ilah yok, ben hep O`na güvenmişimdir; çünkü O en yüce hükümranlık makamının Rabbidir!\""}],[{"n":1,"t":"Elif-Lam-Ra! İşte bunlar, her hükmünde tam isabet kaydeden ilahi kelamın ayetleridir."},{"n":2,"t":"İçlerinden bir erkeğe: `İnsanları (azâb ile) korkut ve îmân edenlere, Rableri katında şübhesiz ki kendileri için bir `kadem-i sıdk’ (peygamberin şefâati) bulunduğunu müjdele!` diye vahyetmemiz, insanlar için şaşılacak bir şey mi oldu (da) kâfirler: `Şübhesiz bu, gerçekten apaçık bir sihirbazdır!` dedi(ler)."},{"n":3,"t":"Kuşkusuz sizin Rabbiniz, gökleri ve yeri altı devrede yaratan; ve sınırsız güç ve kudret makamına kurulup varlığı yöneten Allah`tır. O`nun izni olmadan kimse şefaatçi olamaz. İşte bu (niteliklere sahip) olan Allah`tır sizin Rabbiniz; artık yalnız O`na kulluk edin: Hala öğüt almayacak mısınız?"},{"n":4,"t":"Hepinizin dönüşü O`nadır; (bu) Allah`ın gerçekleşmesi kaçınılmaz vaadidir. Çünkü O, insanı yaratmaya başladıktan sonra onun yaratılışını sürdürüyor ki; iman edip de ıslah edici iyi şeyler yapanları hak ettiklerinden fazlasıyla ödüllendirsin. İnkarda ısrar edenlere gelince: inkarda direnişleri nedeniyle, yudum yudum içecekleri kavurucu bir pişmanlık ve can yakıcı bir azap onları bekleyecek."},{"n":5,"t":"Güneşi aydınlığın kaynağı ve ayı ışık yansıtıcı yapan; yılların sayısını ve hesabı(nı) bilesiniz diye ona evreler takdir eden O`dur. Bunu başka değil, hakiki bir gaye (bir atıf olsun) için halk eden Allah, bilmek isteyen bir toplum için varlık ayetlerini ayrıntılı olarak açıklıyor."},{"n":6,"t":"Çünkü gecenin ve gündüzün birbiri ardınca gelişi ve Allah`ın göklerde ve yerde yarattığı her şey, sorumluluk bilinci taşıyan bir toplum için hakikate yapılmış birer atıftır."},{"n":7,"t":"Şu da bir gerçek ki; bizim huzurumuza çıkmaya yüzü olmayanlar ve dünya hayatıyla yetinip onunla kendilerini tatmin edenler, üstelik (bir de) hakikate yapılmış (söz konusu) atıfları fark edemeyenler var:"},{"n":8,"t":"işleye geldikleri bütün bu şeylerden dolayı onların son durağı ateştir."},{"n":9,"t":"Ne var ki iman eden ve imana layık davranışta bulunanlara gelince: Rableri onları imanları sayesinde, ayaklarının altından nehirler çağlayan, nimetlerle dolu Cennetlere ulaşan yola yöneltecektir."},{"n":10,"t":"Orada onların nidaları \"Muhteşemsin ey Allah`ım!\" olur; ve kendilerine \"Mutluluklar!..\" diye mukabele edilir orada. Nihayet onların son nidası yankılanır: \"el-hamdu lillahi Rabbi`l`alemin!\" (Hamd, bütün alemlerin Rabbi Allah`a mahsustur!)"},{"n":11,"t":"Eğer onların nimeti istemede acele ettikleri gibi Allah da insanlar için (hak ettikleri) cezayı vermede acele etseydi, onların sonunu getirecek hüküm hemen infaz edilirdi. Şu halde, bizim huzurumuza çıkmaya yüzü olmayanları küstahça taşkınlıkları içerisinde debelenmeye terkederiz."},{"n":12,"t":"Hem ne zaman insanoğlunun başına bir ziyan gelse, gerek yatarken, gerek otururken ya da ayaktayken (başlar) Biz`e yalvarıp yakarmaya. Biz onu, başına gelen ziyandan kurtardığımız zaman ise, sanki kendisine dokunan ziyandan kurtarmamız için Biz`e hiç yalvarmamış gibi (nankörleşir). Değere dönüşebilecek tüm imkanlarını boşa harcayanlara yaptıkları, (işte) böylesine cazip görünür."},{"n":13,"t":"Doğrusu sizden önceki bir çok nesli de, kötülük odağı olmaya başlayınca yok oluşa mahkum etmiştik. Oysa ki onlara (da) peygamberleri hakikatin apaçık belgeleriyle gelmişlerdi; fakat onlar inanmamakta direndiler: günaha gömülüp giden toplumu işte böyle cezalandırırız."},{"n":14,"t":"Daha sonra ise, öncekilerin peşinden sizi (helak olanların yaşadığı) yerlere mirasçı kıldık ki, nasıl davranacağınızı görüp gözetleyelim."},{"n":15,"t":"Bir de ne zaman hakikatin apaçık kanıtları olan ayetlerimiz onlara okunsa, huzurumuza çıkacak yüzü olmayan o kimseler derler ki: \"Git, bize bundan başka bir hitab getir, ya da onda değişiklik yap!\" (Ey Peygamber)! De ki: \"Onu kendime göre değiştirmem olacak şey değil. Ben yalnızca bana vahyedilene uyarım: çünkü ben Rabbime karşı gelecek olursam, korkunç bir Gün`ün azabından korkarım.\""},{"n":16,"t":"De ki: \"Eğer Allah öyle dileseydi, ben onu size okumazdım; zaten O da onu size göndermezdi. Hem doğrusu şu ki; ondan önce yıllarımı sizin aranızda geçirmişim: bu kadarını olsun düşünemiyor musunuz?\""},{"n":17,"t":"Hem kendi uydurduğu yalanları Allah`a yakıştırandan, ya da O`nun mesajlarını yalanlayandan daha zalim biri olabilir mi? Gerçek şu ki; günaha gömülenler asla iflah olmaz!"},{"n":18,"t":"Bir de Allah`ın peşi sıra kendilerine yararı da zararı da dokunmayan varlıklara kulluk edip de, üstelik \"İşte şunlar Allah katında bizim kayırıcılarımızdır\" diyenler (iflah olmaz). De ki: \"Yoksa siz Allah`a, göklerde ve yerde bilmediği bir şey var da,, onu mu haber veriyorsunuz?\" O, sınırsız yüceliği ve aşkın varlığıyla, onların putlaştırdığı her şeyden beridir."},{"n":19,"t":"İnsanlık başlangıçta aynı duygu, düşünce ve ideal etrafında toplanmış bir topluluktan oluşuyordu; fakat sonradan ayrı görüşlere saptılar. Ve eğer Rabbin tarafından daha önceden bir yasaya bağlanmamış olsaydı, onların kendi aralarında tartıştıkları konularda (daha başından) hüküm verilip iş bitirilirdi."},{"n":20,"t":"Bir de diyorlar ki: \"Ona Rabbinden mucizevi bir belge gönderilmeli değil miydi?\" Buna karşılık de ki: \"Aşkın hakikatler yalnızca Allah`a ait bir alandır: şimdi artık bekleyin (akıbetinizi)! İyi bilin ki, ben de sizinle birlikte bekleyeceğim!\""},{"n":21,"t":"Ve ne zaman, kendilerine dokunan bir sıkıntının ardından bu tiplere rahmet(imizden) bir parça tattırsak, derhal ayetlerimiz hakkında tuzak tezler kurgulamaya başlarlar. De ki: \"Allah her türlü tuzağı seri bir biçimde (boşa çıkarır).\" Dikkat edin, elçilerimiz inceden inceye tasarladığınız her şeyi kayda alıyorlar."},{"n":22,"t":"Sizi karada ve denizde gezdiren O`dur. Dahası (tutun ki) sizler gemide bulunuyosunuz, tatlı bir rüzgarda onunla yol alıyorsunuz, üstelik tam da bunun sevinciyle mest olmuşsunuz; derken bir fırtına yakalıyor gemiyi ve dalgalar her yandan yolcuları kuşatıyor. Artık onlar dört bir yandan (ölümle) sarıldıklarına kanaat getirmiş vaziyetteler; tüm içtenlikle Allah`a yönelip yalnız O`nun nizamına sığınarak; \"Eğer bizi bu beladan kurtarırsan yemin olsun ki şükredenlerden olacağız!\" diye yalvarıp yakarıyorlar."},{"n":23,"t":"Sonunda (ne oluyor, biliyor musunuz): kurtarmasının hemen ardından bu kimseler, yeryüzünde hak hukuk dinlemeden azgınlık yapmaya başlıyorlar. Ey insanlık! Yaptığınız azgınlıkların neticesi gelip yine sizi bulacaktır. Dünya hayatının zevkleri gelip geçicidir. Sonunda Bize döneceksiniz ve Biz yaptıklarınızı bir bir size haber vereceğiz."},{"n":24,"t":"Bu dünyanın cezbedici hayatı, olsa olsa şu misale benzer: gökten indirdiğimiz bir su (düşünün); nihayet o insanların ve hayvanların kendisinden beslendiği bitkilerce emilir. Derken toprak (yapay) bir parlaklık ve baştan çıkarıcı bir tezyin ile arzı endam edip de sakinleri onun üzerinde tamamıyla hakim olduklarını düşünmeye başladıklarında; bir gece vakti ya da güpegündüz, (ansızın) emrimizin infaz (vakti) geliverir: Böylece onu, sanki önceden hiç safa sürmemiş gibi kökünden sökülmüşe çeviririz! İşte Biz, düşünen bir toplum için ayetlerimizi böyle açık ve anlaşılır bir biçimde dile getiriyoruz."},{"n":25,"t":"Böylelikle Allah (insanı) mutluluk ve güvenlik zeminine çağırmakta ve isteyeni dosdoğru bir yola yöneltmeyi dilemektedir."},{"n":26,"t":"İyi ve yararlı davranmakta sebat gösterenlere (karşılık olarak) ondan daha iyisi ve (kat kat) fazlası var. Dahası (o gün) onların ne yüzleri kara çıkar, ne de onursuzluktan başları eğilir: işte bunlar Cennet`in sakinleridir; orada yerleşip kalmak üzere girerler."},{"n":27,"t":"Kötülük yapmakta ısrar edenler ise, sadece yaptıkları kötülüğün misliyle cezalandırılacaklar. Ve onlar (o gün) öyle bir aşağılanmaya mahkum olurlar ki -Allah`ın gazabından kaçıp sığınacakları biri de olmadığı (için)- sanki zifiri bir gecenin karanlığı sıvanmış gibi suratları (utanç ve zilletten) kapkara kesilir: işte bunlar (da) ateşin sakinleridirler; onlar (da) orada yerleşip kalmak üzre girerler."},{"n":28,"t":"Ve bir gün onların tümünü bir araya toplayacak, ardından da (hayattayken) Allah`a has özellikleri başkalarına yakıştırmakta direnenlere diyeceğiz ki: \"Siz ve ilahlık yakıştırdıklarınız: haydi yerlerinize!\" İşte böylece onların arasını kesip ayırmış (olacağız). Ve (o zaman) onların ilahlık yakıştırdıkları, dönüp kendilerine şöyle diyecek: \"Zaten sizin tapınıp durduklarınız, (gerçekte) hiç biz olmadık ki;"},{"n":29,"t":"`Bizimle sizin aranızdaki konularda şâhit olarak Allah yeter, sizin bize taptığınızdan kesinlikle bizim haberimiz yok.`"},{"n":30,"t":"İşte o an ve orada herkes geride bıraktıklarından sınav verir, (yaptıklarının sonucunu görür); en nihayet Allah`a, o yüceler yücesi gerçek sahipleri olana döndürülürler ve (çarpık tasavvurlarının) ürettiği sahte ilahlar kendilerini yüzüstü bırakır."},{"n":31,"t":"(Ey Peygamber)! De ki: \"Göğün ve yerin ürünleriyle sizi rızıklandıran kimdir? Peki, işitme ve görme duyularınız üzerinde kim mutlak söz sahibidir? Dahası kimdir ölüden diriyi çıkaran? Ve diriden ölüyü çıkaran kim? Ya bir düzen içerisinde devinen bütün bir varlığa talimatı kim veriyor? Derhal diyecekler ki: \"(Elbette) Allah!\" O halde sen de (onlara) de ki: \"Hala sorumsuzca davranmayı sürdürecek misiniz?\""},{"n":32,"t":"Halbuki, işte bu Allah`tır sizin gerçek ve tek Rabbiniz! Şimdi söyler misiniz: hakikati çıkarırsanız, geriye sapıklıktan başka ne kalır? Buna rağmen, nasıl oluyor da (hakikate) böylesine mesafeli durabiliyorsunuz?"},{"n":33,"t":"İşte böylece, yoldan iyice sapmış olanlar için Rabbinin sözünün hakikat olduğu ortaya çıkmış oldu: \"Onlar inanmayacaklar!\""},{"n":34,"t":"Sor (onlara): \"Hayatı yoktan var edip de sonra o yaratışı sürekli yenileyen zat, ortak koştuklarınızdan biri midir? Cevap ver: \"Hayatı yoktan var edip de sonra o yaratışı sürekli yenileyen Allah`tır! Gerçek bu iken, nasıl olur da böylesine savrulursunuz?\""},{"n":35,"t":"Sor (onlara): \"Hak yola yönelten kimse ortak koştuklarınızdan biri midir?\" Cevap ver: \"Hak yola yönelten sadece Allah`tır. Peki, hak yola yönelten mi uyulmaya daha layıktır, yoksa yol gösterilmedikçe kendi başına doğru yolu bulamayacak olan mı? Şu halde ne oluyor size; nasıl böyle bir hükme varabiliyorsunuz?\""},{"n":36,"t":"Bir de, onların çoğu sadece zannın peşine takılırlar. Oysa ki hiç bir zan, insanı hakikatten hiçbir şekilde müstağni kılmaz. Elbette Allah onların yaptıklarını çok iyi bilmektedir."},{"n":37,"t":"İmdi bu hitab, Allah`tan başkası tarafından tasarlanıp ortaya konulmuş olamaz. Aksine o, kendisinden önce gelenlerden geriye kalan hakikatleri doğrular ve kendisinde kuşku bulunmayan Kitab`ı ayrıntılı olarak açıklar; Alemlerin Rabbindendir."},{"n":38,"t":"Yoksa, \"Onu o uydurdu\" mu diyorlar? De ki: \"Öyleyse haydi, Allah`tan başka yardıma çağırabileceğiniz herkesi çağırın da ondakine eşdeğer bir sure getirin; tabii ki eğer sözünüzün arkasındaysanız!\""},{"n":39,"t":"Fakat hayır, aksine onlar özünü kavramaktan aciz kaldıkları, üstelik o mesajın ayrıntılı açıklaması da (henüz) kendilerine ulaşmamışken yalanlamayı tercih ettiler. Onlardan öncekiler de işte böylesi bir yalanlamaya yeltenmişlerdi; fakat (onların akıbetini merak ediyorsan), dön de zalimlerin sonunun ne olduğuna bir bak!"},{"n":40,"t":"Onlar arasında bu mesaja inanacak olanlar olduğu gibi, hiç inanmayacak olanlar da var. Bir de, senin Rabbin bozgunculuğu iş edinenleri en iyi bilendir."},{"n":41,"t":"Şu durumda eğer seni yalanlamaya kalkarlarsa, hemen (onlara) de ki: \"Benim yaptıklarım(ın sorumluluğu) bana, sizin yaptıklarınız(ın sorumluluğu) da size aittir; siz benim yaptıklarımdan sorumlu tutulmazsınız, ben de sizin yaptıklarınızdan sorumlu tutulacak değilim.\""},{"n":42,"t":"Bir de, onlar arasında sana kulak verip işitirmiş gibi yapanlar var; iyi ama, eğer akıllarını kullanmıyorlarsa sen sağırlara duyurabilir misin?"},{"n":43,"t":"Yine onlar arasında sana (sanki görürmüş gibi) bakanlar var; iyi de, eğer basiretleri bağlı ise sen (böylesi) körlerin görmesini sağlayabilir misin?"},{"n":44,"t":"Şüphe yok ki Allah, insanlara hiç bir şekilde kötülük etmez; fakat insanlar kötülüğü kendi kendilerine ederler."},{"n":45,"t":"Ve o Gün gelip de Allah onları bir araya topladığı zaman, onlara (dünyada) sanki birbirleriyle tanışmalarına yetecek kadar, yalnızca gündüzün bir saatinde kalmışlar (gibi gelecek); doğrusu, Allah`ın huzuruna çıkarılacakları gerçeğine yalan gözüyle bakan ve doğru yola yönelmemekte ısrarcı davranan kimseler (o gün) hepten kaybetmiş olacaklar."},{"n":46,"t":"Ve sana, onlara vaad ettiklerimizden bir kısmının gerçekleştiğini ya (bu dünyada) gösteririz, ya da senin canını alır (ahirette gösteririz). Nasıl olsa en sonunda dönüşleri Bizedir; dahası, Allah onların yaptığı her şeye şahittir."},{"n":47,"t":"Her ümmet için bir elçi olagelmiştir: ve onlara elçileri geldikten (ve hakikati tebliğ ettikten) sonradır ki ancak aralarında adil yargıda bulunulabilir; onlara asla haksızlık da yapılmaz."},{"n":48,"t":"Buna rağmen bir de kalkıp \"Bu tehdit ne zaman gerçekleşecekmiş? Eğer doğru söylüyorsanız (cevap verin de görelim)!\" diyorlar."},{"n":49,"t":"De ki: \"Allah dilemedikçe, ben kendim için dahi ne yarar sağlayacak ne de zararı önleyecek bir güce sahibim. Her ümmet için belirlenmiş bir süre vardır; süreleri dolduğunda artık onu ne bir an erteleyebilirler, ne de öne alabilirler.\""},{"n":50,"t":"De ki: \"Baksanıza! Tutun ki O`nun azabı bir gece ya da bir gündüz çıkageldi; günaha batmış olanlar ne (elde edeceklerini umarak) onu çabuklaştırmak istiyorlar?\""},{"n":51,"t":"Tehdit gerçekleştikten sonra mı O`na inanacaksınız? Ne! Ancak şimdi ha? Oysa ki siz (asla gelmez diye meydan okuyor), onun çabuk gelmesinde ısrar ediyordunuz!?"},{"n":52,"t":"Sonunda, bilinci ters dönmüş kimselere denilecek ki: \"Tadın bitimsiz azabı! Kazanıp durduğunuz şeyler dışında bir karşılık mı bekliyorsunuz?\""},{"n":53,"t":"Tutup bir de seni \"Şimdi bu gerçek mi yani?\" diye sorguluyorlar. De ki: \"Kesinlikle! Rabbim hakkı için bu gerçeğin ta kendisidir; üstelik sizler (büyük sorgulamayı) asla atlatamayacaksınız!\""},{"n":54,"t":"Bilinci ters dönmüş her birey, eğer yeryüzündeki her şey kendisinin olsa onu (Hesap Günü) kurtuluş akçesi olarak vermek isterdi. Onlar asıl pişmanlığı, kendilerini bekleyen azabı görünce yüreklerinin en derinlerinde yaşayacaklar. Ne ki onların aralarında herkese layık ilahi bir hakkaniyetle hükmolunacak; ve onlara hiç haksızlık yapılmayacak."},{"n":55,"t":"Unutmayın ki, göklerde ve yerde bulunan her şey Allah`a aittir! Unutmayın ki, Allah`ın vaadi kesinlikle gerçekleşecek olan bir hakikattir: velakin onların çoğu bunun bilincinde değildir."},{"n":56,"t":"O`dur hayatı ve ölümü yaratan; nihayet sonunda dönüp dolaşıp varacağınız yer O`nun huzurudur."},{"n":57,"t":"Ey insanlık! Rabbinizden size bir öğüt ve kalplerde oluşabilecek her tür (manevi hastalık) için bir şifa; inananlar için de bir yol haritası ve bir rahmet gelmiştir."},{"n":58,"t":"Söyle (onlara): Allah`ın ihsanı ve rahmetiyle, evet işte bunlarla sevinsinler artık; (ki) bu onların tüm birikimlerinden daha hayırlıdır."},{"n":59,"t":"Sor (onlara): \"Ya Allah`ın sizin yararlanmanız için ikram ettiği, sizin de (keyfi olarak) bir kısmını haram bir kısmını helal saydığınız rızıklar hakkında ne dersiniz?\" De ki: \"Size Allah mı izin verdi, yoksa siz Allah`a iftira mı ediyorsunuz?\""},{"n":60,"t":"İmdi, uydurdukları bu yalanı Allah`a isnat edenler, acaba Kıyamet Günü ne (cevap vereceklerini) düşünüyorlar? Şu kesin ki Allah insanları sınırsız lutfuna muhatap kılmıştır; ve fakat onların çoğu şükretmezler."},{"n":61,"t":"Ve sen (ey peygamber); hangi konumda bulunursan bulun, Kur`an`dan hangi mesajı gündeme getirirsen getir; sizler de hangi işe el atarsanız atın: Ona giriştiğiniz her an (ve) mekanda Biz sizin üzerinizde tarife sığmaz bir şahidiz. Nitekim ne yerde ne de gökte zerre miktarı bir şey bile Rabbinin bilgisinden saklı kalamaz. Ne bunun daha küçüğü ne de büyüğü yoktur ki, hepsi apaçık bir fermanda kayıtlı olmasın."},{"n":62,"t":"Unutmayın ki Allah`a yakın olanlar, gelecekten dolayı kaygı geçmişten dolayı keder duymayacaklar."},{"n":63,"t":"Onlar imanda sebat gösteren ve sorumluluk bilincine sahip olan kimselerdir."},{"n":64,"t":"Onlar için hem bu dünya hayatında, hem de öteki hayatta müjdeler vardır. Allah`ın vaadlerinde bir değişiklik olmayacaktır: bu, işte budur muhteşem zafer!"},{"n":65,"t":"Şu halde onların lafları seni üzmesin, çünkü şeref ve itibarın kaynağı bütünüyle Allah`a aittir: O her şeyi işitendir, her şeyi bilendir."},{"n":66,"t":"Unutmayın ki, göklerde ve yerde kim varsa hepsi Allah`a aittir. Dahası Allah`tan başkasına ilahi nitelik yakıştırarak yalvarıp yakaran kimseler gerçekte ona uymuş olmuyorlar, sadece kendi zanlarının peşinden gidiyor ve yalnızca sürü güdüsüyle hareket ediyorlar."},{"n":67,"t":"Sizin için kollarında dinlenesiniz diye geceyi ve (işlerinizi) görüp gözetesiniz diye gündüzü takdir eden O`dur: zira bunda (hakkı) işitecek bir topluluk için ayetler vardır."},{"n":68,"t":"(Bu gerçeklere rağmen) \"Allah bir oğul edindi\" iddiasında bulundular. O aşkın bir hakikattir; O hiçbir şeye muhtaç olmayıp, mutlak anlamda kendi kendine yetendir: Göklerde ve yerde ne varsa hepsi O`na aittir. Sizin elinizdeyse bu tür bir iddiada bulunmak için hiçbir deliliniz yoktur: (buna rağmen), Allah`a bilmediğiniz bir şeyi mi isnat ediyorsunuz?"},{"n":69,"t":"De ki: \"Kesinlikle, kendi yalanlarını Allah`a isnat edenler başarıya ulaşamayacaklar."},{"n":70,"t":"Yalnızca dünya ile sınırlı geçici bir haz. Sonunda onların dönüşü Bize olacak: en nihayet ısrarlı inkarlarından dolayı onlara şiddetli azabı tattıracağız."},{"n":71,"t":"Onlara Nuh`un kıssasını aktar: Hani o bir zamanlar kavmine şöyle demişti: \"Ey kavmim! Eğer benim konumum ve Allah`ın ayetlerini size hatırlatmam zorunuza gidiyorsa, şunu iyi bilin ki ben yalnızca Allah`a güvendim. Haydi siz de yapacağınız eylemi kararlaştırmak için kendilerine ilahlık yakıştırdıklarınız da dahil, bir araya toplanın ki, kararlaştırdığınız eylem sizi riske sokmasın: en sonunda bana karşı aldığınız kararı infaz edin: hem de hiç göz açtırmaksızın!"},{"n":72,"t":"Şunu da iyi bilin ki: Eğer yüz çevirirseniz, hatırlayın ki ben zaten sizden (davetime) bir ücret talep etmemiştim; benim ücretimi takdir etmek yalnızca Allah`a düşer; zira ben Allah`a kayıtsız şartsız teslim olmakla emrolundum."},{"n":73,"t":"Derken, onu yalanladılar; bunun üzerine Biz de onu ve onunla birlikte gemide bulunanları kurtardık ve onları (yeryüzünün) varisleri kıldık. Ayetlerimizi ısrarla yalan sayan kimseleri ise boğulmaya terk ettik. Dön de bir bak: uyarılan (ama uyanmayan) kimselerin akıbeti nice olurmuş?"},{"n":74,"t":"Sonra onun izinden, her birini kendi toplumlarına olmak üzere (daha başka) elçiler de gönderdik. Ve onlar hakikatin apaçık belgeleriyle geldiler; fakat berikiler bir kez yalanlamış bulundukları hakikate inanmamakta sonuna kadar direndiler: İşte Biz, haddi aşanların kalplerini böyle mühürleriz!"},{"n":75,"t":"Sonra onların izinden Musa ve Harun`u, ayetlerimizle Firavun ve onun etrafındaki yönetici seçkinlere gönderdik. Fakat büyüklük tasladılar: Zira onlar, günaha batmış bir topluluktular."},{"n":76,"t":"Şöyle ki: Katımızdan kendilerine hakikatin ta kendisi geldiği zaman dediler ki: \"İşte bu kesinlikle ayan beyan bir sihirdir!\""},{"n":77,"t":"Musa dedi ki: \"Siz (ayağınıza) gelen hakikat hakkında (hep) bu tarz mı düşünürsünüz? Ne yani, şimdi bu da mı sihir? İyi ama, sihirbazlar (bunu) başaramaz ki!\""},{"n":78,"t":"(Yönetici seçkinler) dediler ki: \"Sen, bizi atalarımızı üzerinde bulup izlerini takip ettiğimiz yoldan çevirmeye ve bu şekilde kendinize ülkede iktidar yolunu açmaya mı geldin? Fakat biz, her ikinize de asla inanacak değiliz.\""},{"n":79,"t":"Firavun ise (şu) emri verdi: \"Tüm uzman sihirbazları bana getirin!\""},{"n":80,"t":"Sihirbazlar gelince, Musa onlara dedi ki: \"Atın atacaklarınızı!\""},{"n":81,"t":"Onlar (gözbağcılığa dayalı düzeneklerini) atınca Musa dedi ki: \"Sizin karşıma çıkardığınız sadece sihir! Elbette Allah bunu boşa çıkaracaktır: çünkü Allah fesatçıların işini amacına ulaştırmaz."},{"n":82,"t":"Evet, etkili müdahelesiyle Allah hakkın (üstünlüğünü) gerçekleştirir; isterse günaha batmış olanlar bundan hoşlanmasın."},{"n":83,"t":"Firavun ve onların önde gelenleri kendilerine işkence ederler korkusuyla, Musa`ya onun kavminden sadece bir avuç insan iman etti. Çünkü Firavun ülkede gerçekten de otorite ve baskı sahibiydi; zaten o dengesizin tekiydi."},{"n":84,"t":"Musa ise (onlara) dedi ki: \"Ey topluluk! Eğer Allah`a inanıyorsanız, o halde yalnızca O`na güvenip dayanmanız gerekir: tabi ki siz O`na tam teslim olmuşsanız!"},{"n":85,"t":"Bunun üzerine dediler ki: \"Yalnızca Allah`a güvenip dayandık: Rabbimiz! Bizi bu zalim kavmin zulmüne muhatap kılma!"},{"n":86,"t":"Ve bizi inkarda ısrar eden toplumun elinden lutfu kereminle kurtar!\""},{"n":87,"t":"Derken Musa ve kardeşine şöyle vahyettik: \"Şehirde toplumunuz için bazı evleri karargah edinin; kendi evlerinizi ise ibadethaneye dönüştürerek ibadetinizi eda edin! Ve (sen ey Musa!), mü`minleri (zaferle) müjdele!\""},{"n":88,"t":"Ve Musa \"Rabbimiz!\" dedi; \"Şu bir gerçek ki Sen, Firavun ve onun yakın çevresine bu dünya hayatında göz kamaştırıcı bir saltanat ve mal verdin! Rabbimiz (işte) bu yüzden senin yolundan insanları saptırıyorlar. Rabbimiz! Onların servetlerini kökünden kazı ve yüreklerine bunun acısını oturt; belli ki onlar, can yakıcı azabı görmedikçe iman etmeyecekler!\""},{"n":89,"t":"(Allah): \"Doğrusu, her ikinizin de dileği kabul olumuştur\" buyurdu; \"bundan böyle doğru yolda sebat gösterin, cehalete gömülmüş kimselerin yoluna uymayın!\""},{"n":90,"t":"Ve İsrailoğullarını denizden geçirdik. Hemen ardından Firavun ve ordusu kin ve nefretle onların peşini takip etti. Nihayet boğulacağını anladığında şöyle yakardı: \"Ben de, İsrailoğullarının inandığından başka ilah olmadığına inandım; artık ben de O`na kayıtsız şartsız teslim olanlardanım!\""},{"n":91,"t":"\"Ne yani, ancak şimdi mi (aklın başına geldi)? Oysa ki sen daha önce isyanda ısrarcıydın ve bozgunculuğu iş edinmiş biriydin.\""},{"n":92,"t":"Artık bugün, senden sonrakilere bir ibret vesikası olsun diye senin yalnızca bedenini kurtaracağız; zira şu bir gerçek ki, insanlardan bir çoğu ibret vesikalarımıza karşı ısrarla aldırmaz bir tavır içindedirler."},{"n":93,"t":"Sonunda, İsrailoğullarını verimli ve güvenli bir yere yerleştirmiş olduk; ve onlara temiz ve helal rızıklar ihsan ettik; durdular durdular da, kendilerine hakikatin bilgisi geldikten sonra ihtilaf ettiler: Elbette senin Rabbin, Kıyamet Günü hakkında anlaşmazlığa düştükleri konularda aralarında hüküm verecektir."},{"n":94,"t":"Bütün bunların ardından (ey bu hitabın muhatabı), sana indirdiğimiz mesajın gerçekliğini daha önce indirilen kitapları okuyanlar da biliyor; şüphen varsa sor onlara! Doğrusu, Rabbinden sana hakikatın ta kendisi gelmiştir: Artık asla kuşku duyanlardan olma!"},{"n":95,"t":"Dahası, Allah`ın ayetlerini yalanlayan kimselerden olmaktan şiddetle sakın! Sonra büsbütün kaybedenlerden olursun!\""},{"n":96,"t":"Hakikat şu ki, haklarında Rablerinin yargısı kesinleşenler asla iman etmeyecekler."},{"n":97,"t":"İsterse hakikatin her tür belgesi (ayaklarına kadar) gelmiş olsun: ta ki can yakıcı azabı görünceye kadar..."},{"n":98,"t":"Şu da var: keşke olsaydı, fakat ne yazık ki Yunus`un toplumu dışında (azabı hak ettikten sonra) iman edip de imanından istifade eden başka hiçbir ülke olmadı. Onlar iman edince, Biz de onları dünya hayatında onursuzluk cezasına çarptırmaktan vazgeçtik; ve bir süre daha onları nimetlerimizden yararlandırdık."},{"n":99,"t":"Ve eğer Rabbin dileseydi yeryüzünde bulunan herkes topyekün iman ederdi, (fakat bunu dilemedi). Şimdi kalkıp da, senmi onları iman edinceye kadar zorlayacaksın?"},{"n":100,"t":"Hem Allah`ın (akıl ve irade vermek suretiyle gerçekleşen) izni olmasaydı, hiçbir insan imana eremezdi! Ve O aklını kullanmayanları pisliğe mahkûm eder!"},{"n":101,"t":"De ki: \"Göklerde ve yerde nelerin bulunduğuna bir bakınız!\" Ne ki, iman etmemekte direnen bir topluma, ne ayetlerin ne de uyarıların hiçbir yararı olmaz."},{"n":102,"t":"Şu durumda, kendilerinden önce gelip geçmiş kimselerin yaşadığı (felaket) günlerinin benzerini mi gözlüyorlar? De ki: \"O halde gözleyin; şunu iyi bilin ki ben de sizinle birlikte gözleyenlerdenim!\""},{"n":103,"t":"Sonuçta, elçilerimizi (ötekilerin başına gelecek her beladan) kurtarırız; aynı şekilde iman eden kimseleri de (kurtarırız): İşin gerçeği, mü`minleri kurtarmak en çok Bize düşer."},{"n":104,"t":"(Ey peygamber!) De ki: \"Ey insanlar! Eğer benim dinimden kuşku duyuyorsanız; şunu iyi bilin ki, Allah dışında sizin kulluk ettiğiniz varlıklara asla kulluk etmem! Ne ki ben, yalnızca sizin canınızı alacak olan Allah`a kulluk ederim; zira ben inananlardan olmakla emrolundum\"."},{"n":105,"t":"Ve dahi sen (ey bu hitabın muhatabı), varlığını her tür sapmadan uzak tutarak tümüyle doğru dine ada; ve sakın şirk koşanlardan olayım deme!"},{"n":106,"t":"Ve Allah`ın peşi sıra, sana ne yararı dokunan ne de senden zararı gideren varlıklara yalvarıp yakarma! Zira eğer böyle yaparsan, işte o zaman sen de zalimlerden olursun!"},{"n":107,"t":"Yine (unutma ki), eğer Allah sana bir darlık musallat ederse, onu O`ndan başka kimse savuşturamaz! Fakat eğer senin için bir hayır dilerse, O`nun lütuf ve kereminin önüne gerilecek kimse yoktur. O lütuf ve keremini, kullarından dileyen/dilediği kimselere bağışlamak ister: Zira O mutlak bağış sahibidir, sonsuz rahmet kaynağıdır."},{"n":108,"t":"(Ey peygamber)! De ki: \"Ey insanlık ailesi! İşte size Rabbinizden hakikatin ta kendisi gelmiştir! Artık kim doğru yolu tercih ederse, hiç şüphesiz o bu tercihi kendisi için yapmış olacaktır; kim de (yoldan) saparsa, hiç şüphesiz onun sapma tercihi kendi aleyhine olacaktır: ama sizin tercihinizden dolayı sorumlu tutulan asla ben olmayacağım!\""},{"n":109,"t":"İmdi (ey Peygamber): Sana indirileni izle ve Allah hükmünü verinceye kadar sabret! Zira hüküm verenlerin en hayırlısı O`dur."}],[{"n":1,"t":"Elif-Lam-Ra! Öyle bir kitaptır ki (bu), her hükmünde tam isabet sahibi ve her şeyden haberdar olan (Allah) tarafından, ayetleri şüpheden arındırılmış ve hayatta karşılığı olan doğru hükümlerle sabitlenmiş, dahası çok boyutlu ve anlaşılır kılınmıştır."},{"n":2,"t":"ki, Allah`tan başkasına kulluk etmeyesiniz. (Ey Peygamber! De ki): \"Hiç şüphesiz ben de O`nun katından size gönderilmiş bir uyarıcı ve müjdeciyim!"},{"n":3,"t":"Haydi, Rabbinizden kusurlarınız için af dileyin ve bilincinizi yenileyerek O`na yönelin; O da size, sonu yasayla belirlenmiş bir süre doluncaya kadar (akıbeti) güzel bir hayat bahşetsin ve erdem sahibi herkese erdeminin karşılığını versin. Ama eğer yüz çevirecek olursanız, iyi bilin ki ben korkunç bir günün azabının üzerinize kopmasından korkuyorum!"},{"n":4,"t":"(Er veya geç) dönüşünüz Allah`adır; ve O her şeyi yapmaya kadirdir."},{"n":5,"t":"Baksanıza onlar, O`ndan saklamak için gönüllerini kat be kat örtüyorlar: Unutmayın ki, onlar (niyetlerini) kat kat örtülere sarıp sarmalasalar dahi, O onların (gerçeği) gizlediklerini de bilir, (yalanı) açığa vurduklarını da; nitekim O, gönüllerin en mahrem sırlarını bilendir."},{"n":6,"t":"Yeryüzünde hiçbir canlı yoktur ki rızık açısından Allah`a bağımlı olmasın. Zira O, her canlının konup eğleşeceği yeri de göçüp yerleşeceği yeri de iyi bilir: Bütün bunlar kesin ve net bir yazılım ve yasayla kayıt altına alınmıştır."},{"n":7,"t":"Yine O (bile) gökleri ve yeri altı aşamada yaratmıştır; ve O`nun Kudret Makamı`nın (en büyük tecellisi olan hayat) su üzerinde kaimdir. (Bütün bunları) hanginizin eylem ahlakı konusunda daha iyi olduğunu sınamak için yaptı. Şimdi sen kalkıp da, \"Muhakkak siz ölümden sonra yeniden diriltileceksiniz!\" desen, küfre saplananlar hemen \"Hah, al sana bir numara daha!\" diyecekler."},{"n":8,"t":"Ve eğer onların cezasını sayılı bir süreye ertelesek, hemen \"Onu tutan mı var?\" derler. Bakın, o gün geldiğinde, onu onlardan savuşturacak hiçbir güç olmayacak; dahası, alaya aldıkları gerçek onları çepeçevre kuşatacak."},{"n":9,"t":"Ne ki eğer insanoğluna katımızdan bir rahmet tattırır, daha sonra da o rahmeti ondan çekip alırsak; derhal o derin bir umutsuzluğa, dehşet bir nankörlüğe saplanır."},{"n":10,"t":"Yok eğer kendisine dokunan bir sıkıntı ve darlığın ardından ona esenlik ve bolluk tattırmış olsak, hemen der ki: \"kötülük(veren güç)ler benden uzaklaştı\"; (ve) bir anda küstahça bir övünce kapılır."},{"n":11,"t":"Ancak sabreden, Allah`ın rızasına uygun işler yapan kimseler (bu tavrı takınmazlar): İşte onlar için, ilahi bir bağış ve muhteşem bir karşılık vardır."},{"n":12,"t":"VE SEN (Ey Nebî!) Onlar “Onun üzerine bir hazine indirilmeli değil miydi?” ya da “Onunla birlikte bir de melek gelseydi (ya)!” diyorlar diye için daralacak, belki de bu yüzden sana indirilen kimi vahiyleri terk edeceksin! Unutmaki sen sadece, kendini uyarmaya adamış birisin! Allah ise, her şeyi en ideal mânada koruyan bir otoritedir."},{"n":13,"t":"Yoksa \"onu o uydurdu\" mu diyorlar? De ki: \"Madem öyle, eğer dürüstseniz haydi Allah dışında gücünüzün yetip elinizin erdiği herkesi yardıma çağırın; siz de onun seviyesinde `uydurulmuş` (!) on sure getirin de (görelim)!"},{"n":14,"t":"Fakat, eğer onlar sizin çağrınıza cevap veremezlerse; o zaman bilin ki (Kur`an vahyi) yalnızca Allah`ın ilmiyle indirilmiştir; yine (bilin ki) O`ndan başka ilah yoktur: Şimdi siz, artık O`na kayıtsız şartsız teslim olacak mısınız?"},{"n":15,"t":"Her kim dünya hayatını ve onun güzelliklerini isterse, orada yaptıklarının karşılığını tastamam veririz; üstelik onlar orada, (niyet ve amaçlarına bakılarak) değerlendirmeye tabi tutulmazlar."},{"n":16,"t":"(Fakat) işte bu kimselerin payına ahiretten düşen yalnızca ateştir; zira onların burada yaptıkları (yatırım, orada) işe yaramayacaktır: (ibadet adına) yapa geldikleri her şey ise zaten batıldır."},{"n":17,"t":"Şu halde, hiç (böyleleri), Rabbinden (gelen) hakikatin apaçık belgesine dayanan kimseyle bir tutulabilir mi? Şimdilerde O`nun katından bir şahidin duyurduğu o belgeyi, daha önce de bir önder ve bir rahmet olarak Musa`nın Kitabı temsil ediyordu. İşte, ancak (hakikatin birliğini fark eden) o kimseler bu vahye inanırlar. Küfür ittifakı mensuplarından her kim bu hakikati inkar ederse, iyi bilsin ki onun son durağı ateştir. Sen (ey bu vahyin muhatabı); sakın ola onun kaynağı hakkında tereddüde düşeyim deme; iyi bil ki o, Rabbin katından gelen hakikatin ta kendisidir: ve fakat insanların çoğu (henüz bu gerceğe) inanmıyorlar."},{"n":18,"t":"İmdi, kendi uydurduğu yalanı Allah`a isnat edenden daha zalim biri olabilir mi? İşte onlar, (hesap vermek üzere) Rablerinin huzuruna çıkartılacaklar. Şahitlerse \"İşte, Rablerine karşı yalan söyleyenler bunlardı!\" diyecekler. Unutmayın: Allah zalimleri rahmetinde tamamen dışlamıştır:"},{"n":19,"t":"O zalimler ki, insanları Allah`ın yolundan çevirirler; onu çapraşık ve dolambaçlı göstermeye çabalarlar: çünkü onlar ahirete inanmazlar."},{"n":20,"t":"Bu tipler yeryüzünden (cezayı atlatsalar da, ahirette) yakalarını asla sıyıramayacaklar; Allah dışında onlara yardım edecek bir evliya da olmayacak; onların azabı katlandıkça katlanacak: (değil mi ki) onlar hakikati işitmeye tahammül edemiyorlardı ve gerçeği görmemekte direniyorlardı?"},{"n":21,"t":"Bu tipler kendilerine yazık eden kimselerdir; ve uydurdukları kuruntu(ürünü aracı)lar, kendilerini yüzüstü bırakmıştır."},{"n":22,"t":"(Daha dünyada bütün bunlar olacaksa,) ahirette ondan beter ziyana uğrayacakları kesindir."},{"n":23,"t":"Ne var ki iman edenler, Allah`ı razı eden değerler üretenler ve Rablerine gönülden boyun eğenler de var: işte cennet ehli olanlar da bunlardır; bunlar orada ebedi kalacaklardır."},{"n":24,"t":"Bu iki kesin insanın örneği, kör ve sağır biriyle gören ve işiten birinin arasındaki fark gibidir: Konum olarak hiç bu ikisi aynı düzeyde olabilir mi? Hala ibret almayacak mısınız?"},{"n":25,"t":"Doğrusu, Nuh`u da mesajımızı kavmine taşımak için elçi olarak görevlendirmiştik. (Demişti ki:) \"Bakın, ben size açık ve net bir uyarıyla geldim."},{"n":26,"t":"Şöyle ki: Başkasına değil sadece Allah`a kulluk edesiniz! Çünkü ben, can yakan bir Gün`ün cezasına çarptırılmanızdan korkuyorum.\""},{"n":27,"t":"Bunun üzerine kavminin seçkinlerinden inkarda ısrar edenler şöyle dedi: \"Bakıyoruz da, sen de bizim gibi sadece ölümlü bir insansın. Yine, sana ayak takımına mensup sığ görüşlü kişilerin dışında kimsenin uymadığını görüyoruz. Sonuçta, sizin bize karşı bir üstünlüğünüzün olmadığını düşünüyoruz. Aksine, sizin yalancı olduğunuzdan eminiz!\""},{"n":28,"t":"Dedi ki: \"Ey kavmim! Düşünsenize bir: ya ben Rabbimin katından gelen açık bir delile dayanıyorsam; dahası, ya O bana katından bir rahmet bahşettiği halde siz bunu görmüyorsanız? Şimdi siz, (O`nun delil ve rahmetini) görmeye dahi tahammül edemezken biz kalkıp da ona (imana) sizi zorlayabilir miyiz?"},{"n":29,"t":"İmdi ey kavmim! (Çabama karşılık) sizden bir bedel beklentisi içerisinde değilim! Benim (çabamın) karşılığı Allah`a aittir. Dahası, (bana) güvenip inanan kimseleri de etrafımdan uzaklaştıracak değilim. Çünkü onlar Rablerine kavuşacaklar(ına inanıyorlar). Ve fakat bu arada, ben de sizin cahilce davranan bir topluluk olduğunuzu düşünüyorum."},{"n":30,"t":"Bakın ey kavmim! Eğer onları etrafımdan uzaklaştırırsam, Allah`tan gelebilecek cezaya karşı bana kim yardım eder? Bunu da mı düşünemiyorsunuz?"},{"n":31,"t":"Dahası ben size, \"Allah`ın hazineleri benim gözetimimdedir\" demiyorum; görünmezin bilgisine sahip de değilim. Üstelik asla \"Ben meleğim\" de demiyorum. Sizin küçük görüp aşağıladığınız kimseler için \"Allah onlara gelecekte bir hayır vermeyecek\" demeye ise zaten yanaşmam: Allah onların içlerindekini çok daha iyi bilir; eğer böyle davranırsam o zaman ben de kendisine zulmeden biri olup çıkarım.\""},{"n":32,"t":"Dediler ki: \"Ey Nuh! Bizimle tartıştın, üstelik aramızdaki tartışmada hayli ileri gittin. Madem öyle, eğer sözünün arkasındaysan hadi bizi tehdit ettiğin cezaya çarptır!\""},{"n":33,"t":"Dedi ki: \"Allah dilesin yeter ki! Onu sizin başınıza öyle bir sarar ki, artık bir daha asla atlatamazsınız!"},{"n":34,"t":"Hem ben size ne kadar öğüt vermeye çalışırsam çalışayım, eğer Allah sizin yoldan sapmanızı dilemiş olsaydı (-hele ki öyle değil-), benim verdiğim öğüt size hiçbir yarar sağlamazdı: O sizin Rabbinizdir, sonunda O`na döndürüleceksiniz.\""},{"n":35,"t":"Yoksa, \"Bu (kıssayı) o uydurdu\" mu diyorlar? De ki: \"Eğer onu ben uydurmuşsam, bunun sorumluluğu bana aittir: Ama benim, sizin işlediğiniz suçlara ilişkin hiçbir sorumluluğum bulunmamaktadır.\""},{"n":36,"t":"Derken Nuh`a şöyle vahyettik: \"Şu kesin ki, daha önce inanmış olanlar dışında bundan böyle toplumundan kimse bana inanmayacak: Artık, onların yapa geldikleri şeylerden dolayı sakın üzüleyim deme!"},{"n":37,"t":"Bizim rehberliğimiz altında ve bildirdiğimiz şekilde gemiyi inşa et ve (bundan böyle) sakın kendisini harcayan kimseler hakkında Bana başvurma! Şu kesin: onlar boğulacaklar."},{"n":38,"t":"Derken o, gemiyi inşa etmeye koyuldu. Şimdi, toplumunun önde gelenleri ne zaman ona rastlasalar, onunla alay ederlerdi. O derdi ki: \"Siz bizimle alay ediyorsanız, hiç kuşkunuz olmasın ki, (zaman gelecek) tıpkı sizin gibi, biz de sizinle alay edeceğiz."},{"n":39,"t":"Evet, zamanı gelince siz de öğreneceksiniz alçaltıcı bir cezaya kimin çarptırılacağını, dahası, kalıcı bir azaba kimin mahkum edileceğini."},{"n":40,"t":"En nihayet, hükmümüzün vakti gelince tandır kaynadı. (Nuh`a) \"Yanına her tür (canlıdan) birer çift al; bir de haklarında hüküm kesinleşmiş olanlar dışında aileni ve iman eden kimseleri (al)\" talimatını vermiştik. Zaten onun inancını paylaşan kimseler çok azdı."},{"n":41,"t":"Sonunda (Nuh) \"Haydi, ona binin!\" talimatını verdi; \"yol alması da, demir atması da Allah`ın adıyla olsun: gerçek şu ki, benim Rabbim elbette tarifsiz bir bağışlayıcıdır, eşsiz merhamet kaynağıdır.\""},{"n":42,"t":"Ve gemi dağlar gibi dalgaların arasında yol almaya başladı; ve Nuh oğluna -ki o kendi başına bir kenarda duruyordu- seslendi: \"Yavrucuğum! Gel, bizimle birlikte bin gemiye; inkara gömülüp gidenlerle birlikte olma!\""},{"n":43,"t":"(Oğlu,) \"Ben bir dağa kaçıp sığınacağım; o beni sulardan korur\" dedi. (Nuh) \"Bugün Allah`ın belasından, O`nun rahmet ettikleri hariç, kimse için kaçıp kurtulma ümidi yok!\" diye seslendi. Derken, aralarına dalga giriverdi... Artık o da boğulanlardan biriydi."},{"n":44,"t":"Nihayet denildi ki: \"Ey yer, suyunu yut! Ve ey gök, suyunu tut!\" Ve sular çekildi ve hüküm infaz edildi, sonunda gemi Cudi üzerine oturdu. Ve kendilerine kıyan toplum için \"Olmaz olsunlar!\" denildi."},{"n":45,"t":"Ve Nuh Rabbine yakardı ve \"Rabbim\" dedi, \"o benim oğlumdu, ailemden biriydi!... Bir kez daha anladım ki, senin sözün (herkesi kapsayan) gerçeğin ta kendisiymiş; ve en hakkaniyetli hüküm veren de Senmişsin!\""},{"n":46,"t":"(Allah) \"Ey Nuh! Kesinlikle o senin ailenden sayılamaz; dolayısıyla bu (bu tarz yaklaşım) doğru olmayan bir davranıştır; bundan böyle, iç yüzünü bilmediğin bir şeyi Benden isteme: Elbet Ben sana cahillerden olmamanı öğütlerim!\" dedi."},{"n":47,"t":"(Nuh) \"Rabbim! Hakkında bilgim olmayan bir şey istemekten sana sığınırım! Eğer beni bağışlamaz ve bana merhamet etmezsen, büsbütün kaybedenlerden olurum!\" dedi."},{"n":48,"t":"(Nuh`a) \"Ey Nuh! Senin ve seninle birlikte olanların nesillerinden (gelecek) olanlara, katımızdan bir esenlik ve mutluluk, bir bereket ve bolluk (muştusuyla) inip yerleş. Ama (gelecek) kuşaklar (arasında öyleleri) bulunacak ki; (önce) onlara geçici zevkleri tattıracağız, sonra tarafımızdan can yakıcı bir azaba çarptıracağız!\" denildi."},{"n":49,"t":"Bunlar sana bildirdiğimiz gaybi haberlerdendir; bunları ne sen ne de toplumun daha önce biliyor değildiniz. Şu halde sabret! Unutma ki mutlu son, Allah`a karşı sorumluluğunun bilincinde olanlarındır."},{"n":50,"t":"Ad (kavmine) ise, soydaşları Hud`u gönderdik. \"Ey kavmim!\" dedi, \"Yalnızca Allah`a kulluk edin! (Zira) sizin, O`ndan başka kulluk edeceğiniz bir ilah yoktur. Sizin (yaptığınız) uyduruk ilahlar icat etmekten başka bir şey değildir!"},{"n":51,"t":"Ey kavmim! Sizden bu (çabam) için maddi bir karşılık talep etmiyorum. Yaptıklarımın karşılığını takdir edecek olan yalnızca beni yoktan var edendir. Bunu olsun akledemiyor musunuz?"},{"n":52,"t":"Haydi ey kavmim! Günahlarınız için ondan af dileyin ve bilincinizi yenileyerek O`na yönelin (ki), sizin üzerinize gökten bol bol rahmet yağdırsın ve gücünüze güç katsın; ama (her şeyden önce) sizler günaha gömülerek yüz çevirmeyin!\""},{"n":53,"t":"\"Ey Hud!\" dediler, \"Sen bize bir delil ile gelmedin. Sırf senin sözlerine kanıp da ilahlarımızı terk edecek değiliz. Yani bizden sana inanmamızı asla bekleme!"},{"n":54,"t":"`Seni ilahlarımızdan kimileri fena çarpmış` demekten başka sana söyleyecek hiçbir sözümüz yok!\" (Hud) şöyle dedi: \"Bakın, Allah şahidim olsun ve siz de şahit olun ki, (Allah`a) ortak koştuğunuz ilahlarınızdan beriyim;"},{"n":55,"t":"(tabii ki) Allah dışındaki... Haydi artık topunuz bana tuzak kurun; sonra da bana soluk aldırmayın!"},{"n":56,"t":"İyi bilin ki ben, yalnızca benim de Rabbim sizin de Rabbiniz olan Allah`a güvendim. Hiç bir canlı yoktur ki, O onun denetimini elde tutmamış olsun. Kuşkusuz benim Rabbim dosdoğru bir yol üzeredir."},{"n":57,"t":"Ama eğer yüz çevirirseniz (siz bilirsiniz). Doğrusu ben, benimle size gönderilen mesajı ulaştırmış bulunuyorum. İmdi Rabbim (dilerse eğer), sizin yerinize başka bir toplum getirir ve (yokluğunuz nedeniyle) O`na hiçbir zarar veremezsiniz: çünkü benim Rabbim her şeyin denetimini elinde bulundurandır.\""},{"n":58,"t":"Ve (cezalandırma) talimatımız geldiğinde, Hud`u ve inançlarıyla onun yanında yer alanları katımızdan bir rahmetle kurtardık; dahası onların (ahiretin) ağır ve berbat azabından halas ettik."},{"n":59,"t":"İşte böyleydi Ad kavmi: Rablerinin mesajlarını reddettiler ve O`nun elçilerine karşı geldiler; üstelik her inatçı zorbanın yönetimine boyun eğdiler."},{"n":60,"t":"Sonuçta peşlerine, bu dünyada da kıyametde de bir lanet takıldı. Unutmayın ki, Rablerini ısrarla inkar eden işte bu Ad idi. Unutmayın: Hud`un kavmi Ad tarih sahnesinden işte böyle silindi."},{"n":61,"t":"Semud`a ise soydaşları Salih`i (gönderdik). \"Ey kavmim!\" dedi, \"Yalnızca Allah`a kulluk edin; (zira) sizin ondan başka kulluk edeceğiniz bir ilah yoktur. Sizi topraktan inşa eden ve size orayı imar etme yeteneği bahşeden O`dur. O halde O`ndan günahlarınız için af dileyin ve artık bilincinizi yenileyerek O`na yönelin; çünkü benim Rabbim (kendisine dönene) çok yakındır, duaları kabul eden tek mercidir."},{"n":62,"t":"Onlar şöyle dediler: \"Ey Salih! Doğrusu sen, bundan önce içimizde (hep) gelecek vaat eden biriydin. Şimdi kalkıp sen bizi atalarımızın kulluk ettiği şeylere tapmaktan mı alıkoyacaksın? Ama şunu iyi bil ki, biz senin davet ettiğin şeye dair şüphe içindeyiz\" demişlerdi; mütereddid bir halde..."},{"n":63,"t":"\"Ey kavmim!\" dedi, \"Düşünsenize bir: ya ben Rabbimin katından gelen açık bir delile dayanıyorsam ve O bana katından bir rahmet bahşetmişse? Eğer O`na isyan edersem, Allah`tan gelebilecek bir cezaya karşı bana kim yardım eder? O takdirde siz, yıkımımı arttırmaktan başka bir şey yapmamış olursunuz.\""},{"n":64,"t":"\"İmdi ey kavmim! Allah`a ait olan bu dişi deve sizin için bir sembol kılınmıştır. O halde bırakın da Allah`ın arzında otlasın! Sakın ona kötülük yapayım demeyin! Sonra ani bir azaba çarptırılırsınız.\""},{"n":65,"t":"Buna rağmen, onu vahşice katlettiler. Bunun üzerine (Salih) dedi ki: \"Konaklarınızda keyif sürme süreniz sadece üç gündür; işte bu yalanlaması imkansız bir tehdittir!\""},{"n":66,"t":"Kararlaştırdığımız vakit gelince, Salih`i ve onun inancını paylaşan kimseleri Rahmetimiz sayesinde kurtardık; dahası (onları), o bir Gün (yaşayacakları) utançtan da (kurtarmış olduk). Şüphesiz senin Rabbin var ya: işte O, eşsiz güç sahibidir, mutlak üstün ve yüce olandır."},{"n":67,"t":"Derken, zalimleri (dehşetli) sayha yakalayıverdi de, kendi yurtlarında cansız donakaldılar;"},{"n":68,"t":"sanki orada hiç yaşamamıştılar: unutmayın ki, Rablerini ısrarla inkar edenler işte bu Semud idi; unutmayın, Semud tarih sahnesinden böyle silindi."},{"n":69,"t":"Ve doğrusu elçilerimiz İbrahim`e bir muştu getirdiler ve \"Selam sana!\" dediler. O da \"Selam size!\" diye mukabele etti ve çok geçmeden önlerine kebap yapılmış bir buzağı çıkardı."},{"n":70,"t":"Fakat ellerinin ona uzanmadığını görünce onları yadırgadı ve onlardan yana içini bir korku ve endişe kapladı. Onlar dedi ki: \"Endişeye mahal yok, çünkü biz Lut kavmi için gönderildik!\""},{"n":71,"t":"Karısı ise ayakta duruyordu; derken hayız alameti hissetti. İşte bu şekilde Biz o kadına İshak`ı müjdeledik; üstelik İshak`ın ardından da (onun oğlu) Yakub`u (müjdeledik)."},{"n":72,"t":"\"Ah benim dertli başım! Ben yaşlı bir kadın şu kocam da bir piri fani olduğu halde, ben çocuk doğuracağım ha? Bu gerçekten de çok garip bir şey!\" dedi."},{"n":73,"t":"Onlar \"Sen Allah`ın emrini garip mi karşılıyorsun?\" dediler; \"Allah`ın rahmeti ve bereketi sizin üzerinize olsun ey hane halkı, kuşku yok ki O`dur hamde en layık olan, O`dur yüceler yücesi!\""},{"n":74,"t":"Sonunda İbrahim`in endişesi geçip de müjde kendisine ulaşınca, (bu kez de) Lut kavmi konusunda bize ısrarla yalvarmaya başladı;"},{"n":75,"t":"çünkü İbrahim, hep yanık bir yürekle ah edip Allah`a iltica eden biriydi."},{"n":76,"t":"(Elçilerimiz): \"Ey İbrahim, bundan vazgeç! Gerçek şu ki, Rabbinin kesin talimatı gelmiştir: artık onlar geri dönülmez bir cezaya çarptırıldılar!\" dedi."},{"n":77,"t":"Ve elçilerimiz Lut`a gelince, onları korumaya güç yetiremeyeceğini düşünerek derin bir endişeye kapıldı ve \"Bugün belalı bir gün olacak!\" dedi."},{"n":78,"t":"Nitekim kavmi ona doğru çıldırmışçasına seğirttiler; zaten daha önceden de o kötülüğü işleyip duruyorlardı. (Lut) \"Ey kavmim! İşte kızlarım, onlar sizin için daha temiz! Artık Allah`tan korkun da konuklarıma karşı beni mahcup etmeyin; aranızda hiç bir aklı başında biri yok mu?\" dedi."},{"n":79,"t":"Dediler ki: \"Sen de iyi biliyorsun ki bizim senin kızlarında gözümüz yok; aslında sen çok iyi biliyorsun bizim ne istediğimizi!\""},{"n":80,"t":"(Lut) \"Ah, keşke size karşı koyacak gücüm ya da sırtımı yaslayacağım sağlam bir dayanak olsaydı!\" dedi."},{"n":81,"t":"(Elçilerimiz): \"Ey Lut!\" dediler, \"Biz Rabbinin elçileriyiz; onlar sana asla ilişemeyecekler! Artık gecenin bir vaktinde (iman) ailenle birlikte yola koyul! Sizden hiç kimsenin gözü arkada kalmasın; tabii ki karın hariç: çünkü ötekilerin akıbeti onun da başına gelecektir. Unutma ki onların vadesi bu sabah doluyor: (zaten) sabah yakın değil mi?\""},{"n":82,"t":"Sonunda emrimizin (infaz) vakti geldi, oranın altını üstüne getirdik ve o coğrafyanın üzerine püskürtü halinde akkor balçıktan taşlar yağdırdık;"},{"n":83,"t":"Rabbin tarafından hedefi belirlenmiş (taşlar)... O taşlar ki, zalimlerin başlarından hiç de uzak değildi."},{"n":84,"t":"Medyen`e de soydaşları Şuayb`i gönderdik. \"Ey kavmim!\" dedi, \"Yalnızca Allah`a kulluk edin! (Zira) sizin, ondan başka kulluk edeceğiniz bir ilah yoktur. Bir de eksik ölçüp tartmayın! Her ne kadar sizi şimdi refah içinde görüyorsam da, yine de ben sizi çepeçevre kuşatacak bir Günün gazabından korkuyorum!"},{"n":85,"t":"Bu nedenle ey kavmim, ölçüde ve tartıda adaleti tam gözetin; ve insanları hakları olan şeyden yoksun bırakmayın; ve kötülüğü yaygınlaştırarak yeryüzünde ahlaki çürümeye meydan vermeyin!"},{"n":86,"t":"Allah`ın size bıraktığı sizin için daha hayırlıdır; tabii ki eğer O`na inanıyorsanız. Zira ben sizin korumanız değilim!\""},{"n":87,"t":"\"Ey Şuayb!\" dediler, \" Atalarımızın taptıklarını, ya da mallarımız üzerinde keyfimizce tasarrufta bulunmayı terk etmemizi, senin salat`ın mı emretmektedir? Oysa ki (bizce) sen oldukça uyumlu ve akıllı bir adamsın!\""},{"n":88,"t":"\"Ey kavmim!\" dedi, \"Düşünsenize bir: ya ben Rabbimin katından gelen açık bir delile dayanıyorsam; ve O beni kendi katından güzel bir rızıkla rızıklandırmışsa? Hem sizi sakındırdığım konulara girmem sadece size muhalefet etme arzumdan kaynaklanmıyor. Aksine tüm arzum, gücümün yettiğince düzeltmeye çalışmaktan ibarettir. Başarım ise yalnızca Allah`a bağlıdır: sadece O`na dayanıp güvendim ve yalnızca O`na yöneldim."},{"n":89,"t":"\"Dahası ey kavmim, benimle yollarınızı ayırmanız sakın sizin günahta ısrarınıza yol açmasın! Yoksa Nuh kavminin, Hud kavminin, ya da Salih kavminin başına gelenlerin benzeri sizin de başınıza gelebilir. Kaldı ki Lut kavmi sizden pek de uzakta sayılmaz."},{"n":90,"t":"Haydi, günahlarınız için Rabbinizden af dileyin ve ardından bilinçlerinizi yenileyerek O`na yönelin! Unutmayın ki benim Rabbim çok merhametli davranır: O hem sever hem de sevilmeyi ister!\""},{"n":91,"t":"\"Ey Şuayb!\" dediler, \"Senin söylediklerinden bir çoğunu anlamıyoruz; üstelik biz, aramızdaki konumunun ne kadar zayıf olduğunun da farkındayız: eğer ailen(den hatırını saydıklarımız) olmasaydı, seni mutlaka taşa tutardık; zira sen bizden hiç de güçlü ve üstün değilsin.\""},{"n":92,"t":"(Şuayb) \"Ey kavmim!\" dedi, \"Sizin nezdinizde ailemin hatırı Allah`ın hatırından daha mı üstün ki, O`nu arkaya atılacak biri gibi telakki ediyorsunuz? Elbette Rabbim sizi yapıp ettiklerinizle kuşatandır!\""},{"n":93,"t":"\"Ve ey kavmim! Siz kendinize yakışanı yapınız; şunu iyi biliniz ki ben de (kendime yakışanı) yapmaktayım. Zamanı gelince, alçaltıcı cezaya kimin çarptırılacağını ve yalancının kim olduğunu öğreneceksiniz. Siz de gözetleyin, unutmayın ki ben sizinle birlikte zaten gözetlemekteyim.\""},{"n":94,"t":"Derken emrimizin (infaz) vakti geldi: Şuayb`ı ve onunla aynı inancı paylaşan kimseleri katımızdan bir rahmet sayesinde kurtardık, zulme gömülüp gidenleri malum sayha ansızın yakalayıverdi; öz yurtlarında cansız donakaldılar:"},{"n":95,"t":"Sanki onlar hiç yaşamamıştılar. Unutmayınız ki Medyen tarih sahnesinden, tıpkı Semud`un silindiği gibi silindi."},{"n":96,"t":"Doğrusu Biz Musa`yı da, ayetlerimizle ve kesin bir yetkiyle"},{"n":97,"t":"Firavun`a ve onun yönetici seçkinlerine göndermiştik. Fakat onlar Firavun`un yönetimine boyun eğdiler. Ne ki firavun(laşmış) bir yönetimin, sağduyulu olması mümkün değildi."},{"n":98,"t":"O, Kıyamet Günü (de) kavminin önüne düşecek ve onları ateşe sürecek: sürüldükleri yer ne berbat bir yer!"},{"n":99,"t":"Sonuçta peşlerine burada da bir lanet takıldı, Kıyamet Günü`nde de... Pay da, pay verilen de ne fenadır!"},{"n":100,"t":"Bütün bu kıssasını sana anlattıklarımız, (bilinen) kentlerin (acı) hikayelerinden bir kısmıdır: onlardan (geriye) kalıntı bırakan da var, hasat edilmiş tarlalar gibi yerinde yeller esen de..."},{"n":101,"t":"Ama onlara zulmeden Biz değildik, lakin onlar kendi kendilerine zulmettiler. Dahası Rablerinin helak emri geldiğinde, Allah dışında yalvarıp yakardıkları ilahları onların başından hiçbir şeyi savamadı; üstelik bunlar, kendi çöküşlerini hızlandırmaktan başka bir işe de yaramadı."},{"n":102,"t":"Ve senin Rabbin, kentleri cezalandırmak istediği zaman işte böyle cezalandırır; ki onlar zulmetmiştiler: hiç şüphesiz O`nun cezalandırması çok can yakıcı, pek dehşet vericidir."},{"n":103,"t":"Kuşkusuz bunda, ahiret azabından korkanların alacağı derin ibretler vardır: ki o gün tüm insanlığın toplandığı bir gündür; dahası her şeyin ortaya serildiği bir gündür."},{"n":104,"t":"Ve o günü Biz, ancak sayısı (Bize malum) bir süreye kadar erteleriz."},{"n":105,"t":"O gün geldiğinde, hiçbir kimse O`nun izni olmadan savunma yapamaz: sonuçta onlardan kimileri bedbaht, kimileri de bahtiyar olur."},{"n":106,"t":"Artık bedbaht olan kimselerin mekanı ateş olacaktır: onlar orada ah-u figan edecekler."},{"n":107,"t":"Rabbin aksini dilemedikçe, gökler ve yer orada durduğu sürece onlar da orada kalmayı sürdürecekler: Unutma ki senin Rabbin dilediğini yapan (Allah)tır."},{"n":108,"t":"Ve bahtiyar olanlara gelince: işte onlar da Rabbin aksini dilemedikçe, gökler ve yer orada durduğu sürece içerisinde yerleşip kalacaklar: kesintisiz bir bağış olarak!.."},{"n":109,"t":"Artık, şu adamların (neye) taptıklarından hiçbir kuşkun olmasın: onlar, önceki atalarının kulluk ettiklerinden başkasına kulluk etmiyorlar. Şu var ki Biz, onların payına düşeni hiç eksiksiz ödeyeceğiz."},{"n":110,"t":"Doğrusu Biz Musa`ya da kitap vermiştik ve onda da ayrılığa düşmüşlerdi: Ne ki eğer Rabbin tarafından daha önceden bir yasaya bağlanmamış olsaydı, onların kendi aralarında (daha başından) hüküm verilip iş bitirilirdi. Çünkü (tıpkı Mekkeliler gibi) onlar da onun hakkında önce şüpheye düştüler, nihayet (şüphelerinden de) kuşku duydular."},{"n":111,"t":"Emin ol ki Rabbin, onların her birine yaptıklarının karşılığını tastamam ödeyecektir. Unutma ki O, yaptıkları her şeyden haberdardır."},{"n":112,"t":"Şu halde emrolunduğun gibi dosdoğru ol! Ve seninle birlikte yürümek için sana uyanlar da (aynı yolu tutsunlar)! Asla sınırı aşmayın! Unutmayın ki O yaptığınız her şeyin farkındadır!"},{"n":113,"t":"Zulmedenlere en ufak bir eğilim dahi göstermeyin! Sonra ateş size de dokunur. Sizin Allah`tan başka yardımcınız da olmadığına göre, sonra büsbütün yardımsız kalırsınız."},{"n":114,"t":"Gündüzün iki eteğinde ve gecenin gündüze yakın vakitlerinde namazı ikame et! Unutma ki iyilikler kötülükleri giderir: işte bu, öğüt alacaklara bir hatırlatmadır."},{"n":115,"t":"Ve diren: unutma ki Allah iyilerin hak ettiği karşılığı azla zayi etmez!"},{"n":116,"t":"Keşke çıksaydı, ama ne yazık ki sizden önceki nesiller arasından, kendilerini kurtardığımız bir azınlık dışında, yeryüzünde toplumsal çürümeye karşı direnen akıllı ve erdemli kimseler çıkmadı. Zulme eğilimli çoğunluksa, ayartıcı dünyevi zevklerin peşine takıldılar ve günaha gömülüp gittiler."},{"n":117,"t":"Halkı (birbirlerine) ıslah edici davrandığı sürece, senin Rabbinin haksız yere uygarlıkları helâk etmesi söz konusu değildir."},{"n":118,"t":"Hem Rabbin dileseydi, bütün insanlığı Allah`a inanan tek bir ümmet yapardı. Fakat O, doğru yolu göstererek insanları seçecekleri yollarda özgür bıraktı. Ve böylece insanlar farklı görüşlerin peşinde koşmaya devam edecekler."},{"n":119,"t":"Tabii ki Rabbinin rahmetiyle (yol gösterdiği) kimseler hariç. Oysa ki O, (tüm insanları) bu (rahmete nail olmak) için yarattı. Ne ki, (rahmete ısrarla sırt çevirenler için de) Rabbinin, \"Andolsun ki Ben Cehennemi bütünüyle görünmeyen ve görünen tüm iradeli varlıkların (kötüleriyle) tıka basa dolduracağım\" sözü, elbet gerçekleşmiş olacaktır."},{"n":120,"t":"Bak, elçilerin haberlerinden senin gönlünü takviye edecek olan kısmını sana aktarmış bulunuyoruz. Bu haberlerin içerisinde, hem sana hakikat hem de mü`minlere bir öğüt ve uyarı ulaşmış olmaktadır."},{"n":121,"t":"İnanmamakta ısrar edenlere ise de ki: \"Siz, kendinize yakışanı yapınız, unutmayın ki biz bize yakışanı yapmaktayız:"},{"n":122,"t":"ve bekleyiniz, iyi bilin ki biz zaten beklemekteyiz."},{"n":123,"t":"Göklerin ve yerin gizli gerçekleri Allah`a aittir; ve sonunda her iş döner dolaşır Allah`ın (dediğine) varır: şu halde yalnız O`na kul ol ve O`na güvenip dayan; zira senin Rabbin yaptıklarınız karşısında asla duyarsız kalmaz."}],[{"n":1,"t":"Elif-Lam-Ra! Bunlar, hakikati beyan eden kitabın (olan-biteni) açıklayan ayetleridir."},{"n":2,"t":"Biz onu Arapça bir hitab olarak indirdik: belki bu sayede, kafanızı kullanırsınız."},{"n":3,"t":"Bu Kur`an`ı sana vahyetmekle Biz, sana naklettiklerimizi en güzel, en açık seçik bir biçimde nakletmiş oluyoruz: oysa ki sen, bu hitabtan önce (vahyin ne olduğundan) habersizdin."},{"n":4,"t":"Hani bir zamanlar Yusuf babasına \"Ey babacığım!\" demişti, \"Ben rüyamda on bir gezegen, bir de Güneşi ve Ayı gördüm; hepsi de yerlere kapanarak beni saygıyla selamlıyorlardı."},{"n":5,"t":"(Yakub): \"Ey yavrucuğum!\" dedi, \"Rüyanı kardeşlerine anlatma, sonra sana karşı bir tuzak kurarlar; çünkü Şeytan insan soyu için apaçık bir düşmandır!"},{"n":6,"t":"Zira bunun anlamı, Rabbinin seni seçmesi, sana olayların altında yatan gerçeği öğretmesi ve tıpkı daha önceden ataların İbrahim ve İshak`a olan nimetini tamamladığı gibi, sana ve Yakub oğullarına da nimetini tamamlaması demektir. Gerçekten de senin Rabbin her şeyi bilir, her hükmünde tam isabet eder."},{"n":7,"t":"Doğrusu, Yusuf ve kardeşlerinin (kıssasında, öğrenmek) isteyenler için asla tüketip bitirilemeyecek kadar çok dersler vardır."},{"n":8,"t":"Hani bir zaman da (Yusuf`un kardeşleri) şöyle demişti: \"Biz kalabalık olduğumuz halde, babamız için Yusuf ve kardeşi bizden daha sevimli ve gözde; bu da gösteriyor ki babamız açık bir yanılgı içerisindedir."},{"n":9,"t":"(İçlerinden biri dedi ki): \"Yusuf`u öldürün! Ya da onu ıssız bir yere atın ki babanızın ilgisi yalnız size yönelsin; ve onun ardından, işleri tıkırında giden bir topluluk olmuş olursunuz."},{"n":10,"t":"Bir diğeri ileri atılarak \"Yusuf`u öldürmeyin!\" dedi ve ekledi: \"İlle de bir şey yapacaksanız, onu bir kuyunun derinliklerine bırakın; nasıl olsa bir kervan gelip ona el koyacaktır.\""},{"n":11,"t":"(Babalarına dönüp) \"Ey babamız!\" dediler, \"Biz ona candan yürekten davrandığımız halde, neden Yusuf hakkında bize güvenmiyorsun?"},{"n":12,"t":"Bırak onu, yarın bizimle birlikte koşup oynasın; bizim onu koruyacağımızdan en ufak kuşkun olmasın.\""},{"n":13,"t":"(Yakub) dedi ki: \"Bakın, onu götürmeniz beni endişelendiriyor: Siz dalgınlıkla onu ihmal edersiniz de, sonunda onu kurt kapar diye korkuyorum.\""},{"n":14,"t":"Onlar dediler ki: \"Biz bunca kalabalık olduğumuz halde eğer onu kurt kapacak olursa, asıl işte o zaman biz yanmışız demektir.\""},{"n":15,"t":"İşte bu minval üzere, onu kuyunun derinliklerine atmada söz birliği etmiş bir halde yanlarında götürüyorlardı ki, Biz ona \"(Bir gün gelecek) kendileri hiç farkında değilken onlara bu yaptıklarını bir bir haber vereceksin\" diye ilham ettik."},{"n":16,"t":"Derken akşam vakti babalarına ağlayarak geldiler:"},{"n":17,"t":"\"Ey babamız!\" dediler, \"Yarış yapma amacıyla uzaklaşmıştık. Yusuf`u da eşyalarımızın başında bırakmıştık. Bir de baktık ki onu kurt yemiş. Ama biz ne kadar doğruyu söylersek söyleyelim, yine de sen bize inanmayacaksın!\""},{"n":18,"t":"Üstelik, üzerinde yalandan bir kan lekesi bulunan gömleğini de getirmiştiler. (Yakub) \"Olamaz\" dedi, \"tasavvurlarınız size tumturaklı bir oyun oynayarak sizi yanıltmış olmalı! Artık (bana düşen) güzel bir sabırdır; ve anlattığınız bütün bu şeyler karşısında kendisinden yardım dilenilecek tek merci Allah`tır.\""},{"n":19,"t":"Beri yandan, bir kervan geldi ve sucularını suya gönderdi; kovasını kuyuya salmasıyla (gördüğü karşısında) bağırması bir oldu: \"A, ne kısmet! Bir oğlan çocuğu bu!\" Onu ticari bir mal olarak satmak üzere yanlarında gizlediler; oysa ki Allah ne yapacaklarını çok iyi biliyordu."},{"n":20,"t":"Sonunda onu düşük bir değere -sadece bir kaç gümüş paraya- sattılar; zaten onlar ondan kurtulmak istiyorlardı."},{"n":21,"t":"Ve onu satın alan Mısırlı adam karısına dedi ki: \"Ona iyi bak! Bakarsın bize yararı dokunur; ya da onu evlat edinebiliriz.\" İşte böylece Yusuf için o ülkede sağlam bir zemin hazırladık. Yine (bu şekilde) ona olayların doğru yorumunu öğrettik. Zira Allah murad ettiği işi başarıyla sonuçlandırandır; ve fakat insanların çoğu bunu kavrayamaz."},{"n":22,"t":"Artık olgunluk çağına erince ona bir muhakeme yeteneği ve bilgi (yöntemi) bahşettik: Zira Biz iyilik yapanları işte böyle ödüllendiririz."},{"n":23,"t":"Derken, evinde bulunduğu kadın arzusunu onunla tatmin etmek için onu baştan çıkarmak istedi. Ve (bir gün) kapıları sıkı sıkıya kapatıp dedi ki: \"Hadi, seninim!\" (Yusuf): \"Allah`a sığınırım\" dedi, \"çünkü O benim Efendim; bana güzel bir konum kazandırdı! Şu da bir gerçektir ki, zalimler asla başarıya ulaşmaz.\""},{"n":24,"t":"Doğrusu kadın onu gözüne kestirmişti; eğer Rabbinin burhanını müşahede etmemiş olsaydı, o da kadını gözüne kestirip gitmişti: işte bunun nedeni, her türlü kötülük ve tutkuya bağlı taşkınlığı ondan uzaklaştırmak istediğimiz içindi; çünkü o bizim seçkin kullarımızdan biriydi."},{"n":25,"t":"Ve kapıya koştular... Ve kadın onun gömleğini arkasından yırttı. Tam sırtına sarılacaktı ki, kadının beyiyle yüz yüze geldiler. Kadın dedi ki: \"Senin karına kötülüğe kalkışan bir kişinin cezası hapsedilmekten ya da daha acı bir cezaya çarptırılmaktan başka ne olabilir ki!\""},{"n":26,"t":"(Yusuf) söze girdi: \"Asıl arzusunu benimle tatmin için beni baştan çıkarmaya çalışan odur.\" Ve kadının yakınlarından olan bir görgü tanığı: \"Eğer onun gömleği önden yırtılmışsa bu durumda kadın doğru söylüyor; öteki de yalancının teki demektir."},{"n":27,"t":"Yok eğer onun gömleği arkadan yırtılmışsa, o zaman da kadın yalan söylüyor, beriki dürüst biri demektir.\""},{"n":28,"t":"Bunun ardından (koca) onun gömleğinin arkadan yırtılmış olduğunu görünce dedi ki: \"Öyle anlaşılıyor ki bu da sizin tuzaklarınızdan biridir ey kadınlar taifesi! Doğrusu sizin tuzağınız pek yamandır!"},{"n":29,"t":"(Ey) Yusuf, sen bu olayı yaşamadın say! Ve sen (ey) kadın, kabahatinden dolayı özür dile! Çünkü (şu hal) senin suçunun sabit olduğunu gösteriyor."},{"n":30,"t":"Ve şehirde hanımlar (birbirine şöyle) dedi: \"Malum yöneticinin karısı genç hizmetçisini baştan çıkarmaya yeltenmiş. Besbelli ki tutku kadının yüreğine işlemiş. Bakın: bizim onun hakkındaki düşüncemiz işi iyice azıttığı yönündedir.\""},{"n":31,"t":"(Kadın) onların (bu tür) dedikodularını işitince, onları davet ederek kendileri için dayalı döşeli bir ziyafet sofrası hazırladı, her birinin eline de birer bıçak tutuşturdu ve (Yusuf`a) \"Çık karşılarına!\" dedi. Hanımlar onu görünce kendilerinden geçip hayran kaldılar; dahası (bu yüzden) ellerini kestiler ve \"Olamaz!\" dediler, \"Aman Allah`ım! Bu bir insan olamaz, olsa olsa bu yüce bir melektir!\""},{"n":32,"t":"Kadın dedi ki: \"Bakın, işte beni kendisinden dolayı kınadığınız kişi bu! Doğrusu ben onu baştan çıkarmaya çalıştım, ne ki o geçit vermedi. Ve eğer (bundan böyle de) arzumu yerine getirmezse, kesinlikle hapsi boylayacak ve sürüm sürüm sürünecektir."},{"n":33,"t":"(Yusuf) \"Rabbim!\" dedi, \"Benim için hapislik, bunların beni çağırdıkları şeyden daha hayırlıdır! Bununla birlikte Sen onların tuzaklarına karşı beni korumazsan, hilelerine kapılır da kendini bilmezlerden biri olup çıkarım!\""},{"n":34,"t":"Bunun üzerine Rabbi onun duasına icabet etti ve onların tuzaklarına karşı kendisini korudu: Çünkü O her şeyi işiten ve her şeyi bilendir."},{"n":35,"t":"En sonunda yetkililer, gördükleri belge ve delillerin ardından (olayın sırrına ermelerine rağmen), belli bir süre onu hapsetmenin kesinlikle daha uygun olacağını düşündüler."},{"n":36,"t":"O arada onunla birlikte iki genç daha hapse girdi. (Bir gün) o iki gençten biri dedi ki: \"Rüyamda kendimi şaraplık üzüm sıkarken gördüm.\" Diğeri ise; \"Ben de rüyamda başımın üzerinde ekmek taşıdığımı, kuşların (da) ondan yediğini gördüm\" dedi. (Birlikte şunu talep ettiler): \"Bize bu (rüyaların) altında yatan anlamı haber ver! Çünkü biz senin (bu işi) iyi bilen biri olduğunu düşünüyoruz.\""},{"n":37,"t":"(Yusuf) dedi ki: \"Öğününüz size ulaşmadan, ben her ikinize de rüyanızın altında yatan anlamı, (onun sonucu) başınıza gelmeden haber vereceğim. Zira bunlar Rabbimin bana öğrettiklerindendir. Ama (önce) şunu bilmeniz şart: Ben, Allah`a inanmayan ve ahireti inkar eden bir toplumla yolumu ayırdım;"},{"n":38,"t":"ve atalarım İbrahim, İshak ve Yakub`un inanç sistemine uydum. Allah`a ait herhangi bir niteliği ondan başkasına yakıştırmak bize yakışmaz. İşte bu (tevhidi iman), Allah`ın bize ve tüm insanlığa olan bir lutfudur: ne var ki insanların çoğu bunu değerlendirmez."},{"n":39,"t":"Ey hapishane arkadaşlarım! Birbirinden farklı birden fazla ilaha (inanmak) mı daha makul, yoksa bütün varlıklar üzerinde otorite olan biricik Allah`a (inanmak) mı?"},{"n":40,"t":"Onu bırakıp da taptığınız şeyler, başka değil, yalnızca sizin ve atalarınızın (Allah`a ait) nitelikleri kendilerine yakıştırdığınız isimlerdir, Allah bunlar hakkında hiçbir delil indirmemiştir. (Varlıkların konumları hakkındaki) nihai yargı yalnızca ve yalnızca Allah`a aittir: O size kendisinden başkasına kulluk etmemenizi emretmiştir: İşte bu dosdoğru olan tek dindir, fakat insanların çoğu bundan habersizdir."},{"n":41,"t":"Ey hapishane arkadaşlarım! Birinizin (rüyasının anlamına) gelince: Sonunda o efendisine şarap sunma işini sürdürecek. Diğerine gelince: İşte o asılacak ve kuşlar başını didikleyecek. Akıbetini soruşturduğunuz bu iş hakkındaki ilahi karar kesinleşmiş bulunuyor.\""},{"n":42,"t":"Ve o ikisinden, kurtulacağına inandığı gence şu ricada bulundu: \"Efendinin yanında beni an!\" Şeytan, onu efendisine hatırlatmayı o (gence) unutturdu. Bunun sonucunda hapiste birkaç yıl daha kaldı."},{"n":43,"t":"Derken, kral (bir rüya gördü ve) şöyle anlattı: \"Ben rüyamda, yedi besili ineğin zayıf olan diğer yedisi tarafından yenildiğini gördüm; ayrıca yedi yeşil başak ve bir o kadar da kuru başak gördüm. Siz ey seçkin yorumcular! Eğer rüyaların doğru yorumunu biliyorsanız, benim rüyamı da yorumlayın bakalım!\""},{"n":44,"t":"\"Bir tuhaf, karma karışık düşler bunlar\" dediler, \"üstelik biz rüyaların altında yatan gerçek anlamı bilmekten de aciziz.\""},{"n":45,"t":"İşte o an, iki (zindan arkadaşından) kurtulmuş olan diğeri, aradan geçen bunca vakitten sonra geçmişi hatırlayarak söze girdi: \"Ben bunun altında yatan gerçek anlamı öğrenip size bildirebilirim, fakat önce bana izin vermeniz gerek.\""},{"n":46,"t":"(Hapishaneye gelerek): \"Yusuf, ey dürüst dost!\" dedi, \"Şu rüya hakkındaki görüşünü bana söyle: Yedi besili inek zayıf olan diğer yedisi tarafından yeniliyor; ayrıca yedi yeşil başak ve bir o kadar da kuru başak?.. Keşke insanların yanına (doğru cevapla) dönebilsem; böylece bakarsın senin (değerini) de anlamış olurlar."},{"n":47,"t":"(Yusuf) cevapladı: \"Öteden beri yapa geldiğiniz gibi yedi yıl ekip biçeceksiniz, fakat yiyeceğiniz az bir miktar dışında kalanı, daneyi başağından ayırmaksızın muhafaza edeceksiniz."},{"n":48,"t":"Ondan sonra, bunların ardından yedi yıllık bir kıtlık dönemi gelecek ve sizin zor zamanlar için ayırdığınız her şeyi, muhafaza ettiğiniz az bir miktarın dışında silip süpürecek."},{"n":49,"t":"Daha sonra, bunun da ardından insanların darlıktan kurtulup bolluğa kavuştuğu bir devir gelecek; o zaman insanlar (şıralı ve yağlı bitkileri tekrar) sıkabilecekler."},{"n":50,"t":"(Bu yorum kendilerine iletilince,) kral \"Onu bana getirin!\" emrini verdi. Görevli kendisine gelince (Yusuf) dedi ki: \"Efendine dön ve ona sor bakalım, ellerini kesen hanımların derdi neymiş? Şunu da iyi bil ki, benim Rabbim onların tuzaklarını çok iyi bilmektedir.\""},{"n":51,"t":"(Kral onları toplayıp) sordu: \"Sizler, bir zamanlar Yusuf`u baştan çıkarmaya çabalamakla ne elde etmeyi ummuştunuz? Onlar \"Haşa!\" dediler, \"Allah için biz, onun aleyhine olabilecek en küçük bir kötülüğe tanık olmadık.\" Malum yöneticinin karısı \"İşte\" diye atıldı, \"gerçek olanca çıplaklığıyla şimdi ortaya çıktı! Arzumu tatmin için onu baştan çıkarmaya çalışan bendim; ne ki o, hep (özüne ve sözüne) sadık kaldı."},{"n":52,"t":"Bütün bunları şu gerçeği kesinlikle bilsin diye (söylüyorum) ki, ben gıyabında ona ihanet etmedim, üstelik Allah da hainlerin tuzağını asla başarıya ulaştırmaz."},{"n":53,"t":"Bununla ben kendimi temize çıkarıyor da değilim; o kötülüğü işlemesini (ona) ben kendim ısrarla emrettim; ne var ki Rabbimin rahmeti bunu temizler; Şüphesiz Rabbim rahmeti sınırsız bir bağışlayıcıdır."},{"n":54,"t":"Derken kral \"Onu bana getirin!\" diye emretti, \"Onu kendime seçkin bir yardımcı olarak atayayım.\" Onunla konuşmasının ardından dedi ki: \"İyi bil ki bundan böyle sen, katımızdan saygın bir konuma sahip olup kendisine güven duyulan birisin.\""},{"n":55,"t":"(Yusuf) şu talepte bulundu: \"Beni ülkenin hazinelerine bakmakla görevlendir! Benim onu çok iyi koruyacağıma, bu konudaki bilgi ve birikimime güvenebilirsiniz.\""},{"n":56,"t":"İşte bu şekilde Biz, Yusuf`a ülkede sağlam bir iktidar zemini hazırladık (ki), o orada istediği yapıyı inşa edebilsin. Biz rahmetimizi istediğimize bahşederiz; fakat iyilik yapanların (bu dünyadaki) karşılığını da zayi etmeyiz."},{"n":57,"t":"Hele bir de öte dünyadaki karşılığı var ki, daha hayırlı olan bu karşılık iman eden ve onu korumakla titizlik gösterenler içindir."},{"n":58,"t":"Nihayet Yusuf`un kardeşleri (tahıl yardımından pay almak için Mısır`a) geldiler ve onun huzuruna çıktılar. O onları derhal tanıdı, fakat onlar onu tanıyamadılar."},{"n":59,"t":"Ve onların yükleri yükletilince; \"(Gelecek sefer) bana bir kardeşinizi de birlikte getirin!\" dedi (ve ekledi): \"Görmüyor musunuz ki ben size tam ölçek verdim; çünkü konukseverliğim dillere destandır!"},{"n":60,"t":"Fakat (gelecek sefer) onu da getirmezseniz, o takdirde benden ne bir ölçek alabilirsiniz, ne de yanıma yaklaşabilirsiniz.\""},{"n":61,"t":"\"Onu getirmek için babasından izin alma konusunda tüm çabamızı kullanacağız\" dediler, \"çünkü biz bunu yapmaya mecburuz.\""},{"n":62,"t":"Bu arada (Yusuf) hizmetçilerine \"Onların bedel olarak getirdiklerini yüklerinin içerisine koyun!\" dedi, \"Belki ailelerinin yanına döndüklerinde bunu fark ederler de, bu sayede bir kez daha gelirler.\""},{"n":63,"t":"Sonunda babalarının yanına dönerek (olan biteni haber verdiler ve) \"Ey babamız!\" dediler, \"(Bünyamin olmadan) bize bir ölçek dahi verilmeyecek. İşte bu yüzden kardeşimizi bizimle birlikte gönder de payımızı alalım. Bir de, onu koruyacağımızdan en ufak kuşkun olmasın!\""},{"n":64,"t":"(Yakub) dedi ki: \"Daha önce kardeşi hakkında size güvendiğim gibi mi size güveneceğim? Neyse ki Allah en hayırlı koruyucudur: zira O, merhametlilerin en merhametlisidir.\""},{"n":65,"t":"Ve yüklerini açtıklarında, (takas olarak) verdikleri malların kendilerine iade edilmiş olduğunu gördüler. \"Ey babamız!\" dediler, \"Başka ne isteyebiliriz ki? İşte, verdiğimiz karşılık (bile) aynen bize iade edildi. Bunlarla ailemiz için tekrar erzak alabiliriz. Üstelik hem kardeşimizi korur, hem de fazladan bir deve yükü daha alırız; (zaten) bu (getirdiğimiz) tartıca az bir miktar.\""},{"n":66,"t":"(Yakub) dedi ki: \"Her tarafınızdan kuşatılıp tüm imkanlarınız tükenmedikçe onu bana geri getireceğinize dair Allah adına sağlam bir yemin edip söz vermedikçe, onu sizinle birlikte asla yollamam!\" Onlar yemin ettiklerinde ise (Yakub), \"Allah bütün bu konuştuklarımıza müdahil olan bir şahittir!\" dedi"},{"n":67,"t":"Ve ekledi: \"Yavrularım! (Şehre) tek bir kapıdan girmeyin, farklı farklı kapılardan girin! Ben Allah`tan gelecek hiçbir şeyi sizden savamam; (zira) nihai karar yalnızca Allah`a aittir: O`na güvenim tamdır; sağlam bir dayanak arayan kimseler de O`na güvenip dayansınlar!\""},{"n":68,"t":"Ve onlar her ne kadar babalarının kendilerine emrettiği gibi (şehre) girdilerse de, bunun Allah`tan gelecek olana karşı bir yararı olmadı. Ne ki bu, Yakub`un içinden geçeni dile getirme ihtiyacını duyduğu bir temenniden başka bir şey değildi. Ve gerçekte o, kendisine öğrettiğimiz üzere (Allah`ın hayata müdahil olduğunun) tam bilincindeydi; fakat insanların çoğu (bunu dahi) farketmezler."},{"n":69,"t":"Ve Yusuf`un huzuruna girdiklerinde, o, kardeşini bağrına bastı ve (diğerlerinin duymadığı bir ortamda) \"Evet ben\" dedi, \"ben senin kardeşinim; artık geçmişte onların yaptıklarına üzülme!\""},{"n":70,"t":"En sonunda, yüklerinin yüklenme işlemi tamamlanınca, su kabını öz kardeşinin denkleri arasına koydurttu. Ardından bir görevli \"Siz ey kervancılar! Evet, kesinlikle siz yapmış olmalısınız (bu) hırsızlığı!\" diye bağırdı."},{"n":71,"t":"Onlara yönelerek şöyle seslendiler: \"Nedir kaybettiğiniz?\""},{"n":72,"t":"\"Kralın su kupasını kaybettik!\" dediler ve (eklediler): \"Onu getiren kimseye bir deve yükü (tahıl ödül) verilecektir! Ben de buna kefilim!\""},{"n":73,"t":"\"Hayret vallahi!\" dediler, \"Doğrusu, ülkede bozgunculuk çıkarmak gibi bir amaçla (buraya) gelmediğimizi ve bizim hırsızlık yapan birileri olmadığımızı siz de biliyorsunuz!\""},{"n":74,"t":"\"Evet ama, eğer yalan söylüyorsanız bunun cezası (size göre) nedir?\" dediler."},{"n":75,"t":"\"Onun cezası\" dediler, \"kimin denkleri arasında bulunursa, onun ona karşılık rehin alınmasıdır: biz bu (suçu işleyen) zalimleri işte böyle cezalandırırız!\""},{"n":76,"t":"Bunun ardından, (Yusuf`un huzuruna getirildiler). O, öz kardeşinin yükünden önce diğerlerinin yüklerini aratarak işe başladı. Sonunda onu öz kardeşinin yükünden çıkarttı. İşte Yusuf`un (arzusunu gerçekleştirmek) için böyle bir planı yürürlüğe Biz koyduk. Eğer Allah böyle dilememiş olsaydı, kralın hukuk sistemine göre kardeşini alıkoyması doğru olmazdı. Biz, dilediğimiz kimseyi (ilmen) kat kat yüceltiriz; fakat her bilenin üstünde her şeyi bilen bir (Allah) vardır."},{"n":77,"t":"(Anne ayrı kardeşler) dediler ki: \"O çalmışsa, olabilir! Doğrusu, bir zamanlar onun kardeşi de çalmıştı.\" Bunun üzerine Yusuf onlara belli etmeksizin kendi kendine dedi ki: \"Asıl siz berbat bir konumdasınız; zira Allah söylediğiniz şeyin (gerçeğini) çok iyi biliyor.\""},{"n":78,"t":"\"Ey saygın yönetici!\" dediler, \"Onun yaşını başını almış bir babası var; bu nedenle onun yerine içimizden birini alıkoy: Kesinlikle biz senin iyiliksever biri olduğunu düşünüyoruz.\""},{"n":79,"t":"\"Malımızı kendi yanında bulduğumuz kimse dururken, bir başkasını alıkoymaktan Allah`a sığınırız!\" dedi, \"Çünkü o zaman biz de zalimlerden oluruz.\""},{"n":80,"t":"Bu şekilde ondan umutlarını kesince, baş başa verip durumu gizlice görüşmek için bir kenara çekildiler. Büyükleri dedi ki: \"Bilmiyor musunuz ki, babanız sizden Allah adına söz alıp yemin ettirmişti? Zaten daha önce Yusuf konusunda da güven zedelemiştiniz. Şu durumda babam bana izin verinceye ya da Allah lehimde hüküm verinceye kadar ben bu ülkeden asla ayrılmayacağım: Zira Allah en iyi hükmü verendir."},{"n":81,"t":"Babanıza dönünüz ve \"Ey babamız!\" deyiniz, \"Oğlun hırsızlık yaptı; ne ki biz sadece bilip gördüğümüzün şahidiyiz: Üstelik biz, bilip gördüğümüz dışında olup bitenlerin sorumlusu da değiliz!"},{"n":82,"t":"İstersen, (olay günü) bulunduğumuz şehrin sakinlerine ve birlikte döndüğümüz kervancılara sor: zira biz gerçekten doğru söylüyoruz.\""},{"n":83,"t":"(Olan biteni haber verdikleri babaları) \"Hayır!\" dedi, \"tasavvurlarınız size tumturaklı bir oyun oynamış. Bundan böyle bana düşen güzel bir sabırdır; kim bilir belki de Allah hepsini birden bana kavuşturur: çünkü O, evet O`dur her şeyi bilen, her hükmünde tam isabet kaydeden.\""},{"n":84,"t":"Ve içine kapandı, ve \"Ey gam, ey Yusuf`a dair tasam!\" diye inledi, ve kederden gözlerine ak indi; ve o tüm derdini içine gömdü."},{"n":85,"t":"\"Hayret vallahi!\" dediler, \"Hala Yusuf`tan söz etmeyi sürdürüyorsun; sonunda (bu hasret) seni yiyip bitirecek; ya da kendini telef edip gideceksin.\""},{"n":86,"t":"Ya`kub: “Ben tasamı ve üzüntümü ancak Allah`a havale ederim. Çünkü ben sizin bilemeyeceğiniz şeyleri, Allah tarafından vahiy ile biliyorum” dedi."},{"n":87,"t":"Ey yavrularım! Haydi gidin, Yusuf ile kardeşi hakkında haber elde etmeye çalışın! Allah`ın rahmetinden de umut kesmeyin! Şu bir gerçek ki, Allah`ın kuşatıcı ve kurtarıcı rahmetinden yalnızca kafirler güruhu umut keser."},{"n":88,"t":"Derken onlar (tekrar Mısır`a gelip Yusuf`un) huzuruna çıktılar: \"Ey saygın yönetici!\" dediler, \"Biz ve ailemiz kıtlıktan dolayı perişan olduk; üstelik bedel (olarak) getirdiğimiz şeyler de pek yetersiz. Buna rağmen sen (yine de) bize tam ölçek ver! İstersen üzerine ikramını (da ilave) et! Unutma ki Allah ikram edenlerin karşılığını verir."},{"n":89,"t":"(Yusuf) dedi ki: \"Siz henüz cahilken, Yusuf`a ve kardeşine yaptıklarınızı hatırlıyor musunuz?\""},{"n":90,"t":"Onlar atılıverdiler: \"Ne? Yoksa sen... Sen Yusuf musun?\" (Yusuf): \"Ben Yusuf`um, işte bu da kardeşimdir!\" diyerek ekledi: \"Allah bize lütfetti; çünkü her kim Allah`a karşı gelmekten sakınır ve (musibete) sabrederse, iyi bilsin ki Allah iyilerin yaptığını karşılıksız bırakmaz.\""},{"n":91,"t":"\"Aşkolsun vallahi!\" dediler, \"Doğruya doğru: Allah seni bize üstün kılmıştır; biz de hataya gömülüp gitmişiz işte!..\""},{"n":92,"t":"\"Bugün sizi kınayıp ayıplama yok!\" dedi (Yusuf); \"Allah sizi affeder, zira O merhametlilerin en merhametlisidir."},{"n":93,"t":"Şu gömleğimi götürün! Babamın yüzüne sürün onu; gözleri ışığa kavuşacaktır. Sonunda tüm ailelerinizle birlikte bana gelin!\""},{"n":94,"t":"Derken, kervan yola koyulduğunda babaları dedi ki: \"İnanın ki ben Yusuf`un kokusunu alıyorum; umarım beni bunak yerine koymazsınız.\""},{"n":95,"t":"\"Hayret vallahi!\" dediler (ve eklediler): \"Anlaşılan o ki sen, kadim yanılgında ısrarcısın.\""},{"n":96,"t":"Nihayet müjdeci ulaşıp da o (gömleği) yüzüne sürünce, derhal gözleri ışığa yeniden kavuştu; \"Ben size dememiş miydim` dedi, `herhalde ben Allah sayesinde sizin bilmediklerinizi biliyorum` diye?\""},{"n":97,"t":"\"Ey babamız!\" dediler; \"Günahlarımız bağışlansın diye bizim için Allah`tan af dile! Kusurlu olan elbette bizlerdik.\""},{"n":98,"t":"\"Sizin için Rabbimden af dileneceğim\" dedi, \"çünkü O, evet O`dur mutlak bağış sahibi, sonsuz merhamet kaynağı.\""},{"n":99,"t":"Derken, Yusuf`un huzuruna girdiklerinde o, \"Allah`ın izniyle kendinizi güvende hissedeceğiniz Mısır`a buyurun!\" diyerek, ebeveynine kucak açtı."},{"n":100,"t":"Ebeveynini makamına çıkarttı ve onu yerlere kapanarak saygıyla selamladılar. Ardından \"Ey babacığım!\" dedi, \"Bir zamanlar gördüğüm rüyanın altında yatan anlam buymuş meğer. İşte, Rabbim onu gerçeğe dönüştürmüştür. Yine O, beni hapisten çıkararak, dahası Şeytan benimle kardeşlerimin arasını açtıktan sonra bile sizin çölü aşıp gelmenizi sağlayarak bana lütufta bulunmuştur. Çünkü benim Rabbim, dilediği şeyi cömertçe lutfedendir: zira O her şeyi bilen, her hükmünde tam isabet kaydedendir."},{"n":101,"t":"\"Rabbim! Doğrusu, bana iktidarı sen bahşettin! Yine Sen öğrettin bana olayların doğru yorumunu! (Ey) gökleri ve yeri yoktan var eden: Hem bu dünyada hem öte dünyada yarim, yardımcım Sensin! Canımı, varlığını Sana adamış biri olarak al ve beni iyiler arasına kat!\""},{"n":102,"t":"Bu olay, Bizim sana vahyettiğimiz gaybi haberlerden biridir; üstelik sen, onlar tuzak kurmak amacıyla plan yapmak için bir araya geldiklerinde onların yanında da değildin."},{"n":103,"t":"Hem -sen gönülden arzuluyor olsan dahi- insanların çoğu yine de inanmayacak."},{"n":104,"t":"Oysa ki sen onlardan (davetine) bir karşılık da beklemiyorsun; elbet bu (vahiy) tüm insanlığı muhatap alan bir uyarıdır."},{"n":105,"t":"Göklerde ve yerde ne mucizeler var ki, (insanoğlu) yanından geçip gider de onlara dönüp bakmaz bile."},{"n":106,"t":"Nitekim onların çoğu, Allah`a, O`na ait nitelikleri başkalarına yakıştırmaksızın iman etmezler."},{"n":107,"t":"Yani şimdi onlar, Allah`ın cezasının kendilerini bularak çepeçevre kuşatmasından, ya da kendileri farkında dahi değilken son saatin ansızın gelip çatıvermesinden yana güvencede olduklarını mı düşünüyorlar?"},{"n":108,"t":"De ki: \"Benim yolum budur: Ben yalnızca Allah`a çağırıyorum. Ben de, bana uyan kimseler de (ne yaptığımızın) çok iyi farkındayız; ki Allah`ın şanı pek yücedir ve ben O`na ait vasıfları başkasına yakıştıranlardan değilim."},{"n":109,"t":"Senden önce gönderdiğimiz peygamberler, kentlerin ahalisinden (seçip) kendilerine vahyettiğimiz adamlardan başkası değildi. Hem onlar yeryüzünde gezip dolaşmazlar mı? Öyle yapsalardı, kendilerinden öncekilerin başına gelen feci akıbeti görmüş olurlardı! Ve Allah bilincine ulaşanlar için ahiret yurdu elbette daha hayırlıdır: Bunu dahi düşünemiyor musunuz?"},{"n":110,"t":"(Önceki) peygamberler (öylesine zorlandılar ki), en sonunda neredeyse (toplumlarına ilişkin) tüm umutlarını yitirdiler; artık iyiden iyiye yalanla(n)dıklarını düşünmeye başlayınca, yardımımız kendilerine ulaştı; sonuçta dilediğimizi kurtuluşa ulaştırmışızdır; fakat azabımız günaha gömülüp gitmiş bir toplumdan asla geri çevrilmez."},{"n":111,"t":"Doğrusu onların kıssalarında, derin kavrayış sahiplerinin alacağı bir hayli ibret vardır. (Vahye gelince:) o asla uydurulmuş bir söz değildir. Aksine önceki (vahiylerden) kendisine ulaşan hakikatleri doğrulayan ve her şeyi(n dayanacağı temelleri) açık seçik ortaya koyan ve yürekten inanan bir toplum için bir kılavuz ve bir rahmet olan (hitaptır)."}],[{"n":1,"t":"Elif-Lâm-Mîm-Râ! Bunlar Kitab`ın ayetleridir; ve Rabbin katından sana indirilenler hakikatin ta kendisidir, fakat insanların çoğu buna iman etmezler."},{"n":2,"t":"Allah ise, gökleri, gördüğünüz bir destek olmaksızın inşa edip sonra da mutlak hükümranlık makamına kurulan tek güçtür. O, her biri belirli bir süreye kadar (görevlerini) icra edecek olan güneş ve ayı belli bir yasaya bağlamış, varlığı çekip çevirmektedir. İlahi mesajları size ayrıntılı olarak açıklıyor; belki bu sayede Rabbinize (hesap vermek üzere) kavuşacağınıza gönülden inanırsınız."},{"n":3,"t":"Dahası O`dur yeryüzünü uzatıp genişleten; yani (bir yanda) kalkmaz kımıldamaz dağlar dikip (öte yandan) nehirler akıtan; ve orada her üründen erkekli-dişili çiftler var eden, gündüzü geceyle örten… Elbet bütün bunlarda, düşünen bir topluluk için derin mesajlar vardır."},{"n":4,"t":"Ve (aynı) dünyada birbirine komşu (fakat bitki örtüsü ve doğal zenginlik açısından birbirinden farklı) kara parçaları, asma bahçeleri, ekinler, aynı kökten (çıktığı halde) çatal çatal ya da çatal kökten (çıktığı halde) tek gövde üzerinde yükselen hurma ağaçları... (Hepsi de) aynı suyla sulanırlar; fakat biz onların her birine farklı bir lezzet vermişizdir. Elbet bütün bunlarda, (olaylar ve eşya arasında) bağ kuracak akla sahip bir topluluk için bitmez tükenmez mesajlar vardır."},{"n":5,"t":"İlle de (hala nasıl inkar edebildiklerine) şaşacaksan, asıl onların şu sözüne şaş: \"Ne yani, şimdi biz toprak olup gittikten sonra yeni bir yaratılışın muhattabı mı olacağız?!\" Onların inkar ettikleri aslında Rableridir. İşte (hesap verme sorumluluğunu reddeden) bu tipler, boyunlarında tutsaklık tasması taşıyanlardır: İşte onlardır ateş yaranı; onlar orada yerleşip kalacak olanlardır."},{"n":6,"t":"Ve iyiliği bırakmışlar, (tehdit edildikleri) kötü akıbetin bir an evvel gelip çatması için seni zorluyorlar. Oysa ki, kendilerinden önce bir dolu ibretlik hadise yaşanmıştı. Neyse ki senin Rabbin kendilerine kötülük eden insanlar için dahi bağışlayıcıdır; ama unutma ki cezanın en şiddetlisi de yine Rabbine aittir!"},{"n":7,"t":"Bir de inkarda ısrar edenler, \"Ona Rabbinden bir mucize indirilmesi gerekmez miydi?\" diyorlar. Unutma ki sen sadece bir uyarıcısın: ve her topluluğun bir hidayetçisi zaten bulunmaktadır."},{"n":8,"t":"Allah her dişinin karnında ne taşıdığını, rahimlerin neyi ne kadar eksiltip neyi ne kadar artıracağını da bilir: Zira her şey, O`nun katında bir ölçü ve gayeye bağlanmıştır."},{"n":9,"t":"O, bilinmeyen ve bilinebilen her şeyi, mutlak büyük ve mutlak aşkın olarak bilendir."},{"n":10,"t":"İçinizden birinin düşüncesini gizlemesi ya da açıklaması hiçbir şeyi değiştirmez. Yine, geceleyin köşe bucak gizlenip de gündüzün ortaya çıkan bir kimse,"},{"n":11,"t":"önünden ve ardından takip eden koruma korteji var da, kendisini Allah`ın gazabından korur (diye düşünüyorsa), Allah onu da bilir. Hiç kuşkusuz bir toplumun bireyleri kendi iç dünyalarını değiştirmedikçe Allah da o toplumun gidişatını değiştirmez. Ve Allah (hak eden) bir toplumu cezalandırmayı murad ettiği zaman, onu engellemek mümkün olmaz; O`ndan başka sığınacak bir merci de bulamazlar."},{"n":12,"t":"Size korku ve ümidi (birlikte) yaşatmak için şimşeği gösterip yağmur yüklü bulutları sevk eden O`dur."},{"n":13,"t":"Gök gürültüsü sınırsız bir övgüyle O`nun yüce kudretini dillendirmekte, melekler ise bunu derin bir tazim ve saygıdan dolayı yapmaktadır; dahası O, yıldırımları gönderip dilediğini ona hedef kılmaktadır; onlar ise, dilediğini ustalık ve ince bir planla gerçekleştirmekte mahir olduğunu bildikleri halde, hala Allah hakkında tartışmaktadırlar."},{"n":14,"t":"Mutlak hakikati gözeten gerçek bir dua, yalnızca O`na yönelik olmalıdır. O`ndan başka yalvarıp yakardıkları varlıklar, hiçbir şekilde taleplerine karşılık veremezler. (Onların durumu), tıpkı ellerini suya doğru açıp da ağzına (suyun) ulaşmasını bekleyen kimse (gibidir); bu durumda o asla suya kavuşamayacaktır. Küfre sapanların duası, sapmalarını (artırmaktan) başka hiçbir şeye yaramaz."},{"n":15,"t":"Göklerde ve yerde olan her varlık, onların sabahtan akşama (ilahi yasaya bağlı olarak değişip duran) gölgeleri de dahil, isteyerek ya da istemeyerek Allah`a secde ederler."},{"n":16,"t":"Onlara: \"Göklerin ve yerin Rabbi kimdir?\" diye sor ve \"Allah`tır\" cevabını ver! (Şimdi de) de ki: \"Ne yani, şimdi siz Allah`ı bırakıp da kendilerine bile bir yarar sağlayamayan ve muhtemel bir zararı önleyemeyen varlıkları yar ve yardımcı mı atadınız?\" İlave et: \"Hiç görenle görmeyen bir olur mu? Ya da, karanlıklarla (bir ışık kaynağına sahip olan) aydınlık nasıl bir tutulabilir? Yoksa onlar Allah`a O`nun yarattığı gibi yaratan ortaklar tesbit ettiler de, bu yaratış kendilerine (Allah`ın yaratışından) ayırt edilemeyecek kadar benzer mi göründü?\" De ki: \"Her şeyin yaratıcısı yalnızca Allah`tır: zira tüm varlıklara boyun eğdirecek mutlak otorite sahibi biricik güç sadece O`dur."},{"n":17,"t":"O, gökten su indirdi. Bu sayede vadiler hacimleri kadar suyla dolup taştı. Derken akıntı, (yüzeyde biriken ne kadar) köpüklü tortu ve atık varsa alıp götürdü. Bir tür takı ya da alet yapmak amacıyla potada eritilen (metalin hasını, yüzeyine çıkan) köpüklü posadan arındırma işlemi gibi... İşte Allah hak ile batılı bu misalle açıklar. Artık bakılır: eğer köpüklü tortuysa sonuçta atılıp gider, fakat eğer insanlığın yararına bir şeyse yerli yerinde durur. İşte verdiği bu misallerle Allah`ın ortaya koyduğu gerçek,"},{"n":18,"t":"Rablerinin çağrısına güzel bir biçimde karşılık verenlere daha güzeli var. O’nu karşılıksız bırakan kimselere gelince: eğer ki yeryüzündeki her şey onların olsaydı ve bir o kadarına daha sahip olsalardı, (O gün düştükleri durumdan) kurtulmak için, hiç tereddütsüz hepsini verirlerdi. İşte, hesapların en kötüsü onları beklemektedir ve onların meskeni cehennemdir: o ne kötü bir son duraktır."},{"n":19,"t":"Hiç Rabbinin katından sana indirilenin hakikat olduğunu bilen kimse ile, (hakka karşı) kör davranan kimse bir olabilir mi? Elbet, ancak aktif akıl sahipleri öğüt alırlar;"},{"n":20,"t":"onlar ki, Allah`a verdikleri söze sadakat gösterirler ve fıtrat sözleşmesini ihlal etmezler."},{"n":21,"t":"Yine onlar Allah`ın kurulmasını emrettiği bağları kurarlar. Zira onlar Rablerinin (sevgisini yitirme) kaygısıyla titrerler ve hesabı kötü vermekten korkarlar."},{"n":22,"t":"İşte onlar Rablerinin rızasını elde etme yolunda sebat gösterirler; hem salatı ikame ederler hem de kendilerine verdiğimiz nimetlerden gizlice ve açıktan sarf ederler; dahası, kötülüğü iyilikle ortadan kaldırırlar. İşte onlar, (bu) diyarın mutlu sona ulaşacak sakinleridirler."},{"n":23,"t":"Kalıcı mutluluğun üretildiği merkez olan cennetler… Onlar ve onların atalarından, eşlerinden ve nesillerinden erdemli kimseler oraya girecekler. Melekler de bütün kapılardan onların huzuruna girecekler (ve şöyle seslenecekler):"},{"n":24,"t":"\"Selam sizlere! (Bu Rabbinizin rızasını elde etme yolundaki) direncinizin bir sonucudur. Bakın işte: dâr(-ı dünyanın) ardından gelen mutlu son, ne muhteşemdir!\""},{"n":25,"t":"Ama fıtrat sözleşmesinin ardından Allah`a verdikleri sözü ihlal edenler, dahası Allah`ın kurulmasını emrettiği bağları kesip kopararak yeryüzünde sosyal çürümeye neden olanlar var ya: işte onlar Allah`ın rahmetinden kesinlikle dışlanmışlardır ve dâr(-ı dünyanın) ardından gelen kötü akıbet onları beklemektedir."},{"n":26,"t":"Allah, rızkı dileyene / dilediğine genişletir ve daraltır. Ve (rızkı genişletilenler) dünya hayatında sevinirler; ne var ki dünya hayatı ahirete nazaran kısa vadeli bir hazdan ibarettir."},{"n":27,"t":"Yine inkarda direnenler, \"Ona Rabbinden bir mucize indirilmesi gerekmez miydi?\" derler. De ki: \"Allah dileyen / dilediği kimsenin saptırır, kendisine yönelen kimseyi ise doğru yola yönlendirir\";"},{"n":28,"t":"işte onlar, iman eden ve kalpleri Allah`ın vahyi ile tatmin olan kimselerdir. Bakınız: (akleden) kalpler yalnızca Allah`ın vahyi ile tatmin olur!"},{"n":29,"t":"İman eden ve Allah`ın razı olduğu eylem ortaya koyan bu kimseler var ya: göz aydınlığı onlarındır, güzel yurt da onların…"},{"n":30,"t":"Böylece (ey Nebi), kendisinden önce nice (inkarcı) toplumların gelip geçtiği bir toplumun arasından elçi olarak seni seçtik ki, sana vahyettiklerimizi kendilerine ulaştırasın: zira onlar Rahman`ı inkar ediyorlar. De ki: \"O benim Rabbimdir, kendisinden başka ilah olmayandır: yalnızca O`na güvendim, yüzümü O`na çevirdim.\""},{"n":31,"t":"Eğer bu kendisi sebebiyle dağların yürütüldüğü, yerlerin paramparça edildiği, ölülerin konuşturulduğu bir hitab olsaydı, (yine de inanmazlardı). Bilakis, iş ve oluş tümüyle Allah`ın yasasına bağlıdır: Peki mü`minler, `Allah isteseydi bütün insanları hidayete erdirirdi` gerçeğini anlayıp da (herkesi mü`min yapma) sevdasından vazgeçmediler mi? Ama inkarda ısrar edenlere gelince: Yapıp ettikleri onların başından felaketi eksik etmeyecektir; ya da yurtlarının yanı başına ansızın konuverecektir, ta ki Allah`ın verdiği söz yerini bulsun: Çünkü Allah sözünden asla caymaz."},{"n":32,"t":"Doğrusu, senden önceki elçiler de alaya alınmışlardı. Bu yüzden, inkarda ısrar eden o kimselere (önce) süre tanıdım, sonunda onları yakaladım. Cezalandırma nasıl olurmuş, (görsünler bakayım)!"},{"n":33,"t":"O değilse kimmiş bakayım kazandıkları nedeniyle her canlı varlığın tepesine dikilip duran! Buna rağmen, hala Allah`a ortak koşuyorlar! De ki: \"Onları (keyfinize göre) isimlendirin; yani siz, yeryüzünde bilmediği bir şeyi O`na haber veriyorsunuz, öyle mi? Belki de sözü (hakiki anlamda değil), sırf zahir anlamda kullanıyorsunuzdur? Hayır, inkarda ısrar edenlere hileli mantıkları cazip gösterildi ve doğru yoldan saptırıldılar. Zira Allah kimi saptırırsa, ona doğru yolu gösterecek kimse bulunmaz!"},{"n":34,"t":"Dünya hayatında onlar için bir ceza vardır, fakat ahiretin cezası çok daha elem verici olacaktır: Allah`a karşı onları savunacak birileri de olmayacaktır."},{"n":35,"t":"Allah`a karşı sorumluluk bilinci taşıyanlara söz verilen cennet, zemininden ırmaklar çağlayan (has bahçelere) benzer. (Fazladan olarak) oranın ürünleri daimidir, gölgeleri de öyle… İşte bu, Allah`a karşı sorumluluk bilinci taşıyanları bekleyen akıbettir; inkarcıların akıbeti ise ateştir."},{"n":36,"t":"Yine, kendilerine (bu) Kitab`ı emanet ettiğimiz (mü`min) kimseler, sana indirilenlerden dolayı seviniyorlar. Fakat muhalif müttefikler arasında onun bir kısmını inkar edenler de bulunmakta. (Onlara) de ki: \"Ben, sadece Allah`a kul olmakla ve O`na ortak koşmamakla emrolundum: Yalnız O`na davet ediyorum, zira dönüş yalnızca O`nadır.\""},{"n":37,"t":"Ve işte böylece Biz, onu Arapça bir hüküm kaynağı olarak indirdik. Artık sana ilimden bir pay verildikten sonra eğer onların keyfi arzularının peşine düşersen, senin için Allah`tan başka ne bir yar, ne de bir sığınak var!"},{"n":38,"t":"Doğrusu, senden önce de elçiler göndermiş, onlara da eşler ve çocuklar vermiştik. Allah’ın izni olmaksızın bir elçinin ilâhi kudret delîli getirmesi mümkün değildir; (kaldı ki) her devrin, (kendine has) bir kudret delîli vardır."},{"n":39,"t":"Allah dilediğini yok eder, dilediğini bırakıp sağlamlaştırır: zaten mesajın kaynağı (da) O`nun katındadır."},{"n":40,"t":"İmdi, onları tehdit ettiğimiz (cezanın) bir kısmını ister sana (daha hayatında) gösterelim, isterse (ondan önce) senin ölümünü takdir edelim: unutma ki sana düşen yalnızca tebliğ etmektir; (onların) hesabını görmekse sadece bize düşer."},{"n":41,"t":"Peki onlar görmediler mi ki, Biz yeryüzüne müdahil olup, ona (ait değerleri) her bir tarafından eksiltiyoruz? (Şu kesin) ki; Allah yasa koyar, O`nun yasasını kimse bozamaz. Üstelik o hesabını pek çabuk görür."},{"n":42,"t":"Doğrusu onlardan öncekiler de zaafı ustaca gizlenmiş düzenler kurmuşlardı; fakat bütünüyle kusursuz düzen kurarak (diğer düzenleri boşa çıkarmak) sadece Allah`a has idi; (zira) O her bir canın ne kazandığını bilir. Ama istikbalin kime ait olduğunu, (bir gün) gelecek kafirler de bilecekler."},{"n":43,"t":"İnkarda ısrar edenler, (yine) \"Sen Allah tarafından gönderilmiş değilsin\" diyecekler. Sen (de) de ki: \"Benimle sizin aranızda şahit olarak Allah yeter; bir de ilahi mesajın bilgisini iyice sindirmiş kimseler.\""}],[{"n":1,"t":"Elif-Lam-Ra! Bu, insanlığı, Rablerinin arzusuyla karanlıklardan aydınlığa; tüm övgülerin muhatabı olan, O her işinde mükemmel olanın yoluna çıkarman için sana indirdiğimiz bir vahiydir."},{"n":2,"t":"O Allah ki, göklerde ve yerde olan her şey kendisine aittir. (Kendilerini bekleyen) şiddetli cezadan dolayı vay o kafirlerin haline!"},{"n":3,"t":"Onlar ki, sevgilerini dünya hayatına hasrederek onu ahirete tercih ederler; başkalarını da Allah yolundan çevirirler; dahası o (yolu) çapraşık ve dolambaçlı göstermeye çabalarlar. İşte onlar derin bir sapıklığa gömülmüşlerdir."},{"n":4,"t":"Biz her peygamberi yalnızca kendi kavminin diliyle gönderdik ki, mesajı onlara açık ve net olarak iletsin. Bundan sonradır ki Allah isteyenin sapmasını dileyecek, isteyeni ise doğru yola yöneltecektir: Zira her işinde mükemmel olan, hükmünde tam isabet kaydeden O`dur."},{"n":5,"t":"Nitekim, Musa`yı da ayetlerimizle \"Kavmini karanlıklardan aydınlığa çıkar ve onlara Allah`ın (imtihan ve yardım) günlerini hatırlat\" diye göndermiştik. Çünkü bunda sonuna kadar sabreden ve şükrünü eda etmek için var gücünü harcayan herkes için dersler vardır."},{"n":6,"t":"İşte o zamanlar Musa kavmine demişti ki: \"Allah`ın üzerinizdeki nimetini hatırlayın; hani O sizi Firavun yönetiminin elinden kurtarmıştı? Onlar size işkencenin en bayağısını reva görüyorlar, oğullarınızı öldürüp kadınlarınızı sağ bırakıyorlardı. Bu yaşananlar, içerisinde Rabbinizden size gelen ağır bır sınavı barındırıyordu."},{"n":7,"t":"Hani Rabbiniz size şunu duyurmuştu: \"Eğer şükrederseniz size (olan nimetimi) artırırım, yok eğer nankörlük ederseniz iyi bilin ki mahrumiyetim pek şiddetli olacaktır.\""},{"n":8,"t":"Ve Musa dedi ki: \"Siz ve yeryüzünde bulunan herkes topyekün nankörlük etseniz bile, şunu unutmayın ki Allah övgülerin tümü kendine mahsus olup kendi kendisine yeten yegane zattır."},{"n":9,"t":"Sizden öncekilerin haberi size gelmedi mi? Nuh, Ad ve Semud kavimlerinin ve onlardan sonra gelenlerin (uğradıkları felaketin gerçek mahiyetini) Allah`tan başka kimse bilmez. Elçileri onlara hakikatin apaçık delilleriyle gelmiş, onlar ise nimeti teperek (sözlerini) ağızlarına tıkmışlar ve \"Şunu aklınıza koyun ki biz sizinle gönderilenleri reddediyoruz; zira biz, davet ettiğiniz şeye dair şüphe içindeyiz\" demişlerdi; mütereddit bir halde..."},{"n":10,"t":"Elçileri onlara \"Gökleri ve yeri var eden Allah hakkında kuşku ha?\" dediler; \"O sizi günahlarınızdan arındırıp bağışlamaya ve sizin (hak ettiğiniz cezayı) belirli bir süre erteleyerek, sizleri (tevbe etmeye) çağırıyor. Onlar şöyle cevapladılar: \"Siz de bizim gibi ölümlü bir insandan başkası değilsiniz. Siz bizi babalarımızın öteden beri tapa geldiği şeylerden vazgeçirmek istiyorsunuz. Madem öyle, bize apaçık bir belge getirsenize!\""},{"n":11,"t":"Peygamberleri onlara şöyle cevap verdi: \"Evet, biz de yalnızca sizin gibi ölümlü birer insanız, ama Allah kullarından dilediği kimseyi de nimetlendirir; üstelik Allah`ın izni olmaksızın size (bu konuda mucizevi) güçte bir belge sunmak da bizim üstümüze vazife değildir. Ne ki yürekten inananlar yalnızca Allah`a güvenip dayanmalıdırlar."},{"n":12,"t":"Hem bize yollarımızı bulmada rehberlik ettiği halde, Allah`a neden güvenip dayanmayalım ki? Ve elbette sizin bize çektirdiğiniz eza cefaya rağmen direneceğiz: sağlam bir dayanak arayan herkes de sadece Allah`a güvenip dayansınlar!\""},{"n":13,"t":"Sonunda inkarda direnenler peygamberlerine (iki seçeneğiniz var) dediler: \"Ya sizi yurdumuzdan sürüp çıkarırız, veya bizim inanç sistemimize dönersiniz!\" Bunun ardından Rableri kendilerine şöyle vahyetti: \"Zalimleri kesinlikle helak edeceğiz;"},{"n":14,"t":"onların ardından (boşalan) yere sizi yerleştireceğiz.\" İşte bu (son), Benim makamımdan ve tehdidimden korkan kimselere hastır."},{"n":15,"t":"Ve (mü`minler) önlerinin açılmasını niyaz ettiler. İnatçı zorbaların tümü ise dünyada yıkılıp gittiler."},{"n":16,"t":"Onun da ötesinde cehennem vardır; onlara orada iğrenç bir sıvı sunulacaktır."},{"n":17,"t":"Onu (yutmak için) yutkunacak fakat bir türlü yutamayacaktır. Derken ölüm(den beter bir hal) her yandan gelip onu kuşatacak, ne ki o ölüm imkanından mahrum olacaktır. Ve onun da ötesinde, çok daha ağır bir azap onları bekleyecektir."},{"n":18,"t":"Rablerini inkarda direnenlerin yapıp ettikleri (iyi şeyler), fırtınalı bir günde rüzgarın haşince saçıp savurduğu küle benzer; onların eline kazandıklarından hiçbir şey geçmez. Bu, işte budur telafisi mümkün olmayan büyük kayıp."},{"n":19,"t":"Görmez misin ki Allah, gökleri ve yeri mutlak hakikate (bir atıf olsun diye) amaçlı ve anlamlı olarak yarattı. (Dolayısıyla) eğer dilerse sizi topyekün ortadan kaldırır, yerinize yepyeni bir varlık türü getirir:"},{"n":20,"t":"bu Allah için erişilmesi güç bir şey de değildir."},{"n":21,"t":"Derken, (hesap günü) toptan Allah`ın huzuruna çıkmışlardır. Ve altta kalan zayıflar büyüklük taslayanlara diyecekler ki: \"Sahiden biz zamanında size uymuştuk; şimdi siz Allah`ın azabından bir şeyi bizden savabilecek durumda mısınız?\" Onlar cevap verecekler: \"Eğer Allah bize bir yol gösterseydi, biz de size kılavuzluk ederdik; inleyip sızlasak da (başımıza gelene) sabretsek de, bizim için hepsi bir: artık bizim sığınacak bir yerimiz yok!\""},{"n":22,"t":"Ve hüküm kesinleşip iş bitince Şeytan dedi ki: \"İşte hakikat: Allah size gerçekleşmesi kesin olan bir söz vermişti, ben de size söz vermiştim: fakat size verdiğim sözü tutmadım. Zira benim sizin üzerinizde yaptırım gücüm bulunmamaktaydı. Ne var ki sizi sadece davet ediyordum, siz de benim davetime yumuluyordunuz. Dolayısıyla beni suçlamayın, asıl kendinizi suçlayın! Ne ben sizin imdadınıza yetişecek durumdayım, ne de siz benim imdadıma. İşin gerçeği ben, sizin daha önce beni Allah`a ortak koşma girişimlerinizi de (ilahi mahkemede) kesinlikle reddediyorum. Elbette zalimleri, can yakıcı bir azap beklemektedir."},{"n":23,"t":"Fakat iman eden ve o imana uygun iş işleyen kimseler, zemininden ırmaklar çağlayan cennetlere buyur edilecekler. Onlar orada Rablerinin izniyle ebedi kalacaklar. Onlar orada (birbirlerine şöyle) mukabele edecekler: \"Mutluluklar!..\""},{"n":24,"t":"Allah`ın güzel bir söze nasıl bir benzetme yaptığını görmez misin? O, kökü (yerde) sabit, dalları göğe uzanan alımlı bir ağaç gibidir."},{"n":25,"t":"Rabbinin izniyle o her mevsim ürün verir. İşte Allah belki öğüt alırlar diye insanlara böyle misaller veriyor."},{"n":26,"t":"Çirkin bir söz ise, (ekili olduğu) yerden kökten sökülüp çıkarılmış (kendi başına) ayakta duramayan zavallı bir ağaç gibidir..."},{"n":27,"t":"Allah inanıp güvenen kimseleri sabit, sağlam bir sözle hem dünyada hem de ahirete sapasağlam (dimdik ayakta) tutar; ve Allah zalimlerin ayaklarını kaydırır: çünkü Allah dilediğini yapar."},{"n":28,"t":"Görmez misin Allah`ın nimetini limitsiz bir nankörlükle takas edenleri? Ve toplumlarını sürükleyenleri tükeniş diyarı olan"},{"n":29,"t":"cehenneme? (Evet) oraya varıp dayanacaklar: Ama orası ne berbat bir ikametgahtır!"},{"n":30,"t":"Allah`a, O`nun yolundan saptırmak için eşdeğer rakip güçler tasavvur ettiler. De ki: \"Geçici arzularla oyalana durun, nasıl olsa varacağınız yer ateş olacaktır!\""},{"n":31,"t":"İmanda sebat gösteren kimselere söyle: hiçbir pazarlığın, hiçbir dostluğun fayda vermediği gün gelip çatmazdan önce hakkını vererek namaz kılsınlar, kendilerine verdiğimiz nimetlerden -gizli ya da açık- infak etsinler."},{"n":32,"t":"(Unutmayın ki) Allah`tır gökleri ve yeri yaratan; gökten suyu indiren ve onunla size rızık olması için ürünler çıkaran; ve Kendi emriyle denizde yüzen gemileri sizin yararlanmanız için (bir yasaya) tabi kılar; ve nehirleri siz yararlanasınız diye (bir yasaya) bağlayan;"},{"n":33,"t":"yine sizin yararlanmanız için (bir yörüngede) devinip duran güneşi ve ayı (yasalara) tabi kılan; yine sizin için geceyi ve gündüzü (yasalarına) amade kılan;"},{"n":34,"t":"ve isteyebileceğiniz her türlü şeyden (yararınıza olanları) size veren... Ve eğer Allah`ın nimetlerini saymaya kalksanız baş edemezsiniz. Şu da bir gerçektir ki, insanoğlu zulme pek yatkın olup nankörlüğünde hayli ısrarcıdır."},{"n":35,"t":"Bir zaman da İbrahim, \"Rabbim!\" demişti, \"Bu beldeyi güvenlikli kıl; ben ve çocuklarımla birlikte hepimizi putlara tapmaktan uzak tut!"},{"n":36,"t":"Rabbim! Çünkü o putlar insanlardan bir çoğunu saptırdılar: Artık kim bana uyarsa işte o bendendir; kim de bana karşı çıkarsa biliyorum ki Sen tarifsiz bir bağışlayıcısın, eşsiz bir merhamet kaynağısın!"},{"n":37,"t":"\"Rabbimiz! İşte ben, neslimden bir kısmını ekip-biçmeye elverişsiz bir vadiye, Senin Mukaddes Beytinin yanına yerleştirdim. Ey Rabbimiz, (bunu) kulluklarını yerine getirebilsinler diye (yaptım)! Artık insanların gönüllerini onlara meylettir; onları bereketli ürünlerle rızıklandır; umulur ki onlar da (bunun) şükrünü eda ederler!.."},{"n":38,"t":"`Rabbimiz! Sen bizim gizlediğimizi de bilirsin, açığa vurduğumuzu da. Çünkü ne yerde, ne de gökte hiçbir şey Allah`tan gizli kalmaz."},{"n":39,"t":"\"Her tür övgü ve sena, yaşlılığıma rağmen bana İsmail ve İshak`ı bahşeden Allah`a aittir. Gerçekten de benim Rabbim duaları işitendir:"},{"n":40,"t":"(Öyleyse) ey Rabbim! Beni ve neslimden gelenleri ibadet ve kulluğun hakkını verenlerden kıl; ve duamı kabul buyur ey Rabbimiz!"},{"n":41,"t":"\"Rabbimiz! Beni, ebeveynimi ve tüm inananları hesapların verileceği gün affet!\""},{"n":42,"t":"Sen, zalimlerin yaptıklarından Allah`ı habersiz sanmayasın. Ne var ki O onları, sadece gözlerin yuvalarından fırlayıp bir noktada donakaldığı bir güne ertelemektedir."},{"n":43,"t":"(O gün) onlar arkaya kaykılmış başları, yuvalarına bir türlü dönmeyen fırlamış bakışları ve tamtakır yürekleriyle panik içinde seğirtip dururlar."},{"n":44,"t":"Bu yüzden, başlarına azabın geleceği gün için insanları uyar. Zalimler (o gün) diyecekler ki: \"Rabbimiz! Bize kısa bir süre daha tanı da, senin çağrına katılalım ve elçilere tabi olalım!\" (Onlara denilecek ki): \"Ne oldu? Daha önceki (hayatta), sizin için herhangi bir tükenişin olamayacağına yemin edip durmuyor muydunuz?"},{"n":45,"t":"Üstelik siz, kendilerine zulmedenlerin yurdunda yaşıyordunuz; dahası onlara nasıl muamele ettiğimiz size açıklanmıştı; ve size örnekler de göstermiştik."},{"n":46,"t":"Ama onlar hilelerini sürdürdüler; isterse onların hileleri dağları yerinden oynat(mayı vaad et)sin, yine de hileleri bütünüyle Allah’a ayandır."},{"n":47,"t":"İşte bu yüzden, asla Allah`ın elçilerine olan vaadinden cayacağını sanma! Unutma ki Allah, herkese yaptığının acısını tattıran yüceler yücesidir."},{"n":48,"t":"O gün yer başka bir yere, gökler ise (başka göklere) dönüştürülür; ve her şeye egemen biricik güç olan Allah`ın huzuruna çıkarlar;"},{"n":49,"t":"ve sen günahkarları o gün zincirlerle birbirlerine bağlı olarak görürsün."},{"n":50,"t":"Onların giysileri katrandandır; suratlarını ise ateş yalazı bürüyecektir."},{"n":51,"t":"(İşte bu), Allah`ın her bir cana kendi kazandığının karşılığını verdiği içindir; elbette hesabı (böylesine) seri gören sadece Allah`tır."},{"n":52,"t":"Bu, insanlık için bir mesajdır: Artık onunla uyarılsınlar ve bilsinler ki biricik ilah O`dur: nihayet derin kavrayış sahibi olanlar, bunu hatırdan hiç çıkarmasınlar!"}],[{"n":1,"t":"Elif-Lam-Ra! Bunlar Kitab`ın, yani özünde açık ve (hakikatı) açıklayıcı olan ilahi hitabın ayetleridirler."},{"n":2,"t":"Gün gelecek, inkarda ısrar edenler (vahyin yol göstericiliğine) teslim olmayı yürekten temenni edecekler."},{"n":3,"t":"Kendi haline bırak onları; yesinler, geçici hazlarla avunsunlar, oyalasın onları boş umutlar: nasıl olsa zamanı gelince (gerçeği) öğrenecekler."},{"n":4,"t":"Zira Biz hiçbir memleketi, (önceden) bilinip anlaşılan ilahi bir vahye muhatap kılmadıkça helake sürüklememişizdir."},{"n":5,"t":"(Kaldı ki) hiçbir uygarlık, kendisi için belirlenen sürenin (artık kaçınılmaz olan) bitimini ne öne alabilir ne de erteleyebilir."},{"n":6,"t":"Bir de (kalkıp) \"Sen ey kendisine uyarıcı mesaj indiğini (iddia eden) kişi, evet sen kesinlikle mecnunsun!\" dediler;"},{"n":7,"t":"\"Eğer doğru söylüyor idiysen, bize meleklerle gelseydin ya!\" (diye de eklediler)."},{"n":8,"t":"Biz, melekleri ancak ve ancak hakikatin gerçekleşmesi için indiririz; eğer (dedikleri olsaydı), o zaman da onlar için asla erteleme olmazdı."},{"n":9,"t":"Elbette bu uyarıcı mesajı kaynağından indiren Biziz; onu koruyacak olan da kesinlikle yine Biz olacağız, Biz!"},{"n":10,"t":"Doğrusu (Ey Peygamber), senden önce de geçip gitmiş topluluklara (elçiler) göndermiştik."},{"n":11,"t":"Kendilerine gelen hiçbir elçi yoktu ki onları alaya almamış olsunlar."},{"n":12,"t":"Biz (vahyin, etki etmeden) günahkarların yüreklerinden geçip gitmesini işte böyle sağlarız;"},{"n":13,"t":"onlar da öncekilerin nasıl bir model ortaya koydukları sergilendiği halde, (yine de) bu (vahye) inanmazlar."},{"n":14,"t":"Ve eğer onların üzerine gökten bir kapı açmış olsaydık ve onlar da oraya yükselebilselerdi,"},{"n":15,"t":"kesinlikle derlerdi ki: \"Al işte, bizim basiretimiz de bağlandı; daha da beteri (galiba) biz topyekün büyülendik...\""},{"n":16,"t":"Doğrusu Biz, gökyüzünde yıldız kümeleri var ettik; ve onları (ibret nazarıyla) bakanlar için süsledik."},{"n":17,"t":"Ve onları (bilir bilmez) atan her tür şeytani güçten koruduk."},{"n":18,"t":"Fakat kim ki (gayb konusunda) kulak hırsızlığına soyunur, onun peşine ayan açık parlak bir alev takılır."},{"n":19,"t":"Ve yeryüzünü (engebeli arazi yapısıyla) uzatıp genişlettik; zira orada kalkmaz kımıldamaz dağlar yerleştirdik; üstelik orada her türün dengeli bir biçimde büyüyüp gelişeceği (bir canlı hayat) bahşettik."},{"n":20,"t":"Yine orada hem sizin için, hem de rızık vericisi siz olmadığınız bütün (diğer) varlıklar için geçinme imkanları sağladık."},{"n":21,"t":"Hiçbir şey yoktur ki, onun kaynağı Bizim katımızda olmamış olsun; fakat Biz her bir şeyi tesbit ve tayin edilmiş bir ölçüye göre indiririz."},{"n":22,"t":"Yine, aşılayıcı rüzgarları Biz sevk etmişiz; bunun sonucunda gökten suyu indirmiş ve onunla sizi suya kandırmışız; yoksa onun kaynağına hükmeden siz değilsiniz."},{"n":23,"t":"Ve elbette Biziz hayatı ve ölümü var eden; ve (ölümlü tüm varlıklardan) geriye kalan her şeyin tek gerçek varisi olan da Biziz."},{"n":24,"t":"Doğrusu Biz, sizin içinizden öne geçmek isteyenleri de, bile isteye geride kalanları da biliriz."},{"n":25,"t":"Ve gerçekte senin Rabbin var ya; işte O`dur onları bir araya toplayacak olan: Çünkü O her hükmünde hep isabet kaydeder, her şeyi tarifsiz bilir."},{"n":26,"t":"Doğrusu Biz insanı süzme, kurumuş, ses veren bir balçık türünden özgün bir biçim almaya elverişli, tabiatı değiştirilmiş, koyu ve yoğun çamur nevi bir şeyden yarattık."},{"n":27,"t":"Görünmez varlıkları ise, (insandan) daha önce, yakıp kavuran (şaşırtıcı bir karışımda), zehir gibi (insanın gözeneklerine) nüfuz eden tarifsiz bir ateşten yarattık."},{"n":28,"t":"Hani bir zamanlar Rabbin meleklere demişti ki: \"Bakın, Ben süzme, kurumuş, ses veren bir balçıktan; özgün bir biçim almaya elverişli, tabiatı değiştirilmiş, koyu ve yoğun bir çamurdan fiziki olarak görünen ölümlü bir varlık yaratacağım!"},{"n":29,"t":"İzleyin; ne zaman ki onu şekillendirir de kendisine ruhumdan üflersem, derhal yere kapanıp onun (hizmetine) amade olun!\""},{"n":30,"t":"Bunun üzerine meleklerin tümü hep birlikte yere kapandı;"},{"n":31,"t":"iblis müstesna: o (hizmete) amade olup yere kapananlarla birlikte hareket etmekten kaçındı."},{"n":32,"t":"(Allah) \"Ey İblis! Sen neden yere kapananlarla birlikte hareket etmedin?\" dedi."},{"n":33,"t":"(İblis) dedi ki: \"Benim, süzme, kurumuş, ses veren bir balçıktan; tabiatı değiştirilmiş, koyu ve yoğun bir çamurdan yarattığın bir beşerin emrine amade olmam yakışık almazdı!\""},{"n":34,"t":"(Allah) \"Öyleyse çık git bu makamdan!\" dedi, \"Çünkü sen kendi kendini aşağıladın!"},{"n":35,"t":"Ve unutma ki Hesap Günü`ne kadar tüm lanet senin üzerine olacaktır!\""},{"n":36,"t":"(İblis) \"Rabbim!\" dedi, \"Madem öyle, bana tekrar diriliş gününe kadar süre tanı!\""},{"n":37,"t":"(Allah) buyurdu ki: \"Peki, sen zaten süre tanınmışlardan birisin;"},{"n":38,"t":"(tabi ki, sadece tarafımdan) bilinen zaman doluncaya ve günü gelinceye kadar!\""},{"n":39,"t":"(İblis) \"Rabbim!\" dedi, \"Beni yoldan dışladığın için ben de yeryüzünde onlara (günahları) süslü püslü göstereceğim ve kesinlikle onların tümünü yoldan çıkaracağım."},{"n":40,"t":"Bunun tek istisnası, onlar arasındaki imanını saf ve temiz tutma çabasını desteklediğin kullar olacak!\""},{"n":41,"t":"(Allah) buyurdu ki: \"(Zaten) bu, kendim için benimsediğim en doğru yol ve yöntemdir;"},{"n":42,"t":"Şu bir gerçek ki, has kullarım üzerinde senin hiçbir inandırıcı gücün olmayacaktır; ne var ki batıl inançlı cahil ve bilinçsizlerden sana uyanlar müstesna!"},{"n":43,"t":"İşte onların tümünün buluşma yeri cehennemdir;"},{"n":44,"t":"oranın yedi kapısı vardır; o kapıların her biri, onlardan (günahına göre) tasnif edilmiş bir kesime tahsis edilecektir."},{"n":45,"t":"Ve fakat muttakiler! Onlar has bahçelerde, pınar başlarında..."},{"n":46,"t":"(Çünkü) onlara \"Esenlik ve güvenlik içinde oraya girin!\" (denilecek)."},{"n":47,"t":"Zira Biz Onları, içlerine işlemiş olan her tür olumsuz duygu ve düşünceden tamamen arındıracağız. Onlar mutluluk tahtları üzerinde, kardeşler olarak karşılıklı oturacaklar."},{"n":48,"t":"Orada onlar ne bir yorgunluk ve zahmete katlanacaklar, ne de oradan çıkarılacaklar."},{"n":49,"t":"(Ey Peygamber!) Kullarıma haber ver: Ben, evet Ben tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıyım!"},{"n":50,"t":"Ama unutma ki, en çok elem ve ıstırap veren azap da Benim azabım!"},{"n":51,"t":"Onlara İbrahim`in konuklarından da haber ver:"},{"n":52,"t":"Hani, onun huzuruna girmişler ve \"Selam!\" demişlerdi. (İbrahim) ise \"Doğrusu biz sizden çekiniyoruz\" diye mukabele etmişti."},{"n":53,"t":"\"Çekinmenize gerek yok\" dediler, \"çünkü biz sana bilge bir oğlan çocuğu müjdelemek amacıyla geldik.\""},{"n":54,"t":"\"Ne! Yaşlılık gelip başıma çökmüşken bana bu müjdeyi veriyorsunuz, öyle mi?\" dedi; \"Peki neye dayanarak bana müjde veriyorsunuz?\""},{"n":55,"t":"Onlar \"Biz seni, gerçekleşmesi kaçınılmaz bir bilgiye dayanarak müjdeliyoruz\" deyip eklediler: \"Sakın ha, umutsuzluğa düşeyim deme!\""},{"n":56,"t":"(İbrahim) \"Yoldan sapanlar dışında Rabbinin rahmetinden kim umut kesebilir ki?\" dedi"},{"n":57,"t":"ve ekledi: \"Daha başka bir işiniz de var mı ey elçiler?\""},{"n":58,"t":"Dediler ki: \"Evet, biz günaha gömülmüş bir toplumun (helakı) için gönderildik;"},{"n":59,"t":"tabii ki Lut`un (iman) ailesi bundan istisna. Şu kesin ki, biz onların tümünü kurtaracağız;"},{"n":60,"t":"onun karısı hariç! Biz (tercihine bakarak) bunu öngördük; çünkü o dökülenlerden biri olmayı seçti.\""},{"n":61,"t":"Derken, elçiler Lut ailesinin (yanına) gelince"},{"n":62,"t":"o dedi ki; \"Bakın, siz tanınmayan garip kimselersiniz!\""},{"n":63,"t":"Dediler ki: \"Hayır, aksine biz sana onların kendisi hakkında kuşku içerisinde bocalayıp durdukları şeyi getirdik,"},{"n":64,"t":"ve biz sana tartışılmaz bir gerçekle geldik; zira unutma ki biz sadece doğruyu söyleriz."},{"n":65,"t":"Şu durumda sen gecenin bir vaktinde aileni yola çıkar, sen de onların arkalarından peşlerine takıl! Sizden hiç kimsenin gözü arkada kalmasın! Emredildiğiniz yere doğru ilerleyin!\""},{"n":66,"t":"Ve ona şu kesin kararımızı bildirdik: \"İşte bu güruhun kökü gün ağarırken tamamen kazınmış olacaktır!\""},{"n":67,"t":"Derken, şehir halkı sevinç çığlıkları atarak gelip (kapıya dayandı)."},{"n":68,"t":"(Lut) dedi ki: \"Bakın, onlar benim konuklarımdır! Sakın bir rezalet çıkarayım demeyin!"},{"n":69,"t":"Ve Allah`tan korkun; beni de utanç içinde bırakmayın!\""},{"n":70,"t":"Şöyle çıkıştılar: \"Yok ya! Biz seni el alemin işine karışmaman konusunda uyarmamış mıydık?\""},{"n":71,"t":"(Lut) dedi ki: \"İşte kızlarım; tabi ille de bu işi yapacaksınız!..\""},{"n":72,"t":"(Melekler) \"Hay, sen bin yaşa!\" dediler; \"Baksana, onlar (şehvet) sarhoşluğuyla (gömüldükleri günah bataklığı) içerisinde debelenip duruyorlar!\""},{"n":73,"t":"Ve şafak ağarırken, onları (dehşetli) sayha kıskıvrak yakalayıverdi;"},{"n":74,"t":"ve oranın altını üstüne getirdik ve o coğrafyanın üzerine (püskürtü halinde) akkor balçıktan taşlar yağdırdık."},{"n":75,"t":"Kuşku yok ki bütün bunlarda, işaretleri okumasını bilen kimselerin alacağı nice ibretler vardır."},{"n":76,"t":"Yine kuşku yok ki bu (şehir)ler, (hala) varlığı sabit bir yol üzerindedirler."},{"n":77,"t":"Kuşkusuz bütün bunlarda iman sahiplerinin alacağı nice ibretler vardır."},{"n":78,"t":"Doğrusu (Medyen`deki) Yeşil Vadi`nin halkı da zulme gömülmüş kimselerdi."},{"n":79,"t":"Bundan dolayı Biz, onlara (da) yaptıklarının acısını tattırdık. İşte adı geçen bu iki toplumun da, (dünyevi refah açısından) çok önde olduğu ayan açık ortadaydı."},{"n":80,"t":"Doğrusu Hicr halkı da gönderilen elçileri yalanlamıştı."},{"n":81,"t":"Zira onlara ayetlerimizi iletmiştik, fakat onlar o (ayetlerden) ısrarla yüz çevirmiştiler."},{"n":82,"t":"Hesapta onlar dağları oyarak kendilerine güvenli evler inşa ediyorlardı;"},{"n":83,"t":"fakat sabahın ilk ışıklarıyla (dehşetli) sayha onları kıskıvrak yakalayıverdi;"},{"n":84,"t":"ve elde ettiklerinden hiçbir şey onların başından belayı savamadı."},{"n":85,"t":"İmdi Biz, gökleri, yeri ve o ikisi arasındakileri başka değil, sadece mutlak hakikate atıf olsunlar için yarattık. Şu da bir gerçek ki, Son Saat kesinlikle gelecektir. Şu halde (onlara) hoşgörüyle karşılık ver:"},{"n":86,"t":"çünkü senin Rabbin var ya: en yüce yaratıcı, her şeyi bilen işte O`dur!"},{"n":87,"t":"Doğrusu Biz sana, seb`i mesani`yi, yani Yüce Kur`an`ı verdik."},{"n":88,"t":"(Öyleyse) onlardan kimilerine verdiğimiz geçici lezzetlere iltifat etme! Üstelik onlar için üzülme de... Ancak mü`minlere kol kanat ger."},{"n":89,"t":"ve de ki: \"Bakın ben, evet ben (ilahi vahyi) açıklayan uyarıcıyım!\""},{"n":90,"t":"(Vahyi sana Biz indirdik), tıpkı (onu önceden) paramparça edenlere indirdiğimiz gibi."},{"n":91,"t":"Onlar ki, (şimdi de) Kur`an`ı birbirinden kopuk sözler demeti olarak tasavvur ediyorlar."},{"n":92,"t":"Evet, Rabbine andolsun ki onların tümünü sorgulayacağız;"},{"n":93,"t":"yapıp ettikleri her şeyden!"},{"n":94,"t":"O halde, artık sana emredileni açıkça ortaya koy ve şirk koşmayı tabiat haline getirenlere aldırma!"},{"n":95,"t":"Unutma ki küçümseyip alaya alanlara karşı Biz sana yeteriz."},{"n":96,"t":"Onlar ki, Allah`la beraber başka bir ilah (atama yetkisini) kendilerinde buluyorlar. Nasıl olsa günü gelince (yaptıklarının ne demeye geldiğini) öğrenecekler!"},{"n":97,"t":"Doğrusu, onların söyledikleri şeylerden dolayı içinin daraldığını Biz de biliyoruz."},{"n":98,"t":"Öyleyse Rabbinin adını anarak O`nun yüceliğini hamd ile dile getir ve (hep) O`nun huzurunda secde edenlerden biri ol!"},{"n":99,"t":"Nihayet, ölüm gelip seni buluncaya dek Rabbine kulluğu (sürdür)!"}],[{"n":1,"t":"Allah`ın emri geldi (bilin); onun çabuk gelmesini istemenize gerek yok ki! Yüceler yücesi olan O, onların şirk koştukları her şeyin ötesinde aşkın ve eşsizdir."},{"n":2,"t":"O, kullarından dilediğine \"(İnsanları) uyarın! Şunu iyi bilin ki Benden başka ilah yok! O halde (başkalarına ilahlık yakıştırmaktan artık sakının!\" buyruğunu iletmeleri için, melekleri (ölü canlara) hayat veren vahiyle indirir.\""},{"n":3,"t":"O, gökleri ve yeri mutlak hakikate (bir atıf olsun diye) amaçlı olarak yarattı; eşyaya ilahlık yakıştıranların tasavvur ettiklerinin çok ötesinde, aşkındır O!"},{"n":4,"t":"O insanı bir damlacık atık sudan yaratmıştır. Fakat o da ne! O sonunda bilinçli bir (biçimde Allah`a karşı) kendini savunan biri olup çıkar."},{"n":5,"t":"Ve evcil hayvanları da O yarattı: sizi ısıtan giysileri onlardan temin ediyorsunuz. Daha başka yararlarının yanında onlardan elde etiğiniz besinleri de yiyorsunuz."},{"n":6,"t":"Yine onlarda, akşam getirirken ve sabah salarken sizin güzellik duygunuzu tatmin eden bir boyut vardır."},{"n":7,"t":"Kendinizi sıkıntıya sokmadan ulaşamayacağınız nice mekanlara yüklerinizi onlar taşır. İyi bilin ki Rabbiniz gerçekten çok şefkatli, pek merhametlidir."},{"n":8,"t":"O, atları, katırları ve merkepleri hem kendilerine binesiniz, hem de (hayata) güzellik katmak için yarattı; ve daha sizin bilmediğiniz nice şeyleri de yaratacak."},{"n":9,"t":"İşte (O tek yaratıcı olduğu için), yolun istikamet tayini de O`na düşer; zira bazı yollar saptırıcıdır. Eğer Allah dileseydi, hepinizi doğru yola yöneltirdi."},{"n":10,"t":"O’dur ki, sizin için gökten bir tür su indirir: içme suyunuz ondan meydana geldiği gibi, hayvanlarınıza yedirdiğiniz ot ve ağaçlar da onunla yetişir."},{"n":11,"t":"onunla sizin için ekin(ler), zeytin ve hurma ağaçları, üzümler ve daha nice ürünler bitirir O. Unutmayın ki bütün bunlarda, düşünen bir toplum için mutlaka çıkarılacak bir ders vardır."},{"n":12,"t":"Ve O`dur sizin yararlanmanız için geceyi ve gündüzü, güneşi ve ayı (yasalarına) boyun eğdiren; zaten bütün yıldızlar O`nun emrine teslim olmuşlardır. İyi bilin ki bütün bunlarda aklını kullanan bir toplum için mutlaka çıkarılacak bir ders vardır."},{"n":13,"t":"Ve sizin için yeryüzüne serpiştirdiği her biri farklı tonlarda rengarenk (güzellikler)... Kuşkusuz bütün bunlarda (da), hafızası olup hatırda tutan bir toplum için mutlaka çıkarılacak bir ders vardır."},{"n":14,"t":"Yemeniz için taze et ve takınıp kuşanmanız için mücevherat çıkarasınız diye denizi ve onun içinde suları yararak akıp gittiğini gördüğün(üz) gemileri, O`nun ihsanından payınıza düşeni arayacağınızı ve (bulunca da) şükredeceğinizi umarak (bir yasaya) tabi kılan da yine O`dur."},{"n":15,"t":"Bir yanda sizi sarsar diye yeryüzüne yerleştirdiği kalkmaz kımıldamaz dağlar, öte yanda yolunuzu bulabilmeniz için nehirler ve yollar,"},{"n":16,"t":"ve daha bir nice işaretler var... Mesela onlar, yıldızlarla yollarını buluyorlar."},{"n":17,"t":"İmdi bakın, hiç yaratan yaratamayan gibi (olur) mi? Hala gerçeğin farkına varmayacak mısınız?"},{"n":18,"t":"Ve eğer Allah`ın nimetlerini saymaya kalksanız asla baş edemezsiniz. İyi bilin ki, tarifsiz bir bağışlayıcı, eşsiz bir rahmet kaynağı elbet yalnızca Allah`tır."},{"n":19,"t":"Zira Allah, içinizde tuttuğunuz ve açığa vurduğunuz her şeyi bilir."},{"n":20,"t":"Allah`tan başka kendilerine yalvarıp yakardığınız varlıklar hiçbir şey yaratamazlar; zira onların kendileri yaratılmışlardır."},{"n":21,"t":"Onlar ölüdürler, diri değildirler; ne zaman diriltileceklerini dahi bilemezler."},{"n":22,"t":"Sizin ilahınız bir tek ilahtır; fakat ahirete inanmayan kimselerin yürekleri, büyüklük taslamaları yüzünden (bu hakikati) inkara meyletmiştir."},{"n":23,"t":"Ziyanı yok, nasıl olsa Allah onların gizlediklerini de açığa vurduklarını da bilmektedir. Şu bir gerçek ki O, büyüklük taslayanları hiç sevmez."},{"n":24,"t":"Ve kendilerine \"Rabbiniz size ne indirdi?\" diye sorulduğunda, \"Eskilerin masallarını...\" derler;"},{"n":25,"t":"Böylece Kıyamet Günü kendi günahlarının yükünü tamamen, bilgisizlikleri sebebiyle saptırdıklarının vebalini ise kısmen yüklenmiş olurlar. Hele bir bakın şunlara, ne berbat bir yükü yükleniyorlar!"},{"n":26,"t":"Doğrusu, onlardan öncekiler de zaafı ustaca gizlenmiş düzenler kurmuşlardı; fakat Allah onların kurdukları yapıları temellerinden sarstı ve sonunda üstlerindeki tavan başlarına çöktü: zira daha nereden geldiğini anlayamadan azap onlara ulaşıvermişti."},{"n":27,"t":"Sonunda Kıyamet Günü O, onları rezil edecek ve \"Neredeymiş bakalım o uğruna mücadele verdiğiniz `ortaklarım`(!)?\" diye soracak. Bilgi ve bilginin amacını kavrama yeteneğiyle donatılmış olanlar, \"Bugün\" diyecekler, \"alçaklığın her türü ve kötülüğün daniskası kafirler içindir!"},{"n":28,"t":"O kimseler ki, kendi kendilerine kötülük etmeyi sürdürürken melekler onların canlarını almışlardı. İşte (Hesap Günü) bunlar teslim sancağını çekerek \"Biz yaptıklarımızı kötülük olsun diye yapmamıştık\" (diyecekler). \"Yoo!\" (denilecek kendilerine), \"Unutuyorsunuz ama, Allah yapmış olduğunuz her şeyi eksiksiz bilendir."},{"n":29,"t":"Haydi o halde, içerisinde yerleşip kalmak üzere cehennemin kapılarından buyurun!\" İşte, büyüklük taslamayı kişiliğinin bir parçası haline getirenlerin düştüğü berbat konum."},{"n":30,"t":"Bir de sorumluluk bilincine sahip olanlara sorulacak: \"Rabbiniz size ne indirdi?\" Onlar \"iyilik-güzellik!\" diyecekler. İyilikte sebat gösterenler bu dünyada iyilik bulacaklar; ama ahiret yurdu ondan çok daha hayırlı olacak: ve elbet pek güzeldir muttakilerin yurdu!"},{"n":31,"t":"Zemininden ırmakların aktığı kalıcı mutluluğun merkezi olan cennetlere girecekler; orada istedikleri her şeyi bulacaklar. Allah, sorumluluk bilincine sahip olanları işte böyle ödüllendirecek."},{"n":32,"t":"Bunlar, meleklerin \"Selam sizlere!.. Yapmış olduklarınızdan dolayı girin cennete!..\" diyerek canlarını tertemizken aldığı kimseler olacak."},{"n":33,"t":"Şu berikiler başka değil, sadece meleklerin ya da Rablerinin (helak) emrinin kendilerine gelmesini bekliyorlar, öyle mi? Onlardan öncekiler de böyle yapmıştı. Onlara zulmeden Allah değildi; aksine onlar kendi kendilerine zulmetmiş oldular."},{"n":34,"t":"En sonunda yaptıkları kötülüklerin hedefi haline geldiler: alay edip durdukları şey tarafından çepeçevre kuşatıldılar."},{"n":35,"t":"Bir de, Allah`tan başkasına ilahlık yakıştırmakta direnenler dediler ki: \"Eğer Allah dileseydi, ne biz ne de atalarımız, hem O`ndan başka hiçbir şeye kulluk etmez hem de O`ndan başkasının (sözüyle) hiçbir şeyi haram kılmazdık.\" Onlardan öncekiler de böyle yapmışlardı; peki, bu durumda elçilere (mesajı) açık seçik bildirmek dışında başka ne düşer?"},{"n":36,"t":"Doğrusu Biz, (geçmiş) her uygarlığın içinden \"Allah`a kulluk edin, ilahlaştırılan şer otoriteden uzak durun!\" diyen bir elçi çıkarmışızdır. Bunun ardından onlardan kimileri Allah`ın gösterdiği doğru yola uydu, kimileri de (ısrarlı tercihleri sonucu) sapıklığa mahkum olmayı hak etti. İsterseniz yeryüzünde dolaşın ve yalanlayanların sonu nasıl olurmuş görün!"},{"n":37,"t":"Sen onların doğru yolu bulmasını ne kadar istersen iste, ama unutma ki Allah`ın sapıklığa mahkum ettiğini kimse doğru yola yöneltemez; onlara yardım eden de bulunmaz!"},{"n":38,"t":"Dahası, bunlar var güçleriyle Allah adına yeminler ediyorlar: \"Allah ölen kimseyi asla diriltmeyecektir!\" Kesinlikle hayır, bu O`nun gerçekleştirmeyi üstlendiği bir sözdür; ve fakat insanların çoğu bunu bilmiyorlar."},{"n":39,"t":"(Oysa ki), hakkında görüş ayrılığına düştükleri hakikati onlara ayan açık göstersin; (onu) inkarda ısrar edenler ise, kendilerinin yalancı olduklarını anlasınlar diye (Allah ölüleri diriltecektir)."},{"n":40,"t":"Gerçek şu ki, bir şeyin olmasını istediğimizde ona \"Ol!\" dememiz yeterlidir; o da hemen oluş sürecine girecektir."},{"n":41,"t":"Beri yandan, uğradıkları zulmün ardından Allah yolunda hicret edenlere gelince: kesinlikle onları dünyada güzel bir konuma yerleştireceğiz, fakat öte dünyadaki karşılıkları çok daha büyük olacaktır. (İnkarcılar) keşke kavrayabilselerdi."},{"n":42,"t":"eza cefaya karşı direnen ve sadece Rablerine dayanan kimseleri (bekleyen bu güzellikleri)..."},{"n":43,"t":"(Ey Peygamber!) Senden önce gönderdiklerimiz de kendilerine vahyettiğimiz (Ademoğullarına mensup) adamlardan başkası değildi -eğer bilmiyorsanız (önceki) vahiylerin mensuplarına sorabilirsiniz:"},{"n":44,"t":"(Biz onları) hakikatin açık belgeleri ve hikmet yüklü sayfalarla (göndermiştik). İşte sana da bu uyarıcı vahyi indirdik ki, kendilerine indirileni insanlara açıklayasın ve belki onlar da bu sayede düşünürler."},{"n":45,"t":"Yani şimdi, entrikaya dayalı düzenler kuran kimseler Allah`ın kendilerini yerin dibine geçirmeyeceğinden, ya da azabın hiç farkında olmadıkları bir noktadan gelip kendilerini bulmayacağından eminler, öyle mi?"},{"n":46,"t":"Veya (gündelik telaşeyle) dolaşıp dururken, kendilerine asla savuşturamayacakları bir (belanın) yakalamayacağından?"},{"n":47,"t":"Yahut da, bir süreç içerisinde içten içe çözülmeye mahkum edip ortadan kaldırmayacağından... Şunu da unutmayın ki Rabbiniz, elbet çok şefkatli, pek merhametlidir."},{"n":48,"t":"İmdi onlar, Allah`ın yarattığı çevrelerindeki şeylere hiç mi bakmıyorlar? Onların gölgeleri sağ ve sollarından süzülüp dönerken, Allah`a teslim olup (koyduğu yasaya) derin bir tevazu ile boyun eğmekteler."},{"n":49,"t":"Yine, (görünen) varlıkların en (yakın) tabakasından (görünmeyen varlıkların ufku olan) meleklere varıncaya dek, göklerde ve yerde olan her şey Allah`ın (yasasına) boyun eğip teslim olmuşlardır; onların hiçbiri büyüklük taslamazlar."},{"n":50,"t":"Üzerlerinde (egemen) olan Rablerinden korkarlar ve verilen komutları uygularlar."},{"n":51,"t":"Hani Allah şöyle buyurmuştu: \"İki ilah edinmeyin; çünkü yalnızca O`dur biricik ilah! Artık Benden, sadece Benden sakının!\""},{"n":52,"t":"Zira göklerde ve yerde olanların hepsi ona aittir; (varlıkların) O`na olan borçluluk sorumluluğunun bittiği bir nokta yoktur. Şimdi siz kalkıp Allah`tan başkasına saygı duyacaksınız, öyle mi?"},{"n":53,"t":"Fakat, nimetten payınıza her ne düşerse bilin ki o Allah`tandır. Dahası başınıza ne zaman iş gelse, hemen O`ndan imdat dilersiniz."},{"n":54,"t":"O daha sonra üzerinizden darlığı çekip alacak olsa, o zaman da içinizden bir gurup hemen Rablerine şirk koşmaya başlar;"},{"n":55,"t":"adeta kendilerine verdiğimiz nimetlere nankörlük edercesine... Haydi, tadımlık lezzetlerle oyalanın bakalım: gün gelecek nasıl olsa (gerçeği) öğreneceksiniz."},{"n":56,"t":"Bir de kendilerine verdiğimiz rızıktan (dolayı), hakkında bir şey bilmedikleri nesnelere bir pay ayırırlar. Allah şahittir ki, iftira ede geldikleri şeylerden dolayı, kesinlikle sorguya çekilecekler."},{"n":57,"t":"Üstelik kızları Allah`a isnat ederken, -haşa, beşeri niteliklerden uzak aşkın bir varlıktır O- beğendiklerini ise kendilerine ayırıyorlar."},{"n":58,"t":"Ne var ki onlardan birine (bir) kız çocuğu olduğu müjdelense suratı kapkara kesilir. İçini öfkeyle karışık bir hüzün kaplar;"},{"n":59,"t":"Ona müjdelenen şeyin kendisinde oluşturduğu kötümser duygulardan dolayı, toplumdan kaçıp köşe bucak saklanacak delik arar: şimdi onu zillete katlanma pahasına tutsun mu, yoksa toprağa mı gömsün? Görüyorsunuz değil mi; ne berbat akıl yürütüyorlar."},{"n":60,"t":"Çirkin niteleme(ler)e ahirete inanmayanlar layıktır; Allah`a layık olan ise en yüce, en güzel niteleme(ler)dir: zira O her işinde mükemmel olandır, her hükmünde tam isabet sahibidir."},{"n":61,"t":"Nitekim, eğer Allah insanları zulümleri nedeniyle hemen cezalandıracak olsaydı, yeryüzünde bir tek canlı bırakmazdı; fakat onları belirli bir süreye kadar ertelemektedir. Ama vadeleri dolduğu vakit, akıbetlerini ne bir an geciktirebilirler ne de çabuklaştırabilirler."},{"n":62,"t":"Hem kendilerinin hoşlanmadığı şeyi Allah`a layık görürler, hem de en güzel akıbete kendileri layıkmış gibi yalan beyanda bulunan dilleriyle kendilerini aldatırlar. Hiç kimsenin kuşkusu olmasın ki, ellerine geçen sadece ateş olacaktır; üstelik de onlar önden buyur edilecekler."},{"n":63,"t":"Allah şahittir ki, senden önceki toplumlara da nice elçiler göndermişizdir: fakat Şeytan onlara eylemlerini güzel göstermiştir. Bakın işte o bugün onların kılavuzudur, fakat (yarın) onları yürek yakan bir ceza beklemektedir."},{"n":64,"t":"Biz sana ilahi mesajı, sadece üzerinde anlaşmazlığa düştükleri (inançla ilgili) meselelerin çözümlerini kendilerine sunasın, inanıp güvenecek bir topluluk için de bir yol haritası ve bir rahmet olsun diye indirdik."},{"n":65,"t":"Ve (bakın), gökten yağmuru indirip ölümünün ardından onunla toprağa can veren Allah`tır: şüphesiz bunda da işiten bir toplum için mutlaka alınacak bir ders vardır."},{"n":66,"t":"Yine sizin için sağmal hayvanlarda da alınacak bir öğüt vardır: size hayvanın karnında sindirilen şeylerden oluşan, atıklarından ve kanından ayrışarak süzülüp gelen saf ve lezzetli, sindirimi kolay bir süt içiriyoruz."},{"n":67,"t":"Yine, hurma ağaçlarının ve asmalarının ürünlerinden, hem sarhoşluk veren (zararlı) şeyler, hem de yararlı, güzel bir rızık elde ediyorsunuz: elbet bunda aklını kullanan bir topluluk için mutlaka alınacak bir öğüt bulunmaktadır."},{"n":68,"t":"Yine Rabbinin arıya vahyetti(ğini de düşün): \"Dağlardan, ağaçlardan ve imal edilmiş kovanlardan kendine yuva edin!"},{"n":69,"t":"Sonra her türlü üründen ye ve ardından Rabbinin sana amade kıldığı yollarına koyul!\" (Bütün bunların sonunda) onların karınlarından, içerisinde insanlar için şifa barındıran farklı renkler/tatlardan oluşan bir sıvı çıkar. Hiç şüphesiz, bütün bunlarda da düşünen bir toplum için mutlaka alınacak bir ders vardır."},{"n":70,"t":"Sizi de Allah yarattı, sonra canınızı alacak. İçinizden kimileri ömrün en düşkün çağına kadar ulaştırılır. Hatta öyle ki, bilirken hiçbir şey bilmez olur: (ama) unutmayın ki Allah her şeyi bilir, sınırsız bir kudret sahibidir."},{"n":71,"t":"Allah rızkı kiminize diğerinden daha fazla vermiştir. Peki, kendisine fazla verilenler emirleri altında çalışan kesimleri servetlerine ortak etseler de, onlar da bu konuda (kendileriyle) eşit hale gelseler ya! Buna (dahi razı olmayacaklarına) göre, hala (ortak koşmakla), Allah`ın nimetlerini bile bile inkara yeltenmiş olmuyorlar mı?"},{"n":72,"t":"Yine Allah size sizin cinsinizden eşler var etti; ve eşlerinizden sizin için çocuklar ve torunlar takdir etti; ve sizi temiz ve güzel şeylerle rızıklandırdı. Bütün bunlara rağmen bir yandan asılsız şeylere inanıp öte yandan Allah`ın nimetini inkar edecekler, öyle mi?"},{"n":73,"t":"Üstelik Allah`ı bırakıp, kendileri için göklerden ve yerden rızkın hiçbir türünü sağlayamayan ve buna gücü de yetmeyen şeylere kulluk edecekler!?"},{"n":74,"t":"Artık Allah ile (başka şeyler arasında) benzetme yoluyla misal vermeye kalkmayın! (Allah misaller veriyor;) çünkü Allah (her şeyi) biliyor, fakat siz bilmiyorsunuz."},{"n":75,"t":"(İşte, örnek olarak) Allah size şu misali verir: Başkasının boyunduruğu altındaki köle sınıfına mensup birini (düşünün; bir de) kendisine tarafımızdan güzel bir rızık verdiğimiz ve ondan açık ve gizli hayırda bulunan (hür) birini... Şimdi bunların (ikisi de) bir tutulabilir mi? Övgülerin en mükemmeline yalnız (iradeyi yaratan) Allah layıktır: fakat onların çoğu (bunun dahi) farkında değiller!"},{"n":76,"t":"Yine Allah şu iki adamı da misal verir: Onlardan biri elinden hiçbir iş gelmeyen, iki lafı bir araya getiremeyen bir ahmak. Üstüne üstlük bir de efendisinin sırtında yük. Onu nereye gönderse başarılı bir sonuçla dönemez. Şimdi böyle biri, adaleti emreden ve kendisi de dosdoğru yolda olan kimseyle denk tutulabilir mi?"},{"n":77,"t":"İmdi, göklerin ve yerin gaybını (bilmek) yalnızca Allah`a mahsustur: Nitekim Son Saat`in gelip çatması, sadece bir göz açıp kapamak gibi veya daha da kısa bir zamanda vuku bulacak. Unutmayın ki her şeyi yapmaya kadir olan yalnızca Allah`tır."},{"n":78,"t":"Sizi analarınızın karınlarından hiçbir şey bilmez bir halde çıkaran, belki şükrederler diye sizin için işitme, görme ve duyma-düşünme kabiliyeti takdir eden de yine Allah`tır."},{"n":79,"t":"Peki, kuşlar üzerinde hiç mi gözlem yapmazlar? Onlar göğün boşluğunda (uçarken, ilahi yasalara) boyun eğmişlerdir. Onları orada tutan (yasayı) Allah`tan başka kimse (koyamaz). Hiç şüphesiz, inanıp güvenen bir toplum için bunda da mutlaka alınacak dersler vardır."},{"n":80,"t":"Size içinde huzur ve sükun duyacağınız sabit meskenler (inşa etme yeteneği) veren; yine size hayvanların derilerinden konup göçerken kolayca taşıyacağınız seyyar mekanlar (yapma yeteneğini) kazandıran; onların yünlerinden, kürklerinden, kıllarından hem dayanıklı temel eşyalar hem de sınırlı süre kullanılan dayanıksız tali eşyalar (üretme yeteneğini) veren de Allah`tır."},{"n":81,"t":"Yarattığı şeylerden kimilerini size gölgelik kılan; ve dağlardan size sığınaklar-korunaklar temin eden; yine size hem sıcağa (ve soğuğa) karşı korunacak giysiler, hem de savaşlarınızın darbelerinden korunacak elbiseler (imal etme yeteneği) veren de Allah`tır. Size olan nimetlerini işte böyle tamamladı; belki (O`na) teslimiyetiniz (de tam) olur."},{"n":82,"t":"Buna rağmen yüz çevirirlerse unutma ki sana düşen açık ve net olarak (mesajı) tebliğ etmektir."},{"n":83,"t":"Allah`ın nimetlerini pekala tanıyıp biliyorlar, fakat yine de nankörlük ediyorlar; zira onların çoğu küfre sapmışlar."},{"n":84,"t":"Fakat bir gün gelecek Biz, her ümmetten bir şahit çıkaracağız. Sonra inkarda ısrar edenlere ne mazeret beyan etme izni verilecek, ne de suçlarını itiraf ile af dileme imkanı."},{"n":85,"t":"Ve o zulmedenler azabı görünce, artık onun kendilerine hafifletilmeyeceğini de fırsat tanınmayacağını da anlayacaklar."},{"n":86,"t":"Allah`a ait nitelikleri başkalarına yakıştıranlar ise, (Allah`a) yakıştırdıkları ortakları karşılarında görünce; \"Rabbimiz! İşte sana ortak koştuklarımız; Seni bırakıp da kendilerine yalvarıp durduğumuz kimseler bunlardı!\" der demez, hemen berikiler onların sözlerini ağızlarına tıkayacaklar: \"Sizi gidi yalancılar sizi!..\""},{"n":87,"t":"İşte o gün onlar, (iş iten geçtikten sonra) Allah`a kayıtsız şartsız teslimiyetlerini sunarlar; uydurdukları kuruntu (aracılar) kendilerini yüzüstü bırakırlar."},{"n":88,"t":"İnkarda direnmekle kalmayıp başkalarını da Allah`ın yolundan çeviren kimselerin üzerine, sebep oldukları toplumsal çürüme ve yozlaşmadan dolayı azab üstüne azap yığacağız;"},{"n":89,"t":"ve günü gelince onların aleyhine (de) her bir ümmetin kendi içerisinden bir şahit çıkaracağız. Seni de (Ey Muhammed), işte şu (mesajın muhatabı olan) insanlara bir şahit olarak getirdik; ve sana (din ile ilgili) her şeyi ana kaynağından indirerek vurgulu bir biçimde açıklayan ve bir yol haritası, bir rahmet ve Allah`a teslim olanlar için bir müjde olan bu ilahi mesajı indirdik."},{"n":90,"t":"Hiç şüphe yok ki Allah adil davranmayı, iyilik yapmayı ve yakınlara karşı cömert olmayı emreder; ve her türlü utanç verici hayasızlığı, selim akla ve sağduyuya aykırı çirkinliği ve sınırları hiçe sayan taşkınlık ve azgınlığı yasaklar: size (bu) öğütleri verir ki, sorumluluklarınızı aklınızda tutabilesiniz."},{"n":91,"t":"Yine Allah ile sözleşme yaptığınızda, sözünüze sadakat gösteriniz; bir de yeminlerinizi iyice kesinleştirdikten sonra bozmaya kalkmayınız! Unutmayınız ki Allah`ı kendinize kefil kılmıştınız: zira Allah yaptığınız her şeyi biliyor."},{"n":92,"t":"Ve asla bir topluluk (diğerinden) daha karlı gerekçesiyle, yeminlerinizi kendi aranızda bir kandırmacaya dönüştürerek, ipliğini iyice eğirdikten sonra onu tersine çevirip çözen kadının durumuna düşmeyin! Şüphesiz Allah sizi bununla sınamaktadır; ve elbette Kıyamet Günü üzerinde sürekli tartışıp farklı sonuçlara ulaştığınız şeyleri açık seçik önünüze serecektir."},{"n":93,"t":"Zaten eğer Allah dileseydi sizi tek bir ümmet yapıverirdi; fakat o sapmak isteyeni saptırıyor, doğru yöne yönelmek isteyeni ise (ona) yöneltiyor: ne ki (seçiminiz sonucu) yapa geldiğiniz her şeyden mutlaka hesaba çekileceksiniz."},{"n":94,"t":"Asla yeminlerinizi bir kandırma aracına dönüştürmeyin; yoksa ayağınızı sağlam basmışken (zemin alttan) kayıp gider ve Allah yolundan uzaklaşmanızın kötü sonuçlarını (yudum yudum) tadarsınız; üstelik (ötede) sizi bekleyen daha korkunç bir azap bulursunuz."},{"n":95,"t":"Ve Allah ile yaptığınız sözleşmeyi az bir bedel karşılığında satmayın! Bakın, (onun) Allah katındaki karşılığı var ya; işte o eğer bilirseniz sizin için çok daha hayırlıdır."},{"n":96,"t":"(zira) sizin yanınızdaki tükenir, fakat Allah katındakiler bakidir. İmdi herkes emin olsun ki, zorluklara karşı göğüs gerenleri işlediklerinin en iyisiyle ödüllendireceğiz:"},{"n":97,"t":"kim imanlı olarak bir iyilik ortaya koymuşsa; -erkek ya da kadın (fark etmez)- kesinlikle ona güzel bir hayat yaşatacağız; dahası elbet onları işlediklerinin en iyisiyle ödüllendireceğiz."},{"n":98,"t":"Bundan böyle Kur`an okuyacağın zaman, öncelikle kovulmuş şeytandan Allah`a sığın."},{"n":99,"t":"Fakat şunu da unutma ki, (Şeytan`ın) imanda sebat gösterenlerin ve Rablerine güvenip dayananların üzerinde etkin bir gücü yoktur;"},{"n":100,"t":"ne var ki o, yalnızca kendisini kılavuz edinip ısrarla izleyenlerin ve kendisine ilahlık yakıştıranların üzerinde etkin bir güç sergileyebilir."},{"n":101,"t":"Ve Biz bir ayeti diğeriyle değiştirdiğimizde, -ki Allah neyi ne zaman indireceğini pekala bilir- \"Sen sadece ve sadece uydurduklarını söyleyen birisin!\" derler; aksine onların çoğu (lafının nereye vardığını) bilmeyen kimselerdir."},{"n":102,"t":"De ki: \"Onu Kutsal Ruh, mutlak hakikate bir atıf olsun ve hem imanda sebat edenleri desteklesin, hem de Allah`a teslim olan kimseler için bir yol haritası ve bir müjde olsun diye, Rabbin katındaki ana kaynaktan indirdi!\""},{"n":103,"t":"Doğrusu Biz onların; \"Ona bu (vahyi) öğreten bir insandan başkası değil\" dediklerini çok iyi biliyoruz. Onların gerçeği saptırmak için kendisini ima ettikleri kişinin dili yabancı bir dil olduğu halde, bu (vahyin) dili hem özünde açık hem de hakikatı açıklayan bir Arapça`dır."},{"n":104,"t":"Şu kesin ki; Allah`ın ayetlerine inanmayan kimseleri Allah doğru yola yöneltmeyecektir; dahası (ötede) onların payına can yakıcı bir azap düşecektir."},{"n":105,"t":"Zaten yalan uydurup (birilerine) atma işini, ancak Allah`ın mesajlarına inanmayanlar yapar: zira onlar, yalanı meslek edinenlerin ta kendileridir."},{"n":106,"t":"İman ettikten sonra Allah`ı inkar eden kimseye gelince: -(ki) bu kalbi imanla tatmin bulmuş olduğu halde baskı altında görünüşte inkar eden kimse değil, ve fakat kalbini küfre bile isteye açan kimsedir- işte böyleleri Allah`ın rahmetinden dışlanacaklar, dahası (ahirette) onları korkunç bir azap bekleyecektir."},{"n":107,"t":"İşte bu, hem onların dünya hayatını ahiret hayatına tercih etmelerinin, hem de Allah`ın inkarcı kimseleri doğru yola yöneltmemesinin neticesidir."},{"n":108,"t":"İşte onlar Allah`ın kalplerinin (akletme), işitme ve görme yetilerini mühürlediği kimselerdir. Artık onlar (bundan) dahi habersizdir."},{"n":109,"t":"Kimsenin en ufak kuşkusu olmasın ki, ahirette de hepten kaybedecek olanlar işte bunlardır."},{"n":110,"t":"Sonra yine unutma ki Rabbin, ağır işkence altında (kendilerine dayatılanı kabul ederek) fitneye düşürülmelerinin ardından hicret edenleri, (Allah yolunda) tüm çabasını harcayan ve direnenleri gözetecektir; evet, çünkü senin Rabbin, o (ağır acının) ardından elbette tarifsiz bağışıyla, eşsiz rahmetiyle muamele edecektir."},{"n":111,"t":"Gün gelecek, her can kendi derdine düşecek; ve herkes yapıp ettiklerinin karşılığını tastamam bulacak: zira (orada) hiç kimse zulme uğramayacaktır."},{"n":112,"t":"Allah (size) bir örnek verir: Güvenli ve (sakinlerini) her açıdan tatmin eden bir belde (düşünün ki), oranın ihtiyaç duyduğu rızık her yerden oraya akıyor. Buna karşın o (belde) Allah`ın nimetlerine nankörlük etti. Derken, yaptıkları sebebiyle Allah orayı çepeçevre içine alan açlık ve korku (belasıyla) kuşattı."},{"n":113,"t":"Ve doğrusu onlara kendilerinden bir elçi gelmişti; fakat onu yalanladılar. Ne var ki onlar zulümlerini sürdürürken azap onları yakalayıverdi."},{"n":114,"t":"Haydi, siz hem Allah`ın size verdiği rızıkların helal ve temiz olanlarından yiyin, hem de onun nimetlerine şükredin! Tabi ki, gerçekten yalnızca O`na kulluk etmek (istiyorsanız)..."},{"n":115,"t":"Allah, size ancak (kesilmesi mümkün iken kesilmeden veya kesilme yerine geçmeyecek herhangi bir sebeple) ölen hayvanın leşini, kanı, domuz etini ve Allah’tan başkası için kesilen (hayvanın etini) haram kıldı. Bununla birlikte kim başkasının hakkına tecavüz etmeden, konan sınırları çiğnemeden ve zaruret miktarını geçmemek kaydıyla, yemediği takdirde ölecek derecede mecbur kalır da bunlardan yerse, (günah işlemiş olmaz). Muhakkak ki Allah, çok bağışlayandır, hususî rahmet ve merhameti pek bol olandır."},{"n":116,"t":"Artık, dilleriyle yalan beyanda bulunup, üstelik uydurduğunuz yalanı (da) Allah`a isnat ederek \"Bu helaldir, bu da haramdır!\" demeyin! Çünkü uydurdukları yalanı Allah`a isnat edenler asla kurtuluşa eremezler."},{"n":117,"t":"(Bu dünyada) oyalayıcı kısa bir haz (duysalar da), (ahirette) onları can yakıcı bir ceza bekler."},{"n":118,"t":"Ve yalnızca Yahudileşen kimselere sana daha önce aktardığımız şeyleri yasaklamıştık; ama onlara zulmeden biz değildik, ne var ki onlar asıl kendi kendilerine zulmettiler."},{"n":119,"t":"Sonuç olarak şunu aklından çıkarma ki, Rabbin, bir cahillik ederek kötülük işleyen ama bunun ardından tevbe edip Allah`a yönelerek kendisini düzeltenden yana tavır koyar. Çünkü senin Rabbin, öylesi bir (tevbenin) ardından tarifsiz bir bağışlayıcı, eşsiz bir rahmet kaynağı olduğunu mutlaka (gösterecektir)."},{"n":120,"t":"Hiç şüphe yok ki İbrahim tüm güzellikleri kendinde toplamış başlı başına örnek bir önder, her türlü kötülükten yüz çevirip bütün varlığıyla Allah`a adanmış biriydi; fakat o, asla başkalarına ilahlık yakıştıran bir müşrik olmadı."},{"n":121,"t":"O, kendisini seçip dosdoğru bir yola yönelten (Allah`ın) nimetlerine hep şükretti."},{"n":122,"t":"Biz de bu dünyada ona iyi bir (makam) bahşettik; şu kesin ki o, ahirette de dürüst ve erdemliler arasında yer alacaktır."},{"n":123,"t":"Sonuçta (ey Peygamber), sana da şöyle vahyettik: \"Her türlü kötülükten yüz çeviren İbrahim`in inanç sistemine uy; zira o Allah`tan başkalarına ilahlık yakıştıranlardan değildi!\""},{"n":124,"t":"Cumartesi yasağı sadece, bu konuda (İbrahim`in inanç sisteminden) farklılaşıp kopmuş olan kimselerin aleyhine oluşturulmuş bir durumdu. Ama şu kesin ki, Rabbin Kıyamet Günü üzerinde sürekli çekişip durdukları bu konuda onlar arasında hüküm verecektir."},{"n":125,"t":"Rabbinin yoluna hikmetle ve güzel öğütle davet et; ve onlara (karşı) öyle bir mücadele yöntemi ortaya koy ki, o en güzeli, en etkilisi olsun! Çünkü senin Rabbin var ya: işte O kendi yolundan sapan kimseyi de, doğru yola yöneleni de en iyi bilendir."},{"n":126,"t":"İmdi siz, cezalandırdığınızda mutlaka sizin maruz kaldığınız miktarı aşmadan cezalandırınız; yok eğer sabrederseniz, bu, sabırda direnenler için daha hayırlıdır."},{"n":127,"t":"Ve sen de sabret ve (unutma ki) senin sabretmen yalnızca Allah sayesinde mümkündür! Ve onlardan yana üzülme! Hele onların çevirdikleri entrikalardan dolayı için hiç daralmasın!"},{"n":128,"t":"Çünkü Allah sorumluluk bilincine sahip olanlar ve iyilik ve erdemi hayat tarzı haline getirenlerle beraberdir."}],[{"n":1,"t":"Yarattıklarına benzemekten münezzeh, mutlak aşkın ve yüce O (Allah) ki, kulunu gecenin bir vaktinde Mescid-i Haram`dan çevresini bereketli kıldığımız Mescid-i Aksa`ya, ayetlerimizden bir kısmını gösterelim diye yürüttü: zira O, evet sadece O`dur her şeyi işitip gören."},{"n":2,"t":"Yine Biz, Musa`ya (da) kitabı vermiş ve onu İsrailoğulları için bir doğru yol haritası kılarak (demiştik ki): \"Benim dışımda, herhangi bir koruyucu otorite edineyim demeyin!"},{"n":3,"t":"Siz, ey Nuh`la birlikte (gemide) taşıdıklarımızın soyundan gelenler! Unutmayın ki o hep şükreden bir kuldu!\""},{"n":4,"t":"Ve İsrailoğullarına vahiy yoluyla (şunu) bildirdik: \"Mutlaka yeryüzünde iki kez bozgunculuk çıkartacak ve küstahça böbürlenip büyüklük taslayacaksınız!\""},{"n":5,"t":"İşte bu iki uyarıdan birincisinin vakti geldiğinde, sizin üzerinize şu Bizim (belalı) kullardan saldırı gücü çok yüksek olanları musallat ettik; öyle ki, bunlar köşe bucak her yeri arayıp taradılar: zira bu, sadece (böyle yapanlar için) konulmuş bir yasanın uygulanmasıydı."},{"n":6,"t":"Daha sonra tekrar onlara galip gelmenizi temin ettik; ve sizi hem mal, hem de evlatça destekleyip sayınızı artırarak (şu mesajı verdik):"},{"n":7,"t":"\"Eğer iyilik ederseniz yalnızca kendinize iyilik yapmış olursunuz, yok eğer kötülük ederseniz bunun da sonucuna katlanırsınız.\" Derken, sonuncu uyarının da vakti gelip çattığında (yeni düşmanlar gönderdik / göndereceğiz); ki sizler için yüzkarası olan öncekilerin girişi gibi, Mabed`e (destursuz) girip ele geçirecekleri her şeyi paramparça edip mahvetsinler."},{"n":8,"t":"Tabii ki Rabbinizin size rahmetiyle muamele etmesi umulabilir; ama eğer siz (günaha) dönerseniz, Biz de (cezaya) döneriz. Zira Biz cehennemi nankörleri çepeçevre kuşatan bir hisar kılmışızdır."},{"n":9,"t":"Hiç şüphe yok ki işte bu Kur`an, en doğru yola yöneltmekte, erdemli ve güzel davranış sergileyenleri, kesinlikle muhteşem bir karşılığın beklediğini müjdelemektedir;"},{"n":10,"t":"ve ahirette (yaptıklarından hesap vereceğine) inanmayan kimseler için, dehşet bir azap hazırladığımızı da..."},{"n":11,"t":"Ne ki insan, (sanki) hayır için yalvarıp yakarıyormuşçasına şer için yalvarıp yakarır; zira insan çok acelecidir."},{"n":12,"t":"Hem Biz geceyi ve gündüzü iki ayet kıldık. Baksanıza, gecenin ayetini gideriyor ve (onun yerine) gündüzün ayetini bir ışık kaynağı olarak getiriyoruz ki; hem Rabbinizin lutfundan (size düşeni) arayasınız, hem de (geçip giden) yılların sayısının ve (gelmesi kaçınılmaz olan) hesabın farkına varasınız. İşte Biz, (ibret almanız için gerekli olan) her şeyi açık ve net olarak önünüze koymuş bulunuyoruz."},{"n":13,"t":"Ve Biz, her bir insanın kaderini kendi çabasına bağlı kıldık. Nitekim Kıyamet Günü onun önüne, (dünyada yapıp ettiği) her şeyi kayıtlı bulacağı bir sicil koyacak (ve diyeceğiz ki):"},{"n":14,"t":"\"Oku sicilini! Bugün kendi hesabını görmek için sen sana yetersin!\""},{"n":15,"t":"Kim doğru yola yönelirse, iyi bilsin ki o sadece kendisi lehine yönelmiş olacaktır; kim de saparsa, unutmasın ki o da yalnızca kendi aleyhine sapmış olacaktır: zira hiç kimse bir başkasının sorumluluğunu taşımaz; üstelik Biz, bir elçi gönderinceye kadar asla (bir toplumu) azaba sürüklememişizdir."},{"n":16,"t":"Biz bir toplumun helakini dilediğimiz zaman (bilin ki süreç şöyle gelişmiştir: önce) o toplumun refah içinde şımarmış seçkinlerini yönetici yaparız; buna rağmen onlar orada kötülük işlemeyi sürdürürlerse, artık onlar aleyhindeki hüküm kesinleşir: bunun ardından Biz de orayı yerle bir ederiz."},{"n":17,"t":"Nitekim Biz Nuh`tan bu yana nice toplumları helak etmişizdir. Zira, günahkarlıkları yüzünden kullarıyla başa çıkmak için, her bir şeyden haberdar olup her bir şeyi gören Rabbin alasıyla yeter de artar bile!"},{"n":18,"t":"Her kim ki, hemen `şimdi ve burada`nın geçici hazlarını tercih ederse, Biz de onun payını orada hızlandırır, dilediğimiz kimseye istediğimiz kadar veriveririz; ne ki sonunda ona cehennemi tahsis ederiz (de), o oraya kınanmış ve gözden çıkarılmış biri olarak atılır."},{"n":19,"t":"Ve her kim de ahiret hayatını tercih eder, (karşılığını Allah`tan alacağına) inanarak orası için göstermesi gereken çabayı gösterirse, işte onların bu çabası karşılığını bulur."},{"n":20,"t":"Hepsine birden, -ötekilere de, berikilere de- senin Rabbinin lutfundan (bu dünyada zaten) ulaştırmaktayız: zira Rabbinin lutfu yalnız (bir kesimle) sınırlandırılamaz."},{"n":21,"t":"(Bu dünyada) onların bir kısmını, diğerlerine nasıl üstün kıldığımıza bir bak, ama ahiretin payı hem nicelik olarak çok daha büyük, hem de (nitelik olarak) çok daha üstün ve değerlidir."},{"n":22,"t":"(Ey insan!) Allah`la birlikte başka bir ilah edinme! Sonra kınanmış olarak bir köşeye atılıp orada bir başına kalakalırsın."},{"n":23,"t":"Zira senin Rabbin, başkasına değil yalnızca kendisine kulluk etmenizi emreder. Bir de ana babaya iyilik etmeyi... Eğer onlardan biri ya da ikisi senin yanındayken yaşlanırsa, sakın onlara \"Üf!\" bile deme ve onları azarlama! Aksine onlara gönül okşayıcı şeyler söyle!"},{"n":24,"t":"Dahası, o ikisine alçak gönüllü davranarak merhametle kol-kanat ger ve de ki: \"Rabbim, o ikisi beni küçüklüğümde sevgiyle görüp gözettikleri gibi, sen de onları merhametinle kolla!\""},{"n":25,"t":"(Ey insanlar!) Rabbiniz, içinizde olan biteni çok daha iyi bilir; yeter ki siz iyiliği özümseyenlerden olun: hiç aklınızdan çıkarmayın ki O, (hatada ısrar etmeyip) kendisine yönelenler için tarifsiz bir bağışlayıcıdır."},{"n":26,"t":"(Ey insan!) Yakınlık sahiplerine hakkını ver; düşküne ve yolda kalmışa da... Fakat sakın ola ki (elinde avucunda olanı) amaçsız bir biçimde saçıp savurma!"},{"n":27,"t":"Çünkü amaçsızca saçıp savuranlar, (çok geçmeden) Şeytanın kardeşleri olup çıkarlar: zira Şeytan Rabbine karşı pek nankör idi."},{"n":28,"t":"Ve eğer sen kendin, umut (kapın olan) Rabbin katından gelecek bir rahmet ve lutfu arama çabasında olduğun için (muhtaçları) geri çevirmek durumundaysan, en azından onlara gönül alıcı bir söz söyle."},{"n":29,"t":"Yine sen (ey insan), ne ellerini boynuna bağlayıp (cimrilik yap), ne de onları büsbütün açarak (saçıp savur); eğer böyle yaparsan, kınanmış olarak bir köşeye atılıp pişmanlık içinde kıvranırsın."},{"n":30,"t":"Elbet senin Rabbin (hak edenin) rızkını bollaştırmayı, (hak etmeyenin) rızkını da kısmayı diler; çünkü O kullarının her durumundan haberdardır, her şeyi tarifsiz görmektedir."},{"n":31,"t":"Şu halde, çocuklarınızı rızkınıza ortak olur endişesiyle öldürmeye kalkmayın! Onları da sizi de besleyecek olan Biziz: şüphesiz onları öldürmek büyük bir cürümdür."},{"n":32,"t":"Ve sakın zinaya yaklaşmayın! Çünkü o arsızca bir hayasızlık ve çirkin bir yoldur."},{"n":33,"t":"Yine haklı bir gerekçeye dayanmaksızın Allah`ın dokunulmaz kıldığı hiçbir cana kıymayın! Zira haksız yere canına kıyılan kim olursa olsun, işte onun velisine (eşdeğer bir ceza konusunda) yetki tanımışızdır; fakat o katl cezasında (belirlenen) sınırı aşmasın; şu da bir gerçek ki, zaten o yardıma mazhar olmuştur."},{"n":34,"t":"Yetimin malına da, -kendisi (ergenlik çağına erinceye kadar) yapacağınız en uygun ve olumlu tasarruflar dışında- yaklaşmayın. Yine, verdiğiniz her (meşru) söze sadık kalın! Şüphesiz söz veren herkes bundan dolayı hesaba çekilecektir."},{"n":35,"t":"Ve ölçtüğünüz zaman ölçüyü tam tutun! Tartıp değerlendirdiğinizde (ise) dosdoğru kıstas ile tartıp değerlendirin! Böylesi çok daha yararlı ve sonuç alma açısından çok daha güzeldir."},{"n":36,"t":"Ve bilmediğin bir şeyin peşinden gitme! Çünkü kulak, göz ve gönül; bütün bunlar (hesap günü) ondan dolayı sorguya çekilecektir."},{"n":37,"t":"Ve yeryüzünde çalım satarak dolaşma! Unutma ki sen ne yeri yarabilir, ne de dağlarla boy ölçüşebilirsin."},{"n":38,"t":"Bütün bunların asıl kötülüğü, Rabbinin katında hoş karşılanmamış olmalarıdır:"},{"n":39,"t":"bütün bunlar, Rabbinden sana vahyedilen amacı gerçekleştirme hususunda en isabetli hükümlerden bir bölümdür. (Ey İnsan!) Sakın Allah`la birlikte başka bir ilah edinme! Yoksa kınanmış ve dışlanmış biri olarak cehennemi boylarsın."},{"n":40,"t":"Ne yani, şimdi Rabbiniz sizin için oğullar seçip ayırırken, kendisine meleklerden kızlar edindi, öyle mi? Şu bir gerçek ki siz, pek dehşet bir söz söylüyorsunuz."},{"n":41,"t":"Doğrusu Biz bu hitapda, (hakikati) tüm boyutlarıyla ortaya koyduk ki düşünüp öğüt alabilsinler; fakat bu onların sadece nefretini artırdı."},{"n":42,"t":"De ki: \"Eğer iddia ettikleri gibi O`nunla birlikte başka ilahlar olmuş olsaydı, onlar da Otorite Sahibine (yakın olmak ya da O`na galip gelmek için) elbet bir yol bulmağa çabalarlardı.\""},{"n":43,"t":"Her noksandan beri, her şeyden yüce ve mutlak aşkın olan O, onların söylediklerinin de çok çok ötesinde sonsuzca yücelik, sonsuzca büyüklük sahibidir:"},{"n":44,"t":"Yedi gök ve yer ve onlarda yaşayan her bilinçli varlık O`nun sonsuz yüceliğini dillendirirler; daha da öte, (lisan-ı hal ile) onun ululuğunu övgüyle dile getirmeyen bir tek nesne dahi bulunmamaktadır; ve fakat siz onların ululayan dilini anlamamakta (ısrarcısınız); buna rağmen O sizi cezalandırmada hiç acele etmeyendir, eşsiz bir bağışlayıcıdır."},{"n":45,"t":"Hem ne zaman (onlara) Kur`an okusan, seninle ahirete inanmamakta ısrar eden o kimseler arasına görünmez bir perde çekeriz;"},{"n":46,"t":"(akleden) kalplerinin üzerine onu anlamalarını engelleyen bir kapak, kulaklarına ise bir tıkaç yerleştiririz. Bu yüzden sen ne zaman Kur`an (okuma anın)da Rabbini birleyerek ansan, nefretle gerisin geri dönüp uzaklaşırlar."},{"n":47,"t":"(Ey Muhammed!) Sana kulak verdiklerinde, aslında onların neye kulak kabarttıklarını ve kendi aralarında gizli kapaklı görüşmeleri sırasında o zalimlerin, \"Eğer (ona) uyarsanız yalnızca büyülenmiş bir adama uymuş olursunuz\" dediklerini Biz çok iyi biliyoruz."},{"n":48,"t":"Şunların seni neye benzettiklerine bir bak hele! Ve sonuçta öyle bir sapıtıyorlar ki, bir daha doğru yolu bulacak (muhakeme) gücünü asla kendilerinde bulamıyorlar."},{"n":49,"t":"Bir de tutmuş diyorlar ki: \"Ne yani, şimdi biz kemik yığınına dönüşüp oradan da toza toprağa karıştıktan sonra yepyeni bir yaratılışla tekrar diriltileceğiz, öyle mi?\""},{"n":50,"t":"De ki: \"İster taşa dönüşün, ister demire,"},{"n":51,"t":"ya da mahlukat içerisinde aklınıza gelebilecek (hayata) en uzak (başka) bir varlığa!..\" Bundan sonra kalkıp da \"Kimmiş bizi yeniden diriltecek olan?\" diye soracak olurlarsa, \"Sizi ilk defa yaratan Kimse!\" diye cevapla. Bunun üzerine, kafalarını (kinayeli kinayeli) sallayarak \"Peki, bu ne zaman gerçekleşecekmiş bakayım?\" diye sana soracak olurlarsa, de ki: \"Kim bilir (!) belki de çok yakında gerçekleşecektir:"},{"n":52,"t":"O sizi o gün çağıracak, derhal siz de (ister istemez) O`nu överek bu çağrıya uyacaksınız; üstelik (dünya hayatında) çok kısa bir süre oyalandığınızı kesinkes bileceksiniz!\""},{"n":53,"t":"İmdi söyle kullarıma: birbirlerine karşı sözü en güzel bir biçimde söylesinler; çünkü Şeytan aralarını açmak ister. Gerçek şu ki, Şeytan insanın apaçık düşmanıdır."},{"n":54,"t":"Rabbiniz kim ve ne olduğunuzu çok iyi bilmektedir; dilerse size rahmetiyle muamele eder, dilerse cezalandırır. Bunun içindir ki, Biz seni onlara inanç dayatan bir otorite olarak göndermedik."},{"n":55,"t":"Zira, göklerde ve yerde bulunan her varlığı Rabbin çok iyi bilmektedir; dahası Rabbin peygamberlerden her birine diğerinden farklı olarak üstün nitelikler vermiştir: Nitekim, Davud`a (hükümdarlıkla birlikte) hikmet yüklü sayfalar verdiğimizi (hatırlayın)."},{"n":56,"t":"De ki: \"O`nun dışında kendilerinde (tanrısal güç) vehmettiğiniz kimseleri çağırsanıza; (düş kırıklığıyla) göreceksiniz ki, sizden hiç bir zararı kaldırmaya ya da onu (yararlı bir şeyle) değiştirmeye güçleri yetmeyecektir.\""},{"n":57,"t":"Kaldı ki, onların kendilerine yalvarıp yakardıkları kimseler var ya; -(Allah`a) en yakın sandıkları hangileriyse- işte onlar bile Rablerine yakın olmak için var güçleriyle çaba gösterirler ve O`nun rahmetini dilenip cezasından da korkarlar: çünkü senin Rabbinin azabı, her daim kaçınılması gereken bir ceza olmuştur."},{"n":58,"t":"Ve (yoldan çıkmış) hiçbir toplum yoktur ki, Biz onun helakını Kıyamet Günü`nden önce kararlaştırmamış, ya da şiddetli bir azap ile cezalandırmamış olalım: Bu daha baştan kayıt altına alınmış ilahi yasa gereğidir."},{"n":59,"t":"Bizim mucizeler göndermemize yalnızca önceki toplumların onları yalanlamış olmaları engel oldu. Nitekim Semud`a (risaletin) görünür bir delili olarak dişi deveyi vermiştik, fakat temsil ettiği gerçeği inkar yoluyla ona zulmettiler; zaten Biz bu tür mucizevi delilleri, yalnızca korkutarak uyarma amacıyla göndeririz."},{"n":60,"t":"Hani (Ey Muhammed), Biz sana demiştik ki: \"(Tasalanma), senin rabbin insanları çepeçevre kuşatmıştır! Sana gösterdiğimiz o (malum) müşahedeyi ise, başka değil, insanlar için yalnızca bir imtihan aracı yaptık; tıpkı Kur`an`da geçen lanetlenmiş ağaçta olduğu gibi... İşte, onları (bu tür imtihanlarla) korkutarak uyarıyoruz, ne var ki (bu) onların sadece küstahça azgınlaşıp böbürlenmelerini artırıyor!\""},{"n":61,"t":"Meleklere: `Âdem’e secde ederek saygı gösterin` demiştik. İblis hariç hepsi secde ederek saygı gösterdi. İblis: `Çamurdan yarattığına mı secde ederek saygı göstereceğim?` dedi."},{"n":62,"t":"(İtirazına) şunu da ekledi: \"Bula bula şuncağızı mı buldun bana üstün tutacak? Eğer bana Kıyamet Günü`ne kadar izin verecek olursan, çok azı dışında onun soyunun ağzına gem vurup, tümünün ipini elime geçireceğim!\""},{"n":63,"t":"(Allah) buyurdu ki: \"Defol, git! Onlardan her kim seni izlerse, şu kesin ki, tümünüzü bekleyen bir ceza olarak cehennem, yaptıklarınızın mükemmel bir karşılığı olacaktır!"},{"n":64,"t":"Ve onlardan gücünün yettiklerini sesinle yoldan çıkar; atlarını ve adamlarını sal üzerlerine, servet ve evlat edinirken onlara ortak ol; dahası onlara vaadlerde bulun! -Nasıl olsa Şeytan`ın vaadi aldatmadan başka bir şey ifade etmez-"},{"n":65,"t":"Ama unutma ki, (gerçek) kullarım üzerinde senin etkin bir gücün olmayacaktır: zira senin Rabbin, (kullarını) koruyucu otorite olarak haydi haydi yeterlidir!\""},{"n":66,"t":"Rabbiniz... O`dur lutfu kereminde payınıza düşeni arayasınız diye sizin için denizde gemileri yüzdüren; yine, bitimsiz bir merhametle sizi kollayan da O`dur."},{"n":67,"t":"İmdi, siz denizde bir tehlikeyle karşılaştığınızda, yalvarıp yakardığınız herkes sizi yüzüstü bırakır da O bırakmaz; fakat O sizi kurtarıp karaya çıkardığı zaman (bu kez de) siz yüz çevirirsiniz: zira insanoğlu pek nankördür."},{"n":68,"t":"Şimdi, O`nun sizi (bulunduğunuz) kara parçasının bir kısmıyla birlikte yerin dibine geçirmesine, yahut, taşı toprağı üzerinize uçuran bir kasırga göndermesine dair kesin bir güvenceniz mi var? Sonunda, (bu halinizle) kendinize hiçbir koruyucu otorite bulamayacaksınız."},{"n":69,"t":"Ya da sizi bir defa daha denize döndürüp, üzerinize ortalığı kasıp kavuran bir fırtına göndererek nankörlüğünüze karşılık sizi boğmayacağına dair bir garantiniz mi var? Bunun ardından sizin adınıza Bize hesap soracak hiç kimse bulamayacaksınız."},{"n":70,"t":"Ama doğrusu Biz Ademoğluna kat kat ikram ederek onu üstün ve şerefli kıldık. Karada ve denizde onlara ulaşım imkanı sağladık. Temiz ve helal besinlerle onları rızıklandırdık ve onları yarattıklarımızın bir çoğundan üstün tuttuk."},{"n":71,"t":"Bir gün gelecek, bütün insanları, (eylemlerine) önderlik eden (tasavvur ve bilinç)leriyle huzurumuza çıkarıp (hesap soracağız); artık kimlerin karnesi sağ ellerine verilirse, işte onlar karnelerini (sevinç içinde) okuyacaklar ve onlara zerre kadar haksızlık edilmeyecek."},{"n":72,"t":"Ne ki, bu dünyada (kalp) gözü kör olan kimse ahirette de kör olacak; öyle ki, yolunu büsbütün kaybedecektir."},{"n":73,"t":"İşte o (tipler) eğer ellerinden gelse, sana vahyettiğimizin dışında Bizim adımıza birtakım şeyler tedarik edesin diye, seni dahi baştan çıkararak tuzağa düşürmeye kalkışırlar; seni de ancak bunu başarabildikleri zaman dost edinirler."},{"n":74,"t":"Fakat Biz eğer kalbini iman üzere perçinlememiş olsaydık, belki o zaman birazçık olsun onlara eğilim göstermen mümkün olabilirdi."},{"n":75,"t":"O zaman da sana, hayatın da ölümün de acısını kat kat tattırırdık; üstelik seni elimizden kurtaracak birini de bulamazdın."},{"n":76,"t":"Fakat (bunun imkansız olduğunu gören) berikiler, bu kez oradan çıkarmak için (senin) toprağında ısrarla seni taciz ve tedirgin etmeye çalışıyorlar. Ama (seni çıkardıkları) zaman, senin ardından onlar da pek fazla kalamayacaklar."},{"n":77,"t":"Elçilerimizden senden önce gönderdiğimiz kimselere uygulanan yöntem de buydu; ve sen Bizim uyguladığımız yöntemin (niteliğinde) bir farklılaşma bulamazsın."},{"n":78,"t":"Güneşin zirveyi aşıp (batıya) ağmasından gecenin karanlığının iyice çökmesine kadar (geçen zaman dilimlerinde) namazı hakkını vererek kıl; ve bir de sabah (namazı) okuyuşunu: unutma ki sabah okuyuşu, oldu olası (insanı her tür manevi) algıya açık hale getirir."},{"n":79,"t":"Ve gecenin bir vaktinde uykuna ara vererek, sana özgü bir armağan olarak namaz kıl; umulur ki Rabbin seni övgüye değer bir makama yüceltir!"},{"n":80,"t":"Ve de ki: \"Rabbim! Benim girdiğim her yere doğruluk ve dürüstlükle girmemi, çıktığım her yerden doğruluk ve dürüstlükle çıkmamı sağla; ve yüce katından beni (bu hususta başarılı) kılacak etkin bir güçle destekle."},{"n":81,"t":"Yine de ki: \"Hak geldi, batıl ise yıkılıp gitti; çünkü her batıl zaten yıkılıp gitmeye mahkumdur!\""},{"n":82,"t":"İşte Biz Kur`an`ı, ona inananlar için (iç dünyalarını onaran) bir şifa ve rahmet (eczanesi) olarak indirdik; ama o, zalimlerin yalnızca yıkımını artırıyor."},{"n":83,"t":"Zira ne zaman Biz insana nimet ihsan etmişsek, mesafe koydu ve (sorumluluklarından) yan çizdi; ne zaman da başına bir ziyan gelse, tuttu umutsuzluğa kapıldı."},{"n":84,"t":"De ki: \"Herkes kendi tasavvur ve aklının verdiği istikamet üzere eylemde bulunur; nasıl olsa Rabbiniz kimin yöneltildiği yolun daha doğru olduğunu çok iyi bilmektedir."},{"n":85,"t":"Sana ruh hakkında soruyorlar. De ki: \"Ruh Rabbimin (akıl sır ermez) işlerindendir ve size bu konuda çok sınırlı bir bilgi verilmiştir.\""},{"n":86,"t":"Ve eğer dilersek, kesinlikle sana vahyettiklerimizin tamamını gideririz. Ardından da Bize karşı sana kol-kanat gerecek bir koruyucu bulamazsın."},{"n":87,"t":"Neyse ki Rabbinin rahmeti sayesinde (bundan uzaksın). Unutma ki O`nun senin üzerindeki lutfu her daim büyük olmuştur."},{"n":88,"t":"De ki: \"Bütün görünen ve görünmeyen iradeli varlıklar bu Kur`an`ın bir benzerini ortaya koymak için bir araya toplansalar ve bu konuda birbirlerine var güçleriyle destek verseler, yine de onun bir benzerini ortaya koyamazlardı!\""},{"n":89,"t":"Doğrusu Biz bu Kur`an`da, (hakikati) insanlara her tür dolaylı anlatım tarzını kullanarak farklı açılardan açıklamışızdır. Buna rağmen insanların çoğunun yüz çevirmesi, kat be kat nankörlükten başka bir şey değildir."},{"n":90,"t":"Nitekim demişlerdi ki: \"(Ey Muhammed!) Bize yerden kaynak fışkırtmadıkça sana asla inanmayacağız."},{"n":91,"t":"Veya senin hurma ağaçlarıyla ve asmalarla dolu bir bahçen olmalı; dahası onların arasından gürül gürül ırmaklar çağlatmalısın."},{"n":92,"t":"Ya da sürekli iddia ettiğin gibi göğü başımızda paralamalı ve nihayet Allah`ı ve melekleri getirip karşımıza dikmelisin."},{"n":93,"t":"Veyahut da senin altından bir köşkün olmalı ya da semaya çıkmalısın; fakat semaya çıkman durumunda (dahi) oradan bize okuyacağımız bir kitap indirmedikçe yine de sana inanmayacağız.\" De ki: \"Kudret ve yüceliğinde sınır bulunmayan sadece Rabbimdir; ben, fani bir elçiden başka neyim ki?\""},{"n":94,"t":"İşte, kendilerine doğru yol bilgisi geldiği zaman insanları ona inanmaktan alıkoyan şey, sadece şöyle akıl yürütmeleriydi: \"Ne yani, şimdi Allah fani bir insanı mı elçi olarak gönderdi?\""},{"n":95,"t":"Onlara de ki: \"Eğer yeryüzünde salına salına dolaşanlar melekler olsaydı, elbet Biz de onlara elçi olarak gökten bir melek indirirdik.\""},{"n":96,"t":"De ki: \"Benimle sizin aranızda (bütün bu olan bitenlere) şahit olarak Allah yeter: Çünkü o kullarıyla ilgili her habere (daha kaynağında) vakıf olan, onların her halini bizzat görendir.\""},{"n":97,"t":"Nitekim, her kime Allah rehberlik etmişse işte odur doğru yola ulaşan; kimi de sapıklığa terk etmişse, artık böylelerini O`na karşı savunacak dostlar bulamazsın. Ve Biz Kıyamet Günü onları (dehşetten kararmış olan) yüzleri yerde, (hakikati) görmez, işitmez ve söylemez birileri olarak toplayacağız; varış yerleri, ne zaman yatışır gibi olsa kavurucu alevini tekrar kışkırtacağımız cehennem olacaktır."},{"n":98,"t":"Bu onların, Bizim ayetlerimizi inkarda ısrar etmelerinin ve \"Ne yani, şimdi biz kemiğe, toza-toprağa karıştıktan sonra yepyeni bir yaratılışla tekrar mı diriltileceğiz?\" demelerinin bir karşılığı olacak."},{"n":99,"t":"Gökleri ve yeri yaratan Allah`ın, onları kendi suretleri üzere yeniden yaratacak güce sahip olduğunu, yine onlar için bir gün sona ereceğinde hiçbir kuşku bulunmayan sınırlı bir süre takdir etmiş bulunduğunu nasıl görmezler? Fakat şu da var ki, zalimler, zirvesine ulaştıkları nankörlükten başka her (iyi) şeyden yüz çevirirler."},{"n":100,"t":"De ki: \"Eğer benim Rabbimin rahmet hazinelerine siz sahip olsaydınız, o zaman harcanıp tükenir korkusuyla kesinlikle sımsıkı sarılırdınız: zira insanoğlu oldum olası pek hasistir."},{"n":101,"t":"Doğrusu Biz Musa`ya, (Risaletinin) apaçık belgeleri olan dokuz mucizevi kanıt verdik. İstersen sor İsrailoğullarına; (Musa) onlara geldiğinde, Firavun ona \"Gerçek şu ki, ben senin sihirlenmiş biri olduğunu düşünüyorum!\" demişti."},{"n":102,"t":"(Musa) dedi ki: \"Doğrusu (muhatabına) basiret kazandıran bu (vahyi), göklerin ve yerin Rabbi dışında kimsenin indiremeyeceğini sen de çok iyi biliyorsun; ve ben de ey Firavun, senin artık iyice tükenip bittiğini düşünüyorum!\""},{"n":103,"t":"Nihayet (Firavun), onların kökünü yeryüzünden kazımaya karar verdi. Bunun üzerine Biz de onu ve onunla birlikte olan herkesi boğup attık."},{"n":104,"t":"Derken onların ardından İsrailoğullarına \"(Artık) yurd(unuz)a güvenlik içinde yerleşin!\" dedik; \"fakat ahirete ilişkin vaad gerçekleştiği zaman, sizi parçası olduğunuz (insanlıkla) bir araya getireceğimizi de (olup-bitmiş) bir iş gibi kesin bilin)!\""},{"n":105,"t":"Biz bu (vahyi) mutlak gerçeğe bir atıf olarak indirdik ve o da kaynağından indiği (gibi) asli gerçekliğiyle (muhatabına) ulaştı; nitekim Biz seni, sadece müjdeci ve uyarıcı olarak gönderdik."},{"n":106,"t":"Ayrıca onu sürekli okunan bir Kur`an kılmak için bölüm bölüm açıkladık (ki), üzerinde dura dura onu insanlara okuyasın; çünkü biz de onu, (hayata geçirsinler) diye dura dura, parça parça indirmiştik."},{"n":107,"t":"(Artık) de ki: \"Ona ister inanın, ister inanmayın!\" Gerçek şu ki, daha önceden bilgi ve bilginin amacını kavrama yeteneğiyle donatılmış olanlar, kendilerine (ayetlerimiz) okunduğu zaman, derhal yüzleri üzerine yere kapanırlar"},{"n":108,"t":"ve derler ki: “Kudret ve yüceliğine pâyân olmayan Rabbimizin şanı ne yücedir! İşte Rabbimizin sözü kesin olarak gerçekleşmiş bulunuyor!”;"},{"n":109,"t":"İşte onlar gözyaşları içinde yüzleri üzere böyle yere kapanıyorlar ve bu (duyarlılıkları) onların Allah`a olan saygılarını artırıyor."},{"n":110,"t":"De ki: \"İster Allah diye yalvarıp yakarın, ister Rahman diye: O`na hangi biriyle yalvarırsanız yalvarın, ama unutmayın ki en güzel nitelikler ve tüm mükemmellikler O`na mahsustur!\" İmdi (ey muhatap), sen de yalvarıp yakarırken ne sesini aşırı yükselt, ne de aşırı kıs; bu ikisi arasında dengeli bir yol tut;"},{"n":111,"t":"ve de ki: \"Övgülerin tamamı (kendisi için) çocuk edinmeyen, mutlak otoritesinde O`na ortak olacak hiçbir varlık bulunmayan, güçsüzlük ve düşkünlükten dolayı bir yar ve yardımcıya ihtiyaç duymayan Allah`a aittir!\" Nihayet, sınırsız büyüklüğünü anarak O`nun ululuğunu ikrar et!"}],[{"n":1,"t":"Hamd tümüyle kuluna ilahi mesajı indiren ve onda hiçbir çarpıklığa yer vermeyen Allah`a mahsustur."},{"n":2,"t":"(Aksine onu) dosdoğru ve dolambaçsız (kıldı) ki, (inkarcıları) kendi katından gelecek şiddetli bir cezayla uyarsın; yararlı ve erdemli davranan mü`minlere de kendilerini bekleyen güzel bir karşılığı müjdelesin:"},{"n":3,"t":"içinde ebedi kalacakları (bir karşılığı)..."},{"n":4,"t":"Bir de \"Allah çocuk edindi\" diyen kimseleri uyarsın…"},{"n":5,"t":"(Kaldı ki) ne onlar ne de ataları, bu konuda (sahih) bir bilgiye sahip değildirler; ağızlarından öylesine çıkmış pek dehşet bir söz bu: onlar bunu demekle sadece yalan söylemiş oluyorlar."},{"n":6,"t":"Hal böyleyken demek sen kalkıp, -bu hitaba inanmamaları durumunda- onların verdiği tepkiler üzerine kızıp kendini helake sürükleyeceksin."},{"n":7,"t":"Gerçekten de Biz yeryüzünde bulunan şeyleri, onlardan hangisinin daha güzel davranacağını sınayalım diye oraya (cazibe katan) birer süs unsuru kıldık;"},{"n":8,"t":"ama hiç şüphesiz yine Biz, (günü gelince) orada bulunan her şeyi kupkuru bir toprak haline çevirmeyi biliriz."},{"n":9,"t":"Yoksa sen mağara arkadaşlarının ve (onlar için yazılan) anıt kitabenin, bizim (bütün bu) ayetlerimizden daha mı ibret ve hayret verici olduğunu düşünüyorsun?"},{"n":10,"t":"Hani, zamanın birinde o gençler mağaraya sığınmışlar ve \"Rabbimiz!\" demişlerdi, \"Bize yüce katından bir rahmet bahşet ve bizi içine düştüğümüz şu durumdan dolayı doğru (sonuca) ulaştıracak bir bilinçle donat!\""},{"n":11,"t":"Bunun üzerine Biz de kulaklarına, yıllar boyu onları (dış dünyaya) kapatan bir (mühür) vurduk."},{"n":12,"t":"Sonra onları dirilttik ki, geçip giden süreci iki guruptan hangisinin (olayı hakikate uygun bir bakış açısıyla) değerlendirdiğini seçip ortaya çıkaralım."},{"n":13,"t":"Sana onların haberini, sahih bir amaca uygun olarak Biz aktaracağız: Şu bir gerçek ki, onlar Rablerine iman etmiş gençlerdi; ve Biz de onların doğru yolda olma bilincini artırmış"},{"n":14,"t":"ve yüreklerini (imanda) sabit kılmıştık. (Küfre) başkaldırdıkları zaman (aralarında) şöyle konuşmuşlardı: \"Bizim Rabbimiz, göklerin ve yerin Rabbidir! Asla O`nu bırakıp da, ilah diye başkalarına kulluk etmeyiz! Doğrusu eğer böyle yaparsak, asıl o zaman haktan uzaklaşıp haddi aşmış oluruz."},{"n":15,"t":"İşte bizim kavmimiz olacak şu güruh, tuttular O`ndan başkalarını ilah edindiler; oysa ki onların bu konuda ikna edici güçlü bir delil getirmeleri gerekmiyor muydu? Şu halde, kendi uydurduğu yalanı Allah`a isnat edenden daha zalim biri olabilir mi?"},{"n":16,"t":"İmdi, madem siz onlardan ve Allah dışında taptıkları her şeyden uzaklaştınız; o halde (şu) mağaraya sığının ki, Rabbiniz rahmetinden size bir pay ulaştırsın ve sizi (soylu) eyleminizden dolayı ihtiyaç duyduğunuz (maddi-manevi) donanıma sahip kılsın.\""},{"n":17,"t":"Ve onlar o mekanın geniş bir bölümünde bulunuyorlarken, sen, güneş doğarken onların mağarasını sağ tarafından teğet geçip gittiğini, batarken de sol tarafından teğet geçip gittiğini gözünde canlandırabilirsin: Allah`ın ayetlerinden biriydi bu. Allah kimi doğru yola yöneltirse, işte odur doğru yolu bulan, ama kimi de sapıklığa terk ederse, artık onun için ne bir dost, ne bir mürşit bulabilirsin."},{"n":18,"t":"Onlar (ölüm uykusuna) yattıkları halde sen onları uyanık sanırdın; dahası, Biz onları bir sağa bir sola döndürüp duruyorduk. Köpekleri ise, girişte ön ayaklarını yaymış öylece duruyordu: Eğer onların üzerine çıkagelseydin, kesinlikle dönüp ardına bakmadan kaçardın; zira bu (manzara)dan dolayı içini bir ürperti kaplardı."},{"n":19,"t":"İşte durum böyleyken, onları hayata döndürdük; nihayet kendi aralarında (ne olup bittiğini) sormaya başladılar. İçlerinden birinin \"Bu şekilde ne kadar kaldınız?\" diye sorması üzerine, diğerleri \"Bir gün ya da günün bir parçası kadar\" diye cevap verdiler. (O anda söze giren) daha başkaları ise şöyle dedi: \"Ne kadar kaldığınızı çok iyi bilen sadece Rabbinizdir. Şimdi (bunu bırakın) da, içinizden birini şu gümüş paralarla şehre gönderin; bir bakıversin, yiyeceklerden en temiz ve uygunu hangisiyse, size rızık olarak onu getirsin; fakat çok hassas davransın ve sakın sizin varlığınızı kimseye sezdirmesin!"},{"n":20,"t":"Çünkü eğer onlar sizin varlığınızı öğrenirlerse, ya sizi öldüresiye taşlarlar, ya da sizi (zorla) kendi inanç sistemlerine döndürürler; o takdirde ise bir daha asla ellerinden kurtulamazsınız.\""},{"n":21,"t":"Böylece, Allah`ın vaadinin hak olduğunu ve kıyametin geleceğinde şüphe olmadığını bilmeleri için (insanlara) onları buldurduk. Onların durumlarını aralarında tartışıyorlardı. (Bazıları): `Üzerlerine bir bina yapın` dediler. Rabbleri onları daha iyi bilir. Onların işlerine üstün gelenler de: `Mutlaka onların yanlarında bir mescid edineceğiz` dediler."},{"n":22,"t":"(Asırlar) sonra, bilinmeyen hakkında atıp tutma kabilinden, \"Onlar üç kişiydiler dördüncüleri köpekleriydi\" diyenler çıkacağı gibi, \"Beş kişiydiler altıncıları köpekleriydi\" diyenler de çıkacak; dahası \"Yedi kişiydiler sekizincileri köpekleriydi\" diyenler bile... De ki: \"Onların sayısını Rabbim daha iyi bilir! Onlar hakkında (gerçek) bilgiye sahip olanların sayısı çok azdır.\" (Sen, ey muhatap!) O halde artık onlar hakkında, olayın görünen boyutunun dışına taşan bir tartışmaya girme; yine onlar hakkında, (bilinmeyen hakkında atıp tutan) kimselere itibar edip de soru sorma!"},{"n":23,"t":"Ve hiç bir şey için, \"Ben bu işi yarın kesinlikle yaparım!\" deme!"},{"n":24,"t":"Ancak \"Allah dilerse (yapabilirim)\" de. Ve bunu unuttuğun zaman hemen Rabbini hatırla ve de ki: \"Umarım ki Rabbim beni bundan daha yakın (ve derinlikli) bir bilgi ve bilinç düzeyine eriştirir!\""},{"n":25,"t":"İmdi (kimileri) \"Onlar mağaralarında üç yüz yıl kaldılar\" (diye iddia ederlerken), bir (başkaları) da bu sayıya dokuz yıl daha ekledi."},{"n":26,"t":"De ki: \"Onların ne kadar kaldığını Allah daha iyi bilir: Göklerin ve yerin gizli bilgisi O`na açık ve ayandır: O ne muhteşem bir gören, ne muhteşem bir işitendir! Onların, O`ndan başka yakın bir dostları bulunmamaktadır; zira o egemenlik ve otoritesine kimseyi ortak etmez."},{"n":27,"t":"O halde, Rabbinin kitabından sana indirilenleri izle ve ilet! O`nun kelimelerini kimse değiştiremez: sen de O`ndan başka sığınacak birini bulamazsın."},{"n":28,"t":"Ve Rablerinin rızasını arzu ederek, sabah akşam O`na yalvarıp yakaran kimselerle birlikte sen de sabret! Dünya hayatının çekiciliğine aldanıp da sakın onları gözden çıkarma! Ve ayartıcı arzularına uyarak, işi gücü aşırı uçlarda dolaşmaya döktüğü için (akleden) kalbi kendisini zikrimize karşı duyarsızlaştıran kimselere de uyma!"},{"n":29,"t":"Ve de ki: \"Mutlak hakikate (atıf olan bu mesaj) Rabbimizdendir: Artık dileyen iman etsin, dileyen inkar etsin!\" İşin gerçeği Biz, (nefislerine kıyan) o zalimler için kendilerini kat kat sarıp sarmalayacak bir ateş hazırladık; öyle ki, onlar susayıp da su istediklerinde, suratlarını kavuran yanık yağ tortusu gibi bir su sunulur: ne berbat bir içecektir o ve ne fena bir makamdır orası..."},{"n":30,"t":"Ne ki, iman eden ve (o imana uygun) değerler üreten kimselere gelince: Şu kesin ki Biz, güzel bir eylem ortaya koyanın emeğini asla zayi etmeyiz."},{"n":31,"t":"İşte ayaklarının altından ırmakların çağladığı ve mutluluğun üretildiği merkezler olan cennetleri böyleleri için hazırladık. Orada onlara altın künyeler-bilezikler takılacak; dahası ince ve kalın ipekten sırmalı yeşil elbiseler giyerek oradaki tahtlarına kurulacaklar: Ne güzel bir ödül ve ne hoş bir makamdır orası..."},{"n":32,"t":"Onlara şu iki adam meselini örnek ver: Onlardan birine üzüm çubukları ekili iki bağ bağışlamıştık; onların çevresini hurma ağaçlarıyla donatmış, bir de o ikisinin arasında ekin bahşetmiştik."},{"n":33,"t":"Her iki bağ da kendilerinden beklenen ürünü veriyor, verimlilikte en küçük bir düşüş yaşanmıyordu: üstelik her iki bağın arasından bir de dere akıtmıştık."},{"n":34,"t":"Bu minval üzere (sahibi bol bol) ürün devşiriyordu. Derken, (bir gün) arkadaşıyla söyleşirken şöyle bir laf etti: \"Benim malım seninkinden çok, dahası nüfusça da senden üstünüm.\""},{"n":35,"t":"Böylece kendi kendisine en büyük kötülüğü yapmış olan o (adam bir gün) şunları diyerek bağına girdi: \"Bu bağın yok olacağını asla düşünemiyorum bile."},{"n":36,"t":"Hoş, ben Son Saat`in bir gün gerçekleşeceğini de düşünemiyorum ya! Fakat Rabbime döndürülecek olsam bile, sonuçta bundan daha iyisini bulacağımdan eminim.\""},{"n":37,"t":"Kendisiyle söyleştiği adam ona şu cevabı verdi: \"Şimdi sen kalkmış, seni tozdan topraktan ve ardından bir damlacık döl suyundan yaratan, sonra da seni yarattığı amacı gerçekleştirecek bir donanıma sahip kılarak adam eden Allah`ı inkar ediyorsun, öyle mi?"},{"n":38,"t":"Fakat bana gelince: şu kesin ki O benim her şeyimi borçlu olduğum birine hiç kimseyi ortak koşmam."},{"n":39,"t":"Oysa ki senin bağına girerken, (O`nun hayata müdahil olduğunu görüp): \"Bu, Allah`ın yaratıcı iradesiyle olur; (bu irade) ancak Allah sayesinde kullanılan bir güçle (gerçekleşir)\" diye düşünmen gerekmez miydi? Gördüğün gibi mal ve evlat bakımından senden daha güçsüzsem de,"},{"n":40,"t":"kim bilir belki Rabbim bana senin bağından daha yararlısını verir; seninkine de gökten bir afet indirir de ot bitmez çöle döndürür;"},{"n":41,"t":"ya da bir daha asla ulaşıp elde edemeyeceğin bir biçimde onun suyunu çeker.\""},{"n":42,"t":"Nihayet, berikinin bütün serveti mahvedildi; kökü göğe gelip tarumar olmuş o bağın karşısında durmuş, heba olan emeğine yanıp ellerini ovuşturarak diyordu ki: \"Ah n`olaydım, keşke Rabbime hiç kimseyi ortak koşmamış olaydım!\""},{"n":43,"t":"Artık onun Allah`tan gayrı kendisine destek çıkacak hiç kimsesi yoktu. Üstelik kendi başının çaresine bakacak durumda da değildi."},{"n":44,"t":"İşte orada -o anda dahi,- gerçek anlamda yar ve yardımcı olma gücü, sadece mutlak gerçeğin ta kendisi olan Allah`a aittir: O, hem hak edilen karşılığı vermede hem de nihai akıbeti belirlemede rakipsizdir."},{"n":45,"t":"Onlara dünya hayatını da örnek ver: Gökten indirdiğimiz bir su (düşünün); derken, o suyun karışmasıyla yer yüzünün bitki örtüsü boy gösterir; en sonunda bütün bunlar kuruyup, yerinde yellerin estiği çer çöpe döner: zira Allah her istediğini yapmaya kadir olandır."},{"n":46,"t":"Servet de, evlat da geçici dünya hayatının süsleridir; ürünü kalıcı olan güzel ve erdemli davranışlarsa, değer açısından Rabbinin katında daha hayırlı, ümit etmeye de daha layıktır."},{"n":47,"t":"Ve dağları yürütüp düzleyeceğimiz o gün, yeryüzünü düz ve çıplak görürsün; nitekim geride bir tek kişi bırakmadan onların tümünü toplayacağız."},{"n":48,"t":"Sonunda saf halinde Rabbinin huzuruna çıkarıldıklarında: \"İşte, nihayet sizi ilk yarattığımız günkü gibi Bize geldiniz; fakat (dünyadayken) sizin için böylesi bir buluşmayı gerçekleştiremeyeceğimizi düşünüyordunuz!\" (denilecek)."},{"n":49,"t":"Sonunda tutulan kayıt (önlerine) konulur; bunun üzerine suçluların orada gördüklerinden dolayı dehşetle irkildiklerini ve şöyle dediklerini görürsün: \"Vah başımıza gelenler! Bu nasıl bir kayıtmış ki küçük büyük dememiş, hepsini bir bir sayıp dökmüş!\" Ve yapıp ettikleri her şeyi (kayda alınmış olarak) önlerinde bulurlar; zira senin Rabbin hiç kimseye haksızlık etmez."},{"n":50,"t":"Hani bir zamanlar meleklere demiştik ki: \"Adem (oğlu) için emre amade olun!\" İblis hariç hepsi emre amade olmuştu; o görünmeyen varlıklardan biriydi; sonuçta Rabbinin emrine karşı geldi. Şimdi onun size olan düşmanlığına rağmen, Beni bırakıp da onu ve onun soyunu can dostlar mı edineceksiniz? Zalimler lehine yapılan bu takas ne berbat bir takastır!"},{"n":51,"t":"Ben onları ne göklerin ve yerin yaratılışına şahit kıldım, ne de kendi varoluşlarına; üstelik Ben, (bu) saptırıcı güruhu yardımcı edinmiş de değilim."},{"n":52,"t":"Ve o gün (Allah), \"Benim mutlak yetkilerime ortak olduğunu düşündüklerinizi çağırın!\" diye nida edecek. Bunun üzerine onları çağıracaklar. Fakat kendilerine cevap veren çıkmayacak: zira onların aralarına aşılmaz bir uçurum yerleştireceğiz."},{"n":53,"t":"Nihayet günahkarlar ateş görünce, kaçınılmaz olarak oraya gireceklerine akılları kesecek ve oradan kaçıp kurtulacak bir yol bulamayacaklar."},{"n":54,"t":"Doğrusu Biz bu Kur`an`da, (hakikati) insanlara her türlü dolaylı anlatım tarzını kullanarak açıkladık; zira insan, bütün varlık (içerisinde) tartışmaya en düşkün olandır."},{"n":55,"t":"Nitekim, kendilerine doğru yolu gösteren rehber geldiği zaman insanları iman etmekten ve Rablerine af dilemekten alıkoyan şey; ya öncekilerin başına gelenlerin kendi başlarına da gelmesini, ya da ahiret azabının gözlerinin önüne konulmasını istemekten başkası değildi."},{"n":56,"t":"Oysa ki Biz elçilerimizi (azap getirsinler) diye değil, yalnızca müjdeciler ve uyarıcılar olarak göndeririz. İnkarda direnenlerse, aslı faslı olmayan iddialarla hakikati geçersiz kılmanın kavgasını vererek ayetlerimizi ve uyarılarımızı alay konusu ederler."},{"n":57,"t":"Rabbinin ayetleri kendilerine ulaştırıldığı halde, onu görür görmez kendi işlediği (kötülükleri) de unutarak ondan yüz çeviren kimseden daha zalim biri olabilir mi? Şu kesin ki Biz, bu gibilerin (akleden) kalplerine onu anlamalarını engelleyen bir kapak, kulaklarına ise bir tıkaç yerleştiririz; dolayısıyla, onları doğru yola çağırsan da asla doğru yola gelemezler."},{"n":58,"t":"Yine de mutlak bağışlayıcı olan Rabbin sonsuz rahmetin de sahibidir. Eğer işledikleri (günahlar) yüzünden onları cezalandıracak olsaydı, azabı başlarına hemen musallat ederdi: Bilakis işte onlar için de, asla onun ötesine geçip kurtulamayacakları bir süre belirlenmiştir."},{"n":59,"t":"Nitekim işte o şehirlerin (harabeleri)!.. Zulümde ısrar edince onların tümünü yok ettik; ki Biz onların helakı için de (sınırlı) bir zaman takdir etmiştik."},{"n":60,"t":"Bir zaman da Musa yardımcısına demişti ki: \"İki denizin birleştiği yere varıncaya dek durmayacağım; isterse (oraya varmam) yıllarımı alsın.\""},{"n":61,"t":"Fakat iki (denizin) birleştiği yere vardıklarında, balıklarını unutmuşlardı bile; nitekim o (balık) da kendi yoluna koyulup denizde gözden kayboldu."},{"n":62,"t":"Ve bir miktar uzaklaştıklarında, (Musa) yardımcısına \"Azığımızı çıkar\" dedi, \"doğrusu bu yolculuk bizi hayli yormuştur.\""},{"n":63,"t":"\"Bak şu işe\" dedi o, \"hani dibinde dinlendiğimiz kaya vardı ya, işte orada balığı unutmuşum; bunu söylemeyi bana unutturan da Şeytan`dan başkası olamaz: ama o (balık), şaşırtıcı bir biçimde kendi yoluna koyulup gözden kaybolmuştu!\""},{"n":64,"t":"(Musa) dedi ki: \"İşte aradığımız da o(rası)ydı ya!\" Bunun üzerine hemen geri dönüp kendi izlerini takip ettiler."},{"n":65,"t":"Sonunda orada, kendisine katımızdan bir rahmete nail kılarak (ilmimizden) bir ilim öğrettiğimiz kullarımızdan birini buldular."},{"n":66,"t":"Musa ona dedi ki: \"Doğruyu bulma konusunda sana öğretilen bilgiden bana da öğretmen için seni izleyebilir miyim?\""},{"n":67,"t":"O, \"Korkarım ki sen benimle birlikteliğe sabredemezsin!\" dedi (ve ekledi):"},{"n":68,"t":"\"Kaldı ki sen, tecrübî bilgi kapsamına tümüyle girmeyen şeye nasıl (ve neden) katlanasın ki?\""},{"n":69,"t":"(Musa) \"İnşaallah beni dirençli biri olarak bulacaksın!\" dedi ve ekledi: \"Ben senin hiçbir emrine karşı gelmeyeceğim.\""},{"n":70,"t":"O \"Tamam\" dedi; \"eğer beni izleyeceksen, olan bitenler hakkında seni bilgilendirinceye kadar bana hiçbir şey sorma!\""},{"n":71,"t":"Birlikte yola koyuldular (ve) nihayet bir gemiye bindiler. O, gemide bir delik açtı. (Musa) dedi ki: \"Yolcuları boğmak için mi onu deldin? Doğrusu, çok tehlikeli bir şey yaptın!\""},{"n":72,"t":"O dedi ki: \"Ben sana dememiş miydim `Sen benimle birlikteliğe sabredemezsin!` diye?\""},{"n":73,"t":"(Musa) \"Bir anlığına boş bulundum diye beni azarlama ve beni yaptığım bu yanlıştan dolayı köşeye sıkıştırma!\" dedi."},{"n":74,"t":"Tekrar yola koyuldular; en sonunda bir delikanlıya rastladılar; derken, o (alim kişi) onu öldürüverdi. (Musa) \"Ne, sen bir cana karşılık olmaksızın masum bir cana kıydın, öyle mi?\" dedi; \"Doğrusu sen çok büyük bir yasağı çiğnedin!\""},{"n":75,"t":"O (kişi) \"Ben sana dememiş miydim\" dedi; \"sen benimle birlikteliğe asla katlanamazsın diye?!\""},{"n":76,"t":"(Musa) \"Bundan sonra eğer sana herhangi bir şey soracak olursam artık benimle arkadaşlık yapma; zaten benden yeterince özür işittin.\""},{"n":77,"t":"Bunun ardından yeniden yola koyuldular; nihayet bir kasabanın sakinleriyle karşılaştılar; onlardan yiyecek bir şeyler istediler, fakat onlar bu ikisine konukseverlik göstermediler. Hal böyleyken, orada yıkılmak üzere olan bir duvar buldular; ve o (kişi), duvarı onarıverdi. (Musa bunu görünce) \"Eğer isteseydin, buna bedel olarak bir ücret alabilirdin\" dedi."},{"n":78,"t":"O (kişi) \"İşte böylece seninle yol ayrımına gelmiş bulunuyoruz\" dedi; \"şimdi sana, hakkında bir türlü sabır gösteremediğin olayların arkasında yatan gerçeği bir bir açıklayacağım:"},{"n":79,"t":"\"Gemiden başlayalım: O gemi, geçimini denizden sağlayan yoksullara aitti. Hal böyleyken onu hasarlı hale getirmek istedim, çünkü onların peşinde her gemiye zorla el koyan bir yönetici bulunuyordu.\""},{"n":80,"t":"\"Gelelim delikanlıya: Onun ebeveyni imanlı kimselerdi; fakat biz onun azgınlık ve sapkınlıkla (ebeveynini) derin acılara boğacağına dair kaygı verici bir bilgiye sahiptik."},{"n":81,"t":"İşte bu yüzden istedik ki, Rableri onun yerine o ana-babaya karakter temizliği açısından ondan daha hayırlısını ve daha merhametlisini versin.\""},{"n":82,"t":"\"Ve duvara gelince: Duvar o şehirde yaşayan iki yetime aitti ve altında da onlara ait bir hazine gömülüydü. O ikisinin erdemli bir babası vardı; senin Rabbin ise, onlar erişkin birer insan olunca hazinelerini çıkarmalarını-Rabbinden bir rahmet olarak- diledi."},{"n":83,"t":"Bir de sana Zülkarneyn hakkında soruyorlar; de ki: \"Size ona ilişkin birtakım anı(lar) nakledeyim.\""},{"n":84,"t":"Evet, onun (iktidarı) için yeryüzünde uygun bir zemin hazırladık ve ona eşyanın yasalarıyla uyumlu araçların (bilgisini) bahşettik;"},{"n":85,"t":"o da kendisini (amacına) ulaştıracak bir araca başvurdu."},{"n":86,"t":"Nihayet güneşin battığı yere ulaşınca, orada kara balçığa (benzer) bir su gözesinde (güneşi) batar buldu; ve orada yerleşik bir topluluğa rastladı. Biz \"Ey Zülkarneyn!\" dedik, \"(Zulmederek) azab da çektirebilirsin, onlar hakkında (adil davranarak) güzel bir yönetim de benimseyebilirsin;"},{"n":87,"t":"(fakat)\" diye ekledi (Rabbi); \"kim zulmederse, iyi bilsin ki o (bu dünyada) günü gelince azabımıza mahkum olacaktır; en sonunda Rabbine döndürülecek; ve (Allah ahirette) onu da görülmemiş bir azaba uğratacaktır."},{"n":88,"t":"Ama kim de iman eder ve erdemli davranırsa, işte onu da karşılık olarak güzel bir akıbet beklemektedir; zaten Biz ona talimatlarımızdan kolay olanları buyuracağız."},{"n":89,"t":"Sonra o, yeni (amacına) ulaştıracak bir araca yine başvurdu."},{"n":90,"t":"En sonunda güneşin doğduğu yere ulaştı; onu kendileri için güneş ışığından gayrı bir örtü takdir etmediğimiz bir topluluk üzerine doğar halde buldu:"},{"n":91,"t":"onların yaşam tarzı da işte böyleydi; fakat doğrusu Biz, onun sahip olduğu tasavvuru derin bir bilgiyle kuşatmışızdır."},{"n":92,"t":"Yeniden kendisini (amacına) ulaştıracak bir araca başvurdu."},{"n":93,"t":"Nihayet iki set arasına ulaştığı zaman, onların arasında yaşayan bir topluluğa rastladı; konuştuğu dilden pek anlamıyorlardı."},{"n":94,"t":"\"Ey Zülkarneyn!\" dediler, \"Ye`cüc ve Me`cüc ülkede bozgunculuk yapıyor; derhal onlarla bizim aramıza bir set yapman karşılığında, sana bir bedel ödemeye ne dersin?\""},{"n":95,"t":"Şöyle cevap verdi: \"Rabbimin bu konuda bana verdiği imkan daha değerlidir; haydi sizler bana iş gücüyle yardımcı olun da, sizinle onların arasına bir set yapayım:"},{"n":96,"t":"(şimdi) bana demir plakalar getirin!\" Nihayet iki dik yamaç arasındaki (boşluk) doldurulup düz hale gelince onlara \"Körükleyin!\" dedi. Sonunda demir akkor halini alınca, \"Onun üzerine dökmek için bana ergimiş bakır getirin!\" dedi."},{"n":97,"t":"Evet, artık onların (düşmanları) ne onu aşabilirlerdi, ne de onda bir delik ve gedik açabilirlerdi."},{"n":98,"t":"(Zülkarneyn) dedi ki: \"Bu Rabbimin bir rahmetidir. Rabbimin vaat ettiği zaman geldiğinde, onu yerle bir edecektir: zira Rabbimin vaadi mutlaka gerçekleşir."},{"n":99,"t":"O gün geldiğinde, Biz onları birbirini kıran dalgalar (gibi) çalkalanmaya terkederiz. Nihayet sur borusu çalınır; sonunda hepsini bir araya toplarız."},{"n":100,"t":"İşte o gün kafirlere cehennemi (reddedemeyecekleri bir biçimde) arz ederiz."},{"n":101,"t":"Onlar öyle kimselerdi ki; beni hatırlatan (her şeye) karşı gözlerine bir perde çekilmişti, üstelik onlar işitmeye de yanaşmıyorlardı."},{"n":102,"t":"İnkarda ısrar eden bu kimseler benim kullarımı, benden bağımsız olarak, kendilerine kayırıcı veli edineceklerini mi sandılar? Şüphesiz Biz cehennemi kafirler için bir konukevi(!) olarak hazırladık."},{"n":103,"t":"De ki: \"Eylem olarak en büyük kayba uğrayacak olanı size haber verelim mi?\""},{"n":104,"t":"\"Bunlar, dünya hayatında tüm yapıp ettikleri (istikametten) sapmış olan kimselerdir: oysa ki bu tipler, kendilerinin güzel ve erdemli işler yaptığını sanmaktadırlar."},{"n":105,"t":"Bunlar, Rablerinin ayetlerini ve O`na kavuşmayı ısrarla inkar eden kimselerdir: Bu yüzden onların tüm yapıp ettikleri boşa gitmiştir; çünkü onlara Kıyamet Günü hiç kıymet vermeyeceğiz."},{"n":106,"t":"İşte onların cezası, inkarda direndikleri, ayetlerimi ve elçilerimi alaya aldıkları için cehennem olacaktır."},{"n":107,"t":"Ne var ki imanda sabreden ve ıslah edici davranış sergileyenlere gelince: onların buyur edileceği konukevi en görkemli cennetler olacaktır:"},{"n":108,"t":"Orada sürekli kalacaklar; oradan asla ayrılmak istemeyecekler."},{"n":109,"t":"De ki: \"Eğer Rabbimin sözlerini yazmak için denizler mürekkep olsa, hatta onun bir mislini de üzerine ilave etmiş olsak, yine de Rabbimin kelimeleri tükenmeden denizler tükenirdi.\""},{"n":110,"t":"De ki: \"Elbet ben de sizin gibi ölümlü bir insanım: Bana ilahınızın bir tek ilah olduğu vahyolunuyor. Artık kim Rabbine kavuşmayı umuyorsa, işte o Allah`ı razı eden imanına layık işler yapsın ve Rabbine kulluk ederken hiç kimseyi O`na ortak koşmasın!\""}],[{"n":1,"t":"Kâf-Hâ-Yâ-‘Ayn-Sad!"},{"n":2,"t":"Kulu Zekeriyya`ya, Rabbinin rahmetinin anısına..."},{"n":3,"t":"Hani o Rabbine (içinin) ta derinliklerinden seslenerek"},{"n":4,"t":"şöyle yalvarmıştı: \"Rabbim! Benden (iş) geçti, kemiklerim eridi, başa ak düştü; ama (ey) Rabbim, sana dua edip de eli boş kaldığım hiç olmadı."},{"n":5,"t":"Ve gerçek şu ki ben, benden sonra yakınlarımın (yerimi doldurabileceğinden) kaygı duyuyorum; üstelik kadınım da kısır: öyleyse, bana kendi katından yerimi dolduracak ehil bir takipçi ver;"},{"n":6,"t":"hem bana, hem Yakup oğullarına varis olsun; ve Sen de Rabbim, onu razı olacağın biri kıl!\""},{"n":7,"t":"(Melekler seslendiler): \"Ey Zekeriyya! İşte bizler sana adı Yahya olan bir oğlan çocuğu müjdeliyoruz! (Allah buyuruyor ki): \"Daha önce hiç kimseyi ona adaş kılmadık\"."},{"n":8,"t":"(Zekeriyya) \"Rabbim\" dedi, \"Nasıl olur da benim bir oğlum olabilir; çünkü eşim kısır, ben ise yaşlılıktan dolayı gücü tükenmiş biriyim!\""},{"n":9,"t":"(Melek): \"Öyledir (ama)\" dedi, \"Rabbin diyor ki: \"Bu benim için kolaydır; zira daha önce seni de Ben yaratmıştım, oysa ki sen hiçbir şey değildin!\""},{"n":10,"t":"(Zekeriyya: \"Rabbim!\" dedi, \"Bana bir işaret tayin et!\" (Melek) \"Senin işaretin tastamam üç gün insanlarla konuşamamandır."},{"n":11,"t":"Derken o, mabetteki inziva hücresinden çıkarak onlara; \"Sabah akşam Rabbinizin şanını (ibadetle) yüceltmeye devam edin!\" diye işaret etti."},{"n":12,"t":"(Yahya doğup büyüdüğünde ise) \"Ey Yahya! İlahi hükümlere sımsıkı sarıl!\" (diye öğüt verdi). Zira Biz ona, daha çocukluğunda derin ve kapsamlı bir muhakeme yeteneği vermiştik."},{"n":13,"t":"Ve kendi katımızdan ince ruhlu bir sevecenlik ve kendini geliştirme yeteneği bahşetmiştik; dahası o, sorumluluk sahibi biriydi;"},{"n":14,"t":"ana-babasına karşı da oldukça iyi davranırdı; nitekim o hiçbir zaman isyankar bir zorba olmadı."},{"n":15,"t":"İşte bu yüzden o, doğduğu gün ilahi güvence ve esenlik kapsamındaydı; öleceği ve tekrar dirilip kalkacağı gün de (öyle olacaktır)."},{"n":16,"t":"Bu kitapta Meryem`i de gündeme taşı! Hani o ailesinden ayrılarak doğu yönünde bir yere çekilmişti."},{"n":17,"t":"Olabildiğince kendini onlardan uzak tutup sakınıyordu; hal böyleyken ona vahiy meleğimizi gönderdik; öyle ki, o ona eli yüzü düzgün bir insan suretinde göründü."},{"n":18,"t":"(Meryem): \"Senden, O sınırsız merhamet sahibinin koruyuculuğuna sığınırım!\" dedi, \"Tabi ki eğer O`na saygı duyup sakınıyorsan!\""},{"n":19,"t":"(Melek): \"Ben sadece Rabbinin elçisiyim, sana pırıl pırıl bir oğlan çocuğu armağan etmek için buradayım!\" dedi."},{"n":20,"t":"(Meryem): \"Nasıl benim bir oğlum olabilir ki?\" dedi; \"Bana hiçbir erkek eli değmedi, üstelik ben iffetsiz bir kadın da değilim!\""},{"n":21,"t":"(Melek): \"Orası öyledir (ama)\" dedi, \"Rabbin diyor ki Bu benim için çok kolaydır; üstelik Biz onu insanlar için (canlı) bir ayet ve katımızdan bir rahmet kılacağız; zaten bu iş artık gerçekleşmiş bulunmaktadır.\""},{"n":22,"t":"İşte böylece (Meryem) ona hamile kaldı; bundan dolayı da, (insanların gözünden) uzak, kuytu bir köşeye çekildi."},{"n":23,"t":"Ve doğum sancısı (tutunacak bir dal arayan Meryem`i) hurma ağacının gövdesine doğru sürüklerken diyordu ki: \"N`olaydım, keşke bundan önce öleydim de unutulup gidenlerden olaydım!\""},{"n":24,"t":"Bunun ardından o (hurma ağacının) alt tarafından ona hitaben bir ses geldi: \"Sakın üzülme! İşte, Rabbin senin (rahminde) olanı şerefli kılmıştır;"},{"n":25,"t":"haydi, hurma dalını kendine doğru çekerek silkele, üstüne taze ve olgun hurmalar dökülsün;"},{"n":26,"t":"sonra da ye, iç, gözün aydın olsun! Ve eğer insanlardan herhangi birine rastlarsan, o zaman da (işaret yoluyla) de ki: \"Ben O Sınırsız merhamet sahibine oruç adadım: dolayısıyla bu gün insanlardan hiç kimseyle konuşmayacağım!\""},{"n":27,"t":"Nihayet, onu alarak kavminin yanına döndü. \"Ey Meryem!\" dediler, \"Doğrusu sen dehşet bir iş işlemişsin!"},{"n":28,"t":"Ey Harun (soyu)nun kız kardeşi! Senin baban kötü bir adam değildi, annen de iffetsiz bir kadın değildi!\""},{"n":29,"t":"Bunun üzerine (Meryem) çocuğa işaret etti. Onlar; \"Biz, daha dünkü bir beşik bebesiyle nasıl muhatap oluruz!?\" dediler."},{"n":30,"t":"(İsa) dedi ki: \"Ben Allah`ın kuluyum: O bana ilahi vahyi ulaştırdı ve beni peygamber tayin etti;"},{"n":31,"t":"nerede bulunursam bulunayım beni kutlu kıldı; ve bana hayatta olduğum sürece ibadeti diriltmeyi ve arınmak için verilmesi gerekeni vermeyi emretti;"},{"n":32,"t":"bir de anama iyi davranmayı... Fakat beni azgın bir zorba kılmadı."},{"n":33,"t":"Nitekim doğduğum gün tam bir ilahi güvence kapsamındaydım, öleceğim ve yeniden hayata döndüreleceğim gün de (öyle olacaktır)."},{"n":34,"t":"İşte budur Meryem oğlu İsa; çekişip durdukları konuda söylenecek tek gerçek söz de (budur)!"},{"n":35,"t":"Bir çocuk edinmek Allah`a asla yakıştırılamaz; O mutlak aşkın ve yüce olandır: O bir şeyin olmasını dilediği zaman O`nun sadece \"Ol!\" demesi yeterlidir: artık o şey, hemen oluş sürecine girecektir."},{"n":36,"t":"Ve (İsa`nın tek dediği şudur): \"Hiç şüphe yok ki benim de sizin de Rabbiniz Allah`tır. Şu halde yalnız O`na kulluk edin: budur dosdoğru yol!\""},{"n":37,"t":"Buna rağmen mezhepler kendi aralarında ayrılığa düştüler. O halde, büyük bir günün sorgusunda (yaşayacaklarından) dolayı, inkarda direnen o kimselerin vay hallerine!"},{"n":38,"t":"Bize gelecekleri o günde neler işitip neler görecekler (bir bilsen)! Fakat zalimler, o gün aşikar bir biçimde yoldan sapmış bulunacaklar."},{"n":39,"t":"O halde, her şeyin hükmünün kesinleştiği an olan o derin pişmanlık günü konusunda onları uyar, zira onlar gaflet içindedirler; dahası onlar (dirileceklerine) hala inanmış değiller."},{"n":40,"t":"Ama bakın; (o gün) yeryüzü ve onun üzerinde yaşayan herkes yok olacak, geriye tek Biz kalacağız: nihayet onların tümü Bize dönecekler."},{"n":41,"t":"Bu kitapta İbrahim`i de gündeme taşı! Hakikaten o doğruluk ve dürüstlük abidesiydi, (yani) bir peygamberdi."},{"n":42,"t":"Hani o babasına \"Ey babacığım!\" demişti, \"Niçin işitmeyen, görmeyen ve senden hiçbir bir zararı def edemeyen şeylere kulluk ediyorsun?\""},{"n":43,"t":"\"Ey babacığım! İnan ki bana, sana ulaşmamış olan hakikat bilgisinden bir pay ulaşmış bulunuyor; öyleyse bana uy ki, seni dosdoğru bir yola yönlendireyim!\""},{"n":44,"t":"\"Ey babacığım! Şeytan`a kulluk etme! Hatırla ki Şeytan, O rahmet kaynağına isyan eden biriydi\""},{"n":45,"t":"\"Ey babacığım! O rahmet kaynağından gelecek bir azabın sana dokunmasından endişe ediyorum; işte o zaman Şeytan`ın bir dostu da sen olmuş olursun!\""},{"n":46,"t":"(Babası): \"Ey İbrahim! Yoksa sen benim ilahlarımdan yüz mü çeviriyorsun?\" dedi, \"Eğer buna bir son vermezsen, yemin olsun ki seni öldüresiye taşa tutarım! Şimdi gözümün önünden kaybol bakayım!\""},{"n":47,"t":"(İbrahim): \"Sen sağlıcakla kal!\" dedi, \"Seni bağışlaması için Rabbime yalvaracağım; çünkü O, bana karşı oldukça lütufkardır!"},{"n":48,"t":"Artık hem sizden, hem de sizin Allah`ı bırakıp da yalvarıp yakardıklarınızdan uzaklaşacağım; ve (sizin için) Rabbime yalvarmayı sürdüreceğim; umarım, Rabbime duamdan dolayı mahrum olmam."},{"n":49,"t":"En sonunda onlardan ve onların Allah`ı bırakıp da taptıklarından uzaklaşınca, Biz ona İshak ve Yakub`u armağan ettik ve onların her birine de peygamberlik verdik;"},{"n":50,"t":"dahası onlara rahmetimizi bahşettik; nihayet onları doğruluğun ve hakikatin yüce dili yaptık."},{"n":51,"t":"Bu kitapta Musa`yı da gündeme taşı! Gerçekten o da müstesna ve seçkin biriydi; o da vahiy yoluyla haber alan elçilerdendi."},{"n":52,"t":"Hani, ona Tûr (Sina) Dağı`nın sağ tarafından nida etmiş ve onu bir özge söyleşi için vahyimize yaklaştırmıştık."},{"n":53,"t":"ve ona rahmetimizin bir nişanesi olsun için, kardeşi Harun`u peygamber kılarak (yardımcı) yapmıştık."},{"n":54,"t":"Bu kitapta İsmail`i de gündeme taşı! Şu bir gerçek ki, o da sözü özü doğru biriydi; ve bir haberci, bir peygamberdi."},{"n":55,"t":"Ve yakınlarına Allah davasına destek vermeyi ve arınmak için ödenmesi gereken bedeli ödemeyi emrederdi; ve o da Rabbi katında hatırı sayılan biriydi."},{"n":56,"t":"Bu kitapta İdris`i de gündeme taşı! Elbet o da doğruluk ve dürüstlük abidesiydi, (yani) bir peygamberdi."},{"n":57,"t":"Ve biz ona da yüce bir konum bahşetmiştik."},{"n":58,"t":"İşte bütün bunlar, Allah`ın kendilerine nimet verdiği peygamberlerden (sadece) bir kısmı; (yani) Adem`in neslinden, Nuh`la birlikte taşıdıklarımızın neslinden ve İbrahim ve İsrail`in neslinden olup, doğru yolu gösterdiğimiz ve seçtiğimiz kimselerden bazılarıdır: ne zaman O rahmet kaynağının ayetleri kendilerine okunsa (hepsi de) gözyaşları içinde yere kapanarak (teslimiyetlerini sunmuşlardır)."},{"n":59,"t":"Derken onların ardından öyle bir kuşak geldi ki, ibadetin içini boşalttılar ve dünyevi zevklerin peşine düştüler; işte bu yüzden gelecekte olan derin bir düş kırıklığı yaşayacaklar."},{"n":60,"t":"Ancak hatadan dönen, Allah`a iman eden ve salih amel işleyenler müstesna. İşte bunlar cennete girecekler ve en ufak bir haksızlığa uğratılmayacaklar."},{"n":61,"t":"O rahmet kaynağının kullarına söz verdiği, insanın kavrama kapasitesini aşan bir gerçeklik olan mutlak mutluluk ve güzelliğin merkezi cennetler (onların olacak): ve her halükarda O`nun sözü yerini bulacaktır."},{"n":62,"t":"Orada mutluluk tebriği dışında asla boş bir söz işitmeyecekler; ve onlar orada sabah akşam rızıklandırılacaklar."},{"n":63,"t":"Sorumluluk bilincine ermiş olanları mirasçı kılacağımız cennet işte budur."},{"n":64,"t":"VE (melekler der ki): “Biz yalnızca Rabbinin emriyle ineriz: Hem bize açık olup bilebildiğimiz, hem de bizden gizli olup bilemediğimiz ya da bu iki durum arasında bulunan her şeyin sahibi O’dur: ve senin Rabbin asla unutkan değildir."},{"n":65,"t":"O, göklerin, yerin ve bunlar arasındakilerin Rabbidir: O halde yalnız O`na kulluk et ve O`na kulluk ederken dirençli ve sebatlı ol! Hem, adı O`nunla birlikte anılmaya değer başka biri mi var?"},{"n":66,"t":"Buna karşın insan kalkıp \"Ne yani\" der, \"ölümümün ardından gün gelip tekrar mi diriltileceğim?\""},{"n":67,"t":"Peki ama, insan hatırlamaz mı ki hiçbir şey değilken kendisini de Biz yaratmıştık?"},{"n":68,"t":"Madem öyle, Rabbine andolsun ki onları Şeytanlarla bir araya toplayacağız; ardından cehennemin etrafında perişan bir halde getirteceğiz;"},{"n":69,"t":"sonra her topluluktan, O rahmet kaynağına karşı kimin daha azgın ve sapkın olduğunu seçip ortaya çıkaracağız;"},{"n":70,"t":"hem Biz, kimin cehenneme yaslanmayı en çok hak ettiğini elbet daha iyi biliriz."},{"n":71,"t":"Başka yolu yok; (siz ey cehennemlikler) mutlaka her biriniz oraya varacaksınız: Bu Rabbinin katında kesinleşmiş bir hükümdür."},{"n":72,"t":"En sonunda, (hayatta) sorumluluk bilinciyle hareket etmiş olanları (oraya düşmekten) kurtaracağız; fakat kendilerine kötülük edenleri orada perişan bir halde bırakacağız."},{"n":73,"t":"Ne ki, hakikatin apaçık belgeleri olan ayetlerimiz ne zaman kendilerine ulaştırılsa, küfürde ısrar edenler imanda sebat edenlere şöyle sorarlar: \"Bu iki guruptan hangisi konumca daha üstün ve hangisi daha hatırlı bir çevreye mensupmuş?!"},{"n":74,"t":"Halbuki Biz onlardan önce de nice uygarlıkları helake uğrattık; onlar varlık ve görkem açısından daha öndeydiler."},{"n":75,"t":"De ki: \"Sapıklığın içine dalan kim olursa olsun; O rahmet kaynağı onun süresini uzattıkça uzatsın! Taki kendilerinin tehdit edildikleri şeyi -ister (bu dünya) azabı olsun, ister Son Saat olsun- görünceye kadar... İşte o zaman, kimin konumca daha kötü ve ordu bakımından daha zayıf olduğunu öğrenecekler."},{"n":76,"t":"Öte yandan Allah, doğru yola yönelen kimseleri doğru yolda sebatlı kılar; ve (insanoğlunun) verimli ve kalıcı ürünleri olan erdemli ve yararlı davranışları, senin Rabbinin katında hem değer olarak daha iyi, hem de kazanç olarak daha üstündür."},{"n":77,"t":"Küfre saplanmış olan, üstelik \"Servet ve evlat elbette bana verilecekti!\" diyen kimseye baksana bir."},{"n":78,"t":"o, kendisine gaybın sırlarının açıldığını mı düşünüyor; yoksa O rahmet kaynağının katında (muteber olan) bir sözleşme mi yaptı?"},{"n":79,"t":"Kesinlikle hayır! Biz onun söylediklerini kaydedeceğiz ve onun cezasını uzattıkça uzatacağız;"},{"n":80,"t":"ve onun (gururla) dile getirdiği (servet ve evlat) Bize kalacak; ve kendisi huzurumuza yalnız başına çıkacak."},{"n":81,"t":"Bu (gibiler), Allah`tan başkalarını kendilerine statü ve nüfuz sağlamak için ilahlaştırırlar."},{"n":82,"t":"Ama hayır! Aksine (ahirette) onlar kendilerine yönelik tüm tapınmaları reddedecekler ve berikilerin aleyhine zillet ve utanç delili olacaklar."},{"n":83,"t":"(Ey insan!) Küfrü tabiat haline getirenlerin üzerine, (içgüdülerini) kışkırttıkça kışkırtan şeytanları musallat ettiğimizi görmez misin?"},{"n":84,"t":"Şu halde, onlara karşı harekete geçmek için acele etmene gerek yok: şu kesin ki Biz onların günlerini tek tek sayıyoruz."},{"n":85,"t":"O gün (gelince), O rahmet kaynağının huzurunda, sorumluluk bilinciyle kuşanmış olanları ağır konuklar olarak toplayacağız."},{"n":86,"t":"Fakat günaha gömülüp gitmiş olanları bir sürü gibi cehenneme doğru süreceğiz."},{"n":87,"t":"(İşte o gün) O Rahmet kaynağıyla yaptığı (iman) sözleşmesine sadık kalanlar dışında, hiç kimse şefaate nail olamayacaktır."},{"n":88,"t":"Bir de çıkıp \"O rahmet kaynağı kendisine bir oğul edindi\" dediler:"},{"n":89,"t":"Doğrusu siz öyle dehşet verici bir iddiada bulundunuz ki;"},{"n":90,"t":"bundan dolayı neredeyse gökler paramparça olacak, yer yarılacak ve dağlar toz duman olacak!"},{"n":91,"t":"O rahmet kaynağına bir oğul isnat etmek ha!.."},{"n":92,"t":"İyi ama, O rahmet kaynağının bir oğul edinmesi olacak şey değil ki!"},{"n":93,"t":"Hem göklerde ve yerde olan herkes, O rahmet kaynağının huzuruna sadece ve sadece bir kul olarak çıkacaklardır."},{"n":94,"t":"Doğrusu O, onların tümünü derin bir bilgiyle kuşatmış ve tek tek saymıştır."},{"n":95,"t":"Sonunda onların her biri Kıyamet Günü O`nun huzuruna tek başına çıkacaktır."},{"n":96,"t":"İmanda sebat eden, o imanla uyumlu bir hayat yaşayan kimseler var ya: O sonsuz rahmet kaynağı onlar için tarifsiz bir sevgi var edecek."},{"n":97,"t":"İşte sadece bu yüzden Biz onu senin (konuştuğun) dil aracılığıyla kolaylaştırdık ki, sorumluluk bilinci taşıyan kimseleri onunla müjdeleyip sorumsuzca savrulanları da uyarasın diye."},{"n":98,"t":"Zira Biz onlardan önce nice uygarlıkları helak etmişizdir: sen onlardan herhangi birinin varlığını hissediyor, ya da onların ardından bir tek çıtırtı olsun duyabiliyor musun?"}],[{"n":1,"t":"Ey insan!"},{"n":2,"t":"Biz bu ilahi hitabı sana zorluk çekip mutsuz olasın diye indirmedik;"},{"n":3,"t":"yalnızca Allah`ın sevgisini yitirmekten korkan kimselere bir uyarı olsun için (indirdik):"},{"n":4,"t":"yeri ve yüce gökleri yaratan Zat tarafından indirilmedir bu!"},{"n":5,"t":"O rahmet kaynağı ki, mutlak hükümranlık makamına sadece O kurulmuştur."},{"n":6,"t":"Göklerde, yerde, bu ikisi arasında ve toprağın bağrında ne varsa O`na aittir."},{"n":7,"t":"Düşünceni ister yüksek sesle dile getir (ister getirme); unutma ki O, gizli (düşünceleri) bildiği gibi, ondan daha gizli (duyguları) da bilir."},{"n":8,"t":"Allah... O kendisinden başka ilah bulunmayandır; en güzel nitelikler, tüm mükemmellikler O`na mahsustur."},{"n":9,"t":"Musa`nın yaşadıklarından haberin var mı?"},{"n":10,"t":"Hani o ateş türü cazip bir şey görmüştü de, ailesine hemen \"Durun, bekleyin!\" demişti; \"Benim gözüme ateş türü bir şey ilişti; belki size ondan bir tutam kor getiririm veya ateşin etrafında bir yol gösterici bulurum\"."},{"n":11,"t":"Fakat ateşe yaklaşınca ona (gaipten) \"Ey Musa!\" diye seslenildi;"},{"n":12,"t":"\"Benim, Ben! Senin Rabbin! Şimdi ayakkabılarını çıkar! Çünkü sen iki kez kutsal kılınmış vadidesin!"},{"n":13,"t":"Ve Ben seni (elçi) olarak seçtim; bundan böyle artık sana vahyedileni dinle!"},{"n":14,"t":"\"Gerçek şu ki Ben, evet Ben Allah`ım! Benden başka ilah yoktur: artık sadece Bana kulluk et ve adımın anılıp şanımın yücelmesi için tüm destek ve çabanı seferber et."},{"n":15,"t":"Çünkü, her ne kadar son saati (herkesten) gizli tutmuşsam da, herkese çabasının karşılığı verilsin diye Son Saat kesinlikle gelecektir."},{"n":16,"t":"Bu hakikate inanmayıp da bencilce arzularının tutsağı olan kimse seni yolundan alıkoymasın; aksi halde kendi değerini düşürmüş olursun."},{"n":17,"t":"Ve (o ses devam etti): \"Nedir o sağ elindeki ey Musa?\""},{"n":18,"t":"(Musa) \"Bu? Benim değneğim!\" dedi, \"Ona yaslanırım, onunla davarlarıma yaprak silkelerim; tabi ki benim için işe yaradığı başka yerler de var!\""},{"n":19,"t":"(O ses) \"Onu yere bırak ey Musa!\" dedi."},{"n":20,"t":"Bunun üzerine (Musa) onu yere bıraktı. Bir de ne görsün: o değnek bir yılan türü... hızla akıyor..."},{"n":21,"t":"(O ses) \"Onu al ve sakın korkma!\" dedi, \"Biz onu ilk haline geri döndüreceğiz.\""},{"n":22,"t":"\"Şimdi de elini koynuna sok! Her tür kusurdan arınmış olarak, bir başka mucize olarak bembeyaz çıkacaktır;"},{"n":23,"t":"ki bu sayede, sana en büyük mucizelerimizden birini gösterebilelim...\""},{"n":24,"t":"\"(Artık) Firavun`a git, çünkü o iyice azgınlaştı!\""},{"n":25,"t":"(Musa) şöyle dua etti: \"Rabbim! Göğsüme genişlik ver"},{"n":26,"t":"kolaylaştır işimi;"},{"n":27,"t":"düğümü çöz dilimden;"},{"n":28,"t":"ki anlasınlar beni!"},{"n":29,"t":"\"Bana yakınlarımdan yükümü paylaşacak birini görevlendir;"},{"n":30,"t":"(Mesela) Kardeşim Harun`u!"},{"n":31,"t":"Onun sayesinde gücüme güç kat!"},{"n":32,"t":"Görevimden bir pay da ona ver"},{"n":33,"t":"ki, zaten yüce olan adını çok daha yüceltelim;"},{"n":34,"t":"ve Seni sürekli analım:"},{"n":35,"t":"Kuşku yok ki Sen, bizi daima görüp duruyorsun!\""},{"n":36,"t":"(Rab) dedi ki: \"Doğrusu Ey Musa, işte istediklerin sana verilmiştir;"},{"n":37,"t":"ve zaten geçmişte bir kez daha sana (bu şekilde) ikramda bulunmuştuk."},{"n":38,"t":"Hani ilahi mesajı annene şöyle iletmiştik;"},{"n":39,"t":"\"Onu sandığa koy, ardından da o sandığı suyun akıntısına bırak; akıntı onu kıyıya ulaştıracaktır; Bana düşman olan ve ona da düşman olacak olan biri ona sahip çıkacaktır.\" İşte Ben, seni daha (o zamandan) katımdan bir muhabbetle kuşatmıştım ki, gözlemimiz altında yetiştirilesin diye."},{"n":40,"t":"O zaman kız kardeşin de takip etmiş ve onlara \"Size, ona bakabilecek birini göstermemi ister misiniz?\" demişti. En sonunda seni annene geri kavuşturduk ki, onun da gözü aydın olsun ve üzülmesin... Derken (erişkin biri olunca) tuttun bir cana kıydın; fakat Biz seni bu tasadan da kurtarmıştık; yani seni bir sınavdan diğerine deneyip durmuştuk. Daha sonra yıllarca Medyenliler arasında yaşadın; en sonunda takdirimiz gereği (bu noktaya) geldin ey Musa!"},{"n":41,"t":"Zira seni kendim için seçip yetiştirmiştim:"},{"n":42,"t":"(İmdi) sen ve kardeşin verdiğim mucizevi belgelerle yola çıkın; sakın ola adımı (yüceltme) konusunda ihmalkar davranmayın!"},{"n":43,"t":"Siz ikiniz doğruca Firavun`a gidin, çünkü o pek azdı!"},{"n":44,"t":"Fakat ona konuşurken yumuşak bir üslup kullanın! (O zaman) belki söz dinler, ya da en azından (daha ileri gitmekten) çekinir."},{"n":45,"t":"O ikisi \"Rabbimiz!\" dediler, \"doğrusu biz, bize aşırı şiddet uygulamasından veya daha da azgınlaşmasından korkarız.\""},{"n":46,"t":"(Allah) \"Korkmayınız\" dedi, \"Şu kesin ki Ben sizinle birlikteyim; her şeyi duyuyor ve görüyorum."},{"n":47,"t":"Haydi ona gidip deyin ki: `Biz Rabbinin iki elçisiyiz. İsrailoğullarını bizimle gönder ve onlara işkence etme. Şüphesiz biz sana Rabbinden ayetle geldik. Selâm hidayete uyanların üzerinedir."},{"n":48,"t":"Bir de unutmayın ki, (büyük) azabın hakikatı yalanlayan ve ondan yüz çevirenlerin üzerine olacağı bize vahyolunmuştur.\""},{"n":49,"t":"(Firavun): \"Kimmiş bakayım sizin Rabbiniz ey Musa?\" dedi."},{"n":50,"t":"(Musa): \"Bizim Rabbimiz her şeyin yaratılışını takdir edip, sonra da onu yaratılış amacına yöneltendir.\""},{"n":51,"t":"(Firavun): \"İyi ama\" dedi, \"ya önceki kuşakların durumu ne olacak?\""},{"n":52,"t":"(Musa): \"Onların ne olacağının bilgisi Rabbim katında bir yasaya bağlı kılınmıştır: benim Rabbim ne yanılır, ne de unutur\" dedi."},{"n":53,"t":"O, sizin için yeryüzünü bir beşik yaptı; ve orada sizin için yolları O açtı; yine gökten yağmuru O indirdi. İşte bu sayede onunla envai çeşit bitkilerden çift çift ürünler çıkarmışızdır;"},{"n":54,"t":"siz de beslenin, hayvanlarınızı da besleyin: Şüphesiz bütün bunlarda, sahibini kötülükten koruyan bir akla sahip olanlar için alınacak dersler vardır."},{"n":55,"t":"Biz sizi (topraktan) yarattık, yine ona döndüreceğiz; ve oradan bir kez daha çıkaracağız."},{"n":56,"t":"Doğrusu Biz (Firavun`a) mucizevi belgelerimizin her türünü gösterdik; fakat o yalanladı ve küstahça yüz çevirdi."},{"n":57,"t":"(Firavun) dedi ki: \"Sen, sihrinle bizi yurdumuzdan çıkarmak için mi geldin ey Musa?"},{"n":58,"t":"Fakat şunu da bil ki biz de sana, benzer bir sihirle karşılık vereceğiz. Haydi, şimdi bizimle senin aranda kamuya açık bir mekanda, iki tarafın da cayamayacağı bir buluşma zamanı tayin et!\""},{"n":59,"t":"(Musa) dedi ki: \"Buluşma zamanınız bayram günü; tam da halkın toplandığı kuşluk vakti olsun!\""},{"n":60,"t":"Hemen ardından Firavun görüşmeyi sona erdirdi ve tüm numaralarını hazırladıktan sonra (buluşma zamanı) çıkageldi."},{"n":61,"t":"Musa onlara \"Size yazıklar olsun!\" diye çıkıştı; \"Allah`a karşı yalan uydurmayın; böyle yaparsanız, O size kökünüzü kurutacak bir ceza verir: zaten O`na iftira eden daha baştan kaybetmiştir.\""},{"n":62,"t":"Derken, (Firavun ve yandaşları) aralarında tartışarak planlarını yaptılar, fakat bunu gizlediler;"},{"n":63,"t":"diyorlardı ki: \"Bu ikisi, sizi sihirleriyle yurdunuzdan sürüp çıkarmak ve sizin oluşturduğunuz ideal yaşam tarzınıza son vermek isteyen büyücülerden başkası değil!"},{"n":64,"t":"İşte bu nedenle, tüm hile ve tuzaklarınızı bir araya getirecek tek saf halinde üzerlerine gidin; zira bugün galip gelen taraf, kesin bir başarı kazanmış olacaktır.\""},{"n":65,"t":"(Sihirbazlar): \"Ey Musa!\" dediler, \"Sen mi atarsın, yoksa ilk atan biz mi olalım?\""},{"n":66,"t":"(Musa): \"Hayır!\" dedi, \"(Önce) siz atın!\" Bunu yapar yapmaz, onların ipleri ve sopaları sihirden dolayı ona akıyormuş gibi göründü;"},{"n":67,"t":"işte bu yüzden Musa, içinde bir ürperti hissetti."},{"n":68,"t":"Ona \"Korkma!\" dedik, \"Şüphe yok ki sonunda üstün gelecek olan sen olacaksın, elbette sen!"},{"n":69,"t":"Şimdi sağ elindeki (asa)yı at, onların yaptıklarını silip süpürecektir; çünkü onların yaptığı, sihirbazların gözbağcılığından başka bir şey değil. Kaldı ki, bir sihirbaz ne amaç güderse gütsün, asla kalıcı bir başarı elde edemez."},{"n":70,"t":"Nihayet sihirbazlar secdeye kapanarak dediler ki: \"Biz Harun ve Musa`nın Rabbine iman ettik!\""},{"n":71,"t":"(Firavun) \"Demek siz, benden izin almadan ona inandınız ha?\" dedi; \"Öyle anlaşılıyor ki size sihri öğreten baş ustanız bu olmalı. Fakat dönekliğinizden dolayı kesinlikle ellerinizi ve ayaklarınızı keseceğim; ve topunuzu götürüp hurma kütüklerine asacağım: böylece hangimizin cezasının daha şiddetli ve kalıcı olduğunu iyice anlamış olacaksınız!\""},{"n":72,"t":"Onlar şöyle cevap verdiler: \"Senin tehditlerine kapılıp da asla bize gelen hakikatın apaçık delillerine ve bizi yaratana sırt dönmeyeceğiz; ne karar verirsen ver, umurumuzda değil; nasıl olsa senin kararın sadece bu (fani) dünya hayatında geçerlidir!"},{"n":73,"t":"Şu kesin ki biz, hatalarımızı ve senin bizi icra etmeye zorladığın sihir türü şeyleri bağışlaması için Rabbimize gönülden inanıp güvenmişiz: Zira Allah (güven duyulanların) en hayırlısı ve en kalıcısıdır.\""},{"n":74,"t":"Şüphe yok ki, kim Rabbine günaha batmış bir halde kavuşursa kendisini cehennemin beklediğini unutmasın! Orada ne tam ölebilir, ne de tam yaşayabilir."},{"n":75,"t":"Ama kim de (sahibine) erdemli işler yaptıran bir iman ile kavuşursa, işte en yüce makamlar onların olacaktır:"},{"n":76,"t":"mutluluğun üretildiği, zemininden ırmakların çağladığı, girenin bir daha çıkmadığı cennetler... İşte bu da, arınan kimselerin ödülüdür."},{"n":77,"t":"Ve doğrusu Biz Musa`ya şöyle vahyetmiştik: \"Kullarımla birlikte geceleyin yola koyul, onları denizin ortasında kuru bir yola vur; arkanızdan yetişirler diye endişe etme, hepsinden öte (Allah`tan gayrı kimseden) korkma!\""},{"n":78,"t":"Derken Firavun da askerleriyle birlikte onların peşine düştü; ama birden onları boğacak olan su (görevini yapıp) onları içine alıverdi;"},{"n":79,"t":"bir kez Firavun halkını yoldan çıkarmıştı; bir daha da yolu bulamadılar."},{"n":80,"t":"Siz ey İsrailoğulları! Doğrusu sizi düşmanlarınızdan kurtarmış ve (Sina) Dağı`nın sağ yamacında sizden söz almıştık; üstelik bir de size menn ve selva indirmiştik:"},{"n":81,"t":"(ve demiştik ki): \"Size verdiğimiz rızıklarla beslenin, fakat bu hususta sınırı aşmayın; aksi halde gazabımı hak etmiş olursunuz! Kim benim gazabımı hak ederse, işte o artık tepe taslak gitmiş olur."},{"n":82,"t":"Ama şu da var ki Ben, af dileyip samimiyetle Bana yönelen, iman eden ve erdemli davranan, nihayet doğru yolda olan herkesi tekrar tekrar bağışlayan biriyim!"},{"n":83,"t":"Ve (Allah şöyle dedi:) \"Ey Musa, seni halkını terk etme pahasına böylesine tez canlı kılan nedir?\""},{"n":84,"t":"(Musa) şöyle cevap verdi: \"Onlar, beni izlemeyi sürdürüyorlar; ben ise ey Rabbim, Sana ulaşan yolda sırf Senin rızanı kazanmak için acele ettim!\""},{"n":85,"t":"(Allah): \"O halde haberin olsun ki\" dedi, \"senin ardından Biz kavmini sınadık; ve Samiri onları yoldan çıkardı.\""},{"n":86,"t":"Bunun üzerine Musa hüzünle karışık bir kızgınlıkla toplumuna döndü; \"Ey kavmim!\" dedi, \"Rabbiniz size güzel bir vaadde bulunmamış mıydı? Yoksa (bu sözün) vadesi size çok uzun (ve bedeli çok ağır) mı geldi? Veya, Rabbinizin gazabını üzerinize çekmeye can mı atıyorsunuz? İşte, sonuçta bana verdiğiniz sözden dönmüş oldunuz!\""},{"n":87,"t":"Onlar (kendilerini) şöyle savundular: \"Biz sana verdiğimiz sözü kasıtlı olarak çiğnemedik; fakat (Mısır) halkının ziynet eşyalarına (haksız yere) konmanın vebalini taşıyorduk; ama biz onları (sorumluluktan kurtulmak için) kaldırıp attık, bunun üzerine Samiri de (onları alıp ateşe) attı.\""},{"n":88,"t":"Derken o onların önüne, böğürme sesi çıkaran bir inek yavrusu heykeli çıkarttı. Daha sonra da (birbirlerine) \"İşte sizin de ilahınız Musa`nın ilahı buydu; fakat o unuttu!\" dediler."},{"n":89,"t":"Fakat onlar görmüyorlar mı ki, bu (heykel) kendilerine tek kelime cevap veremez; dahası, kendilerine ne zarar verebilir ne de yarar sağlayabilir?"},{"n":90,"t":"Üstelik, (Musa dönmeden) önce Harun onlara \"Ey kavmim!\" demişti, \"Fena halde tuzağa düşürüldünüz; unutmayın ki sizin Rabbiniz O sınırsız rahmet kaynağıdır: o halde artık beni izleyin ve benim talimatlarıma uyun!\""},{"n":91,"t":"Onlar dediler ki: \"Musa bize dönüp gelinceye kadar asla ona perestiş göstermekten geri durmayacağız!\""},{"n":92,"t":"(Musa dönünce) \"Ey Harun!\" dedi, \"Onların sapıttıklarını gördüğün halde neden engel olmadın?"},{"n":93,"t":"Bana uyman gerekmiyor muydu? Şimdi sen emrime karşı gelmiş olmadın mı?\""},{"n":94,"t":"\"Ey anamın oğlu!\" dedi, \"Sakalımı-saçımı çekiştirip durma! İnan ki senin bana \"İsrailoğulları arasına ayrılık tohumları saçtın, nasihatimi dinlemedin!\" demenden korktum, (fakat gücüm yetmedi)!\""},{"n":95,"t":"(Musa) \"Peki, ya senin derdin neydi ey Samiri!\" dedi."},{"n":96,"t":"O dedi ki: \"Ben (bu) işe onların bakmadıkları bir gözle baktım; bu nedenle de Elçi`nin (İnanç sisteminden) etkili bir parçayı çekip aldım ve kaldırıp attım: zira güdülerim beni böyle yapmaya sevk etti.\""},{"n":97,"t":"(Musa): \"Defol, git!\" dedi, \"Ama iyi bil ki bundan böyle senin hayatın `(Ben) tecrit edildim` demekten ibaret olacaktır. Bir şeyi daha unutma ki, seni (öte dünyada) asla atlatamayacağın bir buluşma daha beklemektedir. Şimdi, kendisine tapınmakta bunca ısrar ettiğin ilahına dön de bir bak: onu cayır cayır yakacak, ardından da külünü suya savuracağız!"},{"n":98,"t":"Şu gerçeği hiç unutmayın: ilahınız yalnızca kendisinden başka ilah olmayan Allah`tır: O`nun bilgisi her şeyi kuşatmıştır."},{"n":99,"t":"İşte bu şekilde, geçmişte yaşanmış birtakım olayların özüne ilişkin anlatımı sana sunmuş olduk; zira sana, katımızdan hatırlatıcı bir mesaj vermiş bulunuyoruz."},{"n":100,"t":"Her kim bu (ilahi mesajdan) yüz çevirirse, iyi bilsin ki o, Kıyamet Günü (zorlanacağı) bir sorumluluğun altına girmiş olacak;"},{"n":101,"t":"o sorumluluğun altından bir daha da asla kalkamayacaktır; üstelik o, Kıyamet Günü onlar için çok berbat bir yük olacaktır."},{"n":102,"t":"O gün sura üflenecek; ve Biz de o gün günahı hayat tarzı haline getirmiş olanları, (korku ve dehşetten) morarmış olarak bir araya toplayacağız;"},{"n":103,"t":"korkudan kısılmış bir sesle birbirlerine \"(Dünyada) ne kadar kaldınız ki; hepsi hepsi on gün işte!\" diye fısıldaşacaklar."},{"n":104,"t":"Onların en akıldane yol göstericisinin \"Hayır, asla bir günden fazla kalmadınız!\" dediği zaman, berikilerin (kendi içlerinde) neler neler diyeceklerini de yine en iyi Biz biliriz."},{"n":105,"t":"Sana, (o gün) dağların ne olacağı hakkında sorarlar. Bu takdirde onlara şöyle de: \"Rabbim onları un ufak edip tümünü savuracak;"},{"n":106,"t":"ve arzı çırılçıplak, kupkuru bir düzlük olarak bırakacak;"},{"n":107,"t":"orada ne bir çukur ne de bir tümsek göreceksin!\""},{"n":108,"t":"O gün onların (tümü), kendisine karşı yanlış yapamayacakları bir davetçiye tabi olmak durumundadırlar: artık bütün sesler O rahmet kaynağının azametinden dolayı iyice kısılmıştır; öyle ki, boğuk bir uğultu dışında hiçbir ses işitemeyeceksin."},{"n":109,"t":"O gün, kendisine O rahmet kaynağının geçit verdiği ve sözünden razı olduğu kimselerden başkasına şefaatin hiçbir yararı olmayacak."},{"n":110,"t":"O onların bildiklerini de, bilmediklerini de biliyor; fakat insan bilgi (kapasitesinin sınırlılığı) sebebiyle bunu asla kavrayamaz."},{"n":111,"t":"Her şeyi ayakta tutan Mutlak Diri`nin huzurunda yüzler yere eğilmiştir ve sırtına zulüm yükünü yüklenen kimsenin işi bitmiştir."},{"n":112,"t":"Fakat, kim de mü`min olduğu halde erdemli davranırsa, artık o ne haksızlığa uğramaktan ne de (cehenneme) yem olmaktan korksun."},{"n":113,"t":"Ve böylece Biz bu (vahyi) Arapça bir hitap olarak indirdik; ve ondaki tüm uyarıları bütün boyutlarıyla ortaya serdik: Belki sorumluluk duyarlar veya (bu mesaj) onları (fıtratlarında zaten) var olanı hatırlatarak yeniden ortaya çıkarır diye."},{"n":114,"t":"Sonuçta, aşkın olan Allah, mutlak otoritenin sahibi olarak mutlak hakikatin de kaynağıdır: şu halde O`nun vahyi tamamıyla sana ulaştırılmadan önce, Kur`an hakkında tez canlı davranarak (sonuç çıkarma), fakat, \"Rabbim, ilmimi artır!\" de."},{"n":115,"t":"Ve doğrusu Biz Adem`e, her şeyden önce, talimatımıza (uygun bir fıtrat) nakşetmiştik; fakat o buna yabancılaştı; dolayısıyla Biz onu bu hususta kararlılık sahibi bulmadık."},{"n":116,"t":"Hani meleklere \"Adem (oğlu) için emre amade olun!\" dediğimiz zaman, onların tümü hemen emre amade olmuştu; fakat sadece İblis yüz çevirmişti."},{"n":117,"t":"Bunun üzerine Biz de \"Ey Adem!\" demiştik, \"İşte bu, sana ve eşine tarifsiz bir düşmanlık beslemektedir; dolayısıyla, onun sizi bu has bahçeden çıkarma girişimlerine karşı çok dikkatli olun; yoksa bedbaht olursun!"},{"n":118,"t":"Zira aklından çıkarma ki burada aç değilsin, açık değilsin;"},{"n":119,"t":"yine unutma ki burada ne susuzluk çekersin, ne de sıcağa maruz kalırsın!\""},{"n":120,"t":"Hal böyleyken Şeytan onu vehimlere sürükleyerek \"Ey Adem!\" dedi, \"Sana sonsuzluk ağacını ve sonu gelmez bir saltanatın (yolunu) göstereyim mi?\""},{"n":121,"t":"Derken o ikisi ondan yediler. Bunun ardından kendi cinselliklerinin farkına vardılar ve başladılar has bahçenin yapraklarından topladıklarıyla üzerlerini örtmeye: sonuçta Adem Rabbine karşı gelmiş ve huzurunu bozmuş oldu."},{"n":122,"t":"Nihayet Rabbi onu seçip arındırdı. Dolayısıyla hem tevbesini kabul etti; hem de ona (sorumluluğunu ifa edecek) yolu göstererek"},{"n":123,"t":"dedi ki: \"O makamdan hep birlikte birbirinize düşman olarak inin! Bundan böyle de, Benim katımdan size doğru yol bilgisi gelecektir: artık kim benim gösterdiğim yolu izlerse, işte o ne sapacak ne de kendini yitirecektir."},{"n":124,"t":"Fakat, kim de benim uyarıcı mesajlarımdan yüz çevirirse, iyi bilsin ki onun hayat alanı daraldıkça daralacak ve Kıyamet Günü Biz o kimseyi kör olarak kaldıracağız."},{"n":125,"t":"O kimse \"Rabbim\" diyecek, \"Niçin beni kör olarak kaldırdın; oysa ki ben daha önce gören biriydim?\""},{"n":126,"t":"(Allah) \"Böyle gerekiyordu\" diyecek, \"Sana Bizim ayetlerimiz ulaşmıştı, fakat sen onları unutmuştun; sonuçta bugün de sen unutulacaksın!"},{"n":127,"t":"İşte Biz de, haddi aşan ve Rabbinin ayetlerine güvenip inanmayan kimseleri böyle cezalandırırız; hele bir de ahiret azabı var ki, o çok daha şiddetli ve çok daha kalıcıdır."},{"n":128,"t":"Şimdi yurtlarında gezip tozdukları, kendilerinden önce yaşayıp gitmiş olan nesillerden bir nicesini cezalandırmış olmamız onların aklını başına getirmedi mi? Şüphesiz bunda, kendisini kötülükten koruyan bir akla sahip olanlar için alınacak dersler vardır."},{"n":129,"t":"Ve eğer Rabbin tarafından -belirli bir süreye kadar (fırsat tanınacağına) dair- başlangıçta konulmuş bir yasa olmasaydı, (günahkarları) hemen cezalandırmak kaçınılmaz olurdu."},{"n":130,"t":"Öyleyse, artık onların söyleyeceklerine karşı sabırlı ol! Bir de güneşin doğumu ve batımından önce Rabbinin aşkın olan yüce zatını (namaz kılarak) hamd ile an! Yine gecenin bazı saatlerinde ve gündüzün belli zamanlarında (namaz kılarak) O`nun yüce zatını an (ki, O`ndan) razı olduğun belli olsun!"},{"n":131,"t":"Ve onlardan kimi çiftlere kendilerini sınamak için verdiğimiz bu dünya hayatının aldatıcı parlaklığına gözlerini dikme: zira senin Rabbinin (sana verdiği) nimet, çok daha yararlı ve çok daha kalıcıdır."},{"n":132,"t":"Öyleyse yakınlarına namazı emret ve sen de bunun üzerinde kararlı ol! Biz senden rızık istemiyoruz; seni Biz doyuruyoruz: ve mutlu son (kişinin) sorumluluk bilincine bağlıdır."},{"n":133,"t":"Bir de dediler ki \"O bize, Rabbinden bir mucize getirmeli değil miydi?\" İyi de, daha önceki vahiylerin içeriğinde yer alan açık deliller kendilerine ulaşmadı mı?"},{"n":134,"t":"Ve eğer Biz, onları (elçi göndermeden) önce bir helake uğratarak cezalandırmış olsaydık, bu kez de \"Ey Rabbimiz! Eğer Sen, şu zillet verici ve onur kırıcı duruma düşmeden önce bize bir elçi göndermiş olsaydın ona hemen uyardık!\" diyecekleri kesindi!"},{"n":135,"t":"De ki: \"Herkes (hak ettiği akıbeti) beklemektedir; o halde siz de bekleyiniz! Nasıl olsa, doğru dürüst bir yol seçenlerin kimler olduğunu; ve (bu tercih sonucunda Allah`ın) kimleri doğru yola yönelttiğini, günü gelince öğreneceksiniz."}],[{"n":1,"t":"İnsanlar için yaptıklarının hesabını verme vakti oldukça yaklaştı; fakat onlar hala gaflet içerisinde (bu gerçeğe) sırt çeviriyorlar."},{"n":2,"t":"Rablerinden kendilerine ne zaman yeni bir uyarı gelse, onu da sadece alaya alarak dinliyorlar."},{"n":3,"t":"Onların aklı fikri oyunda oynaştadır; üstelik bilinci altüst olan bu kimseler el altından şöyle fiskos yapıyorlar: \"Bu da sizin gibi ölümlü bir insan değil mi? Şu halde siz, göz göre göre büyüye kapılıp gidecek misiniz?\""},{"n":4,"t":"(Ve) dedi ki: \"Rabbim gökte ve yerde söylenen her sözü, her düşünceyi bilmektedir: zira O her şeyi işitendir, her şeyi bilendir.\""},{"n":5,"t":"\"Hayır!\" dediler; \"(Bunlar) karma karışık düşlerdir!.. Yok yok, onu kendisi uydurmuştur!.. Bu da değilse, o bir şair olmalı... İyi ama, önceden gönderilen (peygamberler) gibi bize bir mucize getirse ya!..\""},{"n":6,"t":"Onlardan önce kendilerini (inkarda ısrarlarından dolayı) helak ettiğimiz nice kentler iman etmemişlerdi, şimdi bunlar mı iman edecekler?"},{"n":7,"t":"Biz senden önce de kendilerine mesajlarımızı ilettiğimiz (ölümlü) insanlardan başka birilerini peygamber olarak göndermedik. Hem eğer (bu konuda bir şey) bilmiyorsanız, (geçmiş) vahiylerin mensuplarına sorun!"},{"n":8,"t":"Biz onları yemeğe bile ihtiyaç duymayan varlıklar olarak göndermedik; dahası onlar ölümsüz de değildiler."},{"n":9,"t":"Nitecede Biz onlara verdiğimiz sözü tuttuk; bunun sonucunda onları ve dilediklerimi kurtarıp, (hayatlarını) amaçsızca harcayanları ise helak ettik."},{"n":10,"t":"Doğrusu Biz size, içinde size şeref ve itibar kazandıran bir mesaj indirmiş bulunuyoruz: şu halde, aklınızı başınıza almayacak mısınız?"},{"n":11,"t":"Üstelik Biz, zulümde ısrarcı olan nice beldeleri kırıp geçirdik; ve (bunun) ardından onların (yerine) başka bir toplum ikame ettik."},{"n":12,"t":"Ve onlar Bizim ezici gücümüzü hissettikleri zaman, derhal oradan kaçmaya yeltendiler."},{"n":13,"t":"Durun, kaçmayın! Haydi, sizi küstahça şımartan konforlu yaşantınıza ve konaklarınıza geri dönün! Ne yani, herhalde hesaba çekilecektiniz!"},{"n":14,"t":"Onlar \"Vah bize!\" diyecekler; \"Şu kesin ki, bizler hep zulümde ısrar ettik!\""},{"n":15,"t":"Ve onların bu yazıklanmaları, Biz kendilerini biçilmiş ekin haline getirip sönmüş köze çevirinceye kadar devam edip gidecek."},{"n":16,"t":"(Ey insanlar!) Biz göğü, yeri ve bunların arasındakileri bir oyun olsun diye yaratmadık."},{"n":17,"t":"Eğer Biz bir eğlence edinmek isteseydik, onu kendi katımızdan edinirdik; ne ki bunu asla yapacak değiliz."},{"n":18,"t":"Aksine Biz, mutlak hakikate atıf olan (amaçlı ve anlamlı yaratılış) gerçeğini, malum amaçsız ve anlamsızlığın başına çalarız da, o berikinin belini kırar; işte o zaman beriki de yok olup gider. İşte (Yaratan ve yaratılan) konusunda bu türden tanımlamalarınızdan dolayı yazıklar olsun size!"},{"n":19,"t":"Zira, göklerde ve yerde ne varsa hepsi O`na aittir; nitekim O`nun tarafında yer alanlar, O`na kulluk etmede ne kibire kapılırlar, ne de bıkıp usanırlar."},{"n":20,"t":"Onlar, gece gündüz demeden aralıksız O`nun aşkın ve yüce olan zatını anarlar."},{"n":21,"t":"YOKSA onlar yeryüzünden bir takım tanrılar peydahladılar da, onlar mı yapacak can verme işini?"},{"n":22,"t":"Eğer göklerde ve yerde Allah’tan başka ilâhlar olsaydı, (gökler ve yer) kaos içinde mahvolurdu: işte bu nedenle O her şeyden yüce olan Allah, O mutlak otorite sahibi, onların yakıştırdıkları her şeyin ötesindedir."},{"n":23,"t":"(O,) yapmakta olduğundan suâl olunmaz; onlar ise sorguya çekileceklerdir."},{"n":24,"t":"Yoksa onlar (bu gerçeğe rağmen) O`nun dışında ilahlar edinmekte ısrar mı edecekler? De ki: \"Haydi, siz de kendi delilinizi getirin! İşte bu, hem benimle birlikte olanların hem de benden öncekilerin dile getirdikleri (ortak) mesajdır\". Ama hayır, onların çoğu bu (açık) gerçeği bilmiyorlar; bu nedenle (ondan) yüz çeviriyorlar."},{"n":25,"t":"Halbuki Biz, senden önce gönderdiğimiz peygamberlerin tümüne her mesajı ısrarla ilettik; o da şu: \"Benden başka ilah yok, o halde yalnız Bana kulluk edin!\""},{"n":26,"t":"Ama (onların takipçileri arasından) yine de \"Rahman çocuk edindi\" diyenler çıktı. O şanı yüce olan, (ölümlülere has bu tür) tanımlamalardan sonsuzca uzaktır; aksine, (Allah`ın soyundan geldiğini iddia ettikleri o kimseler), ilahi ikrama mazhar olan kullardır:"},{"n":27,"t":"Onlar, kendi sözlerini O`nun sözünün önüne geçirmezler: yani onlar sadece O`nun talimatıyla hareket ederler."},{"n":28,"t":"O, onların bildiklerini de bilmediklerini de bilir. Ki zaten onlar, O`nun hoşnut ve razı olmadığı hiç kimseye şefaat edemezler: zira onlar O`nun yüceliği karşısında derin bir saygıyla titrerler."},{"n":29,"t":"Kaldı ki onlardan biri \"O`ndan bir alt basamakta da olsa, sonuçta ben de bir ilahım demiş olsaydı, bu takdirde onu cehennemle cezalandırırdık: Çünkü haddini bilmeyenleri Biz böyle cezalandırırız."},{"n":30,"t":"İnkarda ısrar eden o kimseler görmezler mi ki; gökler ve yer başlangıçta bitişikken Biz onları ayırdık ve (hareket edebilen) her canlıyı sudan var ettik? Buna rağmen hala inanmayacaklar mı?"},{"n":31,"t":"Ve yeryüzünde kendilerini sarsar diye sağlam ve sarsılmaz dağlar var ettik; ve onların aralarında, yollarını bulabilsinler diye vadiler açtık."},{"n":32,"t":"Ve göğü güvenlikli bir kubbe olarak tepelerine diktik; ama onlar, bu tür göstergelerle işaret ettiğimiz (hakikatlere) sırt çeviriyorlar."},{"n":33,"t":"Oysa ki geceyi ve gündüzü, güneşi ve ayı yaratan da O`dur; (ama yıldız ve gezegenlerin) hepsi de (kendileri için tesbit edilen) bir yörüngede akıp durmaktadırlar."},{"n":34,"t":"(Ey Peygamber!) Biz, senden önce yaşamış hiçbir insana ölümsüzlük bahşetmedik. Hem sanki sen öleceksin de, onlar ebediyyen yaşayacaklar mı?"},{"n":35,"t":"Her can ölümü tadacaktır; şu da var ki, Biz sizi seçip ayırmak için hayır ve şer ile sınava tabi tutuyoruz: zaten sonunda bize döneceksiniz."},{"n":36,"t":"Ve o küfre saplanmış olanlar ne zaman seni görseler, sadece alaya almak amacıyla \"Bu muymuş sizin ilahlarınızı diline dolayan?\" diye (dudak bükerler); ama iş, Rahman (adının) anılıp yüceltilmesine gelince: onu ısrarla tanımazdan gelen de yine onlar olur."},{"n":37,"t":"İnsanoğlu aceleci bir yaratılışa sahiptir; zamanı gelince size mesajlarımın (gerçek olduğunu) göstereceğim; dolayısıyla acele etmenize hiç gerek yok."},{"n":38,"t":"Buna rağmen onlar diyorlar ki: \"Eğer sözünüze sadıksanız (cevap verin bakalım): bu tehdit ne zaman gerçekleşecek?\""},{"n":39,"t":"İnkarda ısrar eden bu kimseler, yüzlerini ve sırtlarını ateşten koruyamayacakları, dahası hiçbir yardım da alamayacakları anın (dehşetini) keşke bir bilseler!"},{"n":40,"t":"Ama hayır, o (an) birdenbire gelecek ve onları şaşkına çevirecektir; artık ne onu geri çevirebilecekler, ne de kendilerine zaman tanınacaktır!"},{"n":41,"t":"Doğrusu (ey Muhammed)! Senden önceki elçilerle de alay edilmişti; fakat alay eden kimseleri bizzat alay ede geldikleri şey perişan etti."},{"n":42,"t":"De ki: \"Sizi O sınırsız rahmet kaynağına karşı, gece ya da gündüz kim koruyacak? Ama hayır, onlar Rablerinin uyarılarından yüz çeviriyorlar.\""},{"n":43,"t":"Yoksa onların Bizim dışımızda kendilerini savunacak birtakım ilahları mı var? O (sahte ilahlar) kendilerine dahi yardım edecek güçten yoksunlar; üstelik onlara katımızdan hiç bir himaye de ulaşmayacak."},{"n":44,"t":"Hayır, Biz onları ve atalarını geçici zevklere daldırdık; ta ki ömrün kendileri için böyle uzayıp gideceği (zehabına kapılsınlar): İyi ama, onlar görmüyorlar mı ki Biz yeryüzüne müdahil olup, ona (ait değerleri) her bir tarafından eksiltiyoruz? Bir de kalkıp kazanacaklarını umuyorlar, öyle mi?"},{"n":45,"t":"(Ey Muhammed!) \"Ben sizi sadece vahiyle uyarıyorum!\" de. Ama, ne kadar uyarılsalar da (kalbi) sağır olanlar bu çağrıyı işitmeyecekler."},{"n":46,"t":"Fakat, Rabbinin azap rüzgarından onlara bi efilti dokunsa, hemen \"Yazıklar olsun bize!\" derler, \"Meğerse biz, zulmü karakter haline getirmişiz!\""},{"n":47,"t":"Ve Biz, Kıyamet Günü dosdoğru tartan teraziler kurarız da, hiçbir kişi en küçük bir haksızlığa uğratılmaz; hatta hardal tanesi ağırlığında bir şey olsa, onu dahi gündeme getiririz: Biz, hesap görücü olarak yeter de artarız bile..."},{"n":48,"t":"Doğrusu Biz, Musa ve Harun`a, hakkı batıldan ayıran, karanlıkları aydınlatan ve sorumluluk bilincine sahip olanlara (yabancılaştıkları özlerini) hatırlatan bir mesaj vermiştik;"},{"n":49,"t":"onlar ki, idrak sınırını aşan bir hakikat olsa da Rablerinden korkarlar; yine onlar (görürcesine inandıkları) Son Saat`ten dolayı titrerler."},{"n":50,"t":"İşte bu da, Bizim indirdiğimiz mübarek bir hatırlatıcı mesajdır: Peki, bu durumda siz onu hala inkar edecek misiniz?"},{"n":51,"t":"Doğrusu Biz, (Musa`dan) çok daha önce İbrahim`e de doğru işleyen bir muhakeme vermiştik; (İbrahim`in) bununla (doğru yolu bulacağını) daha baştan biliyorduk."},{"n":52,"t":"Hani o babasına ve kendi toplumuna \"Sizin kendilerine tapınıp durduğunuz bu heykeller de neyin nesi?\" dediği zaman,"},{"n":53,"t":"onlar şöyle cevap verdiler: \"Atalarımızı onlara kulluk eder bulduk!\""},{"n":54,"t":"Dedi ki: \"Doğrusu siz de, atalarınız da başından beri açık bir sapıklık içindeymişsiniz.\""},{"n":55,"t":"Dediler ki: \"Sen (bunları söylerken) gerçekten ciddi misin, yoksa bize (şakacıktan) bir oyun mu oynuyorsun?\""},{"n":56,"t":"(İbrahim): \"Asla!\" dedi, \"Sizin Rabbiniz göklerin ve yerin Rabbidir ki, onları O yaratmıştır; ve ben de bu gerçeğe tanıklık etmek için (size gönderilen) biriyim."},{"n":57,"t":"Derken, (İbrahim kendi içinden şu kararı aldı): \"Allah`a yemin olsun ki, siz dönüp gittikten sonra, putlarınız için tasarladığım şeyi mutlaka gerçekleştireceğim!\""},{"n":58,"t":"Nihayet, onların tümünü paramparça etti; dönüp de kendisine başvurabilsinler diye (!) onların en iri yarı olanına dokunmadı."},{"n":59,"t":"(Olan bitene vakıf olunca, birbirlerine) dediler ki: \"Kim yaptı bunu ilahlarımıza? Her kimse, onun haddini bilmez biri olduğu apaçık ortada."},{"n":60,"t":"(Onlardan bazıları) \"Adına İbrahim denilen bir gencin onları diline doladığı kulağımıza kadar geldi\" dediler."},{"n":61,"t":"(Diğerleri) dediler ki: \"Onu insanların önüne çıkarın; belki görgü şahitliği yapacak birileri çıkar!\""},{"n":62,"t":"(Getirerek) \"İlahlarımıza bunu sen mi yaptın ey İbrahim?\" diye sorguladılar."},{"n":63,"t":"(İbrahim) \"Hayır!\" dedi, \"Bunu yapsa yapsa, şu en iri-yarı olanı yapmış olmalıdır; en iyisi mi siz kendilerine sorun; tabi ki eğer cevap verebilirlerse!\""},{"n":64,"t":"Bunun üzerine kendi iç dünyalarına döndüler ve (kendi kendilerine) \"Siz var ya, siz\" dediler, \"işte asıl haddini bilmezin ta kendisisiniz!\""},{"n":65,"t":"Fakat daha sonra, baş aşağı çevrilmiş bilinç haline (geri dönerek); \"Doğrusu, onların konuşamayacağını kendin de çok iyi biliyorsun!\" (dediler)."},{"n":66,"t":"(İbrahim) \"Ne yani\" dedi, \"şimdi siz Allah`ı bırakıp da, size hiçbir yarar sağlayamayan ve hiç bir zarardan (da sizi koruyamayan) nesnelere mi kulluk ediyorsunuz?"},{"n":67,"t":"Size de, Allah`ı bırakıp taptığınız bütün bu nesnelere de yuh olsun! Siz hiç mi akıllanmayacaksınız?!\""},{"n":68,"t":"\"Onu yakın!\" diye bağrıştılar; \"İlle de bir şey yapacaksanız (böyle yapın) ki, ilahlarınızı desteklemiş olasınız!\""},{"n":69,"t":"Biz \"Ey ateş!\" dedik; \"İbrahim`e karşı serin ve esenlikli ol!\""},{"n":70,"t":"İşte onlar (İbrahim`e) karşı bir düzen kurmak istediler; fakat Biz onların (düzenini) boşa çıkardık."},{"n":71,"t":"Dahası onu ve (yeğeni) Lut`u (oradan) kurtararak, bütün milletler için mübarek kıldığımız yurda ilettik."},{"n":72,"t":"Ve ona bir armağan olarak İshak`ı ve (onun oğlu) Yakub`u bahşettik; ve onların hepsini kişilik ve erdem sahibi kıldık;"},{"n":73,"t":"ve onları talimatlarımız çerçevesinde herkese doğru yolu gösteren önderler yaptık; nitekim onlara hayırlı işler yapmalarını, Allah`a ibadetin hakkını vermelerini, arınmak ve yücelmek için gerekli bedeli ödemelerini vahyettik: Nihayet, onların tümü de sadece Bize kulluk eden kimselerdi."},{"n":74,"t":"Lut`a da sağlam bir muhakeme ve seçip ayırma yeteneği kazandıran bir bilgi tasavvuru bahşettik; ve onu çirkin eylemleriyle tanınan kentten kurtardık; çünkü onlar yoldan çıkmış yoz bir kavimdi."},{"n":75,"t":"Ama (Lut`a bir şey olmadı), onu rahmetimizle kuşatmıştık; zira o dürüst ve erdemli kimselerdendi."},{"n":76,"t":"Onlardan çok daha önce Nuh da Bize yalvarmış, bunun üzerine Biz de onun duasını kabul etmiş, onu ve onun yakınlarını büyük bir beladan kurtarmıştık."},{"n":77,"t":"Yine onu, ayetlerimizi yalanlamakta ısrar eden bir topluma karşı desteklemiştik: zira onlar da ahlaken yozlaşmış bir toplumdu; bu yüzden Biz de tümünü boğulmaya terk ettik."},{"n":78,"t":"Davud ve Süleyman`ı da (gündeme taşı)! Hani o ikisi, bir topluluğa ait çobansız ve dağınık koyun sürüsünün gece yayıldığı tarla konusunda karar vereceklerdi; ve Biz de onların kararına şahit idik;"},{"n":79,"t":"fakat bu davada Süleyman`a (daha) derin bir kavrayış vermiştik. Bununla beraber Biz, her birine sağlam bir muhakeme ve seçip ayırma yeteneği kazandıran bir bilgi tasavvuru bahşettik. Zaten Davud ile birlikte, emrimize amade kıldığımız dağlar da O`nun kudret ve ihtişamını dillendiriyordu, kuşlar da... Zira Biz, her zaman istediğimizi gerçekleştiririz."},{"n":80,"t":"Ve Biz ona, sizi korku ve zilletten kahredecek her belaya karşı koruyacak (manevi) savunma araçları geliştirmeyi öğrettik: Hal böyleyken siz (gereği gibi) şükrediyor musunuz?"},{"n":81,"t":"Kendisini bereketli kıldığımız ülkeye doğru esip O`nun emriyle (çalışan gemileri) yüzdürsün diye şiddetli rüzgarları Süleyman`a (amade kıldık): zira Biziz her şeyin (yasasına) vakıf olan."},{"n":82,"t":"Yine dik başlı birileri, hem onun için dalgıçlık yapıyorlar, hem de bunun dışında başka hizmetler görüyorlardı. Aslında onlara mukayyet olan da Biziz."},{"n":83,"t":"Eyyub`u da (gündeme taşı)! Hani o bir zamanlar; \"Bu dert gelip beni buldu, ama Sen merhametlilerin en merhametlisisin!\" diye Rabbine yalvarmıştı."},{"n":84,"t":"Biz de onun duasını kabul etmiş ve onu bizar eden dertten kurtarmıştık; dahası katımızdan bir rahmet ve gereği gibi kulluk edenlere bir öğüt olmak üzere, ona yakınlarını bir kat daha artırarak geri vermiştik."},{"n":85,"t":"İsmail`i, İdris`i ve yükümlülük alan kişiyi de (gündeme taşı); hepsi de sıkıntıya karşı direnen kimselerdendi:"},{"n":86,"t":"bu yüzden onları rahmetimize gark ettik: Zira onlar dürüst ve erdemli kimselerdendi."},{"n":87,"t":"Ve balık olayının kahramanını da (gündeme taşı)! Hani bir zamanlar o, hakkında işlem yapmayacağımızı düşünerek, öfkeyle (görev yerinden) çekip gitmişti. Derken o (düştüğü) zifiri karanlığın içerisinde \"İbadete layık başka ilah yok; sadece yüceler yücesi olan Sen varsın: hiç şüphesiz ben (bu tavrımla) zalimlerden biri olup çıktım!\" diye yakarmıştı."},{"n":88,"t":"Bunun ardından Biz de onun yakarışını kabul ettik ve onu içine düştüğü sıkıntıdan kurtardık: işte Biz, inanıp güvenenleri böyle kurtarırız."},{"n":89,"t":"Zekeriyya`yı da (gündeme taşı)! Hani bir zamanlar o \"Rabbim!\" diye yalvarmıştı; \"Beni (evlatsız) tek başına bırakma! Şu da var ki, Sen varislerin en hayırlısısın!\""},{"n":90,"t":"Ve Biz onun yakarışını da kabul ettik ve onun eşini kendisi için çocuk doğurmaya elverişli hale getirerek ona Yahya`yı armağan ettik. İşte bunların (üçü) de birbirleriyle hayırlarda yarışan kimselerdi; Bize bollukta da darlıkta da yalvarıp yakarırlardı: zira onlar Bize karşı derin bir saygı duyarlardı."},{"n":91,"t":"Bir de iffetini koruyan o kadını (gündeme taşı)! \"Kuşkusuz ona da ruhumuzdan üflemiş; onu ve oğlunu (çağının) bütün insanları için (rahmetimizin) bir belgesi kılmıştık."},{"n":92,"t":"(Ey insanlar!) İşte (burada kısaca anlatılan peygamberler tarihinin de gösterdiği gibi) sizin ümmetiniz bir tek ümmettir ve Ben sizin Rabbinizim: O halde sadece Bana kulluk edin!"},{"n":93,"t":"Ama onlar birliklerini aralarında paramparça ettiler: (oysa ki) hepsi de sonunda yine Bize dönecekler."},{"n":94,"t":"Neticede, kim iman etmiş olarak o imanla uyumlu davranışlar göstermeye gayret ederse, onun bu gayreti asla görmezden gelinmeyecektir: zira Biz, onun lehine bütün bunları kaydediyoruz."},{"n":95,"t":"Ne ki, Bizim helakine karar verdiğimiz bir toplum mecburi (istikamete girmiştir); artık onların geri dönmesi mümkün değildir;"},{"n":96,"t":"ta ki Ye`cuc ve Me`cuc`un salınıp, her bir köşeden boşalacakları zamana dek..."},{"n":97,"t":"İmdi, mutlaka gerçekleşecek olan sözün vakti yaklaşmıştır: işte o zaman, küfürde ısrar edenler, gözleri yuvalarından fırlamış bir halde \"Yazıklar olsun bize!\" (diyecekler), \"Doğrusu biz bu (söze) karşın gaflete dalmışız; dahası (böyle yapmakla) kendi kendimize kıymışız!\""},{"n":98,"t":"Şu kesin ki, siz de, Allah`tan başka taptıklarınız da cehennemin yakıtısınız: sizler ona mutlaka takdim edileceksiniz!"},{"n":99,"t":"Eğer (tanrılaştırdıkları) gerçek ilah olsalardı, oraya asla girmezlerdi: (ama) hepsi orada temelli kalacaklar:"},{"n":100,"t":"orada onların payına inim inim inlemek düşecek; ve onlar orada (iniltiden başka bir ses) duymayacaklar."},{"n":101,"t":"Ne var ki, katımızdan kendilerine iyilik-güzellik ihsan ettiğimiz kimselere gelince: işte onlar (cehennem)den uzak tutulacaklar."},{"n":102,"t":"Onlar oranın uğultusunu bile duymayacaklar. Ve onlar canlarının çektiği şeyler arasında kalıcı bir hayat sürecekler."},{"n":103,"t":"Onları, (kıyamete mahsus) o benzeri görülmemiş dehşetli panik dahi tasalandırmayacak; zira melekler kendilerini \"Bu, işte size vaad edilen o (mutlu) gündür!\" diye karşılayacaklar."},{"n":104,"t":"O gün Biz gökleri, kitap sayfalarını rulo yapar gibi dürüp katlayacağız; mahlukat (evrenini) ilk defa nasıl yaratmışsak, onu öylece tekrar yaratacağız. Bu üstlendiğimiz bir sözdür: zira Biz, evet Biz her istediğimizi hep gerçekleştirmişiz."},{"n":105,"t":"Ve doğrusu Biz, hatırlatıcı mesajların ardından, bütün ilahi vahiylerin hikmet yüklü sayfasına \"(Tekrar yarattığımız) bu yerin varisi salih kullarım olacak\" diye yazmışız."},{"n":106,"t":"Hiç şüphesiz bunda, Allah`a gereği gibi kulluk etmek isteyenler için nice mesajlar vardır."},{"n":107,"t":"İşte bu yüzden (Ey Peygamber), Biz seni bütün insanlığa, sadece bir rahmet olarak gönderdik."},{"n":108,"t":"De ki: \"Bana vahyolunan her şeyin (özü) yalnız ve yalnızca \"ilahınızın bir tek ilah olduğu\" yalın gerçeğidir: şu halde artık siz O`na teslim olacak mısınız?"},{"n":109,"t":"Fakat eğer (bu davetten) yüz çevirirlerse, o zaman da de ki: \"Ben bu daveti hiçbir ayrım gözetmeden hepinize duyurdum; ne var ki ben tehdit edildiğiniz (Hesap Günü`nün) yakın mı uzak mı olduğunu da bilemem.\""},{"n":110,"t":"Fakat (Allah) açıktan söyleneni nasıl bilirse, gizlediklerinizi de öylece bilir."},{"n":111,"t":"Ama ben; (bu ertelemenin) sizin için bir sınama ve kısa süreliğine verilmiş bir mühlet olup olmadığını herhalde bilemem.\""},{"n":112,"t":"(Allah`a yönel ve) de ki: \"Rabbim! Aramızda hakkaniyetle hüküm ver!\" (Onlara dön) ve (de ki): \"Kendisine yakıştırdığınız tüm (gerçek dışı) nitelemelere karşı kendisinden yardım istenecek tek merci, (yine) O sınırsız merhamet sahibi olan Rabbimizdir.\""}],[{"n":1,"t":"Ey insanlık! Rabbinize karşı sorumluluğunuzun farkında olun! Çünkü Son Saat`in depremi korkunç olacaktır!"},{"n":2,"t":"O (depremi) gördüğünüz gün, emziren her kadın emzirdiği (bebeğini) unutur; yine her gebe kadın (o an) çocuğunu düşürür; ve insanlar sarhoş olmadıkları halde sen onları sarhoşmuş (gibi) görürsün. Fakat, Allah`ın azabının (ondan) daha şiddetli olduğu kesindir."},{"n":3,"t":"Ne ki yine de insanlar içerisinden, Allah`ı bilmeden tartışma konusu yapan ve haddini bilmez her tür şeytanın peşine takılan kimseler çıkabilmektedir."},{"n":4,"t":"(Şeytan) hakkında kayıt şöyle tutulmuştur: Elbet onu veli edinenler çıkar; ve elbet (Şeytan) o tipleri saptırır ve yakıp kavurucu bir azaba yönlendirir."},{"n":5,"t":"Ey insanlık! Eğer (ölümden sonra) diriliş konusunda kuşku içindeyseniz, unutmayın ki Biz sizi (ilkin) bir tür topraktan, sonra bir damlacık döl suyundan, sonra rahim cidarına asılıp tutunan döllenmiş yumurtadan, sonra (asli unsurları) oluşmuş fakat (tali unsurları) henüz oluşmamış bir ceninden yarattık: bu size (menşeinizi) açıklamak için yaptığımız (bir uyarıdır). Derken, (doğmasını) dilediğimizi belirlenmiş bir süreye kadar (annelerinin) rahimlerinde tutarız; sonra sizi bir bebek olarak dünyaya getiririz; nihayet sizler olgunluk çağına, (işte bütün bu süreçlerden geçerek) ulaşırsınız: ama içinizden kimilerine ölüm (erken yaşlarda) tattırılır, kimileri de ömrün en düşkün çağına kadar ertelenir; öyle ki, sonunda o, bilen biriyken hiçbir şey bilmez hale gelir. (Bu, şuna benzer) ki; önce yeryüzünü kupkuru bir halde görürsün; fakat ona indirdiğimiz suyun ardından canlanır, kabarır ve her türden gözalıcı bitkilerle yeşerir."},{"n":6,"t":"Bütün bunların (gösterdiği) nihai bir amaç vardır ki, o da mutlak olanın yalnızca Allah olduğu gerçeğidir. Zira sadece O`dur ölüyü dirilten; ve her şeye gücü yeten de yalnızca O`dur."},{"n":7,"t":"Hem unutma ki, Son Saat kuşku götürmez bir biçimde gelip çatacaktır; yine unutma ki, Allah kabirlerde yatan herkesi kaldıracaktır."},{"n":8,"t":"Ne ki yine de insanlar içerisinden herhangi bir bilgiye, yol gösterici bir kılavuza ve aydınlatıcı bir kitaba dayanmaksızın Allah hakkında tartışan kimseler çıkabilmektedir."},{"n":9,"t":"Bunlar Allah yolundan çevirebilmek için (hakikati) eğip bükerler. Bu tipin dünyadaki payı onursuzluktur; ama Kıyamet Günü`nde ona yakıp kavurucu bir azabı tattıracak (ve diyeceğiz ki):"},{"n":10,"t":"\"İşte bu senin kendi ellerinde kazanıp getirdiklerindir; unutma ki Allah`ın kullarına zulmetme ihtimali asla bulunmamaktadır!\""},{"n":11,"t":"Yine insanlardan kimileri de vardır ki, Allah`a (iman ve küfrü birbirinden ayıran) sınırda kulluk eder; öyle ki, eğer kendisine bir iyilik dokunsa onunla tatmin olup sevinç duyar; fakat başına bir musibet gelse yüzüstü dönüverir; dünyayı da ahireti de kaybeder: nitekim telafisi en zor kayıp da budur."},{"n":12,"t":"O kimse, Allah dışında, kendisine ne zarar veren ne de yarar sağlayan nesnelere yalvarıp durur: kişiyi (haktan) uzaklaştıran en vahim sapıklık da zaten budur."},{"n":13,"t":"(Kimi zaman da) zararı yararından daha fazla olan insanlara yalvarıp yakarır: o ne berbat efendi, o ne kötü yoldaştır!"},{"n":14,"t":"Şüphesiz ki Allah iman eden, dürüst ve erdemli davrananları zemininden ırmaklar çağlayan cennetlere yerleştirecektir: Zira Allah dilediği şeyi mutlaka gerçekleştirir."},{"n":15,"t":"Her kim, Allah`ın kendisine dünya ve ahirette asla (doğrudan) yardım etmeyeceğini düşünüyorsa, bir sebebe tutunup göğe uzanıversin ve (Allah dışında yalvardıklarıyla ilişkiyi) kessin; daha sonra görsün bu tedbiri kendisini öfkelendiren şeyin kökünü kazıyacak mı (kazımayacak mı)?"},{"n":16,"t":"İşte böylece Biz, bu (mesajları) hakikatin apaçık belgeleri olarak indirmiş bulunuyoruz; ama şu da bir gerçek ki, Allah isteyen kimseyi doğru yola yöneltmeyi diler."},{"n":17,"t":"Şüphesiz (sizden) iman eden kimseler, yahudileşen kimseler, Sabiiler, Hıristiyanlar, Mecusiler ve şirk koşan kimseler arasındaki hükmü Kıyamet Günü Allah verecektir: kuşku yok ki Allah her şeye şahittir."},{"n":18,"t":"(Ey insan!) Göklerde ve yerde bulunan herkesin, güneşin, ayın, yıldızların, dağların, ağaçların ve hayvanların (ister istemez) Allah`ın emrine amade olduğunu görmez misin? İnsanlardan niceleri (bilinçli tercihlerinden dolayı ödülü hak etmiş), niceleri ise azabı hak etmişlerdir. İmdi, Allah her kimi alçaltırsa artık onu kimse yüceltemez: kuşkusuz Allah dilediğini daima gerçekleştirir."},{"n":19,"t":"Birbirlerine karşıt konumlarda bulunan bu iki gurup, Rableri konusunda hep çatışagelmişlerdir. Onlardan inkarda direnenlere, ateşten elbiseler biçilecek; başlarının üzerinden yakıp kavuran bir (gam) boca edilecek:"},{"n":20,"t":"bununla onların içlerinde olan her şey ve deriler eriyip akacak;"},{"n":21,"t":"ve onlar(ı bağlamak) için demirden boyunduruklar olacak;"},{"n":22,"t":"gam ve kederden (bunalıp) da ne zaman oradan çıkmak isteseler, hemen oraya geri döndürülecekler ve (onlara şöyle denilecek): \"Yakıp kavurucu azabı tadın bakalım!\""},{"n":23,"t":"Buna karşın Allah iman eden ve imanıyla uyumlu davranış sergileyenleri zemininden ırmaklar akan cennetlere yerleştirecek; orada onlar altın künye ve bilezikler takınıp incilerle bezenecekler: dahası orada sınırsız bir özgürlük üniforması taşıyacaklar."},{"n":24,"t":"Evet, onlar düşünülüp dile gelebilir olanın en iyisine yönlendirildiler; zira onlar (dünyadayken) bütün övgülere layık olanın (dosdoğru) yoluna yöneltilmişlerdi."},{"n":25,"t":"Fakat inkarda direnenleri, Allah yolundan ve yerli-yabancı ayrımı gözetmeden bütün insanlar için tayin ettiğimiz Mescid-i Haram`dan alıkoyanları, oralı olmayı sapıklığa ve haksızlığa bile isteye vesile kılanları, can yakıcı bir azaba terk edeceğiz."},{"n":26,"t":"Hani Biz, İbrahim`in (inşa ve ihya etmesi) için bu İbadet Evi`nin yerini tesbit ettiğimiz zaman; \"Bana hiçbir şeyi şirk koşmadığın gibi, Mabedimi de tavaf edecekler ve (ona doğru) kıyama durup rüku ve secdeye kapanacaklar için (şirkten) temiz tutacaksın!\" (demiştik)."},{"n":27,"t":"Ve insanları hacca davet et! Gerek yaya, gerekse hızlı yol alma yeteneğine sahip ulaşım araçlarına binerek her bir yoldan senin (çağrına) gelsinler"},{"n":28,"t":"ki, bunun kendilerine sağlayacağı yararlara tanık olsunlar. Bir de belirlenen günlerde, O`nun kendilerine rızık olarak sunduğu hayvanları (kurban ederken), üzerine Allah`ın adını ansınlar: işte bunlardan siz de yiyin, zor durumdaki ihtiyaç sahiplerine de yedirin."},{"n":29,"t":"En sonunda, zorunlu yasaklara son verip kirlerini gidersinler; adaklarını yerine getirsinler ve bu Özgürlük Evi`ni tavaf etsinler."},{"n":30,"t":"(Sözün özü) şudur ki; her kim Allah`ın kısıtlayıcı buyruklarına saygı gösterirse, bu Rabbi katında kendi yararına olacaktır; zaten size bildirilenler dışında kalan bütün hayvanlar size helal kılınmıştır. Ama özellikle de putla(ştırma)dan kaynaklanan her tür (manevi) pislikten sakının; bir de asılsız iddialardan kaçınarak,"},{"n":31,"t":"batıldan yüz çevirip yalnız Allah`a yöneldiğinizi ve O`ndan başkasına ilahlık yakıştırdımadığınızı (ispat edin): zira Allah`tan başkasına ilahlık yakıştıran kimse, gökten düşerek un ufak olan ve saçılan parçalarını kuşların didikleyip kaptığı, ya da rüzgarın ıssız bir köşeye savurduğu nesneye benzer."},{"n":32,"t":"(Sözün özü) işte şudur: Allah`ın sembollerine sarılarak onları yücelten herkes iyi bilsin ki, bu (semboller gerçek anlamını) kalplerde kök salan sorumluluk bilincinden alırlar."},{"n":33,"t":"(Sarıldığınız) bu semboller sonu yasayla belirlenmiş bir süre doluncaya kadar size yarar sağlamayı sürdürür; nihayet bu sembollerin gösterdiği güzergahı izleyenin varış yeri bu Özgürlük Mabedi olacaktır."},{"n":34,"t":"Ve Biz, her ümmet için kurban kesmeyi bir ibadet kıldık ki, bu vesileyle O`nun kendilerine rızık olarak verdiği hayvanlar üzerine Allah`ın ismini ansınlar. Bakın, ilahınız tek bir İlah`tır; o halde yalnız O`na teslim olun! Ve (sen de Ey Peygamber); O`na yürekten boyun eğenleri (O`nun rızasıyla) müjdele!"},{"n":35,"t":"Onlar ki, ne zaman Allah anılsa kalpleri saygıyla ürperir ve başlarına gelen şeylere sabrederler; üstelik namazı hakkını vererek kılarlar ve kendilerine verdiğimiz rızıktan çömertçe sarf ederler."},{"n":36,"t":"Malum kurbana gelince: Biz onu sizin için içerisinde nice hayırlar barındıran Allah`ın simgelerinden biri olarak (ibadet) kıldık: o halde, (ön ayaklarından biri bağlanıp) sıra sıra diz çöktürülen hayvanları kurban ederken Allah`ın ismini anın; nihayet onların yanı yere gelince artık ondan siz de yiyin, ihtiyacını belli eden ya da etmeyen herkese de yedirin: Bu böyledir; zira Biz onları sizin yararınıza amade kılmışızdır; umulur ki şükredersiniz."},{"n":37,"t":"Onların ne etleri, ne de kanları Allah`a ulaşır; fakat sizden O`na ulaşan yalnızca O`na karşı gösterdiğiniz derin sorumluluk bilincidir. Böylece onları sizin yararınıza amade kıldı ki, size yol gösterdiğinden dolayı Allah`ın yüceliğini layıkıyla takdir edesiniz; ve (sen Ey Peygamber,) iyileri (O`nun rızasına ermekle) müjdele!"},{"n":38,"t":"Hiç kuşku yok ki Allah inanıp güvenenleri savunacaktır; çünkü Allah ihaneti tabiat edinen hiç bir nankörü sevmez."},{"n":39,"t":"(İşte bu yüzden), kendilerine savaş açılan kimselere (savaş) izni verildi; zira onlar zulme uğramış kimselerdi: ve elbette Allah, onlara yardım edecek güce sahiptir."},{"n":40,"t":"Onlar ki, yalnızca \"Bizim Rabbimiz Allah`tır\" dedikleri için haksız yere yurtlarından çıkarıldılar. Zira eğer Allah insanların bir kısmını diğer bir kısmıyla savunmamış olsaydı, o zaman içerisinde Allah`ın adının çokca anıldığı nice manastırlar, kiliseler, havralar ve mescidler yıkılıp giderdi. Ama Allah kendi (davasına) destek verenlere elbette yardım edecektir: çünkü Allah aklın almayacağı kadar güçlü ve yücedir."},{"n":41,"t":"Bu kimseler ki, eğer onlara yeryüzünde iktidar versek namazı hakkını vererek eda ederler; arınmak için ödenmesi gereken bedeli öderler; iyi, doğru ve yararlı olanı emreder, kötü, yanlış ve zararlı olandan da sakındırırlar. En nihayetinde işlerin sonucunu belirlemek Allah`a aittir."},{"n":42,"t":"İmdi, eğer seni yalanlıyorlarsa, unutma ki onlardan çok daha önce Nuh, Ad ve Semud kavmi de (kendi peygamberlerini) yalanlamışlardı."},{"n":43,"t":"Yine İbrahim kavmi de, Lut kavmi de,"},{"n":44,"t":"Ve Medyen ahalisi de. Sonra Musa da yalanlandı. Ben ise o kâfirlere önce süre tanıdım; sonra da onları yakalayıverdim. Nasıl oluyormuş Benim onları inkârım?"},{"n":45,"t":"İşte bu yüzden çığırdan çıkmış nice kentleri helak ettik. Nihayet hepsi de tepe taklak gitti, şimdi yerlerinde yeller esiyor. (Geriye) terkedilmiş kuyular (kaldı); o heybetli saraylar(dan şimdi eser yok)."},{"n":46,"t":"İyi ama, onlar hiç mi yeryüzünde gezip dolaşmazlar? Bu sayede kendisiyle akledecekleri bir kalbe ya da işitecekleri bir kulağa sahip olsalardı ya! Ama şu da var ki; gözler kör olmaz, fakat asıl kör olan göğüslerdeki kalplerdir."},{"n":47,"t":"Bir de kalkmış, azabın çabuk gelmesi için seni sıkıştırıyorlar. Ama Allah sözünden asla caymaz; ve unutmayın ki, Senin Rabbin katında bir gün sizin hesabınıza göre tut ki bin yıldır;"},{"n":48,"t":"ve Ben, zulme gömülüp gitmiş nice toplumlara (önce) süre tanımış, sonra enselemişimdir: nihayet dönüş Banadır."},{"n":49,"t":"(Ey Peygamber!) De ki: \"Ey insanlar! Şu bir gerçek ki, ben size gönderilmiş açık (sözlü) bir uyarıcıyım."},{"n":50,"t":"Ve işte (Allah`tan aldığım uyarı): İmanda sebat eden, o imanla uyumlu ıslah edici davranışlarda bulunan kimseleri sınırsız bir bağış ve tarifsiz güzellikte bir rızık beklemektedir."},{"n":51,"t":"Ama ayetlerimizi etkisiz kılmak için çaba harcayanlara gelince: işte onlar, gözlerini faltaşı gibi açacak dehşet bir ateşe duçar olacaklar."},{"n":52,"t":"Hem senden önce kimi rasul ve nebi olarak göndermişsek, (sonuç almayı) umdukları her seferinde, Şeytan mutlaka onun idealindeki amaca ilişkin beklentisine gölge düşürmeye çabalamıştır. Fakat Allah, Şeytan`ın çabasını boşa çıkarır; dahası Allah, ayetlerini kendi içinde açık ve birbirlerini açıklayıcı kılar: zira (yalnızca) Allah`tır her şeyi bilen, her hükmünde tam isabet kaydeden."},{"n":53,"t":"(Allah`ın) Şeytan`ın engel koyma çabasına (izin vermesi), yalnızca kalplerinde bir tür hastalık bulunan ve iç dünyaları kararmış olan kimseleri sınamak içindir. İşte bu tür zalimler, kesinlikle derin bir yabancılaşma içindedirler."},{"n":54,"t":"Yine (bunun bir nedeni) de, bilgi ve bilginin amacını kavrayanlar bu (mesajın) Rabbinden gelen hakikatin ta kendisi olduğunu anlasınlar diyedir. Bu sayede ona inanacaklar, nihayet kalpleri ona tam bir teslimiyetle yatışacaktır. Şu bir gerçek ki, Allah inanıp güvenen kimseleri dosdoğru bir yola yöneltir."},{"n":55,"t":"İnkarda direnen kimseler ise, Son Saat kendilerine ansızın gelip buluncaya, ya da (yaşama sevincinin) kökünü kurutan bir günün tarifsiz azabı kendilerine kavuşuncaya kadar, bu mesajın kaynağı hakkında kuşku duymaya devam edecekler."},{"n":56,"t":"Hakimiyetin tamamı o gün, sadece Allah`a ait olacaktır. O onları yargılayıp aralarında hüküm verecektir. İşte bunun sonucunda iman eden ve o imanla uyumlu davranış sergileyen kimseler, her tür nimetle dolu olan cennetlere yerleşecekler."},{"n":57,"t":"Ama inkarda inat eden ve Bizim ayetlerimizi yalanlayanlara gelince, işte onlar, onur kırıcı bir terkedilmişliğe mahkum olacaklar."},{"n":58,"t":"Bir de, Allah davası uğruna yurdunu yuvasını terk ettikten sonra öldürülen ya da ölen kimseler var; Allah onlara mutlaka tarifsiz güzellikte bir rızık bahşedecektir: zira Allah, evet, elbet O`dur rızık bahşedenlerin en hayırlısı."},{"n":59,"t":"Kesinlikle onları hoşnut olacakları bir makama kavuşturacaktır; zira şu bir gerçek ki, Allah (onların her birinin neden razı olacaklarını) çok iyi bilen, (isyankar kullarını cezalandırmada) hiç acele etmeyendir."},{"n":60,"t":"(Sözün özü) şudur ki; kendisine yapılan saldırıya misliyle karşılık veren kimse, bunun ardından yine insafsız bir saldırıya maruz kalırsa, Allah böyle birine kesinlikle yardım edecektir: elbette Allah, affetmeyi çok seven tarifsiz bir bağışlayıcıdır."},{"n":61,"t":"Bunun (yasası) budur; zira baksanıza Allah gündüzü kısaltıp geceyi uzatıyor, geceyi kısaltıp gündüzü uzatıyor! Ne var ki Allah, her (yardım çağrısını) işitir ve (haksızlığa uğrayan) herkesi görür."},{"n":62,"t":"Bunun böyle olması (doğaldır); zira mutlak hakikat Allah`ın ta kendisidir; ve onların O`nun dışında yalvarıp yakardıklarıysa batılın ta kendisidir: ve şüphe yok ki Allah, yüceler yücesi, büyükler büyüğüdür."},{"n":63,"t":"(Ey insan!) Görmez misin ki, gökten su indiren Allah`tır? Ki bu sayede yeryüzü yeşillenmektedir. Çünkü Allah dilediği şeyi cömertçe lütfeder, (nankörün nankörlüğünden) haberdar olur."},{"n":64,"t":"Göklerde ve yerde var olan her şey bütünüyle sadece O`na aittir: Ve kuşkusuz Allah, elbet O kendi kendine yeterli olandır ve her tür övgüye layık olandır."},{"n":65,"t":"(Ey insan!) Görmez misin ki yeryüzünde bulunan her şeyi sizin için bir yasaya bağlayan; ve (buna) bağlı olarak denizde seyreden gemileri emrinize amade kılan; ve gök (cisimlerinin O izin vermedikçe yeryüzüne çarpmasına (yasalarıyla) engel olan Allah`tır: Şüphe yok ki Allah insanlara karşı pek şefkatli, hep merhametlidir."},{"n":66,"t":"Zira size hayat bahşeden, sonra size ölümü tattıracak olan, ardından sizi diriltecek olan yine O`dur. Şu bir gerçek ki insanoğlu, (bütün bunlara rağmen) nankörlükte ısrarcıdır."},{"n":67,"t":"Biz her bir ümmet için Allah`a kalben yaklaşsınlar diye bir ibadet yol ve yöntemi belirledik; şu halde (ey bu hitabın muhatabı), kimse seni bu konuda tartışmaya çekmesin; ve sen sadece Rabbine çağır: şu bir gerçek ki sen kesinlikle dosdoğru bir yol üzeresin."},{"n":68,"t":"Ve eğer seninle ille de tartışmak isterlerse, onlara de ki: \"Allah, yaptıklarınızın (altında yatan gerçek nedenleri) çok iyi biliyor\"."},{"n":69,"t":"Allah, tartışıp durduğunuz konuda Kıyamet Günü aranızdaki hükmü verecektir."},{"n":70,"t":"(Ey bu hitabın muhatabı!) Bilmez misin ki Allah, gökte ve yerde olup biten her şeyi bilir? Çünkü bunların tamamı (yasalarla) bir bir kayıt altına alınmıştır: nitekim bu Allah için çok kolaydır."},{"n":71,"t":"Ne ki (bazıları hem Allah`a inanıp, hem de) Allah`tan başka, O`nun haklarında hiçbir delil indirmediği ve kendilerinin de haklarında sahici bir bilgiye sahip olmadıkları varlıklara kulluk ediyorlar. Herhalde bu zalimlerin hiçbir yardımcısı olmayacaktır."},{"n":72,"t":"Ve ne zaman kendilerine hakikatin apaçık belgeleri olan ayetlerimiz okunsa, inkarda direnenlerin suratlarındaki inkarı hemen fark edersin. Öyle ki, neredeyse ayetlerimizi okuyanlara saldıracak gibidirler: De ki: \"Bakın, sizi bundan daha beter (kızdıracak) bir haber vereyim mi: O, Allah`ın inkarda ısrar edenlere vaat ettiği ateştir; o ne berbat bir son duraktır!\""},{"n":73,"t":"Siz ey insanlık! Bir misal veriliyor, şimdi onu dinleyin: Allah dışında yalvarıp yakardığınız o varlıkların hiç biri, asla bir sinek bile yaratamazlar; bu iş için hepsi bir araya toplansa dahi... Dahası, eğer sinek kendilerinden bir şey kapıp kaçacak olsa, ondan onu dahi geri alamazlar: (zira) almak isteyen de aciz, kendisinden alınmak istenen de!"},{"n":74,"t":"Onlar, Allah`ın gücünü gereği gibi kavrayıp takdir edemiyorlar: nitekim Allah her şeye muktedir olan yüce bir otorite sahibidir."},{"n":75,"t":"(Dolayısıyla) Allah meleklerden de elçiler seçer, insanlardan da. Ne var ki sadece Allah her bir şeyi duyar, her bir şeyi görür."},{"n":76,"t":"(Yine) O onların bildiklerini de bilir, bilmediklerini de: neticede her iş ve oluş döner dolaşır Allah`a varır."},{"n":77,"t":"Siz ey iman edenler! Sadece (Allah`ın huzurunda) eğilin! O`nun sizin için koyduğu yasaya tabi olun ve yalnızca Rabbinize kulluk edin! Bir de hayırlı işler yapın ki ebedi kurtuluşa nail olasınız!"},{"n":78,"t":"Ve Allah uğrunda üstün çaba sarf ederek gereği gibi mücadele edin: O (mesajını hayata taşımak için) sizi seçti; ve O din konusunda sizi zora koşmadı. (Sizden tek istediği) atanız İbrahim`in inanç sistemine (tabi olmanız). O sizleri bundan önce de bu vahyin (gelişinden) sonra da müslüman olarak isimlendirdi ki, elçi sizin için iyi bir model ve tanık olsun, siz de insanlık için iyi bir model ve tanıklar olasınız. Şu halde, artık namazı hakkını vererek kılın ve zekatı içten gelerek verin; bir de Allah`a sımsıkı bağlanın: O`dur sizin tek efendiniz; O ne güzel koruyup kurtarıcı, ve O ne güzel yardımcıdır!"}],[{"n":1,"t":"Doğrusu, gereği gibi inananlar gerçek kurtuluşa erecekler:"},{"n":2,"t":"Onlar ki, namazlarında derin bir ürperti ve tevazu içinde olurlar;"},{"n":3,"t":"onlar ki, yararsız her şeyden yüz çevirirler;"},{"n":4,"t":"onlar ki, arınmak için gerekeni yaparlar;"},{"n":5,"t":"onlar ki, iffetlerini korurlar; -"},{"n":6,"t":"fakat kendi eşleri, yani meşru olarak sahip oldukları müstesna; zaten onlar (meşru eşleriyle paylaştıkları cinsellikten dolayı) kınanamazlar."},{"n":7,"t":"Ama bu sınırın ötesine geçen kimseler, haddi aşmış olanlardır-"},{"n":8,"t":"yine onlar ki, emanetlerine ve verdikleri sözlere riayet ederler;"},{"n":9,"t":"ve onlar ki, namazları üzerine titizlenirler."},{"n":10,"t":"İşte onlar, (mutluluk yurduna) varis olacak kimselerdir:"},{"n":11,"t":"onlar ki, görkemli cennetlerin mirasçısı olacaklar, onlar orada ebedi kalacaklar."},{"n":12,"t":"Doğrusu Biz insan türünü, bir nevi konsantre bir balçıktan yarattık;"},{"n":13,"t":"epey sonra onu, karar kılacağı (rahimde) yer tutan bir hayat tohumu kıldık;"},{"n":14,"t":"Sonra da, o tohumu rahim duvarına yapışan yapışkan bir madde yaptık. Ardından, bu yapışkan maddeyi bir çiğnem et gibi görünen bir cisme dönüştürdük; bunu müteakiben, bu bir çiğnem et görünümündeki cismi kemikler haline getirdik; derken bu kemiklere et giydirdik. Nihayet onu, (kendisine ruh üfleyerek) bir başka yaratılışta ortaya çıkardık. O eşsiz, emsalsiz en güzel yaratıcı olan Allah ne yücedir, bütün nimet ve bereketlerin asıl kaynağıdır!"},{"n":15,"t":"Ve kuşku yok ki siz, bu sürecin ardından elbette öleceksiniz."},{"n":16,"t":"Yine kuşku yok ki siz, Kıyamet Günü (tekrar) diriltileceksiniz."},{"n":17,"t":"Doğrusu yine Biz, sizin üzerinizde kat kat yollar yaratmışız: zira Biz hiçbir varlıktan habersiz değiliz."},{"n":18,"t":"Ve gökten suyu bir yasaya bağlı olarak Biz indirmekteyiz; ve yeryüzünde onu tutmaktayız; şu da var ki Biz, onu gidermeye elbette kadiriz."},{"n":19,"t":"Ve nihayet onunla sizin için hurma bahçeleri ve üzüm bağları yeşertmekteyiz; orada sizin için bir çok meyve bulunmakta ve onunla beslenmektesiniz."},{"n":20,"t":"Yine Sina Dağı (havalisinde) yetişen, ürünü sayesinde yağ elde edilen ve yiyenler için hoş bir katık sağlayan (zeytin) ağacından da..."},{"n":21,"t":"Yine, evcil hayvanlarda da sizin için elbet bir ibret vardır: onların karınlarında bulunan sütten size içiriyoruz; ve sizin için onlarda bir çok yarar bulunuyor; üstelik onlar sayesinde besleniyorsunuz."},{"n":22,"t":"Onlara (karada), tıpkı (denizdeki) gemilere (olduğu gibi) yük taşıtırsınız."},{"n":23,"t":"Doğrusu Nuh`u kendi kavmine gönderen de yine Bizdik. Nitekim, onlara demiştik ki: \"Ey kavmim! Yalnız Allah`a kulluk edin! Sizin O`ndan başka bir ilahınız bulunmamaktadır: hala sorumluluk bilinciyle hareket etmeyecek misiniz?\""},{"n":24,"t":"Bunun üzerine, kavminin seçkinlerinden inkarda ısrar eden kimseler şöyle dedi: \"Bu da, sadece sizin gibi ölümlü bir insan, onun amacı size üstünlük sağlamak; hem eğer Allah isteseydi, gökten bir melek indiriverirdi; (üstelik) bizler, bu konuda önder atalarımızdan bir şey işitmiş de değiliz."},{"n":25,"t":"O ise, sadece aklını kaçırmış biri: artık siz de onu bir süre gözetim altında tutarsınız."},{"n":26,"t":"(Nuh) demişti ki: \"Rabbim! Onların beni yalanlamalarına karşı bana yardım et!\""},{"n":27,"t":"Bunun üzerine ona şöyle vahyetmiştik: \"Bizim rehberliğimiz altında ve bildirdiğimiz şekilde gemiyi inşa et; unutma ki hükmümüzün vakti gelip çattığında, tandır da kaynamaya başlar. Bu takdirde sen yanına her tür (canlıdan) birer çift ve bir de kendileri hakkında hüküm kesinleşmiş olanlar hariç, aile efradını al! Ama sakın kendilerine kıymakta ısrar eden kimseler hakkında Benimle muhatap olayım deme! Karar kesin: onlar boğulacaklar!"},{"n":28,"t":"Ardından sen ve beraberinde bulunanlar gemiye yerleşir yerleşmez deyin ki: \"Zalim kavimden bizi kurtaran Allah`a sonsuz hamdü senalar olsun!\""},{"n":29,"t":"Bir de \"Rabbim!\" diye yalvar, \"Beni bereketli bir yere ulaştır; zira Sen kişiyi (maksadına) ulaştıranların en hayırlısısın!\""},{"n":30,"t":"Elbet bunda, (akleden kimseler için) işaretler vardır; ve elbet Biz (öncekileri) de sınavdan geçirmişizdir."},{"n":31,"t":"Daha sonra bunların peşinden, başka bir nesli (tarih sahnesine) çıkardık."},{"n":32,"t":"Ve onların içinden de, kendilerine \"Yalnız Allah`a kulluk edin! Sizin O`ndan başka bir ilahınız bulunmamaktadır: hala sorumluluk bilinciyle hareket etmeyecek misiniz?\" diyen bir elçi gönderdik."},{"n":33,"t":"Bunun üzerine, kavminin seçkinlerinden inkarda ısrar eden ve ahiret gerçeğiyle yüzleşeceğini yalanlayan kimseler -ki bunları Biz dünya hayatında refaha kavuşturmuştuk- şöyle demişlerdi: \"Bu da sizin gibi ölümlü birinden başkası değil; sizin yediğinizden yiyor, sizin içtiğinizden içiyor."},{"n":34,"t":"Hal böyleyken kalkar da sizin gibi ölümlü birine tabi olursanız, o takdirde kaybeden mutlaka siz olursunuz."},{"n":35,"t":"Bu kişi siz ölüp gittikten, toza toprağa karışmış bir iskelet halini aldıktan sonra, sizin (Allah`ın huzuruna) çıkartılacağınızı mı iddia ediyor?"},{"n":36,"t":"Uzak, hem de çok uzak size iddia edilen bu şey!"},{"n":37,"t":"Hayat, bu dünyada yaşadığımızdan ibarettir: ölürüz ve (bir kez) yaşamış oluruz ve bir daha da diriltilmeyiz!"},{"n":38,"t":"Bu adam, sadece uydurduğu yalanı Allah`a isnat eden biri; bizim ona inanmamız ihtimal dışıdır!\""},{"n":39,"t":"(Elçi) dedi ki: \"Rabbim! Onların beni yalanlamalarına karşı bana yardım et!\""},{"n":40,"t":"(Allah) buyurdu ki: \"Az kaldı, yakında bin pişman olacaklar!\""},{"n":41,"t":"Derken mutlak hakikatin üstün gücü, onları sarsıcı bir bela çığlığı halinde kuşattı. Sonuçta onları selin sürüklediği çer çöpe çevirdik: evet, uzak olsun bu zalimler güruhu!"},{"n":42,"t":"Daha sonra, bunların peşinden de başka birtakım uygarlıkları (tarih sahnesine) çıkardık;"},{"n":43,"t":"herhangi bir toplum sonu yasayla belirlenmiş süresini ne savuşturabilir, ne de erteleyebilir."},{"n":44,"t":"Daha sonra, birbiri ardınca elçilerimizi gönderdik: her bir topluma kendi elçisi geldi, (ama) onu yalanladılar; bu yüzden biz de onların (akıbetini) birbirine benzettik; ve hepsini efsaneye çevirdik: artık, uzak olsun imansızlar güruhu!"},{"n":45,"t":"Daha sonra, Musa ve kardeşi Harun`u mesajlarımızla ve kendilerini açık ara önde kılan bir güçle,"},{"n":46,"t":"Firavun ve onun önde gelen çevresine gönderdik; çünkü onlar büyüklük taslamıştılar; zaten öteden beri hep tepeden bakan bir güruhtular."},{"n":47,"t":"İşte onlar dediler ki; \"Ne yani, o ikisinin kavmi bizim kölelerimiz olduğu halde, biz bizim gibi iki ölümlü insana mı inanalım?\""},{"n":48,"t":"Böylece onları yalanladılar; bu yüzden de helake uğrayanlardan oldular."},{"n":49,"t":"Ama doğrusu Biz Musa`ya ilahi mesajı, belki onlar doğru yolu bulurlar diye vermiştik."},{"n":50,"t":"Yine (aynı amaçla) Meryem oğlunu ve annesini de birer simge kıldık; ve o ikisini kalıcı bir güzelliğin görkemli makamına ve esenliğin bereketli kaynağına yerleştirdik."},{"n":51,"t":"(Onları izleyenlere dedik ki): \"Siz ey elçiler(in tabileri)! (Dünya nimetlerinin) temiz ve helal olanlarından yiyin, doğru ve yararlı şeyler yapın! Çünkü Ben, yaptığınız her şeyin bilgisine detaylarına vakıfım."},{"n":52,"t":"Kesinlikle bu (elçilerin takipçilerinden oluşan) ümmetiniz bir tek ümmettir ve Ben de sizin (bir tek) Rabbinizim: şu halde Bana karşı sorumluluğunuzu yerine getirin!\""},{"n":53,"t":"Bu (emre) karşın, onlar aralarındaki birliği darmadağın edip (hakikati) parçaladılar: her hizip başladı elindeki (parçayla) övünmeye."},{"n":54,"t":"Artık onları bir vakte kadar, gömüldükleri gafletleriyle baş başa bırak da işine bak;"},{"n":55,"t":"şimdi onlar, bol bol servet ve evlat verdik diye"},{"n":56,"t":"Bizim kendilerinin (mevcut hallerini) onayladığımızı sanıyorlar, öyle mi? Asla! Fakat onlar (bunun bile) farkında değiller."},{"n":57,"t":"Şüphesiz Rablerine karşı duydukları derin bir saygıdan dolayı tir tir titreyenler,"},{"n":58,"t":"Rablerinin mesajlarına inananlar,"},{"n":59,"t":"Rablerine şirk koşmayanlar,"},{"n":60,"t":"en sonunda yine Rablerine döneceklerine inandıklarından, yüreklerinde tarifsiz bir ürperti duyarak vermeleri gerekeni verenler:"},{"n":61,"t":"işte onlardır hayırlarda öne geçmek için can atanlar; nitekim onlardır bu konuda öne geçecek olanlar."},{"n":62,"t":"Ve Biz hiç kimseye gücünün üstünde yük yüklemeyiz; zira Bizim katımızda hakkı-hakikati olduğu gibi dile getiren bir kayıt tutulmaktadır: sonuçta onlar asla zulme uğramayacaklar."},{"n":63,"t":"Fakat kalpleri, bu (ilahi kayıt işlemine) karşı derin bir gaflet içinde olanlar da (var). İşte onlar, bundan daha aşağılık işler de çeviriyorlar: bunlar da o yolda çabalayıp giderler;"},{"n":64,"t":"Nihayet onların refah içinde yüzenlerini azapla yakalayıveririz; işte o zaman feryada başlarlar."},{"n":65,"t":"Bugün imdat dilemeyin; çünkü Bizden size asla yardım ulaştırılmayacak!"},{"n":66,"t":"Hem evvelce mesajlarımız size ulaştırılmıştı. Buna rağmen siz ısrarla arkanızı dönüyordunuz;"},{"n":67,"t":"ona karşı böbürlenerek, sokulduğunuz karanlığın koynunda atıp tutuyordunuz."},{"n":68,"t":"İyi de, onlar (bu) sözü hiç mi düşünmediler? Ya da kendilerinden önce gelip geçmiş atalarına hiç ulaşmamış olan bir şey mi gelmiş onlara?"},{"n":69,"t":"Veya elçilerini tanımadılar da, bu yüzden mi onu inkar ediyorlar?"},{"n":70,"t":"Ya yoksa, onu cinnet geçirmekle mi suçluyorlar? Yoo, aksine o onlara gerçeği getirdi; ama onların çoğu katıksız gerçeği sevmiyor."},{"n":71,"t":"Eğer hak, onların arzularına uysaydı, elbette gökler ve yer ile bunlarda bulunanlar bozulur giderdi. Hayır, biz onlara şan ve şereflerini getirdik, fakat onlar kendi şereflerine sırt çevirdiler.[358]"},{"n":72,"t":"Yoksa sen onlardan (hakka davet karşılığında) dünyevi bir bedel mi istiyorsun? (Hayır), çünkü senin Rabbinin ödeyeceği bedel daha yüksektir: zira rızık verenlerin en hayırlısı O`dur."},{"n":73,"t":"Sen onları gerçekten de dosdoğru bir yola çağırıyorsun,"},{"n":74,"t":"ahirete inanmamakta direnen kimselerse ısrarla bu yoldan sapıyorlar."},{"n":75,"t":"Ve eğer onlara acıyarak başlarına gelen herhangi bir beladan kendilerini kurtarsak, şaşkın şaşkın saplandıkları inkar bataklığında debelenmekte ısrar ederler."},{"n":76,"t":"Doğrusu Biz onları azab ile kuşatmıştık da, yine de Rablerine boyun eğmemişlerdi. Nitekim bundan böyle de acziyetlerini itiraf edecek değiller."},{"n":77,"t":"Ta ki vakti gelip de onlar aleyhine bir azap kapısı açıncaya dek: o zaman da onlar, orada, umutlarının tamamını yitiriverecekler."},{"n":78,"t":"İmdi sizi işitme, görme ve düşünme yeteneğiyle inşa eden O`dur: ne kadar da azınız şükrediyor!"},{"n":79,"t":"Sizi yeryüzüne yayan da O`dur, yine O`na döndürüleceksiniz."},{"n":80,"t":"Yine O hayat verir ve ölümü takdir eder; gece ve gündüzün birbirinin yerine geçmesi de O`nun eseridir: peki, hala akletmeyecek misiniz?"},{"n":81,"t":"Aksine, öncekiler ne dediyse onlar da aynısını söylediler:"},{"n":82,"t":"\"Ne yani\" dediler, \"biz ölüp gittikten, toza toprağa karışmış bir iskelet halini aldıktan sonra tekrar mı diriltileceğiz?"},{"n":83,"t":"Doğrusu bu, bize ve bizden önceki atalarımıza da vaad edilmişti; ne ki bu eskilerin mesajlarından başka bir şey değildir!\""},{"n":84,"t":"De ki: \"Yer ve ondaki varlıklar kime aittir, eğer biliyorsanız (cevaplasanıza)?\""},{"n":85,"t":"\"Allah`a aittir\" diyecekler. De ki: \"O halde, hala (onurunuzu) hatırlamayacak mısınız?"},{"n":86,"t":"de ki: \"Hem yedi göğün, hem de mutlak hükümranlık tahtının yegane Rabbi kimdir?\""},{"n":87,"t":"\"Allah`tır\" diyecekler. De ki: \"O halde, hala sorumluluğunuzun bilincine varmayacak mısınız?\""},{"n":88,"t":"De ki: \"Her şeyin hakimiyetini elinde tutan, (her varlığı) kollayıp kayırdığı halde kendisi kimsenin koruyup kollamasına muhtaç olmayan kimdir, biliyorsanız (söylesenize)?\""},{"n":89,"t":"\"Allah`tır\" diyecekler. De ki: \"O halde, nasıl büyülenmiş (gibi) davranabiliyorsunuz?\""},{"n":90,"t":"Yoo! Aksine Biz onlara saf gerçeği sunmuştuk, ama onlar ısrarla yalana sarıldılar."},{"n":91,"t":"Allah asla herhangi bir çocuk edinmemiştir; O`nunla birlikte başka bir ilah da yoktur. Aksi halde her bir ilah kendi yarattığını kendinden yana çeker, böylece biri diğerine üstünlük kurmaya kalkardı. Allah onların tavsif ve tasavvur ettiklerinin çok ötesinde, aşkın ve uludur."},{"n":92,"t":"O, insan idrakinin algılamaktan aciz olduğu şeylerin de, algılayabildiği şeylerin de sırrına vakıftır: nitekim O, onların Zatına yakıştırdıkları her türlü ortaktan beridir."},{"n":93,"t":"De ki: \"Rabbim! Eğer onları tehdit ettiğin azabı bana ille de göstereceksen,"},{"n":94,"t":"“Bu takdirde Rabbim, beni bu zalimler güruhunun içinde bulundurma!”"},{"n":95,"t":"Ne ki Biz, onları tehdit ettiğimiz azabı (her hal ve şartta) sana göstermeye elbette kadiriz."},{"n":96,"t":"Her çirkin saldırıya karşı öyle bir savunma yap ki, en güzeli, en uygunu o olsun; Biz onların yakıp yakıştırdıklarını elbette biliriz."},{"n":97,"t":"Ve de ki: \"Rabbim! Şeytanların ayartmalarından Sana sığınırım!"},{"n":98,"t":"Onların yaklaşımlarından da Rabbim, sana sığınırım!\""},{"n":99,"t":"Nihayet o (inkarcı)lardan birine ölüm gelip çatınca, \"Rabbim!\" der, \"Döndür ne olur, geri döndür beni;"},{"n":100,"t":"belki ben, daha önce yapmadıklarımın yerine doğru dürüst işler yaparım!\" Kesinlikle hayır! Çünkü onun dile getirdiği, sadece muhatabı etkilemek için sarf edilmiş bir laftır; nitekim böylelerini arkalarından, dirilecekleri güne kadar (aşamayacakları) bir engel kuşatmıştır!\""},{"n":101,"t":"Ve kalk borusu çaldığı zaman, artık o gün ne aralarındaki soy yakınlığı işe yarar ne de birbirlerine (olan biteni) sorabilirler."},{"n":102,"t":"Derken, kimin (iyilikleri) tartıda ağır gelirse işte kurtuluşa erenler onlar olacaktır."},{"n":103,"t":"Ama kiminki de hafif gelirse, cehennemde yerleşip kalmak üzere kendilerini harcayanlar da onlar olacaktır."},{"n":104,"t":"Ateş onların suratlarını kavuracak; sırıtan dişleriyle öylece kalakalacaklar."},{"n":105,"t":"(Allah diyecek ki): \"Ayetlerim size okunmamış mıydı? Ama siz onları ısrarla yalanladınız!\""},{"n":106,"t":"\"Rabbimiz!\" diyecekler, \"Talihimiz yaver gitmedi, bu yüzden biz de sapıtan bir güruh olup çıktık!"},{"n":107,"t":"Rabbimiz! Bizi buradan çıkar! Eğer tekrar dönersek, o zaman anlaşılır ki bizler gerçekten zalimleriz!"},{"n":108,"t":"(Allah) diyecek ki: \"Kalın tıkıldığınız yerde ve bana cevap yetiştirmeyin!"},{"n":109,"t":"Çünkü kullarımın arasında bir gurup vardı. Onlar \"Rabbimiz! Biz iman ettik: o halde bizi bağışla, bize merhamet et! Zira merhametlilerin en hayırlısı Sensin!\" diyorlardı."},{"n":110,"t":"Ne varki siz onlarla alay ettiniz. En sonunda onlar(la alayınız) size beni hatırlamayı unutturdu; üstelik bir de onların halini gülünç buluyordunuz."},{"n":111,"t":"Bakın işte, sabırlarından dolayı onları bugün ödüllendirdim: şüphesiz ki gerçek başarıya erenler işte onlardır."},{"n":112,"t":"(Allah azaptakilere) diyecek ki: \"Yeryüzünde kaç yıl kaldınız?\""},{"n":113,"t":"Onlar cevap verecekler: \"Bir gün ya da bir günden daha az; istersen bunu sayı bilenlere sor!\""},{"n":114,"t":"(Allah şöyle diyecek): \"Yalnızca kısa bir süre kaldınız: Keşke siz, bunu olsun bilseydiniz!\""},{"n":115,"t":"Yoksa sizi boş yere ve anlamsız bir oyun için yarattığımızı mı sanıyorsunuz? Dahası, (hesap vermek için) Bize döndürülmeyeceksiniz, öyle mi?"},{"n":116,"t":"Ama bakın, Allah (sizin tasavvur ettiğinizden) çok daha yüce ve uludur; mutlak otorite ve aşkın gerçeklik sahibidir; O`ndan başka ilah yoktur, sınırsız lütuf ve merhamet tahtının da Rabbidir."},{"n":117,"t":"Şu halde her kim, konu hakkında hiç bir ikna edici delili olmadan Allah`la beraber başka bir ilaha dua ederse, iyi bilsin ki bunun hesabı Rabbinin huzurunda mutlaka görülecektir: şu kesin ki, inkar edenler asla kurtuluşa eremeyecekler."},{"n":118,"t":"İmdi, (ey bu vahyin muhatabı): \"Rabbim!\" de, \"Bağışla! Merhamet et! Zira merhamet edenlerin en hayırlısı Sensin!\""}],[{"n":1,"t":"Bu, Bizim indirdiğimiz, kesin ve ayrıntılı hükümleri açıkladığımız bir suredir; ve Biz onda hakikatin apaçık belgesi olan ayetler indirdik ki, sorumluluğunuzu hatırlayasınız."},{"n":2,"t":"Zina eden kadın ve zina eden erkek: işte bunlardan her biri için, etkisi cilt ile sınırlı yüz vuruş yapın; eğer Allah`a ve Ahiret Günü`ne inanıyorsanız, o ikisine olan acıma duygunuz sizi Allah`ın hükmünü uygulamaktan alıkoymasın; inananlardan bir gurup da onların cezalandırılmasına tanık olsun."},{"n":3,"t":"Zina yapan erkek ancak zinakar bir kadınla; -diğer bir ifadeyle, cinsel güdülerine kul-köle olan bir kadınla- birlikte olur. Zina eden bir kadın da ancak zinakar bir erkekle; -diğer bir ifadeyle, cinsel güdülerine kul-köle olan bir erkekle- birlikte olur: zaten bu tür bir (birleşme) inananlara haram kılınmıştır."},{"n":4,"t":"İffetli kadınları (zinayla) suçlayıp da, ardından buna dört tanık getirmeyen kimselere gelince: işte böylelerine seksen celde vurun, bir daha da onların tanıklığını kabul etmeyin: zira gerçekte kötü yola düşenler işte bunlardır."},{"n":5,"t":"Ancak bunun ardından tevbe edip kendilerini düzeltenler bunun dışındadır; iyi bilin ki Allah tarifsiz bir bağış, eşsiz bir merhamet kaynağıdır."},{"n":6,"t":"Bir de kendilerinden başka tanıkları olmadığı halde eşlerini (zinayla) suçlayan kimseler var. İşte bu tür kişilerin her birine düşen, dört kez kendisinin doğru söylediğine Allah`ı tanık tutarak şahadette bulunmaktır;"},{"n":7,"t":"beşincisinde ise, eğer yalancılardan biriyse Allah`ın lanetinin üzerine olmasını (ister)."},{"n":8,"t":"(Suçlanan eşin) Allah`ı tanık tutarak, dört kez (kocasının) yalan söylediğine dair şahadette bulunması, cezayı kendisinden düşürür;"},{"n":9,"t":"beşincide eğer (kocası) doğru söylüyorsa, Allah`ın gazabının kendi üzerine olmasını (ister)."},{"n":10,"t":"(Düşünsenize bir), ya Allah`ın üzerinizdeki fazlı ve rahmeti olmasaydı? İyi ki Allah, kendisine yönelenlerin tevbesini tekrar tekrar kabul edendir, üstün hikmet sahibidir."},{"n":11,"t":"Gerçek şu ki, iftirayı tasarlayanlar içinizden bir güruhtur. Siz (ey bu iftiranın mağdurları)! Sanmayın ki bu size dokunan bir şerdir, aksine bu sizin için bir hayırdır! Onlardan her birinin kazandığı günah oranında (cezası) vardır; ama onlar içerisinden bu işin elebaşılığını üstlenen kimse var ya: onu korkunç bir azap beklemektedir."},{"n":12,"t":"Bu (iftirayı) işittiğinizde, mü`min erkekler ve kadınlar birbirleri hakkında iyi zanda bulunup da, \"Bu düpedüz bir iftiradır\" demeleri gerekmez miydi?"},{"n":13,"t":"(İftiracılar) iddialarını ispat için dört şahit getirselerdi ya! Madem ki bu şahitleri getiremediler, bu takdirde onlar Allah katında yalancının ta kendisidirler."},{"n":14,"t":"Bakın, eğer Allah`ın dünya ve ahirette sizin üzerinizdeki fazlı ve rahmeti olmasaydı, bulaştığınız bu (iftiradan) dolayı mutlaka size korkunç bir azap dokunurdu;"},{"n":15,"t":"tam da dillerinize dolayıp, hiçbir bilginiz olmadığı halde basite alarak ağızlarınızda gevelediğiniz bir sırada... Oysa ki bu, Allah katında çok ağır bir (vebaldir)."},{"n":16,"t":"İşte bu yüzden, onu işitir işitmez: \"Bu konuda konuşmak bize düşmez! (Allah`ım, böyle bir iftiradan) Senin yüce zatına sığınırız! Bu dehşet bir iftiradır!\" demeniz gerekmez miydi?"},{"n":17,"t":"Eğer imanda sebat gösteren kimselerseniz, Allah size bu tür bir (iftiraya) bir daha asla bulaşmamamınızı öğütler."},{"n":18,"t":"Zira Allah size mesajlarını açıkca bildirir: nitekim her hükmünde tam isabet kaydeden Allah, (bu olayda kimin nerede durduğunu) çok iyi bilmektedir."},{"n":19,"t":"Mü`minler arasında hayasızca söylentilerin yayılmasından hoşlanan kimseleri, bu dünyada da ahirette de can yakıcı bir yalnızlığa terk edeceğiz. (Bir şeyin içyüzünü) Allah bilir, fakat siz bilmezsiniz."},{"n":20,"t":"Ya Allah`ın üzerinizdeki fazlı ve rahmeti bulunmasaydı? Hele ki Allah çok şefkatlidir, pek merhametlidir."},{"n":21,"t":"Siz ey iman edenler! Şeytanın adımlarını izlemeyin! Kim şeytanın adımlarını izlerse, iyi bilsin ki (Şeytan) sadece hayasızlığı ve akl-ı selime aykırı olanı emreder. Ve eğer Allah`ın üzerinizde ki fazlı ve rahmeti bulunmamış olsaydı, sizden hiç kimse ebediyen (günahtan) arınamazdı. Lakin Allah (arınmak) isteyen kimseyi arındırmayı diler; zira Allah (arınmak isteyen herkesi) çok iyi işitir ve çok iyi bilir."},{"n":22,"t":"Şu halde, içinizden (servetçe) bolluk ve rahatlık içinde olan kimseler, yakınlara, muhtaçlara ve Allah davası uğruna hicret edenlere yardım etmekten geri durmasınlar; onları affedip hoş görsünler! Hem Allah`ın sizi bağışlaması hoşunuza gitmez mi? Nitekim Allah tarifsiz bir bağış, eşsiz bir merhamet kaynağıdır."},{"n":23,"t":"Şu kesin ki, iffetli ve inanmış kadınlara -dalgınlık ve dikkatsizlik etmiş olsalar dahi- iftira atan kimseler, dünya ve ahirette Allah`ın rahmetinden dışlanacaklar. Üstelik onlar korkunç bir terkedilmişliğe mahkum olacaklar;"},{"n":24,"t":"o gün onların dilleri, elleri ve ayakları yapıp ettiklerinden dolayı kendileri aleyhine tanıklık edecektir."},{"n":25,"t":"O gün geldiğinde, Allah onlara hak ettikleri karşılığı tastamam ödeyecek; sonunda onlar da, Allah`ın, evet yalnızca O`dur (her şeyi) apaçık ortaya çıkaran, mutlak hakikat olduğunu öğrenecekler."},{"n":26,"t":"Kural olarak kötü, yozlaşmış şeyler ve sözler; kötülere ve yozlaşmış kimselere, kötü ve yozlaşmışlar da, kötü ve yozlaşmış şeylere ve sözlere yakışır. İyi ve temiz şeyler ve sözler iyilere, iyi ve temiz insanlar da, iyi ve temiz insanlara ve sözlere layıktırlar. Bunlar, yani peygamber, Aişe ve Safvân, onların söylediklerinden, tamamen uzaktırlar. Güzel bir rızık ve bağışlanma da, bunlar içindir."},{"n":27,"t":"Siz ey iman edenler! Kendinize ait olmayan evlere, sahiplerinden izin almadan ve selam vermeden girmeyiniz: düşünecek olursanız, sizin yararınıza olan da budur."},{"n":28,"t":"Buna rağmen eğer orada kimseyi bulamazsanız, size izin verilinceye kadar oraya girmeyin; dahası eğer size \"dönün\" denilirse, siz de hemen dönün; bu davranış sizin için daha nezihtir: zira Allah yaptığınız her şeyi bilmektedir."},{"n":29,"t":"(Ama) içinde oturulmayan, sizin de yararınıza hizmet veren kamuya açık mekanlara girmenizde bir sakınca yoktur: şu da var ki Allah, açıktan yaptıklarınızı da gizlediklerinizi de bilmektedir."},{"n":30,"t":"Mü`min erkeklere söyle, bakışlarını (yasak) olandan çevirsinler ve iffetlerini korusunlar; tertemiz kalabilmeleri için en uygun davranış şekli budur: unutmasınlar ki Allah, ortaya koydukları her bir şeyden haberdardır."},{"n":31,"t":"Mü`min kadınlara da söyle, bakışlarını (yasak) olandan çevirsinler, iffetlerini korusunlar, cazibe ve güzelliklerini, bunlardan görünen kısımlar dışında, (kamuya) açmasınlar; bunun için de, başörtülerini yakalarının üzerine sıkıca tuttursunlar; cazibe ve güzelliklerini yalnızca kocalarına, babalarına, kayınbabalarına, oğullarına, üvey oğullarına, kardeşlerine, erkek kardeşlerinin oğullarına, kız kardeşlerinin oğullarına, kendi (evlerindeki) kadınlara, meşru şekilde malik oldukları kimselere, ya da emirleri altındaki cinsel arzudan yoksun erkek hizmetlilere, veya kadınların mahrem yerlerinin henüz farkında olmayan çocuklara açabilirler; bir de yürürken, gizli olan ziynetlerini teşhir etmek için ayaklarını yere vurmasınlar. Siz ey iman edenler! Topyekün günahları terk edip Allah`a yönelin ki, mutluluk ve kurtuluşa erebilesiniz."},{"n":32,"t":"Ve içinizden bekar olanları, erkek ve kadın esirlerinizden (evliliğe) elverişli olanları evlendirin! Yoksul da olsalar, Allah onları lutfuyla destekleyecektir: zira Allah (lutfunda) sınırsızdır, (kime ne kadar vereceğini) çok iyi bilir."},{"n":33,"t":"Ama evlenmeye bir türlü imkan bulamayanlar, Allah lutfundan kendilerine (bir fırsat) tanınıncaya dek iffetlerini korusunlar! Öteden beri mülkiyetinizde bulunan esirlerden azatlık sözleşmesi yapmak isteyenlere gelince: eğer onlarda bir liyakat görüyorsanız, onlarla sözleşme yapınız; üstelik onlara Allah`ın size (emanet) olarak verdiği maldan bir miktar da veriniz. Bir de eğer (evlenme yoluyla) iffetsizliğe karşı korunmak istiyorlarsa, dünya hayatının fani hazlarına tamah ederek sakın kadın esirlerinizi fuhuşa zorlamayınız; zira onları zorlayan herkes iyi bilsin ki, Allah bu zorlanmadan dolayı onları bağışlayacak, merhamet edecektir."},{"n":34,"t":"Ve doğrusu Biz size hakikati açık ve net olarak dile getiren mesajlar, sizden önce geçip gitmiş olanlara ilişkin bir nice mesel ve sorumluluk bilincine sahip olanlar için her türden öğüt indirmişizdir."},{"n":35,"t":"Allah göklerin ve yerin nuru(nun kaynağı)dır. O`nun nurunun sembolü, içinde kandil bulunan bir ışık mahalli gibidir. O kandil kristal bir fanus içindedir. Öyle bir fanus ki, sanki inci gibi (parıldayan) bir gezegen. O kandil, doğuya da batıya da ait olmayan mübarek bir zeytin ağacından elde edilmiş bir yakıtla tutuşturulur. Öyle ışıltılı bir yağ ki, neredeyse ateş değmeden bile ışık saçacak: nur üstüne nurdur! Allah, isteyeni nurunun (peşine takarak) doğru yola iletmeyi diler. İşte Allah insanlara böyle misaller vermektedir: zira her şeyi en ince ayrıntısına kadar bilen yalnızca Allah`tır."},{"n":36,"t":"İçerisinde sabah akşam O`nun adı anıldığı için Allah`ın yükseltilmelerine izin verdiği ibadethanelerde, O`nun ululuğunu ve yüceliğini sürekli dile getiren"},{"n":37,"t":"nice yiğitler vardır ki, onları ne ticaret ne bir (başka) kazanç kapısı Allah`ı anmaktan, namazı hakkını vererek eda etmekten ve arınmak için verilmesi gerekeni vermekten alıkoyabilir; onlar kalplerin ve gözlerin dehşetle döndüğü günden korkarlar."},{"n":38,"t":"Bütün bunların sonucunda da Allah onları yaptıklarının en iyisiyle ödüllendirir; üstelik onlara kendi lutfundan daha fazlasını da verir: zira dilediğine hesapsız rızık bağışlayan yalnızca Allah`tır."},{"n":39,"t":"Ve inkarda ısrar edenlere gelince... Onların yapıp ettikleri çölde (görülen) serap gibidir: susuzluktan yanmış olan onu su sanır, fakat ona yaklaştığında orada (sudan) hiçbir iz bulamaz; fakat Allah`ı kendi vicdanında bulur ve bilir ki, O hesabı tastamam görür: zira Allah çok seri hesap görendir."},{"n":40,"t":"Veya (onların yapıp ettikleri) bir okyanusun derin karanlıkları gibidir; onu üst üste dalgalar kuşatmıştır, derken üstüne (bir de) kara bulutlar... Birbiri üstüne binmiş, kopkoyu, zifiri karanlıklar... kişi çıkarıp baksa, neredeyse elini dahi göremeyecek durumda: nitekim bir kimseyi Allah aydınlatmamışsa, onun asla aydınlıktan nasibi olamaz!"},{"n":41,"t":"Sen (ey insan)! Göklerde ve yerde bulunan her bir varlığın -kanat çırpan kuş katarlarına varana dek- Allah`ın yüce kudretini dillendirdiğini fark etmez misin? Doğrusu onların hepsi de, O`na teslim olmayı ve O`nu yüceltmeyi bilmektedir; Allah onların hareketlerini de çok iyi bilmektedir:"},{"n":42,"t":"zira göklerin ve yerin hakimiyeti Allah`a aittir ve nihai dönüş de yalnızca Allah`adır."},{"n":43,"t":"(Yine) sen fark etmez misin ki bulutları sürükleyen, sonra onları birbiri üzerine istif edip kümeler haline getiren, derken senin onların bağrından boşaldığını gördüğün yağmuru yağdıran Allah`tır. Gökten dolu yüklenmiş (bulut) dağları indiren, peşinden -dilediği kimseye onu isabet ettirip, dilediğinden onu uzak tutan da Allah`tır. (Düşün ki), neredeyse o (bulut)lardan çakan şimşeğin parıltısı gözleri almaktadır:"},{"n":44,"t":"(işte böyle), gece ve gündüzü de Allah evirip çevirmektedir. Bakın, bütün bunlarda görecek gözü olanlar için mutlaka alınacak ibretler vardır."},{"n":45,"t":"Yine her tür canlıyı sudan yaratan da Allah`tır: son tahlilde onlardan kimi karnı üzerinde sürünmektedir; kimi iki ayağı, kimi de dört ayağı üzerinde yürümektedir. Allah dilediğini yaratır; şundan emin olun ki, Allah her şeye güç yetirendir."},{"n":46,"t":"Doğrusu Biz, hakikati bütün açıklığıyla ortaya koyan ayetler indirmişizdir; bununla Allah (isteyen) kimseyi dosdoğru bir yola yöneltmeyi diler."},{"n":47,"t":"Ama birileri \"Biz Allah`a ve Rasul`e hem inandık, hem de itaat ettik\" derler, sonra da onlardan bir kısmı bunca (taahhüdün) ardından sözlerinden geri dönerler: şu halde bu gibiler gerçek mü`min değildirler."},{"n":48,"t":"Zira onlar aralarında hüküm versin diye Allah`a ve O`nun Rasulü`ne çağrıldıklarında, hiç değilse bir kısmı hemen yüz çeviriverirler;"},{"n":49,"t":"fakat eğer kendileri haklı çıkacak olursa, teslim olmuş bir edayla koşa koşa gelirler."},{"n":50,"t":"(Şimdi sen söyle ey bu hitabın muhatabı!) Bunların kalplerinde mi bir hastalık var, yoksa kuşkuya mı kapılıyorlar!? Yahut da Allah`ın, dolayısıyla O`nun Rasulü`nün kendilerine haksızlık yapmasından mı korkuyorlar!? Hayır, aksine asıl kendileri haksızlık yapmaktadırlar."},{"n":51,"t":"Aralarında hüküm vermesi için Allah`a, dolayısıyla O`nun Rasulü`ne çağrıldıkları zaman mü`minlere düşen söz, sadece \"İşittik ve itaat ettik\" demekten ibaret olmalıdır; zira böyleleri gerçek kurtuluşa eren kimseler olacaklar."},{"n":52,"t":"Ve kim Allah`a dolayısıyla O`nun Rasulü`ne itaat eder, Allah`tan korkar ve Allah`a karşı sorumluluk bilinciyle hareket ederse, işte onlar gerçek başarıya eren kimseler olacaklar."},{"n":53,"t":"Bir de kendilerine emredecek olsan, mutlaka (savaş için sefere) çıkacaklarına dair var güçleriyle yemin edenlere de ki: \"Yemin etmeyin! İtaat (herkesçe) bilinen ortak iyiyedir: şu da bir gerçektir ki, Allah yaptıklarınızdan ayrıntısıyla haberdardır.\""},{"n":54,"t":"De ki: \"Allah`a itaat edin, dolayısıyla Rasul`e itaat edin!\" Bundan böyle de, eğer (Rasul`den) yüz çevirecek olursanız, o ancak kendi yükümlülüklerinden sorumlu tutulacaktır, siz de sadece kendi yükümlülüklerinzden sorumlu tutulacaksınız. Ama eğer onu izlerseniz, doğru yolu bulursunuz: Rasul`e düşense, yalnızca (kendisine indirileni) bütün açıklığıyla tebliğ etmektir."},{"n":55,"t":"Allah, içinizden iman edenlere ve ıslah edici iyilikler işleyenlere, onlardan öncekileri hakim kıldığı gibi kendilerini de hakim kılacağına, onlar için hoşnut ve razı olduğu dini yine onlar için sağlamlaştıracağına, endişelerinin (baskın olduğu) bir dönemin ardından onları güvenli bir konuma kavuşturacağına söz vermiştir: (değil mi ki) onlar Bana kulluk ediyorlar ve Bana hiçbir şeyi ortak koşmuyorlar! Fakat kim de bunun ardından inkara saplanırsa, işte onlardır asıl yoldan sapmış olanlar."},{"n":56,"t":"Şu halde, namazı hakkını vererek kılın, zekatı gönülden gelerek verin ve Rasul`ü izleyin ki merhamete mazhar olmayı umut edebilesiniz."},{"n":57,"t":"İnkarda ısrar eden kimseler, bu dünyada asla (Allah`ı) atlatabileceklerini sanmasınlar; onların dönüp dolaşıp varacakları yer ateştir; ki o, ne berbat bir son duraktır!"},{"n":58,"t":"Siz ey iman edenler! Meşru bir biçimde sahip olduğunuz kimseler ve içinizden ergenlik çağına ulaşmamış olanlar (dahi), günün şu üç (vaktinde) yanınıza girmeden önce sizden izin istesinler: sabah namazından önce, öğleyin elbiselerinizi çıkarıp istirahata çekildiğiniz vakit ve yatsı namazından sonra. Bu üç vakit sizin için mahremiyet vakitleridir. Bu vakitler dışında birbirinizin yanına girip çıkmanızda, sizler için de onlar için de herhangi bir beis yoktur. Bu mesajları Allah size işte böyle açıklamaktadır: zira her hükmünde tam isabet sahibi olan Allah, (yarattığı insanı) çok iyi bilmektedir."},{"n":59,"t":"Ama çocuklarınız ergenlik çağına ulaştıklarında, kendilerinden büyüklerin yaptığı gibi (yanınıza girmek istedikleri her zaman) izin istemelidir. Mesajlarını Allah size işte böyle açıklamaktadır: zira her hükmünde tam isabet sahibi olan Allah, (yarattığı insanı) çok iyi bilmektedir."},{"n":60,"t":"Bir de, kadınlardan artık cinsel arzu duymayacak kadar yaşlanmış olanlar var; işte böylelerinin, bedeni teşhir amacı taşımaksızın, giysilerinden bir kısmını çıkarmalarında bir beis yoktur. Ama iffetleri üzerine titrerlerse bu kendileri için daha hayırlıdır: zira Allah (ağızlardan çıkan) her şeyi işitir, (kalplerde olan) her şeyi bilir."},{"n":61,"t":"(Eğer güç gelecekse) görme özürlü zora koşulamaz, yürüme özürlü zora koşulamaz, hasta zora koşulamaz; ve (aile bireyleri olarak) sizin kendi evlerinizde veya babalarınızın evlerinde, veya annelerinizin evlerinde, veya erkek kardeşlerinizin evlerinde, veya kız kardeşlerinizin evlerinde, veya amcalarınızın evlerinde, veya halalarınızın evlerinde, veya dayılarınızın evlerinde, veya teyzelerinizin evlerinde, veya anahtarları size teslim edilmiş olan yahut da sadık arkadaşınıza ait olan (evlerde) yiyip (içmenizde) bir sakınca yoktur; hep birlikte ya da ayrı ayrı yemenizde de bir beis yoktur. Bundan böyle bir eve girdiğiniz zaman, birbirinize Allah katından bir esenlik, bir bereket ve mutluluk dileğiyle selam veriniz: Bu mesajları Allah size işte böyle açıklamaktadır ki, akıllıca hareket edebilesiniz."},{"n":62,"t":"Mü`minler, ancak Allah`a ve O`nun Rasulü`ne yürekten inanıp güvenen kimselerdir; onunla toplumsal bir iş görüşmek için bir araya geldiklerinde, onun iznini almadıkça asla ayrılmazlar. Şüphesiz senden (farklı bir görüş geliştirmek için) izin alanlar (da), Allah`a ve O`nun Rasulü`ne yürekten inanıp güvenen kimselerdir. İşte bu yüzden, onlar senden bazı işleri için izin isterlerse onlardan uygun gördüklerine bu izni ver; Allah`tan da onlar için mağfiret dile: Şüphe yok ki Allah, rahmeti bol bir bağışlayıcıdır."},{"n":63,"t":"Rasul`ün davetini, sakın birbiriniz arasındaki herhangi bir davet gibi algılamayın! Doğrusu Allah, aranızdan kimselere sezdirmeden sıyrılıp çıkmak isteyenleri biliyor. Şu halde onun emrine karşı gelen kimseler, başlarına (bu dünyada) bir musibetin (ahirette ise) can yakıcı bir azabın gelmesinden sakınsınlar."},{"n":64,"t":"Bakın! Göklerde ve yerde olanların hepsi kesinlikle Allah`a aittir; O sizin içinde bulunduğunuz gerçek durumu elbette biliyor; öyle ki, O`na döndürülecekleri gün, evet (o gün) yaptıkları her şey kendilerine haber verilecektir: zira Allah her şeyi bütünüyle bilendir."}],[{"n":1,"t":"Bütün insanlığa bir uyarı olması için, kuluna iyi ile kötünün arasını kesin hatlarla ayıran vahyi indiren (Allah) ne yüce bir bereket kaynağıdır."},{"n":2,"t":"O (Allah) ki, göklerin ve yerin hakimiyeti yalnızca O`na aittir; O çocuk edinmemiştir, hakimiyetinde O`na herhangi bir ortak da bulunmamaktadır: zira her şeyi O yaratmış ve (bütün bunları) ölçüsünü kendi koyduğu yasalara bağlamıştır."},{"n":3,"t":"Ne ki yine de O`nun dışında, hiçbir şey yaratamayıp kendileri yaratılmış bulunan; kendilerinden bir zararı defetmeye de bir yararı talep etmeye de güçleri olmayan; ne hayat, ne ölüm, ne de ölümden sonra dirilişe dair bir yetkisi bulunmayan birtakım sahte ilahlar peydahladılar."},{"n":4,"t":"Bir de inkarda ısrar eden o kimseler; \"Bu onun uydurduğu bir yalandan başkası değildir; üstelik bu konuda başka bir topluluk da ona yardım etmiştir\" dediler. İşte ileri sürdükleri bu iddiayla, hem haksızlık etmiş, hem de gerçeği çarpıtmış oldular."},{"n":5,"t":"Yine dediler ki: `(Bunlar) öncekilerin masallarıdır. O onları yazdırmıştır ve sabah akşam kendisine okunmaktadır.`"},{"n":6,"t":"De ki: \"Onu, göklere ve yere ait bütün sırları bilen (Allah) indirdi: zaten O, tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":7,"t":"Yine: \"Bu nasıl elçi böyle? Yiyip içiyor, çarşıda pazarda dolaşıyor! Ona bir melek indirilseydi de beraberinde o da uyarıp dursaydı ya!"},{"n":8,"t":"Ya da kendisine (gökten) bir hazine bırakılsaydı, veya ondan yiyip içerek (safa sürdüğü) kendisine ait bir cenneti olsaydı?\" dediler. Bir de kalkıp o zalimler; \"Eğer (ona) uymuş olsaydınız, sihirlenmiş bir adamdan başkasına uymamış olacaktınız\" dediler."},{"n":9,"t":"Şunların, seni neye benzettiklerine bir bak hele! Ve sonuçta öyle bir sapıtıyorlar ki, bir daha doğru yolu bulacak (muhakeme) gücünü asla kendilerinde bulamıyorlar."},{"n":10,"t":"O öyle yüce öyle cömerttir ki, dilerse senin için bu (dediklerin)den daha hayırlı olan, zemininden ırmaklar akan cennetler var eder; yine senin için (orada) köşkler, yalılar inşa eder."},{"n":11,"t":"Hayır! Onların (asıl problemi) Son Saat`i yalanlamış olmalarıdır. Ama Biz Son Saat`i yalanlayan kimseler için kışkırtılmış çılgın bir ateş hazırlamışızdır."},{"n":12,"t":"Onlar, çok uzak bir mekandan dahi, kendilerini gördüğü zaman o ateşin nasıl bir homurtuyla kükrediğini elbet işitecekler."},{"n":13,"t":"Derken, birbirlerine kelepçeli olarak oranın oldukça dip bir yerine fırlatıldıklarında.. İşte o anda, tam orada yok olmak için yalvaracaklar."},{"n":14,"t":"Yoo, bugün yok olmak için bir tek ölümü çağırmayın, yok olmak için tüm ölümleri çağırın!"},{"n":15,"t":"De ki: \"Ee, şimdi bu mu hayırlı, yoksa takva sahiplerine vaad edilen ebedi cennet mi? Ki o bir ödül ve bir son duraktır."},{"n":16,"t":"Orada diledikleri her şey kalıcı biçimde onların olacak: Bu, Rabbinin üzerinde kendisinden yerine getirmesi istenilen bir söz idi.\""},{"n":17,"t":"İmdi, O, bir gün onları ve onların Allah`tan gayrı yalvarıp yakardıklarını bir araya getirecek ve soracak: \"İşte şu kullarımı siz mi yoldan çıkardınız, yoksa onlar kendileri mi yoldan çıktılar?\""},{"n":18,"t":"Cevap verecekler: \"Aşkın olan zatını tenzih ve tesbih ederiz ki, Senin dışındakilerden herhangi bir dost, bir veli edinmek bize yakışmaz; ne var ki onlara ve atalarına dünyevi hazları öylesine tattırdın ki, sonunda onlar vahyi unuttular; ve hiç olmaya mahkum bir kavim olup çıktılar."},{"n":19,"t":"Bunun üzerine (Allah şirk koşanlara şöyle demişti): \"Doğrusu o (tanrılık yakıştırdıklarınız), söylediklerinizin tümünde sizin yalancı olduğunuzu ortaya çıkarıyorlar. Artık ne (cezayı) atlatmaya mecaliniz yeter, ne de yardım almaya: zira sizden her kim (hakikati) tersyüz ederse, ona büyük bir azap tattıracağız."},{"n":20,"t":"(Ey Nebi!) Biz senden önce de yemek yiyen, çarşıda pazarda dolaşan insanlar dışında hiçbir peygamber göndermemişizdir. Bazılarınızı diğerleriniz için sınama vesilesi kıldık ki, bakalım sabrediyor musunuz? (Bunu siz öğrenesiniz diye böyle yaptık); yoksa senin Rabbin zaten her şeyi görmektedir."},{"n":21,"t":"Ama Bizim huzurumuza çıkacak yüzü olmayan kimseler: \"Bize melekler gönderilseydi veya Rabbimizi görseydik ya!\" dediler. Doğrusu onlar kendi iç dünyalarında büyüklük tasladılar ve hadlerini aşarak kasım kasım kasıldılar."},{"n":22,"t":"Onlar bir gün melekleri görecekler, fakat o gün günahkarlar için hiç de iç açıcı olmayacak. Ve onlar \"(Eyvah), her yandan sarılmışız!\" diyecekler."},{"n":23,"t":"Zira Biz (o gün) yapıp ettikleri ne varsa hepsinin üzerini çiğneyeceğiz; ve onu yel savurmuş küle çevireceğiz."},{"n":24,"t":"O gün cennet ehli, kalınacak yerlerin en hayırlısına, istirahat mekanlarının en iyisine sahip olacak."},{"n":25,"t":"İşte o gün, tüm bulutlarıyla birlikte gökyüzü param parça olacak; ve melekler bölük bölük indirilecek;"},{"n":26,"t":"mutlak hakimiyet o gün, rahmetin mutlak kaynağı olan (Allah`a) ait olacak: ve zaten o (gün) inkar edenler için çok zor bir gün olacak."},{"n":27,"t":"İşte o gün haddi aşmış olan kişi, (aldanmanın pişmanlığıyla) elini ısırarak diyecek ki: \"Ah n`olaydım! Keşke Rasul ile birlikte bir yol tutmuş olaydım!"},{"n":28,"t":"Vah n`olaydım! Keşke falanca kimseyi kendime yol gösterici bir dost tutmayaydım!"},{"n":29,"t":"Doğrusu, bana vahiy ulaştıktan sonra beni ondan uzaklaştırdı.\" Evet, zaten (kişiyi vahiyden) uzaklaştıran her tür şer güç insanı işte böyle yüzüstü bırakır."},{"n":30,"t":"Ve (o gün) Rasul diyecek ki: \"Ya Rabbi! Benim Kavmim bu Kur`an`a devri geçmiş, işlevi kalmamış bir kitap muamelesi yaptı!\""},{"n":31,"t":"İşte böylece Biz her peygambere, suçu karakter haline getirenler içerisinden düşmanlar çıkarmışızdır: olsun, nasıl olsa Rabbin yol gösterici ve yardım edici olarak sana yeter."},{"n":32,"t":"Bir de inkarda ısrar edenler dediler ki: \"Kur`an ona topyekün olarak indirilseydi ya!\" İşte Biz, bütünü oluşturan parçaları ait oldukları yere biri diğerini açıklayacak şekilde yerleştirerek, onunla senin iç dünyanı inşa edip pekiştirelim diye böyle yaptık."},{"n":33,"t":"İmdi, onlar senin karşına hangi temsili anlatım tarzıyla çıkarlarsa çıksınlar, kesinlikle Biz sana o konudaki gerçeği ve en doğru açıklamayı getiririz."},{"n":34,"t":"Yüzüstü sürünerek cehenneme tıkılacak olan kimselere gelince: En şerli konumda bulunanlar ve yoldan en çok sapanlar işte bunlardır."},{"n":35,"t":"Doğrusu, yine Biz Musa`ya ilahi mesajı gönderdik. Kardeşi Harun`u da onun yanına yardımcı olarak verdik."},{"n":36,"t":"Ve \"Siz ikiniz, ayetlerimizi yalanlayan malum topluluğa gidiniz\" dedik. Ancak bundan sonra(dır ki) onları yerle bir ettik."},{"n":37,"t":"Nuh kavmi de (öyle oldu): tam da elçileri(ni) yalanladıklarında onları suya garkettik. Böylece kendilerini insanlığa ibret kıldık: zira Biz, haddi aşan herkes için can yakıcı bir ceza hazırladık."},{"n":38,"t":"Ve Ad ve Semud kavmi, Ress sakinleri ve bunlar arasında yaşamış olan bir çok nesil de (öyle oldu)."},{"n":39,"t":"Önce her birinin önüne ibretlik örnekler koyduk; sonra hepsini paramparça edip mahvettik."},{"n":40,"t":"Doğrusu bu (vahyin muhatapları), bela sağanağına yakalanan kente uğramış olmalılar. Şimdi orada olup biteni(n iç yüzünü) görmediler, öyle mi? Yoo! Onlar asıl öldükten sonra yeniden dirilerek (hesap vermekten) hazzetmiyorlar."},{"n":41,"t":"Bir de ne zaman seni görseler, sırf seninle alay etme amacıyla \"Ne yani, Allah elçi göndermek için bula bula bunu mu bulmuş?"},{"n":42,"t":"Sahiden, şayet onlar üzerinde ısrar etmeseymişiz bizi ilahlarımız(ın yolun)dan saptıracakmış!\" (diyorlar). Ama zaman gelecek, azabı gördüklerinde kimin daha çok yoldan sapmış olduğunu öğrenecekler."},{"n":43,"t":"Tanrısı olarak hevâi arzularını benimseyen kimsenin durumunu göz önüne getirsene bir! Şimdi (söyle); böyle birinin sorumluluğunu sen üstlenebilir misin?"},{"n":44,"t":"Ya da, sanır mısın ki onların çoğu (ilahi mesajı) işitir veya (hakikati) akleder? Hayır, onlar sürü (içgüdüsüyle davranan) hayvan gibidirler, hatta yoldan sapma konusunda daha da beterdirler!"},{"n":45,"t":"(Ey insan!) Görmez misin Rabbinin gölgeyi nasıl uzattığını? Ama, eğer isteseydi, onu hareketsiz kılardı. Fakat Biz güneşi gölgeye kılavuz yapmışızdır;"},{"n":46,"t":"ardından da onu kendi katımız(dan konulmuş bir yasaya bağlı olarak) usul usul çekip almaktayız."},{"n":47,"t":"Hem sizin için geceyi bir tür örtü yapan, uykuyu istirahat yapan, gündüzü de uyanıp kalkış vakti yapan O`dur."},{"n":48,"t":"Yine Rahmetinin önü sıra rüzgarları müjdeci olarak gönderen de O`dur. Evet Biz, gökten tertemiz bir su indirmişiz"},{"n":49,"t":"ki, onunla ölü toprağı canladıralım; yine onunla yaratmış olduğumuz bir nice canlıyı ve insanı sulayalım diye..."},{"n":50,"t":"Doğrusu Biz, onu (ve bütün bu örnekleri) ayrıntılı bir biçimde açıklayarak insanların önüne koyduk ki düşünüp ders alsınlar diye... Hal böyleyken insanların çoğu yine de yüz çevirmekte, nankörlükte direnmekteler."},{"n":51,"t":"Hem eğer dilemiş olsaydık, (geçmişte olduğu gibi) elbette her topluma (ayrı) bir uyarıcı gönderirdik."},{"n":52,"t":"Madem öyle, artık sen inkarcılara uyma ve onlarla bu (vahiy) sayesinde tüm gayretini sarf ederek büyük bir cihada giriş."},{"n":53,"t":"Hem iki denizi birbirine salan, hem de biri tatlı-susuzluğu giderici ve diğeri tuzlu-acı olduğu halde bu ikisi arasına karışmalarını önleyici (görünmez) bir perde ve aşılmaz bir engel koyan yine O`dur."},{"n":54,"t":"Sudan insanı yaratan ve onun kan bağıyla soy-sop, evlilik bağıyla hısım sahibi olmasını sağlayan da O`dur: zira senin Rabbin sınırsız kudret sahibidir."},{"n":55,"t":"Yine de onlar, Allah`ı bırakıp kendilerine ne yarar ne de zarar verebilecek olan şeylere kulluk ediyorlar: ve zaten som bir kafir/nankör de, Rabbinin düşmanlarına arka çıkan kişidir."},{"n":56,"t":"Ve Biz seni yalnızca bir müjdeci ve uyarıcı olarak gönderdik."},{"n":57,"t":"(Ey Peygamber!) \"Ben bu (davet) karşılığında, dileyen kimsenin Rabbine doğru bir yol tutması dışında sizden herhangi bir ücret talep etmiyorum\" de!"},{"n":58,"t":"Nihayet ölümsüz olan O mutlak diri Zat`a yaslan ve hamd ile O`nun aşkın yüceliğini dillendir! Zira kullarının günahından haberdar olma konusunda kimse O`nunla boy ölçüşemez."},{"n":59,"t":"Gökleri, yeri ve bunların arasındakileri altı evrede yaratıp, sonra da mutlak hükümranlık makamına kurulan O`dur. O, sınırsız rahmet kaynağıdır: haydi o halde, (isteyeceğini) O her haberin hangi kaynaktan ne maksatla çıktığını bilenden iste!"},{"n":60,"t":"Bir de kendilerine \"Yalnızca Rahman olana secde edin!\" denildiğinde, \"Rahman da neymiş? Ne yani, şimdi sen bize neyi emredersen ona boyun mu eğeceğiz\" derler; üstelik bu onların nefretini daha da artırır."},{"n":61,"t":"Göğe büyük yıldız kümeleri serpiştiren, yine oraya (güneş gibi) bir ışık kaynağı ve ay (gibi) bir ışık yansıtıcı yerleştiren Allah ne yüce bir bereket kaynağıdır!"},{"n":62,"t":"Ders almak, ardından şükretmek isteyen kimseler için geceyi ve gündüzü birbirinin peşine takan da O`dur."},{"n":63,"t":"Rahmân’ın has kulları olan kimseler, yeryüzünde vakarlı bir tevazu ile yürürler ve cahillerle muhatap olduklarında “Selam!” der (geçer)ler."},{"n":64,"t":"Yine onlar, gecelerini Rablerinin huzurunda secdeye vararak ve kıyama durarak geçirirler."},{"n":65,"t":"Ve onlar \"Rabbimiz\" derler, \"Cehennem azabını bizden uzak eyle! Çünkü onun azabı oldum olası pek zorlayıcı, pek şedittir."},{"n":66,"t":"Gerçekten de o ne kötü bir ikametgah, ne fena bir makamdır."},{"n":67,"t":"Ve onlar ki, infak ettikleri zaman ne düşüncesizce saçıp savururlar ne de pintilik ederler; zaten bu ikisi arasındaki bir yol dengeli bir tavırdır."},{"n":68,"t":"Yine onlar ki: Allah`la beraber bir başka ilaha yalvarıp yakarmazlar; meşru ve haklı bir gerekçeye dayanmaksızın Allah`ın dokunulmaz kıldığı cana kıymazlar; zina da etmezler! Zira, her kim bunları yaparsa günaha batmış olur."},{"n":69,"t":"Kıyamet Günü`nde onun terkedilmişlik acısı da kat kat olur ve orada onursuzca (tek başına) kalakalır."},{"n":70,"t":"Ancak kim tevbe eder, (yürekten) inanır ve sorumlu davranırsa, Allah işte böylelerinin kötü gidişatını iyi gidişata tebdil edecektir: hem zaten Allah tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":71,"t":"Kaldı ki her kim tevbe eder ve sorumlu davranırsa, işte sadece böyleleri Allah`a gereği gibi yönelmiş sayılacaktır."},{"n":72,"t":"Yine onlar ki: yalan ve sahte olandan yana şahitlik etmezler; yararsız ve anlamsız olan şeylerle karşılaştıklarında da vakarla geçip giderler."},{"n":73,"t":"Yine onlar: Rablerinin ayetleri hatırlatıldığı zaman, sağırlar ve körler gibi (dinleyip anlamadan) üzerine üşüşmezler."},{"n":74,"t":"Ve onlar derler ki: \"Rabbimiz! Bize göz aydınlığı olacak eşler ve nesiller ver ve bizi muttakilere önder eyle!\""},{"n":75,"t":"İşte böyleleridir zorluklara göğüs germeleri sebebiyle cennet köşkleriyle ödüllendirilecek kimseler; hem oraya esenlik ve hayat bahşeden tarifsiz bir mutluluk tebriğiyle buyur edilecekler!"},{"n":76,"t":"Onlar orada ebedi kalacaklar: o ne güzel bir ikamet mahalli, ne kutlu bir makamdır."},{"n":77,"t":"(Müminlere) de ki: \"Eğer duanız olmasaydı Rabbim size niçin değer verecekti ki?\" (Kafirlere de ki:) \"Sonuçta siz de yalanlamış bulunuyorsunuz: bundan böyle (inkarınız) sizin yakanızı asla bırakmayacak!\""}],[{"n":1,"t":"Ta-Sin-Mim!"},{"n":2,"t":"Bunlar Kitab`ın açık ve açıklayıcı olan ayetleridir."},{"n":3,"t":"Mü`min olmuyorlar diye neredeyse kendini helak edeceksin."},{"n":4,"t":"Eğer dileseydik onlara semadan öyle bir belge indirirdik ki, onun karşısında (mecburen) boyun büker, baş eğerlerdi."},{"n":5,"t":"Ama onlara Rahman`ın katından yeni bir hatırlatıcı mesaj gelse, kesinlikle ondan yüz çevirirler."},{"n":6,"t":"Kaldı ki, işte onlar (bunu) da yalanladılar. Buna rağmen, alay edip durdukları haberler yine de karşılarına çıkarılacaktır."},{"n":7,"t":"Peki, şimdi onlar yeryüzüne bakıp da orada her çiftin iyi ve yararlı olanını bitirdiğimizi hiç mi görmezler?"},{"n":8,"t":"Elbet bunda da alınacak bir ders mutlaka vardır; fakat insanların çoğu yine de inanmayacaklardır:"},{"n":9,"t":"ne ki senin Rabbin sınırsız rahmet sahibi olan O yüceler yücesidir."},{"n":10,"t":"Hani Rabbin Musa`ya: \"Zâlimler topluluğuna git!\" diye nida etmişti."},{"n":11,"t":"Firavun`un kavmine!.. (Ve sor onlara): Hala Bana karşı sorumlu davranmayacaklar mı?\""},{"n":12,"t":"(Musa): \"Rabbim!\" dedi, \"Onların beni yalanlamasından endişe ediyorum!"},{"n":13,"t":"Bundan dolayı göğsüm daralacak, dilim dolaşacaktır: işte bu yüzden Harun`a (da) elçilik ver!"},{"n":14,"t":"Üstelik ortada onların lehine benim aleyhime olan bir suçlama da var; bundan dolayı onların beni öldürmelerinden çekiniyorum."},{"n":15,"t":"(Allah) buyurdu ki: `Aslâ! (Sana bir şey yapamazlar.) Şimdi (ikiniz de)mu`cizelerimizle gidin; muhakkak ki biz (ben Azîmüşşân), (aranızda olacak şeyleri)dinleyiciler olarak sizinle berâberiz!`"},{"n":16,"t":"Haydi artık, siz ikiniz Firavun`a gidiniz ve deyiniz ki: \"Biz alemlerin Rabbinin mesajını taşıyoruz:"},{"n":17,"t":"İsrailoğullarını bırak, bizimle gelsinler!\""},{"n":18,"t":"(Firavun) dedi ki: \"Seni daha çocukken aramıza alıp yerleştirmedik mi? Ve ömrünün uzun yıllarını aramızda geçirmedin mi?"},{"n":19,"t":"Ama en sonunda sen yine yapacağını yaptın ve nankörlerden biri olup çıktın!\""},{"n":20,"t":"\"Evet o işi ben yaptım\" dedi, \"çünkü o sırada kendimi kaybetmiştim;"},{"n":21,"t":"ardından da, sizden korktuğum için yanınızdan kaçtım. Daha sonra Rabbim bana doğru düşünme yeteneği bahşetti ve beni elçiler arasına kattı."},{"n":22,"t":"Ve şu başıma kaktığın iyilik, İsrailoğullarını köleleştirmenin bir sonucuydu, (öyle değil mi)?\""},{"n":23,"t":"Firavun: \"Alemlerin Rabbi de neyin nesiymiş?\" dedi."},{"n":24,"t":"(Musa): \"Eğer gerçeğe boyun eğeceksen, (bil ki) O göklerin, yerin ve bunlar arasındaki her şeyin Rabbidir!\""},{"n":25,"t":"(Firavun) çevresindekilere yönelerek \"Ne diyor, duydunuz mu?\" dedi."},{"n":26,"t":"(Musa) dedi ki: \"O sizin de, sizin önden giden atalarınızın da Rabbidir\""},{"n":27,"t":"(Firavun) dedi ki: \"Size gönderil(diğini iddia ed)en elçiniz gerçekten de delinin tekiymiş.\""},{"n":28,"t":"(Musa) dedi ki: \"Eğer kafanızı çalıştırırsanız anlayabilirsiniz ki O, doğunun, batının ve bu ikisi arasında kalan her varlığın Rabbidir!\""},{"n":29,"t":"(Firavun) dedi ki: \"Eğer sen benden başka bir ilahta ısrar edersen, seni kesinlikle mahpuslar arasına katarım!\""},{"n":30,"t":"(Musa) dedi ki: \"Sana, (hakikati) bütün açıklığıyla ortaya koyan bir şeyle gelmiş olsam da mı?\""},{"n":31,"t":"(Firavun) dedi ki: \"Eğer doğru sözlü biriysen, haydi o zaman çıkar ortaya onu!\""},{"n":32,"t":"Bunun üzerine asasını bıraktı; fakat o da ne, bu besbelli ki kocaman bir yılan!"},{"n":33,"t":"Ve elini çıkardı, fakat o da ne, bu bakanların (gözünü kamaştıran) bir beyazlık!"},{"n":34,"t":"(Firavun) etrafındaki gözde danışmanlara \"Anlaşıldı\" dedi, \"bunun hayli bilgili bir büyücü olduğu kesin."},{"n":35,"t":"Büyüsüyle sizi kendi ülkenizden çıkarıp atmak istiyor; şu halde sizler ne önerirsiniz?\""},{"n":36,"t":"(Danışmanlar) dediler ki: \"Onu ve kardeşini alıkoy; bir yandan da bütün kentlere (büyücü) toplamaları için haber sal;"},{"n":37,"t":"ne kadar büyücü-bilgin varsa, hepsini toplayıp sana getirsinler!\""},{"n":38,"t":"Ve böylece büyücüler, belirli bir günün, belirli bir saatinde bir araya geldiler."},{"n":39,"t":"Ve halka şöyle denildi: \"Siz de toplanacaksınız değil mi?"},{"n":40,"t":"Beklentimiz gerçekleşsin diye bizler herhalde sihirbazlardan yana olacağız; yeter ki galip gelen onlar olsunlar!\""},{"n":41,"t":"Ve nihayet büyücüler gelerek Firavun`a dediler ki: \"Şayet biz galip gelecek olursak, bunun bize kazandıracağı büyük bir ödül olmalı, değil mi ama?\""},{"n":42,"t":"(Firavun) \"Kesinlikle\" dedi, \"üstelik siz (protokolde) maiyetimiz arasındaki yerinizi de alacaksınız!\""},{"n":43,"t":"Musa onlara dedi ki: \"Elinizden gelen ne varsa onu ortaya koyun!\""},{"n":44,"t":"Bunun üzerine (onlar) iplerini ve değneklerini attılar ve (böbürlenerek:)`Firavun’un şerefi üzerine yemîn ederiz ki, muhakkak galib olanlar elbette ancak biziz!` dediler."},{"n":45,"t":"Derken, Musa asasını bıraktı. Fakat o da ne! O onların gözbağcılıklarını bir bir silip süpürmesin mi!"},{"n":46,"t":"Sonunda büyücüler hep birden yere kapanarak"},{"n":47,"t":"şöyle dediler: \"İman ettik alemlerin Rabbine!"},{"n":48,"t":"Rabbine Musa ve Harun`un!\""},{"n":49,"t":"(Firavun) dedi ki: \"Demek siz ben izin vermeden ona inandınız, öyle mi? Anlaşıldı ki o size büyüyü öğreten üstadınızdır; fakat pek yakında gününüzü göreceksiniz: dönekliğinizden dolayı ellerinizi ve ayaklarınızı mutlaka keseceğim ve topunuzu asacağım!\""},{"n":50,"t":"(İman eden sihirbazlar) \"Ziyanı yok\" dediler, \"Nasıl olsa biz Rabbimize döneceğiz."},{"n":51,"t":"Şu kesin ki biz mü`minlerin öncülerindeniz, bundan dolayı Rabbimizin bizi bağışlamasını umarız.\""},{"n":52,"t":"Sonunda Musa`ya \"Kullarımı geceleyin yola çıkar; şunu da iyi bilin ki siz mutlaka takip edileceksiniz\" diye vahyettik."},{"n":53,"t":"Derken, Firavun bütün kentlere (asker) toplayıcı görevliler yolladı."},{"n":54,"t":"(ve şöyle dedi): \"Şu kesin ki onlar (donanımsız) başıbozuk bir azınlık."},{"n":55,"t":"Buna rağmen onlar bize karşı hınçla dolular."},{"n":56,"t":"Biz ise şüphesiz ihtiyatlı bir topluluğuz` (dedi)."},{"n":57,"t":"İşte bu tür bir (gurura kapıldıkları) için onları has bahçelerinden ve pınar başlarından çekip çıkardık;"},{"n":58,"t":"servetlerinden, bereketli bir yurttan.."},{"n":59,"t":"Her şey işte böyle olup bitti. Sonuçta Biz İsrailoğullarını, onlardan geriye kalanlara mirasçı kıldık."},{"n":60,"t":"Derken gündoğumunda onların ardına düştüler."},{"n":61,"t":"İki topluluk birbirlerinin görüş alanına girince, Musa`nın ashabı dedi ki: \"Tamam, işte enselendik!\""},{"n":62,"t":"(Musa) \"Hayır, asla!\" dedi, \"çünkü Rabbim benimledir, elbet bir çıkış yolu gösterecektir!\""},{"n":63,"t":"Bunun üzerine Musa`ya \"Asanla denize vur!\" diye vahyettik. Ardından deniz infilak edip ikiye ayrıldı; öyle ki, yolun her (iki) yanından sular ulu dağlar gibi yükselmişti."},{"n":64,"t":"Ötekileri de oraya yaklaştırdık."},{"n":65,"t":"Nihayet Musa ve beraberindekilerin tümünü kurtardık"},{"n":66,"t":"ve ötekileri suya gark ettik."},{"n":67,"t":"Elbet bu (Musa kıssası)nda da alınacak bir ders mutlaka vardır; fakat insanların çoğu yine de inanmayacaklardır."},{"n":68,"t":"Ne ki senin Rabbin sınırsız rahmet sahibi olan O yüceler yücesidir!"},{"n":69,"t":"Onlara İbrahim`in haberini de aktar."},{"n":70,"t":"Hani bir zamanlar o, babasını ve kavmini \"Neye kulluk ediyorsunuz? Diye sor(gula)dı."},{"n":71,"t":"Onlar da \"Putlara kulluk ediyoruz; dahası, onlara adanmış kimseler olarak kalacağız!\" dediler."},{"n":72,"t":"(İbrahim) \"Yalvarıp yakardığınızda sizi duyuyorlar mı bari?\" dedi;"},{"n":73,"t":"\"ya da, size bir yararları veya zararları dokunuyor (mu)?\""},{"n":74,"t":"\"Hayır ama...\" dediler, \"Biz, atalarımızı da böyle yapıyor bulduk!\""},{"n":75,"t":"(İbrahim) \"Ne yani\" dedi, \"taptığınız şeylerin ne olduğuna (bir kez olsun) dönüp bakmadınız mı;"},{"n":76,"t":"(yani) hem siz, hem de önden giden atalarınız?\""},{"n":77,"t":"İşte artık (ilan ediyorum) ki, benim için onlar birer düşmandır. Başka değil, sadece alemlerin Rabbi vardır."},{"n":78,"t":"Ki O`dur beni yaratan, bana doğru yolu gösterecek olan da O`dur."},{"n":79,"t":"Ki O benim açlık ve susuzluğumu giderendir;"},{"n":80,"t":"ve hasta düştüğümde şifa veren de yine O`dur."},{"n":81,"t":"Beni öldürecek, sonra tekrar diriltecek olan da O`dur."},{"n":82,"t":"Hesap Günü`nde beni, hatalarımı bağışlayacağını umduğum (tek) zat da O`dur.\""},{"n":83,"t":"\"Rabbim! Bana doğru bir muhakeme yeteneği bahşet ve beni iyilerin arasına kat!"},{"n":84,"t":"Ve beni sonrakilere sadakatin sözcüsü yap"},{"n":85,"t":"Ve beni ölümsüz nimetlerle dolu cennetin varislerinden kıl!"},{"n":86,"t":"Babamı da bağışla! Çünkü o oldum olası yolunu şaşıranlardan biri olmuştur."},{"n":87,"t":"Ve beni herkesin diriltilip kaldırılacağı o gün mahcup eyleme!\""},{"n":88,"t":"O gün ne malın mülkün bir yararı olur ne de evladın;"},{"n":89,"t":"ancak selim bir kalple Allah`ın huzuruna çıkanlar müstesna."},{"n":90,"t":"Zira (o gün), cennet sorumlu ve bilinçli davrananlara yaklaştırılacaktır."},{"n":91,"t":"Cehennemse sorumsuz ve bilinçsizce davrananlar için kışkırtılacaktır."},{"n":92,"t":"Ve onlara sorulacaktır: \"Nereye kayboldular tapınıp durduğunuz"},{"n":93,"t":"o Allah`tan gayrı (varlıklar)? Size, hadi onu da geçtik, kendilerine olsun bir yardımları dokunacak mı bari?"},{"n":94,"t":"Neticede hem onlar, hem de sorumsuz ve bilinçsizce onlara (umut bağlayanlar) cehennemde üst üste istif edilecekler;"},{"n":95,"t":"İblis`in bütün askerleri de..."},{"n":96,"t":"Onlar orada birbirleriyle atışırken şöyle derler:"},{"n":97,"t":"\"Hayret vallahi! Her ne kadar, apaçık bir sapıklığın ortasına düşen biz isek de,"},{"n":98,"t":"o zaman sizi alemlerin Rabbiyle bir tutuyorduk;"},{"n":99,"t":"ne ki bizi saptıran, yalnızca günahı hayat tarzı haline getiren şu kimselerdi;"},{"n":100,"t":"gel gör ki, şimdi bize arka çıkan ne bir kimse var"},{"n":101,"t":"ne de yürekten bir dost."},{"n":102,"t":"Keşke bizim için bir kez daha dönüş olsaydı da, biz de inananlardan biri olsaydık.\""},{"n":103,"t":"Elbet bu (kıssada) da alınacak bir ders mutlaka vardır, fakat insanların çoğu yine de inanmayacaklardır."},{"n":104,"t":"Ne ki senin rabbin, sınırsız rahmet sahibi olan O yüceler yücesidir."},{"n":105,"t":"Nuh kavmi (de) peygamberlerini yalanladı."},{"n":106,"t":"Hani bir zamanlar soydaşları Nuh onlara şöyle demişti: \"Hala sorumlu davranmayacak mısınız?"},{"n":107,"t":"Hem bakın, ben size gönderilmiş güvenilir bir elçiyim;"},{"n":108,"t":"şu halde, Allah`a karşı sorumlu davranın ve beni izleyin!"},{"n":109,"t":"Ben bu (davet) karşılığında sizden hiçbir ücret talep etmiyorum. Benim ecrimi takdir etmek, sadece alemlerin Rabbine düşer."},{"n":110,"t":"Haydi artık Allah`a karşı sorumlu davranın ve beni izleyin!\""},{"n":111,"t":"Dediler ki: \"Ne yani, toplumun en düşüklerinin sana tabi olduğunu bile bile sana inanalım mı?\""},{"n":112,"t":"(Nuh): \"Onların öteden beri ne yapıp ettiklerine dair benim bir bilgim yok;"},{"n":113,"t":"Onlar hakkında yargıda bulunmak bana değil, sadece Rabbime düşer: keşke bu kadarını olsun fark etseydiniz!"},{"n":114,"t":"Üstelik ben inananları yanımdan kovacak değilim."},{"n":115,"t":"Çünkü ben, (hakkı) tüm açıklığıyla (ortaya koyan) bir uyarıcıdan başkası değilim.\""},{"n":116,"t":"\"Ey Nuh!\" dediler, \"Eğer buna bir son vermezsen, taşlana(rak susturula)caksın."},{"n":117,"t":"\"Rabbim!\" dedi, \"İşte, sonunda kavmim beni yalanlamış bulunuyor;"},{"n":118,"t":"artık benimle onlar arasında kesin bir hüküm ver ve hem beni, hem de benimle birlikte olan mü`minleri kurtar!\""},{"n":119,"t":"Derken, onu ve beraberindekileri yükünü almış olan o gemiyle kurtardık;"},{"n":120,"t":"ve geride kalanları boğulmaya terk ettik."},{"n":121,"t":"Elbet bu (Nuh kıssası)nda da alınacak bir ders mutlaka vardır; fakat insanların çoğu yine de inanmayacaklardır."},{"n":122,"t":"Ne ki senin Rabbin sınırsız rahmet sahibi olan O yüceler yücesidir."},{"n":123,"t":"Ad kavmi (de) elçilerini yalanladı."},{"n":124,"t":"Hani bir zamanlar onlara da soydaşları Hud şöyle demişti: \"Hala sorumlu davranmayacak mısınız?\""},{"n":125,"t":"Hem bakın, ben size gönderilmiş güvenilir bir elçiyim."},{"n":126,"t":"Şu halde, Allah`a karşı sorumlu davranın ve beni izleyin!"},{"n":127,"t":"Ben bu (davet) karşılığında sizden hiçbir ücret talep etmiyorum, benim ecrimi takdir etmek sadece alemlerin Rabbine düşer.\""},{"n":128,"t":"\"Siz, abesle iştigal ederek her bir tepede yüksek bir anıt, bir yapı mı inşa ediyorsunuz?"},{"n":129,"t":"“Ebedî kalacağınız ümidiyle saraylar mı edineceksiniz?”"},{"n":130,"t":"Elinize her (fırsat) geçirdiğinizde, hukuka tecavüz edip zorbalık (mı) yapacaksınız?"},{"n":131,"t":"Haydi, artık Allah`a karşı sorumlu davranın ve bana uyun!"},{"n":132,"t":"Aklınıza gelebilecek her tür (nimeti) size lutfeden Zat`a karşı saygılı olun!"},{"n":133,"t":"Size sürüler ve çocuklar lutfeden;"},{"n":134,"t":"dahası, bağlar-bahçeler ve pınarlar (lutfeden Zat`a)..."},{"n":135,"t":"Bakın, ben korkunç bir günün sizin üzerinize çöreklenecek azabından endişe ediyorum!\""},{"n":136,"t":"Onlar \"Sen\" dediler, \"bize öğüt versen de öğüt vermesen de, bizim için fark eden bir şey olmaz."},{"n":137,"t":"(Zira) bu, önden giden (atalarımızın) ahlak sisteminden başkası değildir."},{"n":138,"t":"Dolayısıyla, bu yüzden bizim azaba uğratılmamız da mümkün değildir!\""},{"n":139,"t":"Neticede, onu işte böyle yalanladılar; bunun üzerine Biz de onları helak ettik. Elbet bu (Hud kıssası)nda da alınacak bir ders mutlaka vardır; fakat insanların çoğu yine de inanmayacaklardır."},{"n":140,"t":"Ne ki senin Rabbin, sınırsız rahmet sahibi olan O yüceler yücesidir."},{"n":141,"t":"Semut (da) elçilerini yalanladı."},{"n":142,"t":"Hani bir zamanlar onlara da soydaşları Salih şöyle demişti: \"Hala sorumlu davranmayacak mısınız?"},{"n":143,"t":"Hem bakın, ben size gönderilmiş güvenilir bir elçiyim:"},{"n":144,"t":"Şu halde Allah`a karşı sorumlu davranın ve beni izleyin!"},{"n":145,"t":"Ben bu (davet) karşılığında sizden hiçbir ücret talep etmiyorum; benim ecrimi takdir etmek sadece alemlerin Rabbine düşer.\""},{"n":146,"t":"\"İçinde bulunduğunuz şu konumda böylece bırakılacağınıza dair güvenceniz mi var?"},{"n":147,"t":"Envai çeşit bahçeler içinde ve pınar başlarında..."},{"n":148,"t":"Ekinler ve iç geçirtecek kadar zarif, olgun ve dolgun hurma salkımlarının sarktığı hurmalıklarda..."},{"n":149,"t":"Bir de kalkmış, dağlarda yonttuğunuz görkemli evlerden dolayı şımarıyorsunuz."},{"n":150,"t":"Ama artık Allah`a karşı sorumlu davranın ve beni izleyin!"},{"n":151,"t":"Haddi aşanların isteklerine uymayın!"},{"n":152,"t":"Böyleleri düzeni sağlamadıkları gibi, yeryüzünde fesat çıkarmaktan da geri durmazlar.\""},{"n":153,"t":"Onlar dediler ki: \"Sen, büyülenmiş birinden başkası değilsin."},{"n":154,"t":"Sen de sadece bizim gibi beşer türüne mensupsun; eğer sözünün arkasında duruyorsan, haydi bir delil getir de (görelim)!\""},{"n":155,"t":"\"(İstediğiniz delil), işte şu (sahipsiz) dişi devedir!\" dedi, \"Su içme hakkı (belli bir gün) ona, belli bir gün de size aittir."},{"n":156,"t":"Sakın ola ona bir kötülük yapayım demeyin! Bu takdirde sizi korkunç bir günün azabı yakalar.\""},{"n":157,"t":"Buna rağmen onlar, onu işkence yaparak vahşice katlettiler; fakat sonunda pişman oldular;"},{"n":158,"t":"çünkü onları malum azap kıskıvrak yakalamıştı. Elbet bu (Salih kıssası)nda da, alınacak bir ders mutlaka vardır; fakat insanları çoğu yine de inanmayacaklardır."},{"n":159,"t":"Ne ki senin Rabbin, sınırsız rahmet sahibi olan O yüceler yücesidir."},{"n":160,"t":"Lut kavmi (de) elçilerini yalanlamışlardı."},{"n":161,"t":"Hani bir zamanlar, onlara kardeşleri Lut şöyle demişti: \"Hala sorumlu davranmayacak mısınız?"},{"n":162,"t":"Hem bakın, ben size gönderilmiş güvenilir bir elçiyim:"},{"n":163,"t":"Şu halde Allah`a karşı sorumlu davranın ve beni izleyin!"},{"n":164,"t":"Ben bu (davet) karşılığında sizden hiçbir ücret talep etmiyorum; benim ecrimi takdir etmek sadece alemlerin Rabbine düşer.\""},{"n":165,"t":"\"İnsanların içerisinden erkeklere mi yaklaşıyorsunuz?"},{"n":166,"t":"Bu şekilde, Rabbinizin sizin için yarattığı eşlerinizi bir yana bırakıyorsunuz? Yoo, siz basbayağı sınırları çiğneyen bir toplumsunuz!\""},{"n":167,"t":"\"Eğer buna bir son vermezsen Ey Lut\" dediler, \"kesinlikle sürgün edilmiş biri olup çıkacaksın!"},{"n":168,"t":"(Lut): \"Bilin ki ben, bu yaptığınızdan dolayı sizi nefretle kınıyorum!\" dedi."},{"n":169,"t":"(Allah`a yönelerek): \"Rabbim!\" (dedi), \"Beni ve ailemi bunların yaptıkların(ın belasın)dan kurtar!\""},{"n":170,"t":"Sonuçta, Biz de onu ve ailesinin tamamını kurtardık;"},{"n":171,"t":"ancak bir kocakarı dökülenler arasında yer aldı."},{"n":172,"t":"Ardından ötekileri yerle bir ettik;"},{"n":173,"t":"sonunda (bela) sağanağını üzerlerine boca ettik: gör ki, uyarılan (fakat uslanmayan) kimselerin maruz kaldığı sağanak ne berbattır."},{"n":174,"t":"Elbet bu (Lut kıssası)nda da alınacak bir ders mutlaka vardır; fakat insanların çoğu yine de inanmayacaklardır."},{"n":175,"t":"Ne ki senin rabbin, sınırsız rahmet sahibi olan O yüceler yücesidir."},{"n":176,"t":"Ormanlık vadinin halkı (da) elçilerini yalanladı."},{"n":177,"t":"Hani bir zamanlar, Şuayp şöyle demişti: \"Hala sorumlu davranmayacak mısınız?\""},{"n":178,"t":"Hem bakın, ben size gönderilmiş güvenilir bir elçiyim."},{"n":179,"t":"Şu halde Allah`a karşı sorumlu davranın ve beni izleyin!"},{"n":180,"t":"Ben bu (davet) karşılığında sizden hiçbir ücret talep etmiyorum; benim ecrimi takdir etmek sadece alemlerin Rabbine düşer.\""},{"n":181,"t":"(Ölçüp biçerken) ölçüyü tam tutun, hak yiyenlerden olmayın!"},{"n":182,"t":"Ve doğruluktan şaşmayan bir teraziyle tartın!"},{"n":183,"t":"İnsanları hakları olan şeylerden mahrum bırakmayın ve kötülüğü yaygınlaştırarak yeryüzünde ahlaki çürümeye meydan vermeyin!"},{"n":184,"t":"`Sizi ve daha önceki nesilleri yaratan Allah`tan korkun.`"},{"n":185,"t":"Onlar dediler ki: \"Sen büyülenmiş birinden başkası değilsin!"},{"n":186,"t":"`Sen de ancak bizim gibi bir insansın; ve (biz) seni gerçekten yalancılardan sanıyoruz.`"},{"n":187,"t":"Fakat sen, eğer sözünün arkasındaysan haydi göğü paramparça başımıza indir!\""},{"n":188,"t":"(Şuayb) dedi ki: \"Rabbim yapıp ettiğiniz her şeyi çok iyi biliyor.\""},{"n":189,"t":"Neticede, onu işte böyle yalanladılar; bunun üzerine onları Gölge Günü`nün azabı yakalayıverdi; gerçekten de o pek korkunç bir günün azabıydı."},{"n":190,"t":"Elbet bu (Şuayb kıssası)nda da alınacak bir ders mutlaka vardır; fakat insanların çoğu yine de inanmayacaklardır."},{"n":191,"t":"Ne ki senin Rabbin sınırsız rahmet sahibi olan O yüceler yücesidir."},{"n":192,"t":"Şüphe yok ki bu (mesaj) elbet alemlerin Rabbi tarafından indirilmiştir:"},{"n":193,"t":"o Güvenilir Ruh ile birlikte geldi"},{"n":194,"t":"senin kalbine; ki (onunla) uyaran kimselerden biri olasın diye;"},{"n":195,"t":"açık bir Arapça ile..."},{"n":196,"t":"Yine kuşku yok ki bu (mesaj), öncekilerin hikmet yüklü sayfalarında da yer almakta."},{"n":197,"t":"İsrailoğullarına mensup alimlerin bunu bilmeleri onlar için delil olarak yeterli değil miydi?"},{"n":198,"t":"Ve eğer Biz onu yabancı birine indirseydik;"},{"n":199,"t":"o da o (mesajı) kendilerine okusaydı, yine de ona inanmazlardı."},{"n":200,"t":"İşte Biz vahyin, günaha batmışların kalplerinde (etki etmeden) geçip gitmesini böyle sağlamışızdır."},{"n":201,"t":"Can yakıcı bir azabı görünceye kadar bu (vahye) iman etmeyecekler;"},{"n":202,"t":"nihayet bu azap kendileri farkında değilken ansızın onları bulacaktır."},{"n":203,"t":"Bunun üzerine onlar \"Bize (ilave) bir süre daha tanınamaz mı?\" diyecekler."},{"n":204,"t":"Ne! Şimdi onlar azabımızın hemen gelmesini mi istiyorlar?"},{"n":205,"t":"Düşünsene bir: onlara yıllarca safa sürmeleri için fırsat versek;"},{"n":206,"t":"sonra vaad edilen azap başlarına gelse;"},{"n":207,"t":"safa sürerek kaçırdıkları bu fırsatın kendilerine bir yararı dokunabilir mi?"},{"n":208,"t":"Dahası, Biz bir ülkeyi helak etmeden önce illa ki uyarıp"},{"n":209,"t":"hatırlatmışızdır; zira Biz, asla zulmeden biri değiliz."},{"n":210,"t":"Hem bu (vahyi) asla şeytanlar indirmiş değildir."},{"n":211,"t":"Zira bu hem onların ağzının işi değildir, hem de buna güçleri yetmez:"},{"n":212,"t":"çünkü onlar (vahyi) işitmekten bile kesinlikle men edilmişlerdir."},{"n":213,"t":"Şu halde, Allah`la beraber başka bir ilaha yalvarıp yakarma! Bu takdirde azaba uğrayanlardan olursun."},{"n":214,"t":"Artık sana en yakın olan aşiretini uyar;"},{"n":215,"t":"ve seni izleyen mü`minlere kol kanat ger."},{"n":216,"t":"Eğer yakın akrabaların sana karşı gelirlerse, onlara “Yaptıklarınızdan uzağım” de!"},{"n":217,"t":"ve merhameti bol olan O yüceler yücesine güven!"},{"n":218,"t":"Ki O kıyam ettiğin vakit seni görmektedir;"},{"n":219,"t":"Allah`a teslim olanlar arasındaki tasarruflarını da..."},{"n":220,"t":"Çünkü O, evet yalnız O`dur her şeyi işiten, her şeyi bilen!"},{"n":221,"t":"O şeytanların kimlere indiğini size haber vereyim mi:"},{"n":222,"t":"Onlar kendini aldatmayı alışkanlık haline getiren her günahkara inerler;"},{"n":223,"t":"(yalana) kulak kabartırlar ve onların çoğu (başkalarına da) yalan söylerler."},{"n":224,"t":"Ve (Şamanlığa soyunan) şairler... Onları, batıl inanç peşindeki cahil ve bilinçsizler izlerler."},{"n":225,"t":"Görmez misin ki onlar, (hayat ve his alemindeki) her vadide şaşkın ve amaçsız gezinirler;"},{"n":226,"t":"ve onlar yapmadıklarını söylerler."},{"n":227,"t":"Ne var ki, iman eden ve salih amel işleyen, Allah`ı sürekli hatırda (ve hatırlı) tutan, zulme uğradıktan sonra haklarını savunanlar onlara dahil değildirler. Nihayet zulme gömülenler, nasıl bir devrimle devrileceklerini günü gelince öğrenecekler."}],[{"n":1,"t":"Ta-Sin! Bunlar Kur`an`ın, yani açık ve açıklayıcı olan ilahi kelamın ayetleridir."},{"n":2,"t":"inananlar için bir rehber ve bir müjdedir."},{"n":3,"t":"Onlar ki, namazı hakkını vererek kılarlar, arınıp yücelmek için ödenmesi gereken bedeli öderler; zira onlar, ahirete gönlü yatarak inananların ta kendisidirler."},{"n":4,"t":"Ahirete inanmayanlara gelince... Biz onlara yapıp ettiklerini süslemişizdir; bu yüzden onlar saplandıkları (kuşku) bataklığında debelenip dururlar;"},{"n":5,"t":"azabın en kötüsüne duçar olacak kimseler işte böyleleridir; ve onlar, evet onlardır en büyük kaybı yaşayacak olanlar."},{"n":6,"t":"Ve elbet sen de bu Kur`an`a, her şeyi bilen, her hükmünde tam isabet edenin katından nail kılınmaktasın."},{"n":7,"t":"Hani bir zamanlar Musa ailesine demişti ki: \"Bakın, gözüme ateş türü cazip bir şey ilişti; belki ondan size bir haber veya bir ateş koru getiririm de ısınırsınız.\""},{"n":8,"t":"Fakat oraya gelince kendisine şöyle seslenildi: \"Bu ışık kaynağının hem içinde hem de etrafında olan herkes mübarek kılınmıştır: zira Alemlerin Rabbi olan Allah`ın şanı pek yücedir."},{"n":9,"t":"(İmdi) Ey Musa! Her işinde mükemmel, her hükmünde isabetli olan Allah var ya? İşte O Benim!"},{"n":10,"t":"Şimdi asanı yere bırak!\" Fakat o asasının çevik ve kıvrak bir yılan gibi hızla aktığını görünce, ardına bakmadan kaçmaya başladı. (Allah) \"Ey Musa, korkma! Çünkü Benim huzurumda elçiler korkuya kapılmazlar!"},{"n":11,"t":"Ancak zulme bulaşanlar hariç. Fakat daha sonra, o kötülüğün ardından gidişatlarını iyi yönde değiştirirlerse, unutmasınlar ki Ben tarifsiz bir bağış, eşsiz bir rahmet kaynağıyım!\""},{"n":12,"t":"\"Şimdi de elini göğsüne sok! Her tür kusurdan arınmış olarak tertemiz, ışıl ışıl bir beyazlıkta çıkacaktır. Dokuz ayet de içinde olmak üzere, (bütün ayetlerle) Firavun ve kavmine git; çünkü onlar öteden beri yoldan çıkmış bir kavimdirler!"},{"n":13,"t":"Fakat onlara göz açıcı nitelikteki (mucizevi) ayetlerimiz gelince: \"Bu apaçık bir büyüdür\" dediler."},{"n":14,"t":"İç dünyalarında kesin kanaat getirdikleri halde, sırf gerçeği çarpıtma ve büyüklenmelerinden dolayı bile bile inkara saptılar: hele bir bak, fesatçıların akıbeti nasıl olurmuş?"},{"n":15,"t":"Doğrusu, Davud`a ve Süleyman`a da ilim vermiştik; o ikisi \"Bütün hamd, bizi mü`min kullarının birçoğundan üstün kılan Allah`a mahsustur!\" demişlerdi."},{"n":16,"t":"Ve Süleyman Davud`a varis oldu; ve \"Ey insanlar!\" diye seslendi, \"Bize kuşların mantığı öğretildi; ve bize bu alanda (gerekli olan) her şey bahşedildi; elbet bu, işte budur Allah`ın apaçık lütfu."},{"n":17,"t":"Ve (günlerden bir gün), Süleyman`ın cinden, insandan ve kuşlardan oluşan ordusu bir araya derilmiş ve zapturapt altına alınarak sevk edilmişti."},{"n":18,"t":"Derken karıncalar(ın olduğu) vadiye gelince, bir ana karınca \"Ey karıncalar!\" diye komut verdi; \"(Derhal) yuvalarınıza girin ki, Süleyman ve orduları farkına varmadan sizi çiğnemesin!\""},{"n":19,"t":"Komutu onun vermesinden dolayı (Süleyman) gülercesine tebessüm etti ve \"Rabbim!\" dedi, \"İç dünyamı öyle bir düzene sok ki, Senin bana ve ana-babama bahşettiğin nimetlere layıkıyla şükreden ve hep Senin hoşnut olacağın güzel işler yapan biri olayım; ve beni rahmetinle erdemli kullarının arasına kat!\""},{"n":20,"t":"Yine o (bir gün) kuşları denetliyordu; birden sordu: \"Hüdhüd`ü neden göremiyorum? Yoksa yine kayıplara mı karıştı?"},{"n":21,"t":"Ya karşıma geçerli ve ikna edici bir mazaretle çıkar; ya da onu şiddetli bir şekilde cezalandırır, daha olmazsa kafasını kopartırım!\""},{"n":22,"t":"Derken beklemesi çok sürmedi, (Hüdhüd) çıkageldi ve dedi ki: \"Ben senin henüz bilmediğin bir şeyi öğrendim ve sana Sebe`den doğru ve kesin bir haber getirdim."},{"n":23,"t":"Evet ben orada bir kadın buldum ki, o ora halkına yöneticilik yapıyor; (bir iktidara gerekli olan) her şeyden ona da verilmişti; üstelik onun pek muhteşem bir tahtı da vardı."},{"n":24,"t":"Ne ki onu ve kavmini Allah`ı bırakıp da güneşe tapar buldum. Öyle (anlaşılıyor) ki Şeytan onlara yaptıklarını güzel göstermiş. Onlar da yoldan sapmışlar ve bir daha da doğru yolu bulamamışlar."},{"n":25,"t":"Allah`a secde etmemeleri!?.. O Allah ki, göklerde ve yerde gizli saklı ne varsa ortaya çıkarır; dahası gizlediklerinizi de açığa vurduklarınızı da iyi bilir;"},{"n":26,"t":"Allah, kendisinden başka ilah olmayan, muhteşem ve mutlak hükümranlık makamının Rabbidir!\""},{"n":27,"t":"(Süleyman): \"Doğru mu söylüyorsun yoksa yalancının teki misin, göreceğiz\" dedi (ve ekledi):"},{"n":28,"t":"\"Bu mektubumu al onlara ulaştır; sonra onlardan uzaklaşıp bir köşeye çekil de bak bakalım, nasıl bir sonuca varacaklar.\""},{"n":29,"t":"(Sebe kraliçesi mektubu alınca): \"Siz ey seçkinler!\" dedi, \"Elime çok önemli bir mektup geçti."},{"n":30,"t":"Evet o Süleyman`dan gelen bir mektup ve o şöyle (başlıyor): \"Rahman Rahim Allah`ın adıyla:"},{"n":31,"t":"Bana karşı büyüklük taslamayın ve bana gönülden teslim olmuş olarak gelin!\""},{"n":32,"t":"(Sebe kraliçesi) dedi ki: \"Siz ey seçkinler! Karşı karşıya kaldığım bu konuda bana kanaatlerinizi bildirin! Sizin katkınız olmadan bu konuda kestirip atmam doğru olmaz.\""},{"n":33,"t":"(Seçkinler) şöyle dediler: \"Biz güçlüyüz ve caydırıcı şiddete bir (askeri) yeteneğe sahibiz. Yine de emir senindir. Şu halde ne emredeceğine sen karar ver!\""},{"n":34,"t":"(Sebe kraliçesi): \"Bakın!\" dedi, \"Krallar bir ülkeye ne zaman (zorla) girmişlerse, orayı perişan etmişler, üstelik oranın soylu insanlarını zelil kılmışlardır: vakıa, bunlar da öyle yapacaklar."},{"n":35,"t":"İşte bu nedenle ben onlara bir armağan göndereceğim ve bakacağım, elçiler nasıl bir (haberle) dönecekler.\""},{"n":36,"t":"(Sebe kraliçesinin elçisi) Süleyman`a gelince, o şöyle dedi: \"Güya servetle beni tavlamış mı oluyorsunuz? Ama Allah`ın bana verdiklerinin, sizin bana verdiğinizden kat kat hayırlı olduğunu biliniz. Bilakis sunduğunuz hediyeler, yine sizin (gibi tek dünyalıları) sevindirir."},{"n":37,"t":"Seni (gönderenlere) dön ve (Allah`ın şu buyruğunu ilet): \"Andolsun karşı konulmaz bir orduyla onların üzerine yürüyeceğiz ve elbette onları küçük düşürülmüş bir halde hor ve hakir olarak oradan çıkaracağız!\""},{"n":38,"t":"(Süleyman, Kraliçe`nin davete icabet edeceğini anlayınca) dedi ki: \"Siz ey maharetli kişiler! Onlar, gönülden teslim olmuş kişiler olarak bana gelmeden önce, aranızdan kim onun tahtını bana getirebilir?\""},{"n":39,"t":"Görünmeyen varlıklara mensup (şeytani) maharette biri \"Sen daha oturduğun yerden kalkmadan onu sana getiririm; çünkü ben bu konuda güvenilir bir güce sahibim\" dedi."},{"n":40,"t":"Kendisinde vahiyden bir bilgi bulunan kimse \"Ben\" dedi, \"sana onu gözünü açıp kapayıncaya kadar getiririm!\" Derken, onu önünde kurulu bir biçimde görünce dedi ki: \"Rabbimizin mahza bir lütfu bu; şükür mü nankörlük mü edeceğim diye beni sınıyor. Oysa ki şükreden kendi iyiliği için şükretmiş olur. Ama kim de nankörlük ederse, iyi bilsin ki Rabbim kendi kendine yetendir, (mahlukata karşı da) sınırsız cömerttir.\""},{"n":41,"t":"Sözünü şöyle sürdürdü: \"Onun tahtını kendisinin tanıyamacağı bir hale getirin de, görelim bakalım doğru yolu bulacak mı? Yoksa doğru yolu bulamayan kimselerden mi olacak?\""},{"n":42,"t":"(Sebe kraliçesi) gelince, ona \"Senin tahtın da böyle miydi?\" denildi; o da \"Sanki bu tıpkı o!\" dedi. Ve (Süleyman şöyle dedi): \"Hakikatin bilgisi ondan önce bize verilmişti, bu yüzden de biz müslüman olduk;"},{"n":43,"t":"ona ise Allah`ı bırakıp da tapınageldiği şeyler engel oldu; çünkü o zaten hakikati ısrarla inkar eden bir toplumun mensubuydu.\""},{"n":44,"t":"(Sebe kraliçesine); \"Saraya buyurun!\" denildi. Fakat sarayı görünce, onun (önünde) derin bir su var sandı ve eteğini kaldırdı. (Süleyman) dedi ki: \"Bu, tabanı kristalle kaplı bir saraydır.\" Kadın \"Rabbim!\" dedi, \"Ben kendime kötülük etmişim! Artık ben de Süleyman`la beraber Alemlerin Rabbine gönülden teslim oldum.\""},{"n":45,"t":"Doğrusu Semud`a da, soydaşları Salih`i \"Yalnız Allah`a kulluk edin!\" desin diye göndermiştik. Fakat onlar birbiriyle çekişen iki fırkaya ayrılıverdiler."},{"n":46,"t":"(Salih) \"Ey kavmim!\" dedi, \"Niçin iyi olan dururken kötü olanın çabucak gelmesini istiyorsunuz? Niçin Allah`tan af dilenmiyorsunuz? Belki ilahi rahmete nail olursunuz.\""},{"n":47,"t":"Onlar \"Biz, senin ve seninle beraber olanların uğursuzluk getirdiğine inanıyoruz\" dediler. (Salih): \"Uğurunuz Allah`ın takdirindedir; kaldı ki siz (besbelli ki) sınanan bir toplumsunuz\" dedi."},{"n":48,"t":"Vakı`a, malum kentte dokuz elebaşı vardı; bunlar düzeni sağlamadıkları gibi, bozgunculuktan geri durmuyorlardı."},{"n":49,"t":"Allah adına yemin ederek dediler ki: \"Ona ve yakınlarına geceleyin baskın yapıp (ortadan kaldıralım); ardından da kanını dava edecek olanlara `Biz onun ailesinin ortadan kaldırılmasına asla karışmadık; çünkü biz kesinlikle özü sözü doğru insanlarız` diyelim\" demişlerdi."},{"n":50,"t":"Ve onlar bir tuzak kurdular; Biz de onlar farkına varmadan tuzaklarını boşa çıkardık."},{"n":51,"t":"Dön de bir bak bakalım: onların tuzaklarının akıbeti ne olmuş? Elbette ki Biz, onları ve toplumlarını topyekün yerle bir ettik."},{"n":52,"t":"Bak işte onların mekanları: İşledikleri zulümler yüzünden viran ve ıssız kalmış! Elbet bunda, işin bilincinde olan bir toplum için alınacak bir ders mutlaka vardır."},{"n":53,"t":"Yine, iman edip sorumluluk bilinciyle hareket eden kimseleri kurtarmış olmamızda da..."},{"n":54,"t":"Ve Lut`u da (kurtarmıştık). Hani o bir zamanlar kavmine şöyle demişti: \"Siz (fıtrattan sapma olduğunu) göre göre bu (tür bir) fuhuşu işlemeyi sürdürecek misiniz?"},{"n":55,"t":"Siz kadınları bırakıp da şehvetle erkeklere mi yanaşıyorsunuz? Gerçekten siz bilgisiz bir toplumsunuz.`"},{"n":56,"t":"Buna karşılık kavminin cevabı, \"Lut (ve) yakınlarını ülkenizden çıkarın! Belli ki bunlar pek temiz (!) insanlarmış!\" demekten başka bir şey olmadı."},{"n":57,"t":"Derken, Biz onu ve (iman) ailesini kurtardık; ancak karısının dökülenler arasında yer almasına karar verdik."},{"n":58,"t":"Nihayet (bela) sağanağını üzerlerine boca ettik: ve uyarılan (fakat uslanmayan) kimselerin maruz kaldığı sağanağın ne berbat olduğunu (gösterdik)!"},{"n":59,"t":"De ki: \"Bütün hamd yalnız Allah`a, selam da O`nun seçip beğendiği kullarına olsun!\" (Şimdi söylesinler): Allah mı daha hayırlı, yoksa ortak koştukları varlıklar mı?"},{"n":60,"t":"(Allah) değilse kimdir gökleri ve yeri yaratan? Dahası, gökten sizin için su indiren? Üstelik onunla sizin bir tek ağacını bile yetiştiremeyeceğiniz, içinden su çıkan göz bebeği seçkin bahçeler yeşertmişiz. Allah`la beraber başka bir ilah ha?! Yoo, onlar yoldan sapmış bir toplum olmalı."},{"n":61,"t":"(Allah) değilse kimdir yeryüzünü dinlenme yeri kılan ve vadilerinden ırmaklar akıtmış olan; ve kalkmaz ve kımıldamaz dağlar inşa etmiş olan; ve iki (farklı) su kütlesi arasına bir engel yerleştirmiş olan? Hala Allah`la beraber başka bir ilah ha?! Yoo, onların çoğu (nereden bakacaklarını) bilmiyorlar?"},{"n":62,"t":"(Allah) değilse kimdir dua ettiğinde darda kalanın yardımına yetişecek olan ve sıkıntıyı giderecek olan; ve sizi yeryüzünün halifeleri yapacak olan? Allah`la beraber başka bir ilah, öyle mi?! Öğüt alanlarınız ne kadar da azınlıkta kalıyor!"},{"n":63,"t":"(Allah) değilse kimdir karanın ve denizin zifiri karanlıklarında yol bulmanızı sağlayan? Ve rüzgarları rahmetinin önü sıra müjdeci olarak gönderen? Allah`la beraber başka bir ilah ha?! Allah, onların ortak koştukları her şeyden aşkın ve yücedir."},{"n":64,"t":"(Allah) değilse kimdir yaratılışı ilk defa başlatan ve onu tekrar tekrar yenileyen? Dahası, kimdir sizi gökten ve yerden rızıklandıran? Allah`la beraber başka bir ilah ha? De ki: \"Eğer sözünüzün arkasında duruyorsanız, haydi delilinizi getirsenize!\""},{"n":65,"t":"De ki: \"Göklerde ve yerde Allah`tan başka hiç kimse, idraki aşan hakikatleri asla kavrayamaz; hiç kimse öldükten sonra ne zaman diriltileceğini de bilemez."},{"n":66,"t":"Değilse, ahirete ilişkin (hakikatler) onların idrak edebileceği bir biçimde baştan sona bilgilerine sunulmuştur. Gel gör ki onlar, ondan yana hala kuşku içindedirler; daha beteri, ondan yana kördürler!"},{"n":67,"t":"Bu yüzden, inkarda direnen kimseler şöyle dediler: \"Ne yani, biz ve atalarımız toprağa karışıp gittikten sonra yeniden çıkarılacağız, öyle mi?"},{"n":68,"t":"Doğrusu bize ve atalarımıza bu vaad önceden de yapılmıştı. Bu, eskilerin masallarından başka bir şey değil.\""},{"n":69,"t":"De ki: \"Yeryüzünde dolaşın da, günahı tabiat haline getirenlerin sonu ne olmuş, görün!\""},{"n":70,"t":"Yine de sen onlar için hüzünlenme! Ve onların hile ve desiselerinden dolayı sıkıntılanma!"},{"n":71,"t":"Bir de diyorlar ki: \"(Azaba ilişkin) bu tehdidiniz ne zaman gerçekleşecek, eğer sözünüze sadıksanız haber verin bakalım?\""},{"n":72,"t":"De ki: \"Belki de, acele gelmesini istediğiniz o azabın bir kısmı peşinize çoktan takılmıştır bile!\""},{"n":73,"t":"Yine de unutma ki, senin Rabbin insanlığa karşı pek lütufkardır; ve fakat insanların çoğu şükretmemektedir."},{"n":74,"t":"Yine unutma ki, senin Rabbin onların kalplerinin gizlediklerini de açığa vurduklarını da elbette bilir."},{"n":75,"t":"Ne gökte ne de yerde gizli ve gizemli hiç bir şey yoktur ki, kesin ve net bir yazılım ve yasayla kayıt altına alınmamış olsun."},{"n":76,"t":"Hiç şüphesiz bu Kur`an, İsrailoğullarının üzerinde ihtilafa düştükleri bir çok konuya açıklık getirmektedir."},{"n":77,"t":"Çünkü o da, inananlar için bir rehber ve bir rahmettir."},{"n":78,"t":"Elbette senin Rabbin, onların arasında kendi verdiği hükmü uygulayacaktır: zira O en yüce olandır, her şeyi bilendir."},{"n":79,"t":"Şu halde yalnızca Allah`a dayan! Çünkü senin dayanağın, doğruluğu açık ve kesin olan hakikattir."},{"n":80,"t":"Şu bir gerçek ki, sen ölülere işittiremezsin. Dahası, bu daveti sırtını dönüp uzaklaşan sağırlara da işittiremezsin."},{"n":81,"t":"Yine, yoldan çıkan körleri doğru yola getirecek olan da sen değilsin. Sen ancak ayetlerimize inananlara duyurabilirsin; ki zaten onlar gönülden teslim olan kimselerdir."},{"n":82,"t":"Ve (o vahyi işitmeyen ölüler ve sağırlar) aleyhindeki söz gerçekleştiği zaman, onlar için yerden bir canlı çıkarırız; o onları mesajlarımıza öteden beri insanların yürekten inanmamış olduklarını söyler."},{"n":83,"t":"İşte o gün, her bir ümmetten ayetlerimizi yalanlayanlara özgü birer bölük oluşturacağız; ve onları (öylece) sevk edeceğiz."},{"n":84,"t":"Ta ki (huzura) geldikleri zaman, (Allah) onlara \"Aklınızın kapasitesi onları kavramaya yetmediği için ayetlerimizi yalanlamaya mı kalktınız? Eğer öyle değilse, bugüne dek ne hazırladınız?\" diyecek."},{"n":85,"t":"İşte onların tüm çarpıtmalarına rağmen kendileri aleyhindeki söz böyle yerini bulmuş olacak. Dahası, bu durum karşısında onlardan çıt çıkmayacak."},{"n":86,"t":"Hem onlar, geceyi bağrında dinlensinler diye (karanlık), gündüzü de (hayatın çift kutuplu yasasını) görsünler diye (aydınlık) kıldığımızı hiç mi düşünmediler? Elbet bunda inanacak bir toplum için, alınacak bir ders mutlaka vardır."},{"n":87,"t":"Ve o gün sura üflenecek; bunun üzerine, Allah`ın dilediği kimseler hariç, göklerde ve yerde bulunan herkes dehşetten paniğe kapılacak; nihayet herkes, başı önde, O`nun huzuruna varacaktır."},{"n":88,"t":"İmdi, hareketsiz ve sabit sandığın dağların kayıp giden bulutlar (gibi) gittiğini görürsün: her şeyi mükemmel bir nizama bağlayan Allah`ın sanatıdır bu: Şüphe yok ki, yaptığınız her şeyden haberdar olan da yine O`dur."},{"n":89,"t":"Kim güzel eylemlerle (huzura) gelirse, daha hayırlısıyla karşılığını bulacaktır; üstelik onlar o günün dehşetinden emin olacaklardır."},{"n":90,"t":"Kim de kötü maksatlı eylemlerle (huzura) gelirse, artık onlar da yüzüstü ateşe kapaklanacaklardır: Şimdi siz, yapıp ettiklerinizin dışında başka bir karşılık mı bekliyordunuz?"},{"n":91,"t":"(Ey Peygamber! De ki): \"Ben yalnızca O`nun mübarek kıldığı şu şehrin Rabbine kulluk etmekle emrolundum: zira her bir şey O`na aittir. Yine ben O`na gönülden teslim olanlardan biri olmakla emrolundum!"},{"n":92,"t":"Bir de bu Kur`an`ı (insanlara) okuyup iletmekle...\" Bundan böyle kim doğru yola yönelirse, o kendisi için doğruyu bulmuş olur; kim de yoldan saparsa, o zaman de ki: \"Ben sadece bir uyarıcıyım.\""},{"n":93,"t":"Nihayet dedi ki: \"Hamd olsun O Allah`a ki, size alamet ve işaretlerini gösterecek; derhal siz de onları tanıyacaksınız.\" Ve Rabbin yaptıklarınıza karşı asla duyarsız değildir."}],[{"n":1,"t":"Ta-Sin-Mim!"},{"n":2,"t":"Bunlar kitabın açık ve açıklayıcı olan ayetleridir."},{"n":3,"t":"İmanlı bir toplum (oluşturmak) için, sana Musa ve Firavun arasında geçen olaylardan bir kısmını sahih bir amaca uygun olarak aktaracağız."},{"n":4,"t":"Şu bir gerçek ki, Firavun malum ülkede zorbaca baskı kurmuş ve ülke halkını kastlara ayırmıştı. Onlardan bir sınıfı zayıf ve güçsüz düşürmek istiyor, (bu yüzden) çocuklarını öldürtüp kadınlarını sağ bırakıyordu; çünkü o, gerçekten de bozguncunun tekiydi."},{"n":5,"t":"Ve Biz de istiyorduk ki, ülkede zayıf ve güçsüz bırakılanlara destek çıkalım ve onları öncüler yapalım; ve kendilerini (ülkeye) varis kılalım;"},{"n":6,"t":"dahası onları yeryüzünde güvenli biçimde yerleştirelim; Firavun`u, Haman`ı ve bunların ordusunu, berikilerin eliyle korktukları şeye uğratalım."},{"n":7,"t":"İşte (bunu gerçekleştirmek için) Musa`nın annesine şöyle vahyettik: \"Onu (bir müddet) emzir! Fakat onun başına bir şey gelmesinden korktuğun zaman onu suya bırak; sakın korkayım ve üzüleyim deme! Çünkü Biz kesinlikle onu sana geri döndüreceğiz ve onu elçilerden biri yapacağız!\""},{"n":8,"t":"Derken, Firavun`un ailesi onu buldu; sonunda kendileri için bir düşman ve bir hüzün kaynağı olacak (bu bebeği) sahiplendiler. Belli ki Firavun, Haman ve onların askerleri yanılgı içindeydiler."},{"n":9,"t":"Firavun`un karısı \"İşte, benim için de senin için de bir göz aydınlığı!\" dedi, \"Onu öldürmeyin; bakarsın bize bir yararı dokunur ya da onu evlatlık edinebiliriz.\" Ama berikiler, (olacakların) asla farkında değildiler."},{"n":10,"t":"Bu arada Musa`nın annesi, gönlü onun acısıyla dolu olarak sabahı etti. Öyle ki (vaadimize) inanıp güvenenlerden biri olması için kalbini sımsıkı pekiştirmiş olmasaydık, az kalsın onun kimliğini açığa vuracaktı."},{"n":11,"t":"İşte o anne bu haldeyken, Musa`nın ablasına \"Onu izle!\" dedi. Bunun üzerine kız onu uzaktan izlemeye koyuldu. Hala onlar hiçbir şeyin farkında değildiler."},{"n":12,"t":"Ve Biz daha ilk günden onun (Mısırlı) süt anneleri (emmekten) geri durmasını sağladık. Bu durumu (öğrenen kız kardeşi) \"Onun bakımını sizin adınıza üstlenecek bir aile göstermemi ister misiniz?\" dedi (ve ekledi): \"Hem, onlar onu iyi eğitirler.\""},{"n":13,"t":"Ve sonunda onu annesine döndürdük kü, gözü aydın olsun ve üzülmesin diye... Dahası insanların çoğu bunu bilmese de, kendisi Allah`ın vaadinin kesin bir gerçek olduğunu bilsin diye..."},{"n":14,"t":"Derken (Musa) erişkinlik dönemini tamamlayıp (aklen) iyice olgunlaşınca, ona üstün bir muhakeme ve seçip ayırma yeteneği kazandıran bir bilgi bahşettik: Biz dürüst ve erdemli davrananları işte böyle ödüllendiririz."},{"n":15,"t":"Ve (Musa) halkından bir kısmının gaflete daldığı bir zamanda kente girdi ve orada iki adamı birbirleriyle kavga ederken buldu. Bunlardan biri kendi halkına, diğeri düşman tarafına mensuptu. Derken kendi halkından olan, düşmanca mensup olana karşı ondan yardım istedi. Yerinden fırlayan Musa ona bir yumruk vurdu ve hesabını gördü. (Fakat kendine geldiğinde) \"Bu Şeytan`ın işi!\" dedi, \"Çünkü o, kişiyi yoldan çıkaran apaçık bir düşmandır.\""},{"n":16,"t":"(Ardından) \"Rabbim!\" dedi, \"Ben kendime kötülük ettim! Ne olur beni affet!\" Bunun üzerine Allah onu affetti: çünkü O, evet O`dur mutlak bağış sahibi, sonsuz merhametin kaynağı da O`dur."},{"n":17,"t":"(Yine o) \"Rabbim!\" dedi, \"Bahşettiğin nimet hakkı için, suçlu ve haksız kimselere bundan böyle asla arka çıkmayacağım.\""},{"n":18,"t":"Ve ertesi sabah, söz konusu kentte endişeyle etrafı kolaçan ederek dolaşıyordu. Fakat o da ne? Dün ondan yardım isteyen adam, kendisini yine yardıma çağırmıyor mu? Musa ona: \"Besbelli ki sen iyice zıvanadan çıkmışsın!\" dedi."},{"n":19,"t":"Fakat bir yandan da her ikisinin ortak düşmanı olan kimseyi yakalamaya girişmişti. O kişi \"Ey Musa!\" dedi, \"Daha dün öldürdüğün adam gibi beni de mi öldürmek istiyorsun? Anlaşılan senin arzun haksızlıkları gideren ve düzeltenlerden biri olmak değil, ülkenin başına zorba kesilmek.\""},{"n":20,"t":"İşte bu sırada kentin öteki ucundan bir adam koşarak geldi ve \"Ey Musa!\" dedi, \"Soylular seni öldürmek için hakkında görüşme yapıyorlar, derhal (burayı) terk et! Ve şunu da unutma ki, ben senin iyiliğini isteyen biriyim.\""},{"n":21,"t":"Bunun üzerine, korku dolu gözlerle etrafa bakınarak orayı terk ederken, bir yandan şöyle yakarıyordu: \"Rabbim! Beni şu zalim toplumun elinden kurtar!\""},{"n":22,"t":"Ve Medyen`e doğru yola koyulurken: \"Umarım Rabbim beni doğru yola yönlendirir\" dedi."},{"n":23,"t":"Ve (Musa) Medyen sularına ulaşınca, orada (hayvan) sulayan bir gurup insanla karşılaştı; ve onların az ötesinde iki kadını hayvanlarına sahip olmaya çalışırken buldu. O ikisine \"Size nasıl yardımcı olabilirim?\" dedi. Onlar \"Bu çobanlar işini bitirip ayrılıncaya dek biz (hayvanlarımızı) sulayamıyoruz; (biz kadınız) ve babamız da çok yaşlı biri\" diye cevap verdiler."},{"n":24,"t":"Bunun üzerine (Musa) onların (hayvanlarını) suladı; ardından gölgeye çekilip şöyle yalvardı: \"Rabbim! Bana bahşetmiş olduğun bu tür bir hayra öylesine muhtacım ki!\""},{"n":25,"t":"Derken, o kızlardan biri utana sıkıla çıkagelerek dedi ki: \"Babam (hayvanlarımızı) sulamana karşılık ikram etmek üzere seni davet ediyor.\" (Musa) onun yanına varınca, olan biteni bir bir anlattı. O, \"Korkma!\" dedi, \"Zalim kavmin elinden artık kurtulmuş oldun.\""},{"n":26,"t":"Kızlardan biri: \"Babacığım!\" dedi, \"Onu ücret karşılığı yanında tut! Çünkü ücret karşılığı tutabileceğin güçlü ve güvenilir kimselerin en iyisi bu olacaktır.\""},{"n":27,"t":"(Kızların babası Musa`ya): \"Bana bak!\" dedi, \"İşte şu iki kızımdan birisini, bana sekiz yıl işçilik yapman karşılığında seninle evlendirmek istiyorum; fakat bu süreyi on yıla tamamlarsan, artık o da senin bileceğin iştir; zira ben seni zahmete koşmak istemem; inşaallah sen beni hep dürüst ve erdemli davranan bir (işveren) olarak bulacaksın!\""},{"n":28,"t":"(Musa): \"Bu seninle benim aramda kalsın!\" dedi, \"İki süreden hangisini doldurursam doldurayım, artık bana karşı bir husumet olmasın; ve Allah bu söylediklerimize tanık olsun!\""},{"n":29,"t":"Nihayet Musa belirlenen süreyi tamamlayıp da yakınlarıyla birlikte yola koyulunca, gözüne (Sina) Dağı`nın yamacından (şavkıyan) ateş türü cazip bir şey ilişti. Ailesine dedi ki: \"Siz bekleyin, gözüme ateş türü cezbedici bir şey ilişti; belki size ondan bir haber ya da ateşten bir köz getiririm de, bu sayede ısınırsınız!\""},{"n":30,"t":"Fakat oraya varınca, o bereketli mevkide, vadinin sağ yamacındaki ağaç (yönü)nden kendisine \"Ey Musa! Benim... Ben, Alemlerin Rabbi olan Allah!\" diye seslenildi."},{"n":31,"t":"Ve (o ses şöyle) devam etti: \"Asanı yere bırak!\" Fakat o asasının küçük ve çevik bir yılan gibi hareket ettiğini görünce, ardına bakmadan dönüp kaçmaya (başladı). \"Ey Musa! Yaklaş ve korkma, çünkü sen güvence altında olanlardan birisin!"},{"n":32,"t":"(Şimdi) elini göğsüne sok! Her tür kusurdan arınmış olarak tertemiz, ışıl ışıl bir beyazlıkta çıkacaktır. Haydi tüm korku, hüzün ve kaygılarından uzaklaşarak kendini topla! İşte bu ikisi senin, Firavun ve onun kurmaylarına Rabbin katından (gönderildiğinin) açık belgeleridir: çünkü onlar yoldan sapmış bir toplum olup çıktılar.”"},{"n":33,"t":"(Musa) \"Rabbim!\" dedi, \"Onlardan birini öldüren benim; buna karşılık onların da beni öldürmelerinden endişe ederim."},{"n":34,"t":"İşte kardeşim Harun! Onun dili benden daha açık, daha düzgün: beni destekleyip doğrulayan bir yardımcı olarak onu da benimle birlikte gönder! Çünkü, beni yalanlamalarından korkuyorum.\""},{"n":35,"t":"(Allah); \"Senin pazunu kardeşinle güçlendireceğiz ve size öyle etkin bir güç ve yetki vereceğiz ki, ikinize de asla ilişemeyecekler; ve ayetlerimiz sayesinde sizler ve sizi izleyenler galip gelecekler.\""},{"n":36,"t":"Musa onların karşısına hakikatin apaçık belgeleri olan ayetlerimizle çıkanca \"Bu tasarlanıp ortaya atılmış bir büyüden başkası değildir; zira biz önden giden atalarımızın geleneğinde böyle bir şey olduğunu işitmedik!\" dediler."},{"n":37,"t":"Ve Musa: \"O`nun katından, doğru yol kılavuzuyla gelenin kim olduğu ve bu yurdun en sonunda kime kalacağını benim Rabbim daha iyi bilir; şu bir gerçek ki, zalimler asla başarıya ulaşamazlar\" dedi."},{"n":38,"t":"Firavun ise: \"Siz ey efendiler!\" dedi, \"Sizin için (hayatınıza müdahil olan) benden başka bir ilah hiç tanımadım. Ve sen ey Haman! Benim için tuğla ocağını tutuştur da, bana yüce bir yapı inşa ediver! Kim bilir, belki o zaman Musa`nın ilahına ulaşabilirim; hoş, ben onun yalancının teki olduğundan eminim ya.\""},{"n":39,"t":"İşte o ve onun askerleri yeryüzünde haksız yere büyüklendiler; ve sandılar ki kendileri Bizim huzurumuza hiç çıkmayacaklar."},{"n":40,"t":"Sonunda onu ve askerlerini enseledik ve onları denize gömdük: Bak gör işte, zalimlerin akıbeti nasıl olurmuş!"},{"n":41,"t":"Ve onları, (takipçilerini) ateşe çağıran rehberler kıldık; onlara kıyamet günü yardım da edilmeyecektir."},{"n":42,"t":"Zira Biz, lanet (halkasını) daha bu dünyada onların (yüreklerine) geçirmişizdir; Kıyamet Günü`nde ise aşağılık ve iğrenç olan yine onlar olacaktır."},{"n":43,"t":"Ve doğrusu, önceki nesilleri (hak ettikleri) helaka sürükledikten sonra insanlık için bilinç kaynağı, bir doğru yol rehberi ve bir rahmet membaı olarak Musa`ya Kitab`ı verdik ki belki (sorumluluklarını) hatırlarlar."},{"n":44,"t":"Ve sen (Ey Peygamber)! Biz (vadinin bir yamacında) Musa`ya bu Emr`i bildirirken, sen vadinin öbür yamacında değildin; dolayısıyla (olan biteni oradan) izleyen tanıklardan da değildin."},{"n":45,"t":"Tam aksine, Biz (o günden bu güne) nice kuşaklar var ettik ve bunların üzerinden de nice zaman akıp gitti. Dahası Sen, kendilerine mesajlarımızı iletmek için Medyen sakinleri arasında bulunmuş da değildin; fakat (bu mesajları) öteden beri gönderip duran da yine Bizdik."},{"n":46,"t":"Yine sen, Biz nida ettiğimizde (Sina) Dağı`nın yamacında da değildin; ve fakat senden önce uyarıcı gelmemiş bir toplumu uyarman için Rabbin tarafından rahmet olarak gönderildin; belki (sorumluluklarını) hatırlarlar."},{"n":47,"t":"İmdi muhataplar, elleriyle işledikleri yüzünden başlarına bir musibet gelmesi durumunda: \"Rabbimiz! Keşke bize bir elçi gönderseydin de biz de Senin mesajlarına uyup inanan kimselerden olsaydık, olmaz mıydı?\" demesinler diye (gönderdik seni)."},{"n":48,"t":"Ama, kendilerine Bizim katımızdan gerçeğin ta kendisi geldiğinde: \"Musa`ya verilenin bir benzeri ona da verilseydi ya!\" derler. Peki ama, onlar bundan önce Musa`ya geleni de inkar etmemişler miydi? (Bu kez de) \"Birbirini destekleyen iki gözbağcılık mahsulü\" diyorlar ve ilave ediyorlar: \"Zaten biz, hepsini birden inkar ediyoruz.\""},{"n":49,"t":"De ki: \"Eğer doğru sözlü kimselerseniz, haydi Allah katından doğru yolu bu ikisinden daha iyi yönelten başka bir kitap getirin de, ben de ona uyayım.\""},{"n":50,"t":"Fakat eğer senin (bu çağrına) cevap veremiyorlarsa, iyi bil ki onlar kendi keyfi ve bencil yargılarına uyuyorlar. Allah`ın rehberliği dışında kendi keyfi ve bencil yargılarına uyan kişiden daha sapkın biri olabilir mi? Şüphe yok ki Allah, zulmü tabiat haline getiren bir toplumu doğru yola yöneltmez."},{"n":51,"t":"Doğrusu Biz bu ilahi sözü onlara adım adım ulaştırdık ki, belki (sorumluluklarını) hatırlarlar."},{"n":52,"t":"Kendilerine daha önce kitap vermiş olduğumuz kimseler ona inanmak durumundadırlar."},{"n":53,"t":"Onlar, kendilerine (Kur`an vahyi) iletildiğinde: \"Buna iman ettik, çünkü bu Rabbimizden gelen hakikatin ta kendisidir; zaten biz bundan önce de (O`na) kayıtsız şartsız teslim olmuş kimselerdik!\" derler."},{"n":54,"t":"İşte, her şeye (rağmen hakta) direnmelerine, kötülüğü iyilikle savmalarına ve kendilerine rızık olarak verdiklerimizden infak etmelerine karşılık, kendilerine iki kat ecir verilecek olan böyleleridir."},{"n":55,"t":"İşte onlar, düşüncesizce söylenmiş bir söz işittiklerinde ondan yüz çevirirler ve \"Bizim yaptıklarımızın sorumluluğu da size aittir; yolunuz açık olsun; biz kendini bilmezlerle bir arada bulunmak istemeyiz\" derler."},{"n":56,"t":"Şüphesiz ki sen sevdiğin herkesi doğru yola yöneltemezsin; ve fakat Allah (isteyenin) doğru yola yönelmesini diler: zira O kimin doğru yola girmek istediğini çok iyi bilir."},{"n":57,"t":"Bir de, “Eğer seninle birlikte doğru yola girersek, yurdumuzdan yuvamızdan koparılırız” dediler. Onları, sayemizde her türlü ürünün gelip rızık olarak kendisinde toplandığı kutsal bir dokunulmazlığa sahip güvenli bir yere Biz yerleştirmedik mi? Ne ki onların çoğu bunun bilincinde bile değil."},{"n":58,"t":"Ama Biz, refahın şımartıp azgınlaştırdığı nice ülkeyi helak etmişiz. Bakın, işte onların yaşadıkları mekanlar! Pek azı dışında arkalarından oralara bir daha yerleşen olmadı: ve zaten her şeyin ebedi varisi sadece Biziz."},{"n":59,"t":"Ama senin Rabbin hiçbir ülkeyi, onların ana kentine kendilerine mesajlarımızı okuyup açıklayan bir elçi göndermedikçe asla helak etmemiştir. Zaten Biz başkalarını değil, sadece fertlerinin (birbirine) zulmettiği toplumları helak etmişizdir."},{"n":60,"t":"Ve size her ne verilmişse, hepsi de dünya hayatının kısa vadeli hazları ve süsüdür; Allah katında olanlarsa daha hayırlı ve daha kalıcıdır: Hala akletmeyecek misiniz?"},{"n":61,"t":"Şimdi kendisine tarifsiz güzellikte bir vaadde bulunduğumuz ve sonunda ona kavuşan kimsenin durumu, kendisine dünya hayatının tadımlık hazlarını tattırdığımız ve Kıyamet Günü yargı önüne çıkarılacak birinin durumuyla aynı olur mu?"},{"n":62,"t":"İşte o gün (Allah) onlara seslenecek ve \"Öteden beri Bana ortak olduğunu sandıklarınız hani, neredeler?\" diye soracak."},{"n":63,"t":"Aleyhlerindeki sözün gerçekleştiğini gören kimseler: \"Rabbimiz!\" diyecekler; \"İşte şunlar bizim azdırdıklarımız; kendimiz azdığımız gibi onları da azdırdık: (onlarla) ilişiğimizi kesip sana sığınıyoruz; zaten onlar aslında bize tapıyor değildiler.\""},{"n":64,"t":"Sonunda onlara: \"Çağırın ortak (koştuk)larınızı!\" denilecek ve onları yardıma çağıracaklar, fakat kendilerine asla karşılık verilmeyecek ama azabı görüverecekler. Ne olurdu sanki, daha önceden doğru yolu bulmuş olsalardı!"},{"n":65,"t":"İşte o gün (Allah) onlara seslenecek ve \"Gönderilen elçilere nasıl bir karşılık verdiniz?\" diye soracak."},{"n":66,"t":"Fakat artık onlara (kendilerini kurtaracak) haberlerin yolu kapanmış olacak; dahası onlar, birbirlerine de soramayacak."},{"n":67,"t":"Ama tevbe eden, iman eden ve imana uygun davrananlara gelince: işte böylelerinin kurtuluşa erenlerden olması beklenecek."},{"n":68,"t":"Ne ki dilediğini yaratan ve (elçi) seçen yalnızca senin Rabbindir. Zaten (bu konuda) onların seçim hakkı asla olmamıştır: yüceler yücesi Allah`ın aşkın olan zatı, onların şirk koştukları her şeyin ötesindedir."},{"n":69,"t":"Onların göğüslerinde sakladıklarını da, açığa vurduklarını da en iyi bilen senin Rabbindir."},{"n":70,"t":"O, kendisinden başka tanrı bulunmayan Allah`tır. Dünyada da, âhirette de hamd Ona aittir. Hüküm Onundur; siz de Onun huzuruna döneceksiniz."},{"n":71,"t":"De ki: \"Hiç düşündünüz mü: eğer Allah geceyi üzerinizde Kıyamet Günü`ne kadar baki kılsaydı, Allah`tan başka size ışık getirebilecek ilah kimdi? Hala (bu sese) kulak vermeyecek misiniz?"},{"n":72,"t":"De ki: \"Hiç düşündünüz mü: eğer Allah gündüzü üzerinizde Kıyamet Günü`ne kadar sürekli kılsaydı, Allah`tan başka size bağrında dinlendiğiniz geceyi getirebilecek ilah kimdi? Hala (bu gerçeği) görmeyecek misiniz?"},{"n":73,"t":"Evet O size olan rahmetinin bir ifadesi olarak geceyi ve gündüzü var etti ki, ilkinde bağrında dinleneseniz, diğerinde O`nun lutfundan (payınızı) arayasınız diye: belki böylece şükredersiniz."},{"n":74,"t":"Ve o gün (Allah) onlara seslenecek ve \"Öteden beri Bana ortak olduğunu düşündükleriniz hani, neredeler?\" diye soracak."},{"n":75,"t":"Zaten (o demeye kalmadan) Biz, her ümmetten bir tanık çıkarmış olacağız; ve dönüp \"Haydi, getirin delilinizi!\" diyeceğiz. Sonuçta onlar anlayacaklar ki, gerçek bütünüyle Allah`tan yana ve (çarpık tasavvurlarının) ürettiği sahte ilahlar kendilerini yalnız bırakmış."},{"n":76,"t":"Unutmayın ki, Karun da Musa kavmine mensup biriydi; fakat onların omuzlarında yükselerek haddi aştı; zira Biz kendisine öyle hazineler vermiştik ki, sadece anahtarlarını taşımak bile güçlü kuvvetli bir müfrezeye zor gelirdi. Bir gün kavmi ona dedi ki: \"Şımarma! Çünkü Allah şımaranları sevmez."},{"n":77,"t":"Gel sen Allah`ın sana verdiklerini doğru yolda harcayarak ahiret yurdunun (mutluluğunu) ara, üstelik dünyadan da nasibini unutma! Allah`ın sana iyilikte bulunduğu gibi, sen de (başkalarına) iyilik yap ve sakın ola yeryüzünde haddi aşarak bozgunculuk edeyim deme: çünkü Allah bozguncuları asla sevmez!\""},{"n":78,"t":"(Karun) \"Herkes iyi bilsin ki bu servete ben, kendi bilgim ve becerim sayesinde ulaştım\" dedi. O bilmez miydi ki Allah, kendisinden önceki kuşaklar içerisinden ondan daha güçlü kuvvetli ve maddi birikimi daha fazla olan nicelerini helak etmiştir. Artık, suçu tabiat haline getirenlerin günahlarından sual olunmaz."},{"n":79,"t":"Ve işte bu kişi kavminin karşısına tüm görkem ve gösterişi içinde çıkmıştı. Yalnızca dünya hayatını isteyenler (ona bakıp) \"Ah keşke, ne olurdu Karun`a verilen kadar bize de verilseydi! Şu kesin ki o gerçekten de çok şanslı biriymiş!\" derlerdi."},{"n":80,"t":"Fakat bilgi ve bilginin amacını kavrama yeteneğiyle donatılmış olanlar da; \"Yazıklar olsun size! İman eden ve Allah`ın razı olduğu iş işleyen kimselere Allah`ın verdiği ödül daha hayırlıdır; ama ona sabredenlerden başkası kavuşamaz!\" derlerdi."},{"n":81,"t":"Nihayet (Karun`u) da, onun evini barkını da yerin dibine geçirdik. Artık Allah`tan başka hiç kimse onun yardımına yetişemezdi: (ama ona Allah da yardım etmedi), zira yardımı hak edenlerden değildi."},{"n":82,"t":"Akşam vakti onun yerinde olmak isteyenler ise, sabahladıklarında, `Demek ki,` diyorlardı, `Allah kullarından dilediğinin rızkını genişletir, dilediğininkini de daraltırmış. Allah bize lütfetmeseydi biz de yerin dibine geçecektik. Demek nankörler iflâh olmuyormuş!`"},{"n":83,"t":"İşte orada (bir de) ahiret yurdu var! Biz orayı yeryüzünde büyüklük taslamayan ve fesat çıkarmak istemeyen kimselere tahsis ederiz: zira mutlu son sorumlu davrananların olacaktır."},{"n":84,"t":"Kim huzura iyiliklerle çıkarsa, işte ona getirdiğinden daha hayırlısı vardır. Kim de huzura kötülüklerle çıkarsa, işte kötülük yapan o kimseler sadece yaptıklarının karşılığını görecekler."},{"n":85,"t":"(Ey bu vahyin muhatabı!) Senin hayatına Kur`an`ın kuşatıcı mesajıyla (istikamet) tayin eden (Allah), elbet seni yepyeni bir hayata kavuşturacaktır. (Şu halde) de ki: \"Kimin hidayete erdiğini ve apaçık bir sapıklığa gömülenin de kim olduğunu asıl bilen Rabbimdir.\""},{"n":86,"t":"Ve sen (ey bu vahyin muhatabı); bu ilahi mesajın sana kadar ulaşacağını ümit etmezdin! Sadece Rabbinin rahmeti sayesinde oldu bu: o halde inkar edenlere asla arka çıkma!"},{"n":87,"t":"Ve sana indirilmiş olduğu şu vakitten sonra, onların seni Allah`ın ayetlerinden alıkoymalarına asla izin verme! Aksine (onları) Rabbine çağır! Sakın ha, Allah`a ortak koşanlardan biri olma!"},{"n":88,"t":"Ve asla Allah`la beraber başka bir ilaha yalvarıp yakarma! O`ndan başka ilah yok: her şey yok olacak, sadece O`nun Zatı baki kalacak. Nihai yargı yalnız O`na aittir: sonunda elbet hepiniz O`na döndürüleceksiniz."}],[{"n":1,"t":"Elif-Lam-Mim!"},{"n":2,"t":"İnsanlar yalnızca \"İman ettik\" demekle, sınanıp denenmeden bırakılacaklarını mı sanıyorlar?"},{"n":3,"t":"Doğrusu, onlardan öncekileri de sınamıştık; fakat Allah her halükârda hem doğru söyleyenleri belirleyecek, hem de yalancıları belirleyecek."},{"n":4,"t":"Yoksa o (\"İnandık!\" deyip de) kötülük yapmayı sürdürenler, Bizi atlatabileceklerini mi sandılar? Ne berbat akıl yürütüyorlar."},{"n":5,"t":"Zaten kim Allah`ın huzuruna çıkmayı bekliyorsa, iyi bilsin ki Allah`ın takdir ettiği süre bir gün mutlaka gelip çatacaktır: üstelik O her şeyi bilip işitendir."},{"n":6,"t":"Ve her kim (yaratılış amacını gerçekleştirmek için) var gücüyle çaba gösterirse, o sadece kendisi için çaba göstermiş olur: çünkü Allah, (diğer) tüm varlıklardan farklı olarak, kendi kendine yetendir."},{"n":7,"t":"İman edip iyi amel işleyenlerin elbette kötülüklerini örteriz ve onlara yaptıklarının daha güzeli ile karşılık veririz."},{"n":8,"t":"Ve zaten insanoğluna anne-babasına iyi davranmasını biz tavsiye etmiştik. Fakat (sen ey muhatab), eğer hakkında bir bilgi sahibi olmadığın bir şeyi Bana ortak koşman için seni ikna etmeye çalışırlarsa, asla o ikisine itaat etme: dönüşünüz sadece Banadır; işte o zaman Ben, yapıp ettiklerinizi size bir bir haber vereceğim."},{"n":9,"t":"Ama iman edip Allah`ın razı olduğu iş işleyenlere gelince: onları da mutlaka iyi ve erdemli insanların arasına katacağız."},{"n":10,"t":"Kimi insanlar da vardır ki, \"Allah`a inandık!\" derler, fakat iş Allah (davası) uğrunda eza cefa çekmeye gelince, insanların baskısını Allah`ın cezası gibi algılarlar; Rabbinden bir yardım ulaşınca da, ısrarla \"Zaten biz ta başından beri sizinle beraberdik\" derler."},{"n":11,"t":"Ve Allah her halükarda imanda sebat edenleri de elbet seçip ayıracak, ikiyüzlü olup çıkanları da elbet seçip ayıracaktır."},{"n":12,"t":"Nitekim (O şunu da bilir ki), inkar edenler iman edenlere; \"Siz bizim yaşam biçimimize uyun, günahınız bizim boynumuza olsun\" derler. Oysa ki onlar berikilerin hiçbir günahını yüklenecek değiller; besbelli ki onlar sadece yalancıdırlar."},{"n":13,"t":"Ve elbet onlar kendi yüklerini zaten taşıyacaklar; ama kendi yükleriyle birlikte (sorumlu oldukları) bir başka yük daha taşıyacaklar; ve Kıyamet Günü uyduruk (inançlarından) dolayı elbette hesaba çekilecekler."},{"n":14,"t":"Doğrusu Biz Nuh`u da kendi kavmine elçi göndermiştik: Nuh da onlar arasında -elli yıl eksiğiyle- bin sene kalmıştı; ve onlar iyice zulme gömülüp gitmiş bir haldeyken, tufan onları enseleyivermişti."},{"n":15,"t":"Fakat onu ve gemi yârânının tümünü kurtardık; ve bunu bütün bir insanlığa (ibretlik) bir belge kıldık."},{"n":16,"t":"İbrahim`i de (göndermiştik). Hani o kavmine demişti ki: \"Yalnız Allah`a kulluk edin ve O`na karşı sorumluluğunuzun bilincinde olun; eğer bilirseniz, bu sizin için çok daha hayırlıdır."},{"n":17,"t":"Baksanıza siz, Allah`ı bırakıp da birtakım heykellere tapıyorsunuz ve (onlara) düzme koşma birtakım (nitelikler) yakıştırıyorsunuz. Gerçek şu ki, Allah`tan başka kulluk ettikleriniz size rızık verecek güce sahip değiller; o halde tüm rızkınızı Allah katında arayın ve yalnız O`na kulluk edin; dahası hep O`na şükredin: (zira) O`na döndürüleceksiniz.\""},{"n":18,"t":"\"Ama eğer yalanlarsanız, iyi bilin ki sizden önceki toplumlar da yalanlamışlardı: zaten elçiye düşen de (ilahi mesajı) bütün açıklığıyla iletmekten başkası değildir.\""},{"n":19,"t":"Peki onlar, Allah`ın yaratılışı nasıl yoktan var ettiğini, sonra onu nasıl yenilediğini hiç mi görmezler? Besbelli ki bu Allah`a çok kolaydır."},{"n":20,"t":"De ki: \"Dolaşın yeryüzünü ve görün yaratılışın nasıl başladığını! Daha sonra Allah öteki hayatı da işte böyle var edecektir: çünkü Allah her şeye güç yetirendir."},{"n":21,"t":"Dilediğini cezalandırır, dilediğine rahmet eder: her durumda O`na döndürüleceksiniz."},{"n":22,"t":"Ve O`nu, ne yerde ne de gökte asla atlatamazsınız; dahası, kendiniz için Allah`tan başka ne sadık bir dost ne de bir yardımcı asla bulamazsınız."},{"n":23,"t":"Ama Allah`ın mesajlarını ve O`na kavuşmayı inkar edenler var ya: işte bu gibiler Benim rahmetimden ümidini kesenlerdir; ve işte onları can yakıcı bir azap beklemektedir."},{"n":24,"t":"Öte yandan (İbrahim`e gelince): Kavminin tek cevabı, \"Onu öldürün ya da yakın!\" demekten ibaretti; fakat Allah onu ateşten kurtardı. Şüphesiz inanan bir toplum için, bunda da alınacak bir ders mutlaka vardır."},{"n":25,"t":"Ve (İbrahim) dedi ki: \"Allah`ı bırakıp da birtakım heykeller peydahlamanızın tek nedeni, şu dünya hayatında (onlarla) aranızdaki (çarpık) sevgi bağıdır; daha sonra, Kıyamet Günü`nde birbirinizi lanetleyeceksiniz; en sonunda hepinizin varıp duracağı yer ateştir: size yardım eden biri de asla çıkmayacaktır.\""},{"n":26,"t":"Bunun ardından ona bir tek Lut inandı. Ve (İbrahim) dedi ki: \"Bana, Rabbime doğru yürüyen bir muhacir olmak düşer; çünkü her işinde mükemmel olan, her hükmünde tam isabet kaydeden O`dur.\""},{"n":27,"t":"Biz de ona İshak ve (onun oğlu) Yakub`u verdik; ve onun neslinden gelenler arasında peygamberliği ve vahyi devam ettirdik; üstelik ona ödülünü daha bu dünyada vermeye (başladık); hiç şüphe yok ki o, ahirette de iyiler arasındaki yerini alacaktır."},{"n":28,"t":"Lut`u da göndermiştik. Hani o kavmine demişti ki: \"Şu kesin ki siz, bütün bir dünyada daha önce hiç kimsenin yapmadığı (derece) iğrençlikler yapıyorsunuz."},{"n":29,"t":"Evet, erkeklere (şehvetle) yaklaşan ve (cinsellik için doğal olan) yolu kapatan; üstelik bu çirkinliği kamuya açık yerlerde güpegündüz gurup halinde işleyen siz değil misiniz? Fakat kavminin tek cevabı: \"Eğer doğru sözlü biriysen, haydi Allah`ın azabını getir de görelim bakalım!\" diye (meydan okumaktan) ibaretti."},{"n":30,"t":"\"Rabbim!\" dedi (Lut): \"Ahlaki çürümeye yol açan şu topluma karşı bana yardım et!\""},{"n":31,"t":"Ve elçilerimiz İbrahim`e (oğlu İshak`ı) müjdelemek için geldiklerinde: \"Bakın\" demişlerdi, \"biz, işte şu bölgelerin halkının helakı (için görevlendirildik); çünkü oraların halkı hadlerini çoktan aşmış bulunuyorlar."},{"n":32,"t":"(İbrahim): \"Peki ama\" dedi, \"Lut da onların içinde yaşıyor!\" (Elçiler): \"Biz\" dediler, \"onların arasında kimlerin yaşadığını çok iyi biliyoruz; sonuçta onu ve (iman) ailesini mutlaka kurtaracağız; ne ki onun karısı hariç: zaten o kadın, döküntülerden biri olmalıydı.\""},{"n":33,"t":"Ve elçilerimiz Lut`a gelir gelmez, o derin bir hüzne kapıldı ve onlar adına hiç bir şey yapamayıp eli kolu döküldü kaldı. Ama onlar dediler ki: \"Korkma ve üzülme! Çünkü biz seni ve yakınlarını elbette kurtaracağız; ancak karın hariç: zaten onun geride kalanlardan biri olacağı malum."},{"n":34,"t":"İşte bu yüzden biz şu bölge halkına, işleye geldikleri fısku fücur yüzünden gökten yakıcı bir bela indireceğiz.\""},{"n":35,"t":"Doğrusu Biz ondan geriye, akleden bir topluluk için hakikatin apaçık belgeleri olan işaretler bırakmışızdır."},{"n":36,"t":"Medyen`e de, soydaşları Şuayb`i (göndermiştik); ve o \"Ey kavmim!\" demişti, \"Allah`a kulluk edin ki Ahiret Günü`ne umutla bakabilesiniz; dahası, kötülüğü yaygınlaştırarak yeryüzünde ahlaki çürümeye meydan vermeyin!\""},{"n":37,"t":"Ne var ki onu yalanladılar; derken şiddetli bir sarsıntı onları ansızın yakalayıverdi ve kendi yurtlarında cansız donakaldılar."},{"n":38,"t":"Onlara ait mesken kalıntılarının da ayan açık önünüze koyduğu gibi, Ad ve Semut da (benzer bir akıbete uğradı); zira Şeytan onlara işledikleri (kötülükleri) süslü göstermişti: sonunda onlar, üstelik açıkgöz ve uyanık (geçinen) kimseler oldukları halde yoldan saptılar."},{"n":39,"t":"Karun, Firavun ve Haman da (benzer bir akıbete uğradı). Doğrusu Musa, onlara hakikatin apaçık delilleriyle gelmişti; fakat onlar ülkede büyüklük tasladılar: ne ki hiç biri de asla (Bizi) aşamadılar."},{"n":40,"t":"Sonuçta her birini günahlarından dolayı enseledik: Ve onlardan kimileri üzerinde (bela) fırtınası estirdik, kimisini de sarsıcı bir azap çığlığı yakaladı; yine onlardan bazı kimseleri yerin dibine geçirdik, bazılarını da boğulmaya terk ettik: Ne var ki onlara zulmeden asla Allah değildi; ve fakat onlar asıl kendi kendilerine zulmetmişlerdi."},{"n":41,"t":"Allah`tan başkalarını sığınacak otorite edinen kimselerin durumu, ördüğü ağı ev edinen dişi örümceğin durumuna benzer; ne ki evlerin en çürüğü, elbette örümcek ağıdır: keşke bunu kavrayabilselerdi."},{"n":42,"t":"Şüphesiz Allah, onların kendisinden başka yalvarıp yakardıkları her şeyi çok iyi bilir; zira yüceler yücesi O`dur, her hükmünde tam isabet sahibi O`dur."},{"n":43,"t":"İşte bütün bu misalleri Biz insanlar için veriyoruz; ne ki bunları sadece (eşyanın var ediliş amacını) bilenler kavrayabilir."},{"n":44,"t":"(zira) Allah, gökleri ve yeri mutlak gerçeğe atıf olsun diye (amaçlı olarak) yaratmıştır: hiç şüphe yok ki bunda, mü`minlerin alacağı bir ders mutlaka vardır."},{"n":45,"t":"(Ey bu hitabın muhatabı!) Sana vahyedilmiş olan bu mesajı izle ve (başkalarına) ilet; ve namazı hakkını vererek kıl: çünkü (hakkı verilerek kılınmış) namaz, (insanı) belli başlı her tür çirkinlik ve kötülükten alıkoyar; ve hele Allah`ı anmak ve Allah`ın sizi anması elbette en büyük (boyutudur)! Zira Allah, işlediğiniz her şeyi bilir."},{"n":46,"t":"Önceki vahiylerin mensuplarıyla tartışırken, haksızlık etmedikleri sürece en güzel yol ve yöntemden başkasına itibar etmeyin ve deyin ki: \"Biz bize indirilene de, size indirilene de inanmışız; bizim de, sizin de ilahınız bir ve tektir; ne ki biz kayıtsız şartsız sadece O`na teslim olmuşuz.\""},{"n":47,"t":"(Ey Peygamber!) İşte bu kitabı sana böyle (bir mesajla) indirdik; bu yüzdendir ki bu kitabı kendilerine verdiklerimiz ona iman ederler; işte şu (önceki vahyin mensupları) arasında da inanan kimseler olacaktır: zaten nankörler dışında hiç kimse ayetlerimizi bile bile inkar etmezler."},{"n":48,"t":"Hem sen bu (Kur`an)dan önce herhangi bir (kutsal) kitabı okumuş değildin; dahası onu kendi elinle yazıyor da değilsin. Eğer böyle olsaydı insanları kuşkuya düşürürlerdi, gerçeği geçersiz kılmaya yeltenenler."},{"n":49,"t":"Aksine o (Kitab), sahibine seçip ayırma yeteneği kazandıran bir bilgi tasavvuru bahşedilenlerin gönüllerinde yer bulan hakikatin apaçık belgelerinden oluşmuştur: zaten bilinci altüst olmuş kimselerden başkası ayetlerimizi bile bile inkara yeltenmez."},{"n":50,"t":"Bir de kalkıp, \"Rabbinden ona mucizevi bir belge indirilmesi gerekmez miydi?\" dediler. De ki: \"Tüm mucizevi belgeler Allah katındadır; ben ise yalnızca açık ve net bir uyarıcıyım.\""},{"n":51,"t":"Ne yani! Şimdi bu ilahi kelamı, kendilerine iletmen için sana indirmiş olmamız onlara yetmedi mi? Elbet bunda, inanacak bir toplum için tarifsiz bir rahmet ve ilahi bir uyarı zaten vardır."},{"n":52,"t":"(Onlara) de ki: \"Sizinle benim aramda şahit olarak Allah yeter; O göklerde ve yerde olan her şeyi bilir; yine (bilir) ki: Batıl inançlara saplanan ve Allah`a nankörlük eden kimseler hüsrana uğrayacak olanların ta kendisidirler.\""},{"n":53,"t":"Ve onlar, sana (meydan okuyarak) azabı çabuklaştırmanı istiyorlar; eğer belirlenmiş (yasaya uygun) bir süreci olmamış olsaydı, azap onların başına derhal gelirdi: yine de o, onlar hiç farkında değilken ansızın mutlaka çıkagelecek."},{"n":54,"t":"Onlar sana (meydan okuyarak) azabı çabuklaştırmanı istiyorlar; ama iyi bilsinler ki cehennem, inkara saplananları elbette çepeçevre kuşatacak;"},{"n":55,"t":"o gün azab onları (başlarının) üzerinden ve ayaklarının altından sarıp sarmalayacak; ve (Allah) onlara \"Öteden beri yapa geldiklerinizin (sonuçlarını) tadın!\" diyecek."},{"n":56,"t":"Siz ey iman eden kullarım! Şüphesiz ki Benim arzım geniştir; o halde Bana, yalnız Bana kulluk edin!"},{"n":57,"t":"Her can ölümü tadıcıdır; en sonunda Bize dönüp geleceksiniz."},{"n":58,"t":"İman eden ve o imana yaraşır eylemler ortaya koyanları, içinde sürekli kalmak üzere cennetin zemininden ırmaklar çağlayan yüce köşklerine yerleştireceğiz: (iyi) davranışta bulunanların ödülü pek güzeldir!"},{"n":59,"t":"Onlar ki, sıkıntılara karşı göğüs gerdiler ve hep Rablerine güvendiler!"},{"n":60,"t":"Nice canlılar vardır ki, rızkının sorumluluğunu yüklenmez; onların rızkını da sizinkini de yalnızca Allah verir: Zira her şeyi işiten ve bilen sadece O`dur."},{"n":61,"t":"Ve eğer dönüp de onlara sorsan: \"Gökleri ve yeri yaratan kimdir; ve güneşle ayı emre amade kılan kimdir?\" diye, hiç kuşkun olmasın ki \"Elbette Allah`tır!\" diyecekler. O halde, nasıl böyle savruluyorlar?"},{"n":62,"t":"Allah kullarından tercih edenin/tercih ettiğinin rızkını genişletir, ya da onu kulu lehine sınırlandırır: çünkü Allah her bir şeyi bilendir."},{"n":63,"t":"Ve eğer dönüp onlara sorsan: \"Gökten suyu indiren ve onunla ölü toprağa can veren kimdir?\" diye, hiç şüphen olmasın ki \"Elbette Allah!\" diyecekler. De ki: \"Hele şükür, (bari şunu olsun bileydiniz)!\" Ama ne gezer... Onların çoğu akıllarını kullanmayı dahi beceremezler."},{"n":64,"t":"Zaten (akletselerdi, bileceklerdi ki) şu dünya hayatı (tek başına) geçici bir oyun ve oynaştan başka bir şey değildir; bir de hayatın öteki yüzü vardır ki, işte odur capcanlı gerçek hayat: keşke bunu olsun bilebilseydiler."},{"n":65,"t":"Fakat gemiye binip de (tehlike hissettikleri) zaman, inancı batıldan arındırıp dini yalnız O`na has kılarak başlarlar Allah`a yalvarıp yakarmaya; ne ki O kendilerini sağ salim karaya çıkarır çıkarmaz, aynı kimseler başlarlar O`na ortak koşmaya."},{"n":66,"t":"Sonuçta kendilerine verdiklerimize nankörlük etmiş ve kısa vadeli bir hazzı tüketmiş olurlar: Fakat zamanı gelince (gerçeği) anlayacaklar."},{"n":67,"t":"Peki, görmezler mi ki kendilerinin etrafındaki insanlar her tür saldırıya açık olmanın tedirginliğini yaşarken, Biz onlara güvenli bir dokunulmazlık sağladık: hâlâ mı bâtıl inançlara saplanıp Allah’ın (din ve vahiy) nimetine nankörlük edecekler?"},{"n":68,"t":"Kendi uydurduğu yalanları Allah`a yakıştıran, ya da önüne gelen hakikati yalanlayandan daha zalim biri olabilir mi? Hiç zulümde direnenler için cehennemde yer bulunmaz mı?"},{"n":69,"t":"Ama davamız uğrunda var gücünü harcayanları, elbette kendi yollarımıza yönelteceğiz: ve şüphesiz Allah iyi ve erdemli olanların yanındadır."}],[{"n":1,"t":"Elif-Lam-Mim!"},{"n":2,"t":"Rumlar yenilgiye uğradılar,"},{"n":3,"t":"(üstelik) en yakın yerde; ama onlar, bu yenilgilerinin ardından yeniden galip gelecekler;"},{"n":4,"t":"(hem de) bir kaç yıl içerisinde -(tabi ki) mutlak karar, önünde sonunda Allah`a aittir-: (Şimdi müşriklerin sevindiği gibi) o gün de mü`minler sevinecekler;"},{"n":5,"t":"Allah`ın yardımı sayesinde... O dilediğine yardım eder: zira O her işinde mükemmel olan, sonsuz merhamet sahibidir."},{"n":6,"t":"(Bu) Allah`ın kesin vaadidir. Allah vaadinden dönmez; ne var ki insanların çoğu (bunu) bilmezler:"},{"n":7,"t":"onlar sadece bu dünya hayatının görünür yüzünü tanırlar, ama onlar (görünmeyen) öteki hayattan gafildirler."},{"n":8,"t":"Şimdi onlar kendi iç dünyalarında hiç muhasebe yapmazlar mı? Allah gökleri, yeri ve bu ikisi arasındakileri asla bir amaç ve anlamdan, dahası sınırlı bir ömürden yoksun olarak yaratmamıştır. Ne var ki insanlardan bir çoğu Rablerine kavuşacaklarını inatla inkar etmektedirler."},{"n":9,"t":"Onlar yeryüzünde dolaşmıyorlar mı? Artık kendilerinden öncekilerin nasıl bir akıbete uğradıklarını görselerdi bari: Onlar kendilerinden daha güçlüydü ve yeryüzünde daha derin izler bırakmışlardı; dahası onlar orayı, berikilerden çok daha fazla mamur ve müreffeh hale getirmişlerdi; üstelik, onlara da elçileri hakikatin apaçık belgeleriyle gelmişti: neticede onlara zulmeden Allah değildi, ama asıl onlar kendi kendilerine zulmettiler."},{"n":10,"t":"Nihayet böylelerinin akıbeti, Allah`ın ayetlerini yalanlamaları ve onları alaya almaları nedeniyle beterin de beteri oldu."},{"n":11,"t":"Allah insan neslini yoktan var ettiği gibi, sonra bu (yaratışı) tekrarlayacaktır: en sonunda hepiniz O`na döndürüleceksiniz."},{"n":12,"t":"Ve Son Saat`ın gelip çattığı gün, suçlular tüm umutlarını yitirecekler:"},{"n":13,"t":"zira ortak koştukları varlıkların hiç birinden bir şefaat göremeyecekler; oysa ki onlar ortak koştukları varlıklar yüzünden kafir olmuşlardı."},{"n":14,"t":"Ve Son Saat`in gelip çattığı gün, safların ayrılacağı bir gün olacaktır:"},{"n":15,"t":"Artık, iman eden ve imana uygun iyi işler işleyen kimseler tarifsiz bir mutluluk bahçesinde, ruha safa veren bir musiki ile mest olacaklar;"},{"n":16,"t":"ama inkar eden, ayetlerimizi ve ahiret buluşmasını yalanlayan kimselere gelince: işte böyleleri de azabın içerisinde (yaptıklarıyla) yüzleşecekler."},{"n":17,"t":"Öyleyse akşamladığınızda ve sabah kalktığınızda, Allah`ın sınırsız şanını yüceltin."},{"n":18,"t":"Göklerde ve yerde her tür sena ve övgüye layık tek varlık O olduğuna göre, öğleyin ve akşama girerken de (O`nu anın)."},{"n":19,"t":"O ölüden diriyi meydana getirir, diriden de ölüyü meydana getirir; ve ölü toprağa can verir: işte siz de böyle çıkarılacaksınız."},{"n":20,"t":"Sizi toprak türünden yaratması, O`nun mucizevi işaretlerinden biridir; sonra siz (bir süreç içinde) beşer olarak gelişip kişilik kazandınız."},{"n":21,"t":"Yine sizin için kendileriyle huzur bulasınız diye kendi türünüzden eşler yaratması, aranıza sevgi ve merhameti yerleştirmesi de O`nun mucizevi işaretlerinden biridir: Şüphesiz bütün bunlarda düşünen bir topluluk için alınacak bir ders mutlaka vardır."},{"n":22,"t":"Yine gökleri ve yeri yaratması, dillerinizin ve renklerinizin farklılığı da O`nun mucizevi işaretlerinden biridir: Şüphesiz bunda (farklılığın değerini) bilenler için mutlaka alınacak dersler vardır."},{"n":23,"t":"Yine geceleyin ve gündüzün uyuyabilmeniz ve O`nun lutfundan (payınıza düşeni) arayabilmeniz de O`nun mucizevi işaretlerinden biridir: Şüphesiz bunda da (varlığın) sesine kulak veren herkesin alacağı bir ders mutlaka vardır."},{"n":24,"t":"Sizlere korkuyla ümidi bir arada yaşatmak için çakan şimşeği de göstermesi de, gökten bir su indirip onunla ölü toprağa hayat vermesi de O`nun mucizevi işaretlerinden biridir: Şüphesiz bunda da akleden bir topluluk için alınacak bir ders mutlaka vardır."},{"n":25,"t":"Göğün ve yerin O`nun yasası sayesinde ayakta durması da O`nun mucizevi ayetlerinden biridir. En sonunda O size yerden (kalkmanız için) bir kez seslenecek; bunun üzerine siz de hemen ortaya çıkıvereceksiniz."},{"n":26,"t":"Göklerde ve yerde bulunan her varlık O`na aittir; hepsi de O`na itirazsız boyun eğmişlerdir."},{"n":27,"t":"Ve sadece O`dur her şeyi yoktan var eden, sonra bu (yaratışı) tekrarlayacak olan: Bu O`nun için çok kolaydır; zira göklerde ve yerdeki en güzel örnekler O`na aittir: mutlak üstünlük ve mutlak hikmet sahibi de yalnızca O`dur."},{"n":28,"t":"O size kendinizden bir örnek verir: Otoriteniz altında bulunan kimseleri, size verdiğimiz servet üzerinde (söz sahibi) ortaklar olarak görüp onlarla (otoritenizi) eşit olarak paylaşır; size denk (statüde) olanlardan çekindiğiniz gibi onlardan da çekinir misiniz? İşte Biz, akleden bir topluluğa ayetlerimizi böyle açıklarız."},{"n":29,"t":"Hayır, (kendilerine) zulmeden kimseler bilgisiz ve bilinçsizce kendi arzu ve tutkularının peşine takılırlar. Artık Allah`ın (bu şekilde) saptırdıklarını kim doğru yola yöneltebilir ki? Üstelik onlar, herhangi bir yardıma mazhar da olamazlar."},{"n":30,"t":"İMDİ sen, varlığını her tür sapmadan uzaklaşarak tümüyle doğru ve asıl dine, Allah’ın insanlığın özüne yaratılıştan nakşettiği fıtrata çevir; (ta ki) Allah’ın yarattığında olumsuz bir değişme olmasın: işte, değerlere dayalı gerçek Din’in (amacı) budur ve fakat insanların çoğu bilmezler."},{"n":31,"t":"(Batılın her türünden yüz çevirip) yalnız O`na yönelin ve O`na karşı sorumluluğunuzun bilincinde olun; ibadet ve duanızın istikametini doğrultun; ve asla O`ndan başkasına ilahlık atfedenlerden olmayın!"},{"n":32,"t":"(Bir de) şunlardan olmayın ki, onlar dinlerini paramparça ettiler de (birbirine karşıt) taraftarlar haline geldiler; (artık) her hizip kendi elindekiyle övünmekte."},{"n":33,"t":"Ne zaman insanlara bir zarar ilişse, (hemen) Rablerine yönelerek O`na yalvarıp yakarırlar; fakat ardından O`nun katından kendilerine bir rahmet tattırılınca, hiç değilse bir kısmı başlarlar Rablerine şirk koşmaya;"},{"n":34,"t":"sonuçta kendilerine verdiğimiz nimetlere nankörlük etmiş olurlar. Haydi bakalım, siz de bir miktar safa sürün; nasıl olsa zamanı gelince (gerçeği) öğreneceksiniz!"},{"n":35,"t":"Yoksa Biz onlara bunu söyleyen bir buyruk indirdik de, bu nedenle mi O`na şirk koşmakta ısrar ediyorlar?"},{"n":36,"t":"Evet, ne zaman insanlara bir rahmet tattıracak olsak onunla sevince gark olurlar; ama elleriyle işledikleri yüzünden başlarına bir kötülük gelse, o zaman da hemen umutsuzluğa kapılıverirler."},{"n":37,"t":"Şimdi onlar, Allah`ın dilediğine rızkı açtıkça açtığını, dilediğine de sınırlandırdığını görmüyorlar mı? Kuşkusuz bunda iman eden bir toplum için mutlaka alınacak bir ders vardır."},{"n":38,"t":"Şu halde yakınlara, yoksullara ve yolda kalmışlara haklarını verin; bu Allah`ın rızasını dileyenler için daha hayırlıdır; zira onlar, mutluluğa erecek olanların ta kendileridir."},{"n":39,"t":"Yine (iyi bilin ki), başka insanların mal varlığı sayesinde artsın diye faiz karşılığı verdikleriniz asla Allah katında size artış sağlamaz. Bir de Allah`ın rızasını dileyerek verdiğiniz arındırıcı mali yükümlülükler var. İşte böyle yapanlar, ödüllerini kat kat artıranların ta kendileridir."},{"n":40,"t":"Allah sizi yaratmış, sonra size rızık vermiştir; daha sonra sizi ölüme sürükleyecek ve en sonunda yeniden diriltecektir. İmdi, ortak koştuklarınız arasında bütün bunlardan herhangi birini yapacak kimse var mı? O yüceler yücesi, onların şirk koştukları her şeyin ötesinde aşkın bir varlıktır."},{"n":41,"t":"İnsanların elleriyle yaptıkları yüzünden karada ve denizde bozulma meydana geldi. Neticede (Allah), yaptıklarının (kötü sonuçlarından) bir kısmını kendilerine tattıracaktır; umulur ki (yol yakınken) dönerler."},{"n":42,"t":"De ki: \"Dolaşın yeryüzünü! Bu sayede daha önce yaşamış (günahkarların) akıbeti nasılmış görün! Zaten onların çoğu, Allah`tan başkasına ilahi vasıflar yakıştırmışlardı.\""},{"n":43,"t":"Haydi, Allah tarafından (takdir edilmiş) geri çevrilmesi imkansız gün gelmezden önce yüzünü doğru ve asıl dine çevir! İşte o gün herkes hak ettiği yere yerleşir."},{"n":44,"t":"Küfreden kişi küfrünün sorumluluğunu sırtlanır; imanıyla uyumlu ıslah edici eylemlerde bulunan ise kendi yararına iyi bir hazırlık yapmış olur;"},{"n":45,"t":"sonuçta (Allah), iman edenleri ve o imanla uyumlu ıslah edici eylemlerde bulunanları kendi lütfuyla ödüllendirmiş olur: Kuşku yok ki Allah inkar edenleri asla sevmez."},{"n":46,"t":"Nitekim (yağmurun) müjdecisi olarak (önden) rüzgarları göndermesi O`nun (kudretinin) delillerindendir; bu sayede size rahmetini tattırmakta, gemileri yasası sayesinde yüzdürmekte, yine bu sayede O`nun lütfu kereminden pay almaktasınız: umulur ki şükrünü eda edersiniz."},{"n":47,"t":"Doğrusu senden önce de kendi kavimlerine elçiler göndermiştik; ve onlara hakikatin apaçık delilleriyle gelmiştiler. En sonunda suç ve günahta direnen kimselere yaptıklarının acısını tattırdık: zaten inananlara yardım etmek üstlendiğimiz bir görevdi."},{"n":48,"t":"Allah O`dur ki, rüzgarları elçi (gibi) göndererek bulutları tetikler; artık onları semada nasıl isterse öyle yayacak, dahası parça parça edecektir. Derken sen (ey insan), bulutların bağrından yağmurun boşaldığını görürsün: bir de onu kullarından dilediği kimselerin üzerine yağdırmaya görsün; işte o an değme onların sevincine!"},{"n":49,"t":"Ama aynı kimseler az önce, yani (yağmur) indirilmeden önce umutlarını büsbütün yitirmiştiler."},{"n":50,"t":"Haydi (ey insan)! Dön de bir bak Allah`ın rahmetinin sonuçlarına: ölü toprağa nasıl da can veriyor! İşte bunu yapan ölüleri diriltenin ta kendisidir: zira O`nun güç ve kudreti her şeye yeter."},{"n":51,"t":"Ama Biz eğer bir sam yeli göndersek ve bu yüzden ekinlerinin sararıp solduğunu görseler, bunun ardından derhal inkarda ayak diremeye başlarlar."},{"n":52,"t":"Şu da bir gerçek ki sen asla ölülere duyuramazsın; arkasını dönüp uzaklaşırken her tür davete sağır kesilenlere de duyuramazsın."},{"n":53,"t":"Yine sen (kalbi) kör olanları sapıklıktan çevirip de doğru yola yöneltemezsin. Sen ancak ayetlerimize iman eden kimselere duyurabilirsin ve onlar da hemen teslim oluverirler."},{"n":54,"t":"Allah`tır başlangıçta sizi güçten yoksun yaratan, bu yoksunluğun ardından sizi güçlü kuvvetli kılan, bu güçlü kuvvetli dönemin ardından sizi (tekrar) zayıflığa ve ak saçlılığa mahkum eden: O dilediğini yaratır; zira O her şeyi bilendir, mutlak kudret sahibidir."},{"n":55,"t":"Ve Son Saat gelip çattığı gün suça batmış olanlar, dünyada bir saatten fazla kalmadıklarına yemin edecekler; böylece kendilerine (dahi) yalan söylemiş olacaklar."},{"n":56,"t":"(Hayattayken) bilgi ve imanla donatılanlarsa: \"Doğrusu siz, Allah`ın kitabı hususunda diriliş gününe kadar yerinizde sayıp direttiniz; işte artık diriliş günü de gelip çattı, fakat siz bunu bilmezden gelmiştiniz!\" diyecekler."},{"n":57,"t":"Ne ki o gün, zulme gömülüp gitmiş olanlara ne getirecekleri mazeret fayda verecek, ne de suçlarını itiraf ile af dilemeleri..."},{"n":58,"t":"Doğrusu Biz bu Kur`an`da, insanlara (hakikati) her türlü dolaylı anlatım tarzını kullanarak açıkladık. Ama onlara (bu türden mesel içeren) bir ayetle gelsen, inkarda direnenler yine de: \"Siz sadece batılın peşine düşen kişilersiniz\" derler."},{"n":59,"t":"Allah (hakikatin) bilgisine sırt çevirenlerin kalplerini işte böyle mühürler."},{"n":60,"t":"Artık sabret; unutma ki Allah`ın vaadi mutlaka gerçekleşecektir. (Kendi söylediklerine dahi) yürekten inanmayanlar, tahrikleriyle sakın seni fevri ve tepkisel bir davranışa sürüklemesinler."}],[{"n":1,"t":"Elif-Lam-Mim!"},{"n":2,"t":"İşte bunlar, her hükmünde tam isabet kaydeden ilahi kelamın ayetleridir;"},{"n":3,"t":"Allah`ı görür gibi hareket edenler için bir rehber ve bir rahmet olan (ayetleri);"},{"n":4,"t":"onlar ki namazı hakkını vererek eda ederler, arınıp yücelmek için ödenmesi gereken bedeli öderler; zira onlar ahirete inananların ta kendisidirler."},{"n":5,"t":"İşte onlar, Rablerinden gelen kusursuz bir rehberliğe tabidirler; ve işte onlar, evet onlardır ebedi mutluluğa erenler."},{"n":6,"t":"Ama insanlardan öyleleri vardır ki, (başkalarını) Allah yolundan bilgisizce saptırmak ve onu gülünç duruma düşürmek için (ilâhî mesajlar üzerinde) hadis oyunu oynamaya kalkışırlar: işte onlar onur kırıcı bir terk edilmişliğe mahkûm olacaklar."},{"n":7,"t":"Böyle birine ayetlerimiz okunduğu zaman sanki kulaklarında kurşun varmış gibi hiç aldırmadan serkeşçe yüz çevirir: İşte böylesini can yakıcı bir azap ile müjdele."},{"n":8,"t":"Bir de iman eden ve imanına uygun eylemler ortaya koyan kimseler var ki, her tür nimetle dolu olan cennetler onların olacak:"},{"n":9,"t":"Onlar orada Allah`ın mutlaka gerçekleşecek olan vaadi uyarınca ebedi kalacak. Zira O her işinde mükemmel olandır, her hükmünde tam isabet edendir."},{"n":10,"t":"O gökleri, gördüğünüz bir direk olmaksızın yarattı ve O sizi sarsmasın diye yeryüzüne kalkmaz kımıldamaz dağlar yerleştirdi ve orada her çeşit canlı varlığın üremesini sağladı. İşte Biz, gökten yağmuru (böyle) indiririz, akabinde orada her tür ve cinsten yararlı varlığı (böyle) yetiştiririz."},{"n":11,"t":"Bu Allah`ın yaratışıdır: Haydi, gösterin bakayım O`nun dışındakiler neyi yaratmışlar? Hayır, zulme gömülüp gitmiş olanlar apaçık bir sapıklık içindedirler."},{"n":12,"t":"Doğrusu Biz Lokman`a da (şu) hikmeti bahşetmiştik: \"Allah`a şükret! Çünkü (O`na) şükreden kendi lehine şükretmiş olur. Fakat kim de nankörlük ederse, iyi bilsin ki Allah kendi kendine yeterli olandır, her tür övgüye layık olandır."},{"n":13,"t":"Hani Lokman oğluna öğüt verirken şöyle diyordu: \"Yavrucuğum! Allah`tan başkasına ilahlık yakıştırma! Çünkü her tür ilahlık yakıştırma gerçekten de korkunç bir zulümdür."},{"n":14,"t":"Nitekim (Allah şöyle buyurur): \"Biz insana anne babasına (iyi) davranmasını emrettik. Annesi onu ağır acılara katlanarak karnında taşıdı ve onun sütten kesilmesi iki yılda gerçekleşti: şu halde (ey insan), Bana ve anne babana şükret; (ama sonunda) dönüş yalnızca Banadır!\""},{"n":15,"t":"Yine (Allah): \"Eğer hakkında bilgi sahibi olmadığın bir şeyi Bana ortak koşman için seni zorlarlarsa, asla onlara itaat etme! Yine de onlara şu (geçici) dünyada iyi davran ve yönünü Bana dönenlerin yolunu izle! En sonunda elbet Bana döneceksiniz ve yapıp ettiğiniz her şeyin (gerçeğini) size bir bir göstereceğim\" (diye buyurur)."},{"n":16,"t":"(Lokman): \"Yavrucuğum! (Yapıp ettiğiniz) o şeyler isterse bir hardal tanesi kadar olsun, ister bir kayanın bağrında, ister göklerin derinliklerinde, isterse yerin altında saklı bulunsun; Allah onu bulup ortaya çıkarır: çünkü Allah (ilmiyle) her şeye nüfuz eder, her şeyden haberdardır."},{"n":17,"t":"\"Yavrucuğum! Allah`a kulluğunu hakkıyla yerine getir, her zaman iyi ve doğru olanı önerip kötü ve yanlış olandan sakındır; başına gelenlere göğüs ger! Şüphesiz bütün bunlar kararlılık ve direnç isteyen işlerdendir.\""},{"n":18,"t":"\"Kasıntılık yapıp insanlara karşı böbürlenme ve yeryüzünde çalım satarak dolaşma! Zira unutma ki Allah kendini beğenmiş kibirliyi sevmez."},{"n":19,"t":"(Hayat) yürüyüşünde dengeli ol ve sesini yükseltme! Unutma ki seslerin en çirkini eşeğin sesidir.\""},{"n":20,"t":"İşte (ey insanlar), görmez misiniz ki Allah göklerde ve yerde bulunan her şeyi emrinize amade kılmıştır; açıktan ve gizli olarak size nimetlerini bol bol ihsan etmiştir? Ne ki yine de insanlar içerisinden herhangi bir bilgiye, yol gösterici bir kılavuza ve aydınlatıcı bir kitaba dayanmaksızın Allah hakkında tartışan kimseler çıkabilmektedir."},{"n":21,"t":"İşte böylelerine \"Allah`ın indirdiklerine uyun!\" denildiğinde: Asla, biz sadece babalarımızın hayat tarzına uyarız!\" derler. Ne yani, Şeytan onları çılgın bir ateşin azabına çağırmış olsa da mı (bunda ısrar edecekler)?"},{"n":22,"t":"Ama kim de bütün varlığıyla görürcesine inandığı Allah`a teslim olursa, işte o kopmaz bir halkaya sımsıkı yapışmış olur: en nihayet her iş döner dolaşır, sonucunu takdir etmesi için Allah`a varır."},{"n":23,"t":"Kim de inkara saparsa, artık onun inkarına üzülmen gerekmez. (Nasıl olsa) sonunda Bize dönecekler; ve Biz yaptıklarını(n iç yüzünü) bir bir kendilerine haber vereceğiz: çünkü Allah gönüllerdeki en mahrem sırları bilendir."},{"n":24,"t":"Tadımlık bir hazzı kısa vadede tüketmelerini sağlarız; ardından onları altında ezilecekleri ağır bir azaba mahkum ederiz."},{"n":25,"t":"Eğer onlara kalkıp da sorsan \"Gökleri ve yeri yaratan kimdir?\" diye, hiç tereddütsüz \"Allah`tır\" derler. Sen de \"Hamd Allah`a mahsustur\" de! Ne var ki onların çoğu bunu dahi kavramaktan acizdirler."},{"n":26,"t":"Göklerde ve yerde olan her şey Allah`a aittir; şüphesiz Allah var ya: işte O`dur kendi kendine yeterli olan, her tür övgüye layık olan."},{"n":27,"t":"Ve eğer dünyanın tüm ağaçları kalem olsa denizleri de mürekkep, buna yedi deniz daha eklense, Allah`ın kelimeleri yine de tükenmez: çünkü Allah`tır her işinde mükemmel olan, her hükmünde tam isabet kaydeden."},{"n":28,"t":"Hepinizin yaratılması ve tekrar diriltilmesi, (O`nun için) bir tek can(ın yaratılması ve diriltilmesi) gibidir: Kuşkusuz Allah her şeyi işitir, her şeyi tarifsiz bilir."},{"n":29,"t":"Fark etmez misin ki (ey insan): Allah geceyi uzatıp gündüzü kısaltıyor ve gündüzü uzatıp geceyi kısaltıyor; O güneşi ve ayı bir yasaya tabi kıldı da, her biri sonu yasayla belirlenmiş bir süre doluncaya kadar hareketini sürdürüyor? Yine (bilmez misiniz) ki Allah, yaptığınız her şeyden haberdardır?"},{"n":30,"t":"İşte bu yüzdendir ki Allah mutlaka hakikatin ta kendisidir ve onların O`nun dışında yalvarıp yakardığı her şey bütünüyle batıldır: evet o Allah ki yüce olan O`dur, ulu olan O`dur."},{"n":31,"t":"Görmez misiniz ki (ey insanlar), O`nun (müdahalesinin) delillerini size göstermek için gemiler denizde Allah`ın nimeti sayesinde yol alıyorlar? Elbet bütün bunlarda, derin bir şükran duygusuyla (O`na) kullukta direnenler için mesajlar vardır."},{"n":32,"t":"Derken, dalgalar onları zifiri gölgeler gibi kuşattığında, yalnız O`na yönelerek başlarlar Allah`a yalvarıp yakarmaya; fakat onları sağ salim karaya çıkarır çıkarmaz, onlardan kimileri ortada kalarak (inanmakla inanmamak arasında) bocalar durur: zaten ayetlerimizi, habis kafirlerden başkası bile bile inkar etmez."},{"n":33,"t":"Ey İnsanlık! Rabbinize karşı sorumluluğunuzu hatırlayın! Dahası ne anne babanın çocuğuna, ne de çocuğun anne babasına hiçbir fayda sağlamayacağı bir günün dehşetinden sakının! Unutmayın ki Allah`ın vaadi gerçekleşecektir: şu halde bu dünya hayatı sizi asla ayartmasın; dahası, aldatıcının hiçbir türü sizi Allah (hakkındaki asılsız düşünceler) ile aldatmasın."},{"n":34,"t":"Şu da bir gerçektir ki, Son Saat`in bilgisi sadece Allah katındadır: yağmuru yağdıran O`dur; rahimlerde yer tutanı O bilir; oysa ki hiç kimse yarın ne kazanacağını bilmez. Dahası hiç kimse yarın hangi mekanda öleceğini bilemez. Şüphesiz Allah`tır her şeyi bilen, her şeydan haberdar olan."}],[{"n":1,"t":"Elif-Lam-Mim!"},{"n":2,"t":"Bu ilahi kelamın indirilişi, hiç kuşku yok ki alemlerin Rabbindendir."},{"n":3,"t":"Yine de onlar \"Onu o uydurdu\" diyorlar. Hayır! O Senin Rabbinden gelen bir hakikattir; senden önce kendilerine uyarıcı gelmemiş bir toplumu belki doğru yola gelirler diye uyarman içindir."},{"n":4,"t":"Gökleri, yeri ve bu ikisi arasındakileri altı aşamada yaratan, sonra da hükümranlık makamına kurulan Allah`tır; (hesap günü) sizi O`ndan koruyacak ne bir dost ne de bir kayırıcı bulamazsınız: peki, hala ders almayacak mısınız?"},{"n":5,"t":"Gökten yere kadar bütün bir oluşu O düzenler; en sonunda bütün bir oluş sizin hesabınıza göre bin yıl kadar süren bir günde O`na yükselir."},{"n":6,"t":"İşte idraki aşan hakiketleri de, idrak ve tecrübe edilebilen gerçekleri de bilen; (hem) her işinde mükemmel olan, (hem de) merhamet kaynağı olan yalnızca O`dur."},{"n":7,"t":"O her şeye yaratılış amacıyla en uyumlu olma ve kemalini bulma (yeteneğini) bahşetmiştir. Öyle ki, insan türünü yaratmaya (basit) bir balçıktan başlamıştır."},{"n":8,"t":"Sonra onun neslini yine (en az o kadar) basit bir sıvı özünden yaratmıştır."},{"n":9,"t":"Daha sonra onu yaratılış amacını gerçekleştirecek bir donanıma sahip kılarak Kendi ruhundan üflemiştir; derken sizi hem işitme ve görme, hem de duygu ve düşünce yetenekleriyle donatmıştır: ne kadar da azınız şükrediyor."},{"n":10,"t":"Bir de kalkıp derler ki: \"Yani biz toprağın içinde kayıplara karışınca mı? Sahiden de biz yeniden yaratılacak mıyız?\" Aslında (bu tavırlarıyla) onlar, Rablerinin huzuruna çıkıp (hesap vermeyi) inkar etmektedirler."},{"n":11,"t":"De ki: \"Sizin için görevlendirilmiş ölüm meleği (nasıl olsa) sizin canlarınızı alacak; en sonunda Rabbinize döndürüleceksiniz."},{"n":12,"t":"Günahı hayat tarzı haline getirenleri Rablerinin huzurunda başları eğik vaziyette (şöyle derken) bir görmeliydin: \"Rabbimiz, (İşte artık) gördük ve işittik! Şu halde bizi (dünyaya) geri döndür de iyi bir şeyler yapalım! Çünkü (yeniden dirilişe) ikna olmuş bulunuyoruz.\""},{"n":13,"t":"İmdi eğer Biz isteseydik, herkesi doğru yola (zorla) sokardık; fakat (bunu istemedik) ki, (iyiler kötülerden seçilsin de) tarafımdan verilmiş bulunan \"Mutlaka cehennemi görünmeyen varlıkların ve insanların (kötüleriyle) tıka basa dolduracağım\" sözü gerçekleşsin."},{"n":14,"t":"Haydi, bu buluşma gününü hatırlanmaya değer bulmadığınız için azabı tadın bakalım! Çünkü artık Biz de sizi hatırlanmaya değer bulmuyoruz. Haydi, yapmakta ısrar ettiklerinizden dolayı ebedi mahrumiyeti tadın!"},{"n":15,"t":"Bizim ayetlerimize iman edenler, ancak kendilerine duyurulduğunda saygıyla yerlere kapanıp teslim olanlar ve Rablerinin aşkın yüceliğini hamd ile ananlardır: zira onlar asla büyüklük taslamazlar."},{"n":16,"t":"Onlar yataklarından kalkarak tarifsiz bir korku ve büyük bir iştiyakla Rablerine yalvarırlar ve verdiğimiz rızıklardan infak ederler."},{"n":17,"t":"İşte, yapa geldiklerinden dolayı bir mükafat olarak, onları (cennette) ne türden göz kamaştırıcı sürprizlerin beklediğini kimse hayal dahi edemez."},{"n":18,"t":"Öyle ya: hiç imanda sebat eden, hak yoldan sapan gibi muamele görür mü? Bunlar asla aynı olamazlar!"},{"n":19,"t":"İman eden ve o imana uygun değer üretenlere gelince: yapa geldiklerinden dolayı mükellef bir ikram olarak ağırlanacakları cennetler onların konağı olacaktır."},{"n":20,"t":"Hak yoldan sapanlara gelince: artık onların da konaklayacakları yer ateş olacak; oradan ne zaman çıkmak isteseler, kendilerine \"Oldum olası yalanlayıp durdurduğunuz ateşin azabını tadın!\" denilerek oraya iade edilecekler."},{"n":21,"t":"Ama onlara, daha büyük mahrumiyeti tattırmadan önce daha yakın (dünya) mahrumiyetini kısmen elbette tattıracağız; umulur ki (yol yakınken) dönerler."},{"n":22,"t":"Kendisine Rabbinin ayetleri hatırlatıldığı halde, onlardan yüz çevirenden daha zalim, yani yaratılış gayesi dışında yaşayan kim olabilir? Bu şekilde, günaha batmış olanlardan biz, intikamımızı mutlaka alacağız."},{"n":23,"t":"Doğrusu Biz Musa`ya da vahiy iletmiştik: şu halde onunla (aynı ortak paydada) buluşacağından asla tereddüdün olmasın! Zira Biz, o (vahyi) de İsrailoğulları için bir yol haritası kılmıştık."},{"n":24,"t":"Yine (unutma ki), zorluklara göğüs gerip ayetlerimize gönülden inandıkları zamanlarda, emrimizle içlerinden hidayete ulaştıran önderler çıkarmıştık."},{"n":25,"t":"Şüphesiz kıyamet günü anlaşmazlığa düştükleri konularda aralarında hüküm verecek olan elbet senin Rabbindir."},{"n":26,"t":"Şimdi kalıntılarında dolaştıkları kendilerinden önce yaşamış uygarlıklardan nicelerini helak etmiş olmamız onlar için yol gösterici olmadı mı? Kuşkusuz bunda da alınacak bir ders mutlaka vardır: hala mı işitmeyecekler?"},{"n":27,"t":"Kıraç toprağa suyu sevk edip de onunla kendilerinin ve hayvanlarının beslendiği bitkiler çıkardığımızı nasıl görmezler? Peki ama, daha da mı görmeyecekler?"},{"n":28,"t":"Bir de diyorlar ki: \"Eğer doğru söylüyorsanız, bu (bahsi geçen) kesin hüküm ne zaman verilecek?\""},{"n":29,"t":"De ki: \"Kesin hükmün verileceği gün inkarda ısrar edenlere ne imanları fayda verecek, ne de göz açtırılacak.\""},{"n":30,"t":"Şu halde boş ver onları da (kendi işine bak); madem onlar beklemeye razılar, sen (dünden) bekle!"}],[{"n":1,"t":"Sen ey peygamber! Allah`a karşı sorumlu davran! (Açıktan) inkar edenlere ve ikiyüzlü davrananlara uyma! Unutma ki Allah her şeyi bilendir, her hükmünde tam isabet edendir."},{"n":2,"t":"(Sadece) Rabbinden sana bildirilene uy: Çünkü Allah yaptığınız her bir şeyden haberdardır."},{"n":3,"t":"Ve yalnızca Allah`a dayan: zira dayanak olarak Allah yeter."},{"n":4,"t":"Allah hiç kimse için bir bedende iki kalp yaratmamıştır; aynen böyle, vücudunu annenizin vücudu gibi haram saydığınız eşlerinizi de hiçbir zaman sizin gerçek anneleriniz kılmamıştır; yine evlatlıklarınızı da sizin gerçek çocuklarınız kılmamıştır: bütün bunlar (düşünmeden) ağzınıza aldığınız boş laflardır; ne ki Allah yalın gerçeği söyler ve O hep doğru yolu gösterir."},{"n":5,"t":"(Şu halde evlatlıkları) babalarına nisbet ederek çağırın, bu Allah katında daha hakkaniyetli bir davranıştır; eğer babalarının kim olduğunu bilmiyorsanız, zaten unutmayın ki onlar sizin din kardeşleriniz ve dostlarınızdır; bu konudaki yanılgılardan dolayı size bir vebal yoktur; fakat asıl kalbinizdeki kasıt (belirleyicidir): zaten Allah tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":6,"t":"Peygamber inananlara kendi öz varlıklarından daha öncelikli gelir; (o onlara baba gibi olduğundan) eşleri de onların anneleridir. Böyle olduğu halde, Allah`ın yasasında yer aldığına göre akraba olanların birbirleri üzerindeki hakları mü`minlerden ve muhacirlerden daha önceliklidir; ancak, geri kalan dostlarınıza da iyi davranmak durumundasınız: zaten bu da yasada kayıtlıdır."},{"n":7,"t":"Biz vaktiyle peygamberlerden söz almıştık-senden, Nuh`tan, İbrahim`den, Musa`dan, Meryem oğlu İsa`dan. Onların hepsinden sağlam bir söz aldık."},{"n":8,"t":"ta ki O, sözlerine sadık kalanların sadakatlerine buldukları karşılığın hesabını sorabilsin: zira O, inkarcılar için acıklı bir azap hazırlamıştır."},{"n":9,"t":"Siz ey iman edenler! Sayısı belirsiz ordular üzerinize geldiğinde Allah`ın size olan nimetini hatırlayın; onların üzerine bir bela kasırgası ve görmediğiniz (semavi) ordular gönderdik: ama Allah yapıp ettiklerinizi görmekteydi."},{"n":10,"t":"Hani onlar önünüzden ve sizin ardınızdan üzerinize gelmişlerdi; işte o an gözlerin yuvalarından fırladığı, yüreklerin ağızlara geldiği bir andı; öyle bir hal ki, Allah`ın ne yapacağı hakkında her tür düşünce zihninizde cirit atıyordu."},{"n":11,"t":"İşte o anda ve orada mü`minler sınanmışlar, şok bir sarsıntıyla sarsılmışlardı."},{"n":12,"t":"O sırada ikiyüzlüler ve kalplerinde hastalık olanlar diyordu ki: \"Allah ve O`nun elçisi bizi yalnızca boş vaadlerle avuttu.\""},{"n":13,"t":"Ve hatırla içlerinden bazısı şöyle demişti: “Ey Medine halkı! Burada düşmana karşı koyamazsınız, evlerinize geri dönün.” Diğer bir gurup da: “Evlerimiz saldırıya açık ve emniyetsiz durumda” diyerek, peygamberden izin istemişlerdi. Halbuki evleri, aslında saldırıya açık değildi, ama tek amaçları savaştan kaçmaktı."},{"n":14,"t":"Eğer şehrin her yanından üzerlerine hücum edilseydi ve onlardan da fitne çıkarmaları istenseydi, onlar bunu bir an bile duraksamadan yaparlardı."},{"n":15,"t":"Oysa ki onlar, daha önce kaçmayacaklarına dair Allah adına söz vermişlerdi: ama (olsun), nasıl olsa Allah`a verilen sözün hesabı sorulacaktı."},{"n":16,"t":"De ki: \"Eğer ölümden ya da öldürülmekten kaçıyorsanız, kaçmanızın size hiçbir yararı yok; zira böyle bir durumda bile, sadece kısa vadeli bir haz elde etmiş olacaksınız.\""},{"n":17,"t":"De ki: \"Eğer O sizi bir zarara uğratmayı dilese, sizi Allah`a karşı kim koruyabilir? Ya da size bir rahmet takdir etse (sizi bundan kim mahrum edebilir)?\" Onlar kendileri için, Allah`tan başka ne bir dost ne de bir yardımcı bulabilirler."},{"n":18,"t":"Doğrusu Allah içinizden (başkalarını savaştan) caydıranları da, kendileri muharebeye çok az katıldıkları halde \"Haydi, katılın bize!\" diyenleri de çok iyi bilir."},{"n":19,"t":"Size yönelik bir kıskançlık bu; öte yandan tehlikeyi hissettikleri zaman da sanki ölüm tarafından çepeçevre kuşatılmışlar gibi gözleri dönmüş bir halde sana (yalvarırcasına) baktıklarını görürsün; tehlike geçtiğinde ise, iyiliğe karşı kıskançlık edip sivri ve keskin bir dille size hücum ederler. İşte bunlar inanmamışlardır; Allah da onların yaptıklarını boşa çıkarmıştır: zira bu Allah için oldukça kolaydır."},{"n":20,"t":"Onlar, müttefiklerin (gerçekte) ayrılmadığını sanıyorlar; ama eğer müttefikler dönüp gelecek olsalar, bu kez de onlar çölde bedeviler arasına karışıp haberlerinizi (uzaktan) almayı tercih edecek kadar (sıvışmayı) isterler; hoş, eğer aranızda bulunmuş olsalardı da, göstermelik bir iki hareket dışında asla savaşmayacaklardı."},{"n":21,"t":"Doğrusu Allah Rasulü sizler için, Allah`a ait ve ahiret gününe umut besleyen ve Allah`ı sürekli hatırda tutan herkes için güzel bir örnek teşkil eder."},{"n":22,"t":"Nitekim mü`minler müttefikleri gördüklerinde: \"Allah`ın ve Rasulü`nün bize vaad ettiği şey işte budur!\" ve \"Allah da doğru söylemiştir, Rasulü de...\" derler. Dahası, bu onların yalnızca imanlarını ve teslimiyetlerini artırmıştır."},{"n":23,"t":"Mü`minler içerisinde Allah adına verdikleri söze sadık kalan nice yiğitler var; onlardan kimi kendini adak olarak sunmuş kimi de sırasını beklemekte, fakat asla sözünden dönmemektedir."},{"n":24,"t":"Neticede Allah sözüne sadık kalanların sadakatlerini ödüllendirmek, iki yüzlü davrananları da isterse cezalandırmak ya da (tevbe ederlerse) tevbelerini kabul etmek için (böyle yapmıştır): çünkü Allah zaten tarifsiz bir bağışlayıcıdır, eşsiz bir merhamet kaynağıdır."},{"n":25,"t":"Allah, kinleri yüzünden küfre gömülenleri geri püskürtmüş, ellerine hiçbir şey geçmemiştir; zira Allah mü`minlere savaşta da yeter: ve zaten Allah eşsiz bir kuvvet, mutlak bir izzet sahibidir."},{"n":26,"t":"Allah, kitap ehlinden düşman gruplara yardım edenleri kalelerinden indirip, kalplerine korku saldı. Siz onlardan bir grubu öldürüyor, bir grubu da esir alıyordunuz."},{"n":27,"t":"Böylece O sizi onların arazilerine, yurtlarına ve mallarına mirasçı kıldı; dahası ayak basmadığınız bir nice toprağı da (vaad etti): zira Allah her şeye kadirdir."},{"n":28,"t":"Sen ey Peygamber! Eşlerine de ki: \"Eğer sizler bu dünya hayatını ve onun ihtişamını istiyorsanız, gelin size dünyalığınızı vereyim ve sizi güzellikle bırakayım;"},{"n":29,"t":"yok eğer Allah`ı, Rasulü`nü ve ahiret yurdunun (mutluluğunu) istiyorsanız, bilin ki Allah içinizden iyi davranışı tabiat haline getirenlere muhteşem bir ödül hazırlamıştır!\""},{"n":30,"t":"Ey Peygamber hanımları! İçinizden her kim açık bir hayasızlık yaparsa, onun azabı ikiye katlanır: zira bu Allah için çok kolaydır."},{"n":31,"t":"Ama içinizden her kim de Allah`a ve Rasulü`ne gönülden boyun eğer ve ıslah edici iyilikler işlerse, onun ödülünü de iki misli veririz; ayrıca ona akıl almaz güzellikte bir rızık hazırlamışızdır."},{"n":32,"t":"Ey Peygamber hanımları! Siz herhangi bir hanım gibi değilsiniz; tabi ki eğer Allah`a karşı sorumluluğunuzun bilincinde olursanız. Şu halde işveli bir edayla konuşmayın, sonra kalplerinde hastalık bulunanlar yersiz bir arzuya kapılırlar; ama güzel ve düzgün konuşun!"},{"n":33,"t":"Evlerinizde (dahi) ağırbaşlılığınızı koruyun! Kadim haddini bilmezlik döneminde olduğu gibi dişiliğinizi ön plana çıkarmayın! Namazınızı hakkını vererek kılın, zekatınızı içten gelerek verin, Allah`a ve Rasulü`ne uyun! Emin olun ki, Allah sizden (maddi manevi) her tür kiri gidermek ve sizi tertemiz yapmak istiyor Ey (Peygamberin) ev halkı; hepsi bu!"},{"n":34,"t":"Bir de evlerinizde okunan Allah`ın ayetlerini, ama (özellikle onlardaki) hikmeti düşünün: şüphesiz Allah (ilmiyle) her şeyin özüne tarifsiz nüfuz eder, her şeyden nihayetsiz haberdardır."},{"n":35,"t":"Şüphesiz Allah`a tam teslim olmuş bütün erkekler ve kadınlar, O`na güvenip inanmış bütün erkekler ve kadınlar, O`na adanmış bütün erkekler ve kadınlar, ahdine sadık bütün erkekler ve kadınlar, sıkıntılara karşı direnen bütün erkekler ve kadınlar, (Allah`a karşı) derin bir saygıyla titreyen bütün erkekler ve kadınlar, (Allah`a) sadakatlerini servetlerini yoksullarla paylaşarak ispat eden bütün erkekler ve kadınlar, benliklerini denetim altına alıp oruç tutan bütün erkekler ve kadınlar, iffetlerini koruyan bütün erkekler ve kadınlar, Allah`ı sürekli hatırda tutan bütün erkekler ve kadınlar... (İşte) bunlara Allah sınırsız bir bağış ve muhteşem bir ödül hazırlamıştır."},{"n":36,"t":"Allah ve Rasulü bir konuda hüküm verdiği zaman, inanan bir erkek ve kadının kendi işlerinde kişisel tercihlerine göre hareket etmeleri düşünülemez: zira kim Allah ve Rasulü`ne isyan ederse, işte o apaçık bir sapıklığa gömülmüş olur."},{"n":37,"t":"Hani bir zamanlar Allah`ın kendisine ikram ettiği, senin de iyilikte bulunduğun kişiye diyordun ki: \"Eşini bırakma ve Allah`a karşı saygılı ol!\" Ama Allah`ın açıklayacağı şeyi sen içinde saklıyordun; zira insanlardan çekiniyordun: oysa ki kendisinden çekinmen gereken sadece Allah`tı. En sonunda Zeyd o kadınla ilişkisini tamamen kesip boşayınca Biz onu seninle evlendirdik ki, evlatlıkları eşleriyle ilişkilerini kesip boşadıklarında kişilerin onlarla evlenmelerinin önünde hiç bir engel bulunmasın: sonuçta Allah`ın emri yerine gelmiş oldu."},{"n":38,"t":"Allah`ın kendisini mecbur tuttuğu suç isnat edilemez. Allah`ın bu sünneti, daha önce gelip geçmiş olan (peygamberler) için de geçerliydi: sonuçta Allah`ın emri ölçülüp biçildiği gibi gerçekleşmiş oldu."},{"n":39,"t":"O (peygamberler), Allah`ın mesajlarını tebliğ edenler, O`ndan korkanlar ve Allah`tan başkasından da asla korkmayanlardı: zira Allah hesap görücü olarak yeterdi."},{"n":40,"t":"(Ey mü`minler!) Muhammed sizin erkeklerinizden herhangi birinin babası değildir; fakat o Allah`ın Rasulü ve peygamberlerin sonuncusudur: Ve zaten Allah her şeyi en ince ayrıntısına kadar bilmektedir."},{"n":41,"t":"Siz ey iman edenler! Allah`ı sürekli hatırda tutun;"},{"n":42,"t":"O`nun aşkın ve yüce olan zatını sabah akşam anın!"},{"n":43,"t":"O sizi melekleri eşliğinde üzerinize indirdiği (vahiyle) destekleyip dimdik ayakta tutar ki, bu sayede sizi karanlıklardan aydınlığa çıkarsın: zira O, mü`minler için sınırsız bir rahmet kaynağıdır."},{"n":44,"t":"O`nun huzuruna çıkacakları o gün \"Selam!\" diye karşılanırlar; O kendilerine tarifsiz güzellikte bir ödül hazırlamıştır."},{"n":45,"t":"Sen ey Peygamber! Elbet Biz seni bir şahit, bir müjdeci ve bir uyarıcı olarak gönderdik;"},{"n":46,"t":"yine O`nun izniyle Allah`a çağıran bir davetçi ve etrafını aydınlatan bir kandil olarak..."},{"n":47,"t":"İmdi mü`minlere, Allah`tan kendilerini büyük bir lütfun beklediğini müjdele!"},{"n":48,"t":"Asla inkarcılara ve ikiyüzlülere uyma ve onlara incitici sözler söyleme/onların incitici sözlerine aldırma; ve yalnız Allah`a güven: zira koruyucu otorite olarak Allah yeter."},{"n":49,"t":"Siz ey iman edenler! Mü`min kadınları nikahlar da onları gerdeğe girmeden önce boşarsanız, onlara karşı iddet hesaplama hakkınız yoktur; şu halde derhal onlara dünyalıklarını verin ve kendilerini güzellikle salıverin."},{"n":50,"t":"Sen ey Peygamber! Biz sana mehir bedellerini verdiğin eşlerini; savaş esirleri arasından sağ elinin altında bulunan kimseleri; seninle birlikte göç etmiş bulunan amca ve hala kızlarını, dayı ve teyze kızlarını; ve kendilerini Peygamber`e (mehir bedeli istemeksizin) sunan ve peygamberin de kendilerini nikahlamayı kabul ettiği mü`min kadınları -ki bu yalnızca sana hastır, diğer mü`minler için değildir- helal kıldık. Doğrusu onlara eşleri ve sağ elleri altında bulunanlar konusundaki talimatlarımızı bilmekteyiz; ne ki bununla amaçlanan, senin zor durumda kalmamandır: zaten Allah tarifsiz bir bağışlayıcıdır, eşsiz bir merhamet kaynağıdır."},{"n":51,"t":"Onlardan dilediğini daha sonraya bırakabilir, dilediğini de yanına alabilirsin; ilişkini dondurup (sonraya) bıraktıklarından birini yeniden istemende senin için bir beis yoktur: bu (seni her görüşte) onların gözlerinin ışımasını, üzülmemelerini ve onlara verdiğin şeylerden razı olmalarını sağlar; ve sadece Allah kalplerinizde olanı bilir: ama zaten Allah her şeyi bilir, tarifsiz bir ilim sahibidir."},{"n":52,"t":"Bundan sonra sana, başka hiçbir hanım helal değildir; güzellikleri seni hayran bıraksa dahi -sağ elinin altında bulunanlar hariç- onlardan hiçbirini değiştiremezsin: hem zaten Allah her şeyi gözetleyendir."},{"n":53,"t":"Siz ey iman edenler! Size izin verilmedikçe Peygamber`in evlerine girmeyin; yemeğe (davet) edildiğinizde (erken gelip) yemeğin hazırlanmasını beklemeyin; lakin ne zaman davet edilirseniz o zaman içeri girin! Yemeği yediğiniz zaman da hemen ayrılın, lafa dalmayın! Çünkü böyle yapmanız Peygamber`i üzebilir, fakat o bunu söylemek için sizden çekinir; ama Allah hakikati söylemekten asla çekinmez. (Ey mü`min erkekler!) Onlardan bir şey isteyeceğiniz zaman, kapı dışından isteyin: bu sizin kalplerinizin de, onların kalplerinin de daha temiz kalması için en uygun yoldur. Dahası sizin ne Allah Rasulü`nü üzmeniz, ne de ölümünden sonra onun eşleriyle evlenmeniz ebediyyen helal değildir: çünkü bütün bunlar Allah katında zaten çok büyük bir vebaldir."},{"n":54,"t":"Bir şeyi açıklasanız da gizleseniz de (fark etmez): unutmayın ki Allah her şeyi en ince ayrıntısına kadar zaten bilmektedir."},{"n":55,"t":"(Ne ki) onların babaları, oğulları, kardeşleri, erkek kardeşlerinin oğulları, kız kardeşlerinin oğulları, kendi cinslerinden olan kadınlar ve sağ elleri altında bulunanlar konusunda bir mahzur yoktur. Ama (Ey Peygamber hanımları), siz hep Allah`a karşı sorumluluk bilinciyle hareket edin: çünkü Allah her bir şeye şahittir."},{"n":56,"t":"Şu kesin ki Allah ve O`nun melekleri Peygamber`i desteklerler; ey iman edenler, siz de onu destekleyin ve tam bir teslimiyetle (onun örnekliğine) teslim olun!"},{"n":57,"t":"Allah`ı ve Rasulü`nü incitenlere gelince: Allah onları bu dünyada da öte dünyada da rahmetinden mahrum edecek ve onlar için alçaltıcı bir azap hazırlayacak."},{"n":58,"t":"Bir de, mü`min erkekler ve kadınları işlemedikleri şeylerle suçlayarak eza edenler var: İşte bunu yapanlar, iftira atmış ve apaçık bir suç işlemiş olurlar."},{"n":59,"t":"Sen ey Peygamber! Eşlerine, kızlarına, (bütün) mü`minlerin hanımlarına (toplum içine çıktıklarında) üzerlerine (tesettürü tam sağlayan) giysilerini almalarını söyle: bu onların (mü`min ve saygın kadınlar olarak tanınmaları ve rahatsız edilmemeleri için daha uygundur: Ve Allah zaten tarifsiz bir bağış, eşsiz bir merhamet kaynağıdır."},{"n":60,"t":"Şu kesin ki, eğer ikiyüzlüler, kalplerinde hastalık bulunanlar ve şehirde yalan haber yayarak ortalığı karıştıranlar buna bir son vermezlerse, seni onların üzerine öyle bir salarız ki, sonra kısa bir süre dışında sana komşu olarak bile orada kalamazlar."},{"n":61,"t":"Allah`ın rahmetinden dışlanmış olarak göze kestirilen her yerde enselenip kesinkes öldürülürler:"},{"n":62,"t":"Allah`ın daha öncekiler için geçerli olan uygulaması budur; ve sen Allah`ın sünnetinde hiçbir değişiklik bulamazsın."},{"n":63,"t":"İnsanlar sana Son Saat hakkında soruyorlar. De ki: \"Onun bilgisi sadece Allah katındadır. Sana kim bildirebilir ki: Son Saat belki yakındır, (belki de uzak)?"},{"n":64,"t":"Şüphe yok ki Allah, inkarcıları rahmetinden mahrum etmiş ve onlar için çılgın bir ateş hazırlamıştır."},{"n":65,"t":"Onlar orada ebediyen kalacaklar: ne bir dost ne de bir yardımcı bulacaklar."},{"n":66,"t":"Ateşte yüzlerinin ters çevrildiği o gün \"Ah keşke Allah`a itaat etseydik, Rasul`e itaat etseydik!\" diyecekler."},{"n":67,"t":"Yine \"Rabbimiz!\" diyecekler, \"Fakat biz ileri gelenlerimize, büyüklerimize uyduk; sonuçta onlar da bizi yoldan saptırdı."},{"n":68,"t":"Rabbimiz! Ne olur onlara kat be kat azap ver ve onları rahmetinden tamamen dışla!"},{"n":69,"t":"Ey iman edenler! Musa`ya eziyet eden (İsrailoğulları) gibi olmayın! Hatırlayın ki Allah onların itham ettikleri şeylerden onu temize çıkardı: ve o Allah katında zaten hatırlı biriydi."},{"n":70,"t":"Siz ey iman edenler! Allah`a karşı sorumlu davranın ve sözü yerinde ve dosdoğru söyleyin!"},{"n":71,"t":"(O zaman) O da sizin işlerinizi yoluna koyar ve günahlarınızı bağışlar. Zira her kim Allah`a ve Rasulü`ne uyarsa, iyi bilsin ki o nihai ve büyük kurtuluşa ermiştir."},{"n":72,"t":"İşin gerçeği Biz emaneti göklere, yere ve dağlara sunduk; ve onlar emanete ihanetten kaçındılar; nihayet onu insan yüklendi: ne var ki, o da zalim ve cahil biri olup çıktı."},{"n":73,"t":"Bundan dolayıdır ki Allah iki yüzlü erkeklere ve kadınlara, Allah`tan başkasına ilahlık yakıştıran erkeklere ve kadınlara azap edecek; inanan erkeklerin ve kadınların tevbelerini de kabul edecektir: zira Allah zaten tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."}],[{"n":1,"t":"Hamd, tümüyle göklerde ve yerde var olan her şeyin gerçek sahibi Allah`a mahsustur; yine hamd öteki alemde de, tümüyle O`na mahsus olacaktır: zira yalnız O`dur her hükmünde tam isabet kaydeden, her şeyden haberdar olan."},{"n":2,"t":"Toprağa giren ve oradan çıkan her şeyi, yine gökten inen ve göğe yükselen her şeyi O bilir; ne ki tarifsiz bağışlayan da, eşsiz merhametin kaynağı olan da yine O`dur."},{"n":3,"t":"Ama küfürde direnenler \"(Kıyamet) Saati asla gelip bizi bulmayacak!\" dediler. De ki: \"Hayır, Rabbime andolsun ki o mutlaka gelip sizi bulacaktır!\" O, idraki aşan hakikatleri bilendir. Göklerde ve yerde zerre kadar bir şey bile O`nun bilgisinden kaçıp kurtulamaz: İster bundan daha küçük olsun, ister daha büyük; bütün bunlar kesin ve net bir yazılım ve yasayla kayıt altına alınmıştır."},{"n":4,"t":"Ki böylece O, iman eden ve imanla uyumlu eylem üretenleri ödüllendirecektir: işte böylelerini sınırsız bir bağış ve tarifsiz güzellikte bir rızık beklemektedir."},{"n":5,"t":"Ama mesajlarımızı amacından mahrum bırakmak için çaba gösterenlere gelince: işte böylelerini de, (bu) çirkinlikten dolayı acıklı bir azap beklemektedir."},{"n":6,"t":"Bilgi ve bilginin amacını kavrama yeteneğiyle donatılmış olanlar, Rabbinden sana indirilenin hakikatin ta kendisi olduğunu; ve O yüceler yücesi, O tüm övgülere layık olanın yoluna yönelteceğini görmektedirler."},{"n":7,"t":"Beri yanda inkara saplanmış olanlar (yandaşlarına) derler ki: \"Siz paramparça olup dağıldıktan sonra, size yeniden yaratılacağınızı haber veren bir adam gösterelim mi?"},{"n":8,"t":"O uydurduğu yalanı Allah`a mı isnat ediyor, yoksa kendisinde delilik belirtileri mi var?\" Hayır! Asıl ahirete inanmayan kimseler, can yakıcı bir terk edilmişliğe ve en uç noktada bir sapıklığa mahkum olacaklar."},{"n":9,"t":"Onlar gökten ve yerden ne kadarını önlerine serdiğimize, ne kadarını da kendilerinden gizlediğimize bakmazlar mı? Eğer Biz dileseydik, onları yerin dibine geçirir ya da göğü başlarında paralardık. Şüphe yok ki bütün bunlarda, O`na yönelen her bir kul için mutlaka alınacak bir ders vardır."},{"n":10,"t":"Doğrusu Biz Davud`u katımızdan (işte bu nedenle) ödüllendirmiştik: \"Ey dağlar! Onun sesine ses katın! Siz (öyle yapın ey) kuşlar!\" Dahası, Biz ondaki bütün katılığı ve sertliği yumuşattık (ve dedik ki):"},{"n":11,"t":"\"İşleri en güzel, en ideal bir şekilde hakkını vererek yap ve onlar arasındaki ölçü ve uyumu gözet!\" Ve hepiniz Allah`ı razı edecek işler yapın! Çünkü Ben, yaptığınız her işi görmekteyim."},{"n":12,"t":"Süleyman`ın emrine de rüzgarı amade kıldık: onun gidişi bir aylık mesafeyi, dönüşü yine bir aylık mesafeyi buluyordu. Ve erimiş metal cevherini onun için akıttık; yine cinlerden bir kısmı, Rabbinin izniyle onun emri altında çalışıyordu; ve onlardan hangisi emrimizden çıkarsa, ona çılgın bir ateşin azabını tattırıyorduk."},{"n":13,"t":"Onlar arzusuna göre ona mabedler, heykeller, göletler gibi yekpare dökümden havuzlar ve yere tespit edilmiş dev küvetler yapıyorlardı. (Biz de dedik ki): \"Ey Davud`un inanç ailesi; şükretmek için çok çalışın! Ne ki, samimi kullarım arasında bile hakkıyla şükreden pek azdır."},{"n":14,"t":"(Süleyman`ın görkemli iktidarına rağmen) bir zaman geldi ölüm hakkındaki yasamız ona da hükmetti; bastonunu kemiren ağaç kurdu olmasaydı, öldüğünü onlara bildiren bir delil asla olmayacaktı; nihayet (baston kırılıp) Süleyman devrilince, (bir gerçek) anlaşılmış oldu: eğer cinler gaybı bilmiş olsalardı, o küçük düşürücü cezaya katlanmalarına gerek kalmazdı."},{"n":15,"t":"Doğrusu (bu), yurtlarında bir nice ibret bulunan Sebe halkı için de geçerliydi: sağdan ve soldan boylu boyunca uzanan cennetler (gibi bir doğa, hal diliyle sanki şöyle sesleniyordu): \"Rabbinizin size bahşettiği rızıktan nasiplenin, ama O`na olan şükrünüzü de eda edin! (İşte) tarifsiz güzellikte bir yurt ve tarifsiz bağışlayıcı bir Rab!\""},{"n":16,"t":"Ne var ki onlar yüz çevirdiler. İşte bu yüzden Biz onların üzerine (barajlarını) yıkan şiddetli bir sel gönderdik ve o iki has bahçeyi, acı meyveli çalılar ve ılgınlarla kaplı, içerisinde birkaç sedir cinsi ağaç bulunan harap bir bahçeye çevirdik."},{"n":17,"t":"İnkarda inat etmelerinden dolayı onları işte böyle cezalandırdık: biz nankörlerden başkasını hiç cezalandırır mıyız?"},{"n":18,"t":"Biz (bu helaktan önce) onlara, mübarek kıldığımız şehirlerle kendileri arasına birbirine nazır beldeler inşa ed(ecek kudret ver)dik; ve bunlar arasında düzenli ulaşımı temin ettik; (ve bu yolla) \"Geceler ve gündüzler boyunca güvenli bir biçimde yolculuk yapın!\" (demiş olduk)."},{"n":19,"t":"Buna rağmen onlar \"Rabbimiz! Sefer menzillerimiz arasındaki mesafeyi uzat!\" de(meye getir) diler ve böylece kendilerine zulmetmiş oldular. Bunun üzerine biz de onları geçmişin efsanelerine döndürdük ve param parça edip dağıttık. Hiç şüphesiz bütün bunlarda, derin bir şükran duygusuyla O`na kutllukta direnen herkes için mutlaka alınacak dersler vardır."},{"n":20,"t":"Ve doğrusu İblis, onların aleyhinde kanaat belirtirken yanılmamıştı; nitekim bir gurup inanan hariç geri kalanların hepsi ona uydular."},{"n":21,"t":"Oysa ki onlar üzerinde onun zorlayıcı hiçbir gücü yoktu; sadece ahirete inanan kimseleri ondan kuşku duyanlardan seçip ayıralım diye (ona izin verdik): nitekim senin Rabbin her şeyi görüp gözetmektedir."},{"n":22,"t":"De ki: \"Allah dışında, (kendilerinde tanrısal güç) vehmettiklerinizi çağırın. Ne göklerde ne de yerde onların zerre kadar bir gücü yoktur; üstelik onlar bu ikisinin (yönetiminde) bir ortaklığa da sahip değiller; dahası O onlar arasından kendisine bir yardımcı da atamamıştır.\""},{"n":23,"t":"O`nun nezdinde, kendisi lehine izin verdikleri dışında hiç kimse için şefaat fayda vermez: nihayet (kıyametin) dehşeti (ödül tevdi edeceklerin) kalplerinden giderilince (ödüllendirilenler) soracaklar: \"Rabbiniz sizin hakkınızda ne buyurdu?\" Berikiler \"Hak neyse onu: zaten mükemmel olan da, büyük olan da sadece O`dur\" diyeceklerdir."},{"n":24,"t":"Sor onlara: \"Göklerden ve yerden size rızık veren kimdir?\" \"Allah`tır!\" de (ve ekle): \"Şu takdirde biz ya da siz; ama mutlaka (ikimizden biri) doğru yoldaysa, diğeri de derin bir sapıklığa gömülmüş demektir.\""},{"n":25,"t":"De ki: \"Ne siz bizim suçlarımızın hesabını vereceksiniz, ne de biz sizin işlediklerinizin hesabını.\""},{"n":26,"t":"De ki: \"Rabbimiz bizi (bir gün) bir araya getirecek ve aramızda hükmünü hakkıyla verecektir: zira O her hükmü hakkıyla verendir, her şeyi ayrıntısıyla bilendir.\""},{"n":27,"t":"De ki: \"Ona ortak olarak tasavvur ettiklerinizi bana bir gösterin bakayım! Asla yapamazsınız! Aksine O mutlak üstün ve yüce olan, her hükmünde tam isabet kaydeden Allah`tır.\""},{"n":28,"t":"(Ey Nebi!) Biz seni ancak, bütün insanlık için bir müjdeci ve uyarıcı olarak gönderdik; ama insanların çoğu bunun farkına dahi varmamış olacaklar"},{"n":29,"t":"ki, \"Bu vaad ne zaman gerçekleşecek; eğer sözünüze sadıksanız (söyleyin)?\" diyorlar."},{"n":30,"t":"De ki: \"Sizin için bir gün tesbit edilmiştir: (o gün geldiğinde) ne onu bir an erteleyebilir, ne de atlatabilirsiniz\"."},{"n":31,"t":"İnkarda ısrar edenler dediler ki: \"Bizler ne bu Kur`an`a inanırız, ne de geçmiş vahiylerden bugüne kalanlara.\""},{"n":32,"t":"Büyüklük taslayanlar mustaz`aflara \"Ne! Ayağınıza kadar gelen hidayetten sizi Biz mi mahrum ettik yani? Asla! Siz zaten günahı hayat tarzı haline getirmiştiniz!\" diye cevap verecekler."},{"n":33,"t":"Bu kez zayıf bırakılanlar büyüklük taslayanlara \"Hayır\" diye itiraz edecekler, \"(İşiniz gücünüz) gece gündüz dolap çevirmek! Hatırlasanıza bir; bize Allah`a yabancılaşmamızı ve O`na eşdeğer rakip güçler tanımamızı dayatıyordunuz!\" Derken onların tümü de asıl pişmanlığı, kendilerini bekleyen azabı görünce yüreklerinin en derinlerinde yaşayacaklar; zira Biz inkarda ısrar edenlerin boyunlarına halkalar geçireceğiz: hem yaptıklarının bunun dışında bir karşılığı mı var?"},{"n":34,"t":"Ve ne zaman Biz bir topluma uyarıcı göndermişsek, oranın refah içinde şımarmış seçkinleri \"Sizinle gönderilen şeyin ısrarlı inkarcısıyız\" derler."},{"n":35,"t":"Yine, \"Biz servet soy açısından sizden daha güçlüyüz: bu durumda bizim cezaya çarptırılmamız söz konusu olamaz\" derler."},{"n":36,"t":"De ki: \"Şüphe yok ki isteyene rızkı açmayı da, sınırlandırmayı da dileyen benim Rabbimdir; fakat insanların çoğu bunu(n hikmetini) dahi kavrayamaz.\""},{"n":37,"t":"Sizleri Bizim katımıza yakın kılacak olan ne servetinizdir, ne de soyunuz; fakat iman eden ve imanla uyumlu iş işleyen kimseler var ya: işte onları yaptıklarına karşılık ödülün en katmerlisi beklemektedir; ve onlar yüce köşklerde, huzur ve güven ortamında yaşayacaklar."},{"n":38,"t":"Ama ayetlerimizin amacını geçersiz kılmaya çalışan kimseler, azabın içerisinde (yaptıklarıyla) yüzleşecekler."},{"n":39,"t":"Tekrar et: \"Şüphe yok ki, isteyen kullarına rızkı açmayı da, onun lehine sınırlandırmayı da dileyen benim Rabbimdir; ama siz her ne infak ederseniz O onun yerini hemen doldurur; zira O rızık verenlerin en hayırlısıdır."},{"n":40,"t":"Ama (o haddini bilmezlere gelince); bir gün onların tümünü bir araya getirecek ve ardından meleklere soracağız: \"Bunların tapındıkları siz miydiniz?\""},{"n":41,"t":"(Melekler) \"Aşkın olan zatını tenzih ederiz ki onlar değil, Sensin bizim velimiz! Hayır, onlar öteden beri cinlere tapıyorlardı; bunların çoğu onlara iman etmişti!\" diyecekler."},{"n":42,"t":"Derken (Allah şöyle buyuracaktır): \"Sizin hiçbiriniz bir diğerine bugün ne yarar, ne de zarar verecek güce asla sahip değilsiniz!\" Ve o gün haddini bilmezlere şöyle sesleniriz: \"Kendisini yalanlayıp durduğunuz ateşin azabını tadın bakayım!\""},{"n":43,"t":"Ve ayetlerimiz onlara açık ve seçik olarak aktarıldığında dediler ki: \"Bu sizi öteden beri atalarınızın taptıklarından uzaklaştırmaya çalışan birinden başkası değil.\" Bir de şunu eklediler: \"Bu (Kur`an) uydurulmuş düzme koşma bir (mesajdan) ibarettir.\" Nihayet inkarda direnenler ayaklarına kadar gelen hakikat için, \"bu açıkça büyüleyici bir sözden başka bir şey değil\" dediler."},{"n":44,"t":"Halbuki Biz onlara ne okuyup öğrenecekleri vahiyler, ne de senden önce bir uyarıcı göndermiş değildik."},{"n":45,"t":"Dahası onlardan öncekiler de yalanlamışlardı; ama onlara verilen (manevi nimetler, bu ümmete) verilenin onda birine bile ulaşmamıştı; buna rağmen elçilerimi yalanladılar ve sonuçta inkar nasıl olurmuş gördüler."},{"n":46,"t":"De ki: \"Size tek bir öğüdüm var: ister başkalarıyla beraber ister yalnız başınayken, Allah`ın huzurunda bulunduğunuz gerçeğini asla (unutmayın)! Sonra arkadaşınızda delilikten eser olmadığını düşünün: onun tek yaptığı, önünüzde bekleyen şiddetli mahrumiyete karşı sizi uyarmaktır."},{"n":47,"t":"De ki: \"Sizden hiçbir ücret talep etmiş değilim; o sizin olsun! Benim ücretimi takdir etmek sadece Allah`a düşer: zira O her şeye fazlasıyla tanıktır.\""},{"n":48,"t":"De ki: \"Şüphesiz Rabbim (batılın başını) ebedi gerçekle parçalayacaktır; O kimsenin bilmediği (geleceğin nelere gebe olduğunu) çok iyi bilir.\""},{"n":49,"t":"De ki: \"Ebedi gerçek (gündeme) gelmiştir: artık sahte ve yalan ne yeni bir şey ortaya koyabilir, ne de geçmişi geri getirebilir.\""},{"n":50,"t":"De ki: \"Eğer ben saparsam kendi aleyhime sapmış olurum; yok eğer doğru yoldaysam, bu yalnızca Rabbimin bana ilettiği vahiy sayesindedir: şüphesiz O her şeyi işitir, O (kuluna şah damarından) çok daha yakındır."},{"n":51,"t":"Asıl sen onları, şah damarlarından yakalanıp kaçacak delik bulamamış bir halde dehşetten panikledikleri zaman bir görmeliydin!"},{"n":52,"t":"İşte onlar (o zaman) \"Biz ona inandık!\" diye haykırırlar. Ama bunca uzak mesafeden (kurtuluşa) zahmetsizce ulaşmak nasıl ve nereden mümkün olacak?"},{"n":53,"t":"Oysa ki onlar daha önceden inkar etmişler ve (dünya gibi) uzak bir noktadan (ahiret gibi) idraki aşan bir gerçeğe dil uzatmışlardı."},{"n":54,"t":"Artık kendileriyle arzu ve özlemleri arasına bir set çekilmiştir; tıpkı kendilerinden önce geçip gitmiş kafadarlarına yapıldığı gibi: çünkü ötekiler de korku ve endişeyle karışık bir kuşku içinde (helak) olup gitmişlerdi."}],[{"n":1,"t":"Hamd tümüyle, gökleri ve yeri bir çekirdeği yarar gibi yoktan var eden; melekleri ikişer, üçer ve dörder kanatlı elçiler kılan Allah`a muhsustur. O yaratıkların kapasitesinde dilediği artışı gerçekleştirir: çünkü Allah her şeye güç yetirendir."},{"n":2,"t":"Allah`ın insanlar için açacağı rahmet kapısını kimse kapatamaz; O kapattıktan sonra da onu kimse açamaz: zira O her işinde mükemmeldir, her hükmünde tam isabet kaydedendir."},{"n":3,"t":"Siz ey insanlar: Allah`ın üzerinizdeki nimetini hatırlayın! Allah`tan başka sizi gökten ve yerden sürekli doyuracak bir yaratıcı mı var? O`ndan başka ilah yoktur: şu halde, nasıl böylesine savruluyorsunuz?"},{"n":4,"t":"Eğer seni yalanlıyorlarsa, unutma ki senden önce de bir çok peygamber yalanlanmıştı: sonunda her iş döner dolaşır Allah`ın (dediğine) varır."},{"n":5,"t":"Siz ey insanlar! İyi bilin ki Allah`ın vaadi gerçekleşecektir! Şu halde dünya hayatı sizi asla ayartmasın! Dahası aldatıcının hiçbir türü sizi Allah (hakkındaki asılsız düşünceler) ile aldatmasın!"},{"n":6,"t":"Şeytanın sizin düşmanınız olduğu kesin; o halde siz de onu düşman olarak bilin! O kendi yoldaşlarını, çılgın ateşin sakinleri olacakları bir akıbete çağırır."},{"n":7,"t":"İnkarda direnenleri şiddetli bir ceza beklemektedir. Ama imanda sebat eden ve imanla uyumlu eylem üretenlere gelince: işte böylelerini de sınırsız bir bağış ve muhteşem bir ödül beklemektedir."},{"n":8,"t":"Ne yani, şimdi süslü püslü kötülüklerin albenisine kapılıp bir de onları güzellik gibi gören(in sonu, yukarıdaki) kimsenin sonuyla aynı olur mu? Hiç şüphe yok ki Allah (sapmak isteyenin) sapmasını diler, (hidayet isteyeni) de doğru yola yöneltmeyi diler: Şu halde onların (imana ermesi) için duyduğun özlem seni yıpratmasın; çünkü Allah onların neler yapmakta olduklarını çok iyi biliyor."},{"n":9,"t":"Allah, rüzgarları elçi (gibi) gönderip peşi sıra bulutları tetikleyen ta kendisidir; derken Biz onu çorak bir beldeye sevk ederiz; ve bu sayede onunla ölü toprağa can veririz: yeniden diriliş de işte böyle olacaktır."},{"n":10,"t":"Kim kalıcı şeref ve itibar arıyorsa, iyi bilsin ki bütün bir şeref ve itibarın kaynağı Allah`tır. O`na sadece güzel sözler yükselir, o sözleri yücelten ise imana uygun eylemlerdir. Gizliden gizliye çirkin entrikalar tasarlayanlara gelince: onları şiddetli bir azap beklemektedir; bu gibilerin tuzakları da hiçe çıkacaktır."},{"n":11,"t":"Allah sizi önce topraktan, sonra bir damla sudan yarattı, sonra da sizi çiftler haline getirdi. Onun ilmi olmadan bir dişi ne gebe kalır, ne doğurur. Bir canlıya ne ömür verildiği de, onun ömründen neyin kısıldığı da bir kitapta yazılıdır. Bu ise Allah için pek kolaydır."},{"n":12,"t":"Dahası (O`nun benzerler arasında farklılıklar yaratması da zor değildir): İki büyük su kütlesi (bile) aynı olmayabilir: şu biri tatlı, susuzluğu giderici, içimi kolay; o biri tuzlu, acı. Ne ki her birinden hem taze balık eti yersiniz, hem de takı olarak kullandığınız süs eşyaları çıkarırsınız. Bir de (Allah`ın) lütfundan nasibinizi aramanız ve şükretmeniz için, onun bağrında gemilerin dalgaları yararak yol aldıklarını görürsün(üz)."},{"n":13,"t":"O geceyi uzatarak gündüzü kısaltıyor ve gündüzü uzatarak geceyi kısaltıyor; yine O güneşi ve ayı emre amade kılmıştır: her biri belirli bir süre için devranını sürdürüyor. İşte sizin Rabbiniz, mülkün tamamı kendisine ait olan Allah`tır: O`ndan başka yalvarıp yakardıklarınız hurma çekirdeğinin zarı kadar bile bir şeye sahip değildir."},{"n":14,"t":"Onlara yalvarsanız bile sizin yalvarıp yakarışınızı duymazlar; duysalar bile sizin imdadınıza yetişemezler: kıyamet günü de kendilerine yakıştırdığınız ortaklığı reddederler. (Ey insan!) Sana hiç kimse, her şeyden haberdar olan (Allah`ın) verdiği türden bir haber veremez!"},{"n":15,"t":"Ey insanlık! Allah`a muhtaç olanlar sizlersiniz! Allah`a gelince: O kendi kendine yeten sonsuz zenginlik sahibidir, (bilakis) her şey O`na hamd ile memurdur."},{"n":16,"t":"Dilerse sizi ortadan kaldırır ve yerinize yeni bir topluluk getirir:"},{"n":17,"t":"zira bu Allah`a asla güç gelmez."},{"n":18,"t":"Hiç kimse bir başkasının sorumluluğunu yüklenecek değildir; yükü ağır gelen kimse onu taşımak için yardım istese, yakını da olsa (bir başkası) onun yükünün bir kısmını dahi taşıyamaz. Şu bir gerçek ki sen, O idraki aşan bir hakikati olmasına karşın, Rablerine karşı derin bir ürperti duyanları ve kulluğun hakkını verenleri uyarabilirsin; hem kim arınırsa sırf kendisi için arınmış olur: zira bütün yollar Allah`a çıkar."},{"n":19,"t":"Kaldı ki ne (gerçeği) görenle görmeyen bir olur,"},{"n":20,"t":"ne de aydınlıkla karanlıklar."},{"n":21,"t":"Dahası, ne serinletici gölgeyle kavurucu sıcaklıklar,"},{"n":22,"t":"ne de (manen) dirilerle ölüler bir olurlar. Şu kesin ki Allah, işitmeyi dileyene işittirir, fakat sen mezardakiler (gibi manen) ölmüş olanlara asla işittiremezsin:"},{"n":23,"t":"sen sadece bir uyarıcısın."},{"n":24,"t":"Şüphe yok ki Biz seni hakikate sadık bir müjdeci ve uyarıcı olarak gönderdik: zira hiçbir ümmet yoktur ki içlerinden bir uyarıcı çıkmamış olsun."},{"n":25,"t":"Eğer seni yalanlıyorlarsa, unutma ki, bunlardan öncekiler de, elçileri kendilerine hakikatin apaçık delilleriyle, hikmet yüklü sayfalarla ve aydınlatıcı vahiy ile geldiklerinde yalanlamışlardı."},{"n":26,"t":"En sonunda inkarda ısrar edenleri yakaladım: Haydi, inkar nasıl olurmuş görsünler bakalım!"},{"n":27,"t":"Görmedin mi, muhakkak ki Allah gökten bir su indirdi. Böylece onunla renkleri muhtelif mahsûller çıkardık. Dağlardan da beyaz, kırmızı, renkleri farklı ve simsiyah yollar (yaptık)."},{"n":28,"t":"Dahası insanlar, (vahşi) canlılar ve evcil hayvanlar da (uyumlu) bir farklılığın renklerini taşıyorlar. İşte (kullar da farklılıkta) böyledir ve Allah`a kulları içinde yalnızca (bunun hikmet ve amacını) bilenler hakkıyla saygı duyarlar: çünkü Allah çok üstün ve yücedir, tarifsiz bir bağışlayıcıdır."},{"n":29,"t":"Şüphesiz Allah`ın kelamını tilavet edenler, namazı istikametle kılanlar, ancak verdiğimiz rızıktan gizli ve açık Allah yoluna harcayanlar asla tüketilemez bir kazanç elde etmeyi umabilirler;"},{"n":30,"t":"neticede (Allah) onlara karşılıklarını tam olarak ödeyecek, üstelik kendisinden bir bağış olarak fazlasını da lutfedecektir: zira O tarifsiz bir bağışlayıcıdır, şükre hadsiz hesapsız bir karşılık verendir."},{"n":31,"t":"Sana vahyettiğimiz ilahi kelam, önceki vahiylerden kendisine kadar ulaşmış olanları doğrulayan hakikatin ta kendisidir. Elbette Allah kullarının (gidişatından) bire bir haberdardır, her şeyi görmektedir."},{"n":32,"t":"Derken, bu ilahi kelamı (tebliğ işine) kullarımızdan seçtiklerimizi varis kıldık: fakat onların içerisinden kimisi kendine zulmeder, kimisi ortalama bir yol tutar, kimisi de Allah`ın izniyle her iyi şeyde öncülük eder: bu, işte budur muhteşem zafer!"},{"n":33,"t":"Onlar kalıcı mutluluk ve güzelliğin merkezi olan cennetlere girecekler; altın künyeleri-bilezikleri, inci takıları orada takınacaklar ve elbiseleri orada tarifsiz bir özgürlüğün göstergesi olacak."},{"n":34,"t":"Ve diyecekler ki: \"Hüznü bizden gideren Allah`a hamdolsun; gerçekten de Rabbimiz, tarifsiz bir bağışlayıcıymış, Kendisine yapılan şükre hadsiz hesapsız bir karşılık verenmiş."},{"n":35,"t":"O lütfuyla bizi bu (varlığı ve güzelliği) kalıcı diyara yerleştirdi: burada semtimize ne yorgunluk ve bezginlik, ne de can sıkıntısı ve bıkkınlık uğrayacak!\""},{"n":36,"t":"İnkarda ısrar edenlere gelince: Onlar cehennem ateşine mahkum olacaklar. İzin verilmez ki ölsünler. Dahası azapları kısmen dahi hafifletilmez: işte Biz her bir nankörü böyle cezalandırırız."},{"n":37,"t":"Ve onlar orada şöyle feryat figan ederler: \"Rabbimiz! Kurtar bizi! (Söz), daha önce yaptıklarımızdan daha farklı, daha iyi şeyler yapacağız!\" (Şöyle cevap verilecek): \"Size aklını başına almaya gönüllü birine yetecek kadar uzun bir ömür vermemiş miydik? Üstelik bir de uyarıcı gelmişti! Şu halde (elinizin ürünlerini) tadın; ama kendini kaybedenlerin hiçbir yardımcısı olmayacağını da unutmayın!\""},{"n":38,"t":"Şüphe yok ki Allah göklerin ve yerin gaybi gerçeklerini bilendir; nitekim O, göğüslerde saklı en mahrem sırları da bilendir."},{"n":39,"t":"O`dur sizleri yeryüzünde halifeler kılan. Şu halde kim O`nu inkar ederse bu inkarın zararı kendisine olur; zira inkarcıların küfrü Rableri katında sadece alçalışlarını arttırır; yine inkarcıların küfrü (kendileri için) de sadece aldanışlarını arttırır."},{"n":40,"t":"De ki: \"Hiç Allah`ı bırakıp da yalvarıp yakardığınız varlıklar olan şu şirk nesneleriniz hakkında kafa yordunuz mu? Bana gösterin bakayım, yeryüzünde neyi yaratmışlar? Yoksa onların gökler(in yönetimin)de bir payı mı var? Veyahut onlara bir vahiy indirdik de, kendileri delil olarak ona mı dayanıyorlar? Asla! bu haddini bilmezler, birbirlerine sadece aldanış vaad ediyorlar."},{"n":41,"t":"Şu açık ki, yok olurlar diye gökleri yeri (yörüngede) tutan sadece Allah`tır; eğer (yörüngeden) sapmalarına (izin verirse), bunun ardından hiçbir güç onları tutamaz: ne var ki O cezalandırmada hiç acele etmeyendir, eşsiz bir bağışlayıcıdır."},{"n":42,"t":"Bir de o (inkarcı)lar, kendilerine bir uyarıcı geldiği takdirde, doğru yolu bulmakta tüm toplumların önünde yer alacaklarına dair Allah adına var güçleriyle yemin ettiler; fakat onlara bir uyarıcı geldiğinde ise, bu onların sadece tepkilerini artırdı;"},{"n":43,"t":"yeryüzünde kibir ve çirkin bir entrika (düzeni kurdular). Oysa ki her çirkin entrika sadece onu çevireni çepeçevre kuşatır: bu durumda onlar, öncekilere uygulanan ilahi uygulama dışında başka bir şey mi bekliyorlar? Ve sen Allah`ın yasasında bir başkalaşma göremezsin; evet sen Allah`ın yasasında bir sapma da göremezsin."},{"n":44,"t":"Şimdi onlar hiç yeryüzünde dolaşıp da, kendilerinden öncekilerin nasıl bir akıbete uğradığını görmediler mi? Oysa ki onların gücü bunlardan daha üstündü. Nitekim ne göklerde ne de yerde, hiçbir şeyin Allah`ı aciz bırakma imkan ve ihtimali yoktur: çünkü O her şeyi bilir, üstün ve yüce kudret sahibidir."},{"n":45,"t":"Eğer Allah insanları yapıp ettikleri yüzünden (hemen) hesaba çekecek olsaydı, yer üzerinde bir tek canlı (insan) bırakmazdı; ama onları sonu yasayla belirlenmiş bir süreye kadar erteliyor; fakat süreleri dolunca artık anlarlar ki, Allah kullarını her daim görüp gözetmektedir."}],[{"n":1,"t":"Ey insan!"},{"n":2,"t":"Hikmetle (muhatabını inşa eden) bu Kur`an`a andolsun"},{"n":3,"t":"ki sen elbette gönderilen elçilerden birisin."},{"n":4,"t":"Dosdoğru bir yol üzeresin."},{"n":5,"t":"(Çünkü bu vahiy) her işinde mükemmel olanın, en merhametli olanın katından indirilmiştir:"},{"n":6,"t":"bu sayede ataları uyarılmamış, dolayısıyla haktan gafil kalmış bir topluluğu uyarabilesin."},{"n":7,"t":"Doğrusu, onlardan bir çoğu hakkındaki söz tahakkuk etmiştir: artık asla iman etmeyecekler."},{"n":8,"t":"Zira (sanki) Biz onların boyunlarına, çenelerine kadar uzanan demir halkalar geçirmişizdir de, başlarını bir türlü eğememektedirler."},{"n":9,"t":"Yine (adeta) önlerinden ve arkalarından birer set çekmiş ve gözlerini perdelemişizdir de, artık görememektedirler."},{"n":10,"t":"Şu halde sen onları uyarsan da, uyarmasan da onlar için fark etmez: iman etmezler."},{"n":11,"t":"Ne ki sen, sadece ilahi uyarıya tabi olan ve idraki aşan bir hakikat olmasına rağmen O rahmet kaynağına derin bir ürpertiyle saygı duyan kimseyi uyarabilirsin: o halde bu gibileri sınırsız bir mağfiret ve tarifsiz güzellikte bir ödülle müjdele!"},{"n":12,"t":"Elbette Biz, evet ölüyü Biz dirilteceğiz; ve onların önden yolladıklarını da arkada bıraktıkları eserleri de Biz yazacağız: böylece her şeyi kaydeden tarifsiz ve çok gelişmiş bir ana (bellek)te kayıt altına almış oluruz."},{"n":13,"t":"Onlara, kendilerine elçiler gönderdiğimiz şehir halkının hikayesini anlat."},{"n":14,"t":"Bir zamanlar onlara iki elçi göndermiştik; ama ikisini de yalanladılar. Bunun üzerine (onları) bir üçüncüyle destekledik; ve onlar dediler ki: \"Biz size gönderilmiş elçileriz.\""},{"n":15,"t":"(Şehir halkı) dediler ki: \"Siz sadece bizim gibi beşer türüne mensupsunuz. O rahmet kaynağı da hiçbir şey indirmemiştir: siz sadece yalan söylüyorsunuz!\""},{"n":16,"t":"(Elçiler) dediler ki: \"Rabbimiz biliyor ki biz size gönderilmiş elçileriz."},{"n":17,"t":"Ve biz size açıkça tebliğ etmekten başka bir şeyle mükellef değiliz.\""},{"n":18,"t":"(Şehir halkı) dediler ki: \"Şüphesiz bize uğursuzluk getirdiniz. Eğer buna bir son vermezseniz, sizi öldüresiye taşa tutar ve sizi keyfimizce şiddetli bir biçimde cezalandırırız.\""},{"n":19,"t":"(Elçiler dediler ki: \"Uğurunuz/uğursuzluğunuz size bağlıdır. Ne yani, size öğüt verildi diye mi (böyle oldu)? Hayır, asıl siz haddi aşmış bir toplumsunuz.\""},{"n":20,"t":"Derken şehrin en uzağından bir adam koşarak gelip \"Ey kavmim\" dedi, \"Elçilere uyun!"},{"n":21,"t":"Uyun sizden hiçbir karşılık beklemeyen bu kimselere; zira bunlar doğru yoldadırlar!"},{"n":22,"t":"Hem ben, beni yaratana, dahası hepinizin huzuruna varacağı O Zata neden kulluk etmeyecek mişim?"},{"n":23,"t":"Onu bırakıp da başka ilahlar edineyim, öyle mi? Eğer rahman bir zarar vermeyi dileyecek olsa (-ki dilemediği açık-), ne onlar bana zerre kadar şefaat edebilir, ne de beni kurtarabilirler."},{"n":24,"t":"Elbet o zaman ben, apaçık bir sapıklığa düşmüş olurum."},{"n":25,"t":"İşte artık ben sizin de Rabbiniz olana iman etmiş bulunuyorum: artık beni dinleyin!\""},{"n":26,"t":"(En sonunda) ona \"Sen cennetliksin!\" denildi. Dedi ki: \"Ah, keşke kavmim bir bilseydi."},{"n":27,"t":"Rabbimin beni bağışladığını ve beni ilahi ikrama mazhar olan kimseler arasına kattığını!..\""},{"n":28,"t":"Ve onun ardından kavminin üzerine gökten bir ordu indirmedik; zaten Biz daha önce de asla indirmiş değiliz:"},{"n":29,"t":"eğer bu gerekseydi, tek bir çığlık yeterli olurdu; o zaman da onlar sönmüş köz gibi kararıp küle dönerlerdi."},{"n":30,"t":"Ah yazıklar olsun şu kullara ki! Ne zaman kendilerine bir elçi gelmişse onu alaya aldılar!"},{"n":31,"t":"Onlardan önce nice nesilleri helak ettiğimizi görmezler mi? Ki onlar kendilerine dönüp gelemeyecekler;"},{"n":32,"t":"ama elbet hepsi Bizim huzurumuzda toplanacaklar."},{"n":33,"t":"Ölü toprakta dahi onlar için bir ders vardır: Onu Biz dirilttik, beslenmeleri için ondan tohumları Biz çıkardık."},{"n":34,"t":"Orada hurmalıkları ve üzüm bağlarını Biz var ettik; yine orada su gözelerini Biz çağlattık;"},{"n":35,"t":"ki onunla yetişenlerin ve elleriyle ektiklerinin ürünlerinden yiyebilsinler. Hala şükretmeyeceksiniz, öyle mi?"},{"n":36,"t":"Şanı ne yücedir O`nun ki, yeryüzünün tüm bitkilerini, insanların bizzat kendilerini ve hakkında henüz hiçbir bilgiye sahip olmadıkları şeyleri çifter çifter O yarattı."},{"n":37,"t":"Gecede de onlar için bir ders vardır: Biz ondan gündüzün ışığını çekip alırız da, onlar aniden karanlıkta kalakalır."},{"n":38,"t":"Güneşte de (bir ders vardır): o kendisi için tayin edilen mekan ve zamana bağlı olarak hareket eder durur; işte bu, en yüce olanın, her şeyi bilenin takdiridir."},{"n":39,"t":"Aya da sonunda kuru ve eğri bir hurma dalı haline gelinceye kadar farklı evreler takdir ettik:"},{"n":40,"t":"ne güneş aya kavuşup çarpabilir ne de gece gündüzü örtebilir: zira hepsi bir yörüngede hareket edip dururlar."},{"n":41,"t":"Bizim onların nesillerini dolu gemilerde taşımamızda da onlar için bir ders vardır;"},{"n":42,"t":"ve onları, benzer nitelikte taşıma araçları (yapacak kabileyette) yaratmamızda da..."},{"n":43,"t":"Dilersek onları suda boğabiliriz; bu takdirde imdatlarına kimse yetişemez ve onlar kurtarılamazlar da;"},{"n":44,"t":"sadece katımızdan bir rahmet ve geçici bir mühlet tanımamız sayesinde yaşayabilirler."},{"n":45,"t":"Kendilerine \"Sizi bekleyen (ahiret) ve geride bıraktığınız (hayattan) dolayı sorumluluktan titreyin ki, ilahi merhamete mazhar olabilesiniz\" denildiğinde (yüz çevirdiler):"},{"n":46,"t":"zira onlara Rablerinden ne zaman bir mesaj ulaşmışsa, her seferinde ondan yüz çevirmişlerdir."},{"n":47,"t":"Kendilerine \"Allah`ın size verdiği servetten (Allah yoluna) cömertçe sarf edin\" denildiğinde, inkarda ısrar edenler imanda sebat gösterenlere \"Ne yani, Allah`ın isterse pekala doyuracağı kimseyi biz mi doyuralım? Şimdi siz açık bir şaşkınlık içinde değil de nesiniz!\" derler."},{"n":48,"t":"Bir de derler ki: \"Eğer sözünüze sadıksanız söyleyin bakalım şu vaat ettiğiniz (Son Saat) ne zaman gerçekleşecek?\""},{"n":49,"t":"Onlar (bunu) tartışırken, kendilerini enselenecekleri bir tek bela çığlığından başka bir şey beklemeyecek:"},{"n":50,"t":"her şey o kadar ani olacak ki; ne vasiyet edebilecekler, ne de yakınlarına dönebilecekler."},{"n":51,"t":"Derken sura üflenmiştir, ve işte o zaman hemen mevzilerinden çıkıp Rablerine koşacaklar."},{"n":52,"t":"\"Eyvah! Bizi yattığımız yerden kim kaldırdı?\" diyecek (ve cevabı kendileri verecek)ler: \"Rahman`ın vaad ettiği bu olsa gerek; demek ki gönderilen elçiler doğru söylemişler!\""},{"n":53,"t":"Sadece bir tek bela çığlığı: olan bitenin hepsi bu! Ve hemen ardından herkes huzurumuzda boy gösterecek."},{"n":54,"t":"Artık bugün hiçbir kimseye zerre kadar haksızlık yapılmayacak ve sadece yaptıklarınızdan sorumlu tutulacaksınız."},{"n":55,"t":"Elbet cennet ehli o gün, keyif veren bir meşguliyet içinde olacak;"},{"n":56,"t":"onlar ve eşleri (bu huzurun) gölgesi altında mükemmel yataklar üzerinde uzanacaklar;"},{"n":57,"t":"orada her tür refaha sahip olacaklar ve arzuladıkları her şey onlara sunulacak."},{"n":58,"t":"rahmeti sonsuz Rabbinin sözüyle gelen tarifsiz bir mutluluktur bu."},{"n":59,"t":"Ama (suçlulara denilir ki): \"Siz ey mücrimler, bugün şöyle ayrı durun!\""},{"n":60,"t":"İmdi, Ben size buyurmadım mı ey Ademoğulları: \"Şeytana kulluk etmeyin, çünkü o sizin apaçık düşmanınızdır!"},{"n":61,"t":"Ve yalnız Bana kulluk edin, dosdoğru yol budur!"},{"n":62,"t":"Doğrusu (o Şeytan) sizden bir çok nesli yoldan çıkarmıştır; o zaman aklınız başınızda değil miydi?"},{"n":63,"t":"İşte, size vaad edilen cehennem budur."},{"n":64,"t":"Israrla inkar etmenizin bir sonucu olarak bugün oraya destek verin!\""},{"n":65,"t":"O gün ağızlarına mühür vururuz; ve Bize onların elleri konuşur, ayakları yaptıklarına şahitlik eder."},{"n":66,"t":"Eğer (Ademoğlu`nu iradesiz yaratmak) isteseydik, onların görüp kavrama yeteneklerini iyice köreltirdik de (hayvanlar gibi) yoldan (çıkmak için) yarışırlardı. O takdirde (doğruyu) nereden, nasıl görebileceklerdi?"},{"n":67,"t":"Eğer (böyle olmalarını) dileseydik, mutlaka onları kendi konumlarına göre başka bir hale dönüştürürdük. O takdirde ne savuşturabilirler ne de geri dönebilirlerdi."},{"n":68,"t":"Ve kimin ömrünü uzatırsak, onun doğuştan gelen yeteneklerinde eksiltme yaparız: hala akıllarını kullanmayacaklar mı?"},{"n":69,"t":"Biz ona şiir öğretmedik; bu onun için gerekli de değil: o (vahiy) sadece bir uyarı ve öğüttür; dahası açık ve açıklayıcı bir hitaptır;"},{"n":70,"t":"ki bu sayede, (kalben) diri olanları uyarsın ve bunu ısrarla inkar edenlere karşı verilmiş söz gerçekleşsin."},{"n":71,"t":"Şimdi onlar, kendileri için kudretimizin bir nişanesi olarak evcil hayvanlar yarattığımızı ve bu sayede onlara sahip olabildiklerini de mi görmezler?"},{"n":72,"t":"Dahası onları emirlerine amade kıldık ki, bir kısmına binsinler, bir kısmını da yesinler;"},{"n":73,"t":"ve onlardan başkaca da yararlansınlar ve içecek (süt) sağsınlar. Hala şükretmeyecekler mi?"},{"n":74,"t":"Ne ki onlar (şükür yerine), kendilerine yardım ederler ümidiyle Allah`tan başka ilahlar edindiler."},{"n":75,"t":"Bunların onlara yardıma asla güçleri yetmez; aksine kendileri bunlar için hazır kıta askerdirler."},{"n":76,"t":"Artık onların sözleri seni üzmesin: unutma ki Biz onların gizlediklerini de biliriz, açıkladıklarını da."},{"n":77,"t":"İnsan görmez mi ki, Biz kendisini bir damlacık hayat suyundan yarattık (ve akıl fikir bahşettik), fakat o apaçık bir hasım olup çıktı."},{"n":78,"t":"Bir yandan Bizim için benzerler düzüp koşarken, öte yandan kendisinin (bir damlacık sudan) yaratılışını unutarak şöyle der: \"Çürüyüp toza toprağa karışmış kemiklere kim hayat verecek?\""},{"n":79,"t":"De ki: \"Onları ilk defa kim yoktan var ettiyse O hayat verecek. Zira O, her tür yaratığın ve yaratmanın akıl sır ermez bilgisine bütünüyle vakıftır."},{"n":80,"t":"O`dur yeşil ağaçta sizin için ateş var eden; bu sayede sizler ondan yakacak elde edersiniz."},{"n":81,"t":"Değil mi ama; gökleri ve yeri yaratan Allah`ın kudreti, onlar gibisini (yeniden) yaratmaya yetmez mi? Elbette yeter! Zira O, her şeyi bilen mükemmel bir Yaratıcıdır."},{"n":82,"t":"O, eşsiz yaratışıyla bir şeyin olmasını dilediği zaman, sadece ona \"Ol!\" demesi yeter: o da hemen oluş sürecine girer."},{"n":83,"t":"Her şeyin tasarrufunu (kudret) elinde bulunduran (Allah), her tür kişileştirmeden uzak ve yücedir: nihayet hepiniz O`na döndürüleceksiniz."}],[{"n":1,"t":"Şahit olsun sıra sıra dizenler ve dizilenler,"},{"n":2,"t":"Vazgeçirip set çekenler,"},{"n":3,"t":"Uyarmak için peşpeşe gelenler..."},{"n":4,"t":"Elbet, ilahınızın bir tek olduğunda şüphe yoktur;"},{"n":5,"t":"göklerin, yerin ve onların arasındaki her şeylerin Rabbi; ve bütün doğuların Rabbi."},{"n":6,"t":"Şüphesiz Biz, yerin en yakın göğünü yıldızların güzelliğiyle süsledik;"},{"n":7,"t":"üstelik (onları) her isyankar Şeytanın tasallutundan koruduk,"},{"n":8,"t":"ki yüce katın sakinlerini dinleme (girişiminde) bulunamasınlar ve her yandan yüz geri edilsinler;"},{"n":9,"t":"(dünyada) dışlansınlar ve (ahirette de) sürekli bir azaba mahkum olsunlar;"},{"n":10,"t":"ancak bir (bilgi) kırıntısı kapanlar olursa, onlar da delik deşik eden bir ateş korunun pençesine düşsünler."},{"n":11,"t":"Onlardan şu sorunun cevabını iste: \"Kendileri yaratılışça (takdir ettiğimizden) daha üstün ve güçlü müdürler, yoksa Bizim yarattığımız (ve çok iyi bildiğimiz Şeytansı) birileri midir? Açık gerçek şu ki, onları konsantre bir balçık türünden yaratan Biziz."},{"n":12,"t":"Ama hayır, sen hayranlık ve şaşkınlık duyarken, onlar işin şakasındalar;"},{"n":13,"t":"hatırlatıldığı zaman da öğüt almazlar;"},{"n":14,"t":"ve bir ayet gördüklerinde küçümsemeye kalkarlar;"},{"n":15,"t":"ve derler ki: \"Açıkca bu, büyü(leyici söz)den başka bir şey değil:"},{"n":16,"t":"ne yani, biz ölüp gittikten, toza toprağa karışmış bir iskelet halini aldıktan sonra tekrar mı diriltileceğiz?"},{"n":17,"t":"Yani, önden giden atalarımız da mı?\""},{"n":18,"t":"\"Evet\" de, \"Hem de rezil rüsva bir halde!\""},{"n":19,"t":"Nitekim o (gün) bir tek sarsıcı komut yankılanır: ve işte o an onlar bön bön bakakalır;"},{"n":20,"t":"ve \"Eyvah! Bu, işte o Hesap Günü budur!\" derler."},{"n":21,"t":"İşte bu, yalanlayıp durduğunuz (iyi ile kötünün) arasını ayırma günüdür:"},{"n":22,"t":"Toplayın bütün o zalimleri, onların türdeşlerini ve kulluk ettikleri her şeyi!"},{"n":23,"t":"Allah`tan başka her şeyi... Ve hepsini gözleri fal taşı gibi açacak bir ateşe yönlendirin;"},{"n":24,"t":"ve onları orada alıkoyun: çünkü onlar sorgulanacaklar!"},{"n":25,"t":"(Denilecek ki): \"Ne oldu, neden birbirinize yardım etmiyorsunuz?\""},{"n":26,"t":"Ama hayır, onlar o gün Allah`a ister istemez teslim olacaklar."},{"n":27,"t":"Ve birbirlerine yönelerek başlayacaklar hesap sormaya..."},{"n":28,"t":"(Bir kısmı) şöyle diyecek: \"Siz bize hep suret-i haktan görünerek yanaşırdınız.\""},{"n":29,"t":"(Diğerleri) \"Asla\" diyecekler, \"Siz zaten hiç inanmamıştınız!"},{"n":30,"t":"Hem bizim sizi zorlayacak bir gücümüz de yoktur: bilakis siz küstah ve azgın bir topluluktunuz!"},{"n":31,"t":"Fakat şimdi Rabbimizin sözü hepimizin aleyhine gerçekleşti: hepimiz (yaptıklarımızın) acısını elbette tadacağız."},{"n":32,"t":"Fakat biz sizi (aldatmadık), açıkca saptırdık; çünkü biz zaten sapıtmış kimselerdik."},{"n":33,"t":"Şu halde onlar o gün azapta da ortak olacaklar;"},{"n":34,"t":"çünkü Biz suçu tabiat haline getirenlere işte böyle davranacağız."},{"n":35,"t":"Şu bir gerçek ki, ne zaman kendilerine \"Allah`tan başka ilah yoktur\" denilmişse, mutlaka küstahça kibirlenmişler"},{"n":36,"t":"ve \"Ne yani, şimdi kalkıp da mecnun bir şairin sözüne uyup ilahlarımızı mı terk edelim?\" demişlerdir."},{"n":37,"t":"Hayır! Bilakis o, hakikati getirmiş ve (önceki) elçileri tasdik etmiştir."},{"n":38,"t":"Şu kesin ki siz, acıklı bir azabı hak ettiniz;"},{"n":39,"t":"ve yaptıklarınızın dışında bir şeyle cezalandırılmayacaksınız."},{"n":40,"t":"Ancak, imanını saf ve temiz tutma çabalarını Allah`ın desteklediği kulları hariç:"},{"n":41,"t":"işte onlar için (ahirette) belirlenmiş bir rızık vardır;"},{"n":42,"t":"lezzet kaynağı her tür ürün... Zira onlar (tarifsiz bir) ikrama mazhar olacaklar;"},{"n":43,"t":"nimetlerle tıka basa dolu olan cennetlerde;"},{"n":44,"t":"muhteşem tahtlarda birbirlerini sevgi dolu gözlerle süzerek..."},{"n":45,"t":"Aralarında kaynağından doldurulmuş kadehlerle kendilerine servis yapılacak;"},{"n":46,"t":"içenlere tarifsiz bir lezzet veren berraklıkta olacak;"},{"n":47,"t":"ne zahmet verecek ne de sarhoş edecek;"},{"n":48,"t":"ve yanlarında gözü dışarıda olmayan tatlı bakışlı eşler;"},{"n":49,"t":"sanki kumda gizlenmiş deve kuşu yumurtaları gibi kusursuz..."},{"n":50,"t":"İşte onlar da (berikiler gibi) birbirlerine yönelerek sualler soracaklar."},{"n":51,"t":"İçlerinden biri diyecek ki: \"Bir zamanlar benim bir arkadaşım vardı;"},{"n":52,"t":"bana, \"Sahi, sen gerçekten de onun doğruluğunu tasdik mi ediyorsun?\" derdi;"},{"n":53,"t":"\"Ne yani, biz ölüp gittikten, toza toprağa karışmış bir iskelet halini aldıktan sonra hesap vereceğiz, öyle mi?\" (diye eklerdi)."},{"n":54,"t":"(Sözüne devamla) sordu: \"Onun halini görmek ister misin?\""},{"n":55,"t":"Bunun üzerine bakar ve onu dehşet verici bir ateşin göbeğinde görür."},{"n":56,"t":"\"Aman Allah`ım!\" der, \"Az kalsın beni mahvedecektin!"},{"n":57,"t":"Eğer Rabbimin yardımı olmasaydı, ben de burada tutulanlardan olmuştum!"},{"n":58,"t":"(Cennet arkadaşlarına yönelerek): \"Biz bir daha asla ölmeyeceğiz, değil mi?"},{"n":59,"t":"(Ölüm) sadece şu ilk ölümümüzdü; ve biz artık asla azaba uğratılmayacağız (değil mi)?"},{"n":60,"t":"Hiç kuşkusuz budur o çok büyük kazanç, o çok büyük başarı."},{"n":61,"t":"İnsan, bir kazanç, bir başarı için çalışacaksa, ancak böyle bir kazanç ve başarı için çalışmalı."},{"n":62,"t":"Şimdi konuğu böyle ağırlamak mı iyidir, yoksa zehir zakkumla (ağırlamak) mı?"},{"n":63,"t":"Şüphe yok ki Biz onu zalimler için bir imtihan vesilesi kıldık."},{"n":64,"t":"Elbet o cehennemin ta orta yerinde yetişen bir ağaçtır;"},{"n":65,"t":"tomurcukları, yeleli yılanların başları gibi (albenili)dir;"},{"n":66,"t":"ve onlar kesinlikle ondan yemeye ve karınlarını onunla tıka basa doldurmaya mecburdurlar;"},{"n":67,"t":"sonra, onun üstüne bir de yürek dağlayıp iç kaldıran bir kokteyl yudumlayacaklar;"},{"n":68,"t":"neticede son durakları, elbet gözleri faltaşı gibi açan ateş olacaktır."},{"n":69,"t":"Çünkü onlar sapık atalarının başlarına sardığı geleneği izlediler;"},{"n":70,"t":"fakat kendileri atalarının izinden akılsızca seğirtiyorlar!"},{"n":71,"t":"Doğrusu, onlardan öncekilerin çoğu da sapmıştı."},{"n":72,"t":"Ve elbette onların arasına da uyarıcılar göndermiştik:"},{"n":73,"t":"dön de bir bak şu uyarılmış olanların akıbeti nasılmış?"},{"n":74,"t":"Bunun tek istisnası var: imanını saf ve temiz tutma çabalarını Allah`ın desteklediği samimi kullar!"},{"n":75,"t":"Doğrusu, (onlardan biri olan) Nuh da bizden imdat dilemişti; ve onun imdadına derhal yetişmemiz de güzeldi:"},{"n":76,"t":"zira onu ve (inanç) ailesini büyük bir badireden kurtarmıştık;"},{"n":77,"t":"onun (inanç) soyunu da baki kıldık:"},{"n":78,"t":"geriden gelenlerin zihninde ona dair (örnek) bir hatıra bıraktık:"},{"n":79,"t":"Bütün milletler arasında Nuh`a selam olsun!"},{"n":80,"t":"Elbet Biz, iyi olup güzel davrananları işte böyle ödüllendiririz;"},{"n":81,"t":"çünkü o, Bizim gerçek iman sahibi kullarımızdandı;"},{"n":82,"t":"nihayet (inkarda direnen) diğerlerini boğulmaya terk ettik."},{"n":83,"t":"Ve onun tarafında saf tutanlardan biri de elbet İbrahim idi:"},{"n":84,"t":"Hani o Rabbine arı duru bir kalp ile yönelmişti;"},{"n":85,"t":"o zaman babasına ve kavmine şöyle demişti: \"Sizler nelere tapıyorsunuz böyle?"},{"n":86,"t":"Ne yani! Allah`ı bırakıp da uyduruk ilahlara tapmakta ısrar mı ediyorsunuz?"},{"n":87,"t":"Sahi siz, alemlerin Rabbini ne zannediyorsunuz?\""},{"n":88,"t":"Ardından yıldızlara bir göz attı"},{"n":89,"t":"ve \"Ben rahatsızım!\" dedi."},{"n":90,"t":"Bunun üzerine etrafındakiler, ondan yüz çevirip gittiler."},{"n":91,"t":"Derken o, onların putlarına usulca yaklaştı ve \"Ne! Yoksa (önünüze konulanlardan) yemiyor musunuz?\" dedi (ve ekledi):"},{"n":92,"t":"\"Size ne oldu böyle, yoksa konuşamıyor musunuz?\""},{"n":93,"t":"Ve onların üzerine abanıp bütün gücüyle vurmaya başladı."},{"n":94,"t":"Derken etraftan koşarak başına üşüştüler."},{"n":95,"t":"O dedi ki: \"Elinizle yonttuklarınıza mı tapıyorsunuz?"},{"n":96,"t":"Oysa sizi de yonttuklarınızı da yaratan Allah`tır.\""},{"n":97,"t":"Onlar \"Onu (yakmak) için bir yapı yapın ve onu çılgınca yanan ateşin ortasına atın!\" dediler."},{"n":98,"t":"Böylece ona zarar vermek istediler, ama biz onları rezil ettik."},{"n":99,"t":"Ve (İbrahim), \"Ben Rabbime (kulluk edebileceğim bir yere) gideceğim, O bana yol gösterecektir\" diyerek (şöyle yalvardı):"},{"n":100,"t":"\"Rabbim! Bana erdemli bir (evlat) bağışla!\""},{"n":101,"t":"Bunun üzerine ona uyumlu ve olgun bir oğlan çocuğu müjdeledik."},{"n":102,"t":"Derken çocuk onun çaba ve tasasına ortak olacak olgunluğa eriştiğinde, (İbrahim) şöyle dedi: \"Yavrucuğum! Kendimi rüyada seni kurban ederken görüyorum; bir bak bakalım, sen bu işe ne dersin?\" (Oğul) \"Babacığım!\" dedi, \"Sana emredileni yap; inşaallah beni sabredenlerden bulacaksın.\""},{"n":103,"t":"Sonunda o ikisi Allah`a teslimiyetlerinin bir gereği olarak (vardıkları sonuca) uydular ve (babası) onu yüzüstü yatırınca,"},{"n":104,"t":"Biz kendisine \"Ey İbrahim!\" diye seslendik:"},{"n":105,"t":"\"Artık rüyanı gerçekleştirmiş bulunuyorsun!\" Nitekim Biz, iyilik yapanları işte böyle ödüllendiririz."},{"n":106,"t":"Hiç şüphesiz bu, elbet apaçık bir sınavdı."},{"n":107,"t":"Ve Biz ona fidye olarak muhteşem bir kurban verdik;"},{"n":108,"t":"geriden gelen herkesin zihninde ona ilişkin (örnek) bir hatıra bıraktık:"},{"n":109,"t":"Selam olsun İbrahim`e!"},{"n":110,"t":"İyileri Biz, işte böyle ödüllendiririz."},{"n":111,"t":"Zira o, Bizim gerçek mü`min kullarımızdan biriydi."},{"n":112,"t":"Bir de ona kendisi salih kullardan biri olan bir peygamberi, İshak`ı müjdeledik;"},{"n":113,"t":"dahası onu ve İshak`ı mübarek kıldık: ama o ikisinin soyundan dürüst ve erdemli olan da var, kendisine açıkça zulmeden de."},{"n":114,"t":"Doğrusu Biz Musa`ya ve Harun`a da lütufta bulunmuştuk:"},{"n":115,"t":"o ikisini ve onların kavmini büyük bir musibetten kurtarmıştık;"},{"n":116,"t":"ve kendilerine yardım etmiştik de, sonunda galip gelen onlar olmuştu."},{"n":117,"t":"Onlara (hakkı batıldan seçip ayıran kitabı vermiş"},{"n":118,"t":"ve o ikisini dosdoğru yola yöneltmiştik."},{"n":119,"t":"Nihayet geriden gelen herkesin zihninde o ikisine ilişkin (örnek) bir hatıra bıraktık:"},{"n":120,"t":"Selam olsun Musa ve Harun`a!"},{"n":121,"t":"İyileri Biz işte böyle ödüllendiririz."},{"n":122,"t":"Zira onlar, Bizim gerçek mü`min kullarımız arasındaydılar."},{"n":123,"t":"Şüphe yok ki İlyas da elçilerden biriydi."},{"n":124,"t":"Hani kavmine demişti ki: \"Ne o, sorumluluğunuzu idrak etmemekte direnecek misiniz?"},{"n":125,"t":"Ba`le (put Tanrı) ya yalvarıp yakararak, Sanatkarların Mükemmelini göz ardı edeceksiniz, öyle mi;"},{"n":126,"t":"Allah`ı, hem sizin hem de önden giden atalarınızın Rabbi olanı?"},{"n":127,"t":"Derken onu da yalanladılar; bu yüzden onlar elbette yargılanacaklar."},{"n":128,"t":"Ancak, Allah`ın inancını saf ve temiz tutma çabasını desteklediği samimi kullar hariç."},{"n":129,"t":"Ve geriden gelen herkesin zihninde ona ilişkin (örnek) bir hatıra bıraktık:"},{"n":130,"t":"Selam olsun İlyas ve onun takipçilerine!"},{"n":131,"t":"İyileri Biz, işte böyle ödüllendiririz."},{"n":132,"t":"Zira onlar, Bizim gerçek mü`min kullarımız arasındaydılar."},{"n":133,"t":"Şüphe yok ki Lut da elçilerden biriydi."},{"n":134,"t":"(Kavmi helak) olduğu zaman, onu ve (inanç) ailesini toptan kurtarmıştık;"},{"n":135,"t":"geride kalıp toz olmayı tercih eden yaşlı bir kadın dışında,"},{"n":136,"t":"En sonunda, diğerlerinin tamamını kahrettik;"},{"n":137,"t":"ve siz onların mekanlarından gelip geçmektesiniz; her sabah"},{"n":138,"t":"ve her akşam... Hala aklınızı kullanmayacak mısınız?"},{"n":139,"t":"Şüphe yok ki Yunus da elçilerden biriydi."},{"n":140,"t":"Hani o efendisinden kaçan bir köle gibi ağzına kadar dolu bir gemiyle kaçmıştı."},{"n":141,"t":"Bunun ardından kur`a çekilmiş ve hayatı kayıp (denize atılmıştı)."},{"n":142,"t":"Derken o derin bir pişmanlıkla kıvranır haldeyken iri balık tarafından yakalanmıştı."},{"n":143,"t":"Fakat o eğer Rabbinin yüceliğini sürekli hatırda tutan biri olmasaydı,"},{"n":144,"t":"yeniden diriliş gününe kadar onun karnında olacaktı."},{"n":145,"t":"Sonunda Biz onu bitkin bir halde ıssız ve çorak bir kıyıya çıkarttık;"},{"n":146,"t":"ve onun başucunda bodur ve bol hevenkli bir bitki yeşerttik."},{"n":147,"t":"Yine onu yüz bin, hatta daha fazla kişiye (yeniden) elçi gönderdik."},{"n":148,"t":"Bu kez onlar iman ettiler; bu yüzden Biz de onlara bir müddet müreffeh bir hayat yaşattık."},{"n":149,"t":"İmdi onlardan şu sorunun cevabını iste: \"Senin Rabbinin payına yalnızca kızlar onlara da oğullar düştü, öyle mi?"},{"n":150,"t":"Yoksa melekleri dişiler olarak yarattık da, buna onlar mı tanık oldular?\""},{"n":151,"t":"Bakın, işte bu tiplerin iftiraya düşkünlüklerinden dolayı ısrarla dedikleri şudur:"},{"n":152,"t":"\"Allah doğurdu!\" Onlar var ya onlar, kesinlikle yalan söylüyorlar."},{"n":153,"t":"Sahi, O kızları oğlanlara tercih mi etmiş?"},{"n":154,"t":"Ne oluyor size, nasıl böyle hüküm verebiliyorsunuz?"},{"n":155,"t":"Hiç mi düşünmüyorsunuz?"},{"n":156,"t":"Yoksa elinize apaçık bir belge mi geçti?"},{"n":157,"t":"Eğer doğru söylüyorsanız, haydi (varsa) kendi kitabınızı getirin!"},{"n":158,"t":"Bir de O`nunla görünmez ve ruhani varlıklar arasında bir soy bağı vehmettiler, oysa bu görünmez ve ruhani varlıklar da bilirler ki, onlar kesinlikle yargılanacaklar."},{"n":159,"t":"Yüceler yücesi olan Allah, onların her türlü tasavvur ve tanımlarının çok çok ötesindedir."},{"n":160,"t":"Ancak, inancını saf ve temiz tutma çabasını Allah`ın desteklediği samimi kulları böyle yapmazlar:"},{"n":161,"t":"çünkü ne siz, ne de taptıklarınız;"},{"n":162,"t":"Allah hakkında kimsenin sapmasına sebep olabilecek değilsiniz;"},{"n":163,"t":"ancak (göz göre göre) ateşe koşan kimseler hariç."},{"n":164,"t":"Hem, (samimi kullar derler) ki: \"İçimizde, (Allah tarafından) kendisine bir yer tayin edilmemiş hiç kimse yoktur:"},{"n":165,"t":"evet biziz (emre amade olup) saf saf duranlar, elbette biz;"},{"n":166,"t":"yine biziz (O`nun) yüceliğini dile getirenler, elbet biz!\""},{"n":167,"t":"Ama bir de ısrarla şöyle diyenler var:"},{"n":168,"t":"Eğer geçmiş atalarımızdan bize tevarüs edilen ilahi bir uyarı devralmış olsaydık,"},{"n":169,"t":"elbet biz de imanını saf ve temiz tutma çabasını Allah`ın desteklediği halis kullarından olurduk!\""},{"n":170,"t":"Fakat (vahiy gelince de) onu inkar ettiler; ama zamanı gelince (ne fena yaptıklarını) bilecekler."},{"n":171,"t":"Ama doğrusu, has kullarımız olan elçilerimize geçmişte verilmiş bir sözümüz vardı."},{"n":172,"t":"mutlaka kendileri yardıma mazhar olacaklar;"},{"n":173,"t":"elbet sonunda galip gelecek olan da Bizim ordumuz olacaktır."},{"n":174,"t":"Bu yüzden artık onlardan bir süreliğine uzak dur;"},{"n":175,"t":"ve sen onları(n zavallı halini) gör, zamanı gelince onlar da (kendi perişan hallerini) görecekler."},{"n":176,"t":"Sahiden de, onlar azabımızın bir an önce gelmesini (gerçekten) istiyorlar mı?"},{"n":177,"t":"Fakat o aniden kendi mekanlarında başlarına indiğinde, uyarılanlar berbat bir sabaha uyanmış olacaklar."},{"n":178,"t":"Yine de sen onlardan bir süreliğine uzak dur;"},{"n":179,"t":"ve sen gözetle; onlar da yakında (günlerini) görecekler."},{"n":180,"t":"İzzet ve azamet sahibi Rabbin, insanların idrak evrenlerinin çok ötesinde aşkın bir yüceliğe sahiptir."},{"n":181,"t":"O`nun bütün elçilerine selam olsun!"},{"n":182,"t":"Ve alemlerin Rabbine hamdolsun!"}],[{"n":1,"t":"Sad! Şeref ve itibar kaynağı olan Kur`an şahit olsun!"},{"n":2,"t":"Ama nerde! İnkarda direnenler (akletmek yerine) yersiz bir gurura ve tarifsiz bir nefrete gömülmüşlerdir."},{"n":3,"t":"Kendilerinden önce nice kuşakları helak ettik; tam bu sırada imdat dilediler, fakat kurtuluşun vakti çoktan geçmişti."},{"n":4,"t":"Ve onlar aralarından birinin kendilerine uyarıcı olarak gelmesine şaştılar; işte bu kafirler şöyle dediler: \"Bu, göz boyamak isteyen yalancının biri."},{"n":5,"t":"Bütün bu ilahları tek bir ilaha indirgiyor ha? Bunun çok tuhaf bir görüş olduğunda hiç şüphe yok.\""},{"n":6,"t":"İçlerinden o hey`et de fırladı şöyle: ilâhlarınız üzerinde sabr-u sebat edin, bu cidden arzu olunur bir şey, bir murad"},{"n":7,"t":"Biz çağdaş inanç sistemlerinin hiç birinde bunu duymadık; bu desteksiz bir uydurmadan başkası değildir;"},{"n":8,"t":"ne yani, aramızdan ilahi mesajın indirileceği bir o mu kaldı?\" Ama hayır, onlar asıl Benim uyarıma karşı şüpheyle yaklaşıyorlar; dahası, belli ki onlar henüz azabımı tatmamışlar."},{"n":9,"t":"Yoksa, mutlak kudret ve lütuf sahibi Rabbinin rahmet hazinelerinin tasarrufu onların elinde mi?"},{"n":10,"t":"Yoksa göklerin, yerin ve bu ikisi arasındakilerin mülkiyeti onlara mı ait? Haydi o zaman, tüm araçlara sarılsınlar da, (göklerin tahtına) çıkıp kurulsunlar bakalım!"},{"n":11,"t":"Onlar, bozguna uğramış müttefiklerin döküntülerinden oluşmuş (başıbozuklar) ordusu..."},{"n":12,"t":"Onlardan önce Nuh ve Ad kavmi ve yüksek sütunlar sahibi Firavun da gerçeği yalanlamıştı;"},{"n":13,"t":"Semud ve Lut, Eyke ahalisi de öyle... Adı geçenler de (inkarda) müttefiktiler."},{"n":14,"t":"Hepsi de elçileri yalanladılar: Bu yüzden cezamızı hak ettiler."},{"n":15,"t":"Ve şu berikiler var ya; işte bunları bir tek bela çığlığı beklemektedir: ilave bir nefes bile alamazlar."},{"n":16,"t":"İşte onlar, \"Rabbimiz! Bizim hesabımızı Hesap Günü`nden önce, hemen şimdi kes!\" diye (alay ederler)."},{"n":17,"t":"Sen onların bu tür laflarına karşı dirençli ol ve güçlü bir kişiliğe sahip olan has kulumuz Davud`u hatırla! Çünkü o her daim Allah`a yönelirdi."},{"n":18,"t":"İşte bu yüzden, her sabah ve her akşam, onunla birlikte emrimize amade kıldığımız dağlar da kudret ve ihtişamımızı dillendirirdi;"},{"n":19,"t":"katar katar dizilmiş kuşlar da: bunların hepsi her daim O`na yönelmişlerdi!"},{"n":20,"t":"Biz de onun iktidarını sağlama aldık; zira ona adaletle hükmedecek muhakeme ve anlaşmazlıkları sona erdirecek yeteneği vermiştik."},{"n":21,"t":"Sen davacıların kıssasından haberdar oldun mu? Hani onlar mabedin inziva hücresinin (duvarına) tırmanmışlardı."},{"n":22,"t":"Yanına aniden girdiklerini görünce Davud onlardan dolayı telaşa kapıldı. Onlar \"Korkma!\" dediler, \"Biz (sadece) iki davalıyız; birimiz diğerinin hakkına tecavüz etti: şimdi sen aramızdan hakkaniyetle karar ver ve doğrudan ayrılma; bize de doğru yolu göster!"},{"n":23,"t":"İşte bu benim kardeşim; onun doksan dokuz koyunu var, benimse yalnızca bir tek koyunum; buna rağmen o, \"Onu da bana ver\" dedi ve dediğini zorla yaptırdı."},{"n":24,"t":"(Davud) dedi ki: \"Doğrusu bu kişi, senin koyununu alıp kendininkine katmakla sana zulmetmiş. Zaten toplumsal hayatı paylaşan insanlar (genellikle) birbirlerinin hakkına tecavüz ederler; iman edip dürüst ve erdemli davrananlar hariç: ama böyleleri, ne kadar da az. Derken Davut, bizim kendisini sınadığımızı fark etti; hemen Rabbinden af diledi ve baş eğip iki büklüm bir halde tevbe ederek O`na yöneldi."},{"n":25,"t":"Ve Biz de bu (hatasını) bağışladık: elbet onu, Bizim katımıza yakınlık ve güzel bir son beklemektedir."},{"n":26,"t":"(Ve nida ettik): \"Ey Davud! Elbet sana yeryüzünde iktidarı Biz verdik: O halde insanlar arasında adaletle hükmet, (kimsenin) heva ve arzusuna kapılma ki, sonra seni Allah yolundan saptırırlar. Şu kesin ki Allah yolundan sapan kimseler, Hesap Günü`nü unutmalarından dolayı şiddetli bir cezaya çarptırılırlar."},{"n":27,"t":"Ve Biz gökleri, yeri ve bunlar arasındakileri bir amaç ve anlamdan yoksun yaratmadık; bu, inkarda direnenlerin bakış açısıdır: yazıklar olsun (kendilerini mahkum ettikleri) ateşten dolayı inkarda direnen o kimselere!"},{"n":28,"t":"Yoksa iman eden ve ıslaha hizmet edenleri, yeryüzünde fesat çıkaranlarla bir mi tutsaydık? Yoksa sorumlu davrananları, sorumsuz sapıklarla bir mi tutsaydık?"},{"n":29,"t":"Sana müberek bir kitab olan bu (Kur`an`ı) Biz indirdik ki, herkes onun mesajları üzerinde iyice düşünsün de akıl izan sahipleri ders alsın diye."},{"n":30,"t":"Davud`a bir de Süleyman`ı bahşettik: o ne güzel kuldu; çünkü o sürekli Bize yönelirdi."},{"n":31,"t":"Hani, gün batımına doğru kendisine soylu ve favori atlar sunulmuştu da,"},{"n":32,"t":"\"Elbet ben güzel olan her şeyi severim\" demişti, \"çünkü bana Rabbimi hatırlatır!\" Ta ki (bunu) atlar gözden kayboluncaya kadar tekrarladı."},{"n":33,"t":"(Ardından) \"Onları bana getirin!\" (diyerek) başladı bacaklarını ve boyunlarını sıvazlamaya."},{"n":34,"t":"Doğrusu Biz Süleyman`ı, vaktiyle tahtının üzerine bir ceset koymakla sınamıştık; bunun ardından o da Bize yönelmiş (ve)"},{"n":35,"t":"\"Rabbim!\" demişti, \"Bana mağfiret eyle! Bana, benden sonra hiç kimsenin üstlenmeye layık olmadığı bir iktidar ver: çünkü Sen, evet Sensin cömertçe bahşeden!\""},{"n":36,"t":"Bunun ardından rüzgarı ona amade kıldık ki, onun emriyle (çalışan gemileri) istediği yöne doğru kolayca yüzdürebilsin;"},{"n":37,"t":"yine şeytanlar (gibi dik başlı) güçlerden, her biri birer yapı ustası ve dalgıç olan kimseleri de (ona amade kıldık);"},{"n":38,"t":"ve zincirlerle birbirine bağlanmış daha başkalarını da..."},{"n":39,"t":"(Ve ona şöyle dedik): \"İşte bu Bizim ikramımızdır; artık onu ister hiçbir hesap yapmadan karşılıksız ver, istersen elinde tut!\""},{"n":40,"t":"Elbet onu da, Bizim katımıza yakınlık ve güzel bir son beklemektedir."},{"n":41,"t":"Ve kulumuz Eyyub`u da hatırla: Hani o Rabbine \"(Rabbim!) Şeytan bana tarifsiz bir bezginlik ve terkedilmişlik hissi vermektedir!\" diye yakarmıştı."},{"n":42,"t":"(Biz de) \"Düş yola! Bak işte (şurada hem yıkanılacak hem de içilecek soğuk bir su var!\" (demiştik)."},{"n":43,"t":"Ona katımızdan bir rahmet ve akıl sahipleri için bir ibret olmak üzere, (kendisini terk eden) yakın çevresini ve onlarla beraber bir kat daha fazlasını bahşettik."},{"n":44,"t":"(Ve dedik ki): \"Eline bir deste al ve onunla vur! Böylece yemininden dönmemiş olursun.\" Hakikaten Biz onu pek sabırlı biri olarak bulduk: ne güzel kuldu o, gerçekten o (da) her daim Allah`a yönelirdi."},{"n":45,"t":"Has kullarımız İbrahim, İshak ve Yakub`u da hatırla: hepsi de güçlü bir kişilik ve keskin bir idrak sahibiydiler."},{"n":46,"t":"Biz onların şahsiyetlerini arı duru bir tasavvurla saflaştırdık (ki, ebedi) yurdu hep hatırda tutsunlar;"},{"n":47,"t":"ve elbet onlar, bizim indimizde pek seçkin, hayırda öne geçenler arasındaydılar."},{"n":48,"t":"Yine İsmail, Elyasa ve yükümlülük alan kişiyi de hatırla: onların hepsi de hayırda öncülük yaptılar."},{"n":49,"t":"Bu (mesaj) bir hatırlatma ve uyarıdır: elbet sorumluluğunun bilincinde olanları en güzel bir menzil beklemektedir."},{"n":50,"t":"Kalıcı güzelliğin üretildiği merkez olan cennetlerin kapıları onlar için ardına kadar dayalı olacaktır."},{"n":51,"t":"Orada huzurla uzanacaklar; ve meyvesine (dek) her çeşit lezzetli (yiyecek) ve içeceği talep edebilecekler."},{"n":52,"t":"Yanlarında kendilerine denk, gözü dışarda olmayan (eşler) bulunacak."},{"n":53,"t":"İşte bu, Hesap Günü için size verilen sözdür:"},{"n":54,"t":"elbet Bizim verdiğimiz bu rızık, asla tükenme riski taşımamaktadır."},{"n":55,"t":"Bu böyledir! Ama bir de haddini bilmez azgınlar var ki, onları da en kötü bir menzil beklemektedir:"},{"n":56,"t":"cehennem... (Onlar da) ona yaslanacaklar: ama o ne berbat bir döşektir."},{"n":57,"t":"Bu (da) böyledir! O halde bırak da, (yürek) dağlayıcı ve zift gibi iç karartıcı zehirli bir azabı sonuna kadar tatsınlar;"},{"n":58,"t":"ve aynı türden ona eşdeğer daha başka azap çeşitlerini de..."},{"n":59,"t":"(Küfrün rehberlerine denilecek ki): \"İşte şu güruh, körü körüne arkanıza takılan yandaşlarınız!\" (Onlar şöyle cevap verecek): \"Rahat yüzü görmesin onlar! Elbet onların da ateşe girmesi gerek!\""},{"n":60,"t":"(Körü körüne izleyenler ise), \"Hayır, (sorumlu) sizsiniz! Asıl siz rahat yüzü görmeyin! Bunu başımıza siz sardınız ve gele gele en berbat yeri (buldunuz)!\" diyerek"},{"n":61,"t":"şöyle yalvaracaklar: \"Rabbimiz! Bunu başımıza kim sardıysa, onun ateş içersindeki azabını kat be kat artır!\""},{"n":62,"t":"Bir de diyecekler ki: \"Ne oldu da, bir zamanlar kendilerini yaramaz adam saydıklarımızdan hiçbirini burada göremez olduk?"},{"n":63,"t":"Bir de onları alaya almıştık, değil mi? Yoksa (buradalar da), gözden kaybolup saklandılar mı?\""},{"n":64,"t":"Elbet ateş ehlinin birbiriyle çekişmesi, işte böyle gerçekleşecektir."},{"n":65,"t":"(Ey peygamber!) De ki: \"Ben sadece bir uyarıcıyım! Mutlak otorite olan tek Allah`tan başka ilah yoktur:"},{"n":66,"t":"göklerin, yerin ve o ikisi arasındakilerin Rabbi, mutlak yücelik, sürekli bağış sahibi!..\""},{"n":67,"t":"(Yine) de ki: \"Bu, muazzam bir haberdir;"},{"n":68,"t":"sizse ondan yüz çeviriyorsunuz.\""},{"n":69,"t":"(De ki): \"(İnsanın yaratılışını) tartıştıkları zaman, o yüce toplulukta (olup bitenler) hakkında bir bilgiye sahip değilim;"},{"n":70,"t":"ne var ki bana, sadece apaçık bir uyarıcı olduğum bildirilmektedir.\""},{"n":71,"t":"Hani o zaman Rabbin meleklere demişti ki: \"Ben balçıktan bir beşer yaratacağım."},{"n":72,"t":"İzleyin; ne zaman ki onu şekillendirmeyi tamamlar da kendisine ruhumdan üflersem, derhal yere kapanıp onun (hizmetine) amade olun!\""},{"n":73,"t":"Bunun üzerine bütün melekler emre amade oldular;"},{"n":74,"t":"İblis hariç: o büyüklük tasladı ve hakkı inkar edenlerden oldu."},{"n":75,"t":"(Allah) \"Ey İblis!\" dedi, \"Ellerimle yarattığım (beşerin) emrine amade olmaktan seni alıkoyan şey neydi? (Başkasına boyun eğmeyecek kadar) kibirli misin, yoksa kendini (herkesten) üstün görenlerden biri misin?\""},{"n":76,"t":"(İblis) dedi ki: \"Ben ondan üstünüm: (zira) beni ateşten yarattın, onu ise çamurdan yarattın!\""},{"n":77,"t":"(Allah) \"Öyleyse, çık git bu (yüce) makamdan\" dedi, \"çünkü sen kendi kendini aşağıladın!"},{"n":78,"t":"Ve unutma ki, Hesap Günü`ne kadar lanetim senin üzerine olacaktır!\""},{"n":79,"t":"(İblis): \"Rabbim!\" dedi, \"Madem öyle, bana tekrar diriliş gününe kadar süre tanı!\""},{"n":80,"t":"(Allah) buyurdu ki: \"Peki, sen artık kendisine süre tanınanlardan birisin;"},{"n":81,"t":"(tabi ki, sadece tarafımdan) bilinen zaman dolup günü gelinceye kadar.\""},{"n":82,"t":"(İblis) bunun üzerine dedi ki: \"Senin yüceliğine yemin olsun ki, kesinlikle onların tümünü yoldan çıkaracağım!"},{"n":83,"t":"Bunun tek istisnası, onlar arasındaki, imanını saf ve temiz tutma çabasını desteklediğin samimi kulların olacak!\""},{"n":84,"t":"(Allah) bunun üzerine şöyle buyurdu: \"İşte gerçek budur ve Ben de bu gerçeği dile getiriyorum:"},{"n":85,"t":"Andolsun ki cehennemi senin (gibiler)le ve sana uyanların tümüyle dolduracağım!\""},{"n":86,"t":"(Ey peygamber!) De ki: \"Ben bu mesajı (iletmemden) dolayı sizden hiçbir karşılık istemiyorum; ben kendi kendini zorla yükümlülük altına sokanlardan da değilim."},{"n":87,"t":"Ne ki bu (vahiy), bütün alemler için serapa bir uyarıdır:"},{"n":88,"t":"Ama onun verdiği haberin (gerçek olduğunu) bir zaman sonra mutlaka öğreneceksiniz!\""}],[{"n":1,"t":"Bu ilahi mesaj, her işinde mükemmel olan, her hükmünde tam isabet kaydeden Allah katından indirilmedir:"},{"n":2,"t":"Bu ilahi mesajı gerçek bir amaçla elbette Biz indirdik; şu halde, sadece Zatına hasredilmiş saf ve samimi bir borçluluk bilinciyle Allah`a kulluk et!"},{"n":3,"t":"Değil mi ki böyle bir borçluluk bilincinin en saf ve samimi olanı, sadece Allah`a has kılınanıdır! O`ndan başkalarını sığınacak otorite edinenler, \"Biz bunlara sadece bizi Allah`a yaklaştırsınlar diye kulluk ediyoruz!\" (derler). Şu kesin ki, tartıştıkları her hususta Allah onlar arasındaki hükmü verecektir: çünkü Allah yalanı tabiat haline getiren hiçbir nankörü asla doğru yola yöneltmez."},{"n":4,"t":"Şayet Allah bir çocuk edinmek isteseydi, yarattıkları arasından elbet dilediğini seçerdi. (Ama) O yüceler yücesi bundan münezzehtir: O mutlak otorite sahibi bir tek Allah`tır."},{"n":5,"t":"O gökleri ve yeri gerçek bir amaçla yaratmıştır; o geceyi gündüzün başına sarar, gündüzü de gecenin başına sarar; yine O, her biri kendi mecrasında belirli bir süreye kadar akıp gidecek olan güneşi ve ayı da bir yasaya bağlamıştır. Değil mi ki, sadece O mutlak üstün ve yüce olandır, tekrar tekrar bağışlayandır."},{"n":6,"t":"O sizi de bir tek canlı varlıktan yaratmış, ondan da eşini meydana getirmiştir; yine O her iki cinsten dört tür hayvanı sizin yararlanmanız için emre amade kılmıştır; o sizi (de) annelerinizin karınlarında üç kat karanlığın göbeğinde birbirini izleyen yaratma aşamalarından geçirerek halk etmektedir. İşte Rabbiniz olan Allah budur: mutlak hakimiyet O`na aittir: O`ndan başka hiçbir ilah yoktur. Böyleyken, nasıl (gerçeğe) bunca mesafeli durabiliyorsunuz?"},{"n":7,"t":"Eğer nankörlük ederseniz, unutmayın ki Allah size asla muhtaç değildir; ama O kullarının nankörlüğünden razı olmaz; fakat şükredecek olursanız, işte O sizin bu tavrınızdan razı olur. Hiç kimse bir başkasının sorumluluğunu taşımaz. En sonunda dönüşünüz Rabbinizedir: o zaman size yaptıklarınızın (gerçek anlamını) bir bir haber verecektir: çünkü O gönüllerde gizleneni hakkıyla bilir."},{"n":8,"t":"Hem ne zaman insanoğlunun başına bir iş gelse, Rabbine yönelerek O`ndan yalvar yakar yardım ister; ama O`nun sayesinde bir nimete kavuşunca da, O`na önceden yalvardığını unutur ve başka varlıkları O`na eş ve denk saymaya başlar: böylece başkalarını da O`nun yolundan saptırır. (Bu gibisine) de ki: \"Nankörlüğünle az bir süre keyif sür; ama şunu da iyi bil ki, sen ateşe layık birisin.\""},{"n":9,"t":"Yoksa (böyle biri), gece vakitlerinde secde ve kıyamda durup kendisini ibadete adayan, Ahiret kaygısı taşıyan ve Rabbinin rahmetini dilenen kimseyle hiç aynı tutulur mu? De ki: \"Hiç bilenlerle bilmeyenler bir olur mu?\" Ne var ki, sadece akleden kalbe sahip olanlar bunu kavrayabilir.\""},{"n":10,"t":"(Ey Peygamber!) De ki: \"(Allah şöyle buyurur): Ey iman eden kullarım! Rabbinize karşı sorumluluğunuzun bilincinde olun; akibet, bu dünyada iyilik yapanları (öte dünyada) güzellikler beklemektedir; iyi bilin ki Allah`ın arzı geniştir: şüphesiz sabredenlere, karşılıksız hesapsız verilecektir.\""},{"n":11,"t":"De ki: \"Elbet, ben, dini Allah`a has kılarak yalnız O`na kulluk etmekle emrolundum;"},{"n":12,"t":"bir de, Allah`a teslim olanların önderi olmakla emrolundum.\""},{"n":13,"t":"Duyur: \"Eğer ben Rabbime isyan etmiş olsaydım, korkunç bir günün azabından dehşete düşmem gerekirdi.\""},{"n":14,"t":"İlan et: \"Ben, dinimi yalnız Allah`a has kılarak sadece O`na kulluk ederim."},{"n":15,"t":"Artık siz de, O`nu bıraktıktan (sonra) neyi tercih ederseniz ona kulluk edin!\" Uyar: \"Gerçek şu ki, asıl hüsrana uğrayanlar, Kıyamet Günü hem kendilerini hem de yakınlarını hüsrana uğratanlardır: bakın bu, işte bu değil midir açık kayıp?"},{"n":16,"t":"Onları, üstlerinden ateş tabakaları kuşatacak, altlarından da (ateş) tabakaları...\" İşte bu yolla Allah kullarının kalbine korku salıyor. Ey kullarım! Bana karşı sorumluluğunuzun şuurunda olun!"},{"n":17,"t":"Allah`a isyanı sistemleştiren güç odaklarına kulluğa yanaşmayan ve Allah`a yönelen kimseler var ya: işte asıl müjdeyi onlar hak ediyor: şu halde bu kullarımı müjdele!"},{"n":18,"t":"O kullar ki, sözün tamamını dinlerler ve en güzeline uyarlar: İşte Allah`ın kendilerine doğru yolu gösterdiği kimseler bunlardır; ve işte onlar, aktif akıl sahipleridir."},{"n":19,"t":"Ne o, hakkında azap vaadi gerçekleşmiş olan kimseyle (böyle olmayan) kimse bir olabilir mi? Şimdi, ateşin göbeğine düşmüş birini sen kurtarabilir misin?"},{"n":20,"t":"Öte yandan Rablerine karşı sorumlu davrananlar, altından ırmakların geçtiği üst üste inşa edilmiş yüce cennet köşklerine sahip olacaklar. Bu Allah`ın vaadidir: Allah vaadinden asla dönmez."},{"n":21,"t":"(Ey insan!) Görmez misin ki Allah yağmuru gökten indirdi; ve onu yeryüzünde kaynaklar halinde akıttı; sonra da onunla farklı renklerde bitkiler çıkardı; ve nihayet onları kuruttu: artık sen onları sararmış görürsün; en sonunda onu da çer çöpe çevirecektir. İşte bütün bunlarda akletme yetisini tam kullananlar için alınacak bir ders mutlaka vardır."},{"n":22,"t":"Ne o! Yoksa Allah`ın gönlünü İslam`a açtığı ve böylece Rabbinden bir ışık üzere olan kimse, Allah`ı hatırlamaktan uzaklaşıp kalpleri katılaştığı için kendisine yazık eden kimseyle bir tutulur mu? Böyleleri apaçık bir sapıklığa mahkum olacaklardır."},{"n":23,"t":"Allah, öğretilerin en güzelini, biri diğerine atıf yaparak tekrarlanan, çift kutuplu bir hitap olarak indirmiştir: (öyle bir hitap ki), Rablerine karşı derin bir saygıyla titreyenlerin ondan dolayı tenleri ürperir; ardından Allah`ı(n sonsuz rahmetini) hatırlayınca kalpleri ve tenleri yatışır. İşte bu Allah`ın hidayetidir: isteyeni bununla doğru yola ulaştırmayı diler. Allah`ın saptırdığı kimse, artık asla yol gösterici bulamaz."},{"n":24,"t":"Ne o! Yoksa Kıyamet Günü azabın en beterinden kendisini yüzüyle korumaya çalışan kimse, (güven içindeki) kimseyle aynı olur mu? Zalimlere (o gün) \"Daha önce kazandıklarınızı şimdi tadın bakalım!\" denilecek."},{"n":25,"t":"Onlardan öncekiler de hakikati yalanlamışlardı; bunun üzerine, nereden geldiğini anlayamadıkları azap onları bulmuştu."},{"n":26,"t":"Sonunda Allah onlara bu dünyada onursuzluğu tattırdı: ama ahiret azabı elbet daha beterdi; keşke bunu olsun bilselerdi."},{"n":27,"t":"Doğrusu Biz bu ilahi mesajda (hakikati), belki düşünüp ibret alırlar diye insanlara her türlü dolaylı anlatım tarzını kullanarak aktardık;"},{"n":28,"t":"(ve onu) hiçbir çarpıklığa meydan bırakmadan Arapça bir hitap olarak (indirdik): belki sorumluluklarını idrak ederler."},{"n":29,"t":"(Bu bapta) Allah size hepsi birbirine rakip bir çok ortağın emri altında bulunan bir adamla, sadece bir kişiye bağlı bir adamın durumunu misal gösterir: bu ikisinin durumu eşit midir? Allah`a hamd olsun ki hayır, ama onların çoğu bunu kavramaktan bile acizdirler."},{"n":30,"t":"Şüphesiz sen de öleceksin, onlar da ölecekler:"},{"n":31,"t":"En sonunda sizler Kıyamet Günü Rabbinizin huzurunda hesaplaşacaksınız."},{"n":32,"t":"Allah hakkında yalan söyleyen ve ayağına kadar geldiği halde gerçeği yalanlayandan daha zalim kim olabilir? Hiç inkarda ısrar edenler için cehennemde yer bulunmaz mı?"},{"n":33,"t":"Ama doğruluğun tarafında yer alan ve hakikati tüm kalbiyle tasdik eden kimselere gelince: işte sorumluluklarını idrak eden onlardır."},{"n":34,"t":"Arzuladıkları her şey Rableri katında onları beklemektedir: Bu da iyi davrananların ödülüdür."},{"n":35,"t":"Şöyle ki: Allah onların yaptıklarının en kötülerini örter ve onları yapageldiklerinin en iyisiyle ödüllendirir."},{"n":36,"t":"Hiç Allah kuluna yetmez mi ki, onlar seni O`ndan başkalarıyla korkutuyorlar? Ve Allah kimi yoldan saptırırsa, artık onu doğru yola getiren olmaz;"},{"n":37,"t":"ama Allah kimi de doğru yola yöneltirse, artık onu doğru yoldan kimse çıkaramaz. Değil mi ki Allah her işinde tek mükemmel olandır, kimsenin yaptığını yanına kar bırakmayandır."},{"n":38,"t":"Ve eğer onlara \"Gökleri ve yeri yaratan kimdir?\" diye sorsan, kesinlikle \"Allah`tır\" derler. Sor onlara: \"Allah dışında yalvarıp yakardığınız varlıklara hiç baktınız mı? Eğer Allah benim için bir zarar murad etse, O`ndan gelecek zararı onlar def edebilirler mi? Veya bana bir rahmet dilese, onlar O`nun rahmetine engel olabilir mi?\" İlan et: \"Allah bana yeter! Artık O`nun (kuluna yeteceğine) güvenen herkes, sadece O`na dayansın!\""},{"n":39,"t":"Uyar: \"Ey kavmim! Siz kendinize yakışanı yapınız! Şunu iyi biliniz ki ben de (kendime yakışanı) yapmaktayım. Unutmayın ki, zamanı gelince onlar bilecekler"},{"n":40,"t":"muhatabını alçaltan (dünyevi) azabın kimi gelip bulacağını ve (ahiretteki) kalıcı cezanın kimin başına çökeceğini..."},{"n":41,"t":"Hiç şüphe yok ki, bu ilahi kelamı insanlık için (gerçek) bir amaca mebni olarak sana Biz indirdik: Artık kim doğru yolu seçerse bu kendi lehinedir; ama kim de saparsa sadece kendi aleyhine sapmış olur: zira sen onların tercihinden sorumlu değilsin."},{"n":42,"t":"Allah insanların canlarını ölümleri sırasında alır, henüz ölmemiş olanları da uykusunda alır: Derken ölümüne hükmettiklerini (katında) tutar, geri kalanı sonu yasayla belirlenmiş bir süre doluncaya kadar (geriye) salar. Kuşkusuz bunda, düşünen bir toplumun alacağı bir ders mutlaka vardır."},{"n":43,"t":"Yoksa onlar, Allah`ı bir tarafa bırakıp da (hayali) şefaatçiler mi buldular? Onlara şunu sor: \"Ne yani! Hiçbir şeye güçleri yetmese, akılları ermese de mi?\""},{"n":44,"t":"De ki: \"Şefaate (izin verme) yetkisi tamamıyla ve sadece Allah`a aittir: Gökler ve yerin mutlak otoritesi (de) O`na aittir: sonunda sadece O`na döndürüleceksiniz."},{"n":45,"t":"Ve ne zaman Allah tek başına anılsa, ahirete inanmayanların kalpleri tiksinti duyar; ne zaman da O`nun dışında başka varlıklar anılsa, bu kez aynı kimseler sevinçten uçar."},{"n":46,"t":"De ki: \"Allah`ım! Ey göklerin ve yerin yaratıcısı! Ey idraki aşan hakiketleri de, idrak edilenleri de bilen! Kullarının tartıştıkları konularda, aralarında son sözü söyleyecek olan yalnızca Sensin, Sen!"},{"n":47,"t":"Ve eğer yeryüzünün tüm serveti, hatta onun bir kat fazlası zulümde ısrar edenlerin olsaydı, Kıyamet Günü çarptırılacakları cezadan kurtulmak için onu fidye olarak verirlerdi; zira (o gün) daha önceden hiç hesaba katmadıkları şeyler, Allah tarafından ortaya çıkarılacak."},{"n":48,"t":"ve önceden yaptıkları her kötülük önlerine konacaktır; sonuçta alay ede geldikleri gerçek, kendilerini çepeçevre kuşatmış olacaktır."},{"n":49,"t":"İşbu nedenle, ne zaman insanın başına bir zarar gelse Bize yalvarır; daha sonra kendisi katımızdan bir nimete kavuşsa \"Bu servete ben sadece ve sadece kendi bilgim ve becerim sayesinde ulaştım\" der; ama hayır, aksine o bir sınav aracıdır: ne var ki onların çoğu bunu dahi kavrayamamaktadır."},{"n":50,"t":"Doğrusu onlardan öncekiler de böyle demiştiler: fakat kazana geldikleri şeyler kendilerine hiçbir yarar sağlamamıştı."},{"n":51,"t":"En sonunda kazandıklarının kötü sonuçları gelip onları bulmuştu. İşte şu zulmeden kimseleri de, kazandıklarının kötü sonuçları gelip bulacaktır: ve onlar asla (Allah`ı) atlatamayacaktır."},{"n":52,"t":"Şimdi onlar bilmezler mi ki, Allah dilediğinin rızık alanını genişletir, dilediğininkini sınırlandırır. Elbet bunda, inanan bir toplumun mutlaka alması gereken dersler vardır."},{"n":53,"t":"(Allah`ın şu müjdesini) ilet: \"Ey hadleri aşıp kendilerini israf eden kullarım! Allah`ın rahmetinden asla umut kesmeyiniz! Allah bütün günahları affedebilir: çünkü O, evet O`dur mutlak bağışlayıcı, sonsuz rahmet kaynağı olan!\""},{"n":54,"t":"İmdi, azap gelip sizi bulmazdan önce Rabbinize yönelin ve O`na teslim olun; sonra kimse size yardım edemez."},{"n":55,"t":"Ve bu azap siz farkında değilken ansızın gelip çatmadan önce, Rabbiniz tarafından siz (insanlara) indirilmiş olan en mütekamil vahye uyun"},{"n":56,"t":"ki, hiç kimse, \"Allah`a karşı yabancılaştığım ve gerçeği alay konusu yaptığım için vay benim halime\" demesin!"},{"n":57,"t":"Veya \"Eğer Allah beni doğru yola iletseydi, elbet ben de sorumlu davrananlar arasında olurdum\" demesin!"},{"n":58,"t":"Ya da azabı gördüğü zaman, \"Keşke bana bir fırsat daha tanınsa da iyiler arasına girsem\" demesin!"},{"n":59,"t":"(Allah onlara şöyle diyecek): \"Tam aksine sana ayetlerim gelmişti de, sen onları yalanlamış, küstahça büyüklenmiş ve hakkı inkar edenlerden olmuştun."},{"n":60,"t":"Ve Kıyamet Günü Allah hakkında yalan söyleyenlerin suratlarının kapkara kesildiğini göreceksin: Hiç küstahça böbürlenenler için cehennemde yer bulunmaz mı?"},{"n":61,"t":"Allah sorumluluklarını yerine getirenleri, bu alandaki başarıları sebebiyle kurtaracak; kötülük de hüzün de onların semtine asla uğramayacak."},{"n":62,"t":"Allah her şeyi yaratandır ve O her şeyin üzerindeki tek otoritedir;"},{"n":63,"t":"Göklerin ve yerin anahtarları O`na aittir. Ve Allah`ın ayetlerini ısrarla inkar edenlere gelince: asıl kaybedenler işte onlardır."},{"n":64,"t":"De ki: \"Ey kendini bilmezler güruhu! Allah`tan başkasına kulluk etmemi mi teklif ediyorsunuz?\""},{"n":65,"t":"Doğrusu sana ve senden öncekilere (insanoğluna iletilmek üzere) şöyle vahyedilmişti: \"(Ey insan!) Eğer Allah`a ait nitelikleri başkalarına yakıştırırsan, kesinlikle yapıp ettiklerin boşa gidecek, üstelik büsbütün kaybedenlerden olacaksın!"},{"n":66,"t":"Asla böyle yapma; sen yalnız Allah`a kulluk et ve şükredenlerden ol!\""},{"n":67,"t":"Nitekim onlar Allah`ı hakkıyla takdir edemediler; oysa ki bütün yeryüzü Kıyamet Günü O`nun tasarrufundadır; gökler ise O`nun kudret eliyle dürülmüştür: Yüceler yücesi olan O, onların şirk koştukları her şeyin ötesinde aşkın bir varlıktır."},{"n":68,"t":"Ve sura üflenecek: derken Allah`ın diledikleri dışında göklerde ve yerde bulunan herkes dehşetten çarpılmışçasına düşüp bayılacaktır. Sonra sura bir daha üflenecek: işte o zaman onlar yerlerinden doğrulup (gerçeği) görecekler."},{"n":69,"t":"Ve yer Rabbinin nuruyla aydınlanacak, tutulan kayıtlar ortaya konulacak, peygamberler ve (diğer) tüm şahitler huzura getirelecek; onlar arasında adaletle hükmedilecek ve kendileri asla zulme uğramayacaklar."},{"n":70,"t":"Zira herkese tüm yaptıklarının karşılığı eksiksiz verilecektir: nasıl olsa O onların yaptığı her şeyi bilmektedir."},{"n":71,"t":"İnkarda direnler de, guruplar halinde cehenneme yollanacaklar. Oraya vardıklarında, (cehennemin) kapıları açılacak; ve oranın muhafızları onlara \"Size aranızdan Rabbinizin ayetlerini ulaştıran ve sizi (hesap vereceğiniz) bu güne karşı uyaran elçiler gelmemiş miydi?\" diye soracaklar. Onlar: \"Hayır, elbette geldi!\" diyecekler; ve ne var ki inkar edenler hakkındaki azap hükmü kesinleşmiş olacak."},{"n":72,"t":"Onlara denilecek ki: \"İçinde yerleşip kalmak üzere cehennemin kapılarından girin!\" Sahi, küstahça böbürlenenler için ne berbat bir meskendir orası!"},{"n":73,"t":"Rablerine karşı sorumluluklarının bilincinde olanlar ise guruplar halinde cennete yollanacaklar. Kapıları zaten açılmış bulunan cennete vardıklarında, oranın muhafızları kendilerine şöyle diyecek: \"Selam olsun size! Safa başınıza! Ebedi kalmak üzere buyursunlar!..\""},{"n":74,"t":"Onlar da şöyle mukabele edecekler: \"Bize olan vaadini gerçekleştiren, bizi bu uçsuz bucaksız mekana varis kılan ve bizi cennette dilediğimiz yere yerleştirecek olan Allah`a hamd olsun!\" İşte, çalışıp çabalayanların ödülü böylesine muhteşemdir."},{"n":75,"t":"Ve sen, meleklerin Allah`ın hükümranlık makanı çevresinde halkalanıp hamd ile Rablerinin sonsuz yüceliğini dile getirdiklerini görürsün. Ki (o gün) herkes hakkında adaletle hüküm verilmekte ve şöyle denilmektedir: \"Hamd olsun alemlerin Rabbi olan Allah`a!\""}],[{"n":1,"t":"Ha-Mim!"},{"n":2,"t":"Bu ilahi kelamın indirilişi her işinde mükemmel olan, her şeyi bilen Allah katındandır."},{"n":3,"t":"(O) günahları bağışlayan, kendine yönelenin yönelişini kabul eden, cezalandırması çetin, keremi de sınırsız olandır: O`ndan başka ilah yoktur ve tüm yolların sonu O`na çıkar."},{"n":4,"t":"Allah`ın ayetleri konusunda, sadece inkarda direnenler ileri geri konuşurlar. Fakat onların gözde mekanlarında keyif çatmaları seni yanıltmasın:"},{"n":5,"t":"Onlardan önce Nuh kavmi ve peşlerinden gelen tüm kafadarlar da yalanlamıştı; her toplum kendi elçisini yakalayıp ondan kurtulmanın planlarını yapmıştı; batıl uğruna hakikati kendi kendisiyle alt etmeye çalışmak gibi yanlış ve yanıltıcı bir mücadele yöntemini benimsediler. Fakat, sonuçta Ben onları yakaladım: cezalandırma nasıl olurmuş görsünler bakalım!"},{"n":6,"t":"İşte Rabbinin inkarda direnen kimseler hakkındaki sözü böyle gerçekleşmiştir; elbet onlar ateş yoldaşıdırlar."},{"n":7,"t":"(Allah`ın) hükümranlık makamına (layık bir) sorumluluk taşıyanlar ve O`na yakın olanlar; hamd ile Rablerinin sonsuz yüceliğini dile getirirler, O`na güvenirler ve iman eden (diğer) kimseler için bağışlanma dilerler: \"Rabbimiz! Sen her şeyi rahmet ve bilginle kuşatmışsın! Artık tevbe edip Senin yoluna uyanları bağışla ve onları gözleri yuvalarından fırlatan dehşetli ateşin azabından koru!\""},{"n":8,"t":"\"Rabbimiz! Onları ve onların atalarından, eşlerinden ve nesillerinden iyi ve dürüst olanları güzelliğin merkezi olan cennetlere yerleştir: çünkü Sen, evet Sensin her işinde tek mükemmel olan, her hükmünde tam isabet kaydeden!"},{"n":9,"t":"Ve onları tüm kötülüklerden koru! Ki Sen o gün birini kötü duruma düşmekten korursan, bu ona rahmet ettiğin anlamına gelir: bu, evet, en büyük başarı işte budur!\""},{"n":10,"t":"İnkarda ısrar edenlere (o gün) şöyle nida edilecektir: \"İman etmeye çağırıldığınız halde inkar etmeyi sürdürdüğünüz zaman Allah`ın size olan kahır ve sitemi, sizin (şu an) kendi kendinize olan kahır ve siteminizden daha büyüktür!\""},{"n":11,"t":"Şöyle karşılık verecekler: \"Rabbimiz! Sen bizi iki kez öldürdün, iki kez de dirilttin. İşte artık günahlarımızı itiraf ettik: şimdi bizim için bir çıkış yolu yok mudur?\""},{"n":12,"t":"(Onlara şöyle denilecek): \"Durum işte böyle(sine vahim)dir: çünkü sadece Allah`a (kulluğa) çağrıldığınız her seferinde inkarı tercih ettiniz; O`na ortak koşulduğunda ise inanıverdiniz. Fakat şimdi hüküm yüceler yücesi, mutlak büyük olan Allah`a aittir.\""},{"n":13,"t":"O`dur size (varlık) delillerini gösteren ve size semadan rızık indiren: Yönünü O`na çevirenlerden başkası bundan ders almaz."},{"n":14,"t":"Hakikati inkar edenleri ne denli kızdırsa da, siz akideyi yalnız O`na has kılarak saf ve samimi bir inançla sadece Allah`a yalvarın!"},{"n":15,"t":"Zira O, bütün varlık hiyerarşisinin en yücesi olarak hükümranlık makanına kurulmuştur. O Duruşma Günü hakkında uyarmak için kullarından dilediğine kendi katından vahiy indirir."},{"n":16,"t":"O gün onlardan hiç kimse Allah`tan hiçbir şeyi saklayamadan (gerçek yüzleriyle) ortaya çıkarlar."},{"n":17,"t":"O gün herkes kazandığının karşılığını bulur; haksızlığın olmadığı gündür o: çünkü Allah hesabı seri görendir."},{"n":18,"t":"Ve onları yüreklerin sahibini boğarcasına gırtlağa dayanacağı dehşet gününe karşı uyar: o gün zalimler ne samimi bir dost, ne de sözü geçen bir şefaatçi bulacaktır."},{"n":19,"t":"O, bakışlarda (saklı) ihaneti ve yüreklerin gizlediği şeyleri bilir;"},{"n":20,"t":"ama Allah hükmünde hakkaniyeti gözetir, O`nu bırakıp da yalvarıp yakardıklarıysa hiçbir şey hakkında hüküm veremezler: çünkü sadece Allah her şeyi işitendir, her şeyi görendir."},{"n":21,"t":"Onlar hiç yeryüzünde dolaşmazlar mı ve görmezler mi kendilerinden önce geçip gitmiş olanların (feci) akıbetini? Onlar kendilerinden daha güçlüydüler ve yeryüzünde daha derin izler bırakmıştılar. Buna rağmen Allah günahları sebebiyle onları cezalandırdı ve kendilerini Allah`a karşı koruyacak kimse olmadı."},{"n":22,"t":"Böyle oldu, çünkü elçileri kendilerine hakikatin apaçık belgeleriyle geldiği halde, onlar inkarda direndiler; bunun üzerine Allah da onları cezalandırdı: Zira O güçlüdür, cezası pek çetindir."},{"n":23,"t":"Doğrusu Biz Musa`yı, mesajlarımızla ve (sahibinin doğruluğuna şahit olan) apaçık bir belgeyle elçi göndermiştik:"},{"n":24,"t":"Firavun`a, Haman`a ve Karun`a... Fakat onlar \"Yalancı sihirbazın teki\" demişlerdi."},{"n":25,"t":"(Musa) kendilerine tarafımızdan gönderilmiş malum hakikatlerle gelince, \"Onun yanında yer alan mü`minlerin kadınlarını sağ bırakıp oğullarını öldürün!\" dediler. Kafirlerin entrikası asla hedefine ulaşamayacaktır."},{"n":26,"t":"Firavun \"Bana bırakın, Musa`yı ben öldüreyim!\" dedi ve ekledi: \"O Rabbine yalvara dursun; ama ben asıl onun sizin hayat tarzınızı değiştirmesinden ve ülkede düzenin bozulmasından korkuyorum!\""},{"n":27,"t":"Musa dedi ki: \"Ben kibire kapılıp Hesap Günü`ne inanmayan herkesten benim de sizin de Rabbiniz (olan Allah`a) sığınırım.\""},{"n":28,"t":"Firavun’un yakın çevresinden olup da imanını gizleyen mü’min bir adam şöyle çıkıştı: “Bir adamı sırf ‘Rabbim Allah’tır’ dediği için, üstelik size Rabbinizden, hakikatin apaçık delilleriyle geldiği halde öldürecek misiniz? Kaldı ki, eğer yalancıysa yalanının zararı yalnızca kendisinedir; yok eğer gerçeği söylüyorsa, tehdit ettiklerinin hiç değilse bir kısmı gelip sizi bulacaktır: çünkü Allah yalan dolanla kendini ziyan eden birini asla hedefe ulaştırmaz.”\""},{"n":29,"t":"\"Ey kavmim! Bugün iktidar sizin tekelinizde, yeryüzünde ezici güçsünüz; tamam ama, eğer Allah`ın cezasına maruz kalırsak bizi kim kurtaracak?\" Firavun dedi ki: \"Ben size sadece kendi görüşümü bildiriyorum; ve sizi doğru olan alternatifsiz bir yola yöneltiyorum.\""},{"n":30,"t":"Yine iman eden kimse söze girerek dedi ki: \"Ey kavmim! İnanın ki ben, şu (inkarda) ittifak etmiş toplulukların helakine benzer bir günün sizin de başınıza gelmesinden korkuyorum;"},{"n":31,"t":"yani Nuh kavminin, Ad ve Semud`un ve onlardan sonrakilerin uğradığı türden bir helakın... Bir de (unutmayın) ki Allah, kullarına haksızlık etmeyi asla istemez.\""},{"n":32,"t":"\"Ey Kavmim! Ben, herkesin birbirinden imdat dilediği o günün aleyhinize sonuçlanmasından korkuyorum."},{"n":33,"t":"O gün arkanızı dönüp kaçmaya çalışacaksınız, fakat Allah`ın (adaletinden) sizi kurtaracak kimse bulamayacaksınız: zira Allah kimi saptırırsa artık ona yol gösteren kimse bulunmaz."},{"n":34,"t":"\"Ve doğrusu daha önce Yusuf da size hakikatin apaçık belgeleriyle gelmişti; ama onun size getirdiklerine karşı sürekli bir şüphe taşıdınız; en sonunda Yusuf ölünce, kalkıp `Allah ondan sonra bir daha elçi göndermeyecek` dediniz!\" İşte Allah düştükleri kuşku bataklığında debelenerek kendilerini harcayanları böyle yoldan çıkarır."},{"n":35,"t":"Bu gibiler kendilerine ulaşmış hiçbir belge ve yetki olmadan Allah`ın ayetleri hakkında ileri geri konuşurlar: (bu) hem Allah katında, hem de iman edenler nezdinde büyük bir bayağılaşmadır: İşte Allah her kibirli zorbanın kalbini böyle mühürler."},{"n":36,"t":"Ve Firavun \"Ey Haman!\" diye emretti, \"Bana görkemli bir kule yap! Belki böylece (amacımı gerçekleştirecek) araçlara ulaşırım;"},{"n":37,"t":"gökleri aşacağım araçlara... Böylece Musa`nın ilahına erişebilirim (!). Hoş, ben onun bir yalancı olduğundan kesinlikle eminim ya!\" İşte kötü davranışı Firavun`a böylesine güzel göründü ve doğru yoldan alıkonuldu: neticede Firavun`un düzeni, çöküşü (hızlandırmaktan) başka hiçbir işe yaramadı."},{"n":38,"t":"Derken iman eden o kimse, \"Ey kavmim!\" dedi, \"Bana uyun ki ben sizi akl-ı selim yoluna yönelteyim!"},{"n":39,"t":"Ey kavmim! Bu dünya hayatı sadece kısa vadeli bir hazdır; bir de öteki (hayat) var: kalıcı diyar işte orasıdır."},{"n":40,"t":"Kim bir kötülük işlerse, sadece yaptığı kadarıyla cezalandırılır; ama kim de imanlı olarak güzel davranış sergilerse, -erkek ya da kadın fark etmez- işte bu gibiler cennete girecek ve orada haddi hesabı olmayan nimetler ikram edilecektir.\""},{"n":41,"t":"\"Ey kavmim! Nasıl oluyor da ben sizi kurtuluşa çağırırken siz beni ateşe çağırıyorsunuz?"},{"n":42,"t":"Siz beni hem Allah`ı inkar etmeye, hem de (tanrısal bir nitelik taşıdığı) hakkında hiçbir bilgim olmayan şeyleri O`na ortak koşmaya çağırırken, bense sizleri mutlak üstün ve yüce olup tekrar tekrar bağışlayana çağırıyorum."},{"n":43,"t":"Kesinlikle, sizin beni çağırdığınız şey ne dünyada ve ne de ahirette kendisine çağırılmaya layık bir şey değildir; zaten dönüşümüz de Allah`adır: ve elbet kendini harcayanlar ateşin yoldaşlarıdır."},{"n":44,"t":"Ve bir gün gelecek, bu sözlerimi bir bir hatırlayacaksınız. Bense sorumluluğuma ilişkin (hükmü) Allah`a havale ediyorum: çünkü Allah kulların her şeyini görmektedir.\""},{"n":45,"t":"Derken Allah onu kavminin çirkin tuzaklarından korudu; Firavun ailesinin helaki ise azabın en kötüsüyle oldu:"},{"n":46,"t":"Ateş... Onlar o (ateşe) sabah ve akşam sunulacaklar; ve Son Saat gelip çattığında (Allah şöyle buyuracak): \"Firavun ailesine en şiddetli cezayı verin!\""},{"n":47,"t":"Hani ateşin bağrında karşılıklı tartışırken onları (bir görmelisin): Nitekim zayıflar büyüklük taslayanlara: \"Bizim sizin peşinize takıldığımız kesin; şu halde ateşin üzerimizdeki etkisini bir parça olsun hafifletemez misiniz?\" diye yalvaracaklar."},{"n":48,"t":"Büyüklük taslayanlar ise: \"İşte hepimiz onun içindeyiz; kesin olan şu ki, Allah kulları arasındaki hükmünü çoktan vermiştir!\" diyecekler."},{"n":49,"t":"Ve ateşin içindekiler, cehennemin bekçilerine şu ricada bulunacaklar: \"Rabbinize yalvarın da, azabı üzerimizden bir gün olsun hafifletsin!\""},{"n":50,"t":"(Bekçiler) şöyle cevap verecek: \"Elçileriniz size hakikatin apaçık belgeleriyle gelmemişler miydi?\" (Berikiler): \"Elbette (gelmişti)\" diyecekler. (Bekçiler) diyecek ki: \"O halde yalvarmaya devam edin! Ama inkarı tabiat edinenlerin yalvarması aldanışı (artırmaktan) başka bir sonuç vermez.\""},{"n":51,"t":"Şüphe yok ki Biz rasullerimize ve iman eden kimselere, hem bu dünya hayatında hem de şahitlerin dinleneceği günde (hasımlarına karşı) elbette yardım edeceğiz."},{"n":52,"t":"O gün zalimlere mazaretlerinin hiçbir yararı olmayacak; onların payına düşen Allah`ın rahmetinden dışlanmak ve en berbat yurda konmak olacak."},{"n":53,"t":"(Vaadimiz gereği) vaktiyle Biz Musa`ya rehberliğimizi iletmiş ve İsrailoğullarını ilahi kelama varis kılmıştık:"},{"n":54,"t":"aktif akıl sahipleri için bir hidayet ve bir uyarı olarak."},{"n":55,"t":"Şu halde dirençli ol! Zira Allah`ın vaadi mutlaka gerçekleşecektir. Hatan için af dile ve akşam sabah hamd ile Rabbinin yüceliğini dile getir!"},{"n":56,"t":"Allah`ın ayetleri hakkında kendilerine ulaşmış hiçbir belge ve yetki olmadan tartışanlara gelince: onların içinde hiçbir zaman erişip (tatmin) olamayacakları bir büyüklenme tutkusu vardır, başkası değil. Artık sen sadece Allah`a sığın: çünkü O, evet O`dur her şeyi işiten, her şeyi görüp gözeten."},{"n":57,"t":"Göklerin ve yerin yaratılması elbette insan cinsinin yaratılmasından daha kapsamlı bir hadisedir; lakin insanların çoğu bunun (anlamını) dahi bilmez."},{"n":58,"t":"Neticede görenle görmeyen bir olmaz; tıpkı iman edip o imana uygun iyilik yapan ile kötülük yapanın bir olmadığı (gibi): Ne kadar da azınız öğüt alıyor!"},{"n":59,"t":"İmdi, Son Saat mutlaka gelecektir; bunda kuşku yok: Ama insanların çoğu buna (dahi) inanmaz."},{"n":60,"t":"Ve Rabbiniz şöyle buyurur: \"Bana dua edin ki ben de kabul edeyim! Bunu kulluk yapmayı kendisine yediremeyenler, rezil rüsva olarak cehenneme girecekler."},{"n":61,"t":"Geceyi sükünet bulasınız diye, gündüzü ise (işlerinizi) göresiniz diye yaratan Allah`tır: çünkü Allah insanlara karşı sınırsız lütuf sahibidir; ama insanların çoğu yine de şükretmezler."},{"n":62,"t":"Rabbiniz olan Allah işte böyledir: her şeyi yaratan, kendisinden başka ilah olmayan O`dur: şu halde, nasıl oluyor da böylesine savruluyorsunuz?"},{"n":63,"t":"İşte, vaktiyle Allah`ın ayetlerini göz göre göre inkar edenler de tıpkı böyle savrulmuştular."},{"n":64,"t":"Yeryüzünü sizin için bir yerleşim alanı yapan ve gök kubbeyi inşa eden, size şekil verip üstelik şeklinizi de en güzel kılan, dahası sizi temiz ve güzel nimetlerle rızıklandıran Allah`tır. Rabbiniz olan Allah işte böyledir: nitekim alemlerin Rabbi olan Allah ne yüce bir bereket kaynağıdır!"},{"n":65,"t":"Mutlak diri O, kendisinden başka ilah olmayan O`dur: Artık siz de O`na, adanmış samimi ve saf bir inançla sadece O`na yalvarın! Hamd tümüyle alemlerin Rabbi Allah`a mahsustur."},{"n":66,"t":"De ki: \"Elbet ben, hele de Rabbimden bana hakikatin apaçık delilleri ulaşmışken, Allah`tan başka yalvarıp yakardıklarınıza kulluk etmekten nehyolundum; ve ben kendimi Alemlerin Rabbine teslim etmekle emrolundum.\""},{"n":67,"t":"Sizi önce toprak türünden, sonra bir damlacık hayat suyundan, sonra da döllenmiş yumurta hücresinden yaratan O`dur; sonra bebek olarak meydana gelmenizi (dilemiştir); sonra olgunluk çağına erişmeniz ve ardından da yaşlanmanız için (yasa koymuştur): Ne ki kiminize ölüm daha erken tattırılır, (kiminize) de sonu yasayla belirlenmiş bir süreye ulaşmanız için (zaman tanınır) ki, belki aklınızı başınıza alırsınız."},{"n":68,"t":"Hayatı ve ölümü yaratan O`dur: ve O bir işin olmasına hükmettiğinde ona sadece \"Ol!\" der, o da hemen oluşum sürecine giriverir."},{"n":69,"t":"Baksana Allah`ın ayetleri hakkında ileri geri konuşan şu tiplere: (tasavvurları) kendilerini hakikatten nasıl da uzaklaştırıyor."},{"n":70,"t":"Onlar, bu ilahi kelamı ve elçilerimize daha önce gönderdiğimiz mesajları yalanlayan tipler; fakat bu gibiler zamanı gelince (gerçeği) öğrenecekler."},{"n":71,"t":"İşte o zaman, kendi boyunlarına (geçirdikleri) tasmalar ve (ellerindeki) kelepçelerle sürüklenecekler;"},{"n":72,"t":"yürek dağlayan bir (umutsuzluğun) gayyasına... En sonunda ateşi azdıran bir yakıta dönecekler."},{"n":73,"t":"Ve onlara sorulacak: \"Hani, nerede ilahlık yakıştırdığınız varlıklar;"},{"n":74,"t":"(İlahlar hiyerarşisinde) Allah`ın astlarından saydığınız?\" Onlar şöyle cevap verecekler: \"Bizi terk ettiler. İşin doğrusu, daha önceden biz sanki hiçbir şeye yalvarıp yakarmamışız.\" İşte Allah gerçeği inkar edenleri böyle şaşırtır."},{"n":75,"t":"Bunun nedeni, yeryüzünde hak etmediğiniz halde azıp şımarmanız ve kasıntılık yapmanızdır:"},{"n":76,"t":"Haydi, içinde yerleşip kalmak üzere cehennemin kapılarından girin; doğrusu, küstahça böbürlenenler için orası dehşet bir mekandır."},{"n":77,"t":"Şu halde dirençli ol! Zira Allah`ın vaadi mutlaka gerçekleşecektir. İmdi, onlara yönelttiğimiz tehditlerin bir kısmının gerçekleştiğini ister sana gösterelim, isterse senin için ölümü takdir edelim; er geç, onlar Bize döndürülecekler."},{"n":78,"t":"Doğrusu Biz, senden önce de sayısı belirsiz elçiler göndermiştik; onların kimisinden sana söz ettik, kimisinden sana hiç söz etmedik. Ama şu kesin ki, hiçbir elçi Allah`ın izni olmadan mucizevi bir mesaj getiremez. Nitekim Allah`ın emri geldiği zaman, hak tecelli etmiş olacak; işte o anda ve orada, hayatı anlam ve amacından yoksun bırakanlar hüsrana uğramış bulunacaklar."},{"n":79,"t":"Bir kısmına binmeniz, bir kısmıyla da beslenmeniz için evcil hayvanları emrinize amade kılan (da) Allah`tır."},{"n":80,"t":"Onlardan daha başka alanlarda da yararlanırsınız; onlar aracılığıyla yürekten özlemini çektiğiniz bir ihtiyaca da ulaşırsınız; hem onlarla hem de gemilerle (hayatın) yükünü taşırsınız."},{"n":81,"t":"İşte O size (varlık) ayetlerini böyle gösterir; o halde Allah`ın ayetlerinden hangisini inkar edebilirsiniz?"},{"n":82,"t":"Şimdi onlar yeryüzünde dolaşıp kendilerinden öncekilerin sonunun nasıl olduğunu görmezler mi? Onlar berikilerden daha kalabalık, daha güçlü ve yeryüzünde daha derin izler bırakmışlardı: fakat birikimleri onlara hiçbir yarar sağlamadı."},{"n":83,"t":"Çünkü onlara elçileri hakikatin apaçık delilleriyle geldiğinde, elde tuttukları bir parça bilgiye güvenip küstahça şımardılar: sonunda alay ede geldikleri gerçek kendilerini çepeçevre kuşattı."},{"n":84,"t":"Ve kahredici cezamızı gördükleri zaman \"Tek olan Allah`a iman ettik ve O`na ortak koştuğumuz şeylere olan inancımızı reddettik!\" dediler."},{"n":85,"t":"Fakat kahredici cezamızı gördükten sonra iman etmeleri, onlara hiçbir yarar sağlamadı. Kulları hakkında geçmişten bugüne Allah`ın uygulaması budur: Nitekim inkarı tabiat edinenler orada ve o anda hüsrana uğradılar."}],[{"n":1,"t":"Ha-Mim!"},{"n":2,"t":"Muhteşem bir indiriliş; O Rahman O Rahim`den."},{"n":3,"t":"Öyle bir kitap ki, onun ayetleri, kavrayabilen bir topluluk için Arapça bir hitap olarak ayrıntılı biçimde açıklanmıştır;"},{"n":4,"t":"bir müjdeci ve bir uyarıcı olarak: ama (uyarılanlar var ya), onların çoğu yüz çevirmiştir; artık onlar işitmezler."},{"n":5,"t":"Bir de dönüp derler ki: \"Kalplerimiz bizi çağırdığın şeye kapalıdır, kulaklarımızda kurşun vardır; dahası aramızda aşılmaz bir engel vardır. Şu halde sen (elinden geleni) yap, unutma ki biz de (elimizden ne geliyorsa onu) yapacağız!"},{"n":6,"t":"(Ey Peygamber!) De ki: \"Ben de yalnızca sizin gibi ölümlü bir insanım. Bana ilahınızın tek bir ilah olduğu vahyediliyor: öyleyse O`na yönelin ve O`ndan af dileyin!\" Yazıklar olsun Allah`tan başkasına ilahlık yakıştıranlara!"},{"n":7,"t":"Onlar ki, arınmak için ödenmesi gereken bedeli gönüllü olarak ödemezler; işte onlar, evet onlardır ahireti inkar edenler."},{"n":8,"t":"Ama iman eden, imanına uygun davrananlara gelince: onları kesintisiz bir ödül beklemektedir."},{"n":9,"t":"De ki: \"Şimdi siz, arzı iki evrede yaratan Allah`ı inkar edip, O`na -ki, işte O`dur alemlerin Rabbi- eşdeğer rakip güçler mi peydahlıyorsunuz?\""},{"n":10,"t":"O arz üzerine sarsılmaz dağlar yerleştirdi ve ona bereket bahşetti; dahası oranın besinlerini, ora sakinlerinden talep edenler arasında dengeli bir biçimde takdir etti: (bütün bunlar) dört evrede gerçekleşti."},{"n":11,"t":"Dahası, O duman halindeki göğü şekillendirdi; ona ve arza: \"Her ikiniz, isteyerek ya da istemeyerek (varlık sahnesine) gelin!\" dedi. İkisi birden \"Bizler boyun eğerek (varlık sahnesine) geldik!\" dediler."},{"n":12,"t":"Derken onları iki aşamada yedi gök olarak var etti, her bir göğe kendi görev yasasını yükledi. Nihayet Biz en yakın göğü ışıklarla süsledik ve bir güvenlik sistemi oluşturduk: İşte bu her şeyi bilen, her işi mükemmel olan Allah`ın takdiridir."},{"n":13,"t":"Bu (cömertliğimize) rağmen yüz çevirirlerse, de ki: \"Sizi Ad ve Semud`u çarpan yıldırıma benzer bir (bela) yıldırımıyla uyarıyorum!\""},{"n":14,"t":"Hani elçiler onlara önlerinden ve arkalarından gelerek \"Allah`tan başkasına kulluk etmeyin!\" demişlerdi. Onlar, \"Rabbimiz (böyle bir şey) isteseydi, kesin melekleri indirirdi; şu halde biz, sizinle gönderildiğini (söylediğiniz) şeyleri ısrarla reddediyoruz\" dediler."},{"n":15,"t":"Ad kavmine gelince... Nitekim onlar da yeryüzünde haksız yere büyüklendiler ve \"Bizden daha güçlü kim var?\" dediler. Ne yani onları yaratan Allah`ın kendilerinden daha güçlü olduğunu da mı düşünemediler? Bir de kalkmışlar, ayetlerimizi bile inkar ediyorlar."},{"n":16,"t":"Nihayet bu dünya hayatında alçalışın azabını kendilerine tattırmak için kara günler boyunca üzerlerine iliklere işleyen bir rüzgar gönderdik: ama ahiretin azabı kesinlikle daha alçaltıcıdır ve onlar yardım da göremeyecekler."},{"n":17,"t":"Semud kavmine gelince... Nitekim Biz onlara da yol göstermiştik, fakat onlar doğru yolu görmektense körlüğü tercih ettiler: Sonuçta yapa geldikleri şeylere karşılık, onları onur kırıcı azabın yıldırımı çarptı."},{"n":18,"t":"Ama Biz, iman eden ve sorumluluk bilinciyle kuşananları kurtardık."},{"n":19,"t":"Ve Allah düşmanları, ateşe doğru sevk edilecekleri o gün baştan sona zapturapt altına alınırlar;"},{"n":20,"t":"hatta ateşe vardıklarında, kulakları, gözleri ve derileri yapa geldikleri şeyler sebebiyle onlar aleyhine şahitlik eder."},{"n":21,"t":"Derilerine, \"Niçin aleyhimize şahitlik ettiniz?\" diye sorarlar. Onlar da, \"Her şeye (kendi dilince) konuşma yeteneği veren Allah bize de verdi: sizi yoktan var eden O`dur, dönüşünüz de yine O`nadır."},{"n":22,"t":"Bir zamanlar siz kulaklarınızın, gözlerinizin ve derilerinizin size karşı şahitlik yapmasından sakınmazdınız; üstelik Allah`ın yaptıklarınız hakkında fazla bir şey bilmediği zannına kapılırdınız."},{"n":23,"t":"Bakın işte, Rabbiniz hakkındaki bu zannınız sizi helaka sürükledi de, böylece hüsrana uğrayanlardan olup çıktınız."},{"n":24,"t":"Eğer dayanabilirlerse, bu durumda ateş onlar için bir çeşit mesken olacaktır; geri dönüp af için başvurmak isteyecekler, asla başvuruları kabul edilmeyecektir."},{"n":25,"t":"Zira onların başına güdümüne girecekleri yoldaşlar musallat ettik; bunlar, önlerinde olanı da arkalarında kalanı da kendilerine süslü gösterdiler; işte böylece, kendilerinden önce gelip geçmiş olan görünür görünmez varlıklardan nice topluluklar hakkındaki vaad onlar için de gerçekleşmiş oldu: şüphe yok ki onlar, daima kaybeden taraf oldular."},{"n":26,"t":"Hakkı inkarda direnen kimseler, \"Bu Kur`an`ı dinlemeyin, onu karalayıp şamata yapın ki bastırabilesiniz!\" dediler."},{"n":27,"t":"Ve elbet inkarda direnen bu kimselere şiddetli bir terkedilmişlik acısı tattıracağız, ve onları kesinlikle yapa geldiklerinin en kötüsüyle cezalandıracağız!"},{"n":28,"t":"İşte budur Allah düşmanlarının cezası: ateş. Onların sürekli kalacakları yer, ayetlerimizi bile bile inkar etmelerine karşılık olmak üzere orası olacaktır."},{"n":29,"t":"Ve (oraya girince) inkarda direnen kimseler diyecek ki: \"Rabbimiz! Görünen görünmeyen tüm varlıklardan bizi saptıranları bize göster: Hepsini de ayaklarımız altına alıp çiğneyelim ki, hepimizin en alçağı olsunlar!\""},{"n":30,"t":"Öte yandan, \"Rabbimiz Allah`tır\" diyen, sonra da dosdoğru çizgide yaşama kararlılığı gösterenlere gelince: onlara melekler sürekli inerler (ve derler ki): \"Gelecekten dolayı kaygı duymayın, geçmişten dolayı da mahzun olmayın! Haydi sevinin size vaad edilmiş olan cennetle!"},{"n":31,"t":"Biz bu dünya hayatında sizin dostunuzuz, ahirette de öyle. Orada size canınız ne çekiyorsa o var, orada siz ne arzu ediyorsanız o sizin;"},{"n":32,"t":"tarifsiz bir bağış ve eşsiz rahmet kaynağı olan (Allah) tarafından bir ikram olarak...\""},{"n":33,"t":"Allah`a davet eden, dürüst ve erdemli davranan ve \"Ellbette ben kayıtsız şartsız Allah`a teslim olanlardanım\" diyenden daha güzel sözlü kim olabilir?"},{"n":34,"t":"Madem ki iyilik de bir olmaz, kötülük de; (o halde) sen tezini en güzel biçimde savun! Bak gör o zaman, seninle arasında düşmanlık olan biri bile sanki sımsıcak bir dost kesiliverir."},{"n":35,"t":"Ne ki bu (meziyete) sadece sabırda direnenler ulaşabilir; yine buna, ancak kendisine büyük bir pay ayrılanlar ulaşabilir."},{"n":36,"t":"Ve eğer Şeytan tarafından ısrarlı bir ayartmaya maruz kalırsan, hemen Allah`a sığın: Çünkü O her şeyi işitendir, her şeyi bilendir."},{"n":37,"t":"Ve gece ile gündüz, güneş ile ay O`nun ayetlerindendir: (Şu halde) ne güneşe secde edin, ne de aya! Eğer özellikle O`na kulluk ettiğinizi (düşünüyorsanız), onları da yaratan Allah`a secde edin!"},{"n":38,"t":"Fakat küstahça büyüklük taslarlarsa, iyi bilsinler ki Rabbinin huzurundakiler gece gündüz O`nun yüceliğini anmaktadır; hem de hiç bıkıp usanmadan..."},{"n":39,"t":"O`nun ayetlerinden biri de şudur: Sen toprağı tüm iddialarından soyunmuş olarak görürsün; ama onun üzerine (yağmur) suyunu indirdiğimiz zaman harekete geçer ve uyanıverir. Ona hayat veren, elbet ölü (kalp)lere de hayat verecek olandır: Çünkü O her şeye güç yetirendir."},{"n":40,"t":"Gerçek şu ki, ayetlerimizi anlam ve amacından saptıranlar asla bizden gizlenemezler: şimdi, ateşe atılan mı, yoksa Kıyamet Günü (huzura) güven içinde gelen mi daha değerlidir? İstediğinizi yapın; nasıl olsa O yaptığınız her şeyi görmektedir."},{"n":41,"t":"Şüphesiz onlar, kendilerine ulaştığı halde bu ilahi uyarıyı inkar edenlerdendir: çünkü o, elbette pek yüce bir Kitaptır."},{"n":42,"t":"Hiçbir anlam ve amacından saptırma çabası ona ne önünden açıkça, ne de ardından gizlice ilişemez: o, her tür övgüye layık, hükmünde isabetli olan tarafından indirilmiştir."},{"n":43,"t":"(Ey Nebi!) Sana söylenenler, senden önceki elçilere söylenenlerden başka bir şey değildir. Şüphe yok ki senin Rabbinin bağışlayıcılığı kesindir, ama (aynı zamanda) can yakıcı bir cezanın da sahibidir."},{"n":44,"t":"Eğer Biz bu (vahyi) yabancı dille okunan bir kitap kılsaydık, kesinlikle \"Neden onun ayetleri açık ve anlaşılır değil; ne yani, bir Arab`a dili yabancı bir (hitap) mı?\" derlerdi. De ki: \"Bu (vahiy), iman edenler için bir yol gösterici ve bir şifa kaynağıdır. İman etmeyenlere gelince: Onların kulaklarında bir çeşit kurşun vardır; dahası o (vahyin ışığından dolayı) onlara bir tür körlük arız olmuştur: şimdi onlar, çok uzak bir yerden seslenilen kişi (gibi)dirler."},{"n":45,"t":"Doğrusu Biz Musa`ya da kitap vermiştik ve onun hakkında da ihtilaf edilmişti. Ve eğer Rabbin tarafından daha önce konulmuş kesin bir yasa olmasaydı, haklarında hüküm hemen infaz edilirdi: Yine de onlar, bundan dolayı tereddütlü bir şüphe içindedirler."},{"n":46,"t":"Kim Allah`ı razı edecek iş işlerse kendi lehine olur; kim de kötülük işlerse kendi aleyhine olur: Rabbinin kullarına zulmetme ihtimali asla bulunmamaktadır."},{"n":47,"t":"Son Saat`in bilgisi yalnız O`na havale edilir. Hem O`nun bilgisi olmadan ne meyve çekirdekleri kabuklarını çatlatabilecek, ne de herhangi bir dişi gebe kalabilecektir; dahası, doğuramaz bile. Ve o gün onlara \"Hani, nerede ortaklarım(!)?\" diye seslenen biri çıkar; onlar \"Sana itiraf ederiz ki, bizden hiç kimse (buna) asla tanık olmamıştır\" diye cevap verirler."},{"n":48,"t":"Artık onların daha önceden yalvarıp yakardıkları şeyler kendilerini yalnız bırakmıştır: kendileri için kaçacak bir yer olmadığına iyice kanaat getirirler."},{"n":49,"t":"İnsan özgül ağırlığı olan karşılıklar istemekten asla bıkıp usanmaz; ama başına kötülük bildiği (bir şey) gelecek olsa, bu kez de umudunu yitirip karamsarlığa kapılır."},{"n":50,"t":"Ama uğradığı bu musibetin ardından eğer katımızdan bir rahmet tattıracak olsak, tutar der ki: \"Bu zaten benim hakkımdı; hem Son Saat`in kopacağını da sanmam ya! Bir ihtimal Rabbime döndürülürsem, beni O`nun katında daha güzellerinin beklediğinden kesinlikle eminim.\" Sonuçta inkarda ısrar edenlere elbet yaptıklarını bir bir haber vereceğiz ve onları kesinlikle altında ezilecekleri bir azaba mahkum edeceğiz."},{"n":51,"t":"Ne zaman insana nimetlerimizi bahşetsek yüz çevirir ve yan çizer; ne zaman da başına bir musibet gelse, başlar yalvar yakar uzun uzadıya dualar okumaya."},{"n":52,"t":"De ki: \"Ya bu vahiy Allah katından gelmiş de, buna rağmen siz onu inkar etmişseniz, (neler olacağını) hiç düşündünüz mü? Kim derin bir yabancılaşma içine düşen birinden daha sapık olabilir?\""},{"n":53,"t":"Vakti geldikçe insana, kainatın uçsuz bucaksız ufuklarında ve bizzat kendi iç dünyasında mesajlarımızı göstereceğiz. Ta ki bu vahyin tartışmasız bir gerçek olduğu herkes için ortaya çıksan. Her şeye şahit olan senin Rabbin (insana) yetmedi mi?"},{"n":54,"t":"Bakın, belli ki onlar Rablerinin huzuruna çıkacaklarına ilişkin tereddüt içindedirler! Bakın, şüphe yok ki O her şeyi çepeçevre kuşatandır!"}],[{"n":1,"t":"Ha-Mim"},{"n":2,"t":"`Ayn-Sin-Kaf!"},{"n":3,"t":"Her işinde tek mükemmel olan, her hükmünde tam isabet bulunan Allah, sana ve senden öncekilere hakikati işte böyle vahyediyor."},{"n":4,"t":"Göklerde ve yerde ne varsa, hepsi onundur; O aşkın yüceliğiyle görünmeyen varlıkların da, azamet ve heybetiyle görünen varlıkların da ötesindedir."},{"n":5,"t":"Neredeyse gökler en tepesinden parçalanırcasına sarsılır; melekler ise Rablerinin sonsuz yüceliğini hamd ile dile getirir ve yeryüzünde yaşayan herkes için af dilenir. Bakın, şüphesiz Allah, evet yalnız O`dur mutlak bağış, sonsuz rahmet kaynağı."},{"n":6,"t":"Zatından başkalarını sığınılacak dost edinenleri Allah sürekli gözetim altında tutmaktadır; sen onların tercihinden asla sorumlu değilsin!"},{"n":7,"t":"İşte Biz sana, hem Şehirlerin Anası`nı ve onun çevresindekileri uyarman, hem de kendisinde asla kuşku bulunmayan Toplanma Günü`ne karşı (insanlığı) ikaz etmen için Arapça bir Kur`an vahyettik: (Sonuçta) bir kısmı cennete girecek, bir kısmı da ateşe."},{"n":8,"t":"Ama eğer Allah dileseydi onları tek bir ümmet yapardı: Ne var ki O, (isteyeni) rahmetine kavuşturmayı diler; zalimler ise ne candan bir dost, ne de bir yardımcı bulabilecekler."},{"n":9,"t":"Yoksa onlar O`nun dışında hamiler mi edinmeye kalkıyorlar? Oysa ki asıl himaye edici Allah`tır; zira ölüye can veren sadece O`dur, her şeye kadir olan da o`dur."},{"n":10,"t":"Bu alanda ayrılığa düştüğünüz her hususta hüküm Allah`a aittir. (De ki): \"Bakın, işte benim Rabbim olan Allah budur: yalnız O`na güvendim ve her daim O`na yönelirim.\""},{"n":11,"t":"O, gökleri ve yeri yoktan var edendir. Nasıl ki hayvanları çiftler halinde yaratmışsa, size de kendi türünüzden eşler vermiştir; ve sizi bu sayede çoğaltmaktadır. (Ama) hiçbir şey O`na benzemez; ve O her şeyi işiten, her şeyi görendir."},{"n":12,"t":"Göklerin ve yerin anahtarları O`na aittir: O dilediğine rızkı bol verir, dilediğine sınırlandırır: çünkü O her şeyi her yönüyle bilendir."},{"n":13,"t":"O, dinin (esasa ilişkin) kısmından Nuh`a bildirdiğini -ki o sana vahyettiğimiz, dahası İbrahim, Musa ve İsa`ya da bildirdiğimizdir- size de yol kıldı ki, dini çığrından çıkarmayın ve bu konuda tefrikaya düşmeyin! Şirk koşanlara ağır gelen, işte onları kendisine çağırdığın bu ilkedir: Allah dilediğini seçip kendisine yaklaştırır, kendisine yöneleni de doğru yola yöneltir."},{"n":14,"t":"Onlar, hakikatin bilgisi kendilerine ulaştıktan sonra, sırf aralarındaki kıskançlık yüzünden birbirlerine düştüler: Ve eğer Rabbin tarafından daha önceden belirli bir vadeye kadar ertelendiğine dair bir yasa konmasaydı, haklarındaki hüküm hemen infaz edilirdi. İşte onların ardından gelen (eski) vahyin (son) varisleri de, bu (vahiy)den dolayı tereddütle karışık bir şüphe içindedirler."},{"n":15,"t":"İşte bu yüzden sen (durup dinlenmeden hakikate) çağır ve emrolduğun gibi dosdoğru ol! Onların keyfi taleplerine uyma ve de ki: \"Ben Allah tarafından indirilen her tür vahye inandım; ben aranızda dengeyi sağlamakla emrolundum; Allah bizim de Rabbimiz, sizin de Rabbinizdir; bizim yaptıklarımızın sonucu bizi bulacak, sizin yaptıklarınızın sonucu da sizi bulacaktır; bizimle sizin aranızda tartışmanın bir yararı yok: Allah hepimizi bir araya getirecektir: zira varış sadece O`nadır.\""},{"n":16,"t":"Bir de O`nun çağrısı kabul edildikten sonra hala Allah hakkında tartışanlar var: Onların itirazları Rableri katında tümden geçersizdir; başlarına (O`ndan) bir gazap çökecektir ve onları şiddetli bir azap beklemektedir."},{"n":17,"t":"O Allah ki, indirdiği vahiylerle hem hakikati ortaya sermiş hem de (adil ve mutedil) ölçüp tartacak (bir tasavvur) inşa etmiştir; hem sen (ey muhatab), nerden bileceksin, belki de Son Saat çok yakındır!"},{"n":18,"t":"Ona inanmayan kimseler, onun çabuk gelmesini isteyenlerdir; iman edenlerinse ondan dolayı yürekleri titrer ve bilirler ki o hakikatin ta kendisidir. Bakın! Son Saat hakkında kuşku yayan kimseler, derin bir sapıklığa gömülmüşlerdir."},{"n":19,"t":"Allah kullarına karşı sonsuz lütuf sahibidir; dilediğine (dilediği) rızkı verir: zira O mutlak güç, sınırsız yücelik sahibidir."},{"n":20,"t":"Kim ahiret kazancını elde etmek isterse, onun bu alandaki yatırım (şevkini) artırırız; kim de bu dünya kazancını elde etmek isterse, ona da onu veririz: ama onun ahirette bir payı olmaz."},{"n":21,"t":"Yoksa onların, Allah`ın izin vermediği şeyleri kendileri için dinin koyduğu şer`i bir kural haline getiren (Allah`a) ortak yaptıkları güçler mi var? Eğer konulmuş kesin bir yasa olmasaydı, haklarında hüküm hemen infaz edilirdi: şu kesin ki, zalimleri (ahirette) can yakıcı bir azap beklemektedir."},{"n":22,"t":"(O gün) kazandıkları yüzünden zalimlerin korkudan titrediklerini görürsün; ama korktukları başlarına gelmiştir bir kere. Ne ki iman eden ve Allah`ın razı olduğu eylem üretenler, cennetlerin (kişiyi) mest eden köşelerinde olacaklar; onlar Rablerinin katında dilediklerine nail olacaklar: Bu, işte budur muhteşem lütuf!"},{"n":23,"t":"İşte bu, Allah`ın iman eden ve o imana uygun eylem üreten kullarına verdiği müjdedir. De ki (ey Peygamber): \"Bu davete karşılık sizden bir ücret istemiyorum; sadece (Allah`a) yakınlık hususunda tam bir ilgi ve sevgi (uyandırmak) istiyorum!\" Her kim bir güzelliği bedel ödeyerek gerçekleştirirse, Biz ona daha fazla güzellikler bahşederiz: şüphesiz Allah emsalsiz bir bağışlayıcıdır, şükre hadsiz hesapsız bir karşılık veren tek otoritedir."},{"n":24,"t":"Yoksa, \"Uydurduğu yalanı Allah`a isnat etmek suretiyle iftira etti\" mi diyorlar? Fakat Allah dilerse senin kalbini de mühürleyebilir. Evet, Allah batılı siler hakkı kendi sözleriyle ortaya koyar: Şüphesiz O göğüslerin en mahrem sırlarını bilendir."},{"n":25,"t":"Ne var ki O kullarının tevbelerini kabul eder, günahlarını affeder ve yaptıklarınızı bilir;"},{"n":26,"t":"iman edip o imana uygun davranışta bulunanların (dualarını) kabul eder ve kendi lutfundan onların payını artırır; ama hakkı inkar edenleri çetin bir azap beklemektedir."},{"n":27,"t":"Ve eğer Allah kullarına rızkı bol bol verseydi, elbet yeryüzünde azıp saparlardı; lakin O dilediğine akıl sır ermez bir ölçüyle indirmektedir: çünkü O kullarının her halinden haberdardır, her şeyi tarifsiz bir görüşle görmektedir."},{"n":28,"t":"Ve O, (insanlar) tüm umutlarını yitirdikten sonra yağmuru indirir ve rahmetini yayar: zira O`dur (insanların) gerçek velisi, hamd O`na mahsustur."},{"n":29,"t":"Gökleri ve yeri yaratması, bunlarda yaşayan her türden yürüyen canlılar üretmesi O`nun delillerindendir: Ve O, dilediği zaman onları kendi katında toplama gücüne de sahiptir."},{"n":30,"t":"Başınıza gelen her musibet, kendi ellerinizle yaptıklarınızın sonucudur; üstelik O bir çoğunu da affetmektedir."},{"n":31,"t":"Siz O`nu daha yeryüzünde atlatmaktan acizsiniz; (ahirette) ise Allah dışında ne candan bir dost, ne de işe yarar bir yardımcı bulacaksınız."},{"n":32,"t":"Denizde süzülerek giden dağlar gibi gemiler de O`nun delillerindendir;"},{"n":33,"t":"Dilerse rüzgarı kesiverir de, o zaman denizin üzerinde hareketsiz kala kalırlar: şüphesiz bunda da her daim sabreden ve şükrü eda etmek için çaba harcayan herkes için ibretler vardır."},{"n":34,"t":"Bir ihtimal onları kazançlarıyla birlikte helak da edebilir; ne ki bir çoğunu affetmektedir."},{"n":35,"t":"Ve ayetlerimiz hakkında polemik yapanlar, asla sığınacak bir yer bulamayacaklarını iyi bilmelidirler."},{"n":36,"t":"Size verdiğimiz her şey, şu dünya hayatının kısa vadeli bir hazzıdır; ama Allah katında bulunan daha değerli, daha kalıcıdır. Bu, iman eden ve Rablerine güvenen kimseler için böyledir:"},{"n":37,"t":"İşte onlar, büyük günahlardan ve hayasızca davranışlardan kaçınırlar, dahası öfkeli zamanlarında bile affetme (erdemini) gösterirler."},{"n":38,"t":"Yine onlar Rablerinin (davetine) koşarlar, namazı hakkını vererek eda ederler, toplumsal işlerini aralarında danışma yoluyla görürler ve kendilerine rızık olarak verdiklerimizden harcarlar;"},{"n":39,"t":"yine onlar, haksız bir saldırıya muhatap olduklarında meşru müdaafa için dayanışma sergilerler."},{"n":40,"t":"Ama kötülüğün cezası, ancak ona denk bir karşılık olabilir; ne var ki kim affeder ve barış yaparsa, işte onun mükafatı Allah`a aittir: Şüphe yok ki O, zalimleri asla sevmez."},{"n":41,"t":"Haksız bir saldırıya karşı meşru müdafaa dayanışması sergileyenlere gelince: onlar hiçbir yolla sorumlu tutulamazlar"},{"n":42,"t":"Sorumlu olanlar, sadece insanlara zulmeden ve yeryüzünde haksız yere güç kullanıp saldırganlık yapan kimselerdir: Onları acıklı bir azap beklemektedir."},{"n":43,"t":"Yine de kim sabreder ve affederse, iyi bilsin ki bu kararlılık ve direnç isteyen (büyük) bir davranıştır."},{"n":44,"t":"Allah kimin sapmasına (izin) verirse, artık onun için candan bir dost bulunmaz; ve sen bu zalimlerin azabı gördüklerinde, \"Geri dönüşün bir yolu yok mu?\" dediklerini bir görmelisin."},{"n":45,"t":"Yine sen onları, zilletten iki büklüm vaziyette, etrafı feri kaçmış gözlerle ve kaçamak bakışlarla süzerek (ateşe) atılırlarken bir izlemelisin! Zaten iman edenler de: \"Kıyamet Günü kaybedenler, hem kendilerini hem de takipçilerini mahvedenlerdir\" demişlerdi. Bakın, işte bu zalimler kalıcı bir azaba mahkum olacaklar;"},{"n":46,"t":"ve Allah`a karşı onlara yardım eden candan bir dost olmayacak: zira Allah kimin sapmasına izin verirse, onun için hiçbir çıkış yolu kalmaz."},{"n":47,"t":"(Ey insanlar!) Allah`ın fermanıyla geri dönüşün mümkün olmadığı gün gelmeden önce Rabbinizin davetine uyun! O gün ne sığınacağınız bir yer bulabilirsiniz, ne de delilleri karartabilirsiniz."},{"n":48,"t":"Ne ki eğer onlar yüz çevirirlerse, unutma ki seni onların muhafızı olarak göndermedik: sana düşen sadece mesajı ulaştırmaktır. Ve Biz ne zaman insana katımızdan ikramda bulunsak onunla gurur duyar, ne zaman da yaptıkları yüzünden başına bir musibet gelse, bu kez de insan kıymet bilmez bir nankör olup çıkar."},{"n":49,"t":"Göklerin ve yerin hükümranlığı Allah`a aittir, O dilediğini yaratır: dilediğine kız çocukları bağışlar ve dilediğine de erkek çocukları bağışlar;"},{"n":50,"t":"veya (dilediğine) kızlar ve erkekleri birlikte bağışlar; dilediğini de çocuktan mahrum eder: çünkü O her şeyi bilendir, her şeye güç yetirendir."},{"n":51,"t":"Hiçbir ölümlüyle Allah`ın (yüz yüze) konuşması olacak şey değildir; ancak O ani ve içe tesir eden ilahi bir ilham yoluyla, veya bir perde arkasından, ya da O`nun dilediği şeyi yine O`nun izniyle bildirsin diye bir elçi göndermek suretiyle konuşur: Şüphesiz O aşkın ve yücedir, her hükmünde tam isabet sahibidir."},{"n":52,"t":"Ve (ey Nebi,) işte sana da kendi emrimizden hayat bahşeden bir mesaj vahyettik; sen daha önce kitap nedir iman nedir bilmezdin: Fakat şimdi onu bir nur kıldık ki, kullarımızdan dilediklerimizi onunla doğru yola yöneltelim. Ve şüphe yok ki sen de insanları dosdoğru bir yola yöneltmektesin;"},{"n":53,"t":"göklerde ve yerdeki her şeyin asli sahibi olan Allah`ın yoluna... Bakın: Her iş döner dolaşır sonunda mutlaka Allah`a varır!"}],[{"n":1,"t":"Ha-mim!"},{"n":2,"t":"Özünde açık ve hakikati açıklayıcı olan bu kitabın değerini bilin!"},{"n":3,"t":"Ki zaten Biz, onu anlayabilesiniz diye Arapça bir hitap kıldık."},{"n":4,"t":"Şüphe yok ki o, katımızda bulunan ana kitapda kayıtlıdır; elbet pek değerlidir o, sonuç itibarıyla tam isabet kaydeden hükümlerle doludur."},{"n":5,"t":"Siz değerleri hoyratça harcayan bir toplumsunuz diye bu uyarıcı vahyi sizden geri mi çekelim?"},{"n":6,"t":"Hem öncekilere de çok sayıda peygamber göndermiştik."},{"n":7,"t":"Ama kendilerine gönderilen her peygamberle alay etmiştiler."},{"n":8,"t":"Sonunda, şunlardan daha güçlü kuvvetli oldukları (halde) onları da helak ettik; öncekilerin meselleri daha önce geçmişti."},{"n":9,"t":"Eğer onlara sormuş olsaydın \"Gökleri ve yeri kim yarattı?\" diye, elbet onlar da \"Mutlak üstün ve yüce olan, eşsiz bilgi sahibi yarattı!\" derlerdi."},{"n":10,"t":"(İşte) yeri sizin için beşik yapan da, yolunuzu bulasınız diye orada sizin için yollar var eden de O`dur."},{"n":11,"t":"Gökten suyu bir ölçüye göre sürekli indiren de O`dur: Bunun sonunda Biz (nasıl) ölü toprağı yeniden diriltiyorsak, işte siz de (öldükten sonra) böyle çıkarılacaksınız."},{"n":12,"t":"Ve bütün (varlığı) çift kutuplu ve zıddıyla yaratan O`dur; başta gemiler ve hayvanlar olmak üzere, bindiğiniz her şeyi var eden O`dur:"},{"n":13,"t":"Bu sayede sırtlarına kurulup hükmedesiniz; ve onlara hükmettiğiniz her zaman da, Rabbinizin nimetini anıp şöyle diyesiniz: \"Bütün bunları bizim yararımıza bir yasaya bağlayan Allah`ın şanı ne yücedir; aksi halde bizim gücümüz buna asla yetmezdi."},{"n":14,"t":"Nihayet şu kesin ki biz, elbet Rabbimize döneceğiz!\""},{"n":15,"t":"Ama kalkarlar, kullarından birini O`ndan bir parçaymış gibi telakki ederler: Şu bir gerçek ki, (bunu yapan) insan katmerli bir nankörlük içindedir."},{"n":16,"t":"Yoksa O, yarattıklarından kız olanları kendisine ayırdı da, erkekleri size mi bıraktı?"},{"n":17,"t":"Ama onlardan birine Rahma`a layık gördüğü (kız çocuğu) müjdelenince, suratı kapkara kesilir ve içini öfkeyle karışık bir hüzün kaplar:"},{"n":18,"t":"\"Ne! Süs püs içinde yetiştirilmekten (başka işe yaramayan) biri daha mı?\" (der) ve kendini belli belirsiz bir çatışmanın içinde bulur."},{"n":19,"t":"Onlar, melekleri, Rahman`ın kulları olan o varlıkları dişi olarak tasavvur ettiler: Yoksa onların yaratılışına tanık mı oldular? Onların bu (yalancı) şahitlikleri kaydedilecek ve (bu yüzden) sorgulanacaklar."},{"n":20,"t":"Bir de onlar \"Eğer Rahman dileseydi asla biz onlara tapmazdık\" dediler; ne ki onlar, buna dair bir bilgiye sahip değiller: onlar sadece sürü güdüsüyle hareket ediyorlar."},{"n":21,"t":"Yoksa Biz bundan önce onlara bir kitap göndermişiz de, bu tavırlarıyla ona sımsıkı sarıldıklarını mı iddia ediyorlar?"},{"n":22,"t":"Ama hayır! Onlar, \"Atalarımızı geleneksel bir inanç üzerinde bulduk; kesinlikle biz de onların izinden giderek doğru yolu bulabiliriz\" diyorlar."},{"n":23,"t":"İşte böyle: Biz senden önce hangi beldeye bir uyarıcı göndermişsek, oranın refah içinde şımarmış seçkinleri hep şunu söylediler: \"Biz atalarımızı geleneksel bir inanç üzerinde bulduk; şu halde bize düşen onların izini takip etmektir.\""},{"n":24,"t":"(O peygamberler de): \"Ne yani, ben size atalarınızı üzerinde bulduğunuz yoldan daha doğrusunu göstersem de mi?\" dedi(ler). Cevapları şu oldu: \"Sizinle gönderildiğini (iddia ettiğiniz) şeylerin gerçekliğini kabul etmiyoruz.\""},{"n":25,"t":"Bunun üzerine, Biz de onlara yaptıklarının acısını tattırdık: Bak(ın) işte, hakikati yalanlayanların sonu nasılmış gör(ün)!"},{"n":26,"t":"Hani İbrahim babasına ve kavmine demişti ki: \"Bakın, sizin taptıklarınıza tapmak benden fersah fersah uzak olsun;"},{"n":27,"t":"Yalnız beni Yaratan hariç: zaten bana kılavuzluk edecek olan da O`dur.\""},{"n":28,"t":"Bunu, ardından gelenler arasında baki kalacak bir söz olarak söyledi; belki (bu hak söze) dönerler diye."},{"n":29,"t":"Ama nerde! Ben, işte şunların ve atalarının, hakikat ve (o hakikati) apaçık ortaya koyan bir elçi gelinceye kadar safa sürmelerine izin verdim."},{"n":30,"t":"Ama hakikat ayaklarına kadar geldiği zaman da, \"Bu bir sihirdir, biz bunu kesinlikle reddediyoruz\" dediler."},{"n":31,"t":"Yine dönüp dediler ki: \"Bu ilahi mesaj, şu iki şehrin en büyük (adam)larından birine inmeli değil miydi?\""},{"n":32,"t":"Rabbinin rahmetini onlar mı paylaştırıyorlar? Asıl onlar arasında, bu dünya hayatındaki geçimlerini paylaştıran ve bir kısmı diğer kısmını istihdam etsin diye birbirlerine farklı oran ve alanlarda üstün kılan Biziz: Rabbinin rahmeti var ya: onların biriktirdiği her şeyden daha değerlidir."},{"n":33,"t":"Ve eğer bütün insanlar (küfür ve nankörlükte ittifak etmiş) tek tip bir toplum halini almayacak olsaydı; Rahman`ı inkar eden şu kimselerin konaklarını gümüşten damlarla ve üzerinde gösteriş yapacakları seyir teraslarıyla donatırdık."},{"n":34,"t":"Dahası evlerini (gümüş) kapılarla, üzerinde yayıla yayıla oturacakları koltuklarla (donatır)"},{"n":35,"t":"ve altına (boğardık). Ne ki bütün bunlar, şu dünya hayatının geçici zevklerinden başka bir şey değildir: Rabbinin katında (daha değerli) olan ahiret ise, sorumluluğunu kuşananlar içindir."},{"n":36,"t":"Kim Rahman`ın uyarı dolu mesajına kusurlu bir gözle bakarsa, ona bir tür şeytanı (öteki kişilik) musallat ederiz de, kendisi onun uydusu haline gelir;"},{"n":37,"t":"artık o onları doğru yoldan çıkarır; berikiler de zanneder ki, kendileri doğru yoldadırlar."},{"n":38,"t":"En sonunda çıkıp huzurumuza geldiği zaman, (şeytani kişiliğine) der ki: \"N`olaydı, keşke benimle senin aranda doğuyla batı kadar bir mesafe olaydı. Meğer (uydusu olduğum) yoldaş, ne kadar da berbatmış."},{"n":39,"t":"Ama o gün bunun size hiçbir faydası olmaz; madem zulmettiniz, şimdi de azabı paylaşın!"},{"n":40,"t":"Şimdi sen (ey Nebi), sağıra işittirebilir, ya da köre(lmiş bir kalbe) doğru yolu gösterebilir misin; yani, açıkca derin bir sapıklığa gömülüp orada karar kılan birine?"},{"n":41,"t":"Biz ister seni çekip (katımıza) alır daha sonra onlardan öcümüzü alırız;"},{"n":42,"t":"(istersek, onları tehdit ettiğimiz (azabı) sana da gösteririz: Her durumda Biz, elbette onları alt edecek bir güce sahibiz."},{"n":43,"t":"Şu halde sana vahyedilene sımsıkı sarıl: çünkü sen dosdoğru bir yol üzeresin."},{"n":44,"t":"Kuşkusuz bu (vahiy), senin ve kavmin için bir şeref ve itibar kaynağıdır: fakat zamanı gelince hepiniz (ona karşı aldığınız tutuma göre) hesaba çekileceksiniz."},{"n":45,"t":"Senden önce gönderdiğimiz elçilerimizin (hayatlarını) soruştur; bak bakalım, hiç Rahman`dan başka tapınılacak ilahlar tayin etmiş miyiz?"},{"n":46,"t":"Doğrusu, Musa`yı mucizevi mesajlarımızla Firavun ve kadrosuna da böyle göndermiştik ve demişti ki: \"Bakın, ben alemlerin Rabbinin elçisiyim.\""},{"n":47,"t":"Fakat ardından, onların önüne mucizevi ayetlerimizi sürünce, onlar hemen alay etmeye başladılar."},{"n":48,"t":"Oysa ki onlara gösterdiğimiz her mucizevi ayet bir öncekinden daha büyüktü: Bir de onları, belki dönerler diye bela(lar)la kuşattık."},{"n":49,"t":"Ve \"Sen ey sihirbaz! Seninle yaptığı sözleşme hatırına, Rabbine bizim için yalvar: kesinlikle biz artık doğru yola yöneleceğiz!\" diye yalvardılar."},{"n":50,"t":"Ama cezayı kaldırır kaldırmaz derhal sözlerinden caydılar."},{"n":51,"t":"Derken Firavun, kavminin arasındayken \"Ey ulusum!\" diye seslendi; \"Mısır`ın hakimiyeti bana ait değil mi? Bütün bu akarsular (ayağımın) altından akmıyor mu? Ne yani, bunu da mı görmüyorsunuz?"},{"n":52,"t":"Yoksa, ne demek istediğini bile açık seçik anlatamayan şu değersiz adamdan daha iyi değil miyim?"},{"n":53,"t":"Hem, neden ona altın künyeler bahşedilmemiş yada beraberinde saf saf dizili melekler gelmemiş?\""},{"n":54,"t":"İşte böylece Firavun kavmini tahrik etti; onlar da bu tahrike kapıldılar: Zaten onlar öteden beri yoldan çıkmış bir kavimdiler."},{"n":55,"t":"Bizim gazabımızı davet ettikleri zaman, onlara yaptıklarının acısını tattırdık ve topunu boğulmaya terk ettik."},{"n":56,"t":"Nihayet onları sonraki nesiller için, geçmişin (acı) hatırası ve ibret vesikası kıldık."},{"n":57,"t":"Ne zaman Meryem`in oğlu örneği gündeme getirilse, senin kavmin bu yüzden başlar şamata yapmaya;"},{"n":58,"t":"ve \"Bizim ilahlarımız mı daha değerli, yoksa O mu?\" derler. Onlar bu karşılaştırmayı, seninle sadece polemiğe girmek için yaparlar: Kesinlikle evet, gerçekte onlar, ağzı iyi laf yapan bir topluluktur."},{"n":59,"t":"(İsa`ya gelince): O sadece kendisine ihsan ettiğimiz ve İsrailoğullarına model kıldığımız bir kuldur."},{"n":60,"t":"Ve eğer isteseydik, elbet sizi de birbiri ardınca gelen melekler yapabilirdik."},{"n":61,"t":"İyi bilin ki o (Kur`an) Son Saat`in (geleceğine) ilişkin tarifsiz bir bilgi kaynağıdır; şu halde bu konuda asla şüpheye düşmeyin ve Bana uyun: İşte bu dosdoğru yoldur!"},{"n":62,"t":"Şeytanın sizi saptırmasına izin vermeyin: çünkü o, sizin apaçık düşmanınızdır!"},{"n":63,"t":"İsa hakikatin apaçık belgeleriyle geldiğinde dedi ki: \"Ben size hikmetle, hakkında tartıştığınız bazı konuları açıklamak için geldim; artık Allah`a karşı sorumululuk bilinciyle davranın ve bana uyun!"},{"n":64,"t":"Elbet Allah benim Rabbimdir, sizin de Rabbiniz yalnızca O`dur; artık sadece O`na kulluk edin: bu, dosdoğru bir yoldur."},{"n":65,"t":"Fakat onlar arasından çıkan hizipler birbirleriyle anlaşmazlığa düştüler: Artık, acı bir günün azabından dolayı yazıklar olsun zulme gömülüp giden o kimselere!"},{"n":66,"t":"Şimdi onlar, kendileri farkında değilken, ansızın başlarına gelecek olan Son Saat dışında bir şey mi gözlüyorlar?"},{"n":67,"t":"Can dostlar o gün birbirlerine düşman olacak; sadece sorumluluk bilincini kuşananlar hariç."},{"n":68,"t":"(Allah onlara diyecek ki): \"Ey kullarım! Bu gün ne gelecekten korkmanıza gerek var, ne de geçmiş için üzülmenize!"},{"n":69,"t":"(Ey) ayetlerimize iman eden ve kayıtsız şartsız teslim olanlar:"},{"n":70,"t":"Siz ve eşleriniz, ruha safa veren bir musiki eşliğinde girin cennete!\""},{"n":71,"t":"Orada, huzurlarınızda, altın tepsilerle kupalar dolaştırılacak; orada canlarının çektiği her şeyi ve gözleri kamaştıran (tanımsız) hazzı bulacaklar."},{"n":72,"t":"İşte, yapa geldikleriniz sayesinde maliki olduğunuz cennet böyledir:"},{"n":73,"t":"Orada (amellerinizin) meyvelerini bol bol derecek, onlardan yiyeceksiniz."},{"n":74,"t":"Ne var ki günahı hayat tarzı haline getirenler, cehennem azabı içinde yerleşip kalacaklar."},{"n":75,"t":"Onlardan (azap) hiç hafifletilmeyecek ve onlar derin bir umutsuzluğa kapılacaklar;"},{"n":76,"t":"Ne ki, onlara haksızlık eden Biz değiliz, fakat asıl onlar kendi kendilerine haksızlık ediyorlar-"},{"n":77,"t":"ve şöyle yalvaracaklar: \"Ey cehennemin bekçisi! Rabbine söyle de bizim işimizi bitirsin!\" O şöyle cevap verecek: \"Şunu kafanıza sokun: siz, kalıcısınız!\""},{"n":78,"t":"Doğrusu Biz, hakikati ayağınıza kadar getirmiştik: Fakat bir çoğunuz hakikatten hiç hoşlanmadınız."},{"n":79,"t":"Yoksa, işin (gerçeği) hakkında kararı onlar mı verecekler? Hayır, asıl karar verici Biziz;"},{"n":80,"t":"Yoksa onlar, içlerinde sakladıklarını ve gizli kapaklı konuşmalarını duymadığımızı mı sanıyorlar? Aksine duyarız! Üstelik, elçilerimiz kayda (bile) geçirirler."},{"n":81,"t":"De ki (ey peygamber): \"Eğer Rahman bir erkek çocuğu sahibi olsaydı, ona ilk ben ibadet ederdim."},{"n":82,"t":"Göklerin ve yerin Rabbi -yüce hükümranlık makamının Rabbi- onların yakıştırdığı her şeyden münezzeh ve beridir.\""},{"n":83,"t":"Artık onları bırak, geleceği vaad olunan günlerine kavuşuncaya kadar lafazanlıkla oyalansınlar ve (kelimelerle) oynamayı sürdürsünler."},{"n":84,"t":"Zira gökte de ilah olan yerde de ilah olan yalnızca O`dur; ve O her hükmünde tam isabet sahibidir, her şeyi bilendir."},{"n":85,"t":"Göklerin, yerin ve bu ikisi arasındakilerin mülkü kendisine ait olan Allah ne yüce bir bereket kaynağıdır: Son Saat`in bilgisi sadece O`nun katındadır ve dönüş yalnızca O`nadır."},{"n":86,"t":"O`ndan başka, yalvarıp yakardıkları varlıklar (yaşarken) hakikate şahitlik yapmış ve (Allah`ın eşsiz ve benzersiz) olduğunu bilenler dışında (Hesap Günü) hiç kimseye şefaat edecek güce sahip değiller."},{"n":87,"t":"Ve eğer onlara kendilerini kimin yarattığını sorsan, hiç tereddütsüz \"Allah\" derler: Şu halde, nasıl da savruluyorlar!"},{"n":88,"t":"Ve (O Elçi`sinin) şöyle diyeceğini de (bilir): \"Ya Rabbi! İşte bunlar, inanmamakta direnen bir kavimdi.\""},{"n":89,"t":"Fakat sen (verdikleri selamı) güzel bir karşılıkla al, yani \"(Size de) selam olsun!\" de. Nasıl olsa zamanı geldiğinde (gerçeği) öğrenecekler."}],[{"n":1,"t":"Ha-Mim!"},{"n":2,"t":"Özünde açık ve hakikati açıklayıcı olan bu kitabın değerini bilin!"},{"n":3,"t":"Evet, onu mübarek bir gecede Biz indir(meye başla)dık; zaten, baştan beri (vahiyle) uyaran da Bizdik."},{"n":4,"t":"O gece, (iyi ve kötü) her iş ayrıştırılarak hikmetli bir hükme bağlanır,"},{"n":5,"t":"tarafımızdan verilmiş bir emirle: elbet Biz, evet peygamberleri gönderen de Bizdik,"},{"n":6,"t":"Rabbinin rahmeti sayesinde. Şüphesiz yalnızca O`dur her şeyi işiten, her şeyi bilen O`dur."},{"n":7,"t":"Eğer inandığınız değerlerden mutmain olsaydınız, (yakinen bilirdiniz) ki O göklerin, yerin ve bunlar arasındakilerin yegane Rabbidir."},{"n":8,"t":"O`ndan başka ilah yoktur; hayatı ve ölümü yaratan (Allah) sizin de Rabbinizdir, önden giden atalarınızın da Rabbidir."},{"n":9,"t":"Ama nerde! Onlar, şüphe bataklığında oyalanıp duruyorlar."},{"n":10,"t":"Şu halde, göğün (felaket) taşıyan bir dumanla kaplanacağı günü bekle!"},{"n":11,"t":"(O duman) bütün insanları bürüyecek (ve inkarcılar haykıracak): \"Acıklı azap işte bu!"},{"n":12,"t":"Rabbimiz! Bu azabı bizden kaldır, çünkü biz artık inanmış bulunuyoruz!\""},{"n":13,"t":"Şimdi bu hatırlama, onlara nasıl bir yarar sağlar ki? Zira kendilerine hakikati apaçık ortaya koyan bir elçi gelmişti de,"},{"n":14,"t":"Sonra onlar yüz çevirmiş ve demişlerdi ki: \"O (başkalarınca) doldurulmuş delinin teki.\""},{"n":15,"t":"Elbet Biz cezayı bir süreliğine askıya alacağız, fakat siz yine (eski halinize) döneceksiniz."},{"n":16,"t":"Kapana kıstırıp enselediğimiz büyük gün gelip çatınca da, her halükarda yaptıklarınızın acısını size tattıracağız."},{"n":17,"t":"Doğrusu Biz, onlardan önce de Firavun kavmini sınamıştık. Onlara seçkin bir elçi gelmiş"},{"n":18,"t":"ve (demişti) ki: \"Bana gelin ey Allah`ın kulları! Ben size gönderilmiş güvenilir bir elçiyim."},{"n":19,"t":"Allah`a karşı küstahlaşmayın! Benim size hakikatin açık delilleriyle geldiğimi aklınızdan çıkarmayın!"},{"n":20,"t":"İyi bilin ki ben, sizin bana yönelik saldırınızdan benim de sizin de Rabbiniz olan (Allah`a) sığınıyorum."},{"n":21,"t":"Ama eğer bana inanmıyorsanız, bari yolumdan çekilin!\""},{"n":22,"t":"Olan oldu, o (da) Rabbine şöyle şikayet etti: \"İşte bunların günaha batmış bir toplum olduğu kesinleşmiştir.\""},{"n":23,"t":"(Rabbi ona) \"Kullarımla birlikte geceleyin yola düş!\" (dedi), \"Ama unutmayın ki, takip edileceksiniz."},{"n":24,"t":"Ziyanı yok, sen denizi rahat bir biçimde terk et! Onlar hakkındaki karar kesin: o ordu mutlaka boğulacak!\""},{"n":25,"t":"Geriye nice nice has bahçeler ve su kaynakları bıraktılar;"},{"n":26,"t":"ve bir nice ekili alan ve görkemli eyvan..."},{"n":27,"t":"Dahası, orada mevcut keyif ve sürur verici daha bir nice nimet"},{"n":28,"t":"işte böylece (geride kalmış) oldu. Sonuçta Biz, onların bıraktıklarına başka toplulukları mirasçı kıldık."},{"n":29,"t":"Ne gök ağladı onlara, ne de yer; ve ne de cezaları ertelendi."},{"n":30,"t":"Böylece Biz İsrailoğullarını aşağılayıcı bir beladan kurtarmış olduk;"},{"n":31,"t":"Firavun`dan... Çünkü o, haddini bilmez küstahlardan biriydi."},{"n":32,"t":"Doğrusu onları, akıl sır ermez ilahi bir bilgiye istinaden çağdaşları olan tüm toplumlar içerisinden böyle seçmiştik;"},{"n":33,"t":"ve onlara sınav olduğu ayan açık belli olan mucizevi işaretler ver(miş)tik."},{"n":34,"t":"Bütün bunlara rağmen şu berikiler yine de şöyle diyecekler:"},{"n":35,"t":"\"(Ölüm) şu bizi bekleyen ilk (ve tek) ölümünüzdür ve biz asla bir daha hayata dönmeyeceğiz;"},{"n":36,"t":"ama eğer (bu) iddianızda ısrarlıysanız, haydi (geri) getirin atalarımızı!\""},{"n":37,"t":"Ne yani, onlar günaha gömülüp gittikleri için kendilerini helak ettiğimiz Tubba` kavminden ve onlardan öncekilerden daha mı değerliler?"},{"n":38,"t":"Bakın Biz gökleri, yeri ve bu ikisi arasındakileri oyun olsun diye yaratmadık;"},{"n":39,"t":"lakin bunları, bir başka değil sadece gerçek bir amaç uğruna yarattık; ne var ki onların çoğu bunu kavramıyor."},{"n":40,"t":"Unutmayın ki, hepsinin buluşma zamanı (iyi ile kötünün) birbirinden ayrıldığı gündür."},{"n":41,"t":"O gün ne bir dostun diğer bir dosta yararı dokunacak, ne de kendilerine yardım ulaşacak;"},{"n":42,"t":"Allah`ın rahmet ettiği kimseler müstesna: zira yalnızca O`dur her işinde mükemmel olan, sonsuz merhamet sahibi O`dur."},{"n":43,"t":"Şüphesiz o zakkum ağacı,"},{"n":44,"t":"günahkarların besini olacaktır;"},{"n":45,"t":"tıpkı yanık yağ tortusu gibi karında kaynar,"},{"n":46,"t":"fokurdayarak yakıp kavuran su misali..."},{"n":47,"t":"(Derken emir gelir): \"Tutun onu, yaka paça sürükleyin kışkırtılmış alevlerin ortasına!"},{"n":48,"t":"Sonra baştan ayağa boca edin yürek dağlayan bir (umutsuzluğu ve deyin ki):"},{"n":49,"t":"Tat bakalım; çünkü sen, evet sen hatırlı, saygın biri olmalısın (!)"},{"n":50,"t":"İşin gerçeği, bu, sizin baştan beri `acaba` dediğiniz şeyin ta kendisidir.\""},{"n":51,"t":"Öte yandan Allah`a karşı sorumluluk bilinci taşıyanlar güvenli bir konumda bulunacaklar:"},{"n":52,"t":"cennetlerde ve pınar başlarında..."},{"n":53,"t":"Tarifsiz güzellikte sonsuz özgürlük libası ve altın sırmalı kaftanlar giyip göz göze bakışacaklar."},{"n":54,"t":"İşte böyle olacak. Ve Biz onları sıradışı güzellikte bir bakış, pırıl pırıl (bir kalp) taşıyan eşlerle birleştireceğiz."},{"n":55,"t":"Orada canlarının arzu ettiği her türlü lezzeti güven içinde isteyip tadacaklar."},{"n":56,"t":"Orada ilk ölümlerinden başka bir ölüm tatmayacaklar. Böylece Allah onları dehşet verici bir azaptan korumuş olacak."},{"n":57,"t":"Rabbinin bir lutfudur bu: Bu, işte budur muhteşem başarı!"},{"n":58,"t":"İşte böylece Biz, bu (vahyi) senin dilinle kolaylaştırdık ki düşünüp de ders alabilsinler."},{"n":59,"t":"Artık sen de (yukarıda tanıtılan cennetini) bekle; çünkü ötekiler (yukarıda tanıtılan cehennemlerini) bekliyorlar!"}],[{"n":1,"t":"Ha-Mim!"},{"n":2,"t":"Bu kitabın indirilişi her işinde tek mükemmel olan, her hükmünde tam isabet kaydeden Allah katındadır."},{"n":3,"t":"Elbet göklerde ve yerde inanmaya gönlü olanlar için sayısız mesajlar vardır."},{"n":4,"t":"Hem sizin yaratılışınızda, hem de O`nun yeryüzüne yaydığı diğer tüm yürüyen canlı türlerinde gönülden inanacaklar için tarifsiz mesajlar vardır."},{"n":5,"t":"Aklını kullanan bir topluluk için gece ve gündüzün birbiri ardınca gelişinde, Allah`ın semadan indirerek kendisiyle ölü toprağı dirilttiği rızık vasıtalarında ve rüzgarları çeşitli kılmasında da sayısız mesajlar vardır."},{"n":6,"t":"İşte bunlar, Allah`ın hakikati sana kendisiyle aktardığı ayetlerdir: Peki, Allah ve O`nun ayetleri de değilse, kimden (gelen) hangi habere inanacaklar?"},{"n":7,"t":"Kendini aldatarak günaha gömülenlerin topuna birden yazıklar olsun!"},{"n":8,"t":"(Bu tip) Allah`ın kendisine okunan ayetlerini işitir de, sonra onu hiç işitmemiş gibi küstahça bir direnişi sürdürür: artık böylesini acıklı bir azap ile müjdele!"},{"n":9,"t":"Üstelik bu tipler, ayetlerimizden bazılarının farkına vardığı zaman da başlarlar onunla alay etmeye. İşte böylelerini aşağılayıcı bir azap beklemektedir:"},{"n":10,"t":"cehennem hemen peşlerindedir. Ne kazandıkları şeylerin, ne de Allah`tan başka edindikleri dostların onlara en ufak bir yararı dokunur: zira onları korkunç bir azap beklemektedir."},{"n":11,"t":"(Allah`ın ayetlerini izlemek...) İşte hidayet budur; bir de Rablerinin (kevni ve vahyi) ayetlerini yok sayanlar var: işte onları, (bu) akıl almaz bayağılaşmadan dolayı acınılası bir azap beklemektedir."},{"n":12,"t":"O`nun kanunu sayesinde orada gemiler yol alabilsin diye, yine O`nun lutfundan payınıza düşeni elde edip de şükredebilesiniz diye denizi sizin için bir yasaya bağlayan Allah`tır."},{"n":13,"t":"Yine O, göklerde ve yerde ne varsa hepsini kendi katından (bir bağış olarak) emrinize amade kılmıştır. Elbet bütün bunlarda da düşünen bir toplum için sayısız mesajlar vardır."},{"n":14,"t":"Söyle iman edenlere: Allah`ın Günleri`nin geleceğini arzu etmeyenleri (şimdilik) bağışlasınlar; çünkü O bir toplumu (ancak) ısrarla yaptıklarından dolayı cezalandırır."},{"n":15,"t":"Kim bir iyilik yaparsa, o kendi lehine yapmış olur. Kim de bir kötülük yaparsa, kendi aleyhine yapmış olur. En sonunda dönüp geleceğiniz yer Rabbinizin huzurudur."},{"n":16,"t":"Doğrusu Biz İsrailoğullarına da vahyi, iktidarı ve peygamberliği vermiş, onlara iyi ve temiz rızıklar bahşetmiş ve onları (vahyi hayata taşımakla görevlendirip kendi zamanlarının) tüm toplumlarından üstün tutmuştuk."},{"n":17,"t":"Dahası onlara (tevdi edilen) görevden dolayı açık işaretler vermiştik. Ne ki onlar durdular durdular da, kendilerine bilgi geldikten sonra -sırf aralarındaki kıskançlık yüzünden- ayrılığa düştüler: Şu kesin ki, Rabbin Kıyamet Günü ayrılığa düştükleri her konuda onlar arasında hüküm verecektir."},{"n":18,"t":"Son olarak, seni de bu görevi (hakkıyla ifa edeceğin) bir yol ve yönteme kavuşturduk: o yolu izle, sakın ha (kendini) bilmezlerin keyfi yargılarına uyma!"},{"n":19,"t":"Çünkü onlar, Allah`tan gelecek hiçbir şeyi senden savamazlar! Unutma ki zalimler hep birbirlerinin dostudurlar; Allah ise muttakilerin dostudur."},{"n":20,"t":"Bu (vahiy) insanlık için bir bilinç kaynağıdır; gönülden inananlar için de bir rehber ve bir rahmet membaıdır."},{"n":21,"t":"Yoksa kötülüğün peşinde seğirten tipler, kendilerini -hayatlarında olsun ölümlerinde olsun- iman edip erdemli davrananlarla aynı kefeye koyacağımızı mı sandılar? Ne berbat akıl yürütüyorlar!"},{"n":22,"t":"Ama Allah gökleri ve yeri gerçek bir amaç uğruna yarattı ki, her insan kendi kazandığının karşılığını görebilsin ve hiç kimseye haksızlık yapılmasın."},{"n":23,"t":"Keyfi kanaatini tanrısı yerine koyan ve Allah`ın kişiyi (kendi tercihine ilişkin) bir bilgiye dayalı olarak saptırdığı, kulaklarını ve kalbini mühürlediği, gözlerinin üzerine de tarifsiz bir perde çektiği malum tipleri gözünde canlandırabilir misin? Artık onu Allah`tan başka kim doğru yola ulaştırabilir? Hala düşünüp ders almayacak mısınız?"},{"n":24,"t":"Bir de kalkıp dediler ki: \"Hayat sadece dünya hayatımızdan ibarettir; ölürüz, zira (bir kez) hayata gelmiş bulunuruz; ve bizi sadece zaman yok eder. Ama onlar bu hususta hiçbir bilgiye sahip değiller, onlar sadece (önyargıya dayalı bir) zanna sahiptirler."},{"n":25,"t":"Ve ne zaman ayetlerimiz bütün açıklığıyla önlerine konulsa, tek cevapları şöyle olur: \"Eğer doğru söylüyorsanız atalarımızı getirin!\""},{"n":26,"t":"De ki: \"Hayatınızı bahşeden, ardından ölümünüzü takdir eden Allah`tır. En sonunda sizi geleceğinde kuşku olmayan Kıyamet Günü bir araya getirecektir; fakat insanların çoğu bunun (kaçınılmaz bir sonuç olduğunun) bilincinde değildir.\""},{"n":27,"t":"Ama göklerin ve yerin mülkü Allah`a aittir. Ve kıyamet gerçekleştiği gün, işte o gün, varlığı anlam ve amacından soyutlayanlar kaybedecekler."},{"n":28,"t":"Ve o gün her toplumu zillet içinde diz çökmüş bir halde göreceksin; her toplum kendi hesabını (görmeye) çağrılacak: \"Bugün yapa geldiğiniz her şeyin karşılığını bulacaksınız."},{"n":29,"t":"İşte bunlar Bizdeki kayıtlar; aleyhinize (de) olsa tüm gerçeği size o anlatır: çünkü Biz, yaptığınız her şeyi vaktiyle kayda geçirmiştik.\""},{"n":30,"t":"Öte yandan, iman eden ve erdemli davrananlara gelince: Rableri onları Rahmetine nail edecektir: Bu, işte budur göz kamaştırıcı zafer!"},{"n":31,"t":"İnkarda direnenler var ya! (Onlara şöyle denilecek): \"Mesajlarım size tebliğ edilmemişmiydi? Aksine (edilmişti), ama siz küstahça böbürlenmiş ve günahkar bir toplum olmayı yeğlemiştiniz."},{"n":32,"t":"Size ne zaman, \"Bakın, Allah`ın vaadi gerçekleşecektir ve Son Saat asla kuşku kaldırmaz!\" denilmişse, siz şu cevabı vermiştiniz: \"Bilmiyoruz, `Son Saat` nedir? Ne ki biz onun bir zandan ibaret olduğunu sanıyoruz ve biz (bu konuda) ikna olmuş değiliz.\""},{"n":33,"t":"Onların yaptığı kötülükler (o gün gelince) ayan açık ortaya serilecek ve alay edip durdukları gerçek kendilerini perişan edecektir."},{"n":34,"t":"Ve onlara denilecek ki: \"Siz yüzleşeceğiniz bu günü (dünyada) nasıl unuttunuzsa, biz sizi (ahirette) öyle unutulmaya terk edeceğiz: nihayet varış yeriniz ateştir, size yardım eden hiç kimse de olmayacaktır."},{"n":35,"t":"Durum işte böyle vahimdir; çünkü siz Allah`ın mesajlarını alay konusu ettiniz, zira dünya hayatı sizi fena halde aldatmıştı.\" İşte bu yüzden o gün ne oradan çıkarılacaklar ve ne de bir şey istemeye izin verilecek."},{"n":36,"t":"Hamd göklerin ve yerin Rabbi olan Allah`a mahsustur; alemlerin Rabbine…"},{"n":37,"t":"Göklerde ve yerde erişilmez büyüklük O`na mahsustur: zira O`dur mutlak üstün ve yüce olan, her hükmünde tam isabet kaydeden sadece O`dur."}],[{"n":1,"t":"Ha-mim!"},{"n":2,"t":"Bu kitabın indirilişi, her işinde mükemmel olan, her hükmünde tam isabet sahibi Allah katındandır."},{"n":3,"t":"Biz gökleri, yeri ve o ikisi arasındakileri, ancak gerçek bir anlam ve amaç uğruna -ama sınırlı bir süreliğine yarattık; ne ki inkar eden kimseler uyarıldıkları hakikatten yüz çeviriyorlar."},{"n":4,"t":"De ki: \"Allah'ın astlarından kabul edip de dua ettiğiniz kimselere hiç göz attınız mı? Gösterin bana, onlar yeryüzünün neresinde neyi yaratmışlar? Yoksa onların gökler(in yönetimin)de bir payı mı var? Hadi, bundan önce (inmiş) ilahi bir kelam veya bir bilgi notu getirin bana, eğer iddianızda samimiyseniz!"},{"n":5,"t":"Allah'ı bırakıp da, Kıyamet Günü'ne kadar (duaya) karşılık veremeyecek kimselere, dahası kendisine dua edildiğinin dahi farkında olmayan kimselere yalvarıp yakarandan daha şaşkın ve sapkın biri olabilir mi?"},{"n":6,"t":"Bütün insanlar toplandıkları zaman, (tapınılan kimseler) berikilere can düşman olacaklar ve onların tapınmalarını ısrarla reddecekler."},{"n":7,"t":"Evet ne zaman ayetlerimiz onlara bütün açıklığıyla tebliğ edildiyse, inkar eden kimseler ayaklarına kadar gelen hakikat için \"Bu etkili bir sihirdir!\" dediler."},{"n":8,"t":"Yoksa \"Onu kendisi uydurdu\" mu diyorlar? De ki: \"Eğer onu ben uydurmuş olsaydım, Allah'tan bana gelecek hiçbir (cezayı) başımdan savamazdınız. (Allah) öksesine düştüğünüz bu iftiranın nedenini bilmektedir; benimle sizin aranızda şahit olarak O yeter: iyi ki O mutlak bağış sahibidir, sonsuz merhamet kaynağıdır.\""},{"n":9,"t":"De ki: \"Ben peygamberlerin ilki değilim; kendime de size de ne yapılacağını asla bilmiyorum; ben sadece (vahyi) olduğu gibi beyan eden bir uyarıcıyım.\""},{"n":10,"t":"De ki: \"Düşünsenize bir: ya bu (mesaj) Allah katından gelmiş de buna rağmen siz onu inkar ediyorsanız; üstelik İsrailoğulları'ndan bir şahit kendi gibi birisinin (gönderileceğine) şahitlik yapmış ve ona inanmışken, siz kalkıp küstahça başkaldırmışsanız? Unutmayın ki Allah haddini aşan bir topluma rehberliğini bahşetmez.\""},{"n":11,"t":"Bir de, inkarda direnenler imanda sebat edenler için şöyle derler: \"Eğer o (mesajda) bir hayır olsaydı, şunlar ona bizden önce koşmazlardı.\" Bu söylemle amaçlarına ulaşamayınca da, ister istemez şöyle diyecekler: \"Bu kadim bir sahtekarlık türüdür.\""},{"n":12,"t":"Ne ki bundan önce de (izleyeni inşa eden) önder bir özne ve ilahi bir rahmet olan Musa'nın kitabı vardı; ve bu (Kur'an)da zulmedenlere uyarmak ve iyilere müjde vermek için (önceki vahiyleri) tasdik etmek üzere Arapça olarak indirilmiş ilahi bir kelamdır."},{"n":13,"t":"Elbet \"Rabbimiz Allah'tır\" diyenler ve sonra da tahriklere aldırmadan emredilen yolda sabır ve sebatla yürüyenler için, ne gelecek endişesi vardır, ne geçmiş korkusu;"},{"n":14,"t":"işte onlar cennetliktirler; yaptıklarının bir ödülü olarak orada daimi kalıcıdırlar."},{"n":15,"t":"Biz insana anne babasına karşı iyi davranması talimatını ilettik: annesi onu zahmetle taşıdı ve zahmetle doğurdu. Onun taşınması ve sütten kesilmesi otuz ayı buldu. Nihayet tam olgunluğa erişip kırk yaşına ulaştığında \"Rabbim!\" der, \"Bana ve ana babama sevk ettiğin nimetler için şükretmemi ve rızanı kazanacak iyi ve yararlı işler yapmamı nasip eyle; ve bana bağışladığın neslimi de iyilikte daim eyle: işte ben yüzümü Sana döndüm ve artık ben sana teslim olanlardan biriyim!\""},{"n":16,"t":"İşte bunlar, yaptıklarının en iyilerini kabul edip kötülüklerinin de üstünü çizeceğimiz kimselerdir: Verilmiş olan söze sadakatin bir gereği olarak, cennet ehli arasındaki yerlerini alacaklar."},{"n":17,"t":"Ne ki, (kendisine imanı telkin eden) ana babasına \"İkinize de yuh olsun! Ne yani, benden önce bunca nesil gelip geçtiği halde (hiç biri dirilmemişken) bana diriltileceğimi mi söylüyorsunuz?\" diye çıkışan da var. Ana-baba da Allah'ın yardımına sığınarak (şöyle der): \"Yazıklar olsun sana! Şuna kesinlikle inan ki, Allah'ın vaadi mutlaka gerçekleşecektir.\" Bunun üzerine şöyle der: \"Bunlar eskilerin masallarından başka bir şey değildir.\""},{"n":18,"t":"İşte onlar, haklarında ilahi yasanın gerçekleştiği kimselerdir; kendilerinden önce geçip gitmiş görünür görünmez-bilinir bilinmez iradeli varlıklara dahil olmuşlardır: Şüphesiz kaybeden de onlar olacaktır."},{"n":19,"t":"Her birinin yaptıklarıyla uyumlu bir derecesi bulunacaktır: sonuçta onlar yaptıklarının karşılığını eksiksiz alacaklar ve kendilerine asla haksızlık edilmeyecektir."},{"n":20,"t":"İşte inkarda ısrar edenlerin ateşe takdim edilecekleri o gün (denilecek ki): \"Siz sahip olduğunuz tüm güzellikleri bu dünya hayatında tükettiniz ve onları kısa vadeli bir hazza dönüştürdünüz. Artık bu gün yeryüzünde haksız yere küstahça böbürlendiğiniz ve yoldan çıktığınız için onur kırıcı bir cezaya çarptırılacaksınız."},{"n":21,"t":"Ve Ad kavminin soydaşı (Hud'u) hatırla! Hani o, şu kum tepeleri arasında yaşamış olan kavmi -ki ondan önce de sonra da nice uyarıcılar gelip geçmişti- şöyle uyarmıştı: \"Allah'tan başkasına kulluk etmeyin! Aksi halde ben dehşet verici bir günün azabına uğramanızdan korkarım!\""},{"n":22,"t":"Onlar da: \"Sen bizi ilahlarımızdan soğutmak için mi geldin? Eğer sözüne sadıksan, haydi tehdit ettiğin şeyi getir!\" dediler."},{"n":23,"t":"O, \"Kesin bilgi Allah katındadır; ve ben sadece bana verilen mesajı size iletiyorum; şu da var ki ben, sizi kendini bilmez bir toplum olarak görüyorum\" dedi."},{"n":24,"t":"Derken, yüklü bir bulutun vadilerine doğru yaklaştığını gördüler ve \"Bu bize yağmur getiren bir buluttur\" dediler. Aksine o gelmesini acele istediğiniz şeydir: içinde acıklı bir azabı barındıran bir bela kasırgası..."},{"n":25,"t":"Rabbinin emriyle her şeyi yerle bir etti: nihayet, (harap olmuş) haneleri dışında gözle görülen hiçbir şey kalmadı. Biz, günaha gömülen bir toplumu işte böyle cezalandırırız."},{"n":26,"t":"Doğrusu onlara orada, size burada vermediğimiz kadar güç ve kudret vermiştik. Onların da işitme, görme ve akletme yetileri başlarından belayı savmaya yetmedi; çünkü onlar Allah'ın mesajlarını bile bile inkar etmiştiler: nihayet alay ettikleri şey onları çepeçevre kuşatıp yok etti."},{"n":27,"t":"Doğrusu, çevrenizdeki ülkelerden bir çoğunu da (işte böyle) yok ettik; ama (ondan önce) belki vazgeçerler diye mesajlarımızı çok boyutlu olarak açıklamıştık."},{"n":28,"t":"Bari kendilerini O'na yaklaştırsın diye Allah dışında ilahlık yakıştırdıkları, onlara yardım etselerdi ya! Ne gezer! Onları tanımadılar bile: Bu onların kendi uydurdukları şeylerle kendilerini kandırmalarının sonucuydu."},{"n":29,"t":"Bir zamanlar, cinlerden bir gurubu Kur'an'ı dinlesinler diye sana yönlendirmiştik. Nihayet o (vahye) kavuşur kavuşmaz \"Sükunetle dinleyin!\" demişler, (okuma) biter bitmez de kendi toplumlarının yanına uyarıcılar olarak dönmüşlerdi."},{"n":30,"t":"Onlar \"Ey kavmimiz!\" dediler, \"Biz Musa'dan sonra indirilen ve kendisinden önceki vahyi tasdik eden bir ilahi mesaj dinledik: o vahiy (kendisine uyanı) hakikate ve dosdoğru bir yola yöneltiyor."},{"n":31,"t":"Ey kavmimiz! Allah'ın davetine icabet edin ve O'na iman edin (ki), günahlarınızın üzerini çizip sizi bağışlasın ve sizi elim bir azaptan korusun!"},{"n":32,"t":"Ama kim Allah'ın davetine icabet etmezse, asla O'nu yeryüzünde atlatmış olmaz; ve ona (Allah)tan başka hiçbir dostun yararı dokunmaz: böyleleri fark edilir bir sapıklığın göbeğine düşerler."},{"n":33,"t":"Görmezler mi ki gökleri ve yeri yaratmış ve bunları yaratmakla yorulup bitkin düşmemiş olan Allah, ölülere hayat vermeye elbette güç yetirendir? Yoo! Elbet O her şeye güç yetirendir."},{"n":34,"t":"Ve hakikati inkar eden kimselere ateşe takdim olunurken, \"Ne yani, bu da mı gerçek değil?\" (denileceği) gün, onlar şöyle cevap verecekler: \"Rabbimize andolsun ki (bu hakikatin ta kendisidir)!\" (Allah) buyuracak: \"Haydi, hakikati inkarınıza karşılık tadın malum azabı!\""},{"n":35,"t":"Bundan böyle (ey muhatap), elçilerden kararlılık ve direnç sahibi olanların yaptığı gibi sen de dirençle göğüs ger! Acele ile onların işinin bitirilmesini isteme! (Nasıl olsa) onlar vaad edilen o günü görünce, kendilerini gündüzün tek bir saati dışında sanki dünyada hiç yaşamamış (sayacaklar). Duyurumuz işte budur: Şu halde, hiç sorumsuzca davranan bir toplumdan başkası helak edilir mi?"}],[{"n":1,"t":"İnkarda direnen ve (insanları) Allah yolundan alıkoyanların yaptıklarını, O boşa çıkaracaktır."},{"n":2,"t":"Bir de imanda sebat eden, iyilik yapan ve Rableri tarafından Muhammed`e indirilen hakikate inananlar var: Allah onların günahlarını silecek, tasavvur ve akıllarını (vahiyle) ıslah ve inşa edecektir."},{"n":3,"t":"Bu böyle olacaktır; çünkü inkarda ısrar edenler anlamsız ve amaçsızlığın peşine takılmıştır, imanda sebat edenlerse, Rablerinden gelen hakikate tabi olmuşlardır. İşte Allah insanlara kendi durumlarını böyle açıklamaktadır."},{"n":4,"t":"Artık inkarda direnip (onu dayatanlarla) savaşta karşılaştığınızda, hemen boyunlarına vurun! Nihayet kızışmış bir savaşın sonuna dayandığınızda durmayın, (kalanların) ipini sıkı bağlayın. Fakat daha sonra ya bir lütuf olarak karşılıksız, ya da bir fidye karşılığı serbest bırakın ki, savaş tüm ağır sonuçlarıyla ortadan kalksın: böyle yapın! Ve eğer Allah dileseydi, onların hakkından bizzat gelirdi; fakat bunu (yapmadı) ki, sizi birbirinizle sınayabilsin. Allah yolunda öldürülenlere gelince: Evet (Allah) onların yaptıklarını asla zayi etmeyecektir:"},{"n":5,"t":"Onlara (cennetin) yolunu gösterecek ve kalplerini huzura kavuşturacaktır."},{"n":6,"t":"Nihayet onları kendilerine tarif ettiği cennete koyacaktır."},{"n":7,"t":"Ey imanda sebat edenler! Siz Allah`ın (davasına) yardım ederseniz, O da size yardım eder ve ayaklarınızı sabit tutar."},{"n":8,"t":"Küfürde ısrar edenlere gelince: artık onları helak edici bir yıkım beklemektedir; dahası O, onların yaptıklarını boşa çıkaracaktır."},{"n":9,"t":"Bunun nedeni, onların Allah`ın indirdiğinden nefret etmeleridir; işte bu yüzden (Allah) yaptıklarını heba edecektir."},{"n":10,"t":"Onlar yeryüzünde hiç dolaşmadılar mı; görmediler mi kendilerinden önceki günahkarların sonunun ne olduğunu? Allah onları yerle bir etti; bu kafirleri de bunun bir benzeri beklemektedir."},{"n":11,"t":"Bu böyledir: çünkü Allah imanda sebat edenlerin dostudur; kafirlerin ise dostu bulunmamaktadır."},{"n":12,"t":"Şüphesiz Allah, imanda sebat edip de o imana uygun ıslah edici işler işleyenleri zemininden ırmakların çağladığı cennetlere koyacaktır; ama küfürde direnenler geçici zevklerin peşine takılarak hayvanların yiyip içtiği gibi yiyip içseler de, sonunda ateş onların meskeni olacaktır."},{"n":13,"t":"(Ey Nebi!) Seni yurdundan çıkaran toplumundan çok daha güçlü ve kuvvetli olan nice yurtları helak etmişizdir de, asla onlara yardım eden olmamıştır."},{"n":14,"t":"Hiç Rabbinden (gelen) açık bir delile dayanan kimseyle, kötü eylemleri kendisine güzel görünen ve keyfine göre davranan kimse bir olur mu?"},{"n":15,"t":"Sorumluluk bilinciyle davrananlara vaad edilen, içerisinde zamanla bozulmayan sudan ırmaklar, tadı hiç değişmeyen sütten ırmaklar, içene doyumsuz bir lezzet veren tarifsiz bir meşrubatın çağladığı ırmaklar, saf süzme baldan ırmaklar akan, yine içerisinde tadacakları güzel (davranışlarının) tüm meyveleri ve Rablerinden sınırsız bir bağış bulunan cennetin örneği gibi (bir has bahçeye kavuşan kimse), ateşi mesken tutan ve yakıcı bir (umutsuzluk) içirilip de bağırsakları paramparça olan kimse gibi olur mu?"},{"n":16,"t":"Onların arasından sana kulak verir (gibi) yapanlar var: nihayet senin yanından çıktıklarında, mesajı kavramış olanlara \"Sahi, o demin ne dedi(!)\" diye sorarlar. İşte, Allah`ın kalplerini mühürlediği ve keyiflerine göre davranan kimseler onlardır."},{"n":17,"t":"O doğru yola yönelenlerin hidayetini artırır ve onlara korunma gücü bahşeder."},{"n":18,"t":"Şimdi onlar, Son Saat`in ansızın gelip kendilerini bulmasından başka bir şey mi bekliyorlar? Doğrusu, işte onun tüm alametleri gelmiş bulunuyor: Hal böyleyken, o geldikten sonra (gerçeği) hatırlamak onlara nasıl bir yarar sağlar?"},{"n":19,"t":"Ve (sen ey Nebi): unutma ki Allah`tan başka ilah yoktur! İmdi sen, hem kendi hatan için, hem de mü`min erkekler ve mü`min kadınların (hataları) için af dile! Zira Allah gezip dolaştığınız yeri de, gelip durduğunuz yeri de bilir."},{"n":20,"t":"İman edenler \"(Artık savaşa değinen) bir sure indirilmesi gerekmez mi?\" derler. Fakat içinde savaştan söz edilen hüküm koyucu bir sure indirilince de, kalplerinde hastalık olanların sana ölüm korkusundan baygınlık gelmiş kimsenin bakışı gibi baktıklarını görürsün. Ne ki onlar için en hayırlısı,"},{"n":21,"t":"(vahyi) izlemek ve (emir verilince) de olumlu bir söz söylemektir; ve iş ciddiye bindiği zaman da Allah`a verdikleri söze sadık kalırlarsa, kendileri için elbet çok iyi olur."},{"n":22,"t":"Şimdi siz, eğer sırtınızı dönerseniz, yeryüzünde bozgunculuk çıkarmış, akrabalık bağlarınızı koparmış ve dolayısıyla Allah`a isyan etmiş olmaz mısınız?"},{"n":23,"t":"İşte böyleleri Allah`ın rahmetinden dışladığı, ardından sağırlaştırdığı ve gözlerini körelttiği kimsedirler."},{"n":24,"t":"Onlar hiç Kur`an üzerinde derin derin düşünmezler mi? Yoksa kilit vurulmuş kalplere mi sahipler?"},{"n":25,"t":"Elbet doğru yol kendilerine açıklandıktan sonra ona sırtlarını dönenler olur: Şeytan onların tasavvurlarını yamultmuş ve onlara boş umutlar vaad etmiştir."},{"n":26,"t":"Böyle olmuştur, çünkü onlar Allah`ın indirdiklerinden hoşlanmayanlara \"Bazı konularda sizin talimatınıza uyacağız\" dediler. Ama Allah onların gizlediklerini bilir."},{"n":27,"t":"İyi de, melekler onların suratlarına ve sırtlarına vurarak canlarını alacakları zaman halleri ne olacak?"},{"n":28,"t":"Böyle olacak; çünkü onlar Allah`ın lanetlediği her şeye sarıldılar ve O`nun hoşnutluğundan nefret ettiler: ve böylece (Allah) onların emeklerini boşa çıkardı."},{"n":29,"t":"Yoksa kalplerinde bir tür hastalık bulunanlar, (içlerindeki) derin nefreti Allah`ın açığa çıkarmayacağını mı sandılar?"},{"n":30,"t":"Eğer isteseydik, onları sana kesin gösterirdik ve elbet sen de onları kendi (gerçek) yüzleriyle tanımış olurdun; yine de sen onları, konuşma tarzından tanırsın; ama Allah bütün yaptıklarınızı bilir."},{"n":31,"t":"İçinizden (Allah yolunda) üstün çaba gösteren ve zorluklara karşı direnenleri ortaya koyuncaya kadar sizi mutlaka sınayacağız: zira Biz, sizin bütün iddialarınızı sınarız."},{"n":32,"t":"Şüphesiz inkarda direnen, Allah yolundan alıkoyan ve doğru yol kendilerine açıklandıktan sonra Elçi`yle yollarını ayıran kimseler, Allah`a hiçbir zarar vermiş olmayacaklar; ama (Allah) onların emeklerini boşa çıkaracaktır."},{"n":33,"t":"Siz ey iman edenler! Allah`a itaat edin, Elçi`ye itaat edin ve asla emeklerinizi boşa çıkarmayın!"},{"n":34,"t":"Evet, inkarda direnen ve Allah yolundan alıkoyan sonra da bu inkar üzere ölen kimselere gelince: Allah onları asla bağışlamayacaktır."},{"n":35,"t":"Artık gevşeklik göstermeyin, ama siz üstün durumdaysanız barışa davet edin! Çünkü Allah sizinle beraberdir; ve O sizin emeklerinizi asla zayi etmeyecektir."},{"n":36,"t":"Bu dünya hayatı, (eğer anlam ve amacından soyutlarsanız) bir oyun ve eğlenceden ibaret hale gelir; ama eğer iman eder ve sorumluluk bilinceyle yaşarsanız, karşılığınız size tastamam verilir; üstelik O sizden mallarınızın tümünü de istemez."},{"n":37,"t":"O sizden her şeyinizi istese ve sizi köşeye kıstırsaydı, cimrilik ederdiniz de böylece gizli eğiliminizi ortaya sermiş olurdu."},{"n":38,"t":"Bakın, sizler Allah yolunda infak etmeye çağrıla(rak ödüllendirile)n kimselersiniz. Fakat yine de sizden cimrilik edenler var. Ama kim cimrilik ederse, bilsin ki kendine cimrilik eder: zira Allah kendi kendisine yetendir, ama sizler O`na muhtaçsınız. Sözün özü: eğer (Allah`tan) yüz çevirirseniz, sizin yerinize başka bir topluluk getirir de, onlar sizin gibi yapmazlar."}],[{"n":1,"t":"Elbet sana tartışmasız bir fethin önünü açan Biziz."},{"n":2,"t":"Bu sayede Allah, senin geçmiş ve gelecek tüm hatalarını bağışlayacak; ve sana olan nimetini tamama erdirecek ve seni dosdoğru bir yola yöneltecektir;"},{"n":3,"t":"nihayet Allah seni, saygın ve müstesna bir zafere ulaştıracaktır."},{"n":4,"t":"İmanlarına iman katsınlar diye mü`minlerin kalplerine güven ve sükunet bahşeden O`dur; zira göklerin ve yerin bütün orduları Allah`ın emrine amadedir: ve zaten Allah her şeyi bilmektedir, her hükmünde tam isabet sahibidir."},{"n":5,"t":"Böyle yapmıştır ki, mü`min erkek ve mü`min kadınları zemininden ırmaklar çağlayan cennetlere alsın da, orada yerleşip kalsınlar; ve onların günahlarının üstünü çizsin: ve zaten bu Allah katında büyük bir başarıdır."},{"n":6,"t":"Yine O (diler) ki, Allah hakkında çirkin tasavvurlara sahip münafık erkekler ve münafık kadınları, müşrik erkekler ve müşrik kadınları cezalandırsın; onlar fenalığın girdabını boylasın: zira Allah onlara gazap etmiş ve rahmetinden dışlamıştır. İşte onlar için hazırlamıştır cehennemi; ve orası ne kötü bir son duraktır."},{"n":7,"t":"Evet, göklerin ve yerin bütün orduları Allah`a aittir: ama zaten Allah mutlak izzet, her hükmünde tam isabet sahibidir."},{"n":8,"t":"(Ey Peygamber!) Elbet Biz seni bir şahit, bir müjdeci ve bir uyarıcı olarak gönderdik."},{"n":9,"t":"Şu nedenle ki (ey insanlar); Allah`a ve Elçisine inanasınız, O`nu(n davasını) destekleyip O`na saygıda kusur etmeyesiniz ve sabah akşam O`nun yüceliğini dillendiresiniz."},{"n":10,"t":"Sana biat edenler gerçekte yalnız Allah`a biat etmişlerdir: Allah`ın (yardım) eli, onların (biat için kenetlenen) elleri üzerindedir: Bundan böyle kim ahdinden dönerse, iyi bilsin ki o sadece kendi aleyhine dönmüş olur; kim de Allah`a verdiği ahde sadık kalırsa, O ona muhteşem bir ödül ihsan edecektir."},{"n":11,"t":"Geride kalan bedeviler, \"Mallarımız ve çocuklarımız bizi (sana katılmaktan) alıkoydu; artık Allah`tan bizim için af dile!\" diyecekler. Onlar kalplerinde olmayan şeyi dile getiriyorlar. De ki: \"Peki, şayet Allah size bir zarar vermeyi veya bir yarar sağlamayı dilemiş olsa, O`nun sizin için takdir ettiği şeye kim engel olabilir? Elbette hiç kimse! Ki zaten Allah yaptıklarınızdan ayrıntısıyla haberdardır."},{"n":12,"t":"Aksine sizler, Rasul`ün ve mü`minlerin bir daha asla ailelerine kavuşamayacaklarını zannetmiştiniz; ve böyle düşünmek size pek cazip görünmüştü. İşte böyle berbat bir zanna kapıldınız da, sonunda kredisi tükenmiş bir toplum olup çıktınız."},{"n":13,"t":"Ama kim Allah ve Rasulüne inanmazsa, iyi bilsin ki Biz inkarcılar için kışkırtılmış bir ateş hazırlamışızdır."},{"n":14,"t":"Göklerin ve yerin hükümranlığı Allah`a aittir; O dilediğini bağışlar, dilediğini de cezalandırır: Ama Allah zaten tarifsiz bir bağış, eşsiz bir merhamet kaynağıdır."},{"n":15,"t":"Yakın gelecekte, ganimet vaad eden bir savaşa çıktığınızda, (şimdi) geride kalanlar, \"Bırakın bizi de arkanızdan gelelim!\" diyecekler; Allah`ın sözünü (böylece) değiştirmek isteyecekler. De ki: \"(Bu kez) asla bizimle gelmeyeceksiniz; böyle olacak, (zira) Allah daha önce (ganimet hakkında) konuşmuştu.\" Bunun üzerine onlar \"Asla, aksine siz bizi çekemiyorsunuz\" diyecekler. Yoo, bilakis onlar kıt anlayışlı kimselerdir."},{"n":16,"t":"Geride kalan şu bedevilere de ki: \"Gelecekte ezici gücü olan toplum(lar)la mücadeleye çağrılacaksınız; onlarla (sonuna dek) savaşacaksanız ya da onlar teslim olacaklar. İşte siz eğer bu çağrıya uyarsanız, Allah size güzel bir karşılık verecek; yok eğer şimdi yaptığınız gibi geri durursanız, O sizi umduğunuzdan mahrum bırakarak terkedilmişliğin şiddetli acısını tattıracaktır."},{"n":17,"t":"Gözleri görmeyene, ayağı sakat olana ve hastaya (Allah yolunda savaşamadığı için) bir sorumluluk yoktur; ama kim Allah`a ve Rasulü`ne itaat ederse, onu zemininden ırmaklar çağlayan cennetlere koyacağız, kim de yüz çevirirse elim bir azab ile cezalandıracağız."},{"n":18,"t":"Doğrusu Allah, o ağacın altında sana biat edenlerden razı olmuştur; üstelik O onların kalbinden geçenleri de bilmekteydi; işte bu yüzden onlara iç huzuru indirdi ve kendilerini yaklaşan bir fetihle ödüllendirdi;"},{"n":19,"t":"bir de elde edecekleri sayısız ganimetle... Ve zaten Allah her işini mükemmel yapar, her hükmünde tam isabet kaydeder."},{"n":20,"t":"Allah size elde edeceğiniz daha bir çok ganimet vaad eti: nitekim O size olan bu ikramını öne almış ve insanların elini üzerinizden çekmiştir ki, hem mü`minler için bir belge olsun, hem de sizi dosdoğru bir yola yöneltsin."},{"n":21,"t":"Ama bir diğer (ikramı) daha var ki, onu sizin havsalanız almasa da, Allah onu (sonsuz ilmiyle) kuşatmıştır: ve zaten Allah`ın kudreti her şeyin üstündedir."},{"n":22,"t":"Eğer inkarda direnenler size karşı savaşırlarsa, arkalarını dönüp kaçacaklar, ardından da ne samimi bir dost, ne de sağlam bir destekçi bulacaklardır."},{"n":23,"t":"Allah`ın sünneti geçmişten bu güne hep böyledir: ve sen Allah`ın sünnetinde bir değişme bulamazsın."},{"n":24,"t":"Sizi onlara galip getirdikten sonra, Mekke vadisinde onların ellerini sizden ve sizin ellerinizi de onlardan çeken O`dur: ve zaten Allah yaptığınız her şeyi görmektedir."},{"n":25,"t":"(Doğrudur), inkarda direnenler, sizi Mescid-i Haram`a girmekten alıkoyanlar ve kurbanlarınızın yerine ulaşmasını engelleyenler hep onlardır; ama keşke şu istemeden (haklarını) çiğneme ve bilmeden kendileri yüzünden büyük bir yanlışa düşme ihtimaliniz bulunan, üstelik henüz tanımadığınız mü`min erkekler ve kadınlar (Mekke`de) olmasalardı; Allah dilediğini rahmetiyle kuşatmak için böyle yaptı; eğer onlar seçilip ayrılsalardı, elbet onlar içerisinden küfürde direnenleri (sizin elinizle) şiddetli bir cezaya çarptırırdık."},{"n":26,"t":"Hani, inkarda direnenlerin kalbini malum gurur -cahiliyye gururu- doldururken, Allah, Elçisine ve mü`minlere iç huzuru bahşetmiş ve onların sorumlu davranma sözüne sadık kalmalarını sağlamıştı: zira onlar buna fazlasıyla layık ve ehil idiler; ve zaten Allah da her şeyi hakkıyla bilendi."},{"n":27,"t":"Doğrusu Allah, gördüğü rüyayı gerçekleştirmek suretiyle Elçisini tasdik etmiştir: Elbet Allah dilerse Mescid-i Haram`a güven içerisinde, başlarınız tıraşlı veya kısa kesilmiş olarak ve asla korkuya kapılmadan gireceksiniz: çünkü O sizin bilmediğinizi bilmektedir ve bundan ayrı olarak yakında gerçekleşecek bir fetih takdir etmiştir."},{"n":28,"t":"O Elçi`sini doğru yol rehberliği ve hak din ile göndermiştir ki, böylece (hak) Din`i tamamıyla ortaya çıkarıp bildirmiş olsun: işte (buna) şahit olarak Allah yeter."},{"n":29,"t":"Muhammed Allah`ın Elçisi`dir ve onun safında olanlar, hakkı inkar edenlere karşı kararlı ve ödünsüz, birbirlerine karşı ise çok merhametlidirler. Onları hep rüku ve secde halinde Allah`ın kerem ve rızasını ararken görürsün; onların nişanları yüzlerindeki secde izleridir. Bu onların Tevrat`taki temsilidir. Bir de onların İncil`teki temsili var: Onlar filiz vermiş tohum gibidir; derken (Allah) o filizi güçlendirir ve kalınlaştırır ki kökü üzerine dimdik dursun da üreticiyi sevindirsin. Böylece O, hakkı inkar edenleri de kinlerine mahkum etmiş olur. (Ne ki) Allah onlardan iman eden ve ıslah edici eylemler ortaya koyanlara sınırsız bir bağış ve büyük bir ödül vaad etmiştir."}],[{"n":1,"t":"Siz ey iman edenler! Asla Allah`ın ve Elçisinin önüne geçmeyin ve sorumlu davranın: çünkü Allah her şeyi işitir, her şeyi bilir!"},{"n":2,"t":"Siz ey iman edenler! Sesleriniz Peygamber`in sesini bastırmasın! Birbirinizle bağıra çağıra konuştuğunuz gibi onunla da bağıra çağıra konuşmayın ki, siz farkında olmadan iyilikleriniz boşa gitmesin!"},{"n":3,"t":"Hani şu Allah Rasulü`nün yanında seslerini kısanlar var ya; işte onlar Allah`ın kalplerini takvaya dair sınava çektiği kimselerdir: onlar için sınırsız bir bağış ve büyük bir ödül vardır."},{"n":4,"t":"Ne var ki sana hanelerin berisinden seslenenler de var; onların çoğu kafalarını kullanmazlar."},{"n":5,"t":"Ama eğer sen kendilerine çıkıp gelinceye kadar sabretselerdi, elbet bu kendileri için daha hayırlı olurdu: ne ki Allah tarifsiz bir bağışlayandır, eşsiz merhamet kaynağıdır."},{"n":6,"t":"Siz ey iman edenler! Sorumsuzun biri size (önemli) bir haberle geldiğinde durup gerçeği araştırın; değilse, istemeden birilerini rencide eder, ardından da yaptığınızdan pişmanlık duyarsınız."},{"n":7,"t":"Ve aklınızdan çıkarmayın ki aranızda Allah Rasulü var; eğer o bir çok işte size uysaydı, kesinlikle haliniz harap olurdu. Lakin Allah size imanı sevdirdi ve onu yüreklerinizde güzelleştirdi; yine O size hakikati inkarı, sorumsuz davranmayı ve (iyi olana) karşı çıkmayı çirkin gösterdi. İşte onlar doğru tarafa yönelenlerdir"},{"n":8,"t":"Allah`ın lutfu ve nimeti sayesinde: zaten Allah her şeyi bilir, her hükmünde tam isabet kaydeder."},{"n":9,"t":"Şu halde mü`minlerden iki gurup çarpışırsa, aralarını bulun; fakat bir taraf diğerinin hakkına saldırırsa, siz de o haksız taraf ile Allah`ın emrine dönünceye kadar çarpışın; ama eğer (saldırganlıktan) vazgeçerse, tarafların arasını adaletle ayırın ve (bunun için gerekirse) kendi hakkınızdan feragat edin: çünkü Allah (barış için) fedarlık edenleri sever."},{"n":10,"t":"Mü`minler sadece kardeştirler; öyleyse kardeşlerinizin arasını düzeltin ve Allah`a karşı sorumlu davranın ki, O`nun merhametine mazhar olasınız!"},{"n":11,"t":"Siz ey iman edenler! Hiçbir kişi ve zümre bir diğer kişi ve zümreyi alaya alıp hor görmesin: belki diğerleri berikilerden daha değerli olabilirler. Yine bir kısım kadınlar da diğerlerini (böyle) görmesinler: ötekiler onlardan daha değerli olabilir. Asla birbirinizi itibardan düşürmek için karalamayın ve (kötü) lakaplar takarak yaralamayın: iman ettikten sonra sapıklıkla anmak-anılmak ne berbat bir şey! Ve kim (bu tür davranışlardan) pişmanlık duyup vazgeçmezse, işte zalim olanlar onlardır."},{"n":12,"t":"Siz ey iman edenler! (Birbiriniz hakkında kötü) zandan şiddetle kaçının! Unutmayın ki zannın bir kısmı ağır bir vebaldir! Birbirinizin gizli saklısını da asla araştırmayın ve birbirinizin gıybetini etmeyin! İçinizde ölü kardeşinin etini yemekten hoşlanan biri var mı? Bakın, tiksindiniz işte! Sözün özü: Allah`a karşı sorumluluğunuzun bilincine varın! Kuşkusuz Allah tevbeleri kabul eden sınırsız bir rahmet kaynağıdır."},{"n":13,"t":"Ey insanlık! Elbet sizi bir erkekle bir dişiden yaratan Biziz; derken sizi kavimler ve kabileler haline getirdik ki tanışabilesiniz. Elbet Allah katında en üstününüz, O`na karşı sorumluluk bilinci en güçlü olanınızdır; şüphe yok ki Allah her şeyi bilir, her şeyden haberdardır."},{"n":14,"t":"Bedeviler \"İman ettik\" dediler. De ki: \"Henüz iman etmiş sayılmazsınız, lakin `teslim olduk` diyebilirsiniz, zira iman kalplerinize girmiş değil. Ama eğer Allah ve Rasulü`ne uyarsanız, Allah amellerinizin zerresini eksiltmez: çünkü Allah tarifsiz bir bağış, eşsiz bir merhamet kaynağıdır."},{"n":15,"t":"Gerçek mü`minler sadece Allah`a ve Rasulü`ne iman edenler, ondan sonra da kuşkunun semtine uğramayanlar ve Allah yolunda mallarıyla, canlarıyla cihad edenlerdir: İşte bunlar sadık olanların ta kendileridir."},{"n":16,"t":"De ki: \"Allah`a dininizi siz mi öğreteceksiniz? Ama Allah göklerde ve yerde ne varsa hepsini bilir: zira Allah her şeyi ayrıntısıyla bilendir.\""},{"n":17,"t":"Onlar Müslüman oldular diye seni minnet altına almaya kalkıyorlar. De ki: \"Müslüman olmanızdan dolayı beni minnet altına alıp bana lutfettiğinizi sanmayın; eğer (hakikate) sadıksanız, sizi doğru yola yönelttiği için asıl Allah size lutufta bulunmuştur."},{"n":18,"t":"Muhakkak ki Allah, göklerin ve yerin sırlarını bilir; dahası Allah, yaptığınız herşeyi görür."}],[{"n":1,"t":"Kaf! Bu şanlı-şerefli Kur`an`ın değerini bilin!"},{"n":2,"t":"Ama nerde! Onlar içlerinden bir uyarıcının kendilerine gelmesine şaştılar ve işte bu kafirler dediler ki: \"Bu ne acayip bir iş!"},{"n":3,"t":"Ölümümüzün ve toza toprağa karışmamızın ardından (diriliş) ha? Bu dönüşü imkansız bir son.\""},{"n":4,"t":"Doğrusu Biz, yerin onları nasıl çürütüp toprak edeceğini daha baştan bilmekteyiz; zira katımızda mahfuz bir yasa mevcuttur."},{"n":5,"t":"Dahasını da yaptılar; ayaklarına kadar geldiği halde hakikati yalanladılar: hasılı onlar derin bir iç karmaşası yaşıyorlar."},{"n":6,"t":"Onlar üzerlerindeki göğe dönüp de bakmadılar mı? Onu nasıl inşa ettik ve ışıl ışıl bezedik; üstelik hiçbir eksik gedik bırakmadık!"},{"n":7,"t":"Yeryüzünü ise (engebeli arazi yapısıyla) uzatıp genişlettik; zira oraya kalkmaz kımıldamaz dağlar yerleştirdik; üstelik orada her tür çiftten güzel bitkiler yeşerttik ki,"},{"n":8,"t":"gönüllü olarak O`na yönelen her kul için bir bilinç kaynağı ve bir uyarı vesilesi olsun."},{"n":9,"t":"Yine Biz, gökten bereketli bir su indirdik ve onunla has behçeleri yeşerttik; dahası hasat edilen tahılı"},{"n":10,"t":"ve sıra salkımlı meyveleriyle boylu poslu hurma ağaçlarını,"},{"n":11,"t":"bütün kullara bir rızık olarak (verdik): Evet, Biz ölü bir beldeye o (su) ile can verdik; işte (insanın) yeniden dirilişi de böyle olacaktır."},{"n":12,"t":"Onlardan önce Nuh kavmi, Ress sakinleri ve Semud da yalanladı;"},{"n":13,"t":"yine Ad, Firavun ve Lut`un kardeşleri..."},{"n":14,"t":"Yine ormanlık vadinin sakinleri ve Tubba kavmi... Bunların hepsi de elçileri yalanladılar: sonunda vaat ettiğim ceza gerçekleşti."},{"n":15,"t":"Şimdi Biz, ilk yaratış sırasında bitkin düşmüşüz, öyle mi? Asla! Ama onlar, yeniden yaratmanın (imkanından) kuşku duymaktalar."},{"n":16,"t":"Doğrusu insanı yaratan Biziz ve iç beninin ona neler fısıldadığını iyi biliriz: zira Biz insana şahdamarından daha yakınız."},{"n":17,"t":"(Zıt kutuplarda) konuşlanmış olan o iki (unsur), sağdan ve soldan karşı karşıya geldiği zaman"},{"n":18,"t":"insandan herhangi bir söz çıkmaya görsün; illa ki, kendi içinde bile onu gözetleyip kaydeden Biri vardır."},{"n":19,"t":"Derken ölüm kabusu tüm gerçekliğiyle çıkagelir; (ki) işte bu (ey insan), senin köşe bucak kaçtığın şeydir!"},{"n":20,"t":"Nihayet (diriliş için) sura üflenir: işte bu da (ey insan), kendisine karşı uyarıl(dığın) gündür."},{"n":21,"t":"Ve her can kendisini yönlendiren unsurlar ve tanıklarla huzura gelir;"},{"n":22,"t":"\"Doğrusu sen\" (denilir), \"buna karşı gaflet içindeydin; işte, artık senin perdeni önünden kaldırdık: şimdi gözün daha bir keskindir.\""},{"n":23,"t":"Güdümüne girdiği (şeytani öteki kişiliği) der ki: \"İşte, bir uydu gibi emrime pervane olan budur!\""},{"n":24,"t":"(Allah emreder): \"İnkarda ısrar eden her inatçı kafiri (uydusu olduğu odakla) birlikte cehenneme fırlatın:"},{"n":25,"t":"her hayra engel olanları, her haddini bilmez saldırganı, her kuşku ve fesat yayanı,"},{"n":26,"t":"Allah dışında başka ilahlar peydahlayanı... Haydi, (özne ve nesnesiyle birlikte) hepsini şiddetli azabın bağrına fırlatın!"},{"n":27,"t":"Güdümüne girdiği (şeytani öteki kişilik): \"Rabbimiz!\" der, \"Onu azdırıp saptıran ben değildim; kaldı ki o zaten derin bir sapıklığın içindeydi.\""},{"n":28,"t":"(Allah) buyuracak: \"Benim huzurumda hesaplaşmayın; zira Ben sizi azabımla uyarmıştım;"},{"n":29,"t":"Benim katımda verilen söz değişmez; ve benim kullarıma zulmetme ihtimalim yoktur."},{"n":30,"t":"O gün cehenneme \"Doldun mu?\" diye soracağız; o \"Daha var mı?\" diyecek."},{"n":31,"t":"Ve cennet muttakiler ayağına getirilecek ve asla uzaklaşmayacak."},{"n":32,"t":"\"İşte, size vaad edilen budur; O`na dönük bir gönülle hatırdan O`nu hiç çıkarmayan herkese;"},{"n":33,"t":"idraki aşan bir hakikat olduğu halde, O sonsuz rahmet sahibi karşısında içi titreyen ve O`nun huzuruna adanmış bir yürekle gelen herkese:"},{"n":34,"t":"Oraya tarifsiz bir huzur içinde girin! İşte bu ebedi ikamet günüdür\" (denilecek)."},{"n":35,"t":"Onlar orada arzu ettikleri her şeye kavuşacaklar; ama katımızda daha fazlası da var."},{"n":36,"t":"Biz, onlardan önce nice uygarlıkları helak etmişiz; onlar güç ve kudret olarak bunlardan çok daha ileriydiler; fakat \"Bir sığınak yok mu?\" diye sığınacak delik aradılar."},{"n":37,"t":"Elbet bunda, (akleden) bir kalbe sahip olanlar için ibretlik bir uyarı vardır; veya pür dikkat bir şahit olarak kulak verenler için..."},{"n":38,"t":"Dahası gökleri, yeri ve bunlar arasındakileri altı aşamada yarattığımızı, fakat Bize asla bir yorgunluk arız olmadığını (bilenler için)..."},{"n":39,"t":"Öyleyse artık onların söyleyeceklerine karşı sabırlı ol! Bir de güneşin doğuşundan ve batıştan önce Rabbinin aşkın olan yüce zatını (namaz kılarak) hamd ile an;"},{"n":40,"t":"yine geceleri ve secdelerin ardından O`nun aşkın olan zatını an!"},{"n":41,"t":"İmdi sen (ey insanoğlu); sana çok çok yakın bir yerden o güne ilişkin çağrı yapan Allah`ın nidasına kulak ver!"},{"n":42,"t":"Tüm gerçekliğiyle o malum çığlığı (herkesin) işiteceği güne... İşte bu, bir (başka hayata) çıkış günüdür."},{"n":43,"t":"Kesin olan şu ki, ölümü ve hayatı yaratan Biziz ve her yol sonunda Bize çıkar."},{"n":44,"t":"Yer ayaklarının altında kayıp paramparça olduğu gün (her şey) son sürattir: işte bu akıl sır ermez bir toparlanıştır, Bizim için çok kolay olacaktır."},{"n":45,"t":"Biz onların neler söylediğini çok iyi biliyoruz; ne ki sen onları zorla (inandıracak) bir zorba değilsin: şu halde sen, Benim tehditlerimden korkanları bu Kur`an aracılığıyla uyarmaya devam et!"}],[{"n":1,"t":"İndiği yerden toz kaldırarak (hidayeti gönüllere) saçan;"},{"n":2,"t":"Bir o kadar da ağır mı ağır bir (mana) yükü taşıyan;"},{"n":3,"t":"Buna karşın, kolayca aktığı (kalpleri) fetheden;"},{"n":4,"t":"Ve emr(-i ilahiyi hayata) paylaştıran (vahiy) şahit olsun!"},{"n":5,"t":"Hiç tartışmasız, size vaad edilmiş olan elbet doğrudur;"},{"n":6,"t":"Ve Hesap (Günü) mutlaka gelecektir."},{"n":7,"t":"Şahit olsun hareketli ve çok katmanlı yollarla donatılmış (olarak görünen) gök:"},{"n":8,"t":"Elbet siz, (inanç hususunda) gerçekten de farklı görüşlerdesiniz;"},{"n":9,"t":"Savrulanlar, kendi aleyhine savrulurlar!"},{"n":10,"t":"Kahrolsun keyfi yargılarını kesin gerçek gibi pazarlayanlar."},{"n":11,"t":"Onlar daldıkları gafletin derin karanlığında kendi varlığını unutanlardır;"},{"n":12,"t":"\"Hesap Günü ne zamanmış bakayım?\" diye söylenenlerdir."},{"n":13,"t":"Onlar o gün ateşte azap görecekler;"},{"n":14,"t":"(ve) onlara \"Azabınızı tadın!\" denilecek; \"İşte bu, sizin acele gelmesini istediğiniz şeydir!\""},{"n":15,"t":"Ne var ki sorumlu davrananlar, akıl sır ermez cennetlerde ve pınar başlarında bulunacaklar;"},{"n":16,"t":"Rablerinin kendileri için takdir ettiğini (derin bir şükranla) alarak; çünkü onlar, zaten daha önce de iyilerdendi:"},{"n":17,"t":"Gecenin az bir kısmında uyurlardı,"},{"n":18,"t":"Ve seher vakitlerinde ta yürekten Allah`a yalvarırlardı,"},{"n":19,"t":"servetlerinde, isteyebilen ve isteyemeyen muhtaçların da bir payı vardı."},{"n":20,"t":"Yeryüzünde, gönülden inanmış olanların (şahit olduğu) ilahi işaretler vardır;"},{"n":21,"t":"Tıpkı sizin kendi varlığınızda olduğu (gibi): Bunları görmüyor musunuz?"},{"n":22,"t":"Gökyüzünde ise (maddi manevi) rızkınızın ve size vaad edilen şeylerin (kaynağı) vardır:"},{"n":23,"t":"Göğün ve yerin Rabbine andolsun ki, bu (yeniden diriliş) en az(ından) sizin konuşma yeteneğiniz kadar gerçektir."},{"n":24,"t":"İbrahim`in, ilahi ikrama mazhar olmuş konukları hakkındaki kıssa sana ulaştı mı?"},{"n":25,"t":"Hani, (elçiler) İbrahim`in huzuruna girmişler ve \"(Sana) selam olsun!\" demişlerdi de, o da, \"(Size de) selam olsun!\" demiş ve (içinden) \"Bunlar tanımadık kimseler\" diye geçirmişti."},{"n":26,"t":"Sonra, usulca ailesine yönelerek (kızartılmış) semiz bir buzağı getirmiş,"},{"n":27,"t":"Derhal önlerine sunarak \"Buyurmaz mısınız?\" demişti."},{"n":28,"t":"Derken, onlardan yana içini bir korku ve endişe kapladı. \"Endişeye mahal yok!\" dediler ve ona sıra dışı bir bilgi ile donatılmış bir oğlan çocuğu müjdelediler."},{"n":29,"t":"(Bu arada konuşulanları duyan) eşi çığlık atarak yaklaştı ve elini yüzüne vurarak, “Benim gibi bir kocakarının mı çocuğu olacak?” dedi."},{"n":30,"t":"“Evet, Rabbin böyle buyurdu;” dediler, “muhakkak ki O, her hüküm ve icraatında pek çok hikmetler bulunandır, her şeyi hakkıyla bilendir.”"},{"n":31,"t":"(İbrahim): \"Peki ey Elçiler!\" dedi, \"Nedir bu olağandışı ziyaretinizin (gerçek) sebebi?\""},{"n":32,"t":"Onlar \"Biz\" dediler, \"günaha gömülüp gitmiş bir topluma gönderildik ki,"},{"n":33,"t":"Onların üzerine (gökten) taşlaşmış balçık yağdıralım;"},{"n":34,"t":"kendini harcayanlara, senin Rabbinin katında hedefi belirlenmiş (taşlar)."},{"n":35,"t":"Derken mü`minlerden orada bulunanları çıkardık;"},{"n":36,"t":"zaten orada bir hane dışında hiçbir müslüman bulamadık."},{"n":37,"t":"Ve elem verici azaptan korkacak olan kimseler için orada bir işaret, bir mesaj bıraktık."},{"n":38,"t":"Aynı (mesaj) Musa kıssasında da var: Hani Biz onu açık ara muktedir kılan bir güçle Firavun`a göndermiştik."},{"n":39,"t":"Fakat o iktidarına güvenerek (Musa`ya) karşı çıkmış, üstelik \"O, ya bir büyücü ya da bir delidir\" demişti."},{"n":40,"t":"Derken, Biz de onu ve ordusunu enseledik, hepsini denize döktük: o hala kendi kendisini kınayadursun."},{"n":41,"t":"Aynı (mesaj) Ad kıssasında da var: Hani onlara da köklerini kurutan bir fırtına göndermiştik."},{"n":42,"t":"(Bu fırtına) geçtiği yerde hiçbir şey bırakmadı, hepsini kül edip göğe savurdu."},{"n":43,"t":"Aynı (mesaj) Semud kıssasında da var: Hani onlara da \"Bir süreliğine siz de safa sürün bakalım!\" denilmişti."},{"n":44,"t":"Nitekim onlar Rablerinin emrine karşı gelmişlerdi: Ve onlar bön bön bakarken, bir (bela) yıldırımı kendilerini enseleyiverdi;"},{"n":45,"t":"Ne yerlerinden doğrulmaya, ne de kendilerini savunmaya mecal bulabildiler."},{"n":46,"t":"Daha önce de Nuh kavmi (helak olmuştu): Çünkü onlar da yoldan çıkmış bir kavimdiler."},{"n":47,"t":"Bütün bir göğü kendi güç ve kudretimizle Biz inşa ettik ve onu sürekli genişleten de Biziz."},{"n":48,"t":"Yeri de Biz yayıp döşedik: Biz, ne muhteşem bir döşeyiciyiz."},{"n":49,"t":"Her şeyi çift-zıt kutuplu yarattık ki, öğüt ve ibret alabilesiniz."},{"n":50,"t":"Şu halde (de ki): \"Allah`a kaçınız! Şüphe yok ki ben O`nun katından size gönderilmiş apaçık bir uyarıcıyım."},{"n":51,"t":"Allah`la beraber, başka hiçbir şeye ilahlık yakıştırmayınız! Elbette ben O`nun katından size gönderilmiş apaçık bir uyarıcıyım."},{"n":52,"t":"İşte böyle! Onlardan öncekiler, kendilerine gelen her peygambere mutlaka \"sihirbaz\" ya da \"mecnun\" dediler;"},{"n":53,"t":"yoksa onlar bunu birbirlerine mi bulaştırdılar? Ama hayır, belli ki onlar (da bunlar da bizzat kendileri) Allah`a başkaldırmış azgın bir topluluktular."},{"n":54,"t":"Artık onları kendi hallerine bırak, (sen kendi işine bak); böyle yaptığın takdirde kınanacak değilsin."},{"n":55,"t":"Ama uyarmayı sürdür; en azından bir uyarının mü`minlere yararı olur!"},{"n":56,"t":"Ben görünür-görünmez, bilinir-bilinmez tüm iradeli varlıkları sadece Bana kulluk etsinler diye yarattım."},{"n":57,"t":"Onlardan ne bir rızık bekliyorum ne de beni beslemelerini:"},{"n":58,"t":"çünkü Allah, evet, bütün rızıkları veren mutlak ve sınırsız güç ve kudret sahibi O`dur."},{"n":59,"t":"Bakın, elbette kendilerine kıyanların payına düşen, (seleflerinin) payına düşenin aynısı olacaktır: şu halde, (bu payı) acele istemelerine gerek yoktur."},{"n":60,"t":"İmdi, inkarda direnenlerin tehdit edildikleri o gün başlarına geleceklerden dolayı vay hallerine!"}],[{"n":1,"t":"Ulu Sina dağı şahit olsun!"},{"n":2,"t":"Satırlarda kayıtlı ilahi mesaj (şahit olsun),"},{"n":3,"t":"açılmış deri tomarlarda!"},{"n":4,"t":"el-Beytu`l-Ma-mur şahit olsun,"},{"n":5,"t":"yüceltilmiş gök kubbe şahit olsun!"},{"n":6,"t":"Kükreyen taşkın deniz şahit olsun!"},{"n":7,"t":"Şüphe yok ki, Rabbinin azabı kesinlikle vuku bulacaktır;"},{"n":8,"t":"insan kendisini ona karşı asla savunamaz."},{"n":9,"t":"Gün gelir, gök büyük bir çöküşle çöker."},{"n":10,"t":"Dağlar dehşet bir yürüyüşle yürür."},{"n":11,"t":"İşte o gün yalanlayanların vay haline!"},{"n":12,"t":"Onlar ki daldıkları oyunda oynuyor olacaklar."},{"n":13,"t":"Onlar o gün karşı konulmaz bir güçle cehennem ateşine itilecekler (ve şöyle denilecek):"},{"n":14,"t":"\"Bu sizin vaktiyle yalanlamış olduğunuz ateştir."},{"n":15,"t":"Şimdi (söyleyin bakalım); sihir bu mu, yoksa (hakikati) görmeyen siz misiniz?"},{"n":16,"t":"Orayı boylayın! Artık ister sabredin, ister sabretmeyin; size ilişkin (hüküm) değişmez: çünkü siz, sadece yaptıklarınızın cezasını çekmektesiniz.\""},{"n":17,"t":"Sorumluluk bilinciyle yaşayanlar, tanımsız cennetlerde ve tarifsiz nimetler içinde olacaklar."},{"n":18,"t":"Rablerinin kendilerine verdiği nimetlerle sevinip mutlu olacaklar ve Rableri onları gözleri yuvasından fırlatan azaptan koruyacak"},{"n":19,"t":"(ve onlara diyecek ki): \"Vaktiyle yapmış olduğunuz şeylere bir karşılık olarak yiyin, için, afiyet olsun!"},{"n":20,"t":"Sıra sıra dizilmiş koltuklara yaslanarak yiyin için. Biz onları, iri, güzel gözlü, ceylan gözlü hurilerle everdik."},{"n":21,"t":"Kendileri iman eden, ve soyları da bu muhteşem imanı izleyenlere gelince: Biz onları soylarıyla buluşturacağız ve kendi yaptıklarının (karşılığından) da hiçbir şey eksiltmeyeceğiz; (ne ki) herkesin (akıbeti) kendi kazandıklarına bağlıdır."},{"n":22,"t":"Ve Biz onlara meyve ve etin her türünü, canlarının çektiği her şeyi sunacağız;"},{"n":23,"t":"orada birbirlerine içeni boşboğaz etmeyen ve günaha sokmayan dolu kadehler sunacaklar."},{"n":24,"t":"Ve kendileri için hazırlanmış ebedi bir gençlik ve tazelik onları hiç terk etmeyecek; tıpkı kabuklarının içinde saklanmış inciler gibi olacaklar."},{"n":25,"t":"Derken, birbirlerine dönüp sorular soracaklar..."},{"n":26,"t":"Diyecekler ki: \"Vaktiyle bizler, ailemiz hakkında endişeye kapılıp tir tir titrerdik;"},{"n":27,"t":"fakat Allah bize kerem etti de, bizi zehir gibi içe işleyen yakıcı bir ateşin azabından korudu."},{"n":28,"t":"Şüphesiz biz bundan önce de hep O`na dua ederdik; çünkü O, evet O`dur mutlak iyi olan sonsuz rahmet sahibi."},{"n":29,"t":"(Ey Nebi!) Öğüt vermeyi (sürdür); şüphesiz, -Rabbinin nimeti sayesinde- senin bir kahin ve bir mecnun olma ihtimalin asla bulunmamaktadır."},{"n":30,"t":"Yoksa (şimdi de) \"O bir şairdir; (bırakın da) feleğin sillesini yiyeceği zamanı bekleyip görelim\" mi diyorlar?"},{"n":31,"t":"De ki: \"Bekleyin bakalım! Ama unutmayın ki, ben de sizinle beraber bekleyenlerdenim.\""},{"n":32,"t":"Yoksa onları bu tavra savruk akılları mı sevk ediyor? Sakın onlar isyanda sınır tanımayan azgın bir topluluk olmasın?!"},{"n":33,"t":"Ya yoksa onlar, \"Kendi söylediğini Allah`a isnat etti\" mi diyorlar? Ama yoo! (Dediklerine) kendileri de inanmıyorlar."},{"n":34,"t":"Öyleyse, haydi onun benzeri bir başka söz üretsinler bakalım; sözlerinin arkasında duruyorlarsa tabi ki."},{"n":35,"t":"Ne yani, onlar sebepsiz mi yaratıldılar? Yoksa kendilerini yaratan yine kendileri mi?"},{"n":36,"t":"Ya yoksa gökleri ve yeri yaratan kendileri mi? Hayır! Asıl onlar inanmaya gönüllü değiller."},{"n":37,"t":"Yoksa Rabbinin hazineleri onların elinde mi? Ya yoksa onu zorla ele geçirip üstüne mi oturmuşlar?"},{"n":38,"t":"Ne yani, onlara mahsus (göklere uzanan bir) merdiven var da orada olup-biteni mi dinliyorlar? Öyleyse, haydi açık ve inandırıcı delillerle birlikte dinlediklerini getirsinler de görelim!"},{"n":39,"t":"Ne yani, kızlar O`na da oğullar kendilerine mi?"},{"n":40,"t":"Yoksa onlar senin, kendilerine, onları ağır bir ekonomik yükümlülük altına sokacak bir bedel ödetmenden mi (çekiniyorlar)?"},{"n":41,"t":"Ne yani, idraki aşan hakikatlere vakıflar da, onu kendileri mi kayıt altına alıyorlar?"},{"n":42,"t":"Onlar, bir tuzak tasarlıyor olmasınlar sakın? Fakat kurdukları tuzağa düşecek olan o kafirlerin ta kendileridir!"},{"n":43,"t":"En nihayet, onların Allah`tan başka bir ilahı mı var? Allah onların şirk koştuğu her şeyden aşkın ve yücedir."},{"n":44,"t":"(Onlar gerçeği kabul etmemede o kadar inatçıdırlar ki, ceza olarak üzerlerine) gökten bir parçanın düştüğünü görseler, “Bu, bir bulut yığını!” derler (ve onun ceza olarak üzerlerine düştüğünü itiraf edemezler)."},{"n":45,"t":"Artık onları, dehşetten kendilerini kaybedecekleri günle karşılaşıncaya kadar kendi hallerine bırak!"},{"n":46,"t":"O gün tuzakları kendilerine hiçbir yarar sağlamayacak ve kendilerine asla bir yardım ulaşmayacak."},{"n":47,"t":"Ve elbet kendilerine yazık edenler, bu (ahiret) azabından daha yakın bir (dünya) azabına da mahkum olmuşlardır: fakat onların çoğu bunu kavrayamamaktalar."},{"n":48,"t":"Sözün özü: Rabbinin hükmünü sabırla bekle! Unutma ki sen Bizim gözetimimiz altındasın: kalktığın zaman, Rabbinin yüceliğini hamd ile an!"},{"n":49,"t":"Bir de gece vakti ve yıldızların çekildiği (gündüz) vakti O`nun yüceliğini dillendir!"}],[{"n":1,"t":"Vahyin aşama aşama inişi şahit olsun!"},{"n":2,"t":"Arkadaşınız ne sapmıştır, ne kanmıştır;"},{"n":3,"t":"ne de kendi keyfinden konuşmaktadır."},{"n":4,"t":"bu (Kur`an), kendisine indirilen bir vahiyden ibarettir."},{"n":5,"t":"Onu, melekeleri son derece güçlü bir (melek) öğretti;"},{"n":6,"t":"etkileyici ve tam donanımlı: Derken o kendini olanca haşmetiyle gösterdi;"},{"n":7,"t":"(önce) en uzak ufukta belirmişti;"},{"n":8,"t":"daha sonra yaklaştı, derken iyice sokuldu;"},{"n":9,"t":"öyle ki, iki yay aralığı, hatta daha az bir mesafe kaldı:"},{"n":10,"t":"İşte (Allah)`ın kuluna vahyettiğini böylece iletmiş oldu."},{"n":11,"t":"Gördüğünü gönül yalanlamadı:"},{"n":12,"t":"ne yani, şimdi siz ne gördüğü hususunda onunla tartışacak mısınız?"},{"n":13,"t":"Doğrusu onu bir başka iniş sırasında yine görmüştü;"},{"n":14,"t":"en sonuncu sidre ağacının yanında,"},{"n":15,"t":"vaad edilen cennetin (görüntüsü) eşliğinde,"},{"n":16,"t":"kaplayan o şey sidreyi çepeçevre kuşattığında..."},{"n":17,"t":"Gönül gözü ne şaştı ve kamaştı, ne de haddi aştı:"},{"n":18,"t":"hakikaten de o, Rabbinin en büyük ayetlerinden birini görmüştü."},{"n":19,"t":"Peki hiç düşündünüz mı Lat, Uzza"},{"n":20,"t":"ve sonuncusuna, (hani) şu üçüncüleri olan Menat`a (neden dişi adlar verdiğinizi)?"},{"n":21,"t":"Erkekler size kızlar O`na, öyle mi?"},{"n":22,"t":"O halde bu ne berbat bir paylaşım böyle!"},{"n":23,"t":"Bunlar, sadece sizin ve atalarınızın uydurduğu isimlerden ibarettir; Allah bunlara hiçbir yetki ve otorite devretmemiştir. Bunu söyleyenler sadece kuruntu ve nefsani arzularının peşinden gidiyorlar; oysa ki Rablerinden kendilerine, ilahi rehberlik gelmiş bulunuyor."},{"n":24,"t":"Yoksa insan, (hakikatin) kendi arzu ve isteğine tabi olduğunu mu sanıyor?"},{"n":25,"t":"Fakat ahiret de dünya da Allah`a aittir."},{"n":26,"t":"Her ne kadar göklerdeki melek sayısı çoksa da, Allah`ın dilediği ve razı olduğu kimseler için verdiği şefaat izni olmadıkça, onların şefaati hiçbir fayda sağlamayacaktır."},{"n":27,"t":"Elbet ahirete inanmayan kimseler, melekleri dişi isimlerle adlandırırlar."},{"n":28,"t":"Ama onların bu konuda hiçbir bilgisi bulunmamakta, sadece zannın peşine düşmekteler: şu da bir gerçek ki, zan asla gerçeğin yerini tutamaz."},{"n":29,"t":"Şu halde, artık sen de vahyimizden yüz çevirerek Bize sırt dönen ve tek arzusu bu dünya hayatı(nın geçici zevkleri) olan kimseleri ciddiye alma!"},{"n":30,"t":"Onların bilgi ufku da işte bu (dünya ile) sınırlıdır. Elbet senin Rabbin kendi yolundan kimin saptığını en iyi bilendir, kimin doğru yola yöneldiğini de en iyi bilendir."},{"n":31,"t":"Göklerde ve yerde ne varsa hepsi Allah`a aittir: en sonunda O, kötülük yapanları yaptıklarıyla cezalandıracak, iyilik yapanları ise çok daha güzeliyle ödüllendirecektir."},{"n":32,"t":"Büyük günahlardan ve ahlaksızca fiillerden kaçınanlara gelince: ufak tefek kusurlar işleseler de, kesin olarak bilsinler ki senin Rabbin engin bağış sahibidir. O, yeryüzü (toprağından) sizi var ederken de, anneleriniz karınlarında cenin halindeyken de sizinle ilgili her şeyi bilir; şu halde kendinizi temize çıkarmayın: kimin takvaya uygun davrandığını en iyi bilen O`dur."},{"n":33,"t":"Görmez misin (Bize) sırt çevireni?"},{"n":34,"t":"Azıcık verip ardından koklatmayanı?"},{"n":35,"t":"Şimdi o, gaybın bilgisine sahip olduğunu, onu gözlemlediğini mi iddia ediyor?"},{"n":36,"t":"Yoksa ona bildirilmedi mi Musa`ya gelen vahiyde nelerin yer aldığı?"},{"n":37,"t":"Dahası (aynı şeylerin) vefa sahibi İbrahim`e de (geldiği):"},{"n":38,"t":"Kesinlikle, hiç kimse bir başkasının sorumluluğunu taşımaz."},{"n":39,"t":"Ve insan başkasının değil, sadece kendi çabasının karşılığını görecektir."},{"n":40,"t":"Ve elbet onun çabası, günü geldiğinde kesinlikle gözler önüne serilecektir."},{"n":41,"t":"Sonunda, (yaptıklarının) karşılığı eksiksiz verilecektir."},{"n":42,"t":"En nihayet (varlık bilgisinin) son, en son sınırı Rabbine aittir."},{"n":43,"t":"Ve elbet ağlatan da O`dur, güldüren de O."},{"n":44,"t":"Dahası elbette öldüren de O`dur, hayat veren de O."},{"n":45,"t":"Yine erkek ve dişi çiftleri yaratan da kesinlikle O`dur;"},{"n":46,"t":"(rahme) atıldığı zaman, bir meni damlasından..."},{"n":47,"t":"Ve elbet öteki (hayatı) yaratmak da O`na düşer."},{"n":48,"t":"Yine elbet zengin eden de O`dur, sınırlayan da O."},{"n":49,"t":"Ve Şi`ra yıldızının Rabbi de kesinlikle O`dur."},{"n":50,"t":"Ve elbet O helak etmiştir kadim Ad`ı,"},{"n":51,"t":"ve Semud`u; geriye onlardan hiçbir iz bırakmadı."},{"n":52,"t":"Tıpkı daha önceki Nuh kavmi (gibi): Çünkü onlar zulümde ve azgınlıkta ileri gitmiştiler."},{"n":53,"t":"Tıpkı altı üstüne getirilen diğer topluluklar (gibi)."},{"n":54,"t":"Derken, kuşatan o şey onları (tarihe) gömdü."},{"n":55,"t":"Şu halde (ey insan)! Rabbinin hangi nimetinden dolayı (hesaba çekilmekten) tereddüt edersin?"},{"n":56,"t":"İşte bu, önceki uyarı türlerinden bir uyarıdır:"},{"n":57,"t":"Dehşet (anı) yaklaştıkça yaklaşıyor!"},{"n":58,"t":"Allah`tan başka kimse onun perdesini aralayamaz."},{"n":59,"t":"Ne yani, siz bu (kaçınılmaz) olayın haberini tuhaf mı buluyorsunuz?"},{"n":60,"t":"Ve dahi ağlanacak halinize gülüyorsunuz?"},{"n":61,"t":"Üstelik bir de kafa tutuyorsunuz?"},{"n":62,"t":"Artık (bırakın bu tavrı da), Allah`ın huzurunda yerlere kapanın ve yalnız O`na kulluk edin!"}],[{"n":1,"t":"Son saat yaklaşacak ve ay yarılacak."},{"n":2,"t":"Ama eğer onlar bir mucize görseler, (hem hakikatten) yüz çevirirler (hem de onun cazibesinden kendilerini alamayışlarını) \"Bu sürekli gerçekleşen bir sihirdir\" diye izah ederler;"},{"n":3,"t":"zaten hep yalanlıyorlar ve önyargılarının peşine düşüyorlar. Sonuçta, her hakikatin ortaya çıkmak (gibi bir huyu) var."},{"n":4,"t":"Doğrusu onlara, içerisinde (gerçeği) gözlere zorla sokan haberler bulunan bir mesaj gelmiştir:"},{"n":5,"t":"hedefe tam ulaştıracak çapta bir hikmet; fakat uyarının hiçbir yararı olmadı."},{"n":6,"t":"Artık sen de onlardan yüz çevir! Bir davetçinin, asla (kimsenin) tasavvur edemeyeceği o şeye çağıracağı gün,"},{"n":7,"t":"onlar yılgın ve bitkin gözlerle, savrulmuş çekirge sürüleri gibi mevzilerinden çıkacaklar;"},{"n":8,"t":"davetçiye doğru panik içinde seğirtecekler... ve o inkar edenler \"Bu zor bir gün!\" diye çığlık atacaklar."},{"n":9,"t":"Onlardan önce, Nuh kavmi de yalanlamıştı: hem kulumuzu yalanlamışlar, hem de dönüp \"O bir delidir\" demişlerdi: ama engellendiler."},{"n":10,"t":"Derken, o Rabbine şöyle yalvardı: \"Ben artık bittim, şimdi Sen yardım et!\""},{"n":11,"t":"Biz de bardaktan boşanırcasına dökülen bir su ile semanın kapılarını açtık;"},{"n":12,"t":"ve toprağı fışkıran pınarlara çevirdik; ve kararlaştırılmış bir görevi gerçekleştirmek üzere su(lar) birleşti."},{"n":13,"t":"Ama onu (malzemesi) ahşap ve çiviler olan bir (gemi ile) taşıdık:"},{"n":14,"t":"o (gemi) gözetimimiz altında yol aldı; (bu), nankörlüğe maruz kalan (Nuh`a) verilmiş bir ödüldü."},{"n":15,"t":"Doğrusu Biz, bu (kıssayı) bir (ibret) belgesi olarak bıraktık: öyleyse yok mudur ders alan?"},{"n":16,"t":"Nitekim, uyarımın (dinlenilmemesi) halinde azabım nasıl olurmuş (görün)!"},{"n":17,"t":"Ve doğrusu Biz bu Kur`an`ı ders alınsın diye kolaylaştırdık: öyleyse yok mudur ders alan?"},{"n":18,"t":"`Ad (kavmi) de yalanlamıştı: fakat uyarımın (dinlenilmemesi) halinde azabım nasıl olurmuş, (gördüler)."},{"n":19,"t":"Elbet Biz de onların üzerine kapkara bir günde gürültülü bir kasırga gönderdik:"},{"n":20,"t":"insanları öyle savuruyordu ki, sanki onlar kökünden sökülmüş hurma kütükleri gibi (yere serildiler)."},{"n":21,"t":"Fakat uyarımın (dinlenilmemesi) halinde azabım nasıl olurmuş, (gördüler)."},{"n":22,"t":"Ve doğrusu Biz bu Kur`an`ı ders alınsın diye kolaylaştırdık: öyleyse yok mudur ders alan?"},{"n":23,"t":"Semud da bütün uyarıları yalanladı;"},{"n":24,"t":"ve dediler ki: \"Ne! İçimizden (bula bula) bir ölümlüye mi uyacağız? Bu takdirde biz sapıklığa ve çılgınlığa gömülmüş oluruz."},{"n":25,"t":"Vahiy, aramızdan bir tek ona mı indirildi? Hayır, aksine o yalanda sınır tanımayan bir mağrurun biri.\""},{"n":26,"t":"(Allah dedi ki): \"Onlar yarın `yalanda sınır tanımayan mağrur` kimmiş bilecekler:"},{"n":27,"t":"Unutma ki (Ey Salih); Biz bu dişi deveyi onları sınamak için göndermiş bulunuyoruz: artık onları gözetle ve sabırlı ol!"},{"n":28,"t":"Ve onlara suyun aralarında taksim edildiğini haber ver: her sulama nöbetleşe yapılacaktır.\""},{"n":29,"t":"Derken onlar, (çete başı olan) arkadaşlarını çağırdılar. Kafa kafaya verdiler... ve nihayet o, (deveyi) gaddarca boğazladı."},{"n":30,"t":"Fakat, uyarımın (dinlenilmemesi) halinde azabımın nasıl olduğunu (hiç hesaba katmadı)."},{"n":31,"t":"Elbet Biz de onlara tek bir bela sayhası gönderdik: sonunda çürüyüp un-ufak olmuş odun talaşına döndüler."},{"n":32,"t":"Ve doğrusu Biz bu Kur`an`ı ders alınsın diye kolaylaştırdık: öyleyse yok mudur ders alan?"},{"n":33,"t":"Lut kavmi de bütün uyarıları yalanladı."},{"n":34,"t":"Onların üzerine de öldürücü bir kasırga saldık ve şafak vakti Lût`a iman edenleri kurtardık,"},{"n":35,"t":"katımızdan bir nimet olarak: şükredenleri Biz işte böyle ödüllendiririz."},{"n":36,"t":"Doğrusu (Lut) Bizim kıskıvrak yakalama gücümüze karşı onları uyarmıştı; fakat onlar bu uyarılara hep kuşkuyla yaklaştılar."},{"n":37,"t":"Daha beteri arzularını onun misafirlerinden tatmin etmek için onunla çekiştiler; bunun üzerine Biz de gözlerini kör ettik; \"Madem uyarımı (göz ardı ettiniz), o halde azabımı tadın!\" (dedik)."},{"n":38,"t":"Mamafih, sabahleyin erkenden kalıcı izler bırakan bir azap onları kuşattı:"},{"n":39,"t":"sonunda, uyarımın (dinlenilmemesi) halinde azabım nasıl olurmuş (gördüler)."},{"n":40,"t":"İşte Biz bu Kur`an`ı ders alınsın diye kolaylaştırdık: öyleyse yok mudur ders alan!"},{"n":41,"t":"Firavun hanedanına da uyarıcılar gelmişti."},{"n":42,"t":"Onlar âyetlerimizin hepsini birden yalanladılar. Biz de izzetli ve kudretli bir yakalayışla onları yakaladık."},{"n":43,"t":"İmdi, sizin kafirleriniz şu bahsi geçenlerden daha mı değerlidir; yoksa silinmez sayfalarda dokunulmaz olduğunuz mu kayıtlı?"},{"n":44,"t":"Yoksa \"Biz örgütlü gücüz, galip geliriz\" mi diyorlar?"},{"n":45,"t":"Gün gelecek, birlikleri yenilip dağılacak ve arkalarını dönüp (kaçacak)lar."},{"n":46,"t":"Ne var ki onların asıl randevuları Son Saat`tir; işte o Son Saat en dehşetli, en acı olanıdır."},{"n":47,"t":"Çünkü günahı hayat tarzı edinenler, sapıklığa ve çılgınlığa mahkum olmuşlardır."},{"n":48,"t":"O gün yüzükoyun ateşe sürüklenecekler (ve denilecek ki): \"Tadın bakalım, değdiğinin fiyakasını bozan cehennemin okşayışını!\""},{"n":49,"t":"ŞÜPHE yok ki Biz, her şeyi bir ölçüyle yaratmışızdır."},{"n":50,"t":"Bizim emrimiz ise, sadece göz açıp kapamak gibi bir anlık iştir."},{"n":51,"t":"Nitekim, geçmişte sizinle aynı kafaya sahip toplumları yok ettik: hala yok mudur ders alan?"},{"n":52,"t":"Ve yaptıkları her şey korunaklı sayfalarda kayıt altına alınmıştır;"},{"n":53,"t":"küçük olsun büyük olsun, her ne yapmışlarsa satırlara geçmiştir."},{"n":54,"t":"Ne var ki, sorumluluğunun bilincinde olanlar cennetlerde ve ırmaklar arasında (mest) olacaklar:"},{"n":55,"t":"sadakat tahtında... sonsuz hükümranlık ve iktidar sahibinin yüce huzurunda..."}],[{"n":1,"t":"Rahman?.. (Rahman`ı mı merak ediyorsunuz? O zaman dinleyin ki, O...)"},{"n":2,"t":"Kur`an`ı O öğretti,"},{"n":3,"t":"insanı O yarattı,"},{"n":4,"t":"insana kendini ifade etmeyi o öğretti."},{"n":5,"t":"Güneşi ve ayı mükemmel bir hesapla yörüngelerinde hareket ettiren de (O)."},{"n":6,"t":"Gövdesiz ve gövdeli bitkiler O`nun emrine boyun eğerler."},{"n":7,"t":"Yine göğü özenle O yükseltti, bir denge ve ölçü koydu:"},{"n":8,"t":"ki siz (ey insanlar), dengeyi bozup ölçüyü kaçırmayın!"},{"n":9,"t":"Yine istikametle ölçüp biçin, ölçme değerlendirme yaparken haksızlık etmeyin!"},{"n":10,"t":"Yine O, yeryüzünü orada yaşayan tüm canlıların (ayağı altında) özenle serdi;"},{"n":11,"t":"orada envai çeşit meyveler, salkım saçak hurma ağaçları"},{"n":12,"t":"ve filizlenen danelerle hoş kokulu çiçekler verdi:"},{"n":13,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":14,"t":"O insanı ateşte pişirilmiş gibi kuru, ses veren balçıktan yarattı,"},{"n":15,"t":"görünmeyen varlıkları da tarifsiz ateş türü bir karışımdan halk etti:"},{"n":16,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":17,"t":"O, iki doğunun da Rabbidir, iki batının da Rabbi:"},{"n":18,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":19,"t":"O, iki denizi salarak birbirine kavuşturur;"},{"n":20,"t":"(ama) aralarında aşamayacakları tarifsiz bir engel var (eder):"},{"n":21,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":22,"t":"O ikisinden inci ve mercan çıkar."},{"n":23,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":24,"t":"Yüce dağlar gibi denizde hızla akıp giden koca gemiler O`nun (yasalarına) tabidir:"},{"n":25,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":26,"t":"Oradaki her varlık fanidir;"},{"n":27,"t":"baki kalacak olan azamet ve ihtişam sahibi Rabbinin zatıdır."},{"n":28,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":29,"t":"Göklerde ve yerde bulunan her varlık O`na muhtaçtır; her an O, hayata ve varlığa dair her işe müdahildir."},{"n":30,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":31,"t":"Ey ağır bir yükün altına giren çift: Size ayıracak zamanımız da olacak!"},{"n":32,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":33,"t":"Siz ey görünmez ve görünür varlık (çifti)! Eğer göklerin ve yerin sınırlarını geçebiliyorsanız, durmayın haydi geçin! Bunu, (O`nun bahşettiği) çok özel bir güç sayesinde yapabilirsiniz ancak:"},{"n":34,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":35,"t":"Sizin üzerinize dumanıyla boğup aleviyle yakan tarifsiz bir ateş topu gönderilir ve hiçbir yardım da alamazsınız:"},{"n":36,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":37,"t":"Ve gök yarılınca, göz alıcı kırmızılıkta açılmış bir gül gibi olduğu (görülecek):"},{"n":38,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":39,"t":"O gün, görünen görünmeyen iradeli varlıklardan hiçbirine günahları hakkında sorulmaya (gerek) kalmayacak:"},{"n":40,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":41,"t":"(Zira) günahkarlar alametlerinden tanınacak; yaka paça yakalanıp ateşe atılacak:"},{"n":42,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":43,"t":"İşte bu günahkarların yalanlamış oldukları cehennemdir."},{"n":44,"t":"Onlar cehennem ile anında dağlayan bir (umutsuzluk) ateşi arasında mekik dokuyacak:"},{"n":45,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":46,"t":"Rabbinin mutlak otoritesinden korkup sakınanlara çifte cennetler sunulacak:"},{"n":47,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":48,"t":"İkisinin de türlü türlü ağaçları vardır."},{"n":49,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":50,"t":"O çifte cennetlerden iki çağlayan akacak:"},{"n":51,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":52,"t":"O iki cennette her üründen çifter çifter çıkacak:"},{"n":53,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":54,"t":"Onlar çizgisi ve atkısı (dahil) ipekten mamul atlas halılara uzanacak; o çifte cennetlerin (muhteşem) ürünleri (kendilerine) çok yakın olacak:"},{"n":55,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":56,"t":"Bu (cennetlerde), daha önce ne insanların ne de cinlerin asla ellerinin değmediği gözü dışarıda olmayan eşler olacak:"},{"n":57,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":58,"t":"Sanki o eşler inci ve yakut gibi (birbirine yakışan) güzellikleriyle (göz kamaştıracak):"},{"n":59,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":60,"t":"İyi olmanın karşılığı iyi (bulmak) değil de nedir:"},{"n":61,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":62,"t":"O cennet çiftinin berisinde, daha başka çifte cennetler:"},{"n":63,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":64,"t":"Uzayıp giden (göz alıcı) çifte yeşillikler:"},{"n":65,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":66,"t":"Bu cennet çiftinde (billurdan) sular fışkırtan iki fıskiye olacak:"},{"n":67,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":68,"t":"Bu çifte cennette (lezzetin kemalini temsil eden) meyveler, hurma ve çekirdeksiz nar bulunacak:"},{"n":69,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":70,"t":"Orada (her şeyin) en mükemmeli, en güzeli olacak:"},{"n":71,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":72,"t":"Çardaklar içinde, gözü gönlü dışarıda olmayan pırıl pırıl eşler:"},{"n":73,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":74,"t":"Daha önce görünür görünmez hiçbir varlığın dokunmadığı eşler:"},{"n":75,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":76,"t":"Onlar tarifsiz yemyeşil örtüler ve efsanevi güzellikte sergiler üzerinde uzanacak:"},{"n":77,"t":"o halde Rabbinizin hangi nimetini inkar edebilirsiniz?"},{"n":78,"t":"Azamet ve sonsuz ikram sahibi Rabbinin şanı pek yücedir!"}],[{"n":1,"t":"Gerçekleşmesi kesin olan o korkunç olay gerçekleştiği zaman,"},{"n":2,"t":"kimse kalmayacak onun gerçekliğini yalanlayan!"},{"n":3,"t":"O`dur (bazılarını) alçaltan, (bazılarını) yücelten."},{"n":4,"t":"Yer dehşetli bir sarsılışla sarsıldığında,"},{"n":5,"t":"ve dağlar paramparça olup"},{"n":6,"t":"toz zerrecikleri haline geldiğinde,"},{"n":7,"t":"sizler üç sınıfta tasnif edilmiş olacaksınız."},{"n":8,"t":"Bir bahtiyar kesime dahil olan kesim olacak; ama ne büyük bahtiyarlık!.."},{"n":9,"t":"Bir de bedbaht kesime dahil olan kesim olacak; ama ne felaket bir bedbahtlık!.."},{"n":10,"t":"Bir de yarışta öne geçip arayı açanlar olacak:"},{"n":11,"t":"İşte bunlardır Allah`a yakınlık sağlayanlar,"},{"n":12,"t":"sonsuz nimetlerle dolu has bahçelerde kalacak olanlar;"},{"n":13,"t":"bir kısmı öncekilerden,"},{"n":14,"t":"birazı da sonrakilerden..."},{"n":15,"t":"Emek mahsulü huzur tahtlarına kurulacaklar;"},{"n":16,"t":"onlara yaslanıp tarifsiz bir (sevinci) paylaşacaklar;"},{"n":17,"t":"ölümsüz gençlikler onları bekleyecek;"},{"n":18,"t":"tarifsiz güzellikte bir kaynaktan doldurulmuş bir o kadar tarifsiz ibrikler ve kadehlerle sunulan (içecekler);"},{"n":19,"t":"ne baş döndürür ne de sarhoş eder."},{"n":20,"t":"Ve her tür meyve ve kuruyemiş seçeneği..."},{"n":21,"t":"Ve canlarının çektiğinden tarifsiz lezzette kuş etleri..."},{"n":22,"t":"Ve kusursuz bakışlı temiz eşler;"},{"n":23,"t":"gün görmemiş inciler gibi..."},{"n":24,"t":"Önceden yaptıklarının bir ödülü olacak (bunlar);"},{"n":25,"t":"orada ne bir boş laf ne de kınanma duyacaklar;"},{"n":26,"t":"sadece denilecek ki: \"Mutluluklar!.. Mutluluklar!..\""},{"n":27,"t":"Bahtiyar kesime gelince: nedir o bahtiyar kesimin (ödülü)?"},{"n":28,"t":"Dikenlerinin yerini meyvelerin aldığı upuzun Sidr ağaçları arasında,"},{"n":29,"t":"yine çok gövdeli, misk kokulu ve parıltılı Muğaylan ağaçları,"},{"n":30,"t":"ve uzayıp giden serin gölgeler"},{"n":31,"t":"ve çağlayanlar..."},{"n":32,"t":"Bir de sınırsız çeşitlilikte limitsiz meyveler;"},{"n":33,"t":"ne bir kesintiye uğrar ne de yasaklanır..."},{"n":34,"t":"Ve yüksek döşekler..."},{"n":35,"t":"Çünkü Biz onları yepyeni bir yaratılışla inşa edeceğiz,"},{"n":36,"t":"ve onları bakir/bakire olarak var edeceğiz:"},{"n":37,"t":"Sevgi dolu, denk ve uyumlu;"},{"n":38,"t":"(Hepsi de) bahtiyar kesim için;"},{"n":39,"t":"bir kısmını öncekiler"},{"n":40,"t":"bir kısımını da sonrakiler teşkil edecek."},{"n":41,"t":"Ve bedbaht kesime gelince... Nedir o bedbaht kesimin (cezası)?"},{"n":42,"t":"Zehir gibi içe işleyen yakıcı bir ateş ve yürek dağlayan bir umutsuzluk içinde olacaklar;"},{"n":43,"t":"ve iç karartan boğucu bir gölge;"},{"n":44,"t":"ne serinletici, ne de rahatlatıcı..."},{"n":45,"t":"Çünkü onlar geçmişte refah içinde şımarıp azmıştılar;"},{"n":46,"t":"ve büyük ihanette ısrar etmiştiler;"},{"n":47,"t":"ve \"Ne yani\" demiştiler, \"biz ölüp gittikten, toza toprağa karışmış bir iskelet halini aldıktan sonra tekrar mı diriltileceğiz?"},{"n":48,"t":"Önden giden atalarımız da (diriltilecek), öyle mi?\""},{"n":49,"t":"De ki: \"Şüphesiz hem öncekiler hem de sonrakiler,"},{"n":50,"t":"elbet (sadece Allah tarafından) bilinen bir günün belirli vaktinde bir araya toplanacaklar."},{"n":51,"t":"Sonra siz ey sapıklar, yalanlayanlar!"},{"n":52,"t":"Elbet siz de o ağaçtan, zehirli cehennem ağacından yiyeceksiniz."},{"n":53,"t":"Artık karınları onunla dolduracaksınız."},{"n":54,"t":"Üzerine yürek dağlayan kavurucu (umutsuzluğu) içeceksiniz;"},{"n":55,"t":"hummalı develerin kanma bilmeyen içişi gibi...\""},{"n":56,"t":"Hesap Günü onların ağırlanışı işte böyle olacak."},{"n":57,"t":"Sizi yaratan Biziz; o halde (ey insanlar), bu gerçeği neden hala kabullenmezsiniz?"},{"n":58,"t":"Hiç attığınız o hayat tohumunu düşündünüz mü?"},{"n":59,"t":"Siz mi yaratıyorsunuz onu, yoksa bütün yaratışın kaynağı Biz miyiz?"},{"n":60,"t":"Aranıza ölüm kanunu koyan Biziz; ve Biz asla önüne geçilen biri değiliz;"},{"n":61,"t":"sizi benzerlerinizle değiştirme ve sizi bilmediğiniz bir mahiyette yeniden inşa etme hususunda."},{"n":62,"t":"Doğrusu ilk yaratılış (mucizesini) bilmiş olmanız lazım; o halde neden (ikinci yaratılış hakkında) ibret almıyor sunuz?"},{"n":63,"t":"Hiç toprağa ektiğiniz tohumu düşündünüz mü?"},{"n":64,"t":"Siz mi ekip büyütüyorsunuz onu, yoksa Biz miyiz ekip büyüten?"},{"n":65,"t":"Eğer dileseydik, onu çürüyüp un ufak olmuş bir ahşap kalıntısına çevirirdik de, şaşakalır (ve derdiniz ki):"},{"n":66,"t":"\"Eyvah, borçlu çıkan yine biz olduk!"},{"n":67,"t":"Daha beteri, mahrum kalan da biz olduk!\""},{"n":68,"t":"Hiç içtiğiniz suyu düşündünüz mü?"},{"n":69,"t":"Siz mi indiriyorsunuz onu bulutlardan, yoksa Biz miyiz indiren?"},{"n":70,"t":"Eğer dileseydik onu tuzlu ve acı bir su yapardık: şu halde neden hala şükretmiyorsunuz?"},{"n":71,"t":"Hiç tutuşturduğunuz ateşi düşündünüz mü?"},{"n":72,"t":"Siz mi yapıyorsunuz onun ağacını, yoksa Biz miyiz yapan?"},{"n":73,"t":"Biz onu bir hatırlama vesilesi ve kendi yalnızlığında kaybolmuş muhtaçlar için yarayışlı bir meta kıldık."},{"n":74,"t":"Şu halde azamet sahibi Rabbin adına hareket et!"},{"n":75,"t":"Ötesi yok! İşte Kur`an`ın parçalar halinde indirilişine yemin ediyorum;"},{"n":76,"t":"ki elbet bu, eğer farkındaysanız çok ağır bir yemindir."},{"n":77,"t":"Şüphesiz o, muhatabına değer yükleyen bir hitaptır:"},{"n":78,"t":"korunmuş bir kitap içindedir."},{"n":79,"t":"Ona ancak temizler dokunabilir:"},{"n":80,"t":"Alemlerin Rabbinden indirilmedir."},{"n":81,"t":"Şimdi böyle bir haberi, siz mi kirleteceksiniz?"},{"n":82,"t":"Böylece siz yalanla beslenmeyi alışkanlık haline getireceksiniz."},{"n":83,"t":"Peki ama, ya can boğaza gelince ne olacak?"},{"n":84,"t":"Ve siz o zaman dehşetle bakakalacaksınız."},{"n":85,"t":"Ve Biz ona sizden çok daha yakınızdır, fakat siz görmeyeceksiniz."},{"n":86,"t":"Ve eğer Bize borçlu olmadığınıza inanıyorsanız,"},{"n":87,"t":"(haydi) hayatı ona geri döndürün; tabi ki eğer (inancınızda) sadıksanız."},{"n":88,"t":"Ama eğer Allah`a yakın olanlardan iseniz;"},{"n":89,"t":"(yeriniz) tarifsiz bir huzur, bitimsiz bir rızık ve mutluluğun üretildiği cennetler (olur)."},{"n":90,"t":"Yok eğer bahtiyar kesimden biri olursanız:"},{"n":91,"t":"Artık, (ey) sözünün eri olan bahtiyarlardan olan kişi: sana selam olsun!"},{"n":92,"t":"Fakat eğer o, yalanlayıp da yoldan sapmışlardan biriyse:"},{"n":93,"t":"artık onun hakkı yürek yakan bir (umutsuzluk) sofrasında ağırlanmak"},{"n":94,"t":"ve çılgın bir ateşe atılmaktır."},{"n":95,"t":"Hiç şüphe yok ki bu, işte budur kesin gerçek:"},{"n":96,"t":"Öyleyse sen (ey insan), azamet sahibi Rabbin adına hareket et!"}],[{"n":1,"t":"Göklerde ve yerde olan her şey (onlara yaratılış amacını yükleyen) Allah adına hareket etti: zira mutlak üstün ve yüce olan, her hükmünde tam isabet kaydeden O`dur."},{"n":2,"t":"O`na aittir göklerin ve yerin mülkü; O yaşatır ve O öldürür; her şeye güç yetiren de O`dur."},{"n":3,"t":"el-Evvel ve el-Ahir`dir; ez-Zahir ve el-Batın`dır; ve O her şeyi en iyi bilendir."},{"n":4,"t":"O, gökleri ve yeri altı aşamada yaratmış, ardından hükümranlık makamına kurulmuştur. O hem toprağa giren ve orada çıkan her şeyi, hem de gökten inen ve onda yükselen her şeyi bilir. Nerede olursanız olun, O sizinle beraberdir ve Allah bütün yaptıklarınızı görmektedir."},{"n":5,"t":"Göklerin ve yerin mülkü O`nundur; ve bütün işler Allah`a döndürülür."},{"n":6,"t":"Geceyi O kısaltıp gündüzü O uzatıyor; yine gündüzü O kısaltıp geceyi O uzatıyor; zira O, göğüslerin en mahrem sırlarını bilendir."},{"n":7,"t":"Allah`a ve Rasulü`ne yürekten güvenin ve O`nun sizi kendisini emanetçi kıldığı şeylerden infak edin! Artık sizden iman ve infak eden kimseler için büyük bir ecir vardır."},{"n":8,"t":"Neden siz Allah`a inanıp güvenmeyesiniz; üstelik Rasul sizi Rabbinize inanıp güvenmeye çağırdığı, O da sizden söz almış olduğu halde? Tabi ki eğer inanmaya (gönüllü) iseniz?"},{"n":9,"t":"Kulu (Muhammed`e) sizi karanlıklardan aydınlığa çıkarmak için hakikatin apaçık belgeleri olan ayetleri indiren O`dur; çünkü Allah size karşı elbet çok şefkatli, çok merhametlidir."},{"n":10,"t":"Neden siz Allah yolunda infak etmeyesiniz ki; üstelik göklerin ve yerin mirasının sadece Allah`a ait olduğunu (bilip dururken)? İçinizden zor ve kor zamanlarda infak edenler ve savaşanlarla, (iş kolaya binince bunları yapanlar) bir olmaz; böyleleri derece olarak, daha sonra infak edenler ve savaşanlardan daha üstündür; ve böyle davranan herkese Allah en güzeli vaad etmiştir: ve Allah yaptığınız her şeyden haberdardır."},{"n":11,"t":"Kim Allah`a güzel bir borç verip de, onun kendisine kat kat fazlasıyla geri dönmesini ister? İşte böylelerini tarifsiz güzellikte bir ödül beklemektedir."},{"n":12,"t":"Bütün mü`min erkekleri ve mü`min kadınları önleri ve sağ taraflarını aydınlatan nurlarıyla hızla ilerlerken gördüğün gün onlara: \"Bu gün size müjde var: Zemininden ırmaklar çağlayan, içinde yerleşip kalacağınız cennetler!.. Bu, işte budur muhteşem zafer!\""},{"n":13,"t":"O gün bütün münafık erkekler ve münafık kadınlar mü`minlere (şöyle diyecekler): \"Bize bakın da ışığınızdan biz de yararlanalım!\" Onlara denilecek ki: \"Arkanızdaki (hayata) dönüp, kendinize (orada) bir ışık arayın!\" Derken onlarla mü`minler arasına kapısı olan bir sur çekilecek, onun iç tarafında rahmet bulunacak, dış tarafında ise azap."},{"n":14,"t":"(Münafıklar) seslenecekler: \"Biz sizinle beraber değil miydik? (Mü`minler) şöyle cevap verecekler: \"Elbette! Ama siz kendi kendinizi tuzağa düşürdünüz; böylece (güya) kendinizi gözettiniz; kuşkuya kapıldınız, Allah`ın emri gelinceye kadar malum kuruntularla avundunuz; dahası, o (kafa) sizi Allah ile aldatarak gurura sürükledi.\""},{"n":15,"t":"Artık bu gün, ne sizden ne de kafirlerden kurtuluş akçesi kabul edilmez. Son durağınız ateştir ve tek can dostunuz da odur: o ne kötü varış yeridir."},{"n":16,"t":"İman (ettiğini iddia) edenlerin, Allah`ın zikrine, yani Hak katında inen vahye karşı, ta kalplerinde ürperti duymalarının vakti hala gelmedi mi? Ta ki kendilerine daha önce vahiy verilip de, üzerlerinden uzun zaman geçtiği için kalpleri katılaşan kimseler gibi olmasınlar; ki onların bir çoğu yoldan sapmıştır."},{"n":17,"t":"İyi bilin ki Allah, ölümünden sonra toprağa can verir. İşte aklınızı kullanabilesiniz diye ayetlerimizi size böyle açıklamış bulunuyoruz."},{"n":18,"t":"İmana sadakatin bedelini ödeyen erkekler ve kadınlar ile Allah`a güzel bir borç verenlere gelince: (bu) onlara kat kat fazlasıyla geri dönecek ve tarifsiz güzellikte bir ödül onları bekleyecek."},{"n":19,"t":"Allah`a ve elçilerine (sadakatin bedelini ödeyerek) iman edenler var ya: onlardır doğruluk ve dürüstlük sembolü olanlar, yine onlardır Rableri katında şahitliğine (değer) verilenler; ödül de onların, ışık da onların olacak. Ama inkar eden ve ayetlerimizi yalanlayanlar, gözleri fal taşı gibi açan ateşe mahkum olacak."},{"n":20,"t":"İyi bilin ki (tek başına) bu dünya hayatı bir oyun ve oynaştan, albenili bir gösteri ve birbirinize karşı övünme yarışından, mal ve evlat çoğaltma hırsından ibaret olurdu. Bu (tiplerin sonu) şu yağmur meseline benzer: O (yağmurun) yeşerttikleri, çiftçileri/nankörleri pek sevindirir; sonra kurur ve sen onu sararmış görürsün; en sonunda toz toprak olur. Ama ahirette (böyle olmayacak). Ya şiddetli bir mahrumiyet veya Allah`tan bir mağfiret ve hoşnutluk olacak: Zira (tek başına) bu dünya hayatı, aldatıcı ve geçici bir tatmin aracından başka bir şey değildir."},{"n":21,"t":"Rabbinizin mağfiretine nail olmak, Allah`a ve elçilerine iman edenler için hazırlanan, alanı göğün ve yerin genişliği kadar olan cennete kavuşmak için birbirinizle yarışın! Bu Allah`ın (dileyene) vermeyi dilediği ikramıdır: zira Allah muazzam ikram sahibidir."},{"n":22,"t":"Ne yeryüzünün ne de sizin başınıza, daha önceden kayıt altına aldığımız bir yasa olmadıkça asla bir musibet gelmez: şüphesiz bu Allah için pek kolaydır."},{"n":23,"t":"Böyle takdir etmiştir ki elden kaçırdıklarınıza (aşırı) üzülmeyesiniz, ele geçirdiklerinize de (aşırı) sevinmeyesiniz: nitekim Allah hiçbir kendini beğenmiş şımarığı sevmez."},{"n":24,"t":"Cimrilik edenler ve insanlara da cimriliği teklif edenlere gelince: kim (O`na) sırt çevirirse, iyi bilsin ki Allah, evet O kendi kendine yeten mutlak zengindir, hamdin tamamına layıktır."},{"n":25,"t":"Doğrusu Biz elçilerimizi hakikatin apaçık belgeleriyle gönderdik; onlarla birlikte Kitab`ı ve insanlığı adaletle ayakta tutsun diye mizanı indirdik; ve içinde hem kahredici bir güç hem de insanlar için sayısız faydalar bulunan demiri indirdik: Ki böylece Allah, kendisine ve elçilerine gıyapta destek çıkanları seçip ayırsın: Şüphesiz Allah tarifsiz bir güç sahibidir, mutlak üstün ve yüce olandır."},{"n":26,"t":"Doğrusu Nuh ve İbrahim`i de (aynı amaçla) göndermiştik; ve o ikisinin soylarından gelenlere peygamberlik ve vahiy vermiştik; fakat onlardan bir kısmı hidayete erdiler, ama bir çokları da yoldan saptılar."},{"n":27,"t":"Sonra onların peşinden (başka) elçilerimizi de getirdik; peşlerinden de Meryem oğlu İsa`yı getirdik ve ona İncil`i verdik; ve ona uyanların kalplerine şefkat ve merhamet yerleştirdik. Ama ruhbanlık başka... Onu kendilerine emretmediğimiz halde onlar uydurdu, gerekçesi de Allah`ın rızasını kazanmaktı; fakat onun gereklerine de hakkıyla riayet etmediler ya... Neticede Biz onlardan iman eden kimselere karşılıklarını verdik; fakat yine onlardan bir çoğu yoldan saptılar."},{"n":28,"t":"Siz ey (tevhide) iman eden (ehl-i kitab!) Allah bilinciyle hareket edin ve O`nun peygamberine iman edin ve O`nun peygamberine iman edin ki, O size rahmetinden iki kat versin! Yine size aydınlığında yürüyeceğiniz bir nur bahşetsin ve size mağfiret etsin: Zira Allah tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":29,"t":"Böylece önceki vahiyleri izleyenler kendilerinin Allah`ın lutfundan hiçbir şey elde edemeyeceklerini düşünmesinler; dahası, bu lutfun Allah`ın yetkisinde olup onu dilediğine verdiğini bilsinler: zira Allah muazzam ikram sahibidir."}],[{"n":1,"t":"Doğrusu Allah, kocası hakkında seninle tartışan ve nihayet (işini) Allah`a havale eden kadının başvurusunu kabul etmişti; zira Allah ikiniz arasında geçen konuşmayı işitiyordu: Çünkü Allah her şeyi işitendir, her şeyi tarifsiz görendir."},{"n":2,"t":"İçinizden \"Sen bana annem kadar haramsın\" diyerek eşlerinden ayrılanlara gelince: o kadınlar asla anneleri olamaz; onların anneleri yalnızca kendilerini doğuranlardır; ve şüphesiz onlar mantıksız, dahası düzme-koşma bir laf söylüyorlar: ama şüphe yok ki Allah, tarifsiz bir bağışlayıcı, eşsiz bir rahmet kaynağıdır."},{"n":3,"t":"Ne ki, \"Sen bana annem kadar haramsın\" diyerek eşlerinden ayrılanlar, ardından da söylediklerinden geri dönenler var ya: işte onların (keffareti) eşler birbirine yaklaşmadan önce bir köleyi özgür kılmaktır. Siz ancak böyle uslanırsınız. Ve Allah bütün yaptıklarınızdan ayrıntısıyla haberdardır."},{"n":4,"t":"Fakat kim bunu bulamazsa, yine eşler birbirine yaklaşmadan önce peş peşe iki ay oruç tutar; buna güç yetiremeyen kimseye ise altmış yoksulu doyurmak düşer. Bu Allah`a ve Rasulü`ne imanınızın bir gereğidir; ve bunlar Allah`ın çizdiği sınırlardır. İnkar edenler için, acıklı bir azap vardır."},{"n":5,"t":"Kuşku yok ki Allah`a ve Rasulü`ne meydan okuyanlar, -ki Biz onlara da hakikatin apaçık delillerini indirmiştik- tıpkı kendilerinden önce rezil edilenler gibi rezil edilecekler: zira inkar edenler için alçaltıcı bir azap vardır."},{"n":6,"t":"Gün gelip Allah onların hepsini diriltecek; yaptıkları her şeyi kendilerine bir bir haber verecek; onlar unutmuş olsalar bile, Allah onlara yaptıklarını bir bir sayıp dökecek: zira Allah her şeye ayrıntısıyla şahittir."},{"n":7,"t":"(Ey muhatab!) Görmedin mi ki Allah, göklerde ve yerde olan her şeyi bilir? Gizli görüşme yapan üç kişi yoktur ki dördüncüleri O olmasın; ve(ya) beş kişi yoktur ki altıncıları O olmasın: ister bundan daha az ister daha çok olsun; nerede olurlarsa olsunlar, illa ki O kendileriyle beraberdir. En sonunda Kıyamet Günü, yapıp ettiklerini onlara bir bir haber verecektir: şüphesiz Allah her şeyi hakkıyla bilendir."},{"n":8,"t":"(Ey Peygamber!) Gizli görüşmeden men edilen, sonra da men edildikleri şeye tekrar dönenleri görmedin mi? İşte onlar günah, düşmanlık ve Rasul`e isyan hususunda gizli kapaklı işler çeviriyorlar. Ne zaman sana gelseler, Allah`ın seni selamlamadığı biçimde seni selamlıyorlar ve kendi aralarında \"Hadi bakalım, Allah sözlerimizden dolayı bizi cezalandırsa ya!\" diyorlar. Cehenneme kadar yolları var! Oraya dikilecekler! O ne kötü son duraktır."},{"n":9,"t":"Siz ey iman edenler! Gizli görüşme yapacaksanız (bile), günah, düşmanlık ve Rasul`e isyan hususunda gizli görüşme yapmayın da, bari iyilik ve takva üzere gizli görüşme yapın! Huzurunda toplanacağınız Allah`a karşı sorumluluğunuzun bilincinde olun!"},{"n":10,"t":"(Bunun dışında kalan) gizli görüşmelerin tümü, sadece mü`minlere üzüntü vermeyi amaçlayan Şeytani bir eylemdir; ne ki Allah`ın izni olmadan, onlara hiçbir zararı dokunamaz: artık inananlar sadece Allah`a dayansınlar."},{"n":11,"t":"Siz ey iman edenler! Sosyal hayatta \"Birbirinize yer açın!\" denildiğinde derhal yer açın ki, Allah da size yer açsın. Yine \"Davranın!\" denildiği zaman, derhal yerinizden fırlayın! Allah içinizden tam inanan, bilen ve bilginin amacını kavrama yeteneğiyle donatılanları kat be kat yüceltecektir: Zira Allah yapıp ettiklerinizden tümüyle haberdardır."},{"n":12,"t":"Siz ey iman edenler! Elçi ile özel görüşme talep ettiğinizde (münafıklardan ayırt edilmeniz için), görüşmenizden önce bir sadaka veriniz; bu sizin için daha hayırlı ve daha (iç) arıtıcıdır; yok eğer buna (imkan) bulamazsanız, iyi bilin ki Allah tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":13,"t":"(Elçi ile) özel görüşme talebinizden önce, sadaka türü bir şeyler vermekten dolayı sizde şafak attı, öyle mi? Hemen belli oldu bunu yapamayacağınız ve Allah sizin pişmanlığınızı kabul etti: haydi artık namazı hakkını vererek kılın, zekatı gönlünüzden gele gele verin, Allah`a ve Rasulüne itaat edin: zira Allah yaptıklarınızdan ayrıntısıyla haberdardır."},{"n":14,"t":"Allah`ın gazabına uğrayan bir toplulukla dayanışma içine girenleri görmez misin? Onlar ne sizdendir ne de onlardandır; bir de (utanmadan) bile bile yalan yere yemin ediyorlar."},{"n":15,"t":"Allah onlara şiddetli bir azab hazırlamıştır; çünkü onlar öteden beri pek berbat bir iş işliyorlar."},{"n":16,"t":"Onlar yeminlerini (inkarlarına) örtü yaptılar; böylece Allah yolundan saptılar ve saptırdılar: Onlar alçaltıcı bir azaba duçar olacaklar."},{"n":17,"t":"Ne malları ne de çocukları onları Allah`a karşı asla korumayacaktır: işte onlar ateş ehlidirler; onlar orada kalıcıdırlar."},{"n":18,"t":"Gün gelip Allah onların tümünü diriltecek, (yaptıklarını bir bir haber verecek); bunun üzerine onlar size yemin ettikleri gibi O`na da yemin edecekler ve bu yolla bir şey elde etme hesabı yapacaklar: bakın işte bunlar, evet bunlardır yalanı tabiat edinenler."},{"n":19,"t":"Şeytan onlar üzerinde egemenlik kurmuş ve sonunda onlara Allah`ı hatırlamayı unutturmuştur. İşte bunlar Şeytanın yoldaşıdırlar. Bakın, Şeytanın yoldaşları var ya: işte onlar hüsrana uğrayacaklar."},{"n":20,"t":"Bir de Allah`a ve Rasulüne meydan okuyanlar var: işte onlar da en alçaklar sınıfına dahildirler."},{"n":21,"t":"(Zira) Allah şöyle diledi: \"Elbet Ben galip geleceğim; Ben ve elçilerim! Şüphe yok ki Allah tarifsiz güçlüdür, mutlak üstün ve yüce olandır."},{"n":22,"t":"Allah`a ve ahiret gününe iman eden bir topluluğu, Allah ve Rasulüne meydan okuyan kimselerle -isterse bunlar babaları, oğulları, kardeşleri veya soydaşları olsun- candan-yürekten bir ilişki içinde bulamazsın. İşte (Allah`ın kalplerine imanı nakşettiği ve katından manevi bir güç ile desteklediği kimseler onlardır; onları zemininden ırmaklar çağıldayan cennetlere, içinde daimi kalmak üzere yerleştirecektir: Allah onlardan razı olmuş, onlar da Allah`tan razı olmuşlardır. İşte gerçek Allah taraftarları bunlardır. Bakın, Allah taraftarları var ya: işte kurtulacak olanlar kesinlikle onlardır!"}],[{"n":1,"t":"Göklerde olan her şey ve yerde olan her şey Allah için hareket etti de, (bu sonuç öyle alındı): zira O`dur her işinde mükemmel olan, her hükmünde tam isabet kaydeden."},{"n":2,"t":"O`dur kitap ehlinden nankörlük edenleri ilk kalkışmada yurtlarından çıkaran. Siz onların bırakıp gideceklerine zerrece ihtimal vermemiştiniz, onlar da kalelerinin kendilerini Allah`a karşı savunacağını sanmışlardı. Allah onların (üzerine) hiç beklemedikleri yerden geldi ve kalplerine korku saldı: hanelerini kendi elleriyle ve mü`minler eliyle harap ettiler. Şu halde, ibret alın ey ileri görüş sahipleri!"},{"n":3,"t":"Allah onlar için sürgünü takdir etmemiş olsaydı, elbet onlara dünyada (daha beter) mahrumiyet yaşatırdı; zaten, öbür dünyadaki ateşin azabı onları beklemektedir."},{"n":4,"t":"Bu onların Allah`a ve O`nun elçisine karşı konuşlanmaları yüzündendir; kim de Allah`a karşı konuşlanırsa, unutmasın ki Allah`ın azabı çetindir."},{"n":5,"t":"Onların hurma ağaçlarından her ne kesmiş veya kökü üzere bırakmışssanız, hepsi de Allah`ın izniyle olmuştur; gerekçesi de sapkınları cezalandırmaktır."},{"n":6,"t":"Yine Allah`ın, o kimselerden alıp Elçisi`nin tasarrufuna verdiği kansız ve zahmetsiz savaş gelirleri; üstelik (onu ele geçirmek için) ne atlı ne de develi akınlar düzenlemiş de değildiniz; ne var ki Allah, elçilerini dilediğinin başına sarar: ve Allah her şeye güç yetirendir."},{"n":7,"t":"Allah, malum beldelerin sakinlerinden alıp iade ettiği tüm savaş gelirlerinin sorumluluğunu Rasulü`ne vermiştir: Artık (bu gelirler) Allah`a, Rasulüne, (onun) yakınlarına, yetimlere, yoksullara ve yolculara aittir: bunu böyle yaptık ki, servet (sırf) zengin sınıflarınız arasında dolaşan bir güç ve iktidar aracına dönüşmesin. İmdi, Rasul size (ondan) ne (pay) verirse onu alın, ama size vermediği şeyde de ısrarcı olmayın: Allah`a karşı sorumlu davranın; unutmayın ki Allah cezası çetin olandır."},{"n":8,"t":"(Bu gelirler), yurtlarından ve mallarından uzaklaştırılan muhacirler arasındaki fakirlere (verilir); Allah`tan kendilerine ulaşacak bir lütuf ve rızanın peşine düşen, Allah`a ve Rasulüne yardım eden kimseler bunlardır: İşte onlar, evet onlar (iman) sözüne sadık olanlardır."},{"n":9,"t":"Bir de, onlar (gelmeden) önce kendilerine yurdu hazırlayan ve imanı (yerleştiren) kimselere (verilir); onlar kendilerine sığınan muhacirleri severler, diğerlerine verilenlerden dolayı içlerinde bir hasislik duymazlar; dahası kendileri çok muhtaç halde bulunsalar da, başkalarını kendilerine tercih ederler. Evet, başkasının elindekine göz dikmekten korunanlar var ya: işte onlar kurtuluşa erenlerin ta kendileridir."},{"n":10,"t":"Onlardan sonra gelenler şöyle yakarırlar: \"Rabbimiz! Bizi ve bizden önce imanla göçüp gitmiş olanları bağışla! İman edenlere ilişkin gönlümüzde en küçük bir kin bırakma! Rabbimiz! Şüphe yok ki Sen çok şefkatli, çok merhametlisin!"},{"n":11,"t":"Nifakta direnenlerin, önceki vahyin mensuplarından küfre gömülen yoldaşlarına şöyle diyebilecekleri aklına gelir mi: \"Eğer siz çıkarılırsanız kesinlikle biz de sizinle birlikte çıkacağız; sizin hakkınızda hiçbir kimsenin sözüne ebediyen itibar etmeyeceğiz; yok eğer size karşı savaş açılırsa kesinlikle size yardım edeceğiz\"? Allah şahit ki, onlar yalancının daniskasıdırlar."},{"n":12,"t":"Eğer onlar çıkarılsalar, berikiler onlarla beraber çıkmazlar; onlara karşı savaş açılacak olsa yardım etmezler; tut ki yardım ettiler, sonunda arkalarını dönüp kaçarlar da, kimseden de yardım alamazlar."},{"n":13,"t":"Elbet onların içlerine Allah`tan daha çok sizin korkunuz sinmiş: bunun gerekçesi, onların sığ anlayışlı bir topluluk olmalarıdır."},{"n":14,"t":"Onlar ittifak kursalar dahi, müstahkem mevzilerde olmadıkça, ya da sur diplerine saklanmadıkça sizinle savaşmayı göze alamazlar. Kendi aralarında şiddetli bir rekabet vardır; sen onları birlik içinde sanırsın, ama kalpleri darmadağınıktır: Bunun gerekçesi de, onların aklını kullanmayan bir topluluk olmalarıdır."},{"n":15,"t":"(Onların akıbeti de), kendilerinden hemen önce yaptıklarının acısını tadanların akıbetine benzeyecektir; dahası onları can yakıcı bir azap beklemektedir."},{"n":16,"t":"Tıpkı malum Şeytan örneğinde olduğu gibi: Hani o insana \"inkar et\" diye telkin eder, ona uyup inkar edince de \"Ben senin yaptığından sorumlu değilim, çünkü ben alemlerin Rabbi Allah`tan korkarım\" der."},{"n":17,"t":"Sonuçta o iki (zümre)nin akıbeti de içinde yerleşip kalacakları ateş olacaktır: zira, zalimlerin cezası budur."},{"n":18,"t":"Siz ey iman edenler! Allah`a karşı sorumlu olduğunuzu bilin! Şimdi herkes, (kendisine) malum olmayan bir yarın için ne hazırladığına bir baksın! Ve (bir kez daha): Allah`a karşı sorumlu olduğunuzu bilin! Çünkü Allah yaptığınız her şeyden haberdardır."},{"n":19,"t":"Aman ha, kendileri Allah`ı unutan, bunun sonucu olarak da Allah`ın kendilerini bizzat kendilerine unutturduğu sorumsuzlar gibi olmayın! İşte onlar, evet onlardır yoldan sapanlar."},{"n":20,"t":"Ateşe layık olanlarla cennete layık olanlar, asla bir tutulamazlar: cennete layık olanlar var ya, işte onlardır kurtuluşa erenler."},{"n":21,"t":"EĞER Biz bu Kur’an’ı bir dağa indirmiş olsaydık, onun Allah’a saygıdan boyun eğmiş bir halde parçalanıp dağıldığını görürdün. İşte bu türden temsilî anlatımları, insanların önüne, belki düşünürler diye koyuyoruz."},{"n":22,"t":"O, kendisinden başka ilah olmayan Allah`tır: İdrak edilemeyen ve edilebilen her şeyin alimi sadece O`dur; O özünde merhametli, işinde merhametlidir."},{"n":23,"t":"O, kendisinden başka ilah olmayan Allah`tır: varlığın mutlak hakimidir, kutsalın kaynağıdır, mutlak kurtuluş ve huzurun membaıdır, güven ve iman verendir, (iyi ile kötüyü belirlemede) mutlak otorite sahibidir, mutlak üstün ve yüce olandır, her şartta iradesini yürütendir, büyüklüğünde sınırsız olandır. Eşsiz yüce olan O, onların şirk koştukları her şeyin ötesindedir, aşkındır."},{"n":24,"t":"O Allah`tır; mutlak yaratıcıdır, var ettiğinin ilk örneklerini yaratandır, yarattığı ilk örneklere suret giydirendir. En güzel nitelikler ve tüm mükemmellikler Allah`a mahsustur: Göklerde ve yerde olan her şey O`nun adına hareket eder: zira O`dur her işinde mükemmel olan, her hükmünde tam isabet eden."}],[{"n":1,"t":"Siz ey iman edenler! Benim ve sizin düşmanlarınızı can dostlar edinmeyiniz! Siz onlara yürek dolusu sevgi sunuyorsunuz, ama onlar size gelen bütün hakikati kökten inkar edip Elçi`yi ve sizi, sırf Rabbiniz Allah`a iman ettiniz diye sürüp çıkarıyorlar. Doğrusu sizler de, Benim davam uğruna ve rızamı kazanmak için yapılmış bir cihad sonucunda çıkmıştınız. (Ama şimdi) onlara, fıtri sevgiyi gerekçe yaparak sır veriyorsunuz; ne ki Ben sizin gizlediklerinizi de, açığa vurduklarınızı da çok iyi bilirim: Artık sizden kim böyle yaparsa, işte o doğru yolun ortasında sapıtmış demektir."},{"n":2,"t":"Eğer onlar sizi gözlerine kestirirlerse, size düşmanlıklarını kesintisiz sürdürürler; dahası ellerini ve dillerini size kötülük yapmak için uzatırlar: zira onlar inkar etmenizi ta yürekten isterler."},{"n":3,"t":"Size ne yakınlarınızın ne de çoluk çocuğunuzun Kıyamet Günü hiçbir yararı olmaz; Allah aranızda (iyi-kötü) ayrımını gerçekleştirir: zira Allah yaptıklarınızı ayrıntısıyla görmektedir."},{"n":4,"t":"Doğrusu İbrahim`de ve ona uyanlarda sizin için güzel bir örneklik vardır. Hani onlar kendi kavimlerine şöyle demişlerdi: \"Bakın, biz sizden ve Allah`ın yanı sıra taptığınız her şeyden uzağız; biz sizi(n hayat tarzınızı) reddediyoruz; sizinle bizim aramızda, siz bir tek Allah`a ibadet edinceye kadar ebediyen sürecek bir düşmanlık ve nefret vardır.\" Tek istisna, İbrahim`in babasına \"Senin için kesinlikle Allah`tan mağfiret dileyeceğim; ama senin lehine Allah`tan bir şey elde etme yetkisine sahip değilim\" diye söz vermesiydi. (Size düşen şöyle yalvarmaktır): \"Rabbimiz! Yalnız Sana güvendik, yalnız Sana yöneldik: zira tüm yollar Sana çıkar!"},{"n":5,"t":"Rabbimiz! Bizi küfre gömülenlerin elinde oyuncak etme! Ve günahlarımızı bağışla, ey Rabbimiz: Zira Sen, evet Sensin mutlak üstün ve yüce olan, Sensin her hükmünde tam isabet kaydeden!"},{"n":6,"t":"Doğrusu onlar(ın bu tavrında), içinizden Allah`ı ve Ahiret Günü`nü gözeten kimseler için elbet güzel bir örneklik vardır; ama kim de (kafirleri) dost edinerek (bu emre) yüz çevirirse, iyi bilsin ki Allah kimseye muhtaç değildir, hamdin tamamı zatına mahsus olandır."},{"n":7,"t":"Mümkündür ki Allah, sizin düşman olarak algıladığınız kimselerle sizin aranızda bir sevgi var edebilir; ve Allah`ın (buna) gücü yeter; üstelik Allah tarifsiz bir bağış, eşsiz bir merhamet kaynağıdır."},{"n":8,"t":"Allah size, sizinle din savaşı yapmayan ve sizi yurtlarınızdan çıkarmayan kimselerle iyilik ve fedakarlığa dayalı bir ilişki geliştirmenizi yasaklamaz: Çünkü Allah fedakar olanları pek sever."},{"n":9,"t":"Allah size, yalnızca sizinle din savaşı yapan ve sizi yurtlarınızdan çıkaran veya sizin çıkarılmanıza destek verenlerle dostluk kurmanızı yasaklar: artık kim onlarla dostluk kurarsa, işte onlar zalimlerin ta kendileridir."},{"n":10,"t":"Siz ey iman edenler! Mü`min kadınlar muhacir olarak size geldiği zaman -her ne kadar Allah onların inancını çok iyi biliyor idiyse de- siz (yine de) onları imtihana tabi tutun; sonuçta eğer onların mü`min olduğundan emin olursanız, artık onları kafirlere geri göndermeyin: ne o kadınlar (kafir) eşlerine helaldir, ne de eşleri o kadınlara helaldir. Onların verdiklerini de kendilerine iade edin! Ve siz bu kadınların mehirlerini verdiğiniz sürece, onlarla nikahlanmanızda bir beis yoktur. Beri yandan, inkarda israr eden kadınların nikahına yapışmayın; onlara verdiğinizi isteyin, aynı şekilde onlar da verdiklerini sizden isteyebilirler. İşte bunlar Allah`ın hükmüdür; aranızdaki hükmü O verir: zira Allah her şeyi bilendir, hikmetle hükmedendir."},{"n":11,"t":"Eğer kafirlere kaçan hanımlarınızdan dolayı herhangi bir mağduriyet yaşarsanız, misillemede bulunarak mahsuplaşın; şöyle ki, eşlerin mağdur ettiği kocalara, (karıları için) harcadıklarına denk olan miktarı (onlara gönderilecek meblağdan keserek) siz verin: Ama, iman ettiğiniz Allah`a karşı sorumluluğunuzun bilincinde olun!"},{"n":12,"t":"Sen ey peygamber! Ne zaman mü`min kadınlar sana gelir de Allah`a hiçbir şeyi ortak koşmayacaklarına, çalmayacaklarına, zina etmeyeceklerine, çocuklarını katletmeyeceklerine, elleri ve ayakları arasında yalan düzüp koşarak iftira atmayacaklarına, (dinin) değerler sistemi konusunda sana isyan etmeyeceklerine dair biatlerini sunarlarsa, onların biatlerini kabul et ve Allah`tan onlar için mağfiret dile: Unutma ki Allah tarifsiz bir bağışlayıcıdır, eşsiz bir merhamet kaynağıdır."},{"n":13,"t":"SİZ ey iman edenler! Allah’ın gazabına uğrayan bir kavim olan ve kabirdekilerin (tekrar dirileceğinden) ümit kesen (müşrik) kâfirler gibi âhiretten ümit kesen (Yahudileri), dost ve müttefik edinmeyin!"}],[{"n":1,"t":"Göklerde olan her şey ve yerde olan her şey Allah adına hareket ettiler (de, bu kozmik düzen öyle oluştu): zira O`dur her işinde tek mükemmel olan, her hükmünde tam isabet kaydeden O`dur."},{"n":2,"t":"Siz ey iman edenler! Niçin söylemlerinizle eylemleriniz birbirine uymuyor!"},{"n":3,"t":"Yapmadığınız/yapmayacağınız şeyleri söylemeniz, Allah katında ağır (sonuçları) olan nahoş bir davranıştır."},{"n":4,"t":"Ama Allah, (bütün yapı taşları birbirine kenetlenmiş) kurşundan bir bina gibi, Kendi yolunda saf saf savaşanları sever."},{"n":5,"t":"(Sizin bu durumunuz), Musa`nın kavmine \"Ey kavmim! Benim Allah`ın elçisi olduğumu çok iyi bildiğiniz halde niçin beni üzüyorsunuz?\" (dediği) zaman ki durumu hatırlatıyor. Ve onlar ne zaman yoldan saptılarsa, Allah da onların kalplerinin sapmasına izin verdi: zira Allah, yoldan sapmış bir topluluğu (onun iradesi hilafına) asla rehberliğini bahşetmez."},{"n":6,"t":"Yine bir zamanlar Meryem oğlu İsa`nın; \"Ey İsrailoğulları! Elbet ben, Tevrat`tan bana kadar gelen tüm hakikatleri doğrulamak ve benden sonra gelecek Ahmet adındaki bir elçiyi müjdelemek için size gönderilen Allah elçisiyim\" dediğini hatırlatıyor. O onlara hakikatin apaçık belgeleriyle geldiğinde, \"Bu ayan açık bir sihirdir!\" dediler."},{"n":7,"t":"İslam`a davet edildiği halde, uydurduğu yalanı Allah`a isnat edenden daha zalim biri olabilir mi? Zaten Allah, zulme gömülmüş bir topluluğa asla rehberliğini bahşetmez."},{"n":8,"t":"Onlar Allah`ın (hidayet) nurunu üfürükleriyle söndürmek için can atıyorlar; kafirler istemese de Allah nurunu tamamlayacaktır."},{"n":9,"t":"Allah`tan başkasına ilahlık yakıştıranlar hoşlanmasa da, Elçi`sini yol rehberliği ve (hak) dini kendi bütünlüğü içinde tamamen ortaya koymak için Hakk`ın dini ile gönderen O`dur."},{"n":10,"t":"Siz ey iman edenler! Sizi can yakıcı bir azaptan kurtaracak bir alışverişe yönledireyim mi?"},{"n":11,"t":"Allah`a ve Elçi`sine güvenirseniz, Allah davası uğrunda mallarınızla ve canlarınızla cihad ederseniz: böyle yapmanız sizin için daha hayırlıdır; tabi eğer bilgiyle (hareket) ederseniz."},{"n":12,"t":"(Böyle yaparsanız) O sizin günahlarınızı bağışlayacak ve sizi zemininden ırmakların çağladığı cennetlere koyacaktır; kalıcı güzelliğin merkezi olan cennetlerdeki tarifsiz huzur köşklerine: işte muhteşem final budur!"},{"n":13,"t":"Ve kendisiyle sevineceğiniz bir şey daha var: Allah`tan bir yardım ve görünen bir zafer. Artık mü`minlere müjde ver!"},{"n":14,"t":"Siz ey iman edenler! Allah`ın destekçileri olun! Tıpkı Meryem oğlu İsa`nın, havarilerine \"Allah`a giden yolda kim bana var gücüyle destek olur?\" deyince, havarilerin \"Biziz Allah davasının gönüllü destekçileri!\" demeleri gibi... Nitekim İsrailoğullarından bir gurup (ona) inandı, bir gurup da inkar etti. Bunun üzerine Biz de iman edenleri düşmanlarına karşı dirençli kıldık: Sonunda galip gelenler onlar oldu."}],[{"n":1,"t":"Göklerde olanlar da, yerde olanlar da mutlak otorite sahibi, mukaddes, her işinde mükemmel ve her hükmünde tam isabet sahibi Allah için hareket ederler."},{"n":2,"t":"Daha önce kitaptan mahrum olan ve derin bir sapıklık içinde bulunan topluma kendi ayetlerini okumak, onları arındırmak, kitabı ve isabetli hüküm vermeyi öğretmek için kendi içlerinden bir Elçi gönderen O`dur."},{"n":3,"t":"Üstelik henüz onlara katılmamış (ama katılmayı bekleyen) daha başkaları da var. Mutlak üstün ve yüce olan, her hükmünde tam isabet kaydeden O`dur."},{"n":4,"t":"İşte bu, Allah`ın (hak edene) vermeyi dilediği lütfudur: Zira Allah büyük lütuf sahibidir."},{"n":5,"t":"Tevrat`ı taşıma sorumluluğu kendilerine verilip de sorumluluğunun gereğini yerine getirmeyenlerin durumu, kitaplar yüklenmiş (fakat sırtındakinin değerinden bihaber olan) eşeğin durumu gibidir. Allah`ın ayetlerini yalanlayan toplumun temsil ettiği şey ne kötüdür! Ve Allah zalim bir topluma rehberliğini bahşetmez."},{"n":6,"t":"De ki: \"Ey Yahudiler! Eğer siz, öteki bütün insanları dışlayarak sadece kendinizin Allah`ın dostları olduğunu iddia ediyorsanız, haydi ölümü temenni etsenize, tabi eğer iddianızda sadıksanız?\""},{"n":7,"t":"Elleriyle yaptıkları yüzünden asla (ölümü) temenni etmeyeceklerdir: Allah zulme gömülüp gidenleri çok iyi bilmektedir."},{"n":8,"t":"De ki: \"Bakın, şu kendisinden kaçtığınız ölüm var ya, işte o sizi mutlaka yakalayacaktır. Ardından idraki aşan ve idrak edilebilen tüm hakikatleri bilene döndürüleceksiniz: ve size yapıp ettikleriniz bir bir haber verilecek."},{"n":9,"t":"Siz ey iman edenler! Cuma günü namaza çağrıldığınızda, alışverişi keserek Allah`ın öğüdüne koşun! Eğer (hayır ile çıkar arasındaki farkı) bilirseniz, bu sizin için daha hayırlıdır."},{"n":10,"t":"Ve namaz kılındığı zaman da, artık yeryüzünde dağılın ve Allah`ın lutfundan (payınıza) düşeni talep edin! Ama Allah`ı hiç hatırdan çıkarmayın ki, ebedi mutluluğa ulaşabilesiniz."},{"n":11,"t":"Ama onlar bir ticari menfaat veya bir eğlence gördüklerinde, hemen ona doğru seğirtip seni (konuşurken) ayakta öyle bir başına bırakıverdiler. De ki: \"Allah katında bulunan, eğlenceden de, ticari menfaatten de daha hayırlıdır: zira Allah rızık verenlerin en hayırlısıdır."}],[{"n":1,"t":"İkiyüzlüler sana geldiklerinde, \"Biz şahadet ederiz ki sen kesinlikle Allah`ın Rasulü`sün\" derler. Allah da biliyor ki, gerçekten de sen O`nun Rasulü`sün; ve Allah şahadet eder ki, ikiyüzlüler kesinlikle yalancıdırlar."},{"n":2,"t":"Onlar yeminlerinin arkasına saklandılar; bu yolla Allah yolundan saptırdılar: Elbet yaptıkları şey pek fenadır."},{"n":3,"t":"Bunun nedeni, onların önce iman edip sonra inkar etmeleridir; sonunda kalplerine mühür vurulmuştur: artık onlar (imanın hakikatini) kavrayamazlar."},{"n":4,"t":"Sen onları gördüğünde kalıpları hoşuna gider; ve konuşacak olsalar sözlerine kulak verirsin: giydirilmiş kalaslar gibidir onlar. Her çığlığı kendi aleyhlerine sanırlar; onlar kökten düşmandırlar: artık onlara karşı dikkatli ol! Allah onları kahretsin: Nasıl da savruluyorlar!"},{"n":5,"t":"Ve onlara: \"Gelin, Rasulullah size mağfiret dilesin!\" denildiğinde, başlarını çevirirler; ve sen onların küstahça bir kibir içinde çekip gittiklerini görürsün."},{"n":6,"t":"Onlar için mağfiret dilesen de mağfiret dilemesen de, hiçbir şey değişmez: Allah onları asla bağışlamayacaktır; çünkü Allah yoldan çıkmış bir topluluğa rehberliğini bahşetmez."},{"n":7,"t":"Onlar, \"Rasulullah`ın yanındakilere yardımda bulunmayın ki (etrafından) dağılıp gitsinler\" diyen kimselerdir. Bakın, göklerin ve yerin hazineleri Allah`a aittir; fakat münafıklar (bu gerçeği bile) kavramıyorlar."},{"n":8,"t":"Onlar \"Şehre döndüğümüzde şerefli olan (biz)ler şerefsiz olanları oradan elbet sürüp çıkaracaktır\" diyorlar. Ama şeref Allah`a, O`nun Rasulüne ve mü`minlere aittir: gel gör ki, ikiyüzlüler (bunu bile) bilmiyorlar."},{"n":9,"t":"Siz ey iman edenler! Ne mallarınız ne de çocuklarınız, Allah`ı sizin gündeminizden düşürmesin. Kim bunu yaparsa, işte onlar kaybedenlerin ta kendileridir."},{"n":10,"t":"Sizden birine ölüm gelip de, \"Rabbim! Bana bir miktar daha süre tanısaydın da ben de hayır hasenat yapıp iyilerden olsaydım!\" diyeceği (o gün) gelip çatmadan önce, size rızık olarak verdiklerimizden bir kısmını infak edin!"},{"n":11,"t":"Ama vakti geldiği zaman, Allah hiçbir canı ertelemez. Sonuçta Allah yaptığınız her şeyden haberdardır."}],[{"n":1,"t":"Göklerde olan şeyler de, yerde olan şeyler de Allah adına hareket ederler: mutlak otorite O`na aittir, övgülerin tamamı da O`na aittir; zira O her şeye kadirdir."},{"n":2,"t":"Sizi yaratan O`dur; ama içinizden hakikati inkar eden de, hakikate iman eden de var: ve Allah yaptığınız her şeyi görendir."},{"n":3,"t":"Gökleri ve yeri gerçek bir amaç uğruna O yarattı; ve size O şekil verdi, üstelik şeklinizi en güzel biçimde takdir etti; ama (o suret de fanidir), her halükarda dönüş O`nadır."},{"n":4,"t":"O, göklerde ve yerde olan her şeyi bilir; yine gizlediklerinizi ve açıkladıklarınızı da bilir: zira Allah göğüslerdeki (en mahrem) sırları bilendir."},{"n":5,"t":"Daha önceden inkara gömülüp gidenlerin haberi size gelmedi mi? Onlar da yaptıklarının kötü sonuçlarını (daha burada) tattılar; bir de (ötede) onları can yakıcı bir mahrumiyet beklemektedir."},{"n":6,"t":"Böyledir, çünkü elçileri kendilerine hakikatin apaçık belgeleriyle gelmiş, fakat onlar \"Bize ölümlü biri mi yol gösterecek?\" demişlerdi. İşte böylece küfre saptılar ve (haktan) yüzçevirdiler. Ama Allah (kimseye) muhtaç değildi: zira Allah kendi kendine yetendir, tüm övgülere layık olandır."},{"n":7,"t":"Hakikati inkara şartlanmış olanlar yeniden diriltilmeyeceklerini sandılar. De ki: \"Hayır! Rabbime andolsun ki kesinlikle diriltileceksiniz; sonra yaptıklarınız bir bir gösterilecek: zira bu Allah`a çok kolaydır."},{"n":8,"t":"Şu halde (ey insanlar!) Allah`a, Elçi`sine ve indirdiğimiz nura inanın: Allah yaptıklarınızdan haberdardır."},{"n":9,"t":"Toplanma günü geldiğinde O sizi bir araya toplayacaktır. O gün karşılıklı aldanış günüdür. Ama kim Allah`a iman eder ve Allah rızası için iyi davranışta bulunursa, onun kötülüklerini örteriz; onu zemininden ırmaklar çağlayan cennetlere -orada ebedi kalmak üzere- sokarız: işte büyük başarı budur."},{"n":10,"t":"Hakikati inkar eden ve ayetlerimizi yalanlayanlara gelince: işte onlar içerisinde kalıcı oldukları ateşin yoldaşıdırlar: ve bu, ne berbat bir finaldir."},{"n":11,"t":"Allah`ın izni olmadıkça, (insanın) başına hiçbir musibet gelmez; ve her kim Allah`a inanıp güvenirse, O onun (akleden) kalbine rehberlik eder: zira Allah her şeyi hakkıyla bilendir."},{"n":12,"t":"Allah`a itaat edin ve Resule de itaat edin. Şayet yüz çevirecek olursanız, artık elçimiz üzerine düşen (yalnızca) apaçık olan bir tebliğ (gerçeği en yalın biçimde size iletme)dir."},{"n":13,"t":"Allah, O`ndan başka ilah olmayandır: O halde mü`minler yalnızca Allah`a güvenip dayansınlar!"},{"n":14,"t":"Siz ey iman edenler! Eşlerinizden ve çocuklarınızdan size düşman olanlar var. Her ne kadar affedici, hoşgörülü ve bağışlayıcı olsanız da, yine de onlara karşı dikkatli olun! Fakat bilin ki Allah da tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."},{"n":15,"t":"Mallarınız ve çocuklarınız birer imtihan aracından ibarettir; Allah`a gelince: O, katında muhteşem bir ödül bulunandır."},{"n":16,"t":"Şu halde, ne kadar gücünüz yetiyorsa Allah`a karşı o kadar sorumlu davranın: hem (O`nu) dinleyin, hem (O`na) itaat edin! Ve kendi hayrınıza olmak üzere infak edin! Kim kişiliğinin (zaafı olan) açgözlülükten (infak ile) korunursa, ebedi kurtuluşa nail olanlar işte onlardır."},{"n":17,"t":"Eğer Allah`a güzel bir borç verirseniz, (Allah) kat kat artırarak size döndürecek ve sizi bağışlayacaktır: Zira Allah tüm şükürleri hakeden tek otoritedir, (şükürsüzlüğü) cezalandırmada acele etmeyendir;"},{"n":18,"t":"O, idraki aşan hakikatlerin de, idrak alanına giren gerçeklerin de sırrına vakıf olandır; Her işinde mükemmel, her hükmünde tam isabet edendir."}],[{"n":1,"t":"Sen ey peygamber! Kadınlarınızı boşamak (istediğinizde), onları bekleme sürelerini gözeterek boşayın ve iddeti sayın. Allah`a karşı sorumlu olduğunuzu bilin. Onları (içinde yaşadıkları) evlerinden çıkarmayınız ve onlar da çıkmasınlar; tabi ki, ayan açık bir ahlaksızlık yapmaları hali müstesna. Bunlar Allah`ın çizdiği sınırlardır: Ve kim Allah`ın çizdiği sınırları aşarsa, artık o kendine zulmetmiş olur; (ve) sen bilemezsin (ey insan), belki de Allah bu (bekleyişin) ardından, birtakım yeni (ve hayırlı) gelişmelere kapı açabilir."},{"n":2,"t":"İmdi, sürelerinin sonuna yaklaştıklarında ya onları meşru bir biçimde tutun, ya da meşru bir biçimde ayırın; ve siz(in toplumunuz)dan iki kişiyi de şahit olarak bulundurun; ve (hepiniz) şahitliği Allah için dürüstçe yapın! Bakın, bütün bunlar, Allah`a ve Ahiret Günü`ne iman edenlere verilen bir öğüttür. Ve her kim Allah`a karşı sorumluluğunun bilincinde olursa, O onun için bir kapı aralar"},{"n":3,"t":"ve hiç beklemediği yerden onu rızıklandırır; ve her kim Allah`a güvenirse, artık O ona yeter: Şüphesiz Allah emrini gayesine erdirendir; doğrusu Allah her bir şey için bir ölçü/kader koymuştur."},{"n":4,"t":"Ve ay halinden tamamen kesilen kadınlarınız konusunda kuşkuya düşerseniz; bilin ki onların bekleme süresi üç aydır; hiç ay hali görmeyenlerin ki de öyledir; hamile olanların iddeti ise doğum yapıncaya kadardır. Ve her kim Allah`a karşı sorumluluğunun bilincinde olursa, O ona buyruğunu kolay kılar:"},{"n":5,"t":"İşte bu Allah`ın size indirmiş olduğu buyruğudur; kim Allah`a karşı sorumluluğunun bilincinde olursa, (Allah) onun günahlarını örter ve ona muazzam bir ödül verir."},{"n":6,"t":"(İddet bekleyen kadınlarınızı), imkanlarınız nisbetinde barındığınız şartlara uygun olarak barındırın; onlar üzerinde baskı kurup hayatlarını çekilmez hale getirmeyin; eğer hamileyseler, doğum yapıncaya kadar nafakalarını üstlenin; eğer (çocuğunuzu) sizin hesabınıza emzirirlerse, onlara hak ettikleri karşılığı verin ve (çocuğun geleceğini) kendi aranızda ortak değerler çerçevesinde istişare edin; eğer (emzirme konusunda) karşılıklı zorlanırsanız, bu takdirde (baba) hesabına bir başkasının emzirmesi gerekecektir."},{"n":7,"t":"(Neticede) imkanı olanlar, imkanları nisbetinde harcama yapsın; maddi imkanı dar olanlar da Allah`ın kendisine verdiği kadar harcama yapsın: Allah hiç kimseye verdiği imkandan fazlasını yüklemez; (belki de) Allah, bir zorluktan sonra bir kolaylık ihsan edecektir."},{"n":8,"t":"İmdi, Rablerinin ve O`nun elçilerinin emrini dinlemeyen nice topluluklar gelip geçmiştir; sonunda Biz hepsiyle pek çetin bir biçimde hesaplaşmış, inanılmaz bir azaba çarptırmışızdır:"},{"n":9,"t":"Nihayet yaptıklarının vebalini tatmışlar, işledikleri şeyler sonucunda yıkıma uğramışlardır."},{"n":10,"t":"(Dahası) Allah onlar için (ahirette) çetin bir azab hazırlamıştır. Şu halde ey akletme yeteneğini kamil manada kullananlar! Allah`a karşı sorumluluğunuzun bilincinde olun! (Ey bu vahye) iman edenler: siz de! Zira Allah size uyarıcı bir mesaj indirmiş;"},{"n":11,"t":"iman eden ve ıslak edici iyiliklerde bulunanları (küfrün) karanlıklarından (imanın) aydınlığına çıkarmak için, Allah`ın apaçık ayetlerini okuyan bir elçi göndermiştir. Her kim Allah`a inanır ve ıslah edici iyilikler yaparsa, içinde ebedi kalmak üzere (Allah) onu zemininden ırmaklar çağlayan cennetlere koyar: böylece Allah ona tarifsiz güzellikte bir rızık vermiş olur."},{"n":12,"t":"Allah, yedi kat gökleri ve yerden de bir o kadarını yaratandır. O`nun (yaratıcı) iradesi, bu ikisi arasında her an yenilenerek sürekli tecelli eder ki, Allah`ın her şeye muktedir olduğunu ve her şeyi akıl sır ermez bir ilimle kuşattığını kavrayasanız."}],[{"n":1,"t":"Sen ey peygamber! Eşlerin(den bir kısmının) rızasını kazanmak için, neden Allah`ın helal kıldığı şeyi kendine haram ediyorsun? Yine de Allah çok bağışlayıcıdır, sınırsız bir merhamet kaynağıdır."},{"n":2,"t":"Doğrusu Allah, (kendinizi gereksiz yere bağladığınız) yeminlerinizi bozup keffaretini verebileceğinizi size bildirir; zira Allah sizin efendinizdir: Ve O her şeyi bilendir, her hükmünde tam isabet edendir."},{"n":3,"t":"Hani, bir gün Peygamber eşlerinden birini bir hadiseden (dolayı) sırrına ortak etmişti; fakat eşi bu sırrı ifşa edip Allah da onu (Peygamber`e) bildirince, (Peygamber) o hadisenin bir kısımını (diğer eşine) de anlatmış, ama bir kısmından hiç söz etmemişti. Nihayet (Peygamber sır tutmayan) eşine yaptığı (yanlışı) bildirince, \"Bunu sana kim haber verdi?\" demişti. (Peygamber de), \"Her şeyi bilen, her şeyden haberdar olan haber verdi\" diye cevap vermişti."},{"n":4,"t":"(Onlara de ki): \"Eğer siz ikiniz Allah`a tevbe ederseniz (iyi olur); doğrusu her ikinizinde kalpleri kaymıştır! Siz ikiniz eğer ona karşı dayanışma içine girerseniz, unutmayın ki Allah, evet onun dostu O`dur; buna ilaveten Cebrail, mü`minlerin en seçkin olanları ve melekler de (onun) destekçileridir."},{"n":5,"t":"Farz edin ki o sizi boşadı; bu takdirde O`nun Rabbi yerinizi sizden çok daha iyi eşlerle doldurabilir: Allah`a tam teslim olan, O`na tam güvenip inanan, O`nun iradesini gerçekleştirmek için el pençe divan duran, hatada ısrar etmeyen, yalnız O`na kulluk eden, hayır yolunda koşan, dul ya da bakire eşler..."},{"n":6,"t":"Siz ey iman edenler! Kendinizi ve yakınlarınızı yakıtı insanlar ve taşlar olan tarifsiz bir ateşten koruyunuz! Ona memur melekler kararlı ve tavizsizdirler; hiçbir buyruğunda Allah`a karşı gelmezler ve kendilerine emredileni yaparlar."},{"n":7,"t":"Siz ey küfrü tabiat haline getirenler! Bugün mazaret ileri sürmeyin! Şimdi sadece yapmış olduklarınızın karşılığını göreceksiniz."},{"n":8,"t":"Siz ey iman edenler! Samimi bir kalp ile tevbe ederek içten bir sadakatle Allah`a yönelin! Umulur ki Rabbiniz günahlarınızı örter ve Allah`ın peygamber ve ona katılarak iman edenleri mahcup etmeyeceği o gün, sizi zemininden ırmakların çağladığı cennetlere koyar: Onlar önlerinden ve sağlarından ışık saçarlar ve şöyle dua ederler: \"Rabbimiz! Nurumuzu tamamla ve bizi bağışla: çünkü sen her şeye kadirsin!"},{"n":9,"t":"Sen ey peygamber! İnkar edenlere ve ikiyüzlülüğü huy edinenlere karşı cihat et ve onlara karşı tavizsiz ol! (Böyle giderlerse) varacakları yer cehennemdir: orası ne berbat bir son duraktır."},{"n":10,"t":"Allah nankörlük edenlere, Nûh’un karısı ile Lût’un karısını misal verdi; Bu ikisi iki iyi kulumuzun nikâhı altındaydılar; fakat kocaların(ın misyonların)a ihanet etmişlerdi. (Bu iki kadına) “Ateşe girenlerle birlikte siz de girin!” denildiği (gün), iki (kocanın) varlığı da, onları Allah’ın cezasına uğramaktan asla koruyamadı."},{"n":11,"t":"İman edenlere ise Allah, Firavun`un karısını örnek göstermiştir: Hani o demişti ki: \"Rabbim! Lütfu kereminden bana cennette sade bir ev ihsan et; beni Firavun`dan, onun (çirkin) amelinden ve zalim kavmin (şerrinden) kurtar!\""},{"n":12,"t":"İmran`ın kızı Meryem`i de (örnek göstermiştir): O (Meryem) ki iffetini korumuş, buna karşılık Biz de onun (rahminde)kine ruhumuzdan üflemiştik; o da Rabbinin kelimelerini ve O`nun kitaplarını gönülden tasdik etmişti: zira o, Allah`ın iradesini gerçekleştirmek için el pençe divan duranlardan biriydi."}],[{"n":1,"t":"Mutlak hükümranlık kudret elinde bulunan (Allah) ne yüce, ne ulu bir bereket kaynağıdır; ve O her şeye kadirdir."},{"n":2,"t":"O, ölümü ve hayatı hanginizin daha güzel davranacağını sınamak için yaratmıştır. O mutlak üstün ve yüce olandır, eşsiz ve benzersiz bağışlayandır."},{"n":3,"t":"O, yedi göğü eşsiz bir uyum içinde yaratmıştır; Rahman`ın yaratışında bir düzensizlik göremezsin; haydi, çevir gözünü de bir bak bakalım: bir kusur ve başıboşluk görebilecek misin?"},{"n":4,"t":"Sonra tekrar tekrar çevir gözünü de bir bak; bakışın yılgın ve bezgin bir şekilde sana geri dönecektir."},{"n":5,"t":"Doğrusu Biz, en yakın göğü kandillerle süsledik; onları, Şeytan(lığa soyunan)lar için gayba dair spekülasyon aracı kıldık; ve onlar için yakıp kavuran bir azap hazırladık;"},{"n":6,"t":"zira Rablerine karşı (böyle) nankörlük yapanları Cehennem azabı beklemektedir: ne berbat bir son duraktır."},{"n":7,"t":"Onlar oraya atıldıklarında, onun kaynayış homurtusunu işitecekler;"},{"n":8,"t":"neredeyse öfkeden patlayacak... Günahkarların atıldığı her seferinde bekçiler, \"Size bir uyarıcı gelmemiş miydi?\" diye soracaklar."},{"n":9,"t":"\"Evet, doğrusu bize bir uyarıcı gelmişti; fakat biz onu yalanladık ve \"Allah hiçbir şey indirmemiştir; siz (elçiler) büyük bir şaşkınlık içindesiniz\" demiştik\" itirafında bulunacaklar."},{"n":10,"t":"Ve \"Eğer biz (vahyi) işitmiş veya aklımızı kullanmış olsaydık, şimdi kavurucu ateşe müstehak olanlar arasında bulunmazdık\" diyecekler."},{"n":11,"t":"Böylece günahlarını itiraf etmiş oldular: Olmaz olsun o harlı ateş ashabı!"},{"n":12,"t":"Beri yanda, Rablerine -O gaybi bir hakikat olmasına karşın- derin bir saygı duyanlara gelince: Onları tarifsiz bir bağış ve büyük bir ödül beklemektedir."},{"n":13,"t":"İnancınızı ister gizleyin ister açığa vurun; unutmayın ki O göğüslerin en mahrem sırlarını bilendir."},{"n":14,"t":"Bakın, Yaratan bilmez mi hiç? Zira O ilmiyle her şeye nüfuz eden, her şeyden haberdar olandır."},{"n":15,"t":"Yeryüzünü sizin için emre amade kılan O`dur; artık onun her tarafını dolaşın ve O`nun rızkından nasiplenin: ama O`na döndürüleceğinizi asla (unutmayın)!"},{"n":16,"t":"Gökte olanın, sizi yerin dibine geçirmeyeceğinden emin misiniz? O zaman bir de bakarsınız ki (arz) çalkalanmaya başlamış."},{"n":17,"t":"Veya gökte olanın, sizin üzerinize bir bela kasırgası salmayacağından emin misiniz? Artık uyarım nasıl olurmuş, o zaman anlayacaksınız."},{"n":18,"t":"Doğrusu, onlardan önce de yalanlayanlar olmuştu; ama uyarılarımı reddetmek nasılmış, gördüler."},{"n":19,"t":"Onlar, üzerlerinde saflar halinde kanat çırpıp uçan kuşları düşünmezler mi? Onları O sonsuz rahmet sahibinden başka havada tutan yok: Şüphesiz O, her şeyi görmektedir."},{"n":20,"t":"Ya da O Rahmandan başka, size yardım edip sizin için askerlik yapacak birileri mi varmış? (Bu hakikati) inkar edenler, başka değil, sadece sonu kestirilemeyen bir aldanış içindedirler."},{"n":21,"t":"Yahut (Allah) rızıkınızı keserse, size rızık sağlayacak birileri mi varmış? Ama hayır, onlar küstahça bir kibir ve nefret içinde debelenmekteler."},{"n":22,"t":"Ne yani, şimdi yüzüstü kapaklanmış kimse, hedefe dosdoğru yolda düzgün yürüyen kimseden daha iyi mi ulaşır?"},{"n":23,"t":"De ki: \"O sizi inşa edendir; size işitme duyusu, gözler ve (akleden) kalpler bahşedendir: Ne kadar da azınız şükrediyor!\""},{"n":24,"t":"De ki: \"O sizi yeryüzünde yayıp çoğaltandır: en sonunda O`na döndürüleceksiniz.\""},{"n":25,"t":"Ama onlar: \"Bu vaad ne zaman gerçekleşecek, eğer sözünüze sadıksanız (haber verin de görelim)!\" diye meydan okuyorlar."},{"n":26,"t":"De ki: \"Onun bilgisi sadece Allah katındadır! Ben ise, yalnızca onu olduğu gibi ileten bir uyarıcıyım.\""},{"n":27,"t":"Fakat onun çok yakın olduğunu gördükleri zaman, inkara şartlanmış olanların suratları asılacak; dahası kendilerine denilecek ki: \"İşte (gelmeyeceğini) iddia edip durduğunuz (gün) budur!\""},{"n":28,"t":"De ki: \"Hiç düşündünüz mü? Allah beni ve benimle beraber olanların ölümünü takdir etse, ya da bize rahmet edip (yaşatsa: ikisi de hayırdır). Fakat (söyler misiniz), inkar edenleri acıklı bir azabın pençesinden kim kurtaracak?"},{"n":29,"t":"De ki: \"(İşte kurtaracak olan) O Rahman`dır! Biz O`na iman ettik ve O`na güvendik. (Size gelince): kimin apaçık bir sapıklıkta olduğunu günü gelince öğreneceksiniz."},{"n":30,"t":"De ki: \"Hiç düşündünüz mü? Eğer suyunuz (yeryüzünden) tamamen çekiliverse, size tertemiz kaynak sularını kim getirecek?\""}],[{"n":1,"t":"Nun... Kaleme ve (onun) yazdıklarına yemin olsun!"},{"n":2,"t":"Rabbinin nimeti sayesinde, cin musallat olmuş biri, olman söz konusu değildir."},{"n":3,"t":"Ve senin için kesintisiz bir ödül vardır;"},{"n":4,"t":"çünkü sen, muhteşem bir ahlaka sahipsin;"},{"n":5,"t":"ve bir gün gelecek, sen de göreceksin onlar da görecekler;"},{"n":6,"t":"hanginizin aklından zoru olduğunu."},{"n":7,"t":"Kuşku yok ki senin Rabbin, evet O, kimin kendi yolundan saptığını çok iyi bilir; yine O, kimin hidayete erdiğini de çok iyi bilir."},{"n":8,"t":"Artık hakkı yalanlayanlara boyun eğme!"},{"n":9,"t":"Onlar isterler ki, sen onlara taviz veresin, buna karşılık kendileri de sana..."},{"n":10,"t":"Ve sen, (çiğneyeceğini bile bile) ağız dolusu söz veren hiçbir alçağa da boyun eğme!"},{"n":11,"t":"Arkadan çekiştirmek için mekik dokuyan arabozucuya (da)!"},{"n":12,"t":"İyiliğe ölümüne engel olan günaha gömülmüş zorbaya (da)!"},{"n":13,"t":"Kaba ve duygusuz, üstüne üstlük fırıldak ve hayırsız."},{"n":14,"t":"Bütün bunların nedeni, onun mal ve çocuklara sahip olması idi."},{"n":15,"t":"ki ayetlerimiz kendisine okununca, \"Eskilerin masalları\" diyebildi."},{"n":16,"t":"Onun burnuna (zillet) damgasını çıkmaz bir biçimde vuracağız."},{"n":17,"t":"Şüphesiz şu (yukarıdakileri) sınamıştık, tıpkı malum bahçe sahiplerini sınadığımız gibi: Hani onlar, ertesi sabah kesinlikle hasat yapacaklarına dair sözleşmiştiler."},{"n":18,"t":"Ancak Allah`ın hayata müdahil olduğu gerçeğine dair istisnai bir kayıt da düşmemiştiler."},{"n":19,"t":"Ve onlar uykudayken Rabbinden gelen bir (bela) o (bahçeyi) bir bir yokladı."},{"n":20,"t":"Derken, ertesi sabah o (bahçe) sırım gibi geçmiş küle dönmüştü."},{"n":21,"t":"Derken, sabahın köründe birbirlerine seslendiler."},{"n":22,"t":"\"Hasat yapmak istiyorsanız, erkenden arazinize gidin!\""},{"n":23,"t":"Derken yola koyuldular... Aralarında şöyle fısıldaşıyorlardı:"},{"n":24,"t":"\"Bugün hiçbir yoksulun yanınıza sokulmaması gerekiyor!\""},{"n":25,"t":"Sabah erkenden, güçleri her şeye yetermiş havasıyla yola koyuldular."},{"n":26,"t":"Ama bahçeyi o perişan haliyle görünce: “Herhalde biz yanlış yere gelmişiz, bizim bahçe burası değildir veya biz sapık insanlarız fakir ve yoksulları haklarından mahrum etmeye çalışıyoruz” dediler."},{"n":27,"t":"(Akılları başlarına gelince), \"Hayır, biz mahrum edilmişiz\" dediler."},{"n":28,"t":"İçlerinden en dengeli olanı \"Ben size \"Allah yokmuş gibi hareket etmeyelim\" dememiş miydim?\" diye çıkıştı."},{"n":29,"t":"Onlar \"Varlığın kendisi adına hareket ettiği Rabbimizin şanı ne yücedir\" dediler; \"Meğer biz zalimlerden olup çıkmışız.\""},{"n":30,"t":"Ardından birbirlerine yönelerek, karşılıklı özeleştiri yaptılar."},{"n":31,"t":"\"Yazıklar olsun bize! Gerçekten de biz, haddimizi aşmışız."},{"n":32,"t":"Belki Rabbimiz, onun yerine bize daha iyisini verir: Artık bizim rağbetimiz Rabbimizedir.\""},{"n":33,"t":"İşte (dünyevi) mahrumiyet böyle bir şeydir; ve ahiret mahrumiyeti, hiç kuşkusuz daha beterdir: keşke bilmiş olsalardı."},{"n":34,"t":"Şu bir gerçek ki, takva sahipleri için Rableri katında sonsuz nimetlerle dolu cennetler vardır."},{"n":35,"t":"Ne yani, kayıtsız şartsız Bize teslim olanları suçlularla bir mi tutsaydık?"},{"n":36,"t":"Neyiniz var sizin? Nasıl (bu kadar önyargılı) bir hüküm verebiliyorsunuz?"},{"n":37,"t":"Yoksa bu konuda ders aldığınız size ait bir kitap mı var;"},{"n":38,"t":"yani, siz neyi beğenirseniz o sizindir (diyen bir kitap)?"},{"n":39,"t":"Yoksa elinizde, kiyamete kadar geçerli olup Bizi bağlayan bir yemin var da, onun için mi bu hükme varıyorsunuz?"},{"n":40,"t":"Sor onlara; buna hangisi kefil olacak?"},{"n":41,"t":"Yoksa (Allah katında) onları destekleyen ortaklar mı var? Haydi, eğer doğru sözlülerse o ortakları bulup getirsinler!"},{"n":42,"t":"O ezici gücün kendini gösterip dizde dermanın kalmadığı ve secdeye davet edilecekleri gün, asla ona güçleri yetmeyecektir."},{"n":43,"t":"Bakışları gerçeğin dehşetinden yere düşmüş, kendilerini bir zillet kuşatmıştır; zira onlar, becerebilecekleri bir haldeyken secdeye çağrılmışlardı (da reddetmişlerdi)."},{"n":44,"t":"Artık bana bırak bu sözü yalanlayanları; hiç bilmedikleri bir yerden azar azar bitireceğiz onları."},{"n":45,"t":"Ama onlara imkan ve zaman tanırım; çünkü onların entrikalarını başlarına geçiren düzenim pek sağlamdır."},{"n":46,"t":"Yoksa sen onlardan bir ücret istedin de, onlar altında ezilecekleri ağır bir borç yükünden mi kaçıyorlar?"},{"n":47,"t":"Yoksa idrakı aşan hakikatler onlara ayan oldu da, (gayba dair) kaydı kendileri mi tutuyorlar?"},{"n":48,"t":"Rabbinin hükümüne sabır göster; sakın Balık Sahibi gibi yapma! Hani o kendi kendini kahrederek yalvarıyordu."},{"n":49,"t":"Eğer Rabbinin akıl sır ermez nimeti onun imdadına yetişmemiş olsaydı, andolsun ki aşağılanmış bir halde ıssız bir sahile atılırdı."},{"n":50,"t":"Fakat Rabbi onu (yeniden) seçti ve iyiler arasına kattı."},{"n":51,"t":"İmdi, inkarda ısrar edenler bu ilahi öğüdü duydukları zaman sanki seni gözleriyle devireceklermiş gibi (baksalar) ve \"O, kesinkes cin musallat olmuş biridir\" deseler de (sabret)!"},{"n":52,"t":"Zira bu, bütün bir insanlığa yönelik ilahi bir öğütten ibarettir."}],[{"n":1,"t":"Ah O kesin hakikatin gerçekleşmesi!"},{"n":2,"t":"(Bilir misin ey muhatap) o ne dehşet gerçekleşecek?"},{"n":3,"t":"Sahi onun nasıl gerçekleşeceğini bilir misin sen?"},{"n":4,"t":"Semud ve Ad (İnsanın aklını başına devşiren) o Son Vuruş`u inkar ettiler."},{"n":5,"t":"Bir yanda Semud: sonuçta onlar ses duvarını çok çok aşan bir bela ile helak edildiler."},{"n":6,"t":"Ve öte yanda `Ad: onlar da değdiğini sesiyle çarpan dizginlenemez bir kasırgayla helak edildiler."},{"n":7,"t":"(Allah), üzerlerine emrine amade kıldığı o (kasırgayı) yedi gece sekiz gündüz kesintisiz bir biçimde estirdi; öyle ki, tıpkı kökünden savrulmuş hurma kütükleri gibi, o kavmin orada öylece donup kaldığını gözünde canlandırabilirsin."},{"n":8,"t":"Şimdi onlardan geriye kalan bir (kişi) görebiliyor musun?"},{"n":9,"t":"Bir de Firavun ve ondan önce gelenler ve altüst olmuş şehirler vardı; (hepsi de) hataya gömülmüşlerdi:"},{"n":10,"t":"Nihayet Rablerinin elçisine karşı geldiler; ve (Allah günahlarıyla) katlanan bir bela ile tümünü enseledi."},{"n":11,"t":"Şüphesiz o su çığrından çıkıp tuğyan ettiğinde sizi gemide taşıyan Bizdik;"},{"n":12,"t":"Onu, size bir ibret vesikası kılmak için, dahası işittiğini anlayan her kulak (sahibinin işin özünü) kavraması için (aktardık)."},{"n":13,"t":"İmdi, sur borusuna (ilk kez) tek bir defa üflendiğinde,"},{"n":14,"t":"yeryüzü ve dağlar yerlerinden edilip, ardından da tek bir seferde un ufak edildiğinde:"},{"n":15,"t":"İşte o zaman, olması beklenen o (büyük olay) bitmiş olacak."},{"n":16,"t":"Ve gök parçalanmış olacak, zira o gün tüm direncini yitirmiş olacak."},{"n":17,"t":"Melekler onun enkazı başında duracak; ve onların da üstünde o gün Rabbinin hükümranlık tahtını sekizi taşıyacak."},{"n":18,"t":"O gün (yargılanmak üzere) huzura çıkarılacaksınız; en gizli sırrınız bile gizli kalmayacak."},{"n":19,"t":"Karnesi sağ tarafından verilen kimseye gelince... O (sevinçle) şakıyacak: \"Hey millet! Alın işte, okuyun karnemi!"},{"n":20,"t":"Kesinlikle ben, hesabımla yüzleşeceğime gönülden inanmıştım!\""},{"n":21,"t":"O kendini mesut ve bahtiyar eden bir hayatın içinde bulacak;"},{"n":22,"t":"yüce bir cennette;"},{"n":23,"t":"hemen yakınında (amellerinin) meyveleri."},{"n":24,"t":"(Kendilerine) \"Bu günler için geçmişte peşinen takdim ettiklerinize karşılık yiyin, için, afiyet olsun!\" (denilecek)."},{"n":25,"t":"Karnesi sol tarafından verilen kimseye gelince... Sonunda o da şöyle sızlanacak: \"Eyvah! Keşke hiç karne almasaydım!"},{"n":26,"t":"Ve hesabımın ne olduğunu (keşke) hiç bilmeseydim!"},{"n":27,"t":"Ah! Keşke (ölüm), işi tamamen bitiren (mutlak bir yok oluş) olsaydı!"},{"n":28,"t":"Malım başıma gelen hiçbir belayı def edemedi."},{"n":29,"t":"Gücüm elimde patladı.\""},{"n":30,"t":"(Görevli meleklere emredilecek): \"Alın onu bağlayın!"},{"n":31,"t":"Sonra cehenneme yaslayın!"},{"n":32,"t":"Sonra bir zincire vurun; uzunluğu yetmiş arşın olan bir zincere; ve sıkıca bağlayın!"},{"n":33,"t":"Çünkü o yüce Allah`a inanıp güvenmedi."},{"n":34,"t":"Yoksulu doyurmak için hiçbir çaba harcamadı."},{"n":35,"t":"İşte bu yüzden, burada ne bir can dosta sahip,"},{"n":36,"t":"ne de pis bir atıktan başka yiyeceğe;"},{"n":37,"t":"o, sadece günahkarların yediği bir yiyecek..."},{"n":38,"t":"Ötesi yok! Gördüğünüz her şeye Ben yemin ediyorum;"},{"n":39,"t":"göremediklerinize de."},{"n":40,"t":"Hiç şüpheniz olmasın ki o (mesaj) şerefli bir elçinin sözüdür;"},{"n":41,"t":"ve o bir şair sözü değildir: ne kadar da azınız inanıyor;"},{"n":42,"t":"ve o bir kahin sözü de değildir: ne kadar da azınız düşünüyor:"},{"n":43,"t":"O, Alemlerin Rabbi katından indirilmedir."},{"n":44,"t":"Ve eğer (Peygamber) kısmen dahi, söylemediğimiz sözler uydurarak Bize isnat etseydi,"},{"n":45,"t":"onu sağ kolundan şiddetle yakalar"},{"n":46,"t":"ve şah damarını kesip (başını) koparırdık"},{"n":47,"t":"da, sizden hiç kimse buna engel olamazdı."},{"n":48,"t":"Gerçek şu ki, bu vahiy muttakiler için bir uyarıdır."},{"n":49,"t":"Ama kesinlikle Biz, sizden yalanlayacak olanların çıkacağını da çok iyi biliyoruz."},{"n":50,"t":"Bir o kadar kesin olan da şu ki, bu durum inkarı hayat tarzı edinenler için derin bir pişmanlık kaynağı olacak;"},{"n":51,"t":"zira o (vahiy), elbette mutlak hakikattir."},{"n":52,"t":"Sözün ozü: (Ey muhatap) sen, azamet sahibi Rabbin adına hareket et!"}],[{"n":1,"t":"Herhangi bir soru/istek sahibi (ahirette) vuku bulması kesin olan tarifsiz azabı hemen (burada) sorup isteyebilir;"},{"n":2,"t":"Kâfirler için, onu engelleyecek yoktur."},{"n":3,"t":"Allah`tan gelir; tekamül mertebelerinin sahibi olan (Allah`tan):"},{"n":4,"t":"Bütün melaike, ruh ile birlikte, süresi (dünyaya göre) elli bin yıl olan bir günde O`na yükselir."},{"n":5,"t":"Artık (sen ey muhatap), güzel bir sabırla diren!"},{"n":6,"t":"Çünkü onlar (Hesap Günü`nü) çok uzak bir ihtimal olarak görüyorlar;"},{"n":7,"t":"Biz ise onu çok yakın görüyoruz."},{"n":8,"t":"O gün gökyüzü yanık yağ tortusu gibi kıpkızıl olacak."},{"n":9,"t":"Bütün dağlar hallaç pamuğu gibi atılmış olacak."},{"n":10,"t":"bir dost başka bir dostu sormayacak."},{"n":11,"t":"Onlar birbirlerinin görüş alanında olacakları (halde böyle olacak). O gün günahı tabiat edinmiş kişi, azaptan kurtulmak için fidye vermek isteyecek öz evladını,"},{"n":12,"t":"eşini, kardeşini,"},{"n":13,"t":"kendisine sığınak olmuş bütün yakınlarını;"},{"n":14,"t":"dahası yeryüzünde yaşayan herkesi (fidye vermek isteyecek) ki kendisi kurtulabilsin."},{"n":15,"t":"Fakat ne mümkün! (Onu bekleyen) dediğini çarpan tarifsiz bir alevdir;"},{"n":16,"t":"derisini kavuran bir alev;"},{"n":17,"t":"o, (hakka) sırt dönenleri ve (vahiyden) yüz çevirenleri kendine davet eder;"},{"n":18,"t":"zira o (serveti) toplayıp (paylaşmayarak) biriktiriyordu."},{"n":19,"t":"Kuşku yok ki insan pek tatminsiz yaratılmıştır."},{"n":20,"t":"Şer dokundumu mızıkcı"},{"n":21,"t":"ama bir iyiliğe nail olduğu zaman da onu herkesten kıskanır."},{"n":22,"t":"Namazla dik duranlar müstesna:"},{"n":23,"t":"Onlar ki namazlarında titiz ve devamlıdırlar."},{"n":24,"t":"Onlar ki, malları üzerinde belirli (kimselerin) hakkı olduğunu (bilirler):"},{"n":25,"t":"Hassaten yardım isteyenlerin ve (isteyemediği için) mahrum kalanların..."},{"n":26,"t":"Yine onlar ki Hesap Günü`nü gönülden tasdik ederler;"},{"n":27,"t":"ve onlar ki Rablerinin azabından dolayı derin bir ürperti içerisindedirler:"},{"n":28,"t":"çünkü hiç kimse Rabbinin azabına karşı dokunulmaz değildir."},{"n":29,"t":"Yine onlar ki, iffetlerini korurlar;"},{"n":30,"t":"ancak eşleri, yani meşru şekilde hakkını vererek sahip oldukları kimseler müstesna: zaten onlar (meşru eşleriyle paylaştıkları cinsellikten dolayı) kınanamazlar."},{"n":31,"t":"Ama bu sınırın ötesine geçen kimseler haddi aşmış olanlardır."},{"n":32,"t":"Onlar ki, emanetlerine ve sözlerine riayet ederler."},{"n":33,"t":"Yine onlar ki, şahitlik görevinin hakkını verirler;"},{"n":34,"t":"ve onlar ki, namazlarının (amacını) titizlikle gözetirler."},{"n":35,"t":"İşte cennetlerde sınırsız ikrama nail olacaklar bunlardır."},{"n":36,"t":"İnkarı hayat tarzı edinmiş olan şunlara ne oluyor ki, senden yana boyunlarını uzatarak"},{"n":37,"t":"dağınık gruplar halinde bir sağa bir sola gezinip duruyorlar?"},{"n":38,"t":"Ne yani, şimdi onlardan her biri, tarifsiz nimetler cennetine gireceğini mi sanıyor?"},{"n":39,"t":"Kesinlikle hayır. Şu bir gerçek ki onları iyi bildikleri bir şeyden yaratan Biziz."},{"n":40,"t":"Artık bundan ötesi yok! Gündoğumu ve günbatımı noktalarının tümünün Rabbi olan (Zatıma) yemin ederim ki: elbet Biz kadiriz"},{"n":41,"t":"onları kendiliğinden daha hayırlı bir toplumla değiştirmeye... Zira Biz asla aşılıp (önüne) geçilenlerden biri değiliz."},{"n":42,"t":"Artık onları kendi haline bırak; vaad edildikleri güne kavuşuncaya kadar lafa dalıp oynayadursunlar."},{"n":43,"t":"o gün onlar, sanki putlarına doğru seğirtirmiş gibi hızla mevzilerinden fırlarlar;"},{"n":44,"t":"gözleri yıkılmış, zillete bürünmüş bir halde: işte bu, onların daha önce defalarca tehdit edildikleri gündür."}],[{"n":1,"t":"Biz Nuh`u kendi halkına gönderdik; \"Başlarına elim bir azap gelmezden önce halkını uyar!\" (dedik)."},{"n":2,"t":"(Nuh) \"Ey kavmim!\" dedi, \"Ben size gönderilmiş apaçık bir uyarıcıyım\"."},{"n":3,"t":"(Uyarım şu): \"Yalnız Allah`a kulluk edin ve O`na karşı sorumluluğunuzun bilincinde olun; dahası bana uyun ki,"},{"n":4,"t":"geçmiş günahlarınızı bağışlasın ve adı konulmuş bir vakte kadar size süre tanısın; ama unutmayın ki, Allah`ın belirlediği süre gelip çattığında asla ertelenemez: keşke bunu kavrasaydınız."},{"n":5,"t":"(Nuh) dedi ki: \"Rabbim! Ben kavmimi gece gündüz davet ettim."},{"n":6,"t":"Ne ki benim davetim onları uzaklaştırmaktan başka bir işe yaramadı."},{"n":7,"t":"Senin bağışına layık olmaları için onları davet ettiğim her seferinde parmaklarını kulaklarına tıkadılar, gözlerini (hakikate) kapadılar, (inkarda) direndiler, büyüklendiler de büyüklendiler..."},{"n":8,"t":"Gün oldu ben onları açıktan davet ettim;"},{"n":9,"t":"gün oldu hem (davetimi) kendilerine ilan ettim, bir de gizliden gizliye davet ettim;"},{"n":10,"t":"nihayet dedim ki: \"Rabbinizden bağışlanma dileyin; unutmayın ki O sürekli bağışlayandır:"},{"n":11,"t":"göğü üzerinize cömertçe boşaltacaktır;"},{"n":12,"t":"mal ve evlat vererek dünyevi refahınızı artıracak; dahası sizin için tarifsiz cennetler var edecek ve nehirler bahşedecektir."},{"n":13,"t":"Size ne oluyor da Allah için vakarlı bir tavır takınmıyorsunuz?"},{"n":14,"t":"Oysa ki sizi uzun süreçler içinde halden hale geçiren yaratan O`dur."},{"n":15,"t":"Allah`ın yedi kat göğü nasıl birbiriyle uyumlu tabakalar halinde yarattığını görmüyor musunuz?"},{"n":16,"t":"Yine ayı etkili bir ışık (yansıtıcı) kıldığını, güneşi de (ışık kaynağı) tarifsiz bir lamba yaptığını?"},{"n":17,"t":"Ve Allah sizi yerden tarifsiz bir bitirişle bitirmiştir."},{"n":18,"t":"Ardından sizi oraya geri döndürecek; en sonunda tarifsiz bir çıkarışla yeniden çıkaracaktır."},{"n":19,"t":"Ve Allah sizin için yeri (döşek gibi) yaymıştır"},{"n":20,"t":"ki, geniş yollar bulup onun üzerinden aşabilesiniz diye."},{"n":21,"t":"Nuh \"Rabbim!\" dedi, \"Onlar bana karşı direndiler, malı ve nesli sadece hüsranını artıran kimselere uydular;"},{"n":22,"t":"onlar (propaganda yoluyla) korkunç tuzaklar kurdular;"},{"n":23,"t":"ve \"İlahlarınızı asla bırakmayın; bırakmayın Vedd`i, Suva`ı, Yeğus`u, Ye`uk`u ve Nesr`i!\" dediler."},{"n":24,"t":"Doğrusu böylece onlar bir çoklarını yoldan çıkardılar; Sen de (Allah`ım) bu zalimleri hedeflerinden daha fazla saptır!\""},{"n":25,"t":"Onlar günahlarından dolayı boğuldular; dahası (ahirette) ateşe atılacaklar ve Allah dışında kendilerine yardım edecek kimse de bulamayacaklar."},{"n":26,"t":"Nuh \"Rabbim!\" diye yalvardı, \"Yeryüzünde kafirlerden nümunelik tek kişi dahi bırakma!"},{"n":27,"t":"Çünkü eğer Sen onları bırakırsan, Senin kullarını yoldan çıkarmaya (çalışacaklar); onlardan fesatçılar ve küfre saplananlardan başkası doğmayacaktır."},{"n":28,"t":"Rabbim! Beni, anne babamı, mü`min olarak evime gireni ve mü`min erkeklerle mü`min kadınları bağışla. Zâlimlerin ise helâklerinden başka bir şeylerini artırma."}],[{"n":1,"t":"De ki: \"Bana vahyedildi ki, cinlerden bir kısmı (bu mesaja) kulak vererek, (dostlarına) şöyle dediler: \"Gerçekten de biz olağanüstü güzellikte bir hitap dinledik;"},{"n":2,"t":"doğru bir bilinç inşa eden (bir hitab)... Böylece ona iman ettik: artık asla Rabbimizden başkasına ilahlık yakıştırmayacağız;"},{"n":3,"t":"ve şu bir hakikat ki, Rabbimizin şanı pek yücedir: O kendisine ne bir eş ne de çocuk edinmiştir."},{"n":4,"t":"Bir başka gerçek de, içimizdeki beyinsiz (kişilerin) Allah`a karşı sorumsuzca konuşması olmuştu."},{"n":5,"t":"Halbuki biz, ne insanların ne de cinlerin Allah`a iftira edeceğine asla ihtimal vermezdik.\""},{"n":6,"t":"Hiç kuşku yok ki insanlardan bazıları cinlerden bazılarına sığınırlar, bu da onların (cinler karşısındaki) zillet verici edilgenliğini artırır."},{"n":7,"t":"Öyle ki o sapık insanlar, tıpkı sizin sandığınız gibi Allah`ın hiç kimseyi elçi göndermeyeceğini sanmışlardı."},{"n":8,"t":"(Yine cinler şöyle dediler): \"Gerçek şu ki biz göğü yokladık, ama onu tam donanımlı bir koruma ordusu ve tarifsiz bir göktaşı sağanağıyla dopdolu bulduk;"},{"n":9,"t":"halbuki vaktiyle biz onun uygun yerlerinde (haber) dinlemek için otururduk; ne var ki şimdi (bizden) her kim dinlemeye kalksa, derhal karşısında hedefe kilitli bir ateş topu buluyor."},{"n":10,"t":"Ve anladık ki, gerçekte biz (gaybı) bilmiyormuşuz; (mesela) şu yerdekilere şer mi murad edilmiş, yoksa Rableri onları doğru bir bilince ulaştırmayı mı murad etmiş?"},{"n":11,"t":"Nitekim bizden iyi olanlar var, ama bizden öyle olmayanlar da var: zaten öteden beri biz hep birbirine aykırı yollar izlemişiz."},{"n":12,"t":"Ve nihayet aklımız kesti ki, yeryüzünde asla Allah`a üstün gelemeyiz ve O`ndan asla kaçıp kurtulamayız."},{"n":13,"t":"İşte tam da bu yüzden biz, ilahi rehberliği işitir işitmez ona inandık; artık kim Rabbine inanırsa, o ne bir ziyana uğrar, ne de gazaba."},{"n":14,"t":"Bununla beraber, içimizden Allah`a tam teslim olanlar da var, kendisine kötülük edenler de; ama her kim Allah`a teslim olursa, işte onlar doğru bir bilinç inşa etmenin hakkını verenlerdir."},{"n":15,"t":"Kendisine kötülük edenlere gelince: sonunda onlar cehenneme odun olacaklar.\""},{"n":16,"t":"İmdi, eğer onlar yolda doğru dürüst giderlerse, elbet Biz de onları bitimsiz bir suyla sularız;"},{"n":17,"t":"(bunu, nimet) içinde yüzdürerek sınamak için (yaparız); ama Rabbinin vahyinden yüz çeviren kimseyi de pek zorlu bir mahrumiyete mahkum ederiz."},{"n":18,"t":"Yine (bana vahyedildi ki), kesinlikle ibadethaneler Allah`a mahsustur; öyleyse Allah`ın yanı sıra başka hiç kimseye yalvarıp yakarmayın!"},{"n":19,"t":"Ne var ki Allah`ın kulu O`na davete kalkmaya görsün; hemen yek vücut olup üzerine çullanıverirlerdi."},{"n":20,"t":"Dediği (sadece) şuydu: \"Ben yalnızca Rabbime yalvarıp yakarırım ve O`ndan başka hiç kimseye ilahlık yakıştırmam.\""},{"n":21,"t":"De ki: \"Ne zarar (ve yarar) verebilirim, ne de hidayet (ve dalalete) götürebilirim."},{"n":22,"t":"De ki: \"Şu bir gerçek ki, ne beni Allah`a karşı kimse koruyabilirdi, ne de ben O`nun dışında bir sığınak bulabilirdim;"},{"n":23,"t":"tabi ki eğer, Allah`tan gelen görevi ve O`nun mesajlarını iletmemiş olsaydım... Artık kim Allah`a ve Elçi`sine karşı gelirse, iyi bilsin ki onun payına içinde ebedi kalacağı Cehennem düşecektir."},{"n":24,"t":"Tehdit edildikleri azabı görünceye kadar yolları var; işte o zaman, kimin yardıma daha muhtaç ve sayıca az olduğunu anlayacaklar."},{"n":25,"t":"De ki: \"Keşke bilseydim tehdit edildiğiniz azap yakın mı, yoksa Rabbim onu bir müddet daha erteledi mi?"},{"n":26,"t":"Gaybı (sadece) O bilir ve O gaybına kimseyi bütünüyle asla muttali kılmaz;"},{"n":27,"t":"razı olduğu elçi müstesna... Böylesi bir durumda O (elçisini), gerek bildiği gerekse bilmediği hususlarda ilahi gözetim altına alarak hedefine ulaştırır"},{"n":28,"t":"ki, (peygamberler) bu sayede tebliğ ettiklerinin Rablerinin risaleti olduğunu; dahası (Allah`ın) ellerindeki (vahyi) çepeçevre kuşattığını ve her şeyi tek tek sayarak muhafaza altına aldığını bilsin."}],[{"n":1,"t":"Sen ey ağır yük yüklenen (Nebi)!"},{"n":2,"t":"Kalk gecenin ilerleyen bir vaktinde!"},{"n":3,"t":"Gece yarısı, ondan biraz önce"},{"n":4,"t":"ve de sonra; ve oku Kur`an`ı sindire sindire!"},{"n":5,"t":"Çünkü biz, sana ağır bir söz indireceğiz;"},{"n":6,"t":"elbet (şu) gece dirilişi var ya: işte o pek derin bir iz bırakır ve okuyuş açısından daha bir etkilidir;"},{"n":7,"t":"üstelik gündüzün seni bekleyen bir yığın görev vardır."},{"n":8,"t":"İmdi, Rabbinin adını an ve bütün varlığını O`na vakfet!"},{"n":9,"t":"O doğunun da batının da Rabbidir; O`ndan başka ilah yoktur: Öyleyse kendini yalnızca O`na emanet et!"},{"n":10,"t":"Ve onların söyleyebilecekleri her şeye karşı sabırla diren ve güzellikle uzaklaş onlar(ın çirkin tavırların)dan;"},{"n":11,"t":"ve Bana bırak refah içinde yüzdükleri halde yalanlayanları; onlara az bir süre daha tanı!"},{"n":12,"t":"Çünkü bizim yanımızda ağır kelepçeler ve yakıcı bir ateş vardır!"},{"n":13,"t":"boğaza düğümlenen berbat bir yiyecek ve elemi tarifsiz bir azap var;"},{"n":14,"t":"o gün yerler ve dağlar dehşetli sarsılacak; ve sonunda dağlar kum yığınına dönüşerek eriyip akacak."},{"n":15,"t":"İmdi bakın, tıpkı Firavun`a bir elçi gönderdiğimiz gibi, size de önünüzde hakikate şahitlik eden bir elçi gönderdik;"},{"n":16,"t":"fakat Firavun elçiye karşı geldi; bunun üzerine biz de fena halde enseledik."},{"n":17,"t":"Şu halde eğer inkar ederseniz, yeni doğan bebeleri ak saçlı ihtiyarlara döndüren o gün nasıl korunacaksınız?"},{"n":18,"t":"Gök, bu sebeple çatlamış bir çekirdek (gibi yeni bir doğuma gebedir); böylece O`nun vaadi gerçekleşmiş olacaktır."},{"n":19,"t":"İşte bu, uyarı dolu bir öğüttür: artık dileyen Rabbine ulaştıran bir yol tutsun!"},{"n":20,"t":"(Ey Nebi!) Elbet Rabbin, senin ve yanındakilerden bir kısmının gecenin üçte ikisinden daha azını, ve yarısını, ve üçte birini uyanık geçirdiğini bilmektedir. Gecenin ve gündüzün miktarını belirleyen Allah, sizin onun üstesinden gelemeyeceğinizi de bilmiş ve size rahmetiyle yönelmiştir. Artık Kur’an’dan kolayınıza geldiği kadar okuyun! Allah, ileriki zamanlarda içinizden hastalar, Allah’ın verdiği rızkı aramak için yola koyulanlar, Allah yolunda savaşa çıkan daha başkalarının olacağını bilir. Şu halde ondan, kolayınıza geldiği kadar okuyun, namazınızı kılın, arınıp yücelmek için ödenmesi gereken bedeli ödeyin ve Allah’a güzel bir borç verin; zira kendi adınıza ne hayır işlerseniz, Allah katında onu daha hayırlı ve daha büyük bir ödül olarak bulursunuz. İmdi Allah’tan mağfiret dileyin: İyi bilin ki Allah, tarifsiz bir bağışlayıcı, eşsiz bir merhamet kaynağıdır."}],[{"n":1,"t":"Sen ey içine kapanan kişi!"},{"n":2,"t":"Kalk ve (insanları) uyar!"},{"n":3,"t":"Sadece Rabbini yücelt!"},{"n":4,"t":"Elbiseni temiz tut!"},{"n":5,"t":"Bütün pisliklerden uzak dur!"},{"n":6,"t":"İyilik yapmayı kazanç kapısı haline getirme! ((Allah için) yaptığın iyiliği çok görme!)"},{"n":7,"t":"Rabbin hatırına sabret!"},{"n":8,"t":"Ve (şu haberi ilet): (Sur) borusuna üflendiği zaman;"},{"n":9,"t":"evet işte o gün, pek zor bir gün olacaktır,"},{"n":10,"t":"kafirlerin tümü için hiç de kolay olmayacaktır."},{"n":11,"t":"Beni tek başıma yarattığımla başbaşa bırak!"},{"n":12,"t":"Ki, geniş maddi imkanlar vermiştim ona!"},{"n":13,"t":"Bir de (cömertliğimin) şahitleri olan çocuklar..."},{"n":14,"t":"Ve onu bir (bebek gibi) eleyip belemiştim;"},{"n":15,"t":"şimdi de kalkmış hırsla daha fazlasını istiyor."},{"n":16,"t":"Öyle yağma yok! Madem ki o ayetlerimizi inatla (inkara) saplanmıştır."},{"n":17,"t":"Ben de onu sarp yokuşa süreceğim."},{"n":18,"t":"Çünkü o (vahiy hakkında) sığ ve yanlış düşündü, ölçüp biçti;"},{"n":19,"t":"Canı çıkası, nasıl da ölçüp biçti!"},{"n":20,"t":"Bir daha canı çıkası, nasıl da ölçüp biçti!"},{"n":21,"t":"Sonra (etrafı) süzdü;"},{"n":22,"t":"ardından surat astı ve rengi attı."},{"n":23,"t":"En sonunda (hakikate) sırtını döndü ve kibir abidesi kesildi."},{"n":24,"t":"Nihayet şöyle dedi: \"Bu sadece geçmişten miras kalan bir büyüdür,"},{"n":25,"t":"bu sadece ölümlü bir insan sözüdür."},{"n":26,"t":"Onu Sekar`a yaslayacağım."},{"n":27,"t":"Sekar`ın ne olduğunu nasıl bilebilirsin ki sen?"},{"n":28,"t":"O ne (diri) bırakır, ne de (ölüme) terk eder;"},{"n":29,"t":"o insana kendi özünü gösterir;"},{"n":30,"t":"onun üzerinde on dokuz (melek/e) vardır."},{"n":31,"t":"Zira yalnızca melaikeyi ateşin muhafızları kıldık; ve onların sayısını inkarda ısrar edenler için bir sınav yaptık; ki böylece önceki vahyin mensupları gönülden ikna olsun ve (ona) iman edenlerin imanları artsın; hem önceki vahyin mensupları hem de (bu vahye) iman edenler bütün kuşkulardan arınsın; ve kalplerinde hastalık olanlar ve inkara gömülenler ise, \"Allah bu temsil ile ne yapmayı diledi?\" diye sorsun! İşte böylece Allah (sapmayı) dileyeni saptırır, (hidayeti) dileyeni ise doğru yola yöneltir. Ve Rabbinin ordularını(n sayısını) Zatından başka kimse bilemez. Nihayet bunlar, ölümlü insan için bir uyarı ve öğütten ibarettir."},{"n":32,"t":"Evet, ay şahit olsun!"},{"n":33,"t":"Geçip giden gece şahit olsun!"},{"n":34,"t":"Ve ağaracak olan sabah şahit olsun!"},{"n":35,"t":"Şüphesiz o (cehennem ateşi, musibetlerin) en eşsizidir;"},{"n":36,"t":"insan soyu için bir uyarıdır;"},{"n":37,"t":"içinizden öne geçmeyi veya arkada kalmayı dileyen herkes için..."},{"n":38,"t":"Her insanın (akıbeti) kendi kazandıklarına bağlıdır;"},{"n":39,"t":"ancak iyiler müstesna."},{"n":40,"t":"(Onlar) cennetlerde, hep bir ağızdan soracaklar"},{"n":41,"t":"günahı hayat tarzı edinenlere:"},{"n":42,"t":"\"Sizi, içinizi yansıtan bu ateşe ne soktu?\""},{"n":43,"t":"Cevap verecekler: \"Biz hem Allah`la bağımızı koparmıştık,"},{"n":44,"t":"hem de yoksulları doyurmazdık;"},{"n":45,"t":"üstelik (günaha) dalanlarla birlikte biz de dalardık;"},{"n":46,"t":"hepsinden öte biz Hesap Günü`nü yalanlardık;"},{"n":47,"t":"ta ki ölüm hakikati bizi gelip buluncaya kadar...\""},{"n":48,"t":"İşte bunlara hiçbir şefaatçinin şefaati fayda vermeyecek."},{"n":49,"t":"Şu halde o öğüt ve uyarıdan yüz çevirmekle ellerine ne geçecek?"},{"n":50,"t":"Onlar ürkek yaban eşeklerine benziyorlar;"},{"n":51,"t":"amansız avcıdan (kaçak eşeklere)."},{"n":52,"t":"Evet, onların her biri kendilerine açık seçik sayfalar verilmesini ister."},{"n":53,"t":"Yoo! Aksine onlar ahiret endişesi taşımıyorlar."},{"n":54,"t":"Evet, şüphesiz bu bir öğüttür;"},{"n":55,"t":"Artık dileyen ondan öğüt alır;"},{"n":56,"t":"zaten onlar ancak Allah`ın dilemesi durumunda öğüt alabilirler. O, kendisine karşı sorumluluk duyulmaya ve bağışlamaya en ehil olandır."}],[{"n":1,"t":"Ötesi yok, Kıyamet Günü`ne Ben yemin ediyorum!"},{"n":2,"t":"Yine ötesi yok, kendini kınayan nefse Ben yemin ediyorum!"},{"n":3,"t":"İnsanoğlu kendisini (yeniden diriltip) kemiklerini bir araya getiremeyeceğimizi mi sanıyor?"},{"n":4,"t":"Bilakis onu parmak uçlarına kadar yeniden diriltmeye kadiriz."},{"n":5,"t":"Ne var ki genellikle (inkarcı) insan, önündeki (hakikati) yalanlamaya bayılır;"},{"n":6,"t":"O şöyle sorar: \"Şu kıyamet dediğiniz şey ne zaman kopacak?\""},{"n":7,"t":"Bakın: o zaman gözler şimşek şimşek çakacak;"},{"n":8,"t":"ve ay sönüp gidecek;"},{"n":9,"t":"çünkü güneş ve ay birleştirilecek;"},{"n":10,"t":"insanoğlu o gün şöyle diyecek: \"Nereye kaçmalı?\""},{"n":11,"t":"Yoo! Hiçbir sığınak yok!"},{"n":12,"t":"O gün, yolların sonu Rabbinin katına çıkacak;"},{"n":13,"t":"o gün insanoğluna önceledikleri ve erteledikleri bir bir haber verilecek;"},{"n":14,"t":"bilakis insan kendi benliğine şahit olacak;"},{"n":15,"t":"türlü mazaretler ortaya koymuş olsa bile..."},{"n":16,"t":"O sebeple aceleyle dilini oynatıp durma:"},{"n":17,"t":"Şüphesiz onun toplanması da okunuşu da bize düşer;"},{"n":18,"t":"artık Biz onu okuduğumuzda sen sadece onun okunuşunu izle;"},{"n":19,"t":"Sonra onu açıklamak da bizim üzerimizedir."},{"n":20,"t":"Yoo! Bilakis siz hemen şimdi ve burada olanı seviyor"},{"n":21,"t":"ve öteki dünyayı göz ardı ediyorsunuz."},{"n":22,"t":"O gün bazı yüzler mutluluktan ışıl ışıl olacak;"},{"n":23,"t":"Rablerine tarifsiz bir biçimde nazar edecek."},{"n":24,"t":"O gün bazı yüzler umutsuzca donup kalacak;"},{"n":25,"t":"başlarına dehşet bir felaketin geldiğine iyice akılları kesecek."},{"n":26,"t":"Evet, can boğaza gelip dayandığı zaman"},{"n":27,"t":"bir çığlık koparılacak: \"Kim... Şifacı?\""},{"n":28,"t":"Artık ayrılık vaktinin gelip çattığına aklı iyice yatmıştır;"},{"n":29,"t":"ayaklar birbirine dolaşmıştır:"},{"n":30,"t":"o gün sürüklenip götürülüş Rabbine doğrudur."},{"n":31,"t":"Fakat o (insan) hakikati tasdik etmedi ve yönünü Allah`a dönmedi;"},{"n":32,"t":"fakat yalanladı ve sırt döndü;"},{"n":33,"t":"sonra çalım satarak aşiretine sığındı:"},{"n":34,"t":"İşte yaklaşmakta olan, hem de çok yakınında!"},{"n":35,"t":"Tekrar (duy ey insan), yaklaşmakta olan hemen yanıbaşında!"},{"n":36,"t":"Ne yani, insanoğlu başıboş bırakılacağını mı sanıyor?"},{"n":37,"t":"O, bir zamanlar akıtılan bir damlacık sıvı değil miydi?"},{"n":38,"t":"Sonra bir parçacık pıhtı olmuş; bu safhada (Allah) onu yarattığı (gibi) şekil de vermişti;"},{"n":39,"t":"nihayet ondan erkek ve dişi cinsler var etmişti."},{"n":40,"t":"Şu halde aynı (Allah) ölüye hayat vermeye kadir değil midir?"}],[{"n":1,"t":"İnsanın üzerinden, o tarih sahnesine çıkıncaya (kadar), tüm zamanlar içinden belirsiz ve uzun bir süre geçmemiş miydi (ki), henüz o (bu süre zarfında) anılmaya değer bir varlık bile değildi?"},{"n":2,"t":"İnsanoğlunu katmerli bir karışım olan hayat tohumundan Biz yarattık; sınava tabi tutmayı (diledik) ve ardından ona işitme ve görme yeteneği verdik."},{"n":3,"t":"Elbet onu (amacına ulaştıracak olan) doğru yola Biz yönelttik: ister şükreder, ister nankörlük eder."},{"n":4,"t":"En sonunda (inkarı tercih eden) kafirler için tarifi imkansız zincirler, tasmalar ve kışkırtılmış çılgın bir ateşi Biz hazırladık."},{"n":5,"t":"Elbet iyiler de hoş kokulu çiçek özü katkılı tarifsiz bir kadehden içecekler:"},{"n":6,"t":"(bunların doldurulduğu) öyle bir göze var ki, Allah`ın has kulları gürül gürül çıkartacakları bu kaynaktan içecekler."},{"n":7,"t":"(O has kullar ki;) üzerlerine vacip kıldıkları hayrı yerine getirirler ve şerri kahredici bir virüs gibi yayılan günün kaygısını taşırlar;"},{"n":8,"t":"ve kendi istek ve arzularına rağmen muhtaçlara, yetimlere ve esirlere yedirirler;"},{"n":9,"t":"(kendi kendilerine derler ki): \"Biz size sadece Allah için yediriyoruz; sizden ne bir karşılık ne de bir teşekkür bekliyoruz."},{"n":10,"t":"Elbet biz yüzleri asıp kaşları çatan bir günde Rabbimizin (rızasını) kaybetmekten korkuyoruz."},{"n":11,"t":"Bu yüzden Allah onları bu günün dehşetinden koruyacak ve onların (yüzlerine) nur, (yüreklerine) sürur koyacak;"},{"n":12,"t":"ve sabırlarına karşılık onlara cennet bahçeleri ve tarifi imkansız özgür bir (hayat) bahşedecek."},{"n":13,"t":"Orada divanlara sere serpe uzanacaklar; ne sıcağa ne soğuğa maruz kalacaklar;"},{"n":14,"t":"zira cennetin (kutlu) gölgesi üzerlerine düşecek, oranın salkımları emre amade kılınacak."},{"n":15,"t":"Etraflarında gümüş kadehler ve billûr kupalar dolaştırılır."},{"n":16,"t":"öyle gümüşi billurlar ki, onların hacmini tamamen kendileri takdir edecek."},{"n":17,"t":"Orada zencefil türü bir şeyle tatlandırılmış dolu kadehlerle suvarılacaklar."},{"n":18,"t":"(Ebedi saadetin) kaynağı olan oraya yüceltilen bir yol ara!"},{"n":19,"t":"Kendilerine kalıcı gençlik iksiri servisi yapılacak. Sen o (cennetlik)leri göreceğin zaman, sanki saçılmış tarifsiz inciler sanacaksın;"},{"n":20,"t":"Nereden bakacak olsan, sınırsız bir nimet deryası ve görkemli bir iktidar göreceksin."},{"n":21,"t":"Onların üzerinde yemyeşil, capcanlı ipek elbiseler, atlastan kaftanlar bulunacak; ve onlar tarifsiz gümüşten künyeler-bilezikler takınacak; dahası Rableri onlara temiz ve temizleyici olan tarifsiz bir içecek ikram edecek."},{"n":22,"t":"(Kendilerine): \"Bunlar size ödül olarak verilmiştir; ve (bu uğurdaki) üstün gayretiniz (Allah) tarafından kabul edilmiştir\" (denilecek)."},{"n":23,"t":"Elbet biz, evet Biziz Kur`an`ı sana tedrici bir süreç içinde indirmekte olan;"},{"n":24,"t":"artık Rabbinin hükmünü sabırla bekle ve onlardan hiçbir günahkar veya nanköre uyma!"},{"n":25,"t":"Rabbinin ismini sabah(tan) akşam(a dek) yad et!"},{"n":26,"t":"Ve gecenin bir vaktinde O`na secde et ve uzun geceler boyu O`nun şanını yücelt!"},{"n":27,"t":"Ne var ki şu (nankör) adamlar hemen şimdi ve burada olanı seviyorlar da, zor bir günü (gündemlerine almayı) erteliyorlar."},{"n":28,"t":"Onları Biz yarattık ve bütünün parçaları arasında sımsıkı bir bağ kurduk; ve eğer Biz istersek onları benzerleriyle kökten değiştiririz."},{"n":29,"t":"Bütün bunlar bir öğüt ve uyarıdır: Şu halde dileyen Rabbine varan bir yol tutsun!"},{"n":30,"t":"Bu sayede siz, zaten Allah`ın dilediğini dilemiş (olursunuz): elbette Allah her şeyi bilendir, hep hikmetle hükmedendir."},{"n":31,"t":"O, isteyen kimseyi rahmetine sokmayı diler; ne ki zalimler için de elim bir azap hazırlamıştır."}],[{"n":1,"t":"Şahit olsun birbiri ardınca gönderilen (bu vahiyler)!"},{"n":2,"t":"Ardından bir fırtına gibi ortalığı kasıp kavuranlar!"},{"n":3,"t":"Ve (ilahi mesajı) yaydıkça yayanlar!"},{"n":4,"t":"Peşinden (hak ile batılı) seçip ayıranlar!"},{"n":5,"t":"derken (insanı) tarifsiz (güzellikte) bir öğütle buluşturanlar;"},{"n":6,"t":"(o öğütle) imana yöneleni mazur addeden ve (tevbe için) uyarıda bulunanlar..."},{"n":7,"t":"Elbette, tehdit edildiğiniz şey mutlaka gerçekleşecektir:"},{"n":8,"t":"Yıldızlar söndürüldüğü zaman;"},{"n":9,"t":"ve gök yarıldığı zaman;"},{"n":10,"t":"ve dağlar un ufak edildiği zaman;"},{"n":11,"t":"ve bütün elçiler (tanıklık) vaktinde toplandığı zaman..."},{"n":12,"t":"Peki, bütün bunlar hangi gün gerçekleştirilecek?"},{"n":13,"t":"(İyi ile kötü arasındaki) Ayrım Günü."},{"n":14,"t":"Sahi, bu Ayrım Günü`nün dehşetini sen nereden bileceksin?"},{"n":15,"t":"O gün vay haline (bu) hakikati yalanlayanların!"},{"n":16,"t":"Ne yani, Biz (o yalanlayanların) öncülerini helak etmedik mi?"},{"n":17,"t":"Sonrakileri de onların peşine diziveririz:"},{"n":18,"t":"İşte günahı hayat tarzı haline getirenlere böyle davranırız."},{"n":19,"t":"O gün vay haline bu hakikati yalanlayanların!"},{"n":20,"t":"Sizin yaratılış sürecinizi basit ve zayıf bir sıvıdan başlatmadık mı?"},{"n":21,"t":"Ki Biz o sıvıyı (rahim gibi) sağlam bir karar mahallinde korumaya aldık;"},{"n":22,"t":"tabi ki önceden belirlenmiş bir süreye kadar..."},{"n":23,"t":"Bütün bunları Biz takdir ettik; ve ne muhteşemdir Bizim takdirimiz!"},{"n":24,"t":"O gün vay haline (bu) hakikati yalanlayanların!"},{"n":25,"t":"Değil mi ki yeryüzünü bir arada yaşama alanı yaptık;"},{"n":26,"t":"(manen) diri (mü`min)ler ve ölü (kafir)ler için."},{"n":27,"t":"Ve başı yüce heybetli dağlar var ettik; ve size billur gibi suları sebil ettik."},{"n":28,"t":"O gün vay haline hakikati yalanlayanların!"},{"n":29,"t":"Haydi artık, yalanlayıp durduğunuz (Hesap Günü`ne) doğru ilerleyin bakalım!"},{"n":30,"t":"(İnsanın duygu, düşünce ve eylemini kuşatan) üç boyutlu gölgeye doğru ilerleyin!"},{"n":31,"t":"Serinletmeyen ve ateşin alevinden korumayan (acayip bir gölgeye);"},{"n":32,"t":"O (alevin ateşi) dev yapılar gibi kıvılcımlar saçar;"},{"n":33,"t":"sanki akkordan halatlar gibi..."},{"n":34,"t":"O gün vay haline (bu) hakikati yalanlayanların!"},{"n":35,"t":"Bu, ağızlarını açamayacakları bir gündür;"},{"n":36,"t":"(o gün) onlara özür dilemeleri için dahi verilmez izin."},{"n":37,"t":"O gün vay haline (bu) hakikati yalanlayanların!"},{"n":38,"t":"İşte bu, Ayrım Günü`dür. (Onlara denilecek ki): \"Sizi ve öncekileri bir araya topladık:"},{"n":39,"t":"Haydi, eğer elinizde bir kurtuluş planı varsa hemen onu uygulayın!\""},{"n":40,"t":"O gün vay haline (bu) hakikati yalanlayanların!"},{"n":41,"t":"Şüphe yok ki muttakiler (huzur veren) gölgeler altında ve (ebedi saadetin) kaynağında bulunacaklar;"},{"n":42,"t":"ve canlarının istediği her şey, onları neşe ve zevke gark edecek;"},{"n":43,"t":"(onlara) \"Yaptıklarınıza karşılık olarak yiyin, için, afiyet olsun!\" (deriz)."},{"n":44,"t":"Elbet Biz iyileri işte böyle ödüllendiririz!\""},{"n":45,"t":"Ne ki o gün vay haline (bu) hakikati yalanlayanların!"},{"n":46,"t":"Siz de (dünyada) yiyip için ve geçici hazların sefasını sürün (ey yalanlayanlar)! Çünkü siz, günahı hayat tarzı haline getirdiniz."},{"n":47,"t":"O gün vay haline (bu) hakikati yalanlayanların!"},{"n":48,"t":"Zira onlara Allah’ın huzurunda saygıyla eğilin denildiğinde eğilmezler."},{"n":49,"t":"O gün vay haline hakikati yalanlayanların!"},{"n":50,"t":"Haydi (buna inanmadılar), iyi de, bundan böyle hangi habere inanacaklar!"}],[{"n":1,"t":"Kendi aralarında neyi soruşturuyorlar?"},{"n":2,"t":"O muazzam (olayın) müthiş haberini mi?"},{"n":3,"t":"Ki onlar o (haber) hakkında farklı düşünüyorlar."},{"n":4,"t":"Evet: Bir gün (gerçeği) öğrenecekler;"},{"n":5,"t":"evet, evet: Bir gün (gerçeği nasılsa) öğrenecekler."},{"n":6,"t":"Yeryürüzünü (sizin için) tarifsiz bir beşik kılmadık mı?"},{"n":7,"t":"Ve dağları da (o beşiğin) ayakları?"},{"n":8,"t":"Sizi de çift çift yarattık."},{"n":9,"t":"ve uykunuzu ölüm (sembolü) kıldık;"},{"n":10,"t":"ve geceyi tarifsiz bir örtü kıldık;"},{"n":11,"t":"gündüzü de hayat (sembolü) yaptık."},{"n":12,"t":"Ve üzerinize yedi kat (göğü) sapasağlam bina ettik."},{"n":13,"t":"Ve (oraya) son derece güçlü bir ışık ve ısı kaynağı yerleştirdik."},{"n":14,"t":"Ve sıkılmaya hazır yağmur yüklü (bulutlardan) şarıl şarıl sular indirdik;"},{"n":15,"t":"ki onunla tohumlar ve bitkiler bitirelim;"},{"n":16,"t":"dahası, salkım saçak bahçeler (yetiştirelim diye)."},{"n":17,"t":"Şüphesiz Ayrışma Günü`nün belirlenmiş bir vakti mutlaka vardır:"},{"n":18,"t":"o gün sura üflenir, derhal amacına göre taksim edilmiş topluluklar halinde (hayat alanına) çıkarsınız;"},{"n":19,"t":"ve kapıları varmış gibi gökler açılıverir;"},{"n":20,"t":"ve dağlar yürütülür, sanki bir serap olur."},{"n":21,"t":"Şüphesiz (o gün) Cehennemin gözleri yolda kalacaktır;"},{"n":22,"t":"(o) haddini bilmezler için bir son duraktır;"},{"n":23,"t":"onlar orada uzun zamanlar boyu kalacaklar."},{"n":24,"t":"Orada ne (yürek) serinletici bir (haber) tadacaklar, ne de (iç yangını söndürecek) bir içecek."},{"n":25,"t":"Ancak kavurucu bir umutsuzluk ve zift gibi sıvanan buz gibi bir karanlık."},{"n":26,"t":"(İnkarlarına) uygun bir karşılık..."},{"n":27,"t":"Şu kesin ki onlar vaktiyle, hesaba çekilmeyi arzu etmiyorlardı;"},{"n":28,"t":"üstelik ayetlerimizi de açık bir dille yalanlamışlardı;"},{"n":29,"t":"Biz her şeyi hesap edip, bir sicile, bilgi işlem merkezine, Levh-i Mahfuz’a kaydettik."},{"n":30,"t":"Sonunda (onlara diyeceğiz ki): \"(Büyüttüğünüz Cehennem ağacının meyvelerini) tadın; artık size tarifsiz bir mahrumiyetten başka bir şey artırmayacağız."},{"n":31,"t":"Ne var ki, Allah bilinciyle hareket edenleri tarifsiz bir mutluluk yurdu bekliyor;"},{"n":32,"t":"içinden su çıkan göz bebeği bahçeler, bağlar..."},{"n":33,"t":"Dahası, dengi dengine gözalıcı eşler..."},{"n":34,"t":"Ve dolup taşan kadehler..."},{"n":35,"t":"Orada kimse ne boş bir laf, ne de yalan bir söz duyacak."},{"n":36,"t":"(bütün bunlar) Rabbinden, tarif(e)siz bir hesaba göre bahşedilen sınırsız bir ödül olacak:"},{"n":37,"t":"göklerin, yerin ve ikisi arasındakilerin Rabbi`nden; Rahman`dan... Ve hiç kimse O`na (karşı) söz söyleme cesaretini kendinde bulamayacak;"},{"n":38,"t":"o gün (insanlığa ait) bütün ruhlar ve melekler saf saf kıyama duracak; kimse ağzını açamayacak; ancak Rahman`ın izin verdikleri müstesna; onlar da sadece doğruyu söyleyecek."},{"n":39,"t":"İşte bu, hakkın tecelli ettiği gündür: artık dileyen Rabbine varan bir yol tutsun!"},{"n":40,"t":"Kuşku yok ki Biz sizi, çok yakın bir azaba karşı uyarıyoruz: o gün kişi elleriyle takdim ettiği şeylere bakacak; ve (yeniden dirilişi) inkar eden kişi şöyle diyecek: \"Ah n`olaydım, keşke bir toprak olaydım!\""}],[{"n":1,"t":"Şahit olsun (muhatabın yüreğine) dalıp (küfrü oradan) şiddetle söküp atan (uyarı ayetleri)!"},{"n":2,"t":"Ve (mü`min gönüllere) müjde dolu bir umudu usulca getirip bırakan (rahmet ayetleri)!"},{"n":3,"t":"Ve (o umutla hayat denizine) açılıp yüzdükçe yüzen (mü`min)ler!"},{"n":4,"t":"Ve (hayır yolunda) birbirleriyle yarışan öncüler!"},{"n":5,"t":"Derken, onların peşinden işlerini yoluna koyan artçılar!"},{"n":6,"t":"(Bunların her biri şahit olsun ki) o gün şiddetli bir sarsıcı herşeyi saracak;"},{"n":7,"t":"daha büyük sarsıntılar birbirini kovalayacak;"},{"n":8,"t":"(ve) kalpler çırpılmış (gibi) titreyecek;"},{"n":9,"t":"onların gözleri yıkılmışlığı, bitmişliği temsil edecek."},{"n":10,"t":"(Hala) diyorlar ki: \"Ne yani, şimdi biz yeniden eski halimize mi döneceğiz?"},{"n":11,"t":"Tamamen çürüyüp bir külçe kemik haline gelsek de mi?\""},{"n":12,"t":"(Ve) ekliyorlar: \"O zaman desene bu ikinci bir hüsran olacak!\""},{"n":13,"t":"Sözün özü: o (kalk emri), sert ve kesin bir komuttan ibarettir."},{"n":14,"t":"İşte o zaman onlar, faltaşı gibi açılmış gözlerle mahşer meydanında beliriverecek."},{"n":15,"t":"Musa`nın olayından haberin var mı?"},{"n":16,"t":"Hani Rabbi, iki kat kutsal kılınmış bir vadide ona şöyle seslenmişti:"},{"n":17,"t":"\"Firavuna git, çünkü o haddini aştı;"},{"n":18,"t":"ve ona de ki: \"Arınmaya var mısın?"},{"n":19,"t":"İmdi (cevabın evetse), ben seni Rabbine doğru yönelteceğim ve sen de kendine çekidüzen vereceksin!\""},{"n":20,"t":"Nihayet ona o büyük mucizevi belgeyi gösterdi;"},{"n":21,"t":"fakat o yalanladı ve sert çıktı;"},{"n":22,"t":"sonra hışımla orayı terk etti;"},{"n":23,"t":"derken (adamlarını) topladı ve bağırıp çağırdı;"},{"n":24,"t":"üstelik (bir de) \"Ben sizin en büyük rabbinizim!\" dedi."},{"n":25,"t":"Sonunda Allah, onu ahiret ve dünya azabıyla (aleme) ibret olsun diye yakaladı."},{"n":26,"t":"Şüphesiz bunda Allah`a karşı içten bir saygı duyanlar için sayısız ibret vardır."},{"n":27,"t":"Yaratılış açısından siz mi daha sağlamsınız, yoksa gök kubbe mi? Göğü O inşa etti;"},{"n":28,"t":"onu (içinde gök cisimleri) yüzecek şekilde O yükseltti ve dengeli bir iç düzene kavuşturdu;"},{"n":29,"t":"onun gecesini adım adım O kararttı, aydınlığını kıvamında O çıkardı."},{"n":30,"t":"Ve onun ardından yeryüzünü yuvarlatarak bir düzene koydu;"},{"n":31,"t":"orada suyunu ve bitki örtüsünü O çıkarttı;"},{"n":32,"t":"ve dağları sağlamca O yerleştirdi;"},{"n":33,"t":"siz ve hayvanlarınız için geçim aracı olsun diye."},{"n":34,"t":"O muazzam olay gerçekleştiği zaman;"},{"n":35,"t":"(evet) işte o gün, insan neyin peşinden koştuğunu hatırlayacak;"},{"n":36,"t":"zira gözleri faltaşı gibi açacak olan ateş, görme yeteneğine sahip herkesin gözüne sokulacak."},{"n":37,"t":"Ne var ki, işin sonunda haddini bilmeyen"},{"n":38,"t":"ve dünya hayatını tercih edenler var ya:"},{"n":39,"t":"işte onların varacağı yer gözleri faltaşı gibi açacak olan ateştir."},{"n":40,"t":"Ama Rabbinin yüce makamından korkan ve kendini nefsine (kulluktan) alıkoyan kimseler var ya:"},{"n":41,"t":"işte onların varacağı yer de Cennet`dir."},{"n":42,"t":"(Ey Peygamber!) Sana \"Kıyamet ne zaman kopacak?\" diye soruyorlar."},{"n":43,"t":"Sen nerde onun vaktini bilmek nerde!"},{"n":44,"t":"Onun nihai ilmi Rabbine malum."},{"n":45,"t":"Sen sadece onun azametinden korkanlara hatırlatıcısın."},{"n":46,"t":"(Kafirler) bu hakikati bizzat gördükleri gün, onlara sanki (bu dünyada) bir akşam veya bir kuşluktan fazla kalmamışlar gibi gelecek."}],[{"n":1,"t":"O (kibirli adam) surat astı ve sırtını dönüp uzaklaştı,"},{"n":2,"t":"yanına âmâ geldi diye..."},{"n":3,"t":"\"Ve (sana gelince ey Nebi!) Sen nereden bileceksin o (müşrikin) arınacağına dair bir ihtimal bulunduğuna;"},{"n":4,"t":"veya alacağı öğütün kendisine yarar sağlayacağını?"},{"n":5,"t":"Fakat, kendi kendine yettiğini sanan kimseye gelince:"},{"n":6,"t":"Sen bütün ilgini ona yönelttin;"},{"n":7,"t":"oysa ki, onun arınmamasının sorumlusu sen değilsin;"},{"n":8,"t":"fakat sana büyük iştiyakla gelen var ya:"},{"n":9,"t":"-ki o Allah`a saygıda kusur etmez-"},{"n":10,"t":"işte sen onu ihmal ediyorsun."},{"n":11,"t":"Elbet bu hitap bir öğüt ve uyarıdan ibarettir."},{"n":12,"t":"gönüllü olan herkes ondan öğüt alabilir,"},{"n":13,"t":"kutsal ve seçkin kayıtlar altında korunmuştur;"},{"n":14,"t":"yüce ve şaibesiz"},{"n":15,"t":"elçilerin elleriyle (taşınan);"},{"n":16,"t":"türünün en iyisi ve hata yapmayan (elçilerin)."},{"n":17,"t":"Hakkını vermediği hayattan mahrum kalası insanoğlu, nankörlükte ne kadar da sınır tanımazdır?"},{"n":18,"t":"O, insanı neden yarattı?"},{"n":19,"t":"(Elbette) basit bir hayat tohumundan. Önce yarattı, ardında ona takdir yeteneği bahşetti;"},{"n":20,"t":"sonra ona yolu kolaylaştırdı;"},{"n":21,"t":"en sonunda onun için ölümü takdir etti ve kabre koydurdu;"},{"n":22,"t":"nihayet dilediğinde onu tekrar diriltecektir."},{"n":23,"t":"Evet, (hiçbir insan) O`nun emirlerini asla kusursuz olarak yerine getirememiştir."},{"n":24,"t":"İnsanoğlu yediklerine bir baksın:"},{"n":25,"t":"Elbet suyu tarifsiz bir cömertlikle Biz indirmekteyiz;"},{"n":26,"t":"sonra toprağı tarifsiz bir incelikle yarmaktayız;"},{"n":27,"t":"derken orada tohumu yetiştirmekteyiz..."},{"n":28,"t":"Mesela üzüm bağları, sebze bahçeleri,"},{"n":29,"t":"zeytinlik ve hurmalıklar,"},{"n":30,"t":"Balta girmemiş sulak ormanlar"},{"n":31,"t":"meyveli ve meyvesiz bitkiler;"},{"n":32,"t":"sizin ve hayvanlarınızın (beslenmesi) için..."},{"n":33,"t":"Ve nihayet kulakları sağır eden o (mahşer) çığlığı koptuğunda;"},{"n":34,"t":"o gün kişi kardeşinden kaçacak;"},{"n":35,"t":"annesinden ve babasından;"},{"n":36,"t":"hanımından ve çocuklarından..."},{"n":37,"t":"o gün herkesin birbirinden kaçmak için yeterli meşguliyeti olacak."},{"n":38,"t":"Bazı yüzler vardır: o gün ışıl ışıl, ağardıkça ağaracak;"},{"n":39,"t":"şen-şakrak..."},{"n":40,"t":"Bazı yüzler de vardır: o gün bütünüyle toz-toprak;"},{"n":41,"t":"karardıkça kararacak..."},{"n":42,"t":"İşte bunlar, inkarın dibini boylayan ve yoldan sapan sorumsuz kimseler olacak."}],[{"n":1,"t":"Güneş(in defteri) dürüldüğünde,"},{"n":2,"t":"yıldızlar sönüp döküldüğünde"},{"n":3,"t":"dağlar yürütüldüğünde,"},{"n":4,"t":"doğumu yakın develer terk edildiğinde,"},{"n":5,"t":"bütün yabani hayvanlar birbirine sokulduğunda,"},{"n":6,"t":"denizler fokur fokur kaynatıldığında,"},{"n":7,"t":"bütün insanlar tasnif edildiğinde,"},{"n":8,"t":"diri diri gömülen kız çocukları sorduğunda"},{"n":9,"t":"hangi suçtan dolayı öldürüldüklerinin hesabını,"},{"n":10,"t":"(İnsanların) amel defterleri açıldığında,"},{"n":11,"t":"gök, (bir gövdenin derisi gibi) soyulduğunda,"},{"n":12,"t":"Cehennem kışkırtıldığında,"},{"n":13,"t":"ve Cennet(in görüntüsü) yakın plan sunulduğunda;"},{"n":14,"t":"(işte o zaman) her can ne hazırladığını (yakinen) bilir."},{"n":15,"t":"Bundan ötesi yok! İşte ben yemin ederim gizlenenlere,"},{"n":16,"t":"yuvalarına giren yıldız ve gezegenlere,"},{"n":17,"t":"ve (yokluğun) zifiri karanlığına (zaman ve mekan) geri döndüğünde,"},{"n":18,"t":"Nefes almaya başladığı zaman sabaha,"},{"n":19,"t":"Ki elbet bu (Kur`an), türünün en seçkini olan bir elçi (meleğin) ilettiği sözdür;"},{"n":20,"t":"Arş`ın sahibi katından ona hem güç hem de makam bahşedilmiştir."},{"n":21,"t":"orada kendisine itaat edilir; üstelik güvene layıktır."},{"n":22,"t":"Arkadaşınız da cin musallat olmuş biri değildir."},{"n":23,"t":"Doğrusu o, meleği berrak bir ufukta görmüştür."},{"n":24,"t":"kaldı ki o, görünmeyenin bilgisi üzerinde tekel kurup (onu saklayan) biri de değildir;"},{"n":25,"t":"dahası bu kelam, Allah`ın kendisine sığınanları şerrinden emin kıldığı Şeytanın sözü de değildir."},{"n":26,"t":"Hakikat buyken (ey insanlar), nereye gidiyorsunuz?"},{"n":27,"t":"Bu vahiy, tüm insanlık için bir uyarı ve öğütten ibarettir;"},{"n":28,"t":"sonuçta, içinizden doğru yolda yürümeyi dileyenler (öğüt alır)."},{"n":29,"t":"Zaten alemlerin Rabbi Allah (size irade vermeyi) dilememiş olsaydı, siz hiçbir şey dileyemezdiniz."}],[{"n":1,"t":"Uzay çatlayan bir çekirdekten çıkan filiz gibi yeniden yaratılmaya başladığında,"},{"n":2,"t":"yıldızlar yeniden serpilip saçıldığında,"},{"n":3,"t":"denizler yeniden yükselip kabardığında,"},{"n":4,"t":"kabirlerin içi boşaltıldığında,"},{"n":5,"t":"her insan neyi öncelediğini ve neyi ertelediğini fark edecek."},{"n":6,"t":"Ey insanoğlu! Bu kadar ulu ve cömert olan Rabbine karşı bu gururun ne?"},{"n":7,"t":"O (Allah) ki seni (bir amaçla) yarattı, sana varoluş amacını gerçekleştirecek bir donanım ve dengeli bir tabiat verdi;"},{"n":8,"t":"(yani) hangi surette dilemişse seni öyle terkip etti."},{"n":9,"t":"Yapmayın ama; Hesap (Günü`nü) yalanlama (eğilimini) hep içinizde taşıyorsunuz;"},{"n":10,"t":"üstelik üzerinizde gözetleyip hafızaya kaydediciler olduğu halde;"},{"n":11,"t":"(onlar) kaliteli kaydediciler,"},{"n":12,"t":"ne yaparsanız onu fark edip (kaydeden)..."},{"n":13,"t":"Sorumlu davranan iyiler elbette tarifsiz nimetler içinde yüzecekler,"},{"n":14,"t":"sorumsuz davranan kötüler ise gözleri faltaşı gibi açacak bir ateşin içinde olacaklar,"},{"n":15,"t":"Hesap Günü(nün ardından) oraya dikilecekler;"},{"n":16,"t":"ondan kurtulmaları asla mümkün olmayacak."},{"n":17,"t":"Sahi sen Hesap Günü nedir, bilir misin?"},{"n":18,"t":"Evet sen, sahiden de Hesap Günü nedir bilir misin?"},{"n":19,"t":"O, hiçbir insanın bir başka insana asla fayda sağlamayacağı bir gündüz; zira o gün talimat vermek tamamen Allah`a mahsustur."}],[{"n":1,"t":"Yazıklar olsun yolsuzluk yapanlara!"},{"n":2,"t":"Kendileri başkalarından alacakları zaman noksansız isterler;"},{"n":3,"t":"ama başkaları için ölçüp tarttıkları zaman hak yerler."},{"n":4,"t":"Onlar sanmazlar mı ki tekrar diriltilecekler;"},{"n":5,"t":"dehşetli bir günde (hesaba çekilecekler);"},{"n":6,"t":"o gün bütün insanlar alemlerin Rabbi huzuruna dikilecekler."},{"n":7,"t":"Artık yeter! Sorumsuzluğu tıynet edinenlerin kaydı, elbet Siccin`de (arşivlenecek)."},{"n":8,"t":"Ama Siccin nedir, bilir misin sen?"},{"n":9,"t":"O (Siccin) sayısal değerlerle korunmuş bir kayıttır."},{"n":10,"t":"O gün vay haline yalanlayanların;"},{"n":11,"t":"onlar Hesap Günü`nü yalanlıyorlar;"},{"n":12,"t":"halbuki onu ancak haddi aşan günahkarlar yalanlar:"},{"n":13,"t":"ne zaman (Hesap Günü`nü hatırlatan) ayetlerimiz kendilerine okunsa, \"geçmişin masalları\" derler."},{"n":14,"t":"Ondan daha da beter: yaptıkları yüzünden kalpleri tümüyle pas tutmuştur."},{"n":15,"t":"Bundan daha beteri de var: Elbet onlar o gün Rablerinden mahrum kalacaklar;"},{"n":16,"t":"sonra onlar gözleri faltaşı gibi açan bir azaba sokulacaklar;"},{"n":17,"t":"sonra kendilerine denilecek ki: \"işte sizin yalanlamayı adet edindiğiniz hakikat budur\"."},{"n":18,"t":"Kesinlikle evet! İyilerin kaydı da `İlliyyun`da (arşivlenecek);"},{"n":19,"t":"Ve `Illiyyun nedir, bilir misin sen?"},{"n":20,"t":"O (yine) sayısal değerlerle koruma altına alınmış bir kayıttır;"},{"n":21,"t":"onu Allah`a yakın olanlar izleyebilir."},{"n":22,"t":"Şüphe yok ki iyiler tarifsiz nimetler içinde yüzecekler;"},{"n":23,"t":"Ebedi huzur ve saadet makamında (rahatlarına) bakacaklar;"},{"n":24,"t":"yüzlerinde sonsuz mutluluğun tarifsiz parıltısını göreceksin."},{"n":25,"t":"Kişiye özel tarifsiz bir içki ikram edilecek;"},{"n":26,"t":"o, içenin ağzında misk kokusu bırakacak; işte bu nedenle yarışmak isteyenler, artık bu uğurda yarışsınlar!"},{"n":27,"t":"Onun katkı maddesi, (Cennetin) zirvesinden dolacak;"},{"n":28,"t":"Allah`a yakın olanların içtiği tarifsiz bir kaynaktan..."},{"n":29,"t":"Ne var ki günah bataklığına gömülmüş olanlar, bir zamanlar iman edenlere gülerlerdi;"},{"n":30,"t":"ve ne zaman onlarla karşılaşsalar kaş göz ederlerdi;"},{"n":31,"t":"ve kafadarları arasına döndüklerinde ise keyifle (anlatırlardı);"},{"n":32,"t":"ve iman edenleri her gördüklerinde \"Bunlar iyiden sapıtmış\" derlerdi."},{"n":33,"t":"Ne ki onlar, mü`minlerin inancına müfettiş olarak gönderilmiş değiller."},{"n":34,"t":"Fakat bugün iman edenler küfrü hayat tarzı edinenlere gülecekler:"},{"n":35,"t":"Ebedi huzur ve saadet makamında (rahatlarına) bakacaklar."},{"n":36,"t":"Nasıl? Küfrü hayat tarzı edinenler yapa geldiklerinin `sevabına` (!) nail olabilmişler mi bari!?"}],[{"n":1,"t":"Gökyüzü şerha şerha yarıldığında"},{"n":2,"t":"yani Rabbine kulak verdiğinde ve sonuç alındığında,"},{"n":3,"t":"ve yeryüzü uçsuz bucaksız bir düzlük haline getirildiğinde,"},{"n":4,"t":"ve içindeki her şeyi atarak boşaldığında,"},{"n":5,"t":"yani Rabbine kulak verdiğinde ve sonuç alındığında..."},{"n":6,"t":"Sen ey insanoğlu! Evet evet, hayat yolunda son sürat yeldirdikçe (ister istemez) Rabbine doğru yol alan sen, sonunda O`na kavuşacaksın!"},{"n":7,"t":"İşte (o gün) sicili sağ eline verilen kimseye gelince:"},{"n":8,"t":"onun hesabı pek kolay görülecek"},{"n":9,"t":"ve cemaati arasına sevinçli bir şekilde dönecek."},{"n":10,"t":"Ve sicili bozuk çıkan kimseye gelince:"},{"n":11,"t":"artık ısrarla yok olmak için yalvaracak,"},{"n":12,"t":"ne ki çılgın bir ateşi boylayacak;"},{"n":13,"t":"oysa o, (vaktiyle) kendi cemaati arasında pek şen şakrak idi;"},{"n":14,"t":"her halde o (Allah`a) döneceğini asla ummuyordu;"},{"n":15,"t":"evet öyleydi, ama Rabbi onu sürekli gözetliyordu."},{"n":16,"t":"Ötesi yok! İşte şafak vaktini Ben şahit tutuyorum!"},{"n":17,"t":"ve geceyi ve toplayıp kaydettiklerini,"},{"n":18,"t":"ve safha safha dolunay halini alan ayı (şahit tutuyorum ki"},{"n":19,"t":"ey insanlar; mukadder sona doğru) safha safha, adım adım ilerleyeceksiniz."},{"n":20,"t":"Peki, onlara ne oluyor ki hala (Hesap Günü`ne) iman etmiyorlar?"},{"n":21,"t":"Dahası, kendilerine Kur`an okunduğu zaman onu tasdik edip teslim de olmuyorlar."},{"n":22,"t":"Aksine, inkarda direnenler (ilahi vahyi) yalanlamakta ısrar ediyor;"},{"n":23,"t":"ama Allah içlerinde biriktirip gizlediklerini çok iyi biliyor."},{"n":24,"t":"Artık onlara şiddetli bir azabı müjdele;"},{"n":25,"t":"ancak iman edenler ve Allah rızasına uygun davrananlar hariç: Onları kesintisiz bir ödül bekliyor."}],[{"n":1,"t":"Burçlarla dolu gökyüzü şahit olsun,"},{"n":2,"t":"vaad edilen gün şahit olsun,"},{"n":3,"t":"her bir tanık ve sanık şahit olsun (da şu gerçeği ünlesin):"},{"n":4,"t":"Kahrolsun hendek ehli!"},{"n":5,"t":"O ateş (hendekleri), ağzına kadar doldurulup tutuşturulmuştur."},{"n":6,"t":"O zaman onlar ateşin üstüne oturmuşlardır;"},{"n":7,"t":"Dinlerinden döndürmek için acımasızca şuurlu ve kâmil mü’minlere yaptıkları işkence ve zulmü de seyrediyorlardı, yaptıkları işkence ve zulüm sebebiyle kendi aleyhlerine şâhitlik de edecekler."},{"n":8,"t":"O (zalimler) başka bir sebeple değil, sadece yücelikte eşsiz ve hamdin tümüne layık olan Allah`a imanda ısrar ettikleri için onlardan intikam almışlardır."},{"n":9,"t":"O Allah ki, göklerin ve yerin hakimiyeti sadece O`na aittir; üstelik Allah her şeye şahittir."},{"n":10,"t":"Bakın, mü`min erkekler ve mü`min kadınlara işkence yapıp da sonra pişman olmayanlar var ya: elbet onlar derin bir mahrumiyet gayyasını boylayacaklar ve onları harlı ateşin azabı bekleyecektir."},{"n":11,"t":"Şüphesiz iman eden ve Allah`ın razı olacağı davranışlarda bulunanları da, zemininden ırmaklar çağıldayan cennetler bekleyecektir: işte büyük başarı budur."},{"n":12,"t":"Şüphesiz Rabbinin kıskıvrak yakalaması pek çetindir;"},{"n":13,"t":"çünkü O, evet O`dur yoktan var eden ve o yaratmayı sürekli tekrar eden de yine O`dur."},{"n":14,"t":"Ve mutlak bağış sahibi, hep seven ve sınırsızca sevilmeye layık olan O`dur;"},{"n":15,"t":"en şerefli makamın sahibidir;"},{"n":16,"t":"dilediği her şeyi yapabilendir."},{"n":17,"t":"Malum orduların olayından haberin var mı?"},{"n":18,"t":"Firavun`un ve Semud kavminin (ordularından)?"},{"n":19,"t":"Maalesef inkarı önyargı haline getirenler yalanlamakta ısrar etmişlerdir;"},{"n":20,"t":"Allah ise onları hiç hesaba katmadıkları yerden çepeçevre kuşatandır."},{"n":21,"t":"Hepsinden öte bu şanlı şerefli bir hitaptır;"},{"n":22,"t":"tarifsiz bir hafızada koruma altına alınmıştır."}],[{"n":1,"t":"Sema ve gece gelen konuk şahit olsun."},{"n":2,"t":"Karanlıkta yol tepenle ilgili bizden başka seni bilgilendiren mi var? Karanlıkta gümbür gümbür yol teperek, kapıları çalan, sesini, tebliğini duyuran, varlığını benimseten ne azimli, ne kararlı, ne cesur birisi."},{"n":3,"t":"O (inkarcı aklın zifiri karanlığını) delen bir yıldızdır;"},{"n":4,"t":"Zaten hiçbir insan yoktur ki (ilahi) gözetim ve koruma altında olmasın."},{"n":5,"t":"İnsanoğlu neden yaratıldığına bir baksın;"},{"n":6,"t":"o, (üreme organlarından) fışkıran hayat tohumlarını içeren basit bir sıvıdan yaratıldı;"},{"n":7,"t":"omurga ile kaburga kemikleri arasındaki bölgeden çıkan…"},{"n":8,"t":"Elbet (insanı yoktan var eden) Allah, onu tekrar hayata döndürmeye kadirdir."},{"n":9,"t":"O gün, sırlar (bile) sınanır;"},{"n":10,"t":"dahası kişi ne (içerden) bir güç, ne de (dışardan) bir yardım alabilir."},{"n":11,"t":"(Hayat) çevrimine sahne olan gök şahit olsun;"},{"n":12,"t":"ve (bitkilerle) yarılan yer şahit olsun:"},{"n":13,"t":"elbet bu (vahiy) hakkı batıldan ayıran bir sözdür,"},{"n":14,"t":"asla anlamsız bir lakırdı değildir."},{"n":15,"t":"Ne var ki onlar tuzak üstüne tuzak kuruyorlar;"},{"n":16,"t":"ve Ben de onların tuzaklarını bozuyorum."},{"n":17,"t":"Şu halde kafirlere süre ver, sadece kısa bir süre…"}],[{"n":1,"t":"(Ey muhatab) yücelikte eşsiz olan Rabbin adına/adıyla hareket et!"},{"n":2,"t":"O ki, tüm mahlukatı yarattı ve yaratılış amacını gerçekleştirecek bir donanım verdi."},{"n":3,"t":"O ki, her şeye yaratılıştan bir ölçü ve amaç takdir etti, sonra (o ölçüye uyarak amacına ulaşacak) istikamete yöneltti."},{"n":4,"t":"O ki, tüm bitki örtüsünü çıkardı."},{"n":5,"t":"sonra onu kapkara-kupkuru bir hale soktu."},{"n":6,"t":"(Ey muhatab) Biz sana okutacağız ve sen asla unutmayacaksın;"},{"n":7,"t":"Allah`ın (unutmanı) diledikleri hariç; çünkü O açığa çıkanı da bilir gizleneni de;"},{"n":8,"t":"böylece zaten kolay olan (vahyi anlamayı) sana daha da kolaylaştırmış olacağız."},{"n":9,"t":"Şu halde sen, -öğüt (sadece bazılarına) fayda verse de- hep (fıtratlara nakşolan Allah`ı) hatırlat,"},{"n":10,"t":"Nasıl olsa Allah`ın sevgisini kaybetmekten korkanlar öğüt alacaklardır;"},{"n":11,"t":"bedbaht olanlar ise öğüttün kaçacaktır;"},{"n":12,"t":"bu gibiler en korkunç ateşi boylayacaktır;"},{"n":13,"t":"sonra orada ne ölebilecek, ne yaşayabilecektir."},{"n":14,"t":"(Manevi kirlerden) arınma gayreti içinde olanlar kurtuluşa erecek;"},{"n":15,"t":"Rabbinin adını hatırda tutan da, salata duran da (kurtuluşa erecek)."},{"n":16,"t":"Maalesef siz (ey insanlar), bu yakın ve aşağı hayatı tercih ediyorsunuz;"},{"n":17,"t":"oysa ki öteki (hayat) en hayırlı ve daha kalıcıdır."},{"n":18,"t":"Elbet bütün bu hakikatler önceki vahiylerde yer almıştır;"},{"n":19,"t":"(mesela) İbrahim ve Musa`ya indirilen vahiylerde."}],[{"n":1,"t":"Kasvet gibi sarıp sarmalayan olayın haberi sana ulaştı mı?"},{"n":2,"t":"Bazıları vardır o gün; zillet içinde yıkılmıştır;"},{"n":3,"t":"işi bitmiş, eli kolu dökülmüştür;"},{"n":4,"t":"tarifi imkansız kızgın bir ateşi boylarlar,"},{"n":5,"t":"zehir gibi bir (umutsuzluğun) pınarından sulanırlar;"},{"n":6,"t":"onlara hiçbir yiyecek yoktur, ancak onursuzların yiyeceği vardır;"},{"n":7,"t":"ama ne besleyicidir ne doyurucudur."},{"n":8,"t":"Bazıları da vardır o gün; nimete gark olmuştur;"},{"n":9,"t":"sonuçta gayretinin meyvesinden hoşnut ve razı olmuştur;"},{"n":10,"t":"kendini tarifsiz bir Cennet`te, yüce bir makamda bulmuştur."},{"n":11,"t":"Orada boş bir lakırdı işitmeyecek,"},{"n":12,"t":"orada tarifsiz bir (mutluluk) pınarı hep çağıldayacak,"},{"n":13,"t":"orada sevinç ve huzur kaynağı yüce makamlar bulunacak;"},{"n":14,"t":"her an içime hazır dolu dolu tarifsiz kupalar,"},{"n":15,"t":"yan yana dizilmiş minderler"},{"n":16,"t":"ve serilmiş halılar…"},{"n":17,"t":"Peki, (yeniden dirilişi inkar edenler) yağmur yüklü bulutlara bakmazlar mı nasıl yaratılmış?"},{"n":18,"t":"Ve gök kubbeye (bakmazlar mı), nasıl yükseltilmiş?"},{"n":19,"t":"Ve dağlara (bakmazlar mı), nasıl dikilmiş?"},{"n":20,"t":"Ve yeryüzüne (bakmazlar mı), nasıl yayılmış?"},{"n":21,"t":"İmdi sen (ey peygamber) hatırlat! Çünkü sen sadece bir hatırlatıcısın;"},{"n":22,"t":"onlara inanç dayatan bir zorba değilsin!"},{"n":23,"t":"İlla ki yüz çeviren ve inkar eden olacaktır."},{"n":24,"t":"Allah, en büyük mahrumiyeti işte böylesine yaşatacaktır."},{"n":25,"t":"Bakın: Bizedir onların nihai dönüşü."},{"n":26,"t":"Yine bakın: bize düşer onları hesaba çekmek."}],[{"n":1,"t":"(Karanlığı) yarıp çıkan sabah vakti şahit olsun!"},{"n":2,"t":"O tarifsiz on gece şahit olsun!"},{"n":3,"t":"Çift ve tek şahit olsun"},{"n":4,"t":"Sabaha yürüyen gece şahit olsun!"},{"n":5,"t":"Ne yani, şunların hepsinde sahibini koruyan oturaklı bir aklı olanlar için, sağlam bir şahitlik yok mudur?"},{"n":6,"t":"Görmedin mi Rabbin ne yaptı Ad kavmine,"},{"n":7,"t":"sütun (gibi bina)lar sahibi İrem`e"},{"n":8,"t":"ki, o (günün) dünyasında bir benzeri daha inşa edilmemişti?"},{"n":9,"t":"Yine kayaları vadiler oluşturma amacıyla kesip oyan Semud`a?"},{"n":10,"t":"Ve (pirametlerle dünyaya) kazık çakan Firavun`a?"},{"n":11,"t":"Onların hepsi de kendi ülkelerinde haddi aşmış kimselerdi;"},{"n":12,"t":"derken oralarda ahlaki çürüme ve toplumsal yozlaşmayı körüklediler;"},{"n":13,"t":"bu yüzden Rabbin onların üzerine envai çeşit azab kamçısı yağdırdı."},{"n":14,"t":"Şu kesin ki Rabbin her zaman ve mekanda herkesi gözetleyicidir."},{"n":15,"t":"Ve insana gelince... Ne zaman Rabbi onu (varlıkla) sınayıp ona ikram edecek ve nimetlere gark edecek olsa, hemen (Allah`ın kendisini desteklediğini düşünerek) \"Rabbim bana ikram etti\" der;"},{"n":16,"t":"Ne zaman da Rabbi onu (darlıkla) sınayıp onun geçim alanını sınırlandıracak olsa, bu kez de \"Rabbim beni zelil etti\" der."},{"n":17,"t":"Asla! Bilakis siz yetime izzet ikram göstermiyorsunuz,"},{"n":18,"t":"yoksulu doyurmaya birbirinizi teşvik etmiyorsunuz,"},{"n":19,"t":"Emeksiz kazancı haram-helal demeden açgözlülükle boğazınıza geçiriyorsunuz,"},{"n":20,"t":"dahası ölçüsüz bir sevgiyle malı seviyorsunuz."},{"n":21,"t":"Yoo, öyle yapmayın! Yeryüzü art arda sürekli bir sarsılışla sarsılıp dümdüz olduğu zaman,"},{"n":22,"t":"Rabbinin (fermanı) da gelmiş ve melekler saf saf dizilmiş olacak;"},{"n":23,"t":"o gün Cehennem de ortaya getirilmiş olacak; o gün (sınavı kaybetmiş) insan (gerçeği) itiraf edecek; ama bu itirafın hiçbir yararı olmayacak."},{"n":24,"t":"O diyecek ki: \"Ah n`olaydım, keşke bu hayatım için hazırlık yapmış olaydım!\""},{"n":25,"t":"İşte o gün hiçbir kimse O`nun tattırdığı can yakıcı mahrumiyeti tattıramaz;"},{"n":26,"t":"ve hiçbir kimse O`nun zaptettiği gibi zaptedemez."},{"n":27,"t":"(imdi) ey mutmain kişi:"},{"n":28,"t":"Rabbine, O`ndan memnun olmuş ve O`nu razı etmiş olarak dön!"},{"n":29,"t":"Bunu (başarman) halinde gir (sadık) kullarımın arasına,"},{"n":30,"t":"ve gir cennetime!"}],[{"n":1,"t":"Ötesi yok, işte Ben yemin ediyorum bu beldeye,"},{"n":2,"t":"-ki sen de bu beldenin (şerefli) bir sakinisin-"},{"n":3,"t":"ve babaya ve oğula:"},{"n":4,"t":"Hakikaten Biz insanoğlunu farklı meşakkatlere dayanıklı yarattık."},{"n":5,"t":"Ne yani, şimdi insan kimsenin kendisine güç yetiremeyeceğinimi sanıyor?"},{"n":6,"t":"(Dahası) “Ben (bu konuma gelmek için) kucak dolusu servet harcadım” mı diyor?"},{"n":7,"t":"Kendisini kimsenin görmediğini mi sanıyor?"},{"n":8,"t":"Ona iki göz vermedik mi?"},{"n":9,"t":"Dahası bir dil ve bir çift dudak?"},{"n":10,"t":"Ve ona (iyilik ve kötülüğün) açık seçik iki yolunu da göstermedik mi?"},{"n":11,"t":"Fakat o, (ucunda cennet olan) sarp yokuşu tırmanmak için hiçbir bedel ödemedi."},{"n":12,"t":"Bilir misin nedir o sarp yokuş?"},{"n":13,"t":"Bir kişiyi daha zincirlerinden kurtarmaktır;"},{"n":14,"t":"veya açlık gününde (muhtaçları) doyurmaktır;"},{"n":15,"t":"(mesela) yakını olan bir yetimi,"},{"n":16,"t":"ya da evsiz barksız, yurtsuz yuvasız bir düşkünü..."},{"n":17,"t":"Daha sonra, iman edenlerden olmak ve birbirine hakkı ve merhameti tavsiye etmektir."},{"n":18,"t":"İşte böyleleridir vicdan sahipleri;"},{"n":19,"t":"inkarda ısrar edenler ise vicdansız olanlardır;"},{"n":20,"t":"tarifsiz bir ateş onların üzerine güdümlenmiştir."}],[{"n":1,"t":"Güneş ve onun gözalıcı ışığı şahit olsun;"},{"n":2,"t":"güneşi izleyen ay şahit olsun!"},{"n":3,"t":"Onun ışığını ortaya çıkarıp gösteren gündüz şahit olsun;"},{"n":4,"t":"yine o ışığı gizleyecek gece şahit olsun!"},{"n":5,"t":"Gökyüzü ve onu ayakta tutan (nizam) şahit olsun;"},{"n":6,"t":"yeryüzü ve onu çepeçevre kuşatan canlı örtü şahit olsun!"},{"n":7,"t":"İnsan benliği ve onun yaratılış amacına uygun biçimlenişi şahit olsun;"},{"n":8,"t":"ve nihayet insan benliğine iyiyi ve kötüyü tanıyıp sorumsuz ve sorumlu davranma yeteneğini yerleştiren (şahit olsun) ki:"},{"n":9,"t":"Kim kendini geliştirip arındırırsa, o kesinlikle ebedi mutluluğa ulaşacaktır;"},{"n":10,"t":"kim de kendini geliştirmeyip (içindeki iyilik tohumunu) çürütürse, o kesinlikle kaybedecektir."},{"n":11,"t":"Semûd toplumu, azgınlığı nedeniyle yalanladı."},{"n":12,"t":"hani kavmin en azgını kışkırtmayla zıvanadan çıktığında,"},{"n":13,"t":"Allah`ın elçisi (Salih) şöyle demişti: \"(Bu) Allah`ın devesidir; şu halde bırakın da (Allah`ın) suyunu içsin!\""},{"n":14,"t":"Derken elçiyi dinlemediler onu işkenceyle boğazladılar. Sonunda Rableri, bu günahları yüzünden burunlarını sürte sürte onları yerle bir etti;"},{"n":15,"t":"oysa ki o (kavim) kendi akıbetinden zerrece endişe etmezdi."}],[{"n":1,"t":"Kuşatıp örten gece şahit olsun."},{"n":2,"t":"(Gecenin kuşatmasını) yarıp ortaya çıkan gündüz şahit olsun!"},{"n":3,"t":"Erkek ve dişinin yaratılışı şahit olsun"},{"n":4,"t":"ki ey (insanlık); sizin çabanız, (nedenleri ve sonuçları açısından) elbet farklı farklıdır."},{"n":5,"t":"Sözgelimi; kim (Allah için) karşılıksız verir ve Allah`a muhtaç olduğunun bilinciyle hareket ederse;"},{"n":6,"t":"ve daha güzeliyle (ödüllendirileceğine) inanırsa;"},{"n":7,"t":"işte ona, rahatlık ve mutluluğun zirvesine götüren yolu kolaylaştırırız."},{"n":8,"t":"Sözgelimi; kim de cimrilik yapar ve kendi kendine yettiğini zanneder,"},{"n":9,"t":"En Güzel`i (vahyini) yalanlarsa;"},{"n":10,"t":"işte ona da, zorluk ve felaketin en dibine giden yolu kolaylaştırırız;"},{"n":11,"t":"öyle ki, o baş aşağı (cehenneme) yuvarlanıp helak olacağı zaman, (Allah için paylaşmadığı) malı kendisini asla kurtaramaz."},{"n":12,"t":"Elbet doğru yolu göstermek sadece bizim işimizdir;"},{"n":13,"t":"ama işin gerçeği öteki hayat da, bu hayat da Bizim mülkiyetimizdedir."},{"n":14,"t":"İşte sizi çılgınca kışkırtılmış bir ateşe karşı uyarmış bulunuyorum:"},{"n":15,"t":"oraya sadece sorumsuzluğun zirvesinde olan bir azgın girer;"},{"n":16,"t":"o ki, (vahyi) yalanladı ve (gerçeğe) sırt döndü."},{"n":17,"t":"Ama yüce ve yüksek bir sorumluluk bilinciyle hareket eden kimse, o (ateşten) uzak tutulacak;"},{"n":18,"t":"o ki, malını gönülden verir ve arınıp gelişir;"},{"n":19,"t":"(Bu yaptığı) herhangi birinden gördüğü bir hayra karşılık değildir;"},{"n":20,"t":"sadece Yüce Rabbinin rızasını kazanma iştiyaki iledir."},{"n":21,"t":"İşte böyle biri, kesinlikle, zamanı gelince (gördüğü karşılıktan) fazlasıyla memnun olacaktır."}],[{"n":1,"t":"Sabahın berrak aydınlığını temsil eden kuşluk vakti şahit olsun,"},{"n":2,"t":"karanlığın dibini bulup sakinleşen gece şahit olsun"},{"n":3,"t":"ki; Rabbin seni ne terk etti, ne de darıldı."},{"n":4,"t":"Kaldı ki, sonrası senin için öncesinden daha hayırlı olacaktır;"},{"n":5,"t":"ve zamanı gelince Rabbin sana bahşedecek, sen de (bundan) hoşnut ve memnun olacaksın."},{"n":6,"t":"O seni bir yetim olarak bulup sığınak olmadı mı?"},{"n":7,"t":"Yine O seni yolunu kaybetmiş bulup doğru yola yöneltmişti."},{"n":8,"t":"Seni muhtaç bir halde bulup, muhannete muhtaç olmaktan ve mala tamahtan müstağni kılmıştı."},{"n":9,"t":"Dolayısıyla, asla yetime otoriter davranma (surat asma)"},{"n":10,"t":"Her durumda yardım isteyeni azarlama!"},{"n":11,"t":"ve her zaman Rabbinin (sonsuz) nimetini dilinden düşürme!"}],[{"n":1,"t":"Göğsünü açıp seni ferahlatmadık mı?"},{"n":2,"t":"Ve yükünü sırtından kaldırmadık mı?"},{"n":3,"t":"Ki o yük belini iki büklüm etmişti!"},{"n":4,"t":"Ve senin şanını yüceltmedik mi?"},{"n":5,"t":"Sözün özü: elbet her zorlukla beraber tarifsiz bir kolaylık vardır;"},{"n":6,"t":"evet, her zorlukla beraber tarife sığmaz bir kolaylık vardır."},{"n":7,"t":"Şu halde (zorluktan) kurtulduğunda (kolaylıktan) nasibini gözet! (Zorluğu aşınca tebliğe devam et)"},{"n":8,"t":"Ve (yüzünü) yalnız Rabbine dön; artık hep (O`na) meylet!"}],[{"n":1,"t":"İncir ağacı ve zeytin (diyarı) şahittir!"},{"n":2,"t":"Ulu Sina Dağı şahittir!"},{"n":3,"t":"Bu güvenli belde şahittir:"},{"n":4,"t":"Doğrusu Biz insanı en güzel kıvamda yaratmış,"},{"n":5,"t":"sonra onu başlangıç noktasının en dibine döndürmüşüzdür."},{"n":6,"t":"Ancak (tekamül yolculuğunda), imanda sebat eden ve o imanla uyumlu hareket edenleri kesintisiz bir ödül beklemektedir."},{"n":7,"t":"Öyleyse (ey insan): bütün bu gerçeklerden sonra sana Hesap Günü`nü yalanlatan nedir?"},{"n":8,"t":"Şimdi (söyle ey insan): \"Allah en iyi hükmeden değil de nedir?"}],[{"n":1,"t":"Oku yaratan Rabbin adına;"},{"n":2,"t":"O insanı sevgi ve alakadan yarattı."},{"n":3,"t":"Oku! Zira Rabbin sonsuz kerem sahibidir;"},{"n":4,"t":"O insana (bilgiyi) kalemle (kaydetmeyi) öğretti."},{"n":5,"t":"O insana bilmediklerini öğretti."},{"n":6,"t":"Evet, evet; insan mutlaka azar,"},{"n":7,"t":"kendi kendine yettiğini sandığında!"},{"n":8,"t":"Ne ki insanın Rabbine dönüşü muhakkaktır."},{"n":9,"t":"Ama (ey muhatap) Baksana şu engel olmaya kalkışana,"},{"n":10,"t":"ibadete kalkan bir kula!"},{"n":11,"t":"(Ve sen ey ibadete engel olan) Hiç o hidayet üzere midir diye geldi mi aklına?"},{"n":12,"t":"Yahut da, çağırmakta mıdır diye sorumluluğa?"},{"n":13,"t":"Düşündün mü hiç: eğer o hakikati yalanlasa ve sırt dönmüş olsa Allah`a,"},{"n":14,"t":"kendisi bilmez mi ki, Allah görür mutlaka."},{"n":15,"t":"Yoo! Eğer o buna bir son vermediyse, elbet perçeminden yakalayacağız;"},{"n":16,"t":"o pek sahtekar, bir o kadar da günahkar perçeminden;"},{"n":17,"t":"haydi o kendi örgütünü çağırsın,"},{"n":18,"t":"biz de zebanileri çağıracağız."},{"n":19,"t":"Hayır! O (azgın) insana uyma; imdi (Rabbine) secde et ve yaklaşmaya gayret et."}],[{"n":1,"t":"Elbet onu kadir-kıymet gecesinde Biz indirmeye (başlamışızdır)."},{"n":2,"t":"Bilir misin o kadir-kıymet gecesinin mahiyeti nedir?"},{"n":3,"t":"O kadir-kıymet gecesi bin aydan daha hayırlıdır."},{"n":4,"t":"Melekler, vahiyle beraber o gece inerler de inerler, Rablerinin izniyle, hayatın her alanına dair"},{"n":5,"t":"tarifsiz bir mutluluğun (formüllerini getirirler); bu durum, fecr doğuncaya kadar sürer."}],[{"n":1,"t":"İnkarda ısrar edenler, -ister kitap ehline isterse şirki hayat tarzı edinenlere mensup olsunlar- kendilerine hakikatin açık delili gelinceye kadar dışlanacak değillerdi!"},{"n":2,"t":"(O delil); tüm şaibelerden arınmış sayfaları Allah`tan kendilerine ileten bir elçidir;"},{"n":3,"t":"(o vahiylerin) içinden (önceki) kitapların ölmez yitmez (değerleri) bulunur."},{"n":4,"t":"Ama önceki vahiylerin mensupları durdular durdular da, kendilerine hakikatin apaçık belgeleri geldikten sonra ayrılığa düştüler."},{"n":5,"t":"Oysa kendileri yalnızca Allah`a kulluk etmek, din koyma yetkisinin sadece O`na mahsus olduğuna iman edip batıl olan her şeyden uzak durmak, ibadeti hakkıyla eda etmek, arınmak ve artmak için verilmesi gerekeni vermekle emrolunmuşlardı: İşte insanlığın ebedi değerler sistemi budur."},{"n":6,"t":"Elbette inkarda ısrar edenler, -ister kitap ehline isterse şirki hayat tarzı haline getirenlere mensup olsunlar- içinde ebedi kalmak üzere Cehennem ateşinin bağrına düşecekler: Onlar bütün yaratıkların en şerlileridir."},{"n":7,"t":"Şüphesiz iman eden ve imanına uygun davrananlar da var; işte onlar bütün yaratıkların en hayırlılarıdır."},{"n":8,"t":"Rableri katında onların ödülleri, zemininden ırmakların çağıldadığı ölümsüz güzelliğin üretildiği tarifsiz cennetlerdir; orada sonsuza kadar kalacaklardır: Allah onlardan razı olmuş, onlar da Allah`tan memnun olmuştur. İşte bütün bunlar, Rablerinin sevgisini yitirmekten korkanlar içindir."}],[{"n":1,"t":"Yeryüzü (aniden) korkunç bir depremle sarsıldığı zaman,"},{"n":2,"t":"Tüm maddi-manevi ağırlıklarını çıkarttığı zaman,"},{"n":3,"t":"İnsan der ki: Ne oluyor buna!"},{"n":4,"t":"İşte o dehşet günü, yeryüzü dile gelip (şahit olduklarını) bir bir haber verecek;"},{"n":5,"t":"zira senin Rabbin, ona (da emrini) vahyetmiştir."},{"n":6,"t":"İşte o dehşet günü bütün insanlar, yaptıkları kendilerine gösterilmek üzere darmadağın ve derbeder bir halde toplanacaklar."},{"n":7,"t":"Kim zerre kadar iyilik yaparsa onu (ilahi kayıtta) görecektir."},{"n":8,"t":"kim de zerre kadar kötülük yaparsa, onu (ilahi kayıtta) görecektir."}],[{"n":1,"t":"Yazıklar olsun (vahye) dinmez bir hınçla saldıranlara,"},{"n":2,"t":"ve (içindeki) öfke ateşiyle etrafı tutuşturanlara."},{"n":3,"t":"ve sabah(lara)a kadar kıskançlıktan kıvrananlara,"},{"n":4,"t":"sonuçta tozu dumana katarak ortalığı bulandıranlara:"},{"n":5,"t":"nihayet bu düşmanlıkla toplumun ortasına dalanlara…"},{"n":6,"t":"ki gerçekten de (bu) insan tipi Rabbine karşı çok nankördür;"},{"n":7,"t":"üstelik insanın kendisi de buna şahittir;"},{"n":8,"t":"zira o servete pek tutkundur."},{"n":9,"t":"O bilmez mi ki; kabirlerde bulunan herkes diriltilip ortaya çıkacağı zaman,"},{"n":10,"t":"ve göğüslerde saklı her şey ortaya serileceği (zaman):"},{"n":11,"t":"Elbet Rableri, o gün onları (bekleyen akıbetin) iç yüzünden bütünüyle haberdardır!"}],[{"n":1,"t":"Ah o korkunç patlama!"},{"n":2,"t":"(Bir bilsen ey muhatap) o ne dehşet bir patlama!"},{"n":3,"t":"Sahi, sen nereden bileceksin korkunç patlamanın ne olduğunu?"},{"n":4,"t":"O gün insanlar, sereserpe yerlere saçılmış (kavruk) pervane sineklerini andıracak;"},{"n":5,"t":"dağlar ise, dört bir yana dağılmış pamukları çağrıştıracak."},{"n":6,"t":"İyilikleri ağır gelen kimseye gelince:"},{"n":7,"t":"o kendisini, hoşnut olduğu tarifsiz güzellikte bir hayatın içinde bulacak;"},{"n":8,"t":"iyilikleri hafif gelen kimseye gelince:"},{"n":9,"t":"o da dipsiz bir uçurumun bağrına yuvarlanacak."},{"n":10,"t":"Sahi, sen nereden bileceksin o nedir?"},{"n":11,"t":"O, tarifsiz yakan özge bir ateştir."}],[{"n":1,"t":"Çoğaltma tutkusu sizi oyalayıp durdu,"},{"n":2,"t":"ta ki siz mezarlıklara varıncaya dek."},{"n":3,"t":"Ama hayır! Vakti gelince, gerçeği (burada) öğreneceksiniz;"},{"n":4,"t":"o da olmadı, o zaman vakti gelince gerçeği (orada) öğreneceksiniz."},{"n":5,"t":"Yoo, eğer bu (tutkunun neye mal olduğunu) tam kavramış olsaydınız,"},{"n":6,"t":"elbet (dünyayı) cehenneme (çevirdiğinizi) de görürdünüz;"},{"n":7,"t":"(Tutun ki burada göremediniz), ama daha sonra (ahirette) onu zaten gözlerinizle göreceksiniz;"},{"n":8,"t":"nihayet o gün, ebedi nimetlerden vaz geçip (geçici nimetlere yönelmenizden) dolayı hesaba çekileceksiniz."}],[{"n":1,"t":"Asr şahit olsun."},{"n":2,"t":"Elbet insanoğlu tarifsiz bir kayıptadır;"},{"n":3,"t":"ancak, Allah`a inanıp güvenenler, erdemli ve sorumlu davrananlar; yani birbirlerine hakkı tavsiye edenler ve sabrı tavsiye edenler bundan müstesnadır."}],[{"n":1,"t":"Gizli-açık, arkadan-önden sürekli iftira atıp kara çalan, çekiştirip ayıp kusur arayan herkes kendine yazık etmiştir!"},{"n":2,"t":"İşte, malı yığan ve onu birikim sayan bu tiptir;"},{"n":3,"t":"O, malının kendisini ölümsüz yapacağını sanmaktadır."},{"n":4,"t":"Heyhat! Hiç kuşkusuz, o hutame`ye atılacaktır."},{"n":5,"t":"Sahi sen nereden bileceksin kırıp geçiren ateş nedir?"},{"n":6,"t":"O Allah`ın tutuşturulmuş ateşidir."},{"n":7,"t":"O öyle bir ateştir ki, bütün bir iç dünyalarını kaplayarak yükselir."},{"n":8,"t":"İşte o ateş onların üzerine güdümlenmiştir;"},{"n":9,"t":"Uzayıp giden parmaklıklar arasında (kendi zindanlarına mahkum olacaklardır)."}],[{"n":1,"t":"Gözünde canlandırabilir misin Rabbinin Fil Ordusu`na nasıl muamele ettiğini?"},{"n":2,"t":"Başlarına geçirmedi mi onların ince tasarlanmış haince hilesini?"},{"n":3,"t":"Onların üzerine katar katar bilinmeyen nitelikte uçan taşıyıcı varlıklar saldı;"},{"n":4,"t":"Onlara taş kesilmiş balçık türü tanımlanamayan (şeyler) atıyorlardı."},{"n":5,"t":"Derken (Rabbin) onları, yenil(erek delik deşik edil)miş yapraklara benzetti."}],[{"n":1,"t":"Bari Kureyş`in birlik ve dirliği hakkı için,"},{"n":2,"t":"Onların yaz ve kış yaptıkları ticari sefer güvenliği hakkı için:"},{"n":3,"t":"Kulluğu şu Beyt`in Rabbine tahsis etsinler!"},{"n":4,"t":"Ki O, onları açlığa rağmen doyurmuş, her tür tehlike ve tehdide rağmen güvende kılmıştır."}],[{"n":1,"t":"Allah`a karşı borçluluk sorumluluğunu tümden inkar eden birini tasavvur edebilir misin!"},{"n":2,"t":"İşte böyle biridir yetimi itip kakan,"},{"n":3,"t":"Ve yoksulu doyurmaya gayret etmeyen."},{"n":4,"t":"İşbu yüzden, olmaz olsun (böyle) ibadet edenler!"},{"n":5,"t":"Bu gibiler, ibadetin hakiki amacından gafil görünmektedirler."},{"n":6,"t":"Bunlar öyle kimseler ki, (ibadeti) gösteriye dönüştürürler,"},{"n":7,"t":"Ama en küçük yardımı bile esirgerler."}],[{"n":1,"t":"Gerçek şu ki, Biziz sana her hayrı cömertçe bahşeden:"},{"n":2,"t":"O halde namazı da, kurbanı da yalnız Rabbine tahsis et!"},{"n":3,"t":"Bir başka gerçek de şu ki; (hayırdan) tamamen kesilip kopmuştur senden nefret eden."}],[{"n":1,"t":"Deki: Siz, ey kafirler!"},{"n":2,"t":"Asla kul olacak değilim sizin kul olduğunuz şeylere,"},{"n":3,"t":"Siz de benim kul olduğuma kulluk edecek değilsiniz!"},{"n":4,"t":"Zaten ben asla kulluk etmedim sizin geçmişte kul olduklarınıza,"},{"n":5,"t":"Siz de benim kul olduğuma kulluk etmezsiniz."},{"n":6,"t":"Sizin dininiz size, benim dinim bana!"}],[{"n":1,"t":"Allah`ın zafer garantili yardımı ve Fetih geldiğinde,"},{"n":2,"t":"Ve insanların kitleler halinde Allah`ın dinine gireceklerini gördüğünde, (senin görevin de tamamlandı demektir):"},{"n":3,"t":"Artık durma, tesbih et Rabbini hamd ile birlikte ve O`ndan mağfiret dile; zira O`dur tüm içten tevbeleri kabul eden!"}],[{"n":1,"t":"Kahrolsun Ebu Leheb`in çifte gücü, zaten kendisi de kahroldu-kahrolacak!"},{"n":2,"t":"Malı da kazancı da ona hiçbir yarar sağlamayacak!"},{"n":3,"t":"Zamanı gelince tarifsiz bir alevli ateşe (yakıt) olacak!"},{"n":4,"t":"Karısı da (onun ateşine) odun hamallığı yapacak,"},{"n":5,"t":"gerdanında (takı yerine sanki) çelikten bir halat (bulunacak)."}],[{"n":1,"t":"(Ey muhatab!) De ki: O Allah`tır; eşsiz-benzersiz bir tek`tir."},{"n":2,"t":"Allah Samed`dir."},{"n":3,"t":"O doğurtmamıştır ve doğurulmamıştır."},{"n":4,"t":"Ve hiçbir şey O`na asla denk ve benzer olmamıştır."}],[{"n":1,"t":"(Ey muhatab!) de ki: \"sığınırım ben (yokluk gecesini) yararak varlığı çıkaran sabahın Rabbine:"},{"n":2,"t":"O`nun yarattığı her şeyin şerrinden!"},{"n":3,"t":"Ve (aklı-iradeyi) bastırdığı zaman zehirli-zifiri bir (cehalet) karanlığının şerrinden!"},{"n":4,"t":"Ve düğümlere üfleyenin şerrinden!"},{"n":5,"t":"Ve haset ettiğinde hasetçinin şerrinden!"}],[{"n":1,"t":"(Ey muhatab) De ki: \"sığınırım ben Rabbine insanlığın;"},{"n":2,"t":"Sahibine insanlığın;"},{"n":3,"t":"İlahına insanlığın:"},{"n":4,"t":"Sinsi ve sinik vesvese kaynağının şerrinden;"},{"n":5,"t":"O ki; sürekli kalplerine fısıldıyor insanların;"},{"n":6,"t":"İster görünmeyen-bilinmeyen, ister görünen-bilinen türden."}]];
